pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly useless.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny unusable sliver
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 30 {
            score += 8.0;
        } else {
            score -= 5.0; // large residual still reusable
        }
    } else {
        // Perfect fit is the best possible outcome.
        score -= 200.0;
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 30.0 * tightness;

    // Open-bin pressure: penalize accumulating many open bins mildly,
    // but reward spreading load when few bins are open.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 120.0; // chains a perfect fit
            } else if gap < 10 {
                score -= 20.0;
            } else {
                score -= 8.0;
            }
        } else {
            // Post residual too small for next item: penalize proportionally.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (fill fuller bins first).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: only attractive when nothing fits well
    // or open bins are very fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { mean_residual / open_bins_count as f64 } else { 0.0 };
        if fitting_bins_count == 0 || fragmentation < 15.0 {
            score -= 50.0; // open a fresh bin
        } else {
            score += 40.0; // prefer existing bins when they're reasonably empty
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space zone: residual too small for the smallest possible item (1).
    // Any post_residual > 0 that cannot fit the NEXT item is likely wasted.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize unusable gaps; worse when the gap is tiny relative to need.
        let gap_waste = (next_item_size - post_residual) as f64;
        score += 2.0 * gap_waste + 5.0;
        // Extra penalty if NO other bin could take the next item either.
        if fitting_bins_count == 1 {
            score += 10.0;
        }
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 3.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing bins are crowded
    // or no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        // Base cost of opening a new bin, offset by open-bin pressure.
        score += 30.0 - 1.5 * pressure;
        // If item is large, a fresh bin is fine; if small, prefer squeezing in.
        score -= 0.1 * item_size as f64;
        // If this is the only fitting option anyway, neutralize the penalty.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // Mild preference to place into bins with lower mean residual
    // (consolidate fullness across bins).
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    // Late in the stream: be slightly more conservative about new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small dead-space penalty (non-linear): residuals below 10 are nearly unusable
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.15 * next_item_size as f64;
    }
    // Penalize near-miss residuals that block the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Discourage spreading across many bins when mean residual is low (bins nearly full)
    score += 0.3 * mean_residual;

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins have poor fit or the item is large relative to residuals
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_aversion = (item_size as f64 / bin_capacity as f64).powf(2.0);
        // penalize new bin mildly, less so late in stream or for large items
        score += 60.0 - 40.0 * progress - 30.0 * waste_aversion;
        // opening a bin when many are open and residuals are tight is fine
        score -= 5.0 * open_bins_count as f64 * (1.0 - mean_residual / bin_capacity as f64);
    }

    // Prefer tighter bins (small residual before placement) slightly
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
