        score += 40.0 * (10.0 - dead); // tiny gap => very bad
    } else if dead < 20.0 {
        score += 8.0 * (20.0 - dead);
    }

    // Reward tight fits (small post_residual relative to item).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item can't use the leftover gap: penalize proportional to gap size if gap is awkward
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.15 * post_residual as f64;
        }
    }

    // Open-bin pressure: discourage spreading across too many bins.
    score += 1.2 * open_bins_count as f64;

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive if current bins would leave bad dead space
    // or no bin fits well. Fresh empty bin keeps full flexibility.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: new bin is mandatory
        } else if post_residual < 10.0 || fit_ratio > 0.9 {
            score += 55.0; // existing bins give a great fit; don't open new bin
        } else {
            // mild preference for new bin when fits are mediocre
            score -= 5.0 + 0.1 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste, but residuals that can't fit the NEXT item are also risky.
    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            // Dead space relative to the lookahead item: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
        // Very small unusable gaps (below the global minimum item size 1 => none,
        // but gaps < 10 in the nominal regime are near-waste).
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 3.0;
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (2.0 + progress * 3.0);

    // Penalize bins whose residual is far from the mean (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e. when the current bin's fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.9;
        // If this bin is a last resort, opening fresh is fine.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // Early in the stream, opening bins is cheaper.
        score -= (1.0 - progress) * 20.0;
        // If the item would leave a bad gap in existing bins, prefer a new bin.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

