    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable sliver
        } else if post_residual < 20 {
            score += 35.0; // only fits tiny items
        } else if post_residual < 30 {
            score += 15.0;
        }
    } else {
        score -= 100.0; // perfect fit: reward strongly
    }

    // Reward bins whose post_residual still fits the lookahead item (k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.15 * next_item_size as f64;
        } else {
            score += 8.0; // creates a gap the next item cannot use
        }
    }

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; prefer filling.
    score += 0.8 * open_bins_count as f64;

    // Prefer bins tighter than the mean residual (better fit than average).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: allow opening a new bin only when no good fit exists.
    if bin_residual == bin_capacity {
        // Baseline competitive score; open bins with low score beat it.
        score = 50.0 + 0.5 * open_bins_count as f64;
        if post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item exactly fills the post-residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Next item fits inside leftover: mildly good, but leaves more dead space later.
            score -= 30.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use the leftover: penalize proportionally to wasted space.
            score += 40.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Penalize creating unusable dead space (small slivers that few items can fill).
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Compare post_residual against mean residual across open bins:
    // prefer leaving residuals close to the mean (balanced bins), punish outliers.
    let diff = post_residual as f64 - mean_residual;
    score += 0.05 * diff * diff;

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 && post_residual >= next_item_size { 1.0 } else { 0.0 };
        score += 200.0 - 100.0 * pressure;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0 * progress;
        // Fewer open bins -> opening a new one is cheaper.
        score -= 10.0 * open_bins_count as f64;
    }

    // Slight preference for filling bins that are already mostly full.
    score -= 0.3 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful later
    // are heavily penalized. A gap is "dead" if it is below the minimum item size
    // or below the lookahead item's needs.
    let dead_threshold = 10.0_f64.max(next_item_size as f64);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving a gap that exactly fits the next item (k=2 lookahead pairing)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        score -= 5.0; // mild reward for still being usable by the next item
    }

    // Fit quality: fraction of bin filled by this item
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 20.0;

    // Open-bins pressure: prefer consolidating into existing bins
    // when many bins are open; scale penalty for spreading items.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly prefer using the only bin that fits,
    // otherwise a new bin gets opened and this residual is stranded.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mean residual coupling: bins with residual far below the mean are
    // already fragmented; prefer placing into bins near/above mean residual
    // so small residuals get consumed rather than multiplied.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += dev * 0.4;
    } else {
        score += dev * 0.1;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity and no open bin offers a tight fit. Penalize opening bins early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 - fill * 40.0 + progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A residual that cannot fit even the smallest plausible item (>=1)
    // is pure waste; residuals below a "useful threshold" are heavily taxed.
    let useful_threshold: f64 = 20.0;
    if (post_residual as f64) < useful_threshold {
        score += (useful_threshold - post_residual as f64) * 6.0;
    }
    // Exact fit is a perfect placement.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits the post residual,
    // reward this bin strongly (chaining placements).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual blocks the next item: dead space for the lookahead.
        score += 8.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading; makes opening new bins less attractive.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 3.0 * progress);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let mean_gap = mean_residual - item_size as f64;
        // Penalize new bin unless existing residuals are poor fits.
        if mean_gap > 0.0 {
            score += 30.0 + open_bins_count as f64 * 2.0;
        } else {
            score -= 5.0;
        }
    }

    // Mild alignment with mean residual: bins deviating far from the mean
    // residual (very full bins) are slightly preferred (tight packing).
    score -= (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fraction bands
    let pr = post_residual as f64;
    let frac = pr / cap;
    // Dead-space penalty grows super-linearly for unusable small residuals
    if post_residual > 0 {
        let dead = if post_residual < 10 { 60.0 } else if post_residual < 20 { 25.0 } else { 0.0 };
        score += dead;
    }

    // Perfect-fit harmonic reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // bonus scaled by how snugly next item fits
            let snug = 1.0 - ((post_residual - next_item_size) as f64) / cap;
            score -= 15.0 + 20.0 * snug;
        } else {
            // post_residual unusable for next item: penalize more if residual is tiny
            score += 10.0 + 30.0 * (1.0 - frac);
        }
    } else {
        // last item: prefer tightest fit
        score += 0.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: mild penalty so it's chosen only when fits are bad,
    // but scaled down when open bins are numerous and residuals fragmented
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / cap);
        score += 45.0 - 0.5 * pressure;
        // if next item is large, opening fresh bin is less attractive
        if next_item_size > 50 {
            score += 10.0;
        }
    }

    // Stream progression: late in stream, consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize leaving dead space that cannot fit the next item's minimum size.
    if post_residual > 0 && next_item_size > 0 {
        if post_residual < next_item_size {
            score += 18.0 * (next_item_size - post_residual) as f64;
        } else {
            // Reward residual that can accommodate the lookahead item.
            score -= 12.0;
        }
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Competing bins: mildly prefer bins with less residual waste potential.
        score += 5.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: an empty bin should only win when the fit into
    // existing bins is poor. Penalize the fresh bin so it loses to decent fits.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            // Opening a fresh bin makes sense if the next item is large and current
            // bins are crowded.
            if mean_residual < item_size as f64 {
                score -= 55.0;
            }
        }
    }

    // Time-horizon coupling: early in the stream, be conservative with new bins;
    // late in the stream, exploit tight fits more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * tightness;
    score += 15.0 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64);

    // Global congestion: when many bins are open with high mean residual,
    // discourage opening new bins / encourage filling existing ones.
    score -= 0.15 * mean_residual;
    score += 1.5 * open_bins_count as f64;

    // Prefer bins whose residual is close to the item (best-fit flavor).
    let gap = (bin_residual - item_size) as f64;
    score += 0.3 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals in [1, 9] are nearly unusable (min item = 1..100 unknown,
    // but tiny gaps rarely match) — penalize heavily with a quadratic bump.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0 - 2.0 * post_residual as f64;
    }
    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Small-but-usable residual that still fits the lookahead item: reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Lookahead just barely misses: penalize near-miss gaps.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Tightness reward: fraction of bin filled by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins; encourage closing bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 1.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last chance before opening a new bin: strong reward to use this bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only when open bins are few or item is huge.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / 8.0 + fill_ratio;
        score -= 5.0 * pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (below min item size) are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 200.0 * (10 - post_residual) as f64; // unusable sliver => heavy penalty
    }
    // Mid-size dead space: gaps that can't fit the lookahead item are less useful.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 30.0;
    }
    // Reward perfect / near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Tightness bonus: fraction of bin consumed by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 50.0 * tightness;

    // Open-bin pressure: prefer existing bins when many are open, to consolidate.
    score += (open_bins_count as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: make it attractive only when current bin would be badly wasted.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; compare against wasted space of alternatives.
        score = 100.0 - 50.0 * tightness;
        if post_residual < 20 {
            score -= 20.0; // a fresh bin will soon be near-full too
        }
        if fitting_bins_count == 1 {
            score += 80.0; // don't abandon the last-chance bin
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin can serve the next item as well
        }
    }

    // Slight stream-progression term: later in stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small gaps: residual below the minimum item size (1) is impossible,
    // but tiny residuals (< 12) are statistically hard to fill.
    if post_residual > 0 && post_residual < 12 {
        score += (12.0 - post_residual as f64) * 3.0;
    }

    // Reward tight fits (post_residual near zero) with a superlinear bonus.
    score -= 40.0 / (1.0 + post_residual as f64);

    // Pressure from number of open bins: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post-residual exactly, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 15.0 / (1.0 + slack);
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use leftover space: penalize wasted potential.
        score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.5;
    }

    // Mild bias toward bins with below-average residual (consolidate fullness).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Early in stream: be slightly more willing to open bins (keep flexibility);
    // later: consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when current bins are crowded or fit is bad.
        let crowding = mean_residual / bin_capacity as f64;
        score = 60.0 + crowding * 40.0 - progress * 30.0
            + if fitting_bins_count <= 1 { 0.0 } else { 20.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest item are pure waste; penalize them heavily.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 - 6.0 * post_residual as f64; // tiny gap = big penalty
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // this placement is excellent; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual <= 8 {
            score += 10.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading items out.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that fits the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when the item is large relative
    // to residual space in typical open bins (poor fits everywhere).
    if bin_residual == bin_capacity {
        let tight_fit = (item_size as f64 / bin_capacity as f64) > 0.85;
        let no_good_homes = mean_residual < item_size as f64 * 1.15;
        if tight_fit || no_good_homes || fitting_bins_count == 0 {
            score -= 55.0;
        } else {
            score += 40.0; // discourage opening bins when decent fits exist
        }
    }

    // Slight preference for using emptier bins early, tighter bins later.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 100.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // next item won't fit here; penalize proportional to wasted gap
            score += 50.0 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening new bins when an open bin fits reasonably
    if bin_residual == bin_capacity {
        score += 300.0 + post_residual as f64;
        if fitting_bins_count > 0 {
            score += 150.0;
        }
    }

    // Slight preference for filling bins as stream progresses
    score *= 1.0 - 0.1 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to be useful later are costly.
    // Treat gaps < 10 (or < next item) as near-wasted space.
    let dead_threshold = if next_item_size > 0 { next_item_size.min(bin_capacity / 2) } else { 10 };
    if post_residual < dead_threshold {
        score += 50.0 * (dead_threshold - post_residual) as f64;
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 150.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins;
    // favor packing into existing ones more tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += pressure * 5.0;

    // Penalize bins whose residual deviates strongly from the mean residual
    // (keeps residual profile homogeneous, easier future fits).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // New-bin candidate: baseline attractiveness, modulated by whether
    // existing fits are poor (small fitting_bins_count => opening may be fine).
    if bin_residual == bin_capacity {
        score -= 30.0 + 10.0 * (fitting_bins_count as f64).ln().max(0.0);
        // But late in the stream with many open bins, prefer filling existing bins.
        score += pressure * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize post_residual in the "unusable gap" zone
    // where nothing from the typical size range can ever fill it.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Worst gaps: small but nonzero (1..=15) -> almost certainly dead space.
        if post_residual <= 15 {
            score += 40.0 * (16.0 - gap);
        } else if post_residual <= 30 {
            score += 15.0 * (31.0 - gap);
        }
        // Perfect fit bonus.
        if post_residual == 0 {
            score -= 60.0;
        }
        // Residual that exactly matches next item is valuable.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize if next item cannot fit into the post-residual (creates sequencing risk),
        // but only mildly since lookahead is limited.
        if next_item_size > post_residual && post_residual > 0 {
            score += 8.0;
        }
        // Reward residuals large enough to host any plausible next item.
        if post_residual >= 80 {
            score -= 10.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when few fitting bins exist
    // (last-chance bin should be strongly preferred to avoid opening new bins).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }
    // Mild penalty proportional to number of open bins to encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    // Progress-aware: early in the stream, tolerate spreading; late, tighten packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is close to the mean (balanced packing) slightly.
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    // New-bin candidate: only attractive when it beats terrible fits; make it moderately costly.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if current item is large, a fresh bin is fine (large items fit anywhere anyway).
        if item_size >= 60 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for typical
    // future items (likely unusable) are heavily penalized.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) > 0.0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward tight fits strongly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * tightness * 20.0;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing
    // ones rather than spreading; penalize placements that leave a bin
    // nearly empty of use while many bins are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += (post_residual as f64 / bin_capacity as f64) * pressure * 0.5;

    // Last-chance bin: strongly favor using the only bin that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits
    // well (large post_residual relative to capacity) or when open-bin
    // count is low and mean residual is small.
    if bin_residual == bin_capacity {
        let bad_fit = (bin_residual as f64 - item_size as f64) / (bin_capacity as f64);
        let open_benefit = if mean_residual < item_size as f64 { 40.0 } else { 0.0 };
        let few_bins = if open_bins_count <= 2 { 25.0 } else { 0.0 };
        let lookahead_need = if next_item_size > 0 && next_item_size as f64 > (bin_residual as f64 - item_size as f64) { 10.0 } else { 0.0 };
        score = bad_fit * 100.0 - open_benefit - few_bins - lookahead_need;
        // Never open a new bin when a decent fit exists elsewhere.
        if (bin_residual as f64 - item_size as f64) < dead_threshold && open_bins_count > 0 {
            score += 200.0;
        }
    }

    // Lookahead: if the next item would fit the post residual, reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += (next_item_size as f64 - post_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small to hold even the smallest item (1).
    // Instead penalize residuals smaller than next_item_size (lookahead waste).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 * (next_item_size - post_residual) as f64;
    }
    // Reward residuals that exactly accommodate the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer the bin where item is a large fraction of residual.
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 10.0 * fill_ratio;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Time horizon coupling: late in the stream, consolidate aggressively
    // (avoid new bins); early, allow spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 8.0 + 30.0 * progress;
        // Opening a new bin is worse if other bins fit.
        if fitting_bins_count >= 1 {
            score += 15.0 + 10.0 * (fitting_bins_count as f64).ln();
        }
    }

    // Global state: if mean residual is high, prefer filling the emptiest bins;
    // if mean residual is low, prefer bins tighter than the mean.
    if bin_residual as f64 > mean_residual {
        score -= 4.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    } else {
        score += 4.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.6 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible item are pure waste. Penalize them quadratically.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) + 9 {
        score += 25.0 * (1.0 + (10 - post_residual as i64) as f64).powi(2);
    }

    // Reward very tight fits (post_residual near zero but usable).
    if post_residual <= 3 {
        score -= 15.0;
    }

    // If the next item can use the leftover space, this bin is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 {
        // Leftover won't serve the lookahead: mild dead-space penalty.
        score += 4.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.6 + 0.4 * progress);

    // New-bin candidate: only attractive when it beats poor fits, i.e. when
    // this bin's residual is large relative to the mean and the item is big.
    if bin_residual == bin_capacity {
        score = 55.0 + open_bins_count as f64 * 0.5 - item_size as f64 * 0.3;
    } else {
        // Prefer fuller bins relative to the fleet mean.
        score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear emphasis
    let mut score = norm_pr * (1.0 + 0.9 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post-residual with stream progress:
    // later in the stream, tighter packing matters more
    let coupling = norm_pr * (1.0 - progress) * (1.0 - progress) - 0.5 * norm_pr * progress * progress;
    score += 2.0 * coupling;

    // Lookahead: reward residual that can fit the next item, penalize near-miss dead space
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let fit_quality = (pr - n) / cap;
            score -= 1.5 * (1.0 - fit_quality) * (1.0 - 0.5 * progress);
        } else {
            let miss = (n - pr) / cap;
            score += 0.8 * miss * miss * (0.5 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 - norm_pr);
    } else if fitting_bins_count > 1 {
        score += 0.2 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize bins far below mean residual (keeps residual distribution tight)
    score += 0.4 * ((pr - mean_residual) / cap).abs();

    // Slight preference for consolidating into fewer bins late in the stream
    score += 0.05 * (open_bins_count as f64) * progress;

    // New-bin candidate: make it moderately attractive only when open bins are poor fits
    if bin_residual == bin_capacity {
        score -= 0.6 + 0.8 * progress;
        if next_item_size > 0 && (next_item_size as f64) <= cap * 0.5 {
            score -= 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize residuals in "dead zones" that few item sizes can fill.
        // Class A: residual <= 10 -> nearly dead space.
        if post_residual < 10 {
            score += 60.0;
        }
        // Class B: residual in (10, 20) -> fillable only by small items.
        else if post_residual < 20 {
            score += 25.0;
        }
        // Class C: residual in [50, 90] -> moderately fillable.
        else if post_residual >= 50 && post_residual < 90 {
            score -= 8.0;
        }
        // Harmonic bonus: residual divisible by common item sizes (5,10,20,25).
        if post_residual % 10 == 0 {
            score -= 6.0;
        }
        if post_residual % 25 == 0 {
            score -= 4.0;
        }
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            // Next item still fits: mild bonus proportional to leftover after next.
            let after_next = post_residual - next_item_size;
            score -= 10.0 + (after_next as f64) * 0.2;
        } else {
            // Next item would not fit here: penalize leaving residual just below next size.
            if post_residual >= next_item_size.saturating_sub(10) {
                score += 20.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    // and we have many open bins already (consolidation pressure).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_fit = post_residual > 40.0f64.max(item_size as f64 * 0.5);
        if bad_fit && open_bins_count > 2 {
            score -= 30.0 + 20.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
    }

    // Prefer bins tighter than the mean residual (better packing direction).
    score += 0.3 * ((post_residual as f64) - mean_residual);

    // Mild preference for bins with less residual overall as stream matures.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to residual (waste ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio;

    // Last-chance pressure: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor consolidation.
    score += 0.8 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit here: penalize leaving a large residual that becomes dead space.
            score += 5.0;
        }
    }

    // Mean residual coupling: placing into a bin below mean residual consolidates small gaps.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: only attractive when no open bin fits well or stream is early.
    if bin_residual == bin_capacity {
        let stream_frac = step_index as f64 / total_items.max(1) as f64;
        let desperation = (post_residual as f64 / bin_capacity as f64) * 30.0
            + (fitting_bins_count == 0) as i32 as f64 * 50.0
            + (1.0 - stream_frac) * 5.0;
        score = 55.0 - desperation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = 10.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight fit bonus: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Penalize leaving a gap that exactly fits nothing useful (residual in 1..10 zone already covered),
    // but also penalize mid-range waste mildly.
    score += (post_residual as f64 / bin_capacity as f64) * 5.0;

    // Open bins pressure: with many open bins, prefer filling existing ones over spreading.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.8 * (0.5 + progress);

    // Mean residual coupling: if mean residual is low, keep bins tight.
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as u64) <= post_residual as u64 {
        score -= 12.0;
    }
    // If next item would leave this bin useless anyway, mild penalty.
    if next_item_size > 0 && post_residual > 0 && (next_item_size as f64) > post_residual as f64 {
        score += 3.0;
    }

    // New-bin candidate: opening a new bin should be costly unless current fit is terrible.
    if bin_residual == bin_capacity {
        // Base cost of a new bin, reduced when this bin is a last resort elsewhere.
        score = bin_capacity as f64 * 0.35 + open_bins_count as f64 * 0.5;
        if post_residual == 0 {
            score -= 10.0;
        }
        if item_size > 50 {
            score += 5.0; // large items in fresh bins are fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold even the smallest item
    // (size 1..=10) are nearly unusable; penalize the "wasted" portion.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }
    // Semi-dead zone: residual 10..=19 can only fit tiny items; mild penalty.
    else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits: the smaller the item relative to the residual,
    // the better the packing.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 25.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open-bin pressure is high or no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        // Penalize new bins when few bins are open (early stream).
        score += 30.0 + open_bins_count as f64 * -0.5 + progress * 10.0;
        // If the next item would fit perfectly with this item in a fresh bin,
        // make the new bin more attractive.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            let combined = (item_size + next_item_size) as f64;
            if combined / bin_capacity as f64 > 0.9 {
                score -= 35.0;
            }
        }
        // If many bins are open with high mean residual, new bin is fine.
        if mean_residual > 60.0 && open_bins_count > 4 {
            score -= 15.0;
        }
    } else {
        // Prefer bins whose residual is close to the item (minimize fragmentation).
        let gap = (bin_residual - item_size) as f64;
        score += gap * 0.3;
        // Slight penalty for spreading across too many open bins.
        score += open_bins_count as f64 * 0.2;
    }

    // Lookahead: if the post residual cannot accommodate the next item,
    // this placement is terminal for the bin; slight penalty unless it was a tight fit.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fits (dead space minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0 + (5.0 - post_residual as f64) * 40.0;
    } else {
        // Non-linear dead-space penalty: small residuals are disproportionately bad.
        let r = post_residual as f64;
        score += (100.0 / r) * 12.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            // Chain fit: excellent — penalize less as post_residual approaches next size.
            let slack = post_residual as f64 - nxt;
            score -= 200.0 - slack * 2.0;
            if slack <= 10.0 {
                score -= 80.0; // tight chain: nearly perfect two-item packing
            }
        } else {
            // Next item cannot follow here; penalize more if we leave a big orphan gap.
            let gap = nxt - post_residual as f64;
            if gap < 20.0 {
                score += 60.0; // near-miss: mildly bad
            } else {
                score += 25.0; // clearly unusable for next item
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Reward using bins with residual below mean residual (consolidate waste),
    // penalize dipping into large-residual bins that remain flexible.
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= diff * 1.5;
    }

    // New-bin candidate handling: make an empty bin attractive only when the item
    // is large relative to capacity or the fit elsewhere is poor.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.7 {
            // Large items: opening a fresh bin is fine, even good.
            score -= 60.0 + fill_ratio * 50.0;
        } else {
            // Small/medium items should prefer existing bins.
            score += 120.0 - fill_ratio * 100.0;
        }
        // Late in the stream, avoid opening needless bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
    }

    // Mild preference to fill bins that are already mostly full (compactness).
    let used_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= used_ratio * 30.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: residual close to zero is good.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space exponentially; small residuals are valuable.
        score += (post_residual as f64).powi(2) * 0.01;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // perfect chaining: next item exactly fills this bin
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 - slack * 0.5; // next item still fits: bonus decays with slack
        } else {
            // next item won't fit here; penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    } else {
        // Last item: prefer zero residual even more strongly.
        score -= 100.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are scarcer; favor filling them.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.6;
    } else {
        score += (res - mean_residual) * 0.3;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a new bin should only win when it beats
    // a poor fit. Give the empty bin a mild handicap so real fits usually win,
    // but allow it when all open fits would waste a lot of space.
    if bin_residual == bin_capacity {
        score += 60.0;
        // If existing fits are terrible (large post_residual relative to next item),
        // the base score may already be high enough for the new bin to win.
        if next_item_size > 0 && post_residual as f64 > next_item_size as f64 * 1.5 {
            score -= 40.0;
        }
    }

    // Slight stream-progression pressure: late in the stream, consolidate more eagerly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (res / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item
    // (minimum item size is 1, but small gaps < ~15 are statistically hard to reuse)
    if post_residual < 15 {
        score += 60.0; // heavy penalty: near-unusable dead space
    } else if post_residual < 30 {
        score += 20.0;
    }

    // Reward exact-ish fits strongly
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits in this bin's post-residual, reward;
    // if next item is large and post_residual can't host it, penalize mildly.
    if next_item_size > 0 {
        if post_residual >= next_item_size as u32 {
            score -= 15.0;
        } else if post_residual > 0 && post_residual < next_item_size as u32 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer packing tight
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += pressure * 2.0;

    // New-bin candidate: prefer opening a new bin only when it's early in the stream
    // or the current fit is poor (large post_residual relative to capacity)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
        if post_residual as f64 > 0.6 * bin_capacity as f64 && open_bins_count > 0 {
            score -= 20.0; // poor fit elsewhere -> new bin is fine
        }
    }

    // Mild preference for bins with tighter residual (best-fit coupling)
    score += (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;

    // Exact fit: strong reward (waste-free placement).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic classes: post_residual modulo 10 — small residue classes mean
    // near-tight fits; reward them proportionally.
    let m = (post_residual % 10) as f64;
    score -= (10.0 - m) * 0.6;

    // Dead-space penalty: residual too small for the lookahead item is
    // unusable; penalize the unusable gap non-linearly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64;
        score += dead * 1.5 + (dead * dead) / cap_f;
    }

    // Fractional capacity waste term: linear in wasted fraction of the bin.
    score += (post_f / cap_f) * 5.0;

    // New-bin candidate: brand-new empty bin has bin_residual == bin_capacity.
    // Bias slightly toward reusing open bins, but if this is the ONLY fitting
    // bin, opening a fresh bin preserves it for larger future items.
    if bin_residual == bin_capacity {
        score += 8.0;
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 15.0; // next item needs a fresh bin anyway
        }
    }

    // Mean-residual coupling: prefer bins whose post-residual stays near the
    // fleet mean (balanced packing); deviate mildly.
    score += (mean_residual - post_f) * 0.1;

    // Stream progression: as the stream advances, favor tighter consolidation.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= t * 3.0;

    // Many open bins: discourage leaving tiny unusable slivers behind.
    if open_bins_count > 4 && post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10 / 20 define
    // how "usable" the leftover space is for future items (sizes 1..100).
    let post = post_residual as i64;
    let nxt = next_item_size as i64;

    // Perfect fit reward: strong subtraction.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: leftover too small for typical items is wasted.
    if post > 0 && post < 10 {
        score += 60.0;
    }

    // Harmonic residue classes: leftover congruent to 0 mod 10 is highly
    // reusable (many item sizes sum to multiples of 10).
    let r10 = post % 10;
    if r10 == 0 && post > 0 {
        score -= 25.0;
    } else if r10 <= 3 {
        score += 8.0 * (3 - r10) as f64;
    }

    // Integer-division thresholds on post_residual: classify leftover into
    // usable bands (>=50 half bin, >=25 quarter bin).
    if post >= 50 {
        score -= 15.0;
    } else if post >= 25 {
        score -= 5.0;
    } else if post > 0 {
        score += 10.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // this is a chained perfect fit — reward heavily.
    if nxt > 0 {
        if nxt == post {
            score -= 400.0;
        } else if nxt < post {
            // reward if post residual remains in a good class after next item
            let post2 = post - nxt;
            if post2 % 10 == 0 {
                score -= 40.0;
            }
            if post2 >= 10 {
                score -= 10.0;
            }
        } else {
            // next item cannot use this bin's leftover; slight penalty if
            // leftover is small (dead space locked in).
            if post > 0 && post < 20 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let base = 40.0 + 30.0 * progress;
        score += base;
        // But if mean residual across open bins is tiny (all bins nearly
        // full), opening fresh space is fine.
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 80.0;
        }
        // If next item is large, a fresh bin gives flexibility.
        if nxt >= 70 {
            score -= 20.0;
        }
    }

    // Prefer tighter bins overall: closeness of fit (small post_residual
    // relative to item size) rewarded.
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= 20.0 * tightness;

    // Mild pressure to consolidate: more open bins -> prefer filling existing.
    score += 0.5 * open_bins_count as f64;

    // Deviation from mean residual: bins far below mean are "tighter",
    // favor them slightly.
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes of post_residual via modulo arithmetic (capacity 100 -> mod 10, mod 25)
    let mod10 = post_residual % 10;
