    }

    // Integer-division thresholds: classify residual into harmonic bands
    let band = post_residual / 25; // 0..4
    score += band as f64 * 3.0;    // prefer tighter bins (smaller residual band)

    // Fraction of capacity left
    let frac = post_residual as f64 / cap;
    score += frac * 10.0;

    // Lookahead coupling: does next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic match: next item leaves another aligned residual?
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 10.0;
            } else {
                score -= 3.0;
            }
        } else {
            // next item won't fit: this residual becomes dead space unless small
            let waste = next_item_size - post_residual;
            score += (waste as f64) * 0.5;
            if post_residual > 0 && post_residual < 10 {
                score += 15.0; // tiny unusable sliver with no future use
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bin is a bad host
    if bin_residual == bin_capacity {
        // fresh bin: neutral base, slightly penalized so real fits win, but
        // relieved if all open bins are badly fragmented
        score = cap * 0.35 + (mean_residual - frac * cap) * 0.2;
        if fitting_bins_count == 0 {
            score -= 30.0; // no open bin fits: must open new bin
        }
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Late-stream consolidation: as stream progresses, tighten bin usage
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += frac * progress * 8.0;

    // Fragmentation pressure: if mean residual is high, prefer consuming large residuals
    if mean_residual > 40.0 && post_residual >= mean_residual {
        score += 5.0;
    }

    score
}

