    // space after placement deviates favorably (smaller) from the mean.
    score += (mean_residual - post_residual as f64) * -0.3;

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Discourage opening new bins when good open bins exist; make the empty-bin
    // candidate less attractive unless the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 120.0;
        score += 150.0 - large_item_bonus;
        // early in the stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 80.0 * (1.0 - progress);
    }

    // Mild penalty for leaving many open bins with fragmented space.
    score += open_bins_count as f64 * 0.5;

    score
}

