    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how it decomposes modulo small divisors.
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Class A: post_residual divisible by 4 -> "harmonic" leftover, easy to fill later.
    if pr % 4 == 0 {
        score -= 6.0;
    }
    // Class B: divisible by 5 (decile-friendly with C=100).
    if pr % 5 == 0 {
        score -= 4.0;
    }
    // Class C: divisible by 10 -> prime harmonic slot.
    if pr % 10 == 0 {
        score -= 5.0;
    }
    // Dead-space penalty: post_residual in awkward odd classes (odd and not divisible by 5).
    if pr % 2 == 1 && pr % 5 != 0 {
        score += 5.0;
    }

    // Integer-division thresholds on post_residual.
    if pr == 0 {
        score -= 30.0; // perfect fill
    } else if pr < 10 {
        score += 12.0; // unusable dead space (min item is 10)
    } else if pr <= 20 {
        score += 3.0;  // narrow slot, risky
    } else if pr <= 50 {
        score -= 2.0;  // sweet middle band
    }

    // Fraction-of-capacity coupling.
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;
    if fill_frac > 0.9 {
        score -= 10.0;
    } else if fill_frac > 0.7 {
        score -= 5.0;
    } else if fill_frac < 0.4 {
        score += 4.0;
    }

    // Next-item lookahead via modulo classes: reward if next item divides evenly into post_residual.
    if next_item_size > 0 && next_item_size <= pr {
        if pr % next_item_size == 0 {
            score -= 15.0;
        } else if pr - next_item_size < 10 {
            score += 6.0; // next item would create dead space
        } else {
            score -= 3.0;
        }
    } else if next_item_size > pr {
        score += 4.0; // this bin's leftover can't host next item
    }

    // Last-chance bonus: only this bin fits -> avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 14.0;
    }

    // New-bin candidate: make it attractive only when all open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        // Open new bin if existing residuals are small/awkward; otherwise prefer reusing.
        score = 40.0 + fragmentation * 60.0 - progress * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space penalty: residuals that are too small to hold even
    // the minimum item (1) are pure waste; residuals that can hold nothing
    // useful relative to typical items are heavily penalized.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear dead-space curve: gap <= 10 is nearly worthless, gap in
    // 11..=30 is marginal, gaps > 30 are usable.
    let gap = post_residual as f64;
    if gap == 0.0 {
        // Perfect fit: reward strongly.
        score -= 60.0;
    } else if gap <= 10.0 {
        // Unusable dead space regardless of distribution.
        score += 25.0 * (1.0 - gap / 10.0);
    } else if gap <= 30.0 {
        // Marginal gap: penalize quadratically as it shrinks.
        let t = (30.0 - gap) / 20.0;
        score += 12.0 * t * t;
    }

    // Coupling with lookahead: if the next item fits exactly in the
    // post_residual, this is a great placement; if next item barely misses,
    // we created dead space for it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if gap >= nxt {
            score -= 8.0; // next item can also go here
        } else if gap > 0.0 && nxt - gap <= 10.0 {
            score += 6.0 + 0.4 * (nxt - gap); // near-miss dead space
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // With many fitting bins, prefer tighter fits via post_residual (already in base).
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Open-bin pressure: penalize placements that keep many bins open with
    // fragmented residuals, especially late in the stream.
    score += 0.35 * open_bins_count as f64 * (0.5 + progress);

    // Prefer bins whose residual is below mean (tighter bins first),
    // keeping looser bins available for larger future items.
    if bin_residual as f64 > mean_residual {
        score += 4.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
    } else {
        score -= 2.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    }

    // New-bin candidate handling: an empty bin is a fresh resource; only
    // attractive when existing bins would create dead space. Penalize the
    // empty-bin candidate moderately so it wins only when gap penalties dominate.
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits the next item -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match: next item fits with small slack -> moderate reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to leftover dead space
        let dead = next_item_size as f64 - post_residual as f64;
        score += 10.0 * (dead / 100.0);
    }

    // Penalize tiny unusable residuals relative to the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Discourage spreading across many bins when mean residual is already high
    if bin_residual as f64 > mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    // Late in the stream, prefer tight fits (waste matters more)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let good_lookahead = next_item_size > 0 && post_residual >= next_item_size;
        if fitting_bins_count > 0 && good_lookahead {
            score += 50.0; // keep using open bins
        } else {
            score -= 10.0; // open a new bin for poor fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: squash post_residual non-linearly.
    score -= (post_residual as f64 / bin_capacity as f64).powi(3) * 60.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 5 {
        score -= 20.0;
    }

    // Penalize dead space too small for typical items (1..100 range).
    if post_residual > 0 && post_residual < item_size {
        // dead space likely unusable; mild penalty scaled by its size
        score += (post_residual as f64) * 0.15;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item won't fit here; slight penalty proportional to overflow
            score += ((next_item_size - post_residual) as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make fresh bins attractive only when open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowdedness = mean_residual / bin_capacity as f64;
        // cost of a new bin decreases late in the stream and when open bins are full
        let new_bin_cost = 30.0 * (1.0 - 0.5 * progress) + 20.0 * (1.0 - crowdedness).powi(2);
        score += new_bin_cost;
        // fewer open bins -> opening a new one is cheaper
        score -= (open_bins_count.min(20) as f64) * 0.5;
    }

    // Mild preference for bins below mean residual (balance load across bins).
    score += ((bin_residual as f64 - mean_residual) * 0.05).max(-5.0).min(5.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: quadratic penalty on wasted space, modulated by stream progress.
    // Early on, waste is cheap (bins may fill later); late, waste is costly.
    let waste_curve = x * x * (1.0 + 1.5 * progress) + 0.5 * x * (1.0 - progress);

    // Perfect fit reward (smooth via cubic falloff around x=0)
    let perfect_fit = -(1.0 - x).powi(3) * 8.0;

    // Non-linear coupling: residual vs mean residual deviation (polynomial)
    let dev = x - mean_residual / cap;
    let coupling = 2.0 * dev * dev - 1.0 * dev * progress;

    // Lookahead: penalize if post residual can't hold next item (smooth polynomial)
    let next_fit = if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr) / cap;
        if gap > 0.0 { 3.0 * gap * gap } else { -2.0 * gap * gap }
    } else { 0.0 };

    // Last-chance bin: strong reward to use it rather than open new bin
    let last_chance = if fitting_bins_count == 1 { -4.0 } else { 0.0 };

    // New-bin candidate bias: discourage opening new bins early, allow late
    let new_bin_bias = if bin_residual == bin_capacity {
        2.5 - 4.0 * progress * progress
    } else { 0.0 };

    // Slight preference to keep few open bins
    let spread = 0.01 * open_bins_count as f64;

    let mut score = pr as f64 * (1.0 + 0.5 * progress)
        + waste_curve * 10.0
        + perfect_fit
        + coupling
        + next_fit
        + last_chance
        + new_bin_bias
        + spread;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction slot does the leftover land in?
    let quarter = (bin_capacity / 4).max(1);
    let half = (bin_capacity / 2).max(1);
    let cls = (post_residual / quarter) as f64; // 0..=4 harmonic class

    // Dead-space penalty: leftovers in the awkward middle classes are least reusable.
    let dead_penalty = match post_residual {
        0 => -60.0,                          // perfect fit: strongly reward
        r if r < quarter => -18.0,           // small gap, still often usable
        r if r < half => 14.0,               // mid gap: dead space risk
        r if r < 3 * quarter => 6.0,         // large-ish gap
        _ => -4.0,                           // nearly empty bin, very reusable
    };
    score += dead_penalty;

    // Lookahead coupling: reward if next item fits into post_residual (harmonic chaining)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact class match bonus: post_residual - next_item_size small
            let chain_gap = (post_residual - next_item_size) as f64;
            score -= 10.0 + 0.35 * (quarter as f64 - chain_gap.min(quarter as f64));
        } else {
            // next item won't fit here: leftover must hold value for later; penalize mid classes
            score += cls * 2.5;
        }
    }

    // Integer-division threshold: bins whose residual is a multiple of small harmonics are more flexible
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 3.0;
    }

    // Last-chance bin: strongly prefer using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no decent fit exists
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let tight_fits = if next_item_size > 0 { fitting_bins_count } else { fitting_bins_count };
        // penalize opening a bin unless current fits are all poor (post_residual very small here is impossible;
        // instead judge via mean_residual tightness and fitting scarcity)
        let scarcity = if fitting_bins_count <= 1 { 0.0 } else { 40.0 };
        let mean_tight = (mean_residual / bin_capacity as f64) < 0.25;
        score = 55.0 + scarcity - if mean_tight { 20.0 } else { 0.0 }
            - (post_residual as f64); // keep base ordering
        // late in stream, prefer filling existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Prefer bins with residual close to item (tight fit), scaled by harmonic class
    let tightness = (bin_residual - item_size) as f64;
    score += 0.10 * tightness * (1.0 + 0.15 * cls);

    // Mild pressure to keep open bin count low
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize "unusable" dead space: small gaps that few future items can fill.
    if post_residual > 0 {
        let dead = if post_residual < 20 { 40.0 } else if post_residual < 35 { 15.0 } else if post_residual < 50 { 5.0 } else { 0.0 };
        score += dead;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual && post_residual - next_item_size <= 10 {
        score -= 15.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Pressure from number of open bins: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + open_bins_count as f64 * 2.0 + progress * 15.0;
        // But allow a new bin if it would leave a nicely usable gap matching the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    } else {
        // Slight preference for bins tighter than average (fill the fullest bins first).
        let avg = mean_residual;
        if (bin_residual as f64) < avg {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but weight by how much
    // of the bin's original space we consumed.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio * (bin_residual as f64 / bin_capacity as f64);

    // Aggressive 2-step lookahead: reward exact/near match of post_residual
    // to the next item size (chain placement).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // Next item can chain into this bin: reward closeness of match.
            score -= 30.0 * (1.0 - diff / bin_capacity as f64);
            // Exact match is golden.
            if diff < 1.0 {
                score -= 25.0;
            }
        } else {
            // Dead space the next item cannot use: penalize proportionally.
            score += 0.35 * diff;
            // Extra penalty if dead space is small-but-unusable (worst case).
            if diff < 10.0 {
                score += 15.0;
            }
        }
        // If the NEXT item would exactly fill a fresh bin with current item,
        // opening a new bin becomes attractive; compare against that ideal.
        let fresh_pair_waste = (bin_capacity as f64 - item_size as f64 - nxt).abs();
        let this_waste = post_residual as f64 - nxt; // may be negative
        if this_waste < 0.0 && fresh_pair_waste < this_waste.abs() {
            score += 20.0; // fresh bin pairs better with next item
        }
    }

    // Relative to mean residual: placing into a bin whose residual deviates
    // favorably from the mean keeps the bin population homogeneous.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev; // prefer bins with below-average residual (tighter)

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
        // But if the resulting dead space blocks the next item badly, soften.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0;
        }
    }

    // New-bin candidate handling: an empty bin has large post_residual,
    // which is naturally penalized; add explicit mild penalty so new bins
    // are only opened when open-bin fits are poor.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Exception: if item is large and pairs perfectly with next item
        // in a fresh bin, allow opening.
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 60.0;
        }
    }

    // Late-stream consolidation: near the end, avoid leaving many open bins;
    // prefer packing into existing bins more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * (1.0 - progress) * (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) * -1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic discount for small post-residual
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Dead-space penalty: residuals too small for the smallest plausible item
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead: reward if the next item fits exactly into post-residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item cannot use this bin's remainder: mild penalty
        score += 5.0;
    }

    // Last-chance bonus: only bin that fits the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive when current fit is poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        // Opening a new bin wastes capacity equal to residual of others; discourage
        // unless the item is large and fits poorly anywhere (post_residual small here
        // means item nearly fills a fresh bin, which is good).
        score += 30.0 + 0.5 * mean_residual;
        score -= 50.0 * fit_ratio;
        // Early stream: opening bins is cheaper; late stream: prefer consolidation
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * t;
        // Many open bins: discourage opening more
        score += 2.0 * open_bins_count as f64;
    }

    // Prefer bins below mean residual (keeps residuals balanced)
    if !is_new_bin {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.1 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap;
    let fit = item_size as f64 / cap;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = post * (1.0 + 0.8 * pr * pr);

    // Smooth polynomial coupling of tightness with stream progress:
    // early stream: mild tightness bonus; late stream: strong tightness bonus
    let tightness = (1.0 - pr) * (1.0 - pr);
    score -= 30.0 * (0.5 + 0.5 * progress) * tightness * fit;

    // Penalize large dead space non-linearly, weighted by progress
    score += 12.0 * (0.3 + 0.7 * progress) * pr * pr * pr * cap;

    // Last-chance bin: reward strongly, smoothly scaled by progress
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits the post-residual smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let slack = (post - nx) / cap;
            score -= 10.0 * (1.0 - slack * slack);
        } else {
            let miss = (nx - post) / cap;
            score += 8.0 * miss * miss;
        }
    }

    // Slight dispersion penalty: bins far from mean residual are less attractive
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Mild pressure to reuse existing bins as open-bin count grows
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-fit residual (modulo arithmetic) ---
    // Residuals that are "nice" (multiples of common item sizes) are more reusable.
    let pr = post_residual;
    let class_penalty: f64 = match pr {
        0 => -60.0, // perfect fit: strongly reward
        _ => {
            let mut p = 0.0;
            if pr % 10 == 0 { p -= 12.0; }
            else if pr % 5 == 0 { p -= 6.0; }
            if pr % 20 == 0 { p -= 4.0; }
            if pr % 25 == 0 { p -= 3.0; }
            // dead-space bands: tiny unusable slivers are penalized
            if pr < 10 { p += 25.0; }
            else if pr < 20 { p += 8.0; }
            p
        }
    };
    score += class_penalty;

    // --- Lookahead coupling: does next_item_size divide into post_residual? ---
    if next_item_size > 0 && pr > 0 {
        if next_item_size <= pr {
            // exact division => excellent chain
            if pr % next_item_size == 0 {
                score -= 18.0;
            } else {
                // leftover after next item: judge its harmonic class
                let leftover = pr - next_item_size;
                if leftover % 10 == 0 { score -= 8.0; }
                if leftover < 10 { score += 10.0; }
            }
        } else {
            // next item cannot fit here regardless; mild penalty for hoarding space
            score += 3.0;
        }
    }

    // --- Integer-division threshold on residual fraction of capacity ---
    let residual_quotient = pr / (bin_capacity / 4); // 0..4 buckets
    score += match residual_quotient {
        0 => -5.0,  // nearly full bin: good
        1 => 0.0,
        2 => 2.0,
        _ => 6.0,   // leaving a mostly-empty bin wastes it
    } as f64;

    // --- Last-chance bin: strongly favor using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is good when few bins fit the item or mean residual is low
        let pressure = (fitting_bins_count == 0) as i32 as f64
            + ((mean_residual < item_size as f64 * 0.5) as i32 as f64);
        score = (bin_capacity as f64) * 0.9 - pressure * 20.0;
        // late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // --- Mild consolidation pressure when many bins are open ---
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // --- Small tie-break noise-free symmetry breaker ---
    score += (pr % 3) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // smallest plausible future item (sizes 1..100) are pure waste.
    // Penalize small post_residuals hard (they trap the bin), but reward large ones mildly.
    if post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual < 25 {
        score += 25.0; // very hard to fill
    } else if post_residual < 50 {
        score += 8.0; // moderately hard
    } else {
        score -= 6.0; // roomy leftover: good fit
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // strongly favor this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        // next item would have fit here before this placement — mild penalty
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        // candidate new bin
        score += 15.0 + 3.0 * open_bins_count as f64;
        // but if existing bins would leave terrible dead space, new bin looks better
        if post_residual >= 90 { score -= 10.0; }
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // from the mean (below-mean residual = tighter bin, pack it first).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item won't fit here; mild penalty proportional to overflow gap.
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: fill bins as much as possible, avoid opening new bins.
        score += 60.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: baseline penalty so it's chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Late in the stream, opening new bins is extra wasteful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
        // If many bins are open already, discourage proliferation.
        score += 2.0 * open_bins_count as f64;
    }

    // Global state coupling: prefer bins whose residual deviates from the mean
    // when the deviation is large (consolidate similar residuals).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Prefer bins with less residual overall when many bins are open (consolidation).
    score += 0.05 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    // Early stream: slight preference for spreading items (keep flexibility).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress) * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear penalty on post-residual, strengthening with stream progress
    score += 20.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits via smooth exponential coupling
    score -= 15.0 * (-norm_pr * 6.0).exp() * (0.5 + 0.5 * progress);

    // Penalize dead space that next item cannot use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let unusable = (pr - nxt).max(0.0) / cap;
        score += 10.0 * unusable * unusable;
        // Reward leaving exactly room for the next item
        let gap = (pr - nxt).abs();
        score -= 8.0 * (-gap / 12.0).exp();
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 12.0 * (0.3 + 0.7 * progress);
    }

    // Mild pressure against bin sprawl late in stream
    score += 0.4 * open_bins_count as f64 * progress;

    // Pull toward mean residual balance
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: dead space analysis ---
    // Residuals that are unusable for typical small items are penalized.
    let pr = post_residual;
    if pr > 0 {
        // Dead space: residual too small to hold even a modest item (<= 10..20)
        if pr < 10 {
            score += 40.0; // nearly unusable
        } else if pr < 20 {
            score += 12.0;
        }
        // Modulo-10 harmonic classes: residuals that are multiples of 10
        // align well with integer item sizes; reward them.
        if pr % 10 == 0 {
            score -= 8.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
        // Exact fill is perfect
        if pr == 0 {
            score -= 100.0;
        }
    }

    // --- Lookahead coupling with next_item_size ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Bin can still serve the next item: strong reward, scaled by
            // how snugly the next item fits the post residual.
            let snug = (pr - next_item_size) as f64;
            score -= 15.0 + 0.3 * snug.max(0.0);
            // Perfect two-step fill
            if pr == next_item_size {
                score -= 30.0;
            }
        } else {
            // Next item won't fit here: mild penalty proportional to overflow
            let over = (next_item_size - pr) as f64;
            score += 0.2 * over.min(40.0);
        }
    } else {
        // Last item: prefer tightest fill
        score -= 5.0;
    }

    // --- Last-chance bin bonus ---
    if fitting_bins_count == 1 {
        // Using this bin avoids opening a new bin; reward unless fit is terrible
        let waste = post_residual as f64;
        score -= 25.0 - 0.15 * waste.min(80.0);
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh bin baseline: score equals its full residual, but give it
        // an edge when existing bins would leave bad dead space, and when
        // the stream is early (amortize future items into a fresh bin).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 + 20.0 * (1.0 - progress);
        // If the current fit is very poor (huge leftover), fresh bin wins
        if post_residual as f64 > 0.6 * cap {
            score -= 15.0;
        }
        // If next item is large and current bins are fragmented, fresh bin helps
        if next_item_size > 50 && mean_residual < 30.0 {
            score -= 10.0;
        }
    }

    // --- Mean residual context: prefer bins far from the mean when mean is high
    // (consolidate space), near the mean when mean is low ---
    let dev = (bin_residual as f64 - mean_residual).abs();
    if mean_residual > cap * 0.5 {
        score -= 0.1 * dev;
    } else {
        score += 0.05 * dev;
    }

    // --- Integer-division threshold classes on bin_residual ---
    let q = bin_residual / 25; // quarter classes: 0..4
    match q {
        0 => score -= 5.0,  // nearly full bin, finish it off
        1 => score += 2.0,
        3 => score -= 1.0,
        _ => {}
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) * 10 {
        // gap too small to ever be useful for realistic item sizes (>=1, but
        // treat gaps < 10 as near-dead since typical items are much larger)
        score += 60.0;
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tightness reward: fraction of bin consumed by this placement
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Open bins pressure: penalize spreading across many bins, but relax
    // pressure as stream progresses (late in stream, closing bins matters).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 - 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, reduced if existing bins are fragmented
        score += 35.0;
        // If mean residual across open bins is small (fragmented), opening
        // a fresh bin is more attractive.
        score -= (mean_residual / 10.0).min(20.0);
        // Large item with poor fit potential: new bin better
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 20.0;
        }
    } else {
        // Existing bin: penalize if placement leaves a gap that barely
        // misses the next item (bad lookahead coupling)
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            // gap can't fit next item; penalize proportionally to near-miss
            let near_miss = (next_item_size - post_residual) as f64;
            if near_miss <= 15.0 {
                score += 12.0;
            }
        }
        // Reward if next item fits in the resulting residual (chain fits)
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Penalize wasteful placements relative to mean residual fragmentation
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Near-match lookahead: reward small gap between post_residual and next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 15.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);
        // Penalize leaving space that next item can't use but is still large.
        if post_residual < next_item_size {
            score += 0.3 * post_residual as f64;
        }
    } else {
        // Last item: prefer tightest fit.
        score -= 10.0;
    }

    // Compare post_residual against mean residual: keep bin diversity balanced.
    score -= 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        let fit_quality = item_size as f64 / bin_capacity as f64;
        if fit_quality > 0.7 {
            score += 5.0; // big item: fine to open a bin
        } else {
            score += 30.0; // discourage wasting a fresh bin on small items
        }
    }

    // Mild pressure to fill bins tightly as stream progresses.
    score += 0.1 * (step_index as f64 / total_items.max(1) as f64) * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize leaving dead space that cannot fit the next item's minimum size.
    if post_residual > 0 && next_item_size > 0 {
        if post_residual < next_item_size {
            score += 18.0 * (next_item_size - post_residual) as f64;
        } else {
            // Reward residual that can accommodate the lookahead item.
            score -= 12.0;
        }
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Competing bins: mildly prefer bins with less residual waste potential.
        score += 5.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: an empty bin should only win when the fit into
    // existing bins is poor. Penalize the fresh bin so it loses to decent fits.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            // Opening a fresh bin makes sense if the next item is large and current
            // bins are crowded.
            if mean_residual < item_size as f64 {
                score -= 55.0;
            }
        }
    }

    // Time-horizon coupling: early in the stream, be conservative with new bins;
    // late in the stream, exploit tight fits more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * tightness;
    score += 15.0 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64);

    // Global congestion: when many bins are open with high mean residual,
    // discourage opening new bins / encourage filling existing ones.
    score -= 0.15 * mean_residual;
    score += 1.5 * open_bins_count as f64;

    // Prefer bins whose residual is close to the item (best-fit flavor).
    let gap = (bin_residual - item_size) as f64;
    score += 0.3 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits (low post_residual); later, tolerate leftovers
    // since future packing options shrink.
    let pr_norm = pr / cap;
    let coupling = pr_norm * pr_norm * (1.0 - progress) * cap
                 - pr_norm * progress * cap * 0.5;
    score += coupling;

    // Reward near-perfect fits with a smooth quartic bonus.
    let fit_quality = 1.0 - pr_norm;
    score -= fit_quality * fit_quality * fit_quality * fit_quality * cap * 0.8;

    // Lookahead: penalize residuals that cannot host the next item.
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += (next_item_size as f64 - pr) * (0.5 + 0.5 * (1.0 - progress));
    }
    // Bonus when the residual still fits the next item exactly well.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = pr - next_item_size as f64;
        score -= (1.0 - slack / cap) * 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= cap * 0.6;
    }

    // Mild penalty relative to mean residual: avoid leaving bins far above average fill.
    score += (mean_residual - pr) * 0.05;

    // Slight preference for consolidating into fewer bins when many are open.
    score += (open_bins_count as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: coarse capacity fractions.
    // Residuals in (0,10] are near-perfect fits -> strong reward.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fill, always best
    } else if pr <= 10 {
        score -= 60.0;
    } else if pr <= 20 {
        score -= 20.0;
    } else if pr <= 30 {
        score -= 5.0;
    } else if pr <= 50 {
        score += 8.0;
    } else {
        score += 15.0; // large dead space penalty
    }

    // Modulo-10 harmonic class: residuals that are multiples of 10 pair well
    // with typical item sizes (multiples of 10), giving future exact fits.
    if pr % 10 == 0 && pr > 0 {
        score -= 12.0;
    }

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits here: reward, scaled by how tightly it fits.
            let tightness = (pr - next_item_size) as f64;
            score -= 25.0 - tightness * 0.3;
            if (pr - next_item_size) % 10 == 0 {
                score -= 10.0; // chain of exact fits
            }
        } else {
            // Next item cannot use this residual: penalize wasted potential
            // proportionally to how much of next item goes unused.
            score += (next_item_size - pr) as f64 * 0.15;
        }
    } else {
        // Last item: only the immediate fit matters.
        score -= 30.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a fresh bin when decent fits exist.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if many open bins are fragmented (high mean residual spread vs
        // this item), a fresh bin is more attractive.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if mean_residual < item_size as f64 * 0.5 {
            score -= 20.0 * progress;
        }
    }

    // Slight preference for bins tighter than the mean (best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps (< 10, or below min item size) are pure waste.
    if post_residual < 10 {
        score += 40.0;
    }

    // Penalize post_residuals that no typical item can use efficiently:
    // gap in (0, 20) is only usable by tiny items -> heavy penalty.
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (small but usable residual).
    if post_residual <= 5 {
        score -= 30.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // packing into existing bins is cheap.
    score += open_bins_count as f64 * 0.5;

    // Lookahead: if next item fits exactly in the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    }
    // If next item would NOT fit in the residual, slightly penalize leaving a gap
    // it could have used.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default score so that
    // only genuinely bad fits in existing bins trigger opening a new bin.
    if bin_residual == bin_capacity {
        score = 45.0 + item_size as f64 * 0.3;
        // Late in the stream, opening new bins is less costly (no future to plan for).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 15.0;
        // If no open bin fits at all, new bin is the only option.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference toward bins with residuals close to mean (balance preservation).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
