pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 { score -= 50.0; }

    // Penalize large dead space non-linearly
    let pr = post_residual as f64;
    score += 0.15 * (pr / cap) * pr;

    // Lookahead: reward residual that can fit next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 >= nx {
            score -= 8.0 * (1.0 - nx / cap);
        } else {
            score += 5.0; // dead space for next item
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: mildly discourage opening new bins
    if bin_residual == bin_capacity {
        score += 10.0 + 0.1 * open_bins_count as f64;
        // but if item is large relative to mean residual, opening fresh bin is fine
        let mean_r = if mean_residual > 0.0 { mean_residual } else { cap };
        if item_size as f64 > mean_r * 0.8 { score -= 12.0; }
    }

    // Time horizon: late in stream, consolidate aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = fit_norm * (1.0 + 1.5 * progress * fit_norm - 0.75 * progress * progress * (1.0 - fit_norm));

    let mut score = poly * cap;

    // Reward tight fits more strongly as stream progresses
    score -= 30.0 * (1.0 - fit_norm) * (1.0 - fit_norm) * (0.5 + progress);

    // Penalize wasting a last-chance bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress);
    }

    // Prefer bins with residual near mean (balanced usage)
    score += 0.2 * (pr - mean_residual).abs();

    // Lookahead: favor leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = fit_norm * cap - nxt;
        if gap >= 0.0 {
            score -= 8.0 * (gap / cap);
        } else {
            score += 4.0 * (-gap / cap);
        }
    }

    // Mild penalty for opening new bins early
    if bin_residual as f64 == cap {
        score += 5.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by common item sizes
    // (10, 20, 25, 50) are "clean" and reusable; odd residues are dead space.
    let pr = post_residual;
    if pr > 0 {
        if pr % 50 == 0 || pr % 25 == 0 || pr % 20 == 0 || pr % 10 == 0 {
            score -= 6.0; // clean residual, likely reusable
        } else if pr < 10 {
            score += 4.0 + (10 - pr) as f64; // tiny dead space
        } else if pr % 5 != 0 {
            score += 2.5; // awkward residue
        }
        // Integer-division threshold classes on post_residual
        let class = pr / 10; // 0..=9 decile class
        score += (class as f64) * 0.8;
        if class == 0 {
            score += 5.0; // near-full bin: waste is minimal, good to fill
        }
    } else {
        score -= 12.0; // perfect closure
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if (pr >= next_item_size) && pr > 0 {
            score -= 5.0; // residual serves the next item
            // Harmonic bonus: residual exactly matches next item class
            if pr == next_item_size { score -= 4.0; }
        } else if pr > 0 {
            // residual too small for next item: penalize more if residue is odd-classed
            if pr % 10 != 0 { score += 3.0; }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        score += 1.5 * (fitting_bins_count.saturating_sub(1)) as f64;
    }

    // New-bin candidate handling: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 30.0 };
        score = cap * 0.5 + pressure + 10.0 * progress
            - if next_item_size > 0 && next_item_size >= item_size { 3.0 } else { 0.0 };
    }

    // Mild preference to balance residuals across open bins
    score += 0.05 * ((post_residual as f64) - mean_residual).abs();

    // Tight-fit reward: item fills most of the bin
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.9 { score -= 4.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    // Penalize post_residuals in the "unusable" band (too small for typical items).
    let min_item = 1.0f64;
    let small_gap = (post_residual as f64) > 0.0 && (post_residual as f64) < 12.0;
    if small_gap {
        score += (12.0 - post_residual as f64) * 3.0;
    }
    // Zero residual is perfect.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward tight fits: fraction of bin consumed by this item.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * tightness;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize placements that keep many bins open with
    // scattered residuals; encourage consolidation into bins below mean residual.
    score += 0.5 * (open_bins_count as f64);
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if small_gap {
            score += 5.0; // dead space that even the next item cannot use
        }
    }

    // New-bin candidate: only attractive when nothing fits well or stream is early.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count == 0 || (post_residual as f64) > mean_residual {
            score -= 5.0; // allow opening when open bins are poor
        } else {
            score += 30.0; // discourage opening when decent fits exist
        }
    }

    // Mild stream-progression calibration: late in stream, be more conservative
    // about waste since fewer items remain to fill gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }

    // Bin cannot host the next item: penalize dead space relative to next_item_size.
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += 0.6 * waste;
        // Extra penalty if the leftover is tiny and unusable.
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // Bin can host both current and next item: strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.4 * (post_residual as f64 - next_item_size as f64).min(20.0);
    }

    // Compare against mean residual: bins tighter than average are more precious.
    let rel = post_residual as f64 - mean_residual;
    score += 0.3 * rel;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: mild penalty so we prefer existing bins with good fits,
    // but allow opening a new bin when all fits are poor (post_residual large).
    if bin_residual == bin_capacity {
        score += 12.0;
        // If this "fit" leaves a huge residual, opening a fresh bin is attractive.
        if post_residual > 60 {
            score -= 20.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer filling bins with more open bins (consolidation pressure).
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small dead space), with a non-linear squash.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Extra reward if post_residual is a snug match for the next item.
        let snug = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        score -= 6.0 * (1.0 - snug);
    } else if next_item_size > 0 {
        // Penalize leaving space the next item cannot use.
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: discourage opening a new bin unless current fit is bad.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 20.0;
        // Allow new bins more readily early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // If many bins are open and mean residual is large, prefer reusing.
        score += 0.3 * open_bins_count as f64 + 0.05 * mean_residual;
    }

    // Penalize creating tiny unusable fragments (< smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Mild preference for fuller bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (item_size as f64 / bin_capacity as f64);

    // Penalize bins that deviate from the mean residual (consolidation pressure).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = x * (1.0 + 0.8 * progress + 0.6 * progress * progress);

    // Penalize large wasted residual more strongly as stream progresses
    score += 1.5 * x * x * (0.5 + progress);

    // Reward tight fits (small post_residual) smoothly
    score -= 0.9 * (1.0 - x) * (1.0 - x) * (1.0 + 0.7 * progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 2.0 * (1.0 - x);
    }

    // Lookahead: reward residual that can fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fits_next = if pr as u32 >= next_item_size { 1.0 } else { 0.0 };
        score -= 0.8 * fits_next * nx * (1.0 - x);
        // Penalize residual that is just barely unusable for next item
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 0.6 * gap * (1.0 - fits_next) * (1.0 - progress);
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    let mr = mean_residual / cap;
    score += 0.4 * (x - mr) * (x - mr).signum() * (x - mr).abs().sqrt().max(0.0);

    // New-bin candidate: penalize mildly so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 1.2 + 0.5 * progress;
    }

    // Slight penalty for many open bins to encourage consolidation
    score += 0.02 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions
    let post_frac = post_residual as f64 / cap;
    let class = (post_frac * 10.0).floor() as i32; // 0..10 decile classes

    // Penalize dead-space classes that are hard to fill (small odd residuals)
    let dead_penalty = match class {
        0 => 0.0,               // perfect fit — ideal
        1 => 8.0,               // 1-10 residual: nearly unusable
        2 => 5.0,
        3 => 3.0,
        4 => 1.5,
        5 => 0.5,               // ~50 residual: half-bin, still reusable
        6 => 1.0,
        7 => 2.0,
        8 => 3.5,
        9 => 4.5,
        _ => 0.0,               // full residual (new bin)
    };
    score += dead_penalty;

    // Lookahead harmony: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use this residual: penalize proportionally to wasted harmony
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive late in stream or when many bins open
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = (open_bins_count as f64).ln().max(0.0);
        score += 20.0 - 6.0 * progress - 2.0 * crowding;
        // small item into fresh bin wastes it; penalize
        score += 0.15 * item_size as f64;
    }

    // Coupling with mean residual: prefer bins whose residual is below mean (tighter bins)
    score += 0.5 * (mean_residual - bin_residual as f64).abs().signum()
        * (mean_residual - bin_residual as f64).abs().min(20.0);

    // Small non-linear tie-breaker on item/binary class of item_size
    let item_class = item_size / 20; // 0..4 harmonic classes of item size
    score -= match item_class {
        0 => 1.0,   // tiny items fit almost anywhere; slight preference for tight bins
        1 => 0.0,
        2 => 0.5,
        3 => 1.0,
        _ => 1.5,   // big items: prioritize good fit more
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (gaps below the minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the gap -> dead space likely.
        score += 10.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin (penalize the new-bin candidate implicitly by
    // discounting this bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize the brand-new empty bin candidate, scaled by how many open bins
    // could still fit the item and current open-bin pressure.
    if bin_residual == bin_capacity {
        score += 35.0 + 3.0 * fitting_bins_count as f64;
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
    }

    // Mild pressure to consolidate into bins below the mean residual (denser bins).
    if bin_residual != bin_capacity && (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Prefer filling tighter bins overall (small residual before placement).
    score += 0.1 * (bin_residual as f64 - post_residual as f64) * 0.0; // no-op guard
    score += 0.05 * bin_residual as f64 * 0.0; // keep base semantics

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward post_residual that exactly matches next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as u32 == next_item_size {
            score -= 500.0; // chain: next item fills this bin perfectly
        } else if (post_residual as f64) < nxt {
            // dead space relative to lookahead: penalize proportionally
            score += (nxt - post_residual as f64) * 1.5;
        } else {
            // next item fits: reward tightness of fit
            score -= 100.0 / (1.0 + diff);
        }
        // also reward post_residual that leaves room for item + a small margin
        if post_residual as f64 >= nxt && post_residual as f64 <= nxt * 1.5 {
            score -= 80.0;
        }
    }

    // Compare against mean residual: prefer bins whose new residual is below mean
    // (concentrate waste into fewer bins).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when open bins exist and item fits reasonably.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 300.0 * (1.0 - 0.5 * progress);
            if next_item_size > 0 && (next_item_size as f64) <= (bin_capacity - item_size) as f64 {
                score += 100.0; // new bin would be fine for lookahead, but prefer reuse
            }
        } else {
            score -= 50.0; // no bins yet: new bin is fine
        }
    }

    // Small reward for tighter fits generally.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: prefer it only late in the stream or when open-bin fits are terrible.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty so new bins are used only when justified.
        score += 12.0;
        // Late in stream, opening a fresh bin is cheaper than fragmenting.
        score -= 10.0 * progress;
        // If many bins already fit the item, opening new is wasteful.
        score += 8.0 * (fitting_bins_count as f64).min(5.0);
        // If mean residual is small (bins nearly full), new bin is attractive.
        score -= (mean_residual / bin_capacity as f64).max(0.0) * 6.0;
        // Lookahead: new empty bin always fits next item.
        if next_item_size > 0 {
            score -= 3.0;
        }
        return score;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Dead-space penalty: residual too small for any plausible item (>=1..100).
    if post_residual > 0 {
        // Residual below the smallest possible next-item threshold is waste.
        let waste = if post_residual < 10 { post_residual as f64 * 2.0 } else { 0.0 };
        score += waste;
    }

    // Lookahead coupling: reward if next item fits the post residual exactly or well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
            if next_item_size == post_residual {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here: slight penalty for blocking the lookahead.
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Tightness reward: prefer bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 5.0 * fill_ratio;

    // Global state: with many open bins, prefer consolidating into existing space.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins whose residual is close to the item (minimize leftover).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.02 * gap;

    // Mean residual coupling: bins deviating from mean residual are less attractive.
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // Time horizon: early in stream, keep bins flexible (avoid tiny residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 20 {
        score += (1.0 - progress) * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, scaled by stream progress (later items weigh dead space more)
    let mut score = pr * (0.7 + 0.6 * t);

    // Non-linear polynomial coupling of post_residual with progress
    score += cap * (norm_pr * norm_pr) * (1.0 + t) * 0.5;
    score -= cap * (norm_pr * norm_pr * norm_pr) * t * 0.3;

    // Reward tight fits: quadratic in item fill ratio
    let fill = item_size as f64 / cap;
    score -= (fill * fill) * cap * (0.5 + 0.5 * t);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * t;
    }

    // Lookahead: reward residual that can host next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 5.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 8.0;
        }
    }

    // Penalize deviating far from mean residual (fragmentation signal)
    score += 0.15 * (pr - mean_residual).abs();

    // Mild penalty for too many open bins early on
    score += open_bins_count as f64 * t * 0.05;

    // New-bin candidate: make it attractive only when fits are poor
    if bin_residual == bin_capacity {
        score = cap * (1.0 - t) * 0.6 + pr;
        if fitting_bins_count > 1 {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fractions via integer division.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Class 1: post_residual in [0, eighth] -> excellent fill, strong reward.
    if post_residual <= eighth {
        score -= 40.0 + 3.0 * (eighth - post_residual) as f64;
    }
    // Class 2: (eighth, quarter] -> good fill, moderate reward.
    else if post_residual <= quarter {
        score -= 18.0;
    }
    // Class 3: (quarter, half) -> mediocre; penalize proportionally.
    else if post_residual < bin_capacity / 2 {
        score += 0.25 * (post_residual - quarter) as f64;
    }
    // Class 4: [half, capacity) -> large dead space, heavy penalty.
    else {
        score += 0.6 * (post_residual - bin_capacity / 2) as f64;
    }

    // Modulo arithmetic on post_residual: small residues mod 10 pair well
    // with typical item sizes (multiples of 5/10).
    let class_mod = post_residual % 10;
    if class_mod == 0 {
        score -= 8.0;
    } else if class_mod <= 2 {
        score -= 4.0;
    } else if class_mod >= 7 {
        score += 3.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, huge reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward if next item leaves a small residue again
            if slack <= eighth as f64 {
                score -= 25.0 - 0.2 * slack;
            } else {
                score += 0.15 * slack;
            }
        } else {
            // next item won't fit here: mild penalty scaled by overshoot
            score += 0.1 * ((next_item_size - post_residual) as f64).min(30.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }
    // Many fitting bins: competition is high, prefer tight fits (already via post_residual).

    // New-bin candidate: only attractive when current bin would leave huge waste
    // and the stream is early (plenty of items remain to fill fresh bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_pressure = (pr - mean_residual).max(0.0);
        if waste_pressure > quarter as f64 && progress < 0.7 {
            score -= 20.0 + 0.3 * waste_pressure;
        } else {
            score += 25.0 + 50.0 * progress;
        }
    }

    // Bin congestion: discourage scattering when many bins are open.
    if open_bins_count > 8 {
        score += 0.5 * (open_bins_count as f64 - 8.0).min(20.0);
    }

    // Mean residual alignment: bins far from the mean residual are less flexible.
    let dev = (pr - mean_residual).abs();
    score += 0.1 * dev.min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + (post_residual - next_item_size) as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 3.0 + progress * 30.0;
    } else {
        score -= open_bins_count.min(10) as f64 * 0.5;
    }

    // Prefer bins with residual below mean residual (tighter bins get filled first).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer bins with small post_residual (tight fit).
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            score -= 25.0 * (1.0 - diff / bin_capacity as f64); // next item still fits, closer = better
        } else {
            // next item won't fit here: penalize wasted residual below smallest plausible item
            score += 8.0 + 0.35 * post_residual as f64;
        }
    }

    // Dead-space penalty: residual too small to ever be useful (min item size 1..100 unknown, use 10 as conservative floor).
    if post_residual < 10 {
        score += 20.0;
    }

    // Compare post_residual against mean residual across open bins: keep bins balanced.
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: if this is the only bin that can fit the item, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else {
        // More competing bins: slight penalty to prefer the best fit among many.
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate logic: opening a new bin is only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Quality of the best possible use of an open bin: how tightly would the item fit somewhere?
        let tightness_available = (bin_residual - item_size) as f64; // residual in new bin after placement
        // Penalize opening a new bin, more so early on and when many bins already fit the item.
        let mut new_bin_penalty = 45.0 + 0.6 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            new_bin_penalty += 30.0;
        }
        // Late in the stream, avoid proliferating bins.
        new_bin_penalty += 25.0 * progress;
        // Exception: if next item is huge and would pair with this item, new bin can be good.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual + item_size >= 90 {
            new_bin_penalty -= 40.0;
        }
        score += new_bin_penalty;
        // Keep the raw residual component for the new bin (it equals capacity - item).
        score += tightness_available * 0.2;
    }

    // Mild preference to consolidate into fewer bins when many are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream completed — dynamic time horizon.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward low post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Dead-space penalty: residual too small for typical future items (sizes >= 1).
    // Penalize residuals that no plausible item would use well.
    let dead_zone = (12.0 - post_residual as f64).max(0.0);
    score += 3.5 * dead_zone;

    // Lookahead coupling: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 70.0; // chain fit: perfect follow-up
        } else if gap > 0 && gap < 15 {
            score -= 30.0; // near-chain fit
        } else if gap < 0 {
            // next item won't fit here; mild penalty scaled by wasted potential
            score += 0.4 * (-gap) as f64;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Many open bins with high mean residual: encourage consolidation into fuller bins.
    let mean_tight = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    if bin_residual != bin_capacity {
        score -= 20.0 * mean_tight * (open_bins_count as f64).ln().max(1.0);
    }

    // New-bin candidate logic: early in the stream, opening bins is cheap and flexible;
    // late in the stream, prefer squeezing into existing bins.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity >= item_size;
    if is_new_bin {
        let flexibility_bonus = (1.0 - progress) * 30.0;
        score = 100.0 - flexibility_bonus
            + 0.5 * open_bins_count as f64
            + progress * 40.0;
        // If the only fitting bin exists, don't open a new bin unless fit is terrible.
        if fitting_bins_count >= 1 {
            score += 25.0;
        }
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 10.0; // fresh bin can host next item too
        }
    }

    // Slight preference for bins whose residual is close to item_size (minimal waste ratio).
    if bin_residual >= item_size {
        let waste_ratio = post_residual as f64 / bin_residual as f64;
        score += 15.0 * waste_ratio;
    }

    // Mild noise-free exploration term: quadratic in progress to shift strategy mid-stream.
    score += 8.0 * (2.0 * progress - 1.0) * (2.0 * progress - 1.0) * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted post-residual with non-linear (quadratic) coupling
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Stream-progress coupling: later in stream, tolerate larger residuals less (dead space matters more)
    score *= 1.0 + 0.8 * progress * norm_pr;

    // Reward tight fits: smooth bonus decaying with post_residual
    score -= 12.0 * (1.0 - norm_pr).powi(3);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Crowding: many open bins with low mean residual -> prefer compacting
    let mean_norm = mean_residual / cap;
    score += 10.0 * (open_bins_count as f64).sqrt() * mean_norm * norm_pr;

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && (next_item_size as f64 - pr).abs() < 1e-9 {
        score -= 30.0;
    } else if next_item_size > 0 {
        // penalize if next item cannot use the post residual
        let waste = (pr - next_item_size as f64).max(0.0) / cap;
        score += 20.0 * waste * waste * cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: group residuals into capacity fractions.
    // Classes (fraction of capacity): [0..10] excellent, (10..25] good, (25..50] fair, >50 poor.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    if post_residual <= bin_capacity / 10 {
        score -= 40.0;
    } else if post_residual <= bin_capacity / 4 {
        score -= 15.0;
    } else if post_residual > bin_capacity / 2 {
        score += 25.0; // wasted more than half a bin's remaining space
    }

    // Modulo-10 dead-space band: residuals like 1..9 are nearly unusable
    // (items are >=1 but often larger); small odd residues are dead space.
    if post_residual < 10 && post_residual > 0 {
        score += 30.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it fills the remainder
            let fill = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 30.0 * fill;
        } else {
            // next item won't fit here regardless; slight penalty scaled by overflow
            let over = (next_item_size - post_residual) as f64;
            score += (over / cap) * 20.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate handling: an empty bin has maximal residual.
    // Only prefer opening a new bin when all open fits are poor and the item is large.
    if bin_residual == bin_capacity {
        let poor_fits = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let item_frac = item_size as f64 / cap;
        // Reward opening a new bin for large items early in the stream or when
        // existing bins fit poorly.
        score -= 60.0 * item_frac + 50.0 * poor_fits;
        // Penalize new bins when many bins are already open and mean residual is high.
        score += (open_bins_count as f64) * 2.0 + (mean_residual / cap) * 30.0;
    }

    // Mild stream-progression term: late in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in a small unusable gap is heavily penalized.
    if post_residual > 0 {
        let dead = (post_residual as f64) / bin_capacity as f64;
        if post_residual < 10 {
            score += 60.0 * (1.0 - dead); // tiny unusable sliver -> strong penalty
        } else {
            score -= 8.0 * dead; // larger leftover space is reusable -> mild reward
        }
    } else {
        score -= 40.0; // perfect fit is excellent
    }

    // Reward tight fills relative to current residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: prefer compacting into few bins.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Baseline new-bin cost grows with number of open bins.
        score += 30.0 + 1.5 * open_bins_count as f64;
        // If next item is large and this item is small, opening fresh may be better.
        if next_item_size > 60 && item_size < 30 {
            score -= 20.0;
        }
        // Late in the stream, discourage opening extra bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 18.0;
        } else {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: tiny post_residual is excellent.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: reward when the NEXT item exactly
    // fills this bin's post_residual (a perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            // Next item fits here afterwards: mildly good, tighter is better.
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item would NOT fit in the leftover: penalize big leftovers.
            let over = (next_item_size - post_residual) as f64;
            score += 0.4 * over.min(60.0);
        }
    }

    // Compare post_residual against the mean residual of open bins:
    // leaving less than average is good (tight packing).
    let pr = post_residual as f64;
    score += 0.3 * (pr - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly favor
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // With multiple options, prefer the tightest fit (already via
        // post_residual), but dampen differences slightly.
        score -= 5.0;
    }

    // Penalize opening a brand-new bin when decent fits exist.
    if bin_residual == bin_capacity {
        let urgency = if next_item_size > 0 && next_item_size > item_size {
            0.5
        } else {
            0.0
        };
        score += 18.0 + urgency * 10.0;
        // Early in the stream, opening bins is cheaper; late, avoid sprawl.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0 * progress;
    }

    // Mild penalty for leaving residuals in awkward mid-range zones
    // (hard to fill later, since items are 1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if is_new_bin {
        // Opening a new bin is costly: large base penalty.
        score += 40.0;
        // If the item fills the new bin tightly, opening is attractive.
        if post_residual <= 5 {
            score -= 60.0;
        }
        // Late in the stream, avoid spreading into new bins if any fit exists.
        score += progress * 20.0;
        // If this bin is the only fitting option elsewhere is impossible... but for a
        // new bin, fitting_bins_count reflects open bins that fit; if >0, discourage.
        if fitting_bins_count > 0 {
            score += 15.0 * fitting_bins_count as f64;
        }
        // If the next item would fit perfectly in the leftover of this new bin, encourage.
        if next_item_size > 0 && post_residual as i64 - next_item_size as i64 == 0 {
            score -= 30.0;
        }
    } else {
        // Reward tight fits in existing bins.
        if post_residual == 0 {
            score -= 50.0;
        } else if post_residual <= 10 {
            score -= 20.0;
        }

        // Last-chance bonus: this is the only bin that fits the item.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }

        // Penalize leaving dead space that no plausible item (>=1) can use well:
        // small post_residual is good, but mid-range waste (11..30) is bad.
        if post_residual > 10 && post_residual < 40 {
            score += (post_residual as f64) * 0.6;
        }

        // Lookahead: if the next item fits exactly into the post residual, reward strongly.
        if next_item_size > 0 {
            let diff = post_residual as i64 - next_item_size as i64;
            if diff == 0 {
                score -= 35.0;
            } else if diff > 0 && diff <= 10 {
                score -= 12.0;
            } else if diff < 0 {
                // Next item won't fit here; slight penalty for blocking chain.
                score += 5.0;
            }
        }

        // Prefer bins with below-average residual (tighter bins) to consolidate waste.
        let bin_res_f = bin_residual as f64;
        if mean_residual > 0.0 {
            score += (bin_res_f - mean_residual) * 0.3;
        }

        // Many open bins: encourage closing them out (reward filling fuller bins).
        if open_bins_count > 4 {
            score -= bin_res_f * 0.15;
        }

        // Early in stream, be slightly more willing to use roomy bins; late, pack tight.
        score += progress * (post_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, waste is cheap; later, waste is heavily penalized.
    let waste_penalty = 8.0 * norm_pr * norm_pr * (0.5 + progress);
    score += waste_penalty;

    // Reward tight fits with a smooth saturating term.
    let fit_bonus = 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= fit_bonus;

    // Last-chance bin: smooth reward scaled by how scarce fitting options are.
    if fitting_bins_count == 1 {
        score -= 10.0 + 15.0 * progress;
    }

    // Penalize bins far from the mean residual (fragmentation pressure), smoothly.
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Lookahead: smooth reward if next item fits the post-residual.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64) / cap;
        if gap >= 0.0 {
            score -= 8.0 * gap * (1.0 - gap.abs());
        } else {
            score += 4.0 * gap * gap * cap;
        }
    }

    // New-bin candidate: mildly penalize early, reward late via smooth interaction.
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - 2.0 * progress) * (1.0 - 2.0 * progress);
    }

    // Mild load-balancing pressure on number of open bins.
    score += 0.05 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: capacity split into 8ths.
    // Residuals in low classes (small leftovers) are "dead space" -> penalize slightly
    // via class-aware bonus for high classes only.
    let class = post_residual / (bin_capacity / 8).max(1);
    let class_reward: f64 = match class {
        0 => 0.0,                                  // 0: perfect fit, keep base 0
        1 => -14.0,                                // tiny leftover, very usable? no: tiny = dead
        2 => -6.0,
        3 => -2.0,
        4 => -4.0,                                 // half-empty bin is flexible
        5 => -5.0,
        6 => -8.0,
        _ => -12.0,                                // nearly full bin left: excellent packing
    };
    // Interpretation: we subtract more for classes where leftover is likely reusable.
    // class 0 (perfect) already has score 0; class 7 (leftover ~<=12) is tight but fine.
    // class 1 (leftover 13-25) is awkward: penalize instead.
    let class_penalty: f64 = match class {
        1 => 9.0,                                  // awkward dead zone
        2 => 3.0,
        _ => 0.0,
    };
    score += class_penalty - class_reward * 0.0; // class_reward folded below via fit logic

    // Lookahead: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic pairing: how well does next item divide the leftover?
            let rem2 = post_residual % next_item_size.max(1);
            let pair_quality = if rem2 == 0 {
                -25.0                              // perfect harmonic pair
            } else if rem2 <= 5 {
                -18.0
            } else {
                -8.0
            };
            score += pair_quality;
        } else {
            // Next item won't fit here: this bin becomes dead after placement.
            score += 20.0;
        }
    } else {
        // Last item of stream: prefer filling as tightly as possible.
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it moderately expensive unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if item is huge relative to capacity, opening fresh is fine.
        if item_size * 2 >= bin_capacity {
            score -= 15.0;
        }
        // Late in the stream with many open bins: consolidation preferred, keep new bin costly.
        if open_bins_count > 4 {
            score += 10.0;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (tighter than average).
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // Small exact-fit bonus via modulo arithmetic on post_residual vs capacity classes.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual % 10 == 0 {
        score -= 6.0; // round residual, easy to fill with standard items
    }

    // Progress-aware tightening: later in stream, prioritize tight fits more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.25 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill
    }

    // Reward filling a bin that was already fairly full (good consolidation).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: with many open bins, prefer reusing existing space.
    score += 6.0 * open_bins_count as f64;

    // Mean residual coupling: if average residual is small, waste is costlier.
    score += 0.35 * (mean_residual - post_residual as f64).abs();

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when the item is large
    // relative to remaining space or no good reuse exists.
    if bin_residual == bin_capacity {
        score += 45.0;
        if item_size >= 60 {
            score -= 50.0; // big items are fine in a fresh bin
        }
        if post_residual < 10 {
            score += 40.0; // don't open a bin just to strand dead space
        }
    }

    // Lookahead: if next item fits the post-residual exactly, bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly matches
    // or tightly accommodates the next item size.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = post - nxt;
            // Reward tight fits for the next item: slack near 0 is best.
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
            // Perfect match bonus
            if post_residual == next_item_size {
                score -= 40.0;
            } else if slack <= 5.0 {
                score -= 15.0;
            }
        } else {
            // Next item won't fit here: penalize leaving fragmented space.
            let gap = nxt - post;
            score += 8.0 + 0.5 * gap;
        }
    }

    // Compare post_residual against mean residual: leaving less than average
    // waste is good (tight packing), leaving more is bad.
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.3 * mean_gap;

    // Penalize large unusable dead space (below typical minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score -= 10.0; // small residue often still usable with 1..100 items
    }
    if post_residual > 50 {
        score += 0.2 * (post_residual as f64 - 50.0); // wasteful large leftover
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are
    // nearly full or the item is huge and fits nothing well.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        score += 30.0 * avg_fill;
        if item_size > 70 {
            score -= 10.0; // big items may justify fresh bins
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0; // fresh bin can also host next item
        }
    }

    // Late in the stream, consolidate: prefer tighter bins to close them out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Fractional waste: penalize leaving dead space proportionally.
    score += 1.5 * (post / cap) * (post / cap) * cap;

    // Perfect or near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item could fit into the post-residual,
    // reward this placement (keeps a useful residual for the future).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 6.0 * (1.0 - nxt / cap);
        } else {
            // Post-residual too small for next item: penalize dead space more.
            score += 4.0 * (post / cap);
        }
        // If next item fits exactly in post residual, big reward.
        if (next_item_size as u32) == post_residual as u32 {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, emphasize tightness competition.
        score += 0.5 * (fitting_bins_count as f64).ln();
    }

    // Global state: many open bins with large mean residual -> prefer
    // filling existing bins rather than opening new ones.
    if bin_residual < bin_capacity {
        score -= 0.3 * mean_residual;
    }

    // Time horizon: late in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post / cap);

    // New-bin candidate handling: neutral baseline, slightly penalized so
    // that only genuinely poor fits in all open bins trigger a new bin.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + 0.2 * mean_residual - 8.0 * progress;
        if next_item_size > 0 && (next_item_size as f64) > cap - item {
            score -= 5.0; // next item won't fit here anyway; fine to open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: prefer tight fit (small post residual), smooth polynomial shaping
    let mut score = pr / cap;

    // Smooth non-linear coupling: as stream progresses, tighten preference for small residuals
    let tightness = pr / cap;
    score += 0.6 * tightness * tightness * (0.5 + progress);
    score -= 0.35 * (1.0 - progress) * (1.0 - tightness);

    // Penalize dead space relative to mean residual across open bins
    let dead = (pr - mean_residual) / cap;
    score += 0.25 * dead * dead.abs();

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 0.45 * (1.0 - pr / cap) * (nx / cap);
        } else {
            score += 0.30 * (nx / cap) * (1.0 + progress);
        }
    }

    // Last-chance bonus: only this bin fits the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 0.9;
    }

    // New-bin candidate: penalize opening a new bin early, allow it late or for large items
    if bin_residual == bin_capacity {
        score += 1.2 * (1.0 - progress) - 0.3 * (it / cap);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 0.2;
        }
        // Smoothly relax new-bin penalty as number of open bins grows
        score -= 0.05 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mild preference for fuller bins overall
    score -= 0.15 * (1.0 - bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "usable" residue classes (divisible by common item granularities)
    // are more likely to accept future items.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        // Perfect fill is ideal
        -60.0
    } else if pr <= 10 {
        // Tiny dead space, nearly useless
        25.0
    } else if pr % 10 == 0 {
        -15.0
    } else if pr % 5 == 0 {
        -8.0
    } else if pr % 2 == 0 {
        -3.0
    } else {
        6.0
    };
    score += class_bonus;

    // Integer division thresholds on post_residual
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if pr >= half {
        score -= 10.0; // leaves a half-capacity slot, very reusable
    } else if pr >= quarter {
        score -= 4.0;
    } else if pr < 15 {
        score += 12.0; // high risk of dead space
    }

    // Coupling with next item (lookahead k=2)
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits perfectly in this bin's leftover
            let exact = (pr - next_item_size) as f64;
            score -= 20.0 - 0.2 * exact;
            if pr == next_item_size {
                score -= 25.0; // chain of perfect fills
            }
        } else if next_item_size <= bin_residual && next_item_size > pr {
            // Next item fits the bin now but not after this placement
            score += 10.0;
        }
        // Harmonic compatibility: gcd-like class match between leftover and next item
        let g = gcd(pr, next_item_size);
        if g > 1 {
            score -= 2.0 * (g as f64).ln();
        }
    } else {
        // Last item: prefer zero waste
        score += 5.0 * pr as f64 / bin_capacity as f64;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    // Penalize opening a new bin unless current placement would leave
    // severe dead space in an existing bin.
    if bin_residual == bin_capacity {
        score += 20.0;
        if open_bins_count == 0 {
            score -= 40.0; // must open first bin
        }
    } else if post_residual < 10 && bin_residual >= 10 {
        // This placement creates near-unusable sliver: consider new bin instead
        score -= 5.0;
    }

    // Progression-based scaling: late in the stream, consolidate aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * progress;

    // Mean residual context: if open bins are already loose, prefer filling them
    if mean_residual > (bin_capacity as f64) * 0.5 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    score
}

fn gcd(a: u32, b: u32) -> u32 {
    if b == 0 { a } else { gcd(b, a % b) }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever fit a future
    // item (min size 1, but practically small gaps) are wasted capacity.
    // Penalize small non-zero post_residuals heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }

    // Reward tight fits (post_residual near zero or large enough to be reusable).
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual >= 10 {
        score -= 8.0;
    }

    // Perfect-fit bonus: bin_residual exactly equals item_size.
    if post_residual == 0 && bin_residual == item_size {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    }
    // If next item cannot fit in the post residual, penalize slightly (dead gap).
    else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    // Open-bins pressure: penalize placements into bins when many bins are open
    // and this bin is not the only option; encourage closing bins out.
    if fitting_bins_count > 1 {
        score += 2.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when current fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 15.0;
        // Extra cost when many bins are already open (avoid bin proliferation).
        score += 3.0 * open_bins_count as f64;
        // But if mean residual across open bins is very small (bins nearly full),
        // opening a new bin is natural; reduce the penalty.
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    }

    // Mild progression term: later in the stream, prefer tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Stream progression (0 -> 1)
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let nxt = next_item_size as f64;
    let has_next = next_item_size > 0;

    // ---- Aggressive 2-step lookahead matching ----
    if has_next {
        if post == nxt {
            // Perfect match: the next item exactly fills this bin -> zero future waste.
            // Reward grows with the size of the next item (large items are harder to place).
            let size_w = 0.7 + 0.6 * (nxt / cap);
            score -= cap * (1.1 - 0.4 * progress) * size_w;
        } else if post > nxt {
            // Chainable: next item still fits here; reward tightness of the chain
            // (small leftover gap after the next placement), scaled by how hard
            // the current item was to place.
            let gap = post - nxt;
            let hard_w = 0.8 + 0.4 * (item_size as f64 / cap);
            score -= 0.4 * (cap - gap) * hard_w;
        } else {
            // Dead for the next step: next item cannot use the leftover.
            // Penalize the mismatch; urgency rises as the stream progresses
            // (less time left to recycle small fragments).
            let dead = nxt - post;
            let urgency = 0.6 + 0.4 * progress;
            score += 0.6 * dead * urgency;
        }
    }

    // ---- Last-chance consolidation ----
    if !is_new_bin && fitting_bins_count == 1 {
        // This is the only open bin that fits: strongly prefer it over opening a new bin.
        score -= cap * 0.35;
    }
    if is_new_bin && fitting_bins_count == 0 {
        // No open bin fits at all: the new bin is forced, make it win outright.
        score -= cap * 2.0;
    }

    if is_new_bin {
        // Adaptive new-bin penalty: high mean residual (open bins still roomy)
        // -> strongly discourage opening a new bin; low mean residual (open bins
        // nearly full) -> new bin becomes competitive.
        let adapt = (mean_residual / cap).clamp(0.0, 1.0);
        score += cap * (0.25 + 0.65 * adapt);
        // Mild extra pressure when many bins are already open (consolidation).
        score += (0.05 * open_bins_count as f64).min(15.0);
    } else {
        // Favor fuller-than-average bins (residual below the mean) to pack tightly.
        let dev = mean_residual - bin_residual as f64;
        score -= 0.15 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress horizon: early in the stream, keep bins flexible; late, fill tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Reward tight fits (small post_residual) more strongly as stream advances.
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0 + 2.0 * progress) * 20.0;

    // Penalize dead space that cannot fit even a minimum item (1).
    if post_residual < 1 {
        score -= 100.0; // perfect fill, extremely desirable
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin, unless post_residual would be huge.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 - 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: opening a new bin is attractive only when
    // the item is large relative to capacity or the open bins are crowded/poor.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let large_item = item_size as f64 / bin_capacity as f64;
        // Base penalty: prefer existing bins by default.
        let mut new_bin_penalty = 12.0;
        // If item is large and open bins are fragmented, opening is cheaper.
        new_bin_penalty -= large_item * 18.0;
        new_bin_penalty -= (crowding - 0.5).max(0.0) * 15.0;
        // Late in the stream, closing out tightly is better than new bins.
        new_bin_penalty += progress * 10.0;
        // If many bins already fit the item, opening is wasteful.
        if fitting_bins_count > 2 {
            new_bin_penalty += 8.0;
        }
        score += new_bin_penalty;
    }

    // Lookahead: if the next item fits the post-residual well, reward this placement.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap >= 0 {
            score -= 6.0 * (1.0 - (gap as f64 / bin_capacity as f64));
        } else {
            // Next item won't fit here; slight penalty scaled by waste.
            score += (-gap as f64).min(bin_capacity as f64) * 0.05;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (consolidation).
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.03;

    // Mild bonus for using many open bins efficiently (keep bin count stable).
    score -= (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: reward tight fits (low post residual), with quadratic decay
    let mut score = norm_post + 0.6 * norm_post * norm_post;

    // Non-linear coupling of post residual with stream progress:
    // late in stream, dead space becomes more costly
    let progress_coupling = 2.0 * progress * norm_post * (1.0 - norm_post);
    score -= progress_coupling;

    // Penalize bins whose residual deviates strongly from the mean residual
    let mean_norm = mean_residual / cap;
    let dev = (norm_post - mean_norm).abs();
    score += 0.4 * dev * dev * (1.0 - progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 3.0;
    }

    // Lookahead: if next item fits exactly in post residual, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            score -= 0.8 * (1.0 - slack) * (1.0 - progress);
        } else {
            score += 0.3 * (nxt - post) / cap;
        }
    }

    // Slight preference for consolidating into fewer bins
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * norm_post;

    // New-bin candidate: mildly discourage unless current bins are full
    if bin_residual == bin_capacity {
        score += 0.5 + 0.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" is the leftover space.
    // Class 0: residual divisible by 10 (clean slot), class 1: 5-multiple, else ragged.
    let class10 = (post_residual % 10 == 0) as i32;
    let class5 = (post_residual % 5 == 0) as i32;
    score -= 6.0 * class10 as f64;
    score -= 2.0 * class5 as f64;

    // Dead-space penalty: leftover that no future item (min size 1, typical >= 10) can use.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: does the leftover form a usable harmonic slot for the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // The next item can follow in this bin: strong reward, scaled by tightness.
            let tight = (post_residual - next_item_size) as f64;
            score -= 12.0 + 10.0 * (1.0 - tight / bin_capacity as f64);
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 6.0; // chain of clean 10-multiple slots
            }
        } else {
            // Next item won't fit here; penalize leaving a slot that tempts but fails.
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when the item is large relative to
    // capacity or open bins are heavily fragmented (low mean residual).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        score -= 18.0 * progress + 15.0 * (1.0 - fragmentation);
        // Prefer new bin for large items that would shred a small residual.
        if item_size > 60 {
            score -= 10.0;
        }
    }

    // Prefer filling bins that are already relatively full (small residual before placement).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Dead-space threshold: gaps too small for typical items are waste.
        let dead_threshold = 10.0f64;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 12.0;
        }
        // Non-linear penalty for awkward mid-range gaps that few items fit.
        let awkward = (post_residual as f64).powf(1.4);
        score += awkward * 0.15;
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward exact or near-exact matches to the lookahead item.
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            score -= 35.0; // next item fits exactly afterwards
        } else if diff > 0 && diff < 10 {
            score -= 12.0;
        } else if diff < 0 && (-diff) as u32 <= post_residual {
            // next item cannot fit: dead space locked in
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize placements when many bins are open,
    // encouraging consolidation; relax near stream end.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 - 0.5 * progress);
    score += pressure * 0.6;

    // Prefer bins whose residual deviates from the mean in a controllable way:
    // filling a large-residual bin is cheap; filling a tight bin wastes structure.
    if (bin_residual as f64) < mean_residual {
        score += (mean_residual - bin_residual as f64) * 0.3;
    } else {
        score -= (bin_residual as f64 - mean_residual) * 0.1;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Mild penalty so we prefer open bins unless fit is terrible elsewhere;
        // becomes attractive when post_residual elsewhere would be dead space.
        score += 15.0;
        if item_size >= 60 {
            // Large items start fresh bins cleanly to preserve small-bin flexibility.
            score -= 20.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals the next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small leftover.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Penalize dead space that cannot fit the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Reward tight fits relative to current item.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Penalize bins whose residual deviates strongly from the mean (fragmentation).
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 95.0 + 20.0 * (1.0 - progress);
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // pair fits nicely in a fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space that no future item can plausibly fill.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0 * (post_residual as f64) / (next_item_size as f64);
        }
        // Reward bins whose leftover exactly accommodates the next item.
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual >= next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: just minimize waste.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0 + 0.1 * item_size as f64;
    }

    // Tight-fit reward: near-exact fills are excellent.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Prefer bins already below mean residual (consolidate emptier space usage),
    // but mildly penalize opening new bins when several bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of opening a bin, modulated by stream phase.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_cost = 25.0 + 10.0 * (1.0 - progress);
        // If item leaves a large hole and open bins exist, opening fresh may be fine.
        if post_residual > bin_capacity / 2 && open_bins_count > 0 {
            new_bin_cost -= 5.0;
        }
        // If next item would fit perfectly in a fresh bin after this placement,
        // opening a new bin is attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_cost -= 6.0;
        }
        score += new_bin_cost;
    } else {
        score += 0.05 * (mean_residual - bin_residual as f64);
        // Mild congestion penalty: many open bins -> favor filling existing ones.
        score -= 0.3 * open_bins_count as f64;
    }

    // Time-horizon coupling: early in stream, be conservative (leave room);
    // late in stream, pack aggressively.
    let phase = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * (1.0 - phase);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post_residual as f64 / bin_capacity as f64;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let t = progress * (1.0 - progress) * 4.0; // peaks mid-stream, 0 at ends
    score -= 6.0 * t * norm_post * (1.0 - norm_post);

    // Penalize large dead space more than linearly as stream advances
    score += 4.0 * progress * norm_post * norm_post;

    // Reward tight fits (small post residual) more strongly late in the stream
    score -= 3.0 * progress * (1.0 - norm_post);

    // Lookahead: reward bins whose post residual can fit the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 * (next_item_size as f64 / bin_capacity as f64) * (0.5 + 0.5 * progress);
    } else if next_item_size > 0 {
        score += 2.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - 0.5 * progress);
    }

    // Mild penalty for opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 3.0 + 0.15 * open_bins_count as f64;
    }

    // Coupling with mean residual: prefer bins near the mean residual (balance)
    let diff = (post_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 2.0 * diff * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // --- Harmonic class of post_residual (modulo 10 alignment) ---
    let m = (post_residual % 10) as f64;
    if m == 0.0 {
        // residual aligned with item granularity: highly reusable
        score -= 4.0;
    } else {
        // non-aligned residual: partial dead-space penalty
        score += m * 0.6;
    }

    // --- Dead-space classes ---
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;  // only fits tiny items
    }

    // --- Large reusable residual classes (half-capacity harmonic) ---
    if post_residual >= 50 {
        score -= 6.0; // can host any item from the stream
    } else if post_residual >= 30 {
        score -= 2.0;
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if (next_item_size as f64) <= post_residual as f64 {
            score -= 5.0;
            // harmonic bonus: next item exactly consumes residual classes
            if post_residual % next_item_size.max(1) == 0 {
                score -= 3.0;
            }
        } else {
            score += 3.0;
        }
    }

    // --- Last-chance bin before opening a new one ---
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 12.0;
    }

    // --- New-bin candidate handling ---
    if is_new_bin {
        // opening a new bin is attractive when existing bins are tight overall
        let tightness = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= tightness * 6.0;
        // discourage hoarding many open bins late in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (open_bins_count as f64) * 0.15 * (1.0 - progress);
        // if the next item would leave this fresh bin harmonically packed, favor it
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 2.0;
        }
    } else {
        // reward tight fits into existing bins
        let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= fill * fill * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that cannot fit typical future items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual >= 20 && post_residual < 35 {
        score += 8.0;
    }

    // Reward tight fits strongly (perfect fit is ideal).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Reward bins that can still host the lookahead item after placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize leaving a gap just below the next item's size (near-miss dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.35 * (next_item_size - post_residual) as f64;
    }

    // Last-chance pressure: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // with few open bins, allow spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 5.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open-bin pressure.
        score += 15.0 + 4.0 * pressure;
        // Opening a new bin is attractive only if no bin fits well (high mean residual waste).
        if mean_residual > 45.0 {
            score -= 10.0;
        }
    } else {
        // Favor reusing bins with smaller residuals relative to mean.
        score += 0.15 * (bin_residual as f64 - mean_residual);
        // Slight preference to fill fuller bins first (best-fit style).
        score += 0.05 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next_item_size exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }

    // Near-match: next item nearly fills the bin after this placement.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (-gap as f64 / 8.0).exp();
    }

    // Penalize creating dead space the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 30.0;
        // Extra penalty for very small unusable slivers.
        if post_residual < 10 {
            score += 25.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Many fitting bins: prefer the tightest fit beyond raw post_residual.
    if fitting_bins_count > 2 {
        score -= 5.0;
    }

    // Penalize placements far below the mean residual (wasting a roomy bin).
    if (post_residual as f64) < mean_residual - 20.0 {
        score += 10.0;
    }

    // Reward keeping residuals balanced with mean residual.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate: only attractive when no open bin fits well
    // (post_residual would equal a fresh bin's residual, i.e. bin_capacity - item_size).
    if bin_residual == bin_capacity {
        // Slight default penalty so open bins are preferred unless lookahead says otherwise.
        score += 15.0;
        if next_item_size > 0 && (bin_capacity - item_size) as i64 - next_item_size as i64 == 0 {
            score -= 250.0;
        }
        // Late in the stream, opening a fresh bin is more acceptable.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose post-residual is small but nonzero waste.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 2.5 * fit_ratio * (bin_residual as f64);

    // Penalize dead space that likely cannot be reused (post_residual too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward bins that can also host the next item after this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.05 * next_item_size as f64;
        } else {
            // Penalize creating a residual that neither fits next item nor is useful.
            score += 3.0;
        }
        // Perfect pairing: item + next item exactly fills bin.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // New-bin candidate handling: opening a bin is fine early or when no bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Prefer new bins when existing fits are poor (high mean residual waste) or few fitting bins.
        let poor_fits = mean_residual - item_size as f64;
        if poor_fits > 20.0 || fitting_bins_count == 0 {
            score -= 10.0;
        } else {
            score += 8.0 + 10.0 * progress;
        }
        // Late in the stream, avoid spawning bins with large leftover capacity expectations.
        score += 0.02 * (item_size as f64);
    }

    // Mild preference for fuller bins among many open bins (reduce fragmentation).
    score += 0.05 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Global balance: if mean residual is low, conserve space aggressively (favor exact fits more).
    let tightness = 1.0 - (mean_residual / cap);
    score -= 5.0 * tightness * fit_ratio;

    // Time horizon: early stream tolerates slack; late stream punishes large post residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_frac = post / cap;

    // Base: waste after placement, normalized.
    let mut score = fit_frac;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, tolerate larger residuals; later, punish waste more aggressively.
    let progress_sq = progress * progress;
    let progress_cu = progress_sq * progress;
    let waste_weight = 1.0 + 3.0 * progress_sq + 2.0 * progress_cu;
    score *= waste_weight;

    // Quadratic dead-space penalty: residuals too small to ever be useful
    // (below typical minimum item size) are heavily penalized.
    let min_item = 1.0f64;
    if fit_frac > 0.0 && fit_frac < (min_item / cap).max(0.0) {
        score += 10.0;
    }
    // Smooth penalty when residual is small but nonzero (unusable sliver).
    let sliver = (1.0 - fit_frac.min(1.0)) * (1.0 - fit_frac.min(1.0));
    score += 0.5 * sliver * fit_frac;

    // Reward tight fits: subtract for small post_residual relative to capacity.
    score -= 0.3 * (1.0 - fit_frac) * (1.0 - fit_frac);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 2.0 + 2.0 * progress;
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is fine early; penalize later to consolidate.
        let new_bin_penalty = 0.5 + 2.0 * progress + 1.5 * progress_sq;
        // If existing bins fit poorly (large post_residual elsewhere), new bin is OK:
        // compare against mean residual of open bins.
        let mean_fit = mean_residual / cap;
        let relief = (mean_fit - fit_frac).max(0.0);
        score = new_bin_penalty - 1.5 * relief;
        // If lookahead item fits nicely in the new post_residual, encourage opening.
        if next_item_size > 0 && (next_item_size as f64) <= post {
            let look_fit = 1.0 - (next_item_size as f64 / post);
            score -= 0.8 * look_fit;
        }
    } else {
        // Lookahead coupling: reward bins whose post_residual can host next item tightly.
        if next_item_size > 0 && (next_item_size as f64) <= post {
            let look_fit = (next_item_size as f64 / post).min(1.0);
            score -= 0.6 * look_fit * (1.0 + progress);
        } else if next_item_size > 0 {
            // Next item cannot use the leftover: mild penalty growing with progress.
            score += 0.4 * progress;
        }
        // Slight preference for bins with residuals close to mean (balanced packing).
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 0.1 * dev * dev;
    }

    // Mild scaling with open bins count: prefer filling existing bins when many are open.
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * fit_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = (bin_capacity / 4) as u32;
    let eighth = (bin_capacity / 8) as u32;

    // Perfect-fit harmony: zero post residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space classes: residuals in low harmonic bands are hard to fill.
    if post_residual > 0 && post_residual <= eighth {
        score -= 8.0; // small slivers still usable by tiny items
    } else if post_residual > eighth && post_residual < quarter {
        score += 12.0; // awkward dead zone
    }

    // Harmonic residue: reward residuals that are multiples of common item classes.
    let h = post_residual % (bin_capacity / 10).max(1);
    score -= (h as f64) * 0.3;

    // Lookahead coupling: if next item fits post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 + (post_residual - next_item_size) as f64 * 0.05;
    } else if next_item_size > 0 {
        // penalize wasted lookahead potential proportional to overshoot
        let overshoot = (next_item_size - post_residual) as f64;
        score += overshoot * 0.1;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // among multiple fits, prefer tighter packing via base residual term already
        score += 2.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 60.0;
        // But if no open bin can fit, opening is necessary: soften.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Late in stream, avoid opening new bins for small leftovers.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer bins with residual close to item size (tight fit).
    let tightness = (bin_residual - item_size) as f64 / cap;
    score += tightness * 25.0;

    // Mild preference to spread across bins when many are open.
    score += (open_bins_count as f64).ln() * 1.5;

    // Mean residual alignment: favor bins near mean residual for balanced harvesting.
    score -= ((pr - mean_residual).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item
    // (minimum item size is 1, but small gaps < ~15 are statistically hard to reuse)
    if post_residual < 15 {
        score += 60.0; // heavy penalty: near-unusable dead space
    } else if post_residual < 30 {
        score += 20.0;
    }

    // Reward exact-ish fits strongly
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits in this bin's post-residual, reward;
    // if next item is large and post_residual can't host it, penalize mildly.
    if next_item_size > 0 {
        if post_residual >= next_item_size as u32 {
            score -= 15.0;
        } else if post_residual > 0 && post_residual < next_item_size as u32 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer packing tight
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += pressure * 2.0;

    // New-bin candidate: prefer opening a new bin only when it's early in the stream
    // or the current fit is poor (large post_residual relative to capacity)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
        if post_residual as f64 > 0.6 * bin_capacity as f64 && open_bins_count > 0 {
            score -= 20.0; // poor fit elsewhere -> new bin is fine
        }
    }

    // Mild preference for bins with tighter residual (best-fit coupling)
    score += (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Near match: next item fits with little slack left afterwards.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_pair = post_residual - next_item_size;
        score -= 20.0 - 0.15 * slack_after_pair as f64;
    }
    // Next item cannot use this residual: penalize proportionally.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.3 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Penalize residuals far below mean residual (wasting space in a roomy bin
    // while other bins are tight is bad).
    score += 0.2 * (mean_residual - post_residual as f64).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (post_residual of a fresh bin is capacity - item_size, large).
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count > 0 {
            score += 10.0 * (fitting_bins_count as f64).min(5.0);
        }
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (open_bins_count as f64).recip().min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual is base; amplify penalty for mid-range waste.
    let waste_frac = post_residual as f64 / cap;
    score += 8.0 * waste_frac * (1.0 - waste_frac); // penalize half-empty leftovers

    // Perfect-fit bonus
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 20.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // dead space for the known next item
            score += 6.0;
        }
        // if next item is large, prefer keeping big-residual bins free
        if next_item_size >= 60 && post_residual > 0 && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many fitting bins: slight preference for fullest bin (smallest residual naturally via base).
    if fitting_bins_count > 1 {
        score -= 3.0;
    }

    // Global state: many open bins with high mean residual -> discourage opening new bins,
    // encourage consolidating into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when there is slack in the system.
        let slack = mean_residual / cap;
        score += 20.0 + 40.0 * slack * (1.0 - progress) + open_bins_count as f64 * 0.5;
        // But late in the stream, opening a fresh bin is cheap since leftovers rarely reused.
        score -= 25.0 * progress;
    } else {
        // Reward placing into bins with residual close to mean (keeps bin pool homogeneous).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Mild preference for using bins that are already fairly full.
    let fill = 1.0 - bin_residual as f64 / cap;
    score -= 6.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    let mut score = pr * (1.0 + 0.5 * progress);

    // smooth non-linear coupling: quadratic waste penalty that intensifies over stream progress
    score += 40.0 * pr_norm * pr_norm * (0.5 + progress);

    // reward tight fits (small post residual) more strongly later in the stream
    score -= 30.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * progress;

    // last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * (item_size as f64 / cap);
    }

    // many fitting bins => competition; slight penalty encourages consolidation
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // prefer bins below mean residual (fill emptier bins) via smooth coupling
    score += 5.0 * (r - mean_residual) / cap;

    // lookahead: bonus if post residual can host next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - pr / (next_item_size as f64).max(1.0));
    }

    // new-bin candidate: penalize mildly so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue classes mod 10
    let pr = post_residual as u32;
    let class = pr % 10;
    // Dead-space classes: small nonzero residuals are bad (wasted slivers)
    if pr > 0 && pr <= 5 {
        score += 8.0; // unusable sliver
    } else if pr > 5 && pr <= 10 {
        score += 3.0;
    } else if class == 0 && pr > 0 {
        score -= 2.5; // perfectly divisible residual: reusable harmonic slot
    } else if class >= 7 && pr < 30 {
        score += 1.5;
    }

    // Exact fill bonus
    if pr == 0 {
        score -= 25.0;
    }

    // Coupling with next item (lookahead): residual that fits next item is valuable
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr as f64) >= nxt {
            // residual can host next item: reward proportional to tightness
            let tight = 1.0 - ((pr as f64) - nxt) / cap;
            score -= 6.0 * tight;
        } else {
            // next item cannot fit here; residual becomes dead for lookahead
            score += 2.0 + (nxt - pr as f64) / cap * 4.0;
        }
        // harmonic pairing: pr divisible by next_item_size or shares residue class
        if nxt > 1.0 && (pr as u32) % (next_item_size) == 0 && pr > 0 {
            score -= 3.0;
        }
    } else {
        // last item: prefer exact fill strongly
        score -= 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate penalty grows with number of open bins (avoid bin proliferation)
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 1.5 + 5.0;
        // but if no open bin fits well, opening is fine: handled by comparison
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Fraction-of-capacity harmonic thresholds on post_residual
    let frac = (pr as f64) / cap;
    if frac > 0.5 {
        score -= 1.0; // still half-capable
    } else if frac < 0.1 && pr > 0 {
        score += 2.0;
    }

    // Progress term: later in stream, tighten packing (favor fuller bins)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * (1.0 - frac);

    // Mean residual alignment: prefer bins near mean residual to keep balance
    score += 0.05 * ((post_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
