    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 + progress);
    } else {
        // mild penalty when many alternatives exist
        let fb = fitting_bins_count.max(1) as f64;
        score += 1.5 * (fb as f64).ln() * (0.5 + progress);
    }

    // Lookahead: penalize if next item would not fit in post residual (smooth)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits = if pr >= nx { 1.0 } else { 0.0 };
        let gap = ((nx - pr) / cap).max(0.0);
        score += 4.0 * (1.0 - fits) * (0.5 + gap).powf(1.5);
        score -= 2.0 * fits * (nx / cap) * (1.0 - progress);
    }

    // Prefer fuller bins relative to mean residual (smooth coupling)
    score -= 2.5 * ((mean_residual - pr) / cap);

    // New-bin candidate: make it attractive only when current fits are poor
    if bin_residual == bin_capacity {
        let poor_fit = (pr / cap).powf(1.5); // pr == cap here => large
        score -= 3.0 * (1.0 - progress) * (1.0 - poor_fit);
        score += 5.0 * (1.0 + progress) * (fitting_bins_count as f64 / (open_bins_count.max(1) as f64 + 1.0)).powf(2.0);
        // opening a new bin is neutral-to-good early, penalized late
        score += 4.0 * progress;
    }

    // Small item-size coupling: prefer placing large items into large residuals
    score -= 1.0 * (it / cap) * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize residuals in "dead zones": too small for typical items.
    // Classes (integer division thresholds on post_residual):
    let class = post_residual / 10; // 0..=10 harmonic classes
    match class {
        0 => score += 60.0,                 // <=9: nearly dead space
        1 => score += 30.0,                 // 10..19: only fits tiny items
        2 => score += 12.0,                 // 20..29
        3 => score += 4.0,                  // 30..39
        4 => score -= 6.0,                  // 40..49: useful mid slot
        5 => score -= 10.0,                 // 50..59: very useful
        6 => score -= 8.0,                  // 60..69
        7 => score -= 3.0,                  // 70..79
        8 => score += 2.0,                  // 80..89
        9 => score += 6.0,                  // 90..99
        _ => {}                             // full-ish / new bin
    }

    // Perfect fit reward: post residual zero or exactly divisible harmonic slots.
    if post_residual == 0 {
        score -= 100.0;
    } else if bin_residual % item_size == 0 {
        score -= 15.0; // exact harmonic division of the bin
    }

    // Lookahead coupling: does the residual class match next item's size class?
    if next_item_size > 0 {
        let next_class = next_item_size / 10;
        if post_residual >= next_item_size {
            // Reward if post residual sits in the same harmonic band as next item
            if class == next_class {
                score -= 20.0;
            } else if post_residual >= next_item_size + 10 {
                score -= 8.0; // still reusable afterwards
            } else {
                score += 5.0; // fits next but leaves near-dead remainder
            }
        } else {
            score += 10.0; // next item cannot reuse this bin
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: neutral-ish baseline, mildly discouraged early,
    // more acceptable late in the stream or when mean residual is fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 45.0 + 20.0 * progress - (mean_residual / bin_capacity as f64) * 10.0;
    }

    // Mild tie-break: prefer bins below mean residual (consolidate emptier bins).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest plausible item are pure waste -> heavy quadratic penalty.
    let min_item = 1.0f64;
    let dead_threshold = 12.0f64;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        score += (dead_threshold - pr) * (dead_threshold - pr) * 2.0;
    }

    // Perfect fit reward: exact fill leaves nothing behind.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score -= (1.0 / (1.0 + fit_ratio)) * 15.0;

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            // post residual can't hold the next item -> mild dead-space penalty
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading out.
    score += open_bins_count as f64 * 0.6;

    // New-bin candidate handling: empty bin gets a base cost so we only
    // open a new bin when fits into open bins are poor (large post_residual
    // or dead space).
    if bin_residual == bin_capacity {
        score += 30.0;
        // If current item is large relative to mean residual of open bins,
        // opening fresh is less bad.
        if (item_size as f64) > mean_residual {
            score -= 20.0;
        }
        // Early in stream, allow opening bins more freely.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
    } else {
        // Penalize placing into bins whose residual deviates badly from mean
        // (keeps a portfolio of usable residuals).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // Slight preference for bins with larger residual when all else equal
    // (keeps small residuals for small future items).
    score -= bin_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 == next {
            score -= 500.0; // exact 2-step chain fit
        } else if (post_residual as f64) >= next {
            // slack proportional to how far next item leaves residual
            let after_next = post_residual as f64 - next;
            score -= 200.0 / (1.0 + after_next / 20.0);
        } else {
            // next item cannot follow in this bin: penalize dead space
            score += (next - post_residual as f64) * 0.5;
        }
    }

    // Tightness reward: small post_residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 50.0;

    // Compare against mean residual: placing in a below-average-residual bin is good
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin bonus (avoid opening new bin unnecessarily)
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Early stream: be conservative, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    // Penalize opening new bins when many bins already fit the item
    if bin_residual == bin_capacity {
        score += 60.0 + 10.0 * fitting_bins_count as f64;
        if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
            score += 30.0; // new bin pairs badly with next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let t = step_index as f64 / (total_items.max(1) as f64);

    // Dead-space penalty: superlinear in wasted residual.
    score += (post_residual as f64) * (post_residual as f64) / cap * 0.15;

    // Lookahead (k=2): reward chains where the next item also fits this bin.
    if next_item_size > 0 {
        if (next_item_size as f64) <= post_residual as f64 {
            score -= 8.0;
        } else {
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / cap;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Brand-new empty bin candidate.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        // Opening a new bin is only attractive for large items that fill it well.
        let mut penalty = 22.0 * (1.0 - fill_ratio);
        // If no open bin fits (this call is the only "fitting" candidate), open freely.
        if fitting_bins_count <= 1 {
            penalty -= 35.0;
        }
        // Reward opening a bin that can host the lookahead item too.
        if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            penalty -= 6.0;
        }
        // Late in the stream, opening fresh bins is slightly more acceptable.
        penalty -= 5.0 * t;
        score += penalty;
    } else {
        // Prefer bins tighter than the fleet mean (best-fit style coupling).
        score += (mean_residual - bin_residual as f64).max(0.0) * 0.2;
        // As the stream progresses, mildly favor consuming existing space.
        score -= 2.0 * t;
        // Crowding penalty: spreading residual across many open bins is costly.
        score += 0.05 * open_bins_count as f64 * (post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual (tight fit), with non-linear sharpening
    let mut score = norm_pr * norm_pr * (1.0 + 2.0 * progress) * cap;

    // Smooth polynomial coupling: penalize residual that is small-but-not-zero
    // (dead space), scaled by stream progress.
    let dead = norm_pr * (1.0 - norm_pr);
    score += 8.0 * dead * (0.5 + progress);

    // Last-chance bonus: smooth reward when few fitting bins exist
    let fit_term = 1.0 / (1.0 + fitting_bins_count as f64);
    score -= 10.0 * fit_term * (1.0 + progress);

    // Lookahead: if next item fits in post-residual, reward this placement smoothly
    if next_item_size > 0 {
        let next_fits = if (post_residual as u64) >= (next_item_size as u64) { 1.0 } else { 0.0 };
        let gap = ((post_residual as f64 - next_item_size as f64).abs()) / cap;
        score -= 6.0 * next_fits * (1.0 - gap * gap);
    }

    // Dispersion penalty: placing into a bin far from mean residual
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Mild penalty for many open bins, encouraging consolidation
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: neutral baseline with slight progress-dependent bias
    if bin_residual == bin_capacity {
        score = cap * (0.6 + 0.4 * progress) + 2.0 * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction buckets.
    // Residuals in (0, 10] are dead space -> heavy penalty; large residuals are fine.
    let c = bin_capacity as f64;

    // Dead-space penalty: post_residual below the smallest item size is wasted.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += (10 - post_residual) as f64 * 4.0; // unusable sliver
    }

    // Integer-division thresholds: how many "small items" (size ~10) could still fit.
    let slots = post_residual / 10;
    score -= slots as f64 * 2.0;

    // Modulo arithmetic on post_residual: residuals divisible by common item
    // sizes (10, 20, 25, 50) are reusable by future items.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 3.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 50 == 0 { score -= 4.0; }
    }

    // Lookahead: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item fills the leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * fill;
            // penalize leaving a tiny remainder after the next item too
            let pr2 = post_residual - next_item_size;
            if pr2 > 0 && pr2 < 10 {
                score += 6.0;
            }
        } else {
            // next item can't use this bin's leftover; mild penalty
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 0.15 * (item_size as f64 / c) * 100.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // current fit is bad. Give the empty bin a baseline score that real bins
    // can usually beat.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Early in the stream, new bins are cheaper to open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // If next item is large, a fresh bin is attractive.
        if next_item_size > 50 {
            score -= 8.0;
        }
    }

    // Prefer bins below mean residual (tighter bins get tighter).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Mild pressure to consolidate when many bins are open.
    score -= open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in the "unusable gap" zone
    // (small, hard-to-fill leftovers) gets amplified.
    let pr = post_residual as f64;
    let gap_threshold = 25.0f64;
    if post_residual > 0 {
        if pr <= gap_threshold {
            // small leftovers are dead space -> quadratic penalty
            score += (gap_threshold - pr) * (gap_threshold - pr) * 0.35;
        } else {
            // large leftovers are still useful -> slight discount
            score -= (pr - gap_threshold) * 0.25;
        }
    } else {
        // perfect fill: strong reward
        score -= 60.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a
    // reasonably tight fit exists here.
    let ob = open_bins_count as f64;
    score += ob * 2.5;

    // Mean-residual coupling: if the fleet average residual is high, reward
    // consolidating into this bin (reduces fragmentation).
    score -= (mean_residual - pr) * 0.15;

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64 / (post_residual as f64 + 1.0)) * 8.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Make it attractive only when the current bin would leave a nasty gap
    // or when bin pressure is low.
    if bin_residual == bin_capacity {
        let stream_pos = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bins early in the stream (long horizon to amortize),
        // or when this placement would create dead space.
        let dead_space_penalty = if pr > 0 && pr <= gap_threshold { 1.0 } else { 0.0 };
        score -= 20.0 + 40.0 * (1.0 - stream_pos) + 25.0 * dead_space_penalty - ob * 1.5;
    }

    // Mild stream-progression tilt: late in the stream, tolerate looser fits
    // rather than opening bins that will go mostly unused.
    score -= (step_index as f64 / (total_items.max(1) as f64)) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fits (small post_residual) are good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // 2-step lookahead: exact match of post_residual with next_item_size is ideal.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if gap == 0.0 {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else {
            score += gap * 0.5;
        }
        // If next item can still fit in the post-residual, mild reward.
        if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Dead space: next item can't use leftover; penalize small unusable slivers.
            score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Compare against mean residual: prefer bins that are tighter than average.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when decent open bins exist (new-bin candidate).
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0 + 5.0 * open_bins_count as f64;
    }

    // Early in stream: be slightly conservative about fragmenting bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual quadratically.
    score += 0.05 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // Strong reward for perfect fit.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + 0.1 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // Dead space that next item cannot use: penalize more as stream progresses.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 3.0 + 5.0 * progress;
    }

    // Last chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large or
    // existing residuals are all poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (bin_capacity as f64 - item_size as f64) - post_residual as f64;
        let _ = waste;
        // Opening new bin leaves capacity - item_size residual; penalize when
        // many open bins exist and mean residual is large.
        score += 6.0 + 0.05 * open_bins_count as f64 + 0.03 * mean_residual;
        if item_size > 70 {
            score -= 10.0; // large items benefit from a fresh bin
        }
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 4.0; // fresh bin accommodates lookahead
        }
        let _ = progress;
    }

    // Slight preference for bins below mean residual (consolidate emptier bins).
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let p = progress.clamp(0.0, 1.0);

    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 - x); // vanishes at x=0 and x=1, peaks mid-range
    score += 30.0 * poly * (0.5 + p);

    // Penalize large dead space more strongly as the stream progresses
    score += (x * x * x) * (10.0 + 40.0 * p);

    // Reward tight fits: subtract for small post residuals
    score -= (1.0 - x) * (1.0 - x) * 8.0;

    // Lookahead coupling: bonus if the next item fits smoothly into the post residual
    if next_item_size > 0 {
        let nx = (next_item_size as f64) / cap;
        let gap = (x - nx).max(0.0);
        score -= 12.0 * (gap / (1.0 + nx));
        // penalize if next item cannot fit the leftover
        let miss = (nx - x).max(0.0);
        score += 15.0 * miss * miss;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + p);
    }

    // Mild pressure to consolidate when many bins are open
    let norm_open = (open_bins_count as f64 / (1.0 + open_bins_count as f64)).sqrt();
    score += 5.0 * norm_open * (1.0 - p);

    // Deviation from mean residual: prefer bins near the mean (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate shaping: make an empty bin mildly attractive only for large items
    if bin_residual == bin_capacity {
        let fill = (item_size as f64) / cap;
        score -= 6.0 * fill * fill * (1.0 + p);
        score += 10.0 * (1.0 - fill);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize into capacity fractions (1/8 bins)
    let frac = post_residual as f64 / cap;
    let class = (frac * 8.0).floor() as u32; // 0..8 harmonic class

    // Reward tight fits: bins whose post_residual falls in a "useful" class
    // Useful classes: small residuals (0,1) are great; class 4 (half full) is reusable.
    let useful = match class {
        0 => 30.0,
        1 => 18.0,
        2 => 8.0,
        3 => 2.0,
        4 => 6.0,
        5 => 1.0,
        6 => 0.0,
        _ => 0.0,
    };
    score -= useful;

    // Modulo penalty: post_residual that is awkwardly small-but-nonzero wastes space
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Integer division threshold: can next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead fits: strongly reward, scaled by how well it nests
            let nest = 1.0 - ((post_residual - next_item_size) as f64 / cap);
            score -= 10.0 + 15.0 * nest;
        } else {
            // lookahead won't fit: penalize proportional to wasted potential
            score += 5.0 + 0.15 * (next_item_size as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so we prefer
    // reusing open bins unless their residuals are large/dead.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.3 * open_bins_count as f64;
        // but if open bins are nearly all full, opening is fine
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 20.0;
        }
    }

    // Dead-space penalty: post_residual below smallest plausible item (1..=10)
    if post_residual < 10 && post_residual > 0 {
        score += 10.0;
    }

    // Harmonic parity bonus: post_residual divisible by common item sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Stream progression: late in the stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - frac);

    // Prefer bins below mean residual (filling fuller bins first)
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are wasted capacity.
    if post_residual > 0 {
        // Dead space zone: gaps too small for the smallest plausible item (<= 15).
        if post_residual <= 15 {
            score += 60.0 * (1.0 - post_residual as f64 / 15.0);
        } else if post_residual <= 30 {
            // Moderate dead space: partial penalty, scaled by how far below half capacity.
            score += 20.0 * (1.0 - post_residual as f64 / 30.0);
        }
    } else {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward bins that can also host the lookahead item after placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap blocks the known next item: extra penalty.
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        score = 55.0 + 3.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin pairs well with lookahead
        }
    }

    // Open-bin pressure: discourage accumulating many half-empty bins.
    score += 0.4 * open_bins_count as f64;

    // Slight preference for bins below mean residual (consolidating emptier space).
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: next item exactly fills this bin afterwards.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if diff <= 5.0 {
            score -= 35.0 - diff * 3.0;
        } else {
            // Penalize leftover that is too small for the next item (dead space).
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 0.8;
            } else {
                // Leftover larger than next item: mild reward for retaining capacity.
                score -= ((post_residual - next_item_size) as f64).min(20.0) * 0.4;
            }
        }
        // If next item could fit here after current placement, slight bonus.
        if next_item_size <= post_residual {
            score -= 6.0;
        }
    } else {
        // Last item: strongly prefer minimal leftover.
        score += post_residual as f64 * 0.5;
    }

    // Tight-fit reward: item fills most of the bin now.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if fill_ratio > 0.8 {
        score -= 25.0 * (fill_ratio - 0.8);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer bins below mean residual (waste poor bins first? no: prefer bins with
    // residual close to item, i.e. low residual bins for small items).
    let mean_dev = (bin_residual as f64 - mean_residual).abs();
    score += mean_dev * 0.15;

    // New-bin candidate: only attractive when current placement would leave large dead space
    // and there are alternatives; penalize opening new bins mildly.
    if bin_residual == bin_capacity {
        // Opening a new bin wastes the residual of existing bins; make it costly unless
        // the item is large and no tight fit exists.
        score += 30.0 - 20.0 * fill_ratio;
        if post_residual < 10 {
            score -= 15.0; // large item nearly fills a fresh bin
        }
    }

    // Mild preference for consolidated bins early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * post_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for very tight fits (small dead space).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= (1.0 - tightness) * (1.0 - tightness) * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_quality = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
            score -= 20.0 * chain_quality;
        } else {
            // Penalize leaving a residual too small for the next item (dead space).
            score += ((next_item_size - post_residual) as f64) * 0.4;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: prefer new bin only when all open residuals are poor.
    if bin_residual == bin_capacity {
        let avg = mean_residual;
        // If open bins have plenty of usable space, discourage opening a new bin.
        score += 40.0;
        if avg > (item_size as f64) * 1.5 {
            score += 15.0; // existing bins are roomy; use them
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 10.0; // fresh bin can host item + next item together
        }
        // Early in stream, opening bins is cheaper; late, consolidate.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 20.0;
    } else {
        // Mild penalty for spreading across many open bins.
        score += (open_bins_count as f64).ln().max(0.0) * 2.0;
        // Prefer bins with residual close to item (best-fit flavor).
        let gap = (bin_residual - item_size) as f64;
        score += gap * 0.3;
    }

    // Global state coupling: if mean residual is small, conserve tight fits harder.
    if mean_residual < 15.0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills (small post_residual rewarded more);
    // late in the stream, dead space matters even more.
    let tightness = 1.0 - pr / cap; // 0..1, higher = tighter fit
    let progress_gain = progress * (1.0 + progress);
    score -= tightness * tightness * (20.0 + 40.0 * progress_gain);

    // Penalize residual near the awkward middle range via smooth bump
    let mid = pr / cap;
    let bump = mid * (1.0 - mid); // peaks at 0.5 residual
    score += 15.0 * bump * (1.0 + progress);

    // Lookahead coupling: reward residuals that can host next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 10.0 * (1.0 - slack * slack);
        } else {
            let gap = (nx - pr) / cap;
            score += 12.0 * gap * gap;
        }
    }

    // Last-chance pressure: smooth reward when few fitting bins remain
    if fitting_bins_count <= 1 {
        score -= 8.0 * tightness;
    }

    // Spread pressure relative to mean residual
    score += 0.05 * (pr - mean_residual);

    // Mild penalty for proliferating bins late in the stream
    score += 0.3 * open_bins_count as f64 * progress_gain;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        return -10000.0;
    }

    // Harmonic classes: classify post_residual into residue classes mod 10.
    // Residuals that are multiples of 10 pair naturally with many item sizes.
    let r = post_residual % 10;
    score += match r {
        0 => -20.0,
        1 | 9 => 15.0,
        2 | 8 => 8.0,
        3 | 7 => 3.0,
        _ => 0.0,
    };

    // Fraction-of-capacity classes: post_residual / capacity buckets.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.10 {
        score -= 25.0; // nearly-full bin: excellent
    } else if frac < 0.30 {
        score -= 5.0;
    } else if frac > 0.70 {
        score += 20.0; // leaving a huge gap is bad unless item was huge
    }

    // Dead-space penalty: residual too small for the smallest possible item (1).
    // Since sizes can be as small as 1, only exact 0 is truly dead, but small
    // residuals are valuable if they match the lookahead item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // sets up a perfect fit for the next item
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // residual can't host next item: mild penalty scaled by shortfall
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 80.0
            + (open_bins_count as f64).sqrt() * 2.0
            + mean_residual * 0.2;
    }

    // Prefer consolidating into bins below mean residual (filling emptier bins).
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 5.0;
    }

    // Late in the stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual >= 10 {
        // Usable residual: mild reward proportional to how much usable space remains.
        score -= 0.15 * (post_residual as f64).min(60.0);
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here; leftover will be dead -> penalize.
        score += 8.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 0.1 * item_size as f64;
    }

    // Open-bin pressure: many open bins -> discourage opening new ones,
    // encourage filling existing bins.
    score += 0.6 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin's residual is far below mean, it's a
    // tight bin -> prefer packing it; large-residual bins can wait.
    score += 0.2 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 55.0 + 0.5 * open_bins_count as f64;
        // But if the item is huge relative to capacity and bins are crowded,
        // opening fresh space is less penalized.
        score -= 20.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Progression: late in the stream, be more conservative (avoid waste).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item exactly fills the post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits too: mild reward proportional to how well it fits.
            score -= 50.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit in the leftover: penalize dead space risk.
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    } else if post_residual > 0 {
        // Last item: leftover is pure waste; penalize proportionally.
        score += post_residual as f64;
    }

    // Prefer bins with residuals tighter than the mean (good packing density).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        let open_penalty = 300.0 + 2.0 * open_bins_count as f64;
        // Attractiveness of new bin scales with wasted space it would avoid.
        let waste_avoided = (item_size as f64).max(0.0);
        score += open_penalty - waste_avoided;
    }

    // Early in the stream, allow more flexibility (mild penalty on tight fits).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: post_residual is the base, subtract a bonus that grows
    // super-linearly as post_residual shrinks toward 0.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let tight_bonus = ((cap - pr) / cap).powf(6.0) * 45.0;
    score -= tight_bonus;

    // Penalize "dead space": leftover space too small for the smallest plausible item (1..100 range).
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 3.0; // wasted sliver
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_quality = 1.0 - ((pr - nx) / cap);
            score -= fit_quality * 25.0 * (1.0 + t);
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled by mismatch
            score += ((nx - pr) / cap) * 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // With multiple options, prefer bins whose residual deviates from the mean
        // (consolidate into outlier bins, keep uniform bins flexible).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    // New-bin candidate (empty bin): residual == capacity means post_residual = cap - item.
    // Only attractive when the item is large relative to capacity (poor fit elsewhere likely)
    // or when many bins already exist and this item would leave a very awkward remainder.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        // Base penalty for opening a new bin
        score += 20.0;
        // Large items justify new bins (they leave little choice)
        score -= fill_ratio.powf(2.0) * 40.0;
        // If no open bin fits (fitting_bins_count counts open bins; 0 means only the new bin fits)
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, opening fresh bins is less costly than fragmenting
        score -= t * 10.0;
        // If many open bins already, slightly discourage unbounded growth
        score += (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Global pressure: when mean residual across open bins is low, waste matters more.
    let waste_weight = 1.0 + (cap - mean_residual) / cap;
    score *= waste_weight * 0.5 + 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let tightness = 1.0 - pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Reward tight fits via smooth cubic of tightness
    score -= 24.0 * tightness * tightness * tightness;

    // Penalize dead space: smooth quadratic in post_residual scaled by mean residual
    score += 0.15 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // Last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 * tightness;
    }

    // Lookahead coupling: reward leaving space compatible with next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score += 0.05 * gap * gap / cap;
        if pr >= nx {
            score -= 6.0;
        }
    }

    // Late-stream smoothing: mild penalty on very loose fits as stream ends
    score += 10.0 * progress * (pr / cap) * (pr / cap);

    // New-bin candidate handling: mildly discourage opening new bins mid-stream
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: which eighth of the capacity it occupies.
    let item_class = (item_size * 8) / bin_capacity; // 0..8
    let next_class = (next_item_size * 8) / bin_capacity;

    // Reward tight fits with a strong multiplicative discount.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize dead space that is too small for typical items (1..100 range):
    // unusable residual below the minimum item size is pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Harmonic "trap zones": residuals in (0, 20) rarely pair well.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Modulo-structure on post_residual: residuals that are multiples of
    // common small item sizes (10, 20, 25, 50) stay usable.
    let usable_mod = post_residual % 10 == 0 || post_residual % 25 == 0;
    if usable_mod {
        score -= 6.0;
    } else if post_residual > 0 {
        score += 3.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly prefer this bin (chained perfect packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_fit = post_residual - next_item_size;
        if chain_fit == 0 {
            score -= 30.0;
        } else if chain_fit < 10 {
            score += 10.0; // chain would create dead space
        } else {
            score -= 4.0;
        }
    }
    // If next item cannot fit here anyway, mild bonus (bin stays clean for later).
    if next_item_size > post_residual {
        score -= 2.0;
    }

    // Harmonic class pairing: same-class bins waste space; cross-class
    // (item + next item classes summing to 8) is a perfect complement.
    if next_item_size > 0 && item_class + next_class == 8 {
        score -= 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate (residual == capacity): make it unattractive unless
    // no open bin gives a decent fit. Base penalty scales with open bins.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        // But if item is large (harmonic class >= 6), new bin is fine.
        if item_class >= 6 {
            score -= 22.0;
        }
        // Early in the stream, opening bins is cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer filling bins that deviate most from the mean residual
    // (drives residual distribution toward uniformity).
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.05 * dev;

    // Mild pressure to close bins when many are open.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core 2-step lookahead: reward if next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - 0.4 * slack; // perfect chain match strongly rewarded
        } else {
            // next item won't fit here; penalize proportional to overflow gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Tight fit reward relative to bin capacity
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Relative to mean residual: prefer bins whose residual deviates favorably
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 30.0 * (1.0 - progress) * (open_bins_count as f64).sqrt();
        if fitting_bins_count > 0 && post_residual as f64 >= mean_residual {
            score += 10.0;
        }
    }

    // Small waste penalty scaled by item size
    score += 0.05 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // Penalize dead space relative to bin capacity (non-linear)
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * dead_frac * dead_frac * (bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: prefer opening a new bin only if fit elsewhere is bad
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // base penalty so an existing decent fit wins
        score += 80.0;
        // but if the item is large and residuals are small, opening fresh is attractive
        let tight_open = mean_residual < item_size as f64 + 8.0;
        if tight_open {
            score -= 120.0;
        }
        // early in stream, opening bins is cheap; later, consolidate
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 60.0 * progress;
        // many open bins: discourage adding another
        score += 8.0 * open_bins_count as f64;
    } else {
        // favor bins whose residual is close to item size (tightness reward)
        let tightness = 1.0 - (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score -= 50.0 * tightness;
    }

    // Lookahead: reward if the next item fits the post residual exactly-ish
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 250.0;
        } else if next_item_size <= post_residual {
            let waste = post_residual - next_item_size;
            score -= (60.0 - waste.min(60) as f64).max(0.0);
        } else {
            // next item won't fit here; slight penalty for leaving too-small gap
            score += 10.0;
        }
    }

    // Global state coupling: when mean residual is high, prefer bins that reduce spread
    let spread = (mean_residual - post_residual as f64).abs();
    score += 0.3 * spread;

    // Small time-varying exploration term (deterministic, grounded in step)
    let phase = ((step_index as f64 * 0.017).sin()) * 3.0;
    score += phase;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: penalize wasted space with a non-linear (quartic) coupling
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Polynomial interaction: how well does the leftover space match the next item?
    let gap = (pr - next_item_size as f64) / cap;
    score -= 12.0 * (1.0 - gap * gap) * (1.0 - progress);

    // Smooth progress-weighted tightness reward (favor tight fits more later in stream)
    score -= 6.0 * (norm_item * (1.0 - norm_item)) * (0.5 + progress);

    // Last-chance bonus: strongly prefer using a bin when few bins can fit the item
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Mean-residual coupling: prefer bins whose residual deviates smoothly from mean
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev - 2.0 * dev;

    // Penalize opening new bins, more so early in the stream
    if bin_residual == bin_capacity {
        score += 20.0 + 25.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "useless" (small)
    // and penalize residuals in awkward mid-range classes.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fit
    } else if pr < 10 {
        score -= 12.0; // near-perfect, dead space is tiny
    } else {
        // class by modulo / integer division thresholds
        let class = pr / 10; // 0..10 harmonic class
        // mid classes (20-50) are worst: big enough to waste, small enough to be unusable
        let class_penalty = match class {
            1 => 6.0,
            2 => 10.0,
            3 => 12.0,
            4 => 11.0,
            5 => 8.0,
            6 => 5.0,
            _ => 0.0,
        };
        score += class_penalty;
        // fine-grained: reward residuals that exactly match common item sizes (harmonic slots)
        let slots: [u32; 8] = [10, 20, 25, 30, 40, 50, 60, 80];
        for s in slots.iter() {
            if pr == *s {
                score -= 8.0;
            } else if pr > *s && pr - *s < 5 {
                score += 3.0; // barely-missed slot: awkward
            }
        }
        // modulo structure: residuals divisible by 10 are cleaner targets
        if pr % 10 == 0 {
            score -= 2.0;
        }
    }

    // Lookahead: if the next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            if slack < 10 {
                score -= 10.0; // next item fits almost perfectly
            } else {
                score += (slack as f64) * 0.05;
            }
        } else {
            // next item won't fit here; residual becomes dead space for lookahead
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base = 40.0;
        let discount = 20.0 * (1.0 - pressure) * (1.0 - 0.3 * progress);
        score += base + discount;
        if open_bins_count == 0 {
            score -= 60.0; // must open
        }
    } else {
        // slight preference for fuller bins among open ones
        score += (bin_capacity - bin_residual) as f64 * -0.05;
    }

    // Tie-break: prefer bins whose residual is close to item size (tight fit)
    let tightness = (bin_residual - item_size) as f64;
    score += tightness * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it cannot hold even the smallest plausible item (1..=10).
    let dead_threshold = 10.0f64.min(item_size as f64 * 0.15);
    if post_residual as f64 > 0.0 && (post_residual as f64) < dead_threshold {
        score += 60.0;
    }

    // Penalize moderate gaps that cannot fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward tight fits: exact fill or near-exact fill is excellent.
    let tightness = (post_residual as f64) / bin_capacity as f64;
    score += 8.0 * tightness * tightness;

    // Reward filling a bin that is already fairly full (low residual before placement).
    let fill_ratio_before = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio_before;

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open bins pressure: many open bins -> favor consolidating into existing bins,
    // but only mildly so tight-fit logic can dominate.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * open_pressure * tightness;

    // If this bin is a brand-new empty bin candidate, penalize slightly so that
    // only genuinely good fits in existing bins are bypassed.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * open_bins_count as f64;
        // But if no existing bin fits well (large item, high mean residual), soften:
        if mean_residual < item_size as f64 * 0.5 && fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Late-stream consolidation: as the stream progresses, prefer packing existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - tightness);

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Aggressive 2-step lookahead: prefer leaving a residual that the
    // next item can still fit into.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            // Residual remains usable for the next item: reward proportionally
            // to how snugly the next item will fit afterwards.
            let next_post = post_residual as f64 - nxt;
            score -= 40.0 + 60.0 * (1.0 - next_post / bin_capacity as f64);
        } else {
            // Dead space: residual too small for the next item -> penalize
            // harder the closer it is to being wasted.
            let waste = post_residual as f64 / nxt;
            score += 25.0 + 50.0 * waste;
        }
    }

    // Prefer bins whose residual deviates favorably from the fleet mean
    // (tighter-than-average bins get packed first, keeping loose bins open).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= 20.0 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive when the item
    // fits poorly everywhere else. Penalize new bins mildly by default, with
    // the penalty shrinking as the stream progresses (fewer chances left to
    // amortize a fresh bin).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 45.0 - 25.0 * progress;
    }

    // Mild bonus for filling bins tightly relative to capacity.
    score += 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let item = item_size as f64;
    let nxt = next_item_size as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: prefer small post residual (tight fits).
    let mut score = post;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - post / cap; // 1.0 = perfect fit
    score -= 25.0 * tightness * tightness;

    // Last-chance bin: placing here avoids opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 18.0;
    }

    // Lookahead coupling: reward if the post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward for near-exact pairing (item + next fills bin well).
            let pair_fill = (item + nxt) / cap;
            if pair_fill > 0.85 {
                score -= 10.0 * (pair_fill - 0.85) / 0.15;
            }
        } else {
            // Penalize creating dead space the next item cannot use,
            // scaled by how dead it is.
            let dead = post / cap;
            score += 8.0 * dead * dead;
        }
    } else {
        // Last item of stream: pure tightness matters most.
        score -= 10.0 * tightness;
    }

    // Penalize bins whose residual deviates badly from the mean (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 6.0 * dev;

    // Early stream: be less picky, allow consolidation; late stream: tighter.
    score -= (1.0 - progress) * 4.0;

    // Many open bins: prefer filling existing ones over spreading.
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large (poor fits elsewhere likely) or fits are very bad.
    if is_new_bin {
        // Default: new bin is worse than any reasonable fit.
        score = cap * 1.5;
        // Large items leave little room for waste; a fresh bin is fine.
        if item > 0.6 * cap {
            score = cap - item + 5.0;
        }
        // If several bins fit but all would leave huge dead space, allow opening.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
        // Late in the stream, be more willing to open a clean bin.
        score -= 20.0 * progress;
        // If this bin is the only fitting option (no open bin fits), opening is right.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let norm_item = item / cap;
    let norm_next = next_item_size as f64 / cap;
    let mean_res_norm = mean_residual / cap;

    // Base: minimize post residual, with non-linear (quadratic) emphasis.
    let mut score = norm_pr + 0.7 * norm_pr * norm_pr;

    // Stream-progress coupling: late in the stream, tighten residual preference.
    let late = progress * progress;
    score += late * norm_pr * (1.0 + mean_res_norm);

    // Perfect-fit reward: subtract strongly as post_residual approaches zero.
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + norm_item);

    // Lookahead coupling: reward leaving space that the next item can use.
    if next_item_size > 0 {
        let gap = (norm_pr - norm_next).abs();
        let usable = if norm_next <= norm_pr { 1.0 - gap } else { 0.0 };
        score -= 0.6 * usable * (1.0 - progress);
        // Penalize leaving residual slightly larger than next item (wasted sliver).
        score += 0.4 * (norm_pr - norm_next).max(0.0) * (norm_pr - norm_next).max(0.0);
    }

    // Last-chance bin pressure: if this is the only fitting bin, favor using it.
    if fitting_bins_count == 1 {
        score -= 0.8 * (1.0 - late);
    }

    // Penalize opening a new bin when good fits exist among open bins.
    if bin_residual == bin_capacity {
        score += 0.5 + 0.5 * (1.0 - norm_item) + late * 0.5;
        // But allow new bins when open bins are nearly full on average.
        score -= 0.6 * mean_res_norm * mean_res_norm;
    }

    // Mild open-bins count pressure to discourage bin proliferation.
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are near-perfectly packed -> reward heavily.
    let class_width = bin_capacity / 5; // 20-unit harmonic classes
    let post_class = post_residual / class_width;
    score -= (4 - post_class) as f64 * 12.0;

    // Dead-space penalty: leftover that no future item (min size 1, typical >=10)
    // can ever use. Residual in (0, 10) is pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic pairing: if next item divides into post_residual evenly
    // (integer division leaves 0), this bin is likely reusable next step.
    if next_item_size > 0 && post_residual >= next_item_size {
        let rem = post_residual % next_item_size.max(1);
        if rem == 0 {
            score -= 30.0;
        } else if rem < 10 {
            score += 15.0; // would create dead space next step
        }
    } else if next_item_size > 0 {
        // next item cannot reuse this bin; mild penalty scaled by gap
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: only one open bin fits -> strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Late in the stream, prefer tight packing over opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 20.0;
    } else {
        // New-bin candidate: penalize unless current bins are very fragmented.
        score += 25.0 * progress;
        if mean_residual > (item_size as f64) * 1.5 {
            score += 40.0; // open bins have plenty of room; don't open a new one
        }
    }

    // Prefer bins tighter than the mean (best-fit flavor).
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.2;
    }

    // Modulo threshold on capacity fraction: residuals that are exact
    // eighths of capacity keep the bin in a "clean" harmonic state.
    if post_residual % (bin_capacity / 8) == 0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty: post_residual too small to ever be useful (dead space).
    // Assume smallest plausible item ~ 1; but treat gaps below a soft threshold
    // (e.g. < 20) as progressively wasted since typical items are mid-sized.
    let dead_threshold: f64 = 20.0;
    let pr = post_residual as f64;
    if pr < dead_threshold {
        // The smaller the leftover, the worse (it's wasted capacity).
        let waste = (dead_threshold - pr) / dead_threshold; // 0..1
        score += waste * waste * 60.0;
        // Absolute dead space (gap that likely fits nothing) gets extra penalty.
        if pr < 5.0 {
            score += 40.0;
        }
    }

    // Reward very tight fits (post_residual near zero but item exactly fills bin).
    if post_residual == 0 {
        score -= 25.0; // perfect fill
    }

    // Coupling with mean residual: prefer bins whose residual is close to the item,
    // i.e. avoid dumping a small item into a huge-residual bin when better fits exist.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.15;

    // Open-bin pressure: when many bins are open, discourage spreading items into
    // yet another bin; when few bins are open, encourage consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * 3.0 * (0.5 + 0.5 * progress);
    score += pressure;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward for chaining.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (pr - nr).abs() < 1.0 {
            score -= 15.0;
        } else if pr >= nr && pr - nr < dead_threshold {
            // next item would create dead space here -> penalize
            score += 8.0;
        }
    }

    // New-bin candidate: make it moderately attractive only when current fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; offset by pressure when bins are few.
        score += 10.0 + pressure * 0.5;
        // If the item is large relative to mean residual, new bin is fine.
        if (item_size as f64) > mean_residual {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits the next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 100.0;
    }
    // Next item fits comfortably in the post-residual space
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // Dead space relative to the lookahead item
        score += 0.6 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits relative to mean residual across open bins
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness);

    // Penalize bins whose residual is far above mean (hoarding space)
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New empty bin candidate: penalize mildly so it only wins on terrible fits
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    // Slight preference to consolidate into fewer bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Penalize leaving residuals that are small but useless (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: bonus if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual {
            // next item won't fit here anyway; slight penalty for wasting space now
            score += 4.0 * (next_item_size as f64 - post_residual as f64).min(20.0) / 20.0;
        } else {
            score += (post_residual - next_item_size) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when many bins are already open and mean residual is high.
    if bin_residual == bin_capacity {
        score += 30.0
            - 0.5 * mean_residual
            - (open_bins_count as f64).sqrt() * 2.0
            + (step_index as f64 / (total_items.max(1) as f64)) * 10.0;
    } else {
        // Slight preference for bins with smaller residuals among fitting bins.
        score += (bin_residual as f64 - mean_residual) * 0.1;
    }

    // Mild time-horizon modulation: tighten packing as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual
    let mut score = pr as f64;

    // Smooth non-linear coupling of post_residual with stream progress
    score += 12.0 * x * x * (1.0 + t);
    score -= 8.0 * x * (1.0 - t) * (1.0 - x);

    // Tight-fit reward, smoothly modulated by progress
    let tightness = 1.0 - (pr as f64 / cap);
    score -= 15.0 * tightness * tightness * (0.5 + t);

    // Penalize large residual late in stream
    score += 10.0 * x * t * t;

    // Lookahead: reward residual that can fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as f64 >= nx {
            let slack = (pr as f64 - nx) / cap;
            score -= 10.0 * (1.0 - slack) * (1.0 - t);
        } else {
            score += 5.0 * t;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - 0.5 * t);
    }

    // New-bin candidate: prefer opening a new bin when existing residuals are low-value
    if bin_residual == bin_capacity {
        score += 3.0 + 5.0 * (1.0 - t) - 4.0 * t * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    // Mild dispersion penalty relative to mean residual
    score += 2.0 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: classify post_residual into capacity fractions
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity left

    // Penalize residuals in "dead" harmonic classes (hard to fill later)
    // classes: (0,10], (10,20], (20,30], (30,50], (50,100]
    if post_residual == 0 {
        score -= 200.0; // perfect fill, best possible
    } else if post_residual <= 10 {
        score -= 120.0; // near-perfect: almost dead but tiny waste
    } else if post_residual <= 20 {
        score -= 60.0;
    } else if post_residual <= 30 {
        score -= 25.0;
    } else if post_residual <= 50 {
        score += 15.0;
    } else {
        score += 30.0; // large residual: wasteful placement
    }

    // Modulo coupling: residuals divisible into common size classes are reusable
    let pr = post_residual;
    if pr % 10 == 0 {
        score -= 8.0; // aligns with typical item granularity
    }
    if pr % 5 == 0 && pr % 10 != 0 {
        score -= 3.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            score -= 30.0;
            // harmonic class match of next item with residual
            if post_residual % next_item_size == 0 {
                score -= 20.0;
            }
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: only attractive if all open bins fit poorly
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // fresh bin has huge residual; make it unattractive unless desperate
        score += 55.0;
        if fitting_bins_count == 0 {
            score -= 300.0; // no alternative: must open
        } else if mean_residual < item_size as f64 * 1.2 {
            score -= 80.0; // open bins nearly full anyway
        }
    }

    // Progression: late in stream, tighten up (prefer exact fills)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - frac);

    // Mild pressure against proliferating bins
    score += open_bins_count as f64 * 0.5 * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Gaps that are too small for the minimum item size (1..100 range, so any
    // gap >= 1 is technically usable, but gaps far below the next item's size
    // are likely dead) are penalized non-linearly.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Penalize gaps that cannot fit the next item (likely dead space)
        if next_item_size > 0 && post_residual < next_item_size {
            score += 15.0 + (next_item_size - post_residual) as f64 * 0.6;
        }
        // Non-linear penalty for tiny residual gaps (hard to fill later)
        if gap < 20.0 {
            score += (20.0 - gap) * 1.5;
        }
    } else {
        // Perfect fit: strong reward
        score -= 40.0;
    }

    // Reward tight fits: the smaller post_residual relative to item_size,
    // the better the packing density.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 10.0;

    // Open bins pressure: when many bins are open, prefer filling existing
    // bins rather than spreading; penalize lightly to consolidate.
    if bin_residual != bin_capacity {
        score += open_bins_count as f64 * 0.05;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // the current item would leave a large dead gap in every open bin.
    if bin_residual == bin_capacity {
        // Mild penalty baseline so that decent fits in open bins win,
        // but a new bin beats terrible fits.
        score += 8.0;
        // If many bins are open already, discourage opening yet another.
        score += open_bins_count as f64 * 0.3;
        // If next item is large and current item is small, a fresh bin
        // preserves space for the big item: slight reward.
        if next_item_size > item_size * 2 {
            score -= 6.0;
        }
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is nearly full — prefer filling such bins to close them out.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if post_residual as f64 >= next {
            // Next item fits perfectly in this bin after current placement.
            if diff < 1.0 {
                score -= 500.0;
            } else if diff <= 5.0 {
                score -= 150.0;
            } else if diff <= 10.0 {
                score -= 50.0;
            }
        } else {
            // Next item won't fit here; penalize leaving a residual that is
            // unusable for the next item (dead space).
            score += 0.5 * (next - post_residual as f64);
            if post_residual < 10 {
                score += 60.0; // tiny unusable sliver
            }
        }
        // Bonus if this bin can chain-fit both current and next item tightly.
        if (bin_residual as f64) >= (item_size as f64 + next) {
            score -= 20.0;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // prefer placements that keep the fleet of open bins balanced / tight.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin unless current bins are genuinely poor fits,
    // especially early-to-mid stream where consolidation matters.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fit = post_residual as f64 > 40.0;
        if fitting_bins_count > 0 && !poor_fit {
            score += 150.0; // existing bin is decent; avoid new bin
        } else if fitting_bins_count > 0 && post_residual as f64 <= 10.0 {
            score += 250.0; // near-perfect fit exists; never open new bin
        }
        if open_bins_count as f64 > mean_residual / 5.0 && progress < 0.5 {
            score += 30.0; // many open bins with slack; discourage more
        }
    }

    // Mild preference for filling bins with larger residual usage.
    score -= 0.1 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let waste = (next_item_size - post_residual) as f64;
        score += 0.6 * waste;
    }
    // Reward bins whose post_residual exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin unless residuals are tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_gap = mean_residual - post_residual as f64;
        let mut penalty = 20.0 + 10.0 * (1.0 - progress);
        if avg_gap < 25.0 {
            penalty += 25.0; // existing bins are tight; opening is wasteful
        } else if avg_gap > 45.0 {
            penalty -= 18.0; // open bins are fragmented; fresh bin is fine
        }
        // If nothing else fits well, allow opening.
        if fitting_bins_count == 0 {
            penalty -= 40.0;
        }
        score += penalty;
    }

    // Mild preference for bins with larger residuals when many bins are open.
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // Prefer keeping mean residual low (good global packing).
    score += 0.03 * mean_residual / (open_bins_count.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: prefer tight fits (small post residual), with non-linear sharpening
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; late, demand tighter packing
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * norm_pr * cap * 0.5;

    // Lookahead: reward if next item fits into post_residual (smooth logistic-ish term)
    if next_item_size > 0 {
        let fits = (norm_pr - norm_next).max(0.0);
        let gap = (norm_next - norm_pr).abs();
        score -= 6.0 * fits * fits;
        score += 4.0 * gap * gap * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0 + 15.0 * progress;
    }

    // Penalize bins whose residual deviates from mean (encourage balanced depletion),
    // with non-linear scaling by open bins count
    let openness = (open_bins_count as f64).ln().max(1.0);
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * openness * dev * dev * cap;

    // Mild reward for large items into tight bins (non-linear coupling)
    score -= 3.0 * norm_item * (1.0 - norm_pr) * (1.0 - norm_pr);

    // New-bin candidate: penalize opening a new bin unless item is huge or
    // existing residuals are very tight, smoothly interpolated
    if bin_residual == bin_capacity {
        let tightness = (1.0 - mean_residual / cap).clamp(0.0, 1.0);
        let pressure = norm_item * norm_item * (0.5 + 0.5 * progress) + tightness * 0.3;
        score += 12.0 * (1.0 - pressure.min(1.0)) + 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: perfect-fit classes are golden.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 1: exact fit -> strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }
    // Class 2: residual in the "harmonic small" band (0..=10): still very good,
    // tiny dead space unlikely to hold future items (min size 1..100 unknown, so scale-aware).
    else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // Integer-division thresholds on post_residual: residual divisible by common
    // item granularities (10, 20, 25) is reusable -> reward.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 25.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            // next fits: reward proportional to tightness of that future fit
            let future_waste = (post_residual - next_item_size) as f64;
            score -= 80.0 * (1.0 - future_waste / cap).max(0.0);
        } else {
            // next item cannot use this residual: penalize large leftovers
            score += 0.5 * pr;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Penalize creating residual that is awkward (between 51 and 74: too big to
    // ignore, too small for large items) — dead zone penalty.
    if post_residual >= 51 && post_residual <= 74 {
        score += 20.0;
    }

    // Modulo class coupling between item and residual: item size divisible by 10
    // keeps residual granularity aligned -> mild reward.
    if item_size % 10 == 0 {
        score -= 5.0;
    }

    // Stream progression: late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (1.0 - pr / cap);

    // Prefer bins below mean residual (tighter bins) mildly.
    score += 0.1 * (mean_residual - pr);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 500.0;
        } else {
            // opening a new bin is expensive if existing bins fit
            score += 150.0 + 10.0 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0, 10] are nearly unusable
    // for future items (items >= 1..100 unknown, but tiny gaps waste capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Penalize dead space relative to bin capacity (fraction wasted).
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Tight-fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 {
        score -= 15.0 * fill_ratio;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
        if post_residual < 10 {
            score -= 20.0; // still better to consume the gap now
        }
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins rather than opening new ones.
    score += 0.15 * open_bins_count as f64;

    // New-bin candidate: make empty bin attractive only when existing bins
    // would leave large dead space or when no bins fit well.
    if bin_residual == bin_capacity {
        // Baseline moderate score; beats bad fits (large post_residual + penalties),
        // loses to good fits.
        score += 10.0;
        if next_item_size as f64 > mean_residual {
            score -= 12.0; // lookahead suggests fresh capacity is useful
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0; // next item can't use this bin's remainder anyway
    }

    // Mild stream progression: late in stream, avoid leaving tiny residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 {
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / tight fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 15 {
        score -= 15.0;
    }

    // 2-step lookahead: reward when next item fits the post residual well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 50.0; // next item exactly fills this bin
        } else if gap <= 10 {
            score -= 25.0;
        } else {
            score -= 20.0 * (1.0 - gap as f64 / post_residual as f64);
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here; penalize dead space creation.
        score += 8.0;
        // Small dead space that no future item (>=10) could use is worse.
        if post_residual < 10 {
            score += 12.0;
        }
    }

    // Relative to mean residual: prefer bins tighter (smaller residual) than average.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Mild preference for consolidating into fewer bins early on.
    let progress = step_index as f64 / total_items as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: only attractive when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        // Base penalty so existing bins with reasonable fits win.
        score += 25.0;
        if post_residual >= next_item_size as u32 && next_item_size > 0 {
            score -= 20.0; // fresh bin can host the next item too
        }
        if fitting_bins_count == 0 {
            score -= 40.0; // forced: nothing else fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linearly).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to leftover.
            score += 3.0;
        }
    } else {
        // Last item: fill as much as possible.
        score -= 15.0 * tightness;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate logic: only attractive when item is large relative to
    // capacity or open-bin residuals are fragmented / high.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs() / bin_capacity as f64;
        // Prefer new bin for large items, late in stream, or when mean residual is small (poor fits elsewhere).
        let new_bin_bonus = 14.0 * item_frac * item_frac
            + 10.0 * (1.0 - fragmentation)
            + 8.0 * progress
            - 6.0 * (mean_residual / bin_capacity as f64);
        score -= new_bin_bonus;
        // Slight baseline penalty so a decent existing fit usually wins.
        score += 4.0;
    } else {
        // Existing bin: mild reward when its residual is close to item (good match).
        let match_quality = 1.0 - ((bin_residual - item_size) as f64).abs() / bin_capacity as f64;
        score -= 5.0 * match_quality;
    }

    // Encourage consolidation when many bins are open.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * tightness;

    // Early stream: keep flexibility, penalize creating tiny residuals harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual < 20 && progress < 0.3 {
        score += 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let norm_post = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;

    // Quadratic/cubic shaping of dead space, modulated by progress
    let quad = norm_post * norm_post;
    let cube = quad * norm_post;
    score += 12.0 * quad * (0.5 + progress);
    score -= 8.0 * cube * (1.0 - progress);

    // Reward tight fits (small post_residual) more strongly as stream advances
    let tightness = 1.0 - norm_post;
    score -= 15.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Penalize bins that cannot fit the likely next item from this residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 6.0 * (1.0 - pr / nx) * (0.4 + 0.6 * progress);
        } else {
            score -= 3.0 * (pr / (pr + nx)) * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + 0.5 * progress);
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).sqrt();
    }

    // Prefer bins below mean residual (fills laggards), smooth coupling
    let dev = (mean_residual - pr) / cap;
    score -= 5.0 * dev * (1.0 - progress * progress);

    // Mild pressure to open new bins when many are open and fit is loose
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * quad;

    // New-bin candidate handling: keep it competitive only when item is large
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        score -= 10.0 * fill_ratio * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Penalize residuals in "awkward" classes (odd multiples of small fractions),
    // reward residuals that land on clean division points.
    let cls = post_residual % 25;
    if cls == 0 {
        score -= 6.0; // residual divisible by 25 -> reusable by common sizes
    } else if cls == 10 || cls == 20 {
        score -= 2.0;
    } else {
        score += 4.0 * (1.0 - cls as f64 / 25.0);
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        // dead space below minimum item size is pure waste
        score += 30.0;
    }

    // Lookahead coupling: does this bin's post residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 4.0 * (next_item_size as f64 / 100.0);
        } else {
            score += 5.0;
        }
        // harmonic pairing: post_residual % next_item_size small => likely chain fit
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when existing fits are poor or none exist.
    if bin_residual == bin_capacity {
        score -= 10.0;
        if fitting_bins_count > 0 {
            score += 18.0; // discourage opening new bin when alternatives exist
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 4.0; // new bin can host a fresh pair
        }
    }

    // Late in stream: consolidate into open bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (open_bins_count as f64 / (open_bins_count.max(1) as f64 + 5.0));

    // Slight pull toward bins near the mean residual (balanced packing).
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest plausible item (<= 9) are wasted capacity. Penalize hard,
    // with a quadratic ramp so 1-2 leftovers are punished most.
    if post_residual >= 1 && post_residual <= 9 {
        score += 40.0 + (10 - post_residual as f64) * (10 - post_residual as f64) * 3.0;
    }
    // Moderately small gaps (10..20) are risky too: only large items fit,
    // and those are rare. Mild penalty scaled by stream position.
    else if post_residual > 9 && post_residual < 20 {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 * (1.0 - progress) + 4.0;
    }

    // Perfect fit is ideal: zero dead space, reward strongly.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage proliferating bins; favor consolidation
    // into existing bins, scaled by how many bins are already open.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: it always has a large post_residual, so it wins
    // naturally; add an explicit surcharge so reuse is preferred unless
    // every open bin would create dead space.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // placing here avoids opening a new bin entirely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // this placement sets up a perfect follow-up; reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    // If next item would be blocked by the residual (dead space for the
    // known future), penalize lightly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 6.0;
    }

    // Slight tie-breaker toward bins below-average fullness to balance load.
    score -= (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post residual)
    score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(4);

    // Aggressive 2-step lookahead: reward if next item fits perfectly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain
        } else if post_residual > next_item_size {
            let chain_post = post_residual - next_item_size;
            score -= 35.0 * (1.0 - chain_post as f64 / bin_capacity as f64).powi(3);
        } else {
            // next item won't fit here; penalize wasted potential
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Reward bins whose residual deviates favorably from mean (below-mean residual = fuller bin)
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        score -= 0.5 * dev.abs();
    } else {
        score += 0.3 * dev;
    }

    // Last-chance bin: strong preference to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent existing fits exist
    if bin_residual == bin_capacity {
        let best_possible = 100u32.saturating_sub(item_size);
        score += 15.0 + 0.2 * best_possible as f64;
        if fitting_bins_count > 0 {
            score += 20.0;
        }
        // late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Small penalty for many open bins to encourage consolidation
    score += 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual, but dead space below ~15 is nearly unusable.
    if post_residual < 15 {
        score -= 40.0;
    } else if post_residual <= 30 {
        score -= 15.0 * (1.0 - post_residual as f64 / 30.0);
    }

    // Exact fit is golden.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 55.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer the fullest (smallest residual).
        score += bin_residual as f64 * 0.15;
    }

    // Lookahead coupling: if next item fits into post_residual, this is a great chain.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0 + 0.5 * next_item_size as f64;
        } else {
            // Penalize leaving residual that next item cannot use but could fragment.
            let wasted = (post_residual as f64 - next_item_size as f64).abs();
            if next_item_size > post_residual && post_residual < next_item_size / 2 {
                score += 10.0;
            }
            let _ = wasted;
        }
    }

    // Global state: many open bins -> favor filling existing bins, discourage new bins.
    let openness = open_bins_count as f64;
    score += openness * 0.5;

    // Mean residual coupling: if this bin is emptier than average, deprioritize it slightly.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate handling: empty bin gets a baseline penalty unless item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        let no_fitting = fitting_bins_count == 0;
        if no_fitting || (large_item && progress < 0.8) {
            score -= 25.0;
        } else {
            score += 70.0 + 30.0 * progress;
        }
    }

    // Time horizon: late in stream, be more conservative, prefer compacting existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    // Mild preference for bins whose residual is just above item size.
    let slack = (bin_residual - item_size) as f64;
    score += 0.05 * (slack - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit_ratio = item_size as f64 / cap;

    // Base: prefer tight fits, with non-linear (quadratic/cubic) coupling to progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Non-linear dead-space penalty: small post-residuals are good, mid-size bad
    score += 12.0 * norm_pr * norm_pr * (1.0 - progress);

    // Reward near-exact fits more strongly as stream progresses
    score -= 8.0 * (1.0 - norm_pr).powi(3) * (0.5 + 0.5 * progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead coupling: if next item fits the post-residual, reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let snug = 1.0 - ((pr - nx) / cap).abs();
            score -= 6.0 * snug * (1.0 - progress * 0.5);
        } else {
            // penalize residuals that strand the next item
            score += 4.0 * (nx - pr) / cap * (1.0 - progress);
        }
    }

    // Scarcity pressure: many open bins with low mean residual -> consolidate
    let scarcity = mean_residual / cap;
    score += 3.0 * scarcity * (open_bins_count as f64).sqrt() * (1.0 - progress);

    // Slight preference for filling larger fraction of bin early
    score -= 4.0 * fit_ratio * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Residuals in "useful" classes (small enough
    // to be fillable by typical items, or large enough to stay flexible)
    // are rewarded; awkward middle classes are penalized.
    let q = (post_residual * 4) / bin_capacity; // 0..=3 quartile class
    match q {
        0 => score -= 12.0, // near-perfect fill
        1 => score += 4.0,  // awkward small dead space
        2 => score += 1.0,  // moderate leftover
        _ => score -= 3.0,  // still roomy
    }

    // Fine harmonic bonus: post_residual divisible-friendly to common sizes
    let pr = post_residual;
    if pr > 0 && (pr % 10 == 0) {
        score -= 2.0;
    }
    if pr > 0 && (pr % 25 == 0) {
        score -= 3.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward; if next item cannot fit into post_residual, mildly
    // penalize unless post_residual is already tiny.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            score -= 5.0;
        } else {
            score += (next_item_size - pr) as f64 * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, heavily reward to
    // avoid opening a new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has a huge residual, so its
    // raw score is already high; add a fixed bias so it only wins when no
    // open bin offers a decent fit (poor fits accumulate large penalties).
    if bin_residual == bin_capacity {
        score += 8.0;
    } else {
        // Reward packing into bins that are already partially filled
        // (best-fit pressure beyond raw post_residual).
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill * 6.0;
    }

    // Stream progression: early on, prefer keeping bins flexible (favor
    // larger post_residual); late in the stream, squeeze tight.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += t * 4.0 - 2.0;

    // Spread penalty: if this bin's residual deviates wildly from the mean,
    // discourage creating fragmentation imbalance.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.03;

    // Tie-break with a deterministic smooth function of the item's harmonic
    // class so equal-residual candidates differ sensibly.
    let cls = (item_size * 8) / bin_capacity;
    score += cls as f64 * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small nonzero gaps are the worst outcome: nothing (min size 1..) reliably
    // fits, yet the space is "used". Penalize the unusable band heavily.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual as f64) * 8.0; // dead-space band penalty
    }
    // Perfect fit is golden: subtract a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual >= 10 {
        // Usable residual: reward proportionally, but only mildly (tight fits preferred).
        score -= (post_residual as f64).sqrt() * 1.5;
    }

    // --- Last-chance pressure ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // This is the only open bin that fits; strongly prefer using it
        // over opening a new bin, unless the fit is truly terrible.
        score -= 25.0;
    }

    // --- Open-bin pressure: discourage spawning many bins ---
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus growing penalty with open bins,
        // relaxed only if existing fits would create dead space.
        score += 30.0 + (open_bins_count as f64) * 2.0;
        if post_residual < 10 {
            score += 20.0; // opening a bin for a dead-space fit is bad
        }
        if fitting_bins_count <= 1 {
            score -= 35.0; // no good alternative exists -> open freely
        }
    }

    // --- Lookahead: if next item fits the post-residual exactly-ish, reward ---
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 12.0; // sets up a near-perfect fit for the next item
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 6.0; // residual likely unusable for the incoming item
    }

    // --- Mean-residual coupling: prefer bins below mean residual (tighter bins) ---
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // --- Mild stream-progression tightening: later in stream, prefer tighter fits ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post_residual super-linearly.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // 2-step lookahead: if the next item exactly fills the post_residual, big reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + diff);
        // Perfect chaining: next item exactly fills leftover space.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving space the next item cannot use at all (wasted dead space).
        if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    } else {
        // Last item: only the absolute tightest fit matters.
        score += 10.0;
    }

    // Compare against mean residual: bins already fragmented are less attractive.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual <= 5 {
            score -= 20.0; // near-perfect fit, absolutely take it
        }
    }

    // New-bin candidate: neutral baseline, slightly penalized so existing bins
    // with good lookahead matches win; but if all open fits are poor, the
    // empty-bin score stays competitive.
    if bin_residual == bin_capacity {
        score += 5.0;
        // Opening a new bin is attractive when the item is large relative to capacity.
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
    }

    // Slight preference to fill older bins (consolidation) as stream progresses.
    score += (step_index as f64 / (total_items.max(1) as f64)) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit: tight fits strongly preferred.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize leaving dead space that no future item could plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable slivers are wasted capacity
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if next_item_size > bin_residual {
            // next item won't fit anywhere in this bin anyway; neutral
            score += 1.0;
        } else {
            score += 4.0; // this placement kills the bin for the known next item
        }
        // If next item exactly matches post residual, strongly favor chain packing.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a bin is expensive; only attractive when
    // current bins are crowded or the item is large and fits poorly everywhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual / (bin_capacity as f64);
        let mut new_bin_cost = 14.0 + 6.0 * (1.0 - crowded); // costlier when bins are roomy
        new_bin_cost -= 4.0 * progress; // slightly cheaper to open bins late in stream
        if item_size >= 60 {
            new_bin_cost -= 5.0; // big items often deserve fresh bins
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            new_bin_cost -= 3.0; // fresh bin can chain current + next item
        }
        if post_residual == bin_capacity {
            score += new_bin_cost.max(0.0);
        }
    } else {
        // Mild preference for filling bins that are already quite full.
        let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 3.0 * fill * fill;

        // Penalize spreading across many open bins when residual is high.
        if (bin_residual as f64) > mean_residual + 15.0 {
            score += 2.0;
        }
    }

    // Small global load-balancing nudge: prefer bins below mean residual slightly
    // (keeps some large-capacity bins available for big arrivals).
    if (bin_residual as f64) < mean_residual {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, non-linearly penalized.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space becomes more costly (less future to absorb it).
    let late = progress * progress;
    score += 25.0 * late * (norm_pr - 0.5) * (norm_pr - 0.5) * cap * 0.1;

    // Reward near-perfect fits more strongly as stream progresses.
    let fit_quality = 1.0 - norm_pr;
    score -= 15.0 * fit_quality * fit_quality * fit_quality * (0.5 + progress);

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 30.0 * progress;
    }

    // New-bin candidate: penalize mildly, but allow it when open bins have large residuals.
    if bin_residual == bin_capacity {
        let spread = mean_residual - pr;
        score += 10.0 - 0.05 * spread.max(0.0);
        score += 8.0 * (1.0 - progress);
    }

    // Lookahead coupling: if next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 12.0 * (1.0 - gap / cap).max(0.0);
    } else {
        // Last item: strongly prefer minimal waste.
        score -= 20.0 * fit_quality;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fraction bands
    let pr = post_residual as f64;
    let frac = pr / cap;
    // Dead-space penalty grows super-linearly for unusable small residuals
    if post_residual > 0 {
        let dead = if post_residual < 10 { 60.0 } else if post_residual < 20 { 25.0 } else { 0.0 };
        score += dead;
    }

    // Perfect-fit harmonic reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // bonus scaled by how snugly next item fits
            let snug = 1.0 - ((post_residual - next_item_size) as f64) / cap;
            score -= 15.0 + 20.0 * snug;
        } else {
            // post_residual unusable for next item: penalize more if residual is tiny
            score += 10.0 + 30.0 * (1.0 - frac);
        }
    } else {
        // last item: prefer tightest fit
        score += 0.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: mild penalty so it's chosen only when fits are bad,
    // but scaled down when open bins are numerous and residuals fragmented
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / cap);
        score += 45.0 - 0.5 * pressure;
        // if next item is large, opening fresh bin is less attractive
        if next_item_size > 50 {
            score += 10.0;
        }
    }

    // Stream progression: late in stream, consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold the
    // minimum item (1..10) are pure waste — penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 2.0;
    }
    // Gaps too small for the lookahead item are also likely dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Reward exact / near-exact fills.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Coupling with lookahead: if the next item fits exactly in the
    // post-residual, this placement is excellent.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; with few bins, spreading is cheaper.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 6.0;

    // Prefer bins whose residual is already below the mean (consolidation).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., this item would create large dead space elsewhere) or the
    // item is large relative to capacity.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = bin_capacity as f64
            - 25.0 * tightness
            - 18.0 * scarcity
            - 10.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead: reward when next item fits snugly into post_residual ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt <= pr {
            // slack after hypothetically placing the next item too
            let slack2 = pr - nxt;
            score -= 30.0 * (1.0 - slack2 / bin_capacity as f64);
            // perfect chain match bonus
            if slack2 == 0.0 {
                score -= 40.0;
            }
        } else {
            // next item won't fit here: penalize leaving a large unusable-ish gap
            score += 0.4 * (nxt - pr);
        }
        // pair-fill ratio coupling
        let pair_fill = (item_size as f64 + nxt) / bin_capacity as f64;
        if pair_fill <= 1.0 {
            score -= 20.0 * pair_fill * pair_fill;
        }
    }

    // --- tight fit reward relative to mean residual ---
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    if (post_residual as f64) < mean_residual {
        score -= 5.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;
    } else {
        score += 5.0 * (post_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // --- last-chance bin: strongly favor using it to avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- penalize opening a new bin when a decent fit exists elsewhere ---
    if bin_residual == bin_capacity {
        let waste = bin_capacity - item_size;
        score += 20.0 + 0.3 * waste as f64;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
        // early stream: be more willing to open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // --- avoid creating dead space that nothing (10..80 typical) can use ---
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable sliver
    }
    if post_residual >= 80 {
        score -= 3.0; // still broadly reusable
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: residual-based non-linear coupling
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.85 {
        score -= 40.0 * fit_ratio;
    } else {
        score += 10.0 * (1.0 - fit_ratio);
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Dead space penalty relative to capacity
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Lookahead: does post_residual accommodate next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // we consumed space the next item could have used
            score += 12.0 * (1.0 - (post_residual as f64 / next_item_size as f64));
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // penalize opening a new bin generally
        score += 35.0 + 5.0 * open_bins_count as f64;
        // but if no open bin fits (only candidate), it's forced: neutralize penalty
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // if next item is large and mean residual is fragmented, opening fresh bin is fine
        if next_item_size > 60 && mean_residual < next_item_size as f64 {
            score -= 20.0;
        }
    }

    // Global state: prefer packing into bins whose residual is below mean (consolidate)
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    // Time horizon: late in stream, be greedier about tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = fitting_bins_count as f64;
    let open = open_bins_count as f64;

    // Base: quadratic in normalized post residual (favor small dead space)
    let mut score = pr * (1.0 + norm_pr * norm_pr);

    // Smooth polynomial coupling of post residual with stream progress
    let p = progress;
    score += pr * (0.5 * p * p + 1.5 * p * (1.0 - p)) * norm_pr;

    // Tightness reward: near-perfect fits get strong discount, modulated by progress
    let tightness = 1.0 - norm_pr;
    score -= (item_size as f64 / cap) * tightness * (2.0 + 3.0 * p * p);

    // Last-chance bonus (smoothly weighted)
    let last_chance = 1.0 / fit;
    score -= pr * last_chance * (1.0 + p);

    // Penalize when this bin's residual diverges from mean residual (balance pressure)
    score += ((pr - mean_residual).abs() / cap) * (10.0 + 20.0 * p) / (1.0 + open);

    // Lookahead: if next item fits in post residual, reward; else penalize
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= (nx / cap) * (5.0 + 10.0 * p);
        } else {
            score += ((nx - pr) / cap) * (8.0 + 12.0 * p);
        }
    }

    // New-bin candidate: slightly penalized early, allowed late when fits are scarce
    if bin_residual == bin_capacity {
        score += 5.0 - 10.0 * p * p - 3.0 * last_chance;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into
    // "perfect fit" classes (multiples of small divisors of capacity)
    // leave reusable space; odd dead-space classes are penalized.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // capacity fraction

    // Perfect-fit reward: post_residual near zero
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 100.0;
    }

    // Modular classes on post_residual: residuals divisible by 10 or 25
    // are more likely to match future item sizes (harmonic classes).
    if post_residual % 10 == 0 {
        score -= 40.0;
    }
    if post_residual % 25 == 0 {
        score -= 60.0;
    }
    if post_residual % 50 == 0 {
        score -= 80.0;
    }
    // Penalize awkward odd residuals (unlikely to be filled)
    if post_residual % 2 == 1 && post_residual < 20 {
        score += 25.0;
    }

    // Integer-division thresholds: how many "typical" items (size ~10/25/50)
    // could still fit in the post residual.
    let small_fit = post_residual / 10;
    let med_fit = post_residual / 25;
    score -= 15.0 * small_fit as f64;
    score -= 10.0 * med_fit as f64;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / cap);
        } else {
            // next item does not fit here: mild penalty scaled by overflow gap
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 * (gap / cap).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, prefer tighter fits (already via post_residual)
        score += 5.0 * (fitting_bins_count as f64 - 1.0).min(10.0);
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so it is
    // chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 60.0;
        // late in the stream, opening new bins is less harmful
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * progress;
    }

    // Dead-space penalty: residual too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Mean-residual coupling: prefer bins below the mean residual (tighter bins)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Mild preference for consolidating into fewer bins when many are open
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (non-linear).
    if post_residual > 0 && post_residual < 10 {
