    // Dead space relative to capacity, superlinear.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * frac * frac;

    // Pressure from many open bins: prefer existing bins when crowded.
    score -= open_bins_count as f64 * 0.5;

