    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Early in stream: be more willing to open bins (mild penalty on tight fits).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Slightly favor bins tighter than average residual (best-fit tendency).
    score += (bin_residual as f64 - mean_residual).max(0.0) * 0.1;

    // New empty bin candidate: penalize unless current placement is very poor.
    if bin_residual == bin_capacity {
        score += 10.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
