        } else if post_residual > next_item_size {
            let gap = post - nxt;
            // Small leftover after next item is fine; large leftover is waste.
            score -= 15.0 * (1.0 - gap / bin_capacity as f64);
            // Penalize unusable slivers (<10) after the next placement.
            if gap < 10.0 && gap > 0.0 {
                score += 8.0;
            }
        } else {
            // Next item won't fit here after this placement: dead space risk.
            let miss = nxt - post;
            score += 5.0 + 0.25 * miss;
        }
    } else {
        // Last item: prefer tightest fit.
        score -= 10.0;
    }

    // Reward tight fits (small post_residual relative to mean residual).
    score -= 10.0 * (1.0 - post / bin_capacity as f64);
    if post < mean_residual {
        score -= 4.0;
    } else {
        score += 3.0 * ((post - mean_residual) / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Mild bonus for using bins with small residual (best-fit flavor).
    if post_residual < 20 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize very small post-residuals that are unlikely to fit future items,
    // unless the item almost perfectly fills the bin (post_residual near 0 is great).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fill bonus
    }

    // Last-chance bonus: if this is the only bin that fits, using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate logic: opening a new bin wastes current capacity.
    if bin_residual == bin_capacity {
        // Prefer new bin only if the best existing fit would leave awkward dead space
        // or this bin is a near-perfect fill for a large item.
        let perfect = post_residual == 0 || (item_size as f64 / bin_capacity as f64) > 0.9;
        if perfect {
            score -= 20.0;
        } else {
            score += 15.0 + 0.1 * open_bins_count as f64;
        }
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 5.0; // dead space for the lookahead item
        }
        // If the next item exactly matches post_residual, huge bonus.
        if post_residual == next_item_size {
            score -= 18.0;
        }
    }

    // Global state: when many bins are open with slack, consolidate into them
    // rather than spreading; when few bins, be choosier.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * mean_residual * (1.0 - fit_ratio);
    score -= progress * 6.0 * fit_ratio; // late in stream, prioritize tight fits harder

    // Mild penalty for leaving residuals that are hard-to-fill sizes (e.g. 1..=9 handled above),
    // plus general small-residual aversion scaled by open bin count.
    if post_residual > 0 && post_residual < 20 {
        score += 0.3 * post_residual as f64 * (open_bins_count as f64 / 10.0).min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear polynomial shaping of post-residual
    let mut score = pr as f64
        - 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * pr
        + 8.0 * norm_pr * norm_pr * pr;

    // Smooth interaction: dead-space penalty grows with stream progress
    let dead = norm_pr * norm_pr;
    score += 30.0 * dead * (0.5 + progress);

    // Coupling with mean residual: discourage bins far from the fleet mean
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev * cap * 0.01;

    // Last-chance bonus: if this is the only fitting bin, reward using it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: if next item fits smoothly into post-residual, reward
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            let slack = (pr - ns) / cap;
            score -= 10.0 * (1.0 - slack * slack);
        } else {
            score += 5.0 * ((ns - pr) / cap);
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64) * 0.05 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space classes: residuals that are unlikely to host future items
    // (very small leftovers) get penalized; mid-range residuals are fine.
    let r = post_residual;
    if r > 0 && r < 10 {
        score += 60.0; // tiny dead space
    } else if r < 20 {
        score += 15.0;
    }

    // Harmonic class of post_residual modulo 10: leftovers near multiples
    // of 10 are more reusable for integer-sized items.
    let m = r % 10;
    score -= (10 - m) as f64 * 1.5; // reward residuals close above a decade boundary

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 500.0;
        } else if next_item_size <= r {
            // next item fits: residual is reusable
            score -= (next_item_size as f64) * 0.8;
            // extra reward if next item leaves a good class again
            let nr = r - next_item_size;
            if nr % 10 == 0 { score -= 40.0; }
        } else {
            // next item cannot use this residual: penalize proportionally
            score += ((next_item_size - r) as f64).min(30.0) * 0.5;
        }
    }

    // Last chance: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: prefer filling existing bins unless this bin
    // is empty and current bins are fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is penalized by how many bins are open and how
        // fragmented they are; rewarded slightly late in the stream.
        score += 80.0 + (open_bins_count as f64) * 5.0
                 - mean_residual * 0.3
                 - (step_index as f64 / total_items.max(1) as f64) * 30.0;
        // But if existing bins would leave tiny dead space, new bin wins.
        if item_size < bin_capacity && (bin_capacity - item_size) > r {
            // r here is bin_residual - item_size for real bins; for new bin r==capacity-item_size
        }
        if post_residual >= 20 {
            score -= 10.0; // a fresh bin keeps a healthy residual
        }
    }

    // Tight fit reward: fraction of bin used by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 40.0;

    // Prefer bins with lower residual overall (best-fit bias) when many bins fit.
    if fitting_bins_count > 2 {
        score += (bin_residual as f64) * 0.1;
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Penalize creating residual that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 8.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.6 * (0.5 + progress);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize slightly so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score += 12.0 + mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match of post_residual
    // with the next item's size (perfect chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }

    // Reward near-matches: post_residual slightly larger than next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize post_residual that cannot fit the next item (dead space risk),
    // scaled by how close it just missed.
    if next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        score += 5.0 + 15.0 * (1.0 - miss / 100.0);
    }

    // Compare against mean residual: prefer bins that tighten the average
    // (large residual bins get used, small residual bins preserved).
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mild penalty for opening a new bin when open bins could fit.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.1 * open_bins_count as f64;
        // New bin is attractive if next item is large and current fit is poor.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 25.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Penalize waste relative to the bin's current residual.
    if bin_residual > 0 {
        let fill = item_size as f64 / bin_residual as f64;
        score -= fill * 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count <= 1 {
        score -= 60.0;
    } else {
        // Mild penalty when many bins compete (spread usage is fine).
        score += (fitting_bins_count as f64).ln() * 3.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else {
            // Dead space the next item cannot use: penalize proportionally.
            let gap = (next_item_size as f64 - post_residual as f64).min(next_item_size as f64);
            score += gap * 0.35;
        }
        // Perfect chain: post_residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    } else {
        // Last item: just minimize leftover.
        score += post_residual as f64 * 0.5;
    }

    // Global pressure: many open bins with small mean residual -> prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if mean_residual < item_size as f64 * 1.5 {
        score -= 10.0;
    }
    score += (open_bins_count as f64) * (1.0 - progress) * 0.4;

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // More attractive late in the stream or when current bin choice is poor.
        if post_residual as f64 > bin_capacity as f64 * 0.5 {
            score += 10.0; // placing a small item in a fresh bin wastes it
        } else {
            score -= 8.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Non-linear coupling: penalize leaving residuals in the "awkward zone" (too small for most items).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let fit = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Core: penalize post_residual with non-linear curvature
    let mut score = norm_pr * (1.0 + 1.6 * norm_pr * norm_pr);

    // Smooth interaction with stream progress: later, prefer tighter fits more
    score += 0.9 * t * norm_pr;

    // Reward filling bins that exactly match next item (lookahead coupling, smooth)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs() / cap;
        score += 0.7 * gap * gap;
    }

    // Penalize scarce fitting options mildly (last-chance bonus via subtraction)
    if fitting_bins_count <= 1 {
        score -= 1.2;
    }

    // Small pull toward mean residual to balance load
    score += 0.15 * (norm_pr - mean_residual / cap).abs();

    // Slight penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 0.4 + 0.05 * open_bins_count as f64;
    }

    // Tiny fit-quality reward: large item fraction filling bin
    score -= 0.5 * fit * fit;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose post_residual is small.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Harmonic classes: classify post_residual by integer division into
    // usable "slots" for typical item sizes. Residuals that cannot host
    // any future small item (<= 10) are dead space -> penalize.
    if post_residual > 0 {
        let slot_class = post_residual / 10; // harmonic class of decade
        if slot_class == 0 {
            // unusable dead space (< 10)
            score += 22.0;
        } else {
            // reward residuals that can host common sizes: 10,20,...,80
            let hosts = (post_residual / 10).min(8) as f64;
            score -= 2.0 * hosts;
        }
        // Modulo structure: residuals that are multiples of 10 pair well
        // with the known size grid; penalize awkward remainders.
        let r = post_residual % 10;
        if r != 0 {
            score += 1.5 + 0.1 * r as f64;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        if post_residual - next_item_size < 10 {
            score -= 8.0; // near-perfect two-item packing
        }
    } else if next_item_size > post_residual && post_residual < 10 {
        score += 6.0; // dead space with no lookahead utility
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening new.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual
    // space of all open bins; only attractive when existing bins are poor.
    if bin_residual == bin_capacity {
        let waste = mean_residual * (open_bins_count as f64);
        score += 30.0 + 0.05 * waste;
        // Early in the stream, fewer open bins -> cheaper to open new? No:
        // long streams amortize; late in stream prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        // If no open bin can fit, this call is the only option; make it win.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If mean residual is large (bins are fragmented), opening new is fine.
        if mean_residual > 40.0 {
            score -= 8.0;
        }
    }

    // Prefer bins already below mean residual (consolidate emptier bins,
    // keep fuller bins' structure intact is the opposite: prefer placing
    // into fuller bins to free them). Penalize bins with residual above mean.
    if bin_residual != bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.15 * diff;
    }

    // Mild penalty for spreading across many bins late in the stream.
    if open_bins_count > 0 && bin_residual != bin_capacity {
        score -= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // are heavily penalized (they are effectively wasted capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward very tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Favor bins whose residual is close to the item size (good fill ratio).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 6.0;
    }

    // Open-bin pressure: discourage spreading across too many bins.
    score += 2.0 * open_bins_count as f64;

    // Prefer bins below the mean residual (consolidate space).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when current bins fit poorly
    // (large item relative to residual) or many bins already open.
    if bin_residual == bin_capacity {
        let desperation = (item_size as f64 / bin_capacity as f64) * 30.0
            + (open_bins_count as f64 / 10.0) * 10.0;
        score = 100.0 - desperation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness;

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // reward proportional to how close next item fills the remainder
            score -= 12.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // next item cannot fit in the leftover: penalize wasted space
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.08 * overflow;
        }
    }

    // Compare post_residual against mean residual: avoid leaving this bin
    // far below average (fragmentation), but reward leaving it exactly average
    if post_residual as f64 > mean_residual + 1.0 {
        score += 0.05 * (post_residual as f64 - mean_residual);
    } else {
        score -= 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity or no real bin offers a decent fit
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // penalize opening new bin by default
        score += 20.0;
        // but if item is big, new bin is fine (fresh space for future items)
        score -= 25.0 * fill_ratio;
        // if many bins already open and mean residual is high, opening is ok
        if mean_residual > 40.0 && open_bins_count > 2 {
            score -= 10.0;
        }
    }

    // Slight preference to fill bins progressively through the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize leaving residuals that are too small for typical future items
    // but too large to be "dead" — awkward middle zones.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 12.0; // near-dead space
    } else if pr >= 10.0 && pr <= 40.0 {
        // usable zone: mild reward scaled by usability
        score -= 8.0 * (pr / 40.0);
    }

    // Lookahead: if next item fits into post_residual, big reward.
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 20.0;
            // extra reward if next item fits nearly exactly
            let gap = pr - next_item_size as f64;
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here: slight penalty proportional to overshoot
            score += 5.0 * ((next_item_size as f64 - pr) / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large or existing residuals are fragmented.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 25.0;
        // cheaper to open a new bin early in the stream (long horizon ahead)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // if many open bins with high mean residual, prefer consolidation instead
        score += 0.4 * open_bins_count as f64;
        score += 0.3 * (mean_residual - pr).max(0.0);
        // large items pack better into fresh bins
        score -= 0.25 * item_size as f64;
    }

    // Slight preference for bins with residual close to item_size (perfect fill).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * fit_gap;

    // Mild penalty for spreading across too many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer minimal post residual (tight fit), with non-linear shaping.
    let mut score = post + 0.35 * (post * post) / cap;

    // Smooth polynomial coupling of tightness with stream progress:
    // early on, mild waste is tolerable; late in the stream, waste is costly.
    let tightness = 1.0 - post / cap; // 0..1, higher = tighter fit
    score -= 6.0 * tightness * (1.0 + progress * progress) * (1.0 + tightness * tightness);

    // Lookahead: reward if next item fits into post residual, penalize otherwise
    // (scaled by how far the next item is from fitting).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post {
            score -= 5.0 * (1.0 + progress);
        } else {
            let gap = (next - post) / cap;
            score += 4.0 * gap * (1.0 + gap);
        }
    }

    // Penalize opening a brand-new bin when other bins could fit, especially late.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 8.0 + 12.0 * progress;
    } else if bin_residual == bin_capacity {
        // new bin with no alternative: mild bonus to keep it attractive
        score -= 2.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly reward using it to avoid proliferation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0 * (1.0 + progress);
    }

    // Prefer spreading across bins when mean residual is high (many half-empty bins).
    score += 0.05 * (mean_residual - post).abs();

    // Mild penalty for accumulating too many open bins.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod small divisors
    let pr = post_residual;
    // Dead-space penalty: residuals that are awkward (small but nonzero) are bad
    if pr > 0 && pr < 10 {
        score += 25.0;
    }
    // Perfect fit reward
    if pr == 0 {
        score -= 40.0;
    }
    // Harmonic classes: residual divisible by 10 or 25 is more reusable
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 6.0;
    }
    if pr % 5 == 0 && pr > 0 {
        score -= 2.0;
    }

    // Coupling with next item: does post_residual accommodate the lookahead item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 12.0;
            // bonus if post_residual leaves a still-decent remainder
            let after_next = pr - next_item_size;
            if after_next % 10 == 0 {
                score -= 4.0;
            }
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0;
        // But if lookahead item equals item_size, fresh bin pairs them well
        if next_item_size == item_size {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual is close to item (tight fit) relative to mean residual
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.05;

    // Prefer fuller bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - bin_residual) as f64 * 0.02 * (1.0 + progress);

    // Mild pressure against accumulating many open bins
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 1, practically ~10)
    // can ever use are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny unusable gap
        } else if post_residual < 20 {
            score += 25.0; // likely dead space
        } else if post_residual < 35 {
            score += 8.0; // marginally usable
        }
    } else {
        score -= 40.0; // perfect closure is excellent
    }

    // Reward tight fits relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Pressure from number of open bins: discourage proliferation of open bins
    // unless the fit is genuinely good.
    score += 3.0 * open_bins_count as f64 * (1.0 - fit_ratio.min(1.0));

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // Penalize leaving a gap the next item almost fits but wastes.
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        score += 15.0;
    }

    // New-bin candidate: prefer opening a new bin only when the current bin fit is poor
    // (large post_residual) or open-bin pressure is high.
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: its residual equals capacity
        score = (bin_capacity as f64) - 20.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // fresh bin accommodates lookahead well
        }
        if fitting_bins_count <= 1 {
            score -= 30.0; // no good alternative exists
        }
    }

    // Slight stream-progression nudge: as stream advances, favor consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 100.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // next item won't fit here; penalize proportional to wasted gap
            score += 50.0 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening new bins when an open bin fits reasonably
    if bin_residual == bin_capacity {
        score += 300.0 + post_residual as f64;
        if fitting_bins_count > 0 {
            score += 150.0;
        }
    }

    // Slight preference for filling bins as stream progresses
    score *= 1.0 - 0.1 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Penalize when the bin residual was much larger than the item (wasteful fill).
    let waste = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 15.0 * waste * waste;

    // Lookahead coupling: if next item fits in post_residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when few bins fit the item or mean residual is high.
    if bin_residual == bin_capacity {
        let openness = if fitting_bins_count == 0 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
        let mean_pressure = mean_residual / bin_capacity as f64;
        score = 60.0 - 30.0 * openness - 20.0 * mean_pressure;
        // Early in stream, new bins are cheap; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
    }

    // Mild penalty for spreading across many open bins.
    score += (open_bins_count as f64).ln() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual
    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = 1.0 + 0.8 * t - 1.6 * t * t + 1.2 * t * t * t;
    score += 30.0 * x * poly;

    // Penalize small-but-unusable residuals smoothly (dead space term)
    let dead = (1.0 - x).max(0.0) * (x * (1.0 - x)) * 4.0;
    score -= 40.0 * dead;

    // Lookahead: reward residuals that fit the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let tight = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 15.0 * tight;
    } else if next_item_size > 0 {
        score += 10.0 * (next_item_size as f64 - pr) / cap;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Prefer bins below mean residual (tighter packing) with smooth term
    score += 0.05 * (mean_residual - pr) * (0.5 + t);

    // Mild penalty for proliferating bins late in stream
    score += (open_bins_count as f64).ln() * (1.0 + 2.0 * t);

    // New-bin candidate: make it moderately attractive only for large items / poor fits
    if bin_residual == bin_capacity {
        let waste = 1.0 - item_size as f64 / cap;
        score += 8.0 + 25.0 * waste * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small residue" classes (0..10) are near-perfect; reward heavily.
    let pr = post_residual;
    let class = pr / 10; // integer division threshold classes 0..10
    score -= (10 - class as i32).max(0) as f64 * 3.0; // tighter fit -> lower score

    // Exact-fill is ideal
    if pr == 0 { score -= 50.0; }

    // Dead-space penalty: leftover too small for the smallest plausible item (1..100)
    if pr > 0 && pr < 10 { score += 25.0; }

    // Lookahead coupling: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // harmonic subclass: how close is the follow-up fit
            let slack = pr - next_item_size;
            let slack_class = slack / 10;
            score -= 12.0 - slack_class as f64; // perfect chain reward
        } else {
            // next item won't chain here; penalize proportionally to wasted chain potential
            score += 8.0 + (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 30.0;
        // but if no open bin fits well (post residual here is large), new bin is fine
        if next_item_size > 0 && item_size >= 70 {
            score -= 15.0;
        }
    }

    // Fraction-of-capacity harmonic: reward using a large fraction of the bin
    let fill_frac = item_size as f64 / cap;
    score -= fill_frac * 10.0;

    // Mean residual coupling: prefer bins with residual far below mean (concentrate waste)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Modulo-5 residue texture on post_residual: residues near multiples of 5
    // tend to chain with typical item granularity
    let m = pr % 5;
    if m == 0 { score -= 3.0; } else { score += m as f64 * 0.8; }

    // Stream progression: late in stream, avoid opening bins / prefer tight fills
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= t * 5.0 * fill_frac;
    score += t * (post_residual as f64) * 0.05;

    // Many open bins: discourage spreading, favor best fits more strongly
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible item are pure waste. Penalize them hard.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) {
        score += 1000.0;
    }
    // General dead-space pressure: quadratic in smallness of the gap.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 20.0 {
        score += (20.0 - pr) * (20.0 - pr) * 0.5;
    }

    // Reward tight fits (best-fit flavor) super-linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * fit_ratio * 30.0;

    // Penalize leaving a gap that exactly fails to fit the next item
    // (lookahead-aware dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + 0.2 * (next_item_size - post_residual) as f64;
    }
    // Reward leaving a gap that perfectly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise a new bin must be opened.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin is a fallback. Make it attractive
    // only when current fit is poor (large post_residual) or many bins already open.
    if bin_residual == bin_capacity {
        let poor_fit = pr > 0.5 * bin_capacity as f64;
        if poor_fit || fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 25.0;
        }
    }

    // Mild stream-progression term: as the stream ends, prefer consolidating
    // into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 3.0 * (pr / bin_capacity as f64);

    // Deviation from mean residual: prefer bins whose residual is already low
    // (well-packed bins) to concentrate waste.
    score += (mean_residual - pr).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact/near match between post_residual and next item.
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain: post residual exactly fits next item -> big reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits with slack: mild reward proportional to tightness.
            score -= 25.0 * (1.0 - match_gap / bin_capacity as f64);
        } else {
            // Next item does NOT fit: penalize proportional to how much we "wasted" toward the next item.
            score += 20.0 * match_gap / bin_capacity as f64;
        }
    }

    // Dead-space penalty: small residuals (< smallest plausible item) are unusable.
    if post_residual < 10 {
        score += 30.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Compare against mean residual across open bins: bins with residual well below
    // mean are "tight" and should be preferred for filling.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it unattractive unless no good fit exists elsewhere.
    // Its post_residual is large (capacity - item), which already scores high; add
    // a fixed penalty so open bins win when their fit is reasonable.
    if bin_residual == bin_capacity {
        score += 40.0;
        // Late in the stream, opening a fresh bin is even less desirable.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
    }

    // Mild preference to keep many open bins balanced rather than stacking.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements that leave little waste.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that no future item (>= 10 or >= 1 generically) can use.
    if post_residual > 0 && post_residual < 8 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.05 * next_item_size as f64;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate logic: only open a new bin when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = fit_ratio < 0.45 && post_residual as f64 > mean_residual * 0.5;
        if poor_fit_elsewhere {
            score -= 20.0;
        } else {
            score += 35.0;
        }
        // Early stream: opening bins is cheaper; late stream: consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress - 10.0 * (1.0 - progress);
    }

    // Global state coupling: many open bins with high mean residual -> consolidate.
    if open_bins_count > 4 {
        score += 0.4 * open_bins_count as f64 - 0.15 * mean_residual;
    }

    // Prefer placing large items into fuller bins (best-fit-by-absolute-space).
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;

    // Base: penalize wasted residual, with non-linear (quadratic) waste growth.
    let mut score = pr + 40.0 * pr_norm * pr_norm;

    // Smooth polynomial coupling between post_residual and stream progress.
    // Early stream: prefer tight fits but tolerate moderate residuals.
    // Late stream: strongly penalize any residual since remaining chances shrink.
    let coupling = (1.0 - progress) * (pr_norm * (1.0 - pr_norm)) * 30.0
                 + progress * pr_norm * pr_norm * 60.0;
    score -= coupling * 0.5;
    score += progress * pr * pr / cap;

    // Reward bins whose residual closely matches a plausible future item (smooth kernel).
    if next_item_size > 0 {
        let d = (pr - next_item_size as f64).abs();
        let kernel = (-d * d / (2.0 * 15.0 * 15.0)).exp();
        score -= 12.0 * kernel;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it attractive when residuals across open bins are large,
    // i.e. when current bins are fragmented; penalize opening when a good fit exists.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        // Opening a new bin is favored if mean residual is high (poor fits everywhere)
        // and this item would leave little usable space in existing bins.
        let would_fragment = (pr_norm < 0.35) as i32 as f64;
        score += 20.0 - 35.0 * fragmentation - 10.0 * (1.0 - pr_norm) * would_fragment;
        // Slight early-stream reluctance to open bins, growing late.
        score += 10.0 * (1.0 - progress);
    } else {
        // Slight preference for bins below mean residual (consolidating space).
        score -= 5.0 * (mean_residual - pr) / cap;
    }

    // Mild penalty for many open bins to discourage needless spread.
    score += 0.5 * open_bins_count as f64 * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;

    // Reward near-perfect fits (post_residual in lowest harmonic band)
    if post_residual <= bin_capacity / 20 {
        score -= 25.0;
    } else if post_residual <= bin_capacity / 10 {
        score -= 12.0;
    } else if post_residual <= bin_capacity / 5 {
        score -= 5.0;
    }

    // Penalize dead space in the "dead zone" (too small for the smallest item, 1..=10)
    if post_residual < 10 {
        score -= 30.0; // actually a perfect fill — strongly reward
    } else if post_residual < 20 {
        score += 8.0; // awkward dead zone
    }

    // Integer-division thresholds: post_residual mod classes
    let class = post_residual / 10; // 0..10 harmonic classes
    score += (class as f64) * 1.5;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
            // harmonic match: next item lands in same modulo class
            if (next_item_size / 10) == class {
                score -= 6.0;
            }
        } else {
            // next item won't fit here; penalize leaving large residuals that trap it
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only good when current
    // bins are mostly full and this item fits poorly everywhere
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // penalize new bins early, more lenient late
        score += 15.0 + 25.0 * (1.0 - progress);
        if item_size > bin_capacity / 2 {
            score -= 10.0; // big items justify fresh bins
        }
        if mean_residual > 30.0 {
            score += 10.0; // plenty of slack already open; don't add more
        }
    } else {
        // reward filling bins that are already mostly consumed
        let used_frac = 1.0 - frac;
        score -= used_frac * 10.0;

        // penalize spreading when many bins are open with high mean residual
        if mean_residual > (bin_capacity as f64) * 0.4 && bin_residual > item_size * 2 {
            score += 4.0;
        }
    }

    // Modulo bonus: post_residual divisible harmonics (e.g., 25/50) are reusable
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less wasted space relative to capacity.
    score -= (bin_capacity - post_residual) as f64 * 0.15;

    // Penalize small unusable dead space (< 10, the minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize "awkward" residuals that few item sizes can use.
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: favor bins whose residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance pressure: strongly prefer the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 15.0 + 5.0 * open_bins_count as f64;
    }

    // Mild pressure toward balancing residual mass across bins.
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    // Early stream: be more conservative about opening bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 0.5 * next_item_size as f64;
        } else {
            // dead space for the next item: penalize proportionally
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize small unusable residuals (below min item size 1..~10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize so it is chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 150.0 + 0.5 * item_size as f64;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Late in stream, be more aggressive at filling bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward leaving space for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (post_residual as f64 - next_item_size as f64).sqrt();
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // This placement would strand the next item's fit in this bin.
            score += 10.0;
        }
    }

    // New-bin candidate handling: empty bin gets base cost of a fresh bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score = bin_capacity as f64;
        // Open a new bin only if fits are poor or none exist.
        if fitting_bins_count == 0 {
            score -= 200.0;
        } else {
            // Penalize opening new bins as stream progresses (consolidation phase).
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 40.0 * progress + 5.0 * open_bins_count as f64;
            // If mean residual across open bins is large, prefer using open bins.
            if mean_residual > item_size as f64 {
                score += 15.0;
            }
        }
    } else {
        // Slight preference for bins with below-average residual (keep some bins for large items).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
        // Late in stream, be more aggressive filling existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post_residual
    let pr = post_residual as f64 / bin_capacity as f64;

    // Smooth polynomial coupling: tight fits rewarded more strongly later in stream
    let tightness = (1.0 - pr).powi(2);
    score -= 12.0 * tightness * (0.5 + progress);

    // Penalize large dead space with cubic growth, amplified by progress
    score += 4.0 * pr.powi(3) * (1.0 + 2.0 * progress);

    // Last-chance bin bonus (smooth, not piecewise)
    let last_chance = (fitting_bins_count as f64).recip();
    score -= 8.0 * last_chance * tightness;

    // Prefer bins whose residual is close to the mean residual (keeps bin pool balanced)
    let dev = (post_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 2.0 * dev * dev;

    // Lookahead: reward leaving room for the next item (smooth quadratic match)
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score += 0.05 * gap;
        let fit_next = if (post_residual as f64) >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= 5.0 * fit_next * (1.0 - (gap / bin_capacity as f64).powi(2));
    }

    // Mild penalty for spreading across many open bins early
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into capacity fractions.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = c / 4.0;
    let eighth = c / 8.0;

    // Integer-division harmonic class of post_residual (dead-space bands).
    let band = post_residual / (bin_capacity / 8); // 8 harmonic bands
    let band_penalty = match band {
        0 => 0.0,          // near-perfect fit, keep reward
        1 => -2.0,         // small leftover, good
        2 => 1.0,
        3 => 2.5,
        4 => 4.0,          // mid-sized leftovers are wasteful
        5 => 2.0,
        6 => 0.5,
        _ => -1.0,         // nearly empty bin: still flexible
    };
    score += band_penalty;

    // Non-linear dead-space term: penalize leftovers that no typical item can fill.
    if pr > 0.0 && pr < 10.0 {
        score += 12.0; // unusable sliver
    }
    if pr > quarter && pr < quarter + eighth {
        score += 3.0; // awkward band just above quarter capacity
    }

    // Modulo-style coupling: does post_residual pair well with next_item_size?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            // Next item fits here: strong reward, scaled by how snugly it fits.
            let snug = 1.0 - ((pr - nxt) / c).abs();
            score -= 6.0 + 4.0 * snug;
        } else {
            // Next item won't fit: mild penalty proportional to overflow.
            score += 0.05 * (nxt - pr).min(40.0);
        }
        // Harmonic residue: next item leaves a tiny remainder again -> chain of good fits.
        if nxt <= pr {
            let after = pr - nxt;
            if after > 0.0 && after < 10.0 {
                score += 8.0; // would create dead sliver next step
            } else if after == 0.0 {
                score -= 10.0; // perfect two-item closure
            }
        }
    } else {
        // Last item: reward closing bins tightly.
        if post_residual == 0 {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when existing residuals
    // are all too small to be useful (harmonic low-residual regime).
    if bin_residual == bin_capacity {
        // Fresh bin baseline: mid score; better than cluttered bins when mean residual is tiny.
        score = 0.5 * c - 0.3 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 20.0; // nothing fits elsewhere, new bin is required anyway
        }
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 4.0; // lookahead also poorly served by open bins
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.02 * open_bins_count as f64;

    // Slight adaptation over the stream: become more greedy (tight fits) later.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * progress * (1.0 - (post_residual as f64) / c);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to be useful later are costly.
    // Treat gaps < 10 (or < next item) as near-wasted space.
    let dead_threshold = if next_item_size > 0 { next_item_size.min(bin_capacity / 2) } else { 10 };
    if post_residual < dead_threshold {
        score += 50.0 * (dead_threshold - post_residual) as f64;
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 150.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins;
    // favor packing into existing ones more tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += pressure * 5.0;

    // Penalize bins whose residual deviates strongly from the mean residual
    // (keeps residual profile homogeneous, easier future fits).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // New-bin candidate: baseline attractiveness, modulated by whether
    // existing fits are poor (small fitting_bins_count => opening may be fine).
    if bin_residual == bin_capacity {
        score -= 30.0 + 10.0 * (fitting_bins_count as f64).ln().max(0.0);
        // But late in the stream with many open bins, prefer filling existing bins.
        score += pressure * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: waste-free placement is always ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward residuals that exactly accommodate the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            // Next item still fits, but penalize leftover after that chaining.
            let chained = post_residual - next_item_size;
            score -= 50.0 - (chained as f64).min(50.0);
        } else {
            // Next item won't fit here: penalize more when the gap is small
            // (near-miss dead space is the worst outcome).
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    }

    // Penalize residuals too small to hold any plausible item (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are tighter;
    // prefer filling tight bins (best-fit style) when they fit.
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.15;

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a new bin is only acceptable when
    // this item would leave a large awkward residual elsewhere, or when the
    // item is large and nothing fits well.
    if bin_residual == bin_capacity {
        // Base bias against opening new bins.
        score += 120.0;
        // But if item is large relative to capacity and next item is also large,
        // a fresh bin is fine (avoid fragmenting).
        if next_item_size > 0 && (item_size as f64 + next_item_size as f64) > bin_capacity as f64 * 0.9 {
            score -= 150.0;
        }
        // Fewer open bins => cheaper to open a new one.
        score -= (open_bins_count as f64).min(10.0) * 5.0;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 60.0;
    }

    // Prefer bins that are already substantially filled (high fill ratio).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 30.0;

    // Mild preference to keep number of open bins low.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual)
    let tight_fit = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tight_fit * tight_fit * bin_capacity as f64;

    // Penalize dead space that no future item can plausibly use:
    // dead space is post_residual if it's smaller than the smallest plausible item
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 0.6 * (next_item_size as f64 / post_residual as f64) * 30.0;
        } else {
            // next item won't fit here; penalize wasting space the next item needed
            score += 0.3 * (next_item_size as f64 - post_residual as f64).min(40.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, prefer fuller ones (already via post_residual)
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Prefer bins with residuals below the mean residual (keeps residual spread tight)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.25 * dev;

    // Time horizon: early in stream, be conservative (favor balance);
    // late in stream, aggressively fill bins to close them out
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * tight_fit;

    // If many bins are open, discourage opening new ones (favor existing bins)
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when already many open bins or early stream
        score += 15.0 + 3.0 * open_bins_count as f64 + 20.0 * (1.0 - progress);
        // but allow new bin if this item is large and no tight fit exists elsewhere
        if item_size >= 70 && fitting_bins_count <= 1 {
            score -= 40.0;
        }
    } else {
        score -= 5.0; // mild bonus for using an existing bin
    }

    // Nonlinear coupling: quadratic penalty on moderate leftover space (awkward residuals 20-50)
    let pr = post_residual as f64;
    if pr > 15.0 && pr < 55.0 {
        score += 0.15 * (pr - 35.0) * (pr - 35.0) / 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: quadratic waste penalty (favor tight fits superlinearly)
    let mut score = norm_pr * norm_pr * cap;

    // Smooth coupling: waste matters more later in the stream
    score *= 1.0 + 1.5 * progress * progress;

    // Lookahead: reward residuals that still fit the next item (smooth kernel)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_gap = (nx - pr).abs() / cap;
        let fits_next = (nx <= pr) as i32 as f64;
        score -= 8.0 * fits_next * (1.0 - fit_gap).powi(3);
        // penalize residuals slightly too big for next item (fragmentation risk)
        score += 4.0 * (1.0 - fits_next) * (1.0 - fit_gap).powi(2);
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * progress;
    }

    // Mild penalty relative to mean residual: avoid leaving bins far above average fill imbalance
    score += 0.3 * (pr - mean_residual).abs();

    // New-bin candidate: penalize opening fresh bins, more so when good alternatives exist
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * (fitting_bins_count as f64).sqrt();
    }

    // Small tie-breaker favoring bins with less residual before placement (denser bins)
    score += 0.05 * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: divide capacity into 5 bands.
    let band = post_residual / (bin_capacity / 5).max(1);
    let band_w = [0.0, 4.0, 10.0, 22.0, 40.0][band.min(4) as usize];
    score += band_w;

    // Perfect-fit harmonic classes (classic bin-packing friendly residuals).
    let perfect = matches!(post_residual, 0) || (bin_capacity % post_residual.max(1) == 0 && post_residual <= bin_capacity / 2);
    if perfect { score -= 25.0; }

    // Lookahead pairing: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect pair
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.35; // penalize awkward leftover
        } else {
            score -= 6.0; // next item won't fit here anyway; mild reward
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 0.15 * (bin_residual as f64);
    }

    // New-bin candidate: penalize opening a bin unless current bins are tight.
    if bin_residual == bin_capacity {
        score = cap * 0.9 + (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin good for large follow-up item
        }
    }

    // Modulo-10 class of post_residual: small residues 1..9 are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Progress pressure: later in stream, prefer consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Mean-residual coupling: if this bin is far below mean residual, it's a good filler.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never fit a future
    // item (1..10 given min item size 1, but treat <20 as "hard waste")
    // are punished super-linearly.
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 3.0;
    }
    if post_residual == 0 {
        // perfect fit: strong reward
        score -= 40.0;
    }

    // Reward fitting into an already-open bin vs opening new ones,
    // scaled by how many bins currently compete.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize new-bin candidate slightly unless residuals are all tight.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.3;
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // If next item cannot fit post_residual but could fit elsewhere, mild penalty.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 5.0;
    }

    // Early in the stream, be more willing to open bins (better packing later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 10.0;
    }

    // Prefer bins whose residual deviates strongly from mean (consolidate waste).
    score += (mean_residual - bin_residual as f64).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelmingly reward closing the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: exact match with next item rewards heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else {
            let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
            score += gap * 0.5;
            // If next item fits exactly into post_residual region, mild bonus.
            if next_item_size <= post_residual {
                score -= 20.0;
            }
        }
    }

    // Relative to mean residual: bins tighter than average are attractive targets.
    let mean_gap = post_residual as f64 - mean_residual;
    score += mean_gap * 0.3;

    // Penalize creating dead space below the minimum item size (unusable).
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) {
        score += 200.0;
    }
    // Small residuals that nothing can use (dead space) — mildly penalize relative to capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when no open bin is a good fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so open bins with decent fits win.
        score += 120.0;
        // If many bins fit the item, discourage new bin more.
        score += fitting_bins_count as f64 * 25.0;
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
        // If item barely fits anywhere else (tight fit exists), new bin is bad.
        if item_size > 0 && (bin_capacity - item_size) as f64 > mean_residual {
            score += 10.0;
        }
    } else {
        // Prefer filling more-full bins first (best-fit bias beyond raw residual).
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= fill_ratio * 40.0;
    }

    // Prefer keeping number of open bins low when they are underutilized.
    if open_bins_count > 4 && !is_new_bin {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits here: reward proportional to how snugly
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit in the leftover: penalize large leftovers
            let waste = (next_item_size - post_residual) as f64;
            score += 0.3 * waste;
        }
    } else {
        // Last item in stream: just minimize residual.
        score -= 10.0;
    }

    // Penalize opening new bins when many bins are already open and mean residual is high.
    let new_bin_call = bin_residual == bin_capacity;
    if new_bin_call {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = mean_residual / bin_capacity as f64;
        score += 20.0 + 15.0 * pressure + 10.0 * progress;
        if fitting_bins_count > 0 {
            score += 12.0; // discourage new bin if alternatives exist
        }
    }

    // Mild penalty for leaving residuals that are too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Slight preference to fill bins with larger residual first (waste absorption).
    score -= 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Non-linear coupling: residual squared normalized by capacity, modulated by progress
    score += 0.6 * (pr * pr / cap) * (0.5 + progress);

    // Cubic dead-space penalty for very small residuals, smoothed
    let dead = (1.0 - pr / cap).clamp(0.0, 1.0);
    score += 12.0 * dead * dead * dead * (0.3 + 0.7 * progress);

    // Reward tight fits via smooth interaction
    let fit_quality = 1.0 - (pr / cap).clamp(0.0, 1.0);
    score -= 8.0 * fit_quality * fit_quality * (1.0 - progress);

    // Last-chance bonus when only this bin fits
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // Penalize opening new bins when many open bins exist
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * (open_bins_count as f64).ln().max(0.0);
    } else {
        score -= 1.0;
    }

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 4.0 * (next_item_size as f64 / cap) * (1.0 - progress);
        } else {
            score += 2.0 * (1.0 - pr / cap);
        }
    }

    // Mean residual alignment term
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modular structure on capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // residual as fraction of capacity

    // Reward near-perfect fits strongly (tiny post_residual classes)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    }

    // Modulo-10 harmonic classes: residuals divisible by 10 are "usable"
    // by typical item sizes (10..80 range multiples of 10).
    let mod10 = post_residual % 10;
    score -= match mod10 {
        0 => 60.0,
        5 => 30.0,
        _ => 0.0,
    };

    // Harmonic coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // lookahead fits: reward proportionally to how snugly
            score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // next item cannot use this residual: penalize large dead space
            score += 0.3 * pr;
        }
    }

    // Integer-division thresholds: residual bands
    let band = post_residual / 20; // 0..5 bands
    score += band as f64 * 5.0;

    // Penalize wasting a nearly-full bin on a small item (bad tight-fit usage)
    if frac < 0.15 && item_size < bin_residual / 2 {
        score += 40.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: keep it neutral-ish, slightly worse than decent fits,
    // but attractive when existing residuals are all poor.
    if bin_residual == bin_capacity {
        score = 0.55 * cap + 0.2 * mean_residual - 10.0 * (fitting_bins_count as f64);
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
    }

    // Progress-aware tightening: later in stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (frac - 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never host a meaningful
    // future item (below the minimum plausible size) are pure waste.
    let dead_zone = post_residual < 10;
    if dead_zone {
        score += 60.0 + 2.0 * post_residual as f64; // tiny leftovers are worst
    }

    // Non-linear coupling: penalize residual quadratically in the "awkward" band
    // (small but not zero), rewarding near-perfect fits.
    let pr = post_residual as f64;
    if pr > 0.0 && pr <= 30.0 {
        score += (30.0 - pr) * (30.0 - pr) / 18.0;
    }

    // Reward exact fill aggressively.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins whose residual closely matches the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.35;

    // Open-bin pressure: discourage spreading across many bins unless the fit
    // is excellent; encourage consolidation when many bins are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let decent_fit_exists = mean_residual >= item_size as f64 + 5.0;
        score += if decent_fit_exists { 120.0 } else { -25.0 };
        // Late in the stream, opening new bins is more acceptable.
        score -= 30.0 * progress;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this residual anyway; slightly relax the
        // dead-space penalty for such bins.
        if dead_zone {
            score -= 20.0;
        }
    }

    // Mild preference for bins below mean residual (consolidate emptier space).
    score -= (mean_residual - bin_residual as f64) * 0.10;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 250.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0; // perfect chain match
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else {
            // next item won't fit here; penalize wasted lookahead potential
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap.min(50.0);
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving less than the mean is good (tight packing)
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.3 * (pr - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        score += 120.0;
        // New bin is fine if item is large and nothing else fits well
        if item_size as f64 >= 0.7 * bin_capacity as f64 {
            score -= 100.0;
        }
        if fitting_bins_count == 0 {
            score -= 150.0;
        }
    }

    // Slight bias toward fewer open bins early in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.2 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively than linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 12.0;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize dead space that no plausible item can use.
    // Items are 1..=100, but small dead space is still wasted; scale by item size.
    if post_residual > 0 && post_residual < item_size {
        score += (post_residual as f64) * 0.15;
    }

    // Lookahead: penalize if placing here blocks the next item.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 6.0 + 0.1 * next_item_size as f64;
        }
        // Reward if the next item also fits in this bin afterwards.
        if next_item_size <= post_residual {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate: open a new bin only when fits are poor or bins are crowded.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let waste_threshold = 0.25 * bin_capacity as f64 * (1.0 - progress);
        if (post_residual as f64) > waste_threshold && open_bins_count > 0 {
            score -= 15.0; // prefer fresh bin over sloppy fit
        } else {
            score += 8.0; // discourage needless new bins
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> consolidate.
    if open_bins_count > 3 && (bin_residual as f64) > mean_residual {
        score += 2.0;
    } else if open_bins_count > 3 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear penalty on wasted residual, growing with stream progress.
    let norm_waste = pr / cap;
    score += norm_waste * norm_waste * cap * (0.3 + 0.9 * progress);

    // Reward tight fits (small post_residual) more strongly late in the stream.
    score -= (1.0 - norm_waste) * (1.0 - norm_waste) * 8.0 * (0.5 + progress);

    // Penalize dead space that cannot fit the next item (smooth coupling).
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            let g = gap / cap;
            score += g * g * cap * 0.6;
        } else {
            // Next item fits here: reward keeping this bin attractive.
            score -= 6.0 * (-gap / cap).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: make it less attractive than a decent fit,
    // but viable when residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score = cap * (1.05 - 0.25 * fragmentation) + 10.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across too many open bins.
    score += (open_bins_count as f64).sqrt() * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: group residuals into capacity/10 classes
    let class_size = (bin_capacity / 10).max(1) as f64;
    let post_class = (post_residual as f64 / class_size).floor();
    let item_class = (item_size as f64 / class_size).floor();

    // Reward placements whose post_residual lands in a "harmonically useful" class
    // (small leftovers that are likely fillable by small items)
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 35.0;
    } else if post_residual <= 20 {
        score -= 18.0;
    } else if post_residual <= 30 {
        score -= 6.0;
    }

    // Modulo arithmetic on post_residual: leftovers that are multiples of 10
    // are easier to fill with typical item sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Penalize dead space: post residuals that no plausible item can fill
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable sliver (but still less bad than big waste)
    }

    // Lookahead coupling: if the next item fits the post residual exactly, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 25.0 - (slack as f64).min(40.0) * 0.4;
        } else {
            // next item won't fit here; mildly penalize
            score += 5.0;
        }
    }

    // Integer-division threshold on item class: large items prefer tight bins
    if item_class >= 5.0 {
        score -= (bin_residual - post_residual) as f64 * 0.3;
    } else {
        // small items: prefer bins with small residual to avoid fragmenting big bins
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // New-bin candidate handling: empty bin gets moderate score so it wins only
    // when all open bins are bad fits
    if bin_residual == bin_capacity {
        score = 55.0 + post_class * 2.0;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 * 3 / 4 {
            score -= 20.0; // big next item: fresh bin is valuable
        }
    }

    // Stream progression: late in the stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // Tie-break by mean residual: prefer bins already below-average residual
    score += (post_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than linearly.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Dead space penalty grows sharply for gaps that cannot fit typical small items.
        if gap < 10.0 {
            score += 40.0 * (10.0 - gap);
        } else if gap < 20.0 {
            score += 15.0 * (20.0 - gap) / 10.0;
        }
        // Bonus for tight fits (small post_residual relative to item).
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 25.0 * tightness;
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit: post residual becomes true dead space.
        score += 10.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: when many bins are open, discourage opening new ones
    // and encourage consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 15.0 + bin_pressure;
    } else {
        score -= 2.0 * bin_pressure.min(10.0);
    }

    // Mean residual coupling: prefer bins whose residual is below mean
    // (concentrate filling in tighter bins to close them out).
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chainable residual: reward proportionally to how well next item fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack * 0.5;
        } else {
            // Dead space for the lookahead item: penalize unusable leftovers.
            let dead = post_residual as f64;
            score += dead * 0.8;
            if dead > 0.0 && dead < 10.0 {
                score += 40.0; // tiny unusable slivers are very bad
            }
        }
    }

    // Compare against mean residual across open bins: prefer bins whose residual
    // is tighter than average (concentrate packing).
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f) * 0.3;
    } else {
        score += (resid_f - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (penalize opening bins when decent fits exist).
    if bin_residual == bin_capacity {
        let base = bin_capacity as f64;
        score += 150.0;
        if fitting_bins_count > 0 {
            // If some open bin fits, discourage new bin unless fits are poor.
            score += 100.0;
        }
        if next_item_size > 0 && next_item_size as f64 > base * 0.5 {
            score -= 30.0; // big next item: fresh bin useful
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 20.0;
    }

    // Slight preference for fuller bins (less residual waste).
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of the stream completed — dynamic time horizon.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight-fit reward: strongly favor bins where the item nearly fills residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize creating small unusable dead space (post_residual < 10 and > 0).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward exact fits heavily.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bonus: this is the only fitting bin; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    } else if next_item_size > 0 && next_item_size <= item_size {
        // Next item cannot use leftover space; penalize large leftovers slightly.
        score += 0.05 * post_residual as f64;
    }

    // Global state: prefer filling bins when many bins are open (consolidation pressure).
    score -= 0.3 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (balanced packing), with strength growing as the stream progresses.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += (0.5 + 2.0 * progress) * dev * 0.1;

    // New-bin candidate handling: penalize opening a new bin, but relax the penalty
    // when the item is large and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 20.0 };
        let poor_fit_open = if fitting_bins_count > 0 {
            let best_possible = 1.0 - (item_size as f64 / bin_capacity as f64);
            (best_possible * 10.0).min(15.0)
        } else { 0.0 };
        score += 40.0 + desperation + poor_fit_open - 20.0 * progress;
    }

    // Late-stream urgency: as the stream ends, squeeze existing bins harder.
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Quadratic waste penalty: large residuals are increasingly bad.
    score += 0.35 * (pr / cap) * (pr / cap) * cap * 0.1;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    score -= 12.0 * (1.0 - pr / cap).powi(3);

    // Lookahead coupling: reward residuals that can host the next item smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let compat = 1.0 - (pr - nxt).abs() / cap;
        if compat > 0.0 {
            score -= 8.0 * compat * compat * (1.0 - progress);
        } else {
            score += 3.0 * (pr / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin unless residual would be very small
    // or progress is late and open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let empty_penalty = 20.0 + 25.0 * (pr / cap) * (1.0 - progress) - 10.0 * progress * crowding;
        score += empty_penalty;
        // If the new bin would end with a tight residual, soften the penalty.
        score -= 18.0 * (1.0 - pr / cap).powi(4);
    }

    // Mean residual coupling: placing into a bin near the mean residual is neutral;
    // deviating above the mean wastes more, penalized smoothly.
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev.abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 classes partition residual space.
    // Residuals in "harmonious" classes (multiples of 10) are more reusable.
    let post_class = post_residual % 10;
    if post_class == 0 {
        score -= 12.0; // perfect harmonic residual, highly reusable
    } else if post_class <= 2 {
        score += 8.0; // tiny sliver, near-dead space
    } else if post_class >= 8 {
        score -= 4.0; // almost aligned to next class boundary
    }

    // Integer-division thresholds: how many size-10 "slots" remain.
    let slots = post_residual / 10;
    score -= (slots as f64).sqrt() * 3.0;

    // Lookahead coupling: does post_residual harmonically match next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 {
                score -= 15.0; // next item lands exactly on class boundary
            } else if slack < 10 {
                score += 6.0; // leaves tiny sliver after next item
            } else {
                score -= (slack as f64) * 0.05;
            }
        } else {
            score += 10.0; // next item cannot use this bin's remainder
        }
    }

    // Item size harmonic class: large items are scarce-resource, place greedily.
    if item_size > 60 {
        score -= 10.0;
    } else if item_size < 20 {
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // and mean residual across fleet is low (fleet nearly exhausted).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fit_quality = (bin_capacity - item_size) as f64;
        let fleet_pressure = mean_residual / bin_capacity as f64;
        let base = fit_quality + 30.0;
        let discount = 35.0 * fleet_pressure * (1.0 - 0.3 * progress);
        score = base - discount;
        if fitting_bins_count == 1 {
            score += 40.0; // never open when a last-chance bin exists
        }
    }

    // Mild preference for fuller bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity - bin_residual) as f64 * 0.1 * (0.5 + progress);

    // Crowding: many open bins -> consolidate, avoid spreading.
    if open_bins_count > 4 {
        score += 1.5 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are unusable forever.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 25 {
        score += (25.0 - post_residual as f64) * 1.2;
    }

    // Perfect / near-perfect fits get strong rewards.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the leftover, reward heavily;
    // if it cannot fit, the leftover is more likely dead space -> penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.2 * (post_residual as f64 - next_item_size as f64).abs();
        } else {
            score += 6.0 + 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Open-bin pressure: discourage scattering items across many bins,
    // but relax pressure as the stream progresses (bins close naturally).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (3.0 - 1.5 * progress);

    // Prefer bins with residuals close to the mean (balanced packing).
    score += 0.3 * ((bin_residual as f64 - mean_residual).abs());

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive when no
    // open bin offers a decent fit; make the empty bin moderately costly
    // so it wins only when fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (post_residual as f64 > 0.7 * bin_capacity as f64 && item_size <= 30);
        if poor_fit {
            score -= 20.0;
        } else {
            score += 25.0 + 0.5 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
