pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Penalize dead space that no future item (min size 1, typical 10+) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual < 20 {
        score += 6.0; // hard-to-fill zone
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: bonus if next item fits exactly in the post-residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += 4.0;
        }
    }

    // New-bin candidate: penalize opening a new bin, more so when open bins
    // are crowded (high mean residual relative to item) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 55.0 + 25.0 * progress + 30.0 * (1.0 - crowd);
        // Exception: if item is huge and no open bin fits well, new bin is fine.
        if item_size * 4 >= bin_capacity * 3 && fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild preference to fill bins with larger residuals when many bins open
    // (consolidation pressure scales with open bin count).
    score -= 0.05 * (bin_residual as f64 - mean_residual) * (open_bins_count.min(20) as f64).sqrt();

    // Small early-stream exploration bonus for moderately full bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.3 {
        score -= 5.0 * (1.0 - progress * 3.33) * tight;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
