    let rn = r / cap;

    // Base: prefer small post-residual, with non-linear polynomial coupling to progress.
    let mut score = r
        + 20.0 * rn * rn * (1.0 + 2.0 * progress)
        - 15.0 * rn * (1.0 - rn) * (1.0 - progress);

    // Reward tight fits: quadratic bonus for small post_residual relative to item size.
    let item = item_size as f64;
    let tightness = 1.0 - (r / item.max(1.0));
    score -= 25.0 * tightness * tightness * rn;

    // Penalize creating dead space that next item cannot use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > r {
