    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 18.0 * (1.0 - 0.5 * progress);
    }

    // Mild penalty when this bin's residual deviates from the mean (balance pressure).
    score += 0.15 * (r - mean_residual).abs() / cap;

    // Slight encouragement to fill bins as stream progresses (consolidation).
    score -= 6.0 * progress * (1.0 - rn);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
