    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item would fit the post-residual, reward; else penalize
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 15.0 * (nxt / cap);
        } else {
            score += 8.0 * (1.0 - post / cap);
        }
        // Perfect chain: post residual exactly matches next item
        if (post_residual as u32) == next_item_size {
            score -= 20.0;
        }
    }

    // Time horizon: later in the stream, prefer closing bins tightly (avoid leftovers)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 6.0 * (post / cap);

    // Global state: many open bins with large mean residual -> prefer consolidating
    if open_bins_count > 2 {
        let consolidation = (mean_residual / cap).clamp(0.0, 1.0);
        score -= consolidation * 5.0 * ((open_bins_count as f64).ln() + 1.0);
    }

    // New-bin candidate: only attractive if item is large relative to capacity
    // (opening fresh bin for a big item is fine; for small items it wastes capacity)
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score += 30.0 - 25.0 * fill;
        // discourage new bin when decent existing options exist
        if fitting_bins_count > 1 {
            score += 10.0;
        }
        // late in stream, prefer filling existing bins
        score += progress * 15.0;
    }

    // Slight preference for bins with residual close to item (perfect-ish fits)
    let tightness = 1.0 - ((bin_residual - item_size) as f64 / cap);
    score -= tightness * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: minimize wasted space, non-linearly scaled by stream progress.
    let mut score = post * (1.0 + 0.8 * progress * progress);

    // Smooth polynomial coupling: small post-residuals become increasingly
    // valuable as the stream progresses (tight packing late in the stream).
    let tightness = (1.0 - norm_post).clamp(0.0, 1.0);
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize leaving dead space that likely cannot fit the next item.
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).max(0.0);
        let gap_ratio = gap / cap;
        score += 6.0 * gap_ratio * gap_ratio * (1.0 - progress);
    }

    // Reward using the last bin that can fit the item (avoid opening a new bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins, decaying with progress.
    score += 0.4 * (open_bins_count as f64).powf(1.2) * (1.0 - progress);

    // Encourage bins whose residual is near the mean (balanced packing),
    // with a smooth quadratic divergence term.
    let dev = (post - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Slight preference for fuller placements relative to the bin's current fill.
    let fill_ratio = (item_size as f64) / cap;
    score -= 5.0 * fill_ratio * fill_ratio;

    // New-bin candidate: penalize mildly so it wins only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 10.0 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions
    let pr = post_residual;
    let class = pr % 10; // fine-grained harmonic class
    let coarse = pr / 10; // coarse decile of residual

    // Reward small post_residual strongly (tight fit), with harmonic-class bonus
    score -= (cap - (pr as f64)) * 0.05;

    // Dead-space penalty: residuals that are awkward (prime-ish / small) are hard to fill
    if pr < 10 && pr > 0 {
        score += 25.0; // unusable sliver
    }
    if class == 1 || class == 3 || class == 7 {
        score += 4.0; // awkward harmonic classes
    } else if class == 0 {
        score -= 3.0; // round residuals pair well
    }

    // Integer-division thresholds: can next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // chain fit: reward proportionally, more for larger next items (packing density)
            let density = next_item_size as f64 / cap;
            score -= 8.0 + 10.0 * density;
            // perfect pair: post_residual exactly equals next item
            if next_item_size == pr {
                score -= 20.0;
            }
        } else {
            // next item cannot follow here: penalize if residual is mid-range (dead zone)
            if pr >= 10 && pr < 50 {
                score += 6.0 + (50 - pr) as f64 * 0.1;
            }
        }
    } else {
        // last item: minimize residual count
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: keep it neutral-ish; only prefer it when
    // this bin's fit is bad (large post_residual relative to capacity)
    if bin_residual == bin_capacity {
        // fresh bin baseline: score = item_size left as residual, adjusted
        score = item_size as f64;
        // prefer new bin late in stream when many bins open (consolidation pressure low)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
        // if current fit would leave big awkward residual, new bin wins naturally
    } else {
        // favor filling existing bins as stream progresses
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 6.0 * progress;
        // penalize bins far from mean residual (fragmentation avoidance)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.08;
    }

    // coarse decile bonus: mid deciles (2-4) are the most fillable targets
    match coarse {
        2..=4 => score -= 5.0,
        5..=7 => score -= 1.0,
        8..=9 => score += 2.0,
        _ => {}
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Treat gaps below the smallest plausible item (<=10) as dead space.
        if post_residual < 10 {
            score += 60.0 + (10.0 - gap) * 8.0;
        } else if post_residual < 20 {
            // Small gaps that few future items can use.
            score += 18.0 + (20.0 - gap) * 2.0;
        } else if post_residual < 35 {
            score += 6.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Exact-fill lookahead: if the next item fits the post residual exactly,
    // this placement is very valuable.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        } else if next_item_size > post_residual {
            // Next item can't use this gap; the residual risks becoming dead space.
            score += 4.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins early,
    // encourage consolidation when many bins are already open.
    let pressure = open_bins_count as f64;
    if bin_residual < bin_capacity {
        // Existing bin: reward using it, more so as open bin count grows.
        score -= 3.0 + pressure * 0.6;
    } else {
        // New bin candidate: penalize slightly, scaled by stream progression.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 2.0 + 10.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor filling the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer bins tighter than the mean residual (better fit quality),
    // but only for existing bins.
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: prefer tight fits (small post_residual), with non-linear penalty
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 60.0;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // can exactly or nearly host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // exact match is ideal
            score -= 45.0 * (1.0 - slack / bin_capacity as f64);
            // extra bonus for near-exact chain fit
            if slack < 5.0 {
                score -= 25.0;
            }
        } else {
            // next item won't fit here after placement: penalize,
            // worse when post_residual is large dead space
            score += 0.25 * post_residual as f64;
        }
    } else {
        // last item: just minimize leftover
        score += 0.1 * post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer it only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score = bin_capacity as f64;
        // open a new bin if existing residuals are fragmented relative to item
        let tightness = mean_residual - item_size as f64;
        if tightness < 0.0 || mean_residual < (item_size as f64) * 1.2 {
            score -= 20.0; // open new bin when open bins are poor fits
        }
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // late in stream, consolidate more aggressively
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.7 && mean_residual > item_size as f64 {
            score += 15.0;
        }
    } else {
        // reward using bins with residual above mean (balance load)
        if (bin_residual as f64) > mean_residual {
            score -= 5.0;
        }
    }

    // mild penalty on absolute waste beyond next item needs
    if next_item_size > 0 && post_residual > next_item_size {
        score += 0.05 * ((post_residual - next_item_size) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: squared penalty on leftover space.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead (k=2): if the next item fits exactly into post_residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 12.0 * (1.0 - slack as f64 / bin_capacity as f64);
            if slack == 0 {
                score -= 15.0;
            }
        } else {
            // Dead space for the known next item: penalize proportionally to unusable gap.
            score += 6.0 * (next_item_size - post_residual).min(bin_capacity) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when existing fits are poor or none exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early stream: opening bins is cheap; late stream: prefer filling existing bins.
        score += 20.0 * (1.0 - progress);
        // If item leaves a large hole in a fresh bin, discourage slightly.
        score += 4.0 * (bin_capacity - item_size) as f64 / bin_capacity as f64;
        // If many bins are open already, discourage proliferation.
        score += (open_bins_count as f64).sqrt() * 2.0;
        // If the next item is large and this bin would remain tiny, opening fresh is fine.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 3.0;
        }
    }

    // Prefer bins whose residual is already below average (consolidate fragmented space).
    score -= 0.05 * (mean_residual - post_residual as f64);

    // Mild preference for more-filled bins overall.
    score += 0.1 * (bin_residual - item_size) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fits mildly; Late: penalize large residuals strongly.
    let poly = pr_norm * pr_norm * (1.0 + progress) + pr_norm * progress * 0.5;
    score += 30.0 * poly;

    // Reward near-perfect fits with a smooth quadratic bonus.
    let fit_quality = 1.0 - pr_norm;
    score -= 20.0 * fit_quality * fit_quality * (0.5 + progress);

    // Penalize residual below next item size (dead space) with smooth decay.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).max(0.0) / cap;
        score += 15.0 * gap * gap * (1.0 + 2.0 * progress);
        // Smooth reward when next item could fit exactly into post_residual.
        let closeness = 1.0 - ((nxt - pr).abs() / cap);
        score -= 8.0 * closeness.max(0.0) * closeness * closeness;
    }

    // Last-chance bonus: smooth reward when few fitting bins remain.
    if fitting_bins_count > 0 {
        let scarcity = 1.0 / fitting_bins_count as f64;
        score -= 10.0 * scarcity * (0.3 + progress);
    }

    // Coupling with mean residual: prefer bins deviating smoothly from mean.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Mild penalty for proliferating open bins late in stream.
    score += 0.5 * open_bins_count as f64 * progress;

    // New-bin candidate: prefer it only when it yields better packing than
    // poor fits — penalize opening new bins when good fits exist.
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + 10.0 * (1.0 - fit_quality);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as u32;

    // Class A: post_residual in harmonic residue classes that are highly reusable.
    // Residues mod 10 in {0} are perfectly packable; mod 5 in {0} near-perfect.
    let mod10 = pr % 10;
    let mod20 = pr % 20;
    if mod10 == 0 {
        score -= 8.0; // perfect harmonic slot
    } else if pr % 5 == 0 {
        score -= 4.0;
    }

    // Dead-space penalty: small unusable residuals (1..9) waste capacity
    if pr > 0 && pr < 10 {
        score += 15.0 + (10 - pr) as f64;
    }

    // Integer-division thresholds: post_residual in [10,25] band is awkward
    if pr >= 10 && pr <= 25 {
        score += 6.0;
    } else if pr >= 26 && pr <= 50 {
        score += 2.0;
    }

    // Lookahead coupling: does next_item_size fit harmonically into post_residual?
    if next_item_size > 0 {
        let n = next_item_size as u32;
        if n <= pr {
            // next item fits exactly or leaves a good residue
            let next_post = pr - n;
            if next_post % 10 == 0 {
                score -= 10.0;
            } else if next_post % 5 == 0 {
                score -= 5.0;
            } else if next_post < 10 {
                score += 5.0; // chains into dead space
            }
            // exact fit of next item
            if next_post == 0 {
                score -= 12.0;
            }
        } else {
            // next item won't fit here: residual may serve later items instead
            score += 3.0;
            if pr >= 10 {
                score -= 2.0; // still reusable by future small items
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless current
    // residuals are all poor (mean_residual low means bins are nearly full).
    if bin_residual == bin_capacity {
        // base cost of a new bin
        score += 45.0;
        // open a new bin when open bins are tight and item is large
        let tight = mean_residual / cap;
        score += tight * 30.0;
        if item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: must open
        }
    } else {
        // prefer tighter existing bins: reward small bin_residual
        score += (bin_residual as f64) * 0.15;
        // progress-aware: early in stream, keep bins flexible
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.3 && pr > 40 {
            score -= 2.0;
        }
    }

    // Mean-residual coupling: if this bin is far from mean, slight penalty
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // mod20 harmonic bonus: residues that pair with common item sizes
    if mod20 == 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no realistic item (>=1) can
    // use are waste; residuals below the next item's size are likely dead too.
    if post_residual == 0 {
        score -= 40.0; // perfect fill is the ideal outcome
    } else if post_residual < 10 {
        // tiny unusable gap -> heavy penalty (dead space)
        score += 25.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // gap too small for the lookahead item -> probable dead space
        score += 12.0 + 0.5 * (next_item_size - post_residual) as f64;
    } else {
        // usable residual: reward proportionally to how reusable it is
        score -= 0.1 * post_residual as f64;
    }

    // Tight fit reward: item occupies a large fraction of the bin
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Last-chance pressure: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins early on;
    // allow new bins later when consolidation value decays.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).ln().max(0.0) * (6.0 - 3.0 * progress);

    // New-bin candidate: only attractive when it enables a clean pair with the
    // next item, or when all existing fits would leave dead space.
    if bin_residual == bin_capacity {
        let pair_waste = if next_item_size > 0 {
            (bin_capacity as f64 - (item_size + next_item_size) as f64).max(0.0)
        } else {
            0.0
        };
        score = 55.0 + pair_waste;
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 45.0; // perfect two-item pairing -> open eagerly
        }
        if post_residual < 10 && next_item_size > 0 && post_residual < next_item_size {
            score -= 18.0; // existing fits would strand dead space anyway
        }
    }

    // Mild alignment with mean residual: prefer bins whose post state keeps the
    // fleet of residuals coherent (avoid fragmenting one bin while others stay large).
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
