    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 120.0; // chains the next item perfectly
            } else {
                score += gap as f64 * 0.15;
            }
        } else {
            score += 8.0 + (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Crowding pressure: with many open bins, prefer filling existing ones
    // rather than leaving many partially-filled bins.
    let crowding = open_bins_count as f64 / (1.0 + total_items as f64 * 0.1);
    score += crowding * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Global residual alignment: prefer bins whose residual is near the mean
    // (keeps residuals homogeneous, easier future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.08;

    // Time horizon: late in the stream, be more conservative — avoid tiny
    // slivers; early, allow exploration of new bins for large items.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (0.5 + progress); // tiny slivers are useless
    }
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize mildly unless item is large relative to
        // capacity or the stream is early.
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 30.0 - 40.0 * large_item + 20.0 * progress;
    }

    // Mild preference for bins with larger residual when item is big.
    score += (bin_residual as f64 / bin_capacity as f64) * (item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr as f64;
    score += 30.0 * x * x * (1.0 + progress);
    score += 20.0 * x * x * x * progress;
    score -= 15.0 * x * (1.0 - progress) * (1.0 - progress);

    // Reward tight fits, more strongly as stream progresses
    let fit = 1.0 - x;
    score -= 25.0 * fit * fit * (0.5 + progress);

    // Penalize last-chance bin usage unless the fit is excellent
    if fitting_bins_count == 1 {
        score += 12.0 * (1.0 - fit * fit);
    }

    // Lookahead: favor bins whose post-residual can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 10.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 8.0 * (nx - pr) / cap;
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64;

    // Penalize bins far from mean residual (encourage residual homogenization)
    score += 0.1 * (pr - mean_residual).abs();

    // New-bin candidate: keep it slightly attractive early, discourage late
    if bin_residual == bin_capacity {
        score += 5.0 * progress - 3.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: waste quantized by capacity fractions
    let frac = post_residual as f64 / cap;
    if frac > 0.0 {
        // small leftover space is dead space -> penalize non-linearly
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual <= 20 {
            score += 15.0;
        } else if post_residual <= 30 {
            score += 4.0;
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Modulo harmony: post_residual divisible by small integers pairs well with future items
    let pr = post_residual;
    if pr > 0 && (pr % 10 == 0 || pr % 20 == 0) {
        score -= 6.0;
    }
    // awkward remainders
    if pr % 10 == 7 || pr % 10 == 3 {
        score += 3.0;
    }

    // Lookahead coupling: does next item fit exactly in post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0;
        } else if next_item_size < pr {
            let nxt_post = pr - next_item_size;
            if nxt_post <= 10 {
                score -= 10.0; // chains into near-perfect fit
            } else {
                score += nxt_post as f64 * 0.1;
            }
        } else {
            // next item won't fit here; slight bonus for keeping big residual? no, penalize waste
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    if bin_residual == bin_capacity {
        let load_ratio = item_size as f64 / cap;
        if load_ratio > 0.6 {
            score -= 20.0 * (load_ratio - 0.6);
        } else {
            score += 30.0; // discourage wasting a fresh bin on small items
        }
        // early stream: open bins freely; late stream: consolidate
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Prefer tighter bins when many are open
    score -= mean_residual * 0.05;
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item can use are heavily penalized.
    // Items are 1..=100; treat residual < 10 as near-unusable dead space.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // tiny unusable sliver
        } else if post_residual <= 20 {
            score += 12.0; // awkward small gap
        } else if post_residual <= 35 {
            score += 4.0;
        }
    } else {
        // Perfect fit: strongly reward closing the bin exactly.
        score -= 60.0;
    }

    // Reward tight fits generally: ratio of item to residual.
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 15.0 * fill_ratio * fill_ratio;
    }

    // Lookahead coupling: if the next item fits into this bin's post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // Penalize leaving a gap that blocks the known next item but is still nonzero.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base mild penalty so we prefer reusing open bins with decent fits...
        score += 18.0;
        // ...but if open bins are heavily fragmented (high mean residual, many bins),
        // opening a fresh bin becomes relatively more attractive.
        score -= 0.05 * open_bins_count as f64;
        score -= 0.1 * (mean_residual - (bin_capacity as f64 - item_size as f64)).max(0.0);
        // Early in the stream, be more willing to open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // If the next item is large and this bin would be empty anyway, opening is safe.
        if next_item_size >= 60 {
            score -= 5.0;
        }
    }

    // Open-bin count pressure: mild penalty scaled by number of active bins to discourage sprawl,
    // but only for bins with large leftover space (encourage filling existing bins).
    if bin_residual != bin_capacity {
        score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    // Distance from mean residual: prefer bins whose post-residual aligns with usable sizes.
    let gap_from_mean = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * gap_from_mean;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post-residual can still fit the next item (but not perfectly): moderate reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 {
        // Dead space relative to next item: penalize proportionally to wasted capacity
        let waste = post_residual as f64;
        score += waste * 0.35;
    }

    // Tight fit reward: small post-residual is generally good
    score -= (bin_capacity as f64 - post_residual as f64) * 0.25;

    // Compare against mean residual: bins with residual far from mean are penalized
    // (keeps residual distribution tight so future items fit somewhere)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.10;

    // Last chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless it enables a
    // perfect lookahead match or the fit here is terrible.
    if bin_residual == bin_capacity {
        let perfect_new = next_item_size > 0 && (bin_capacity - item_size) == next_item_size;
        let poor_fit = (post_residual as f64) > 0.45 * bin_capacity as f64;
        if perfect_new {
            score -= 70.0; // open new bin for perfect 2-step chain
        } else if poor_fit {
            score -= 8.0; // slightly prefer fresh bin over wasting a nearly-full bin's structure
        } else {
            score += 55.0; // discourage needless bin proliferation
        }
    }

    // Late in the stream: consolidate more aggressively (avoid new bins, fill gaps)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    } else {
        score += progress * 15.0;
    }

    // Slight preference for bins among many fitting options (keeps scarce bins free)
    if fitting_bins_count > 1 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 300.0;
    } else {
        // Penalize dead space quadratically, scaled by item size.
        score += (post_residual as f64).powi(2) / 50.0;
        // Reward high fill ratio.
        score -= fit_ratio * 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only attractive when the fit elsewhere would be terrible
    // or when post_residual would leave a large unusable gap.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 150.0;
        // Fewer open bins -> opening is cheaper.
        score -= open_bins_count as f64 * 2.0;
        // If the item is large, a fresh bin is more attractive.
        score -= (item_size as f64 / bin_capacity as f64) * 100.0;
        // Lookahead: if next item pairs well with the leftover of the best open bin,
        // opening a fresh bin wastes structure; penalize more.
        if next_item_size > 0 {
            let pairing = (post_residual as i64 - next_item_size as i64).abs();
            if pairing <= 15 {
                score += 80.0;
            }
            // If next item is large, a fresh bin helps absorb it.
            if next_item_size > 60 && post_residual < next_item_size {
                score -= 60.0;
            }
        }
    } else {
        // Lookahead synergy: placing here leaves residual that fits next item well.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 90.0;
            } else {
                score -= 30.0 * (1.0 - slack as f64 / 60.0);
            }
        }
        // Penalize bins that deviate strongly from mean residual (keep pool homogeneous).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    // Early in the stream, be more willing to consolidate (penalize new bins more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer small post-residual, with non-linear (quadratic) tightening over stream progress.
    let mut score = pr * (1.0 + 0.6 * t) + 40.0 * norm_pr * norm_pr * (0.5 + t);

    // Smooth reward for tight fits (small post_residual relative to capacity), coupled with item size.
    let tightness = (1.0 - norm_pr).powi(2);
    score -= 25.0 * tightness * (0.4 + norm_item);

    // Penalize dead space that cannot plausibly fit future items: interaction of post_residual
    // with lookahead item size (smooth quadratic gap penalty).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            let gap = (nxt - pr) / cap;
            score += 60.0 * gap * gap * (1.0 + t);
        } else {
            // Reward leaving room for the next item (smooth coupling).
            let room = 1.0 - (pr - nxt) / cap;
            score -= 12.0 * room * room;
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (1.0 + norm_item);
    }

    // New-bin candidate: penalize opening a new bin, more so when many bins fit the item
    // or mean residual is large (existing space is plentiful).
    if bin_residual == bin_capacity {
        let fits = fitting_bins_count as f64;
        let slack = (mean_residual / cap).clamp(0.0, 1.0);
        score += 45.0 + 18.0 * fits * (0.3 + t) + 35.0 * slack * (1.0 - t);
        // But late in the stream, a fresh bin for a big item can be acceptable: soften penalty.
        score -= 20.0 * t * norm_item;
    }

    // Mild penalty for spreading across too many open bins (encourages consolidation).
    score += 0.15 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify post_residual by capacity fraction
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Dead-space penalty grows steeply for unusable slivers (< 10 units)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Perfect fit reward (harmonic class 0)
    if post_residual == 0 {
        score -= 80.0;
    }

    // Modulo classes of post_residual relative to typical item sizes
    let mod10 = post_residual % 10;
    if mod10 == 0 {
        score -= 12.0; // residual aligns with decade grid: reusable
    } else {
        score += mod10 as f64 * 0.8; // off-grid waste
    }

    // Check whether the lookahead item fits the post residual (pairing reward)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0; // guaranteed perfect next fit
        } else if next_item_size < post_residual {
            score -= 20.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            score += 8.0; // next item cannot use this bin's remainder
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are very full
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight = mean_residual / cap;
        score += 45.0 - 30.0 * tight - 10.0 * progress;
    }

    // Prefer filling bins that are already low on residual (tight packing)
    score -= 0.3 * (cap - bin_residual as f64);

    // Slight preference toward bins whose residual is close to the item (best-fit sharpening)
    let diff = (bin_residual as i64 - item_size as i64) as f64;
    score += 0.15 * diff.max(0.0);

    // Harmonic threshold: residuals in (40, 60) are the most reusable mid-class
    if frac > 0.4 && frac < 0.6 {
        score -= 10.0;
    } else if frac <= 0.1 && post_residual > 0 {
        score += 15.0; // tiny slivers are nearly dead space
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in [1, 9] is unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Fit quality: reward small post_residual relative to capacity.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 35.0;
        } else {
            score -= 10.0;
        }
    }
    // If next item cannot fit the post residual, mild penalty (wasted pairing potential).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // Open-bin pressure: penalize placements in bins when many bins are open,
    // encouraging consolidation unless the fit is excellent.
    score += (open_bins_count as f64) * 0.15;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates below mean
    // (smaller residual bins = tighter fits get priority).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: make it attractive only when item is large relative to
    // typical residuals or stream is early (fresh bins stay flexible).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let flexibility = 15.0 * (1.0 - progress);
        score = 60.0 - flexibility + (item_size as f64) * 0.2;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the lookahead item fits exactly into the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack.min(40.0); // exact/near-exact two-step match is highly desirable
        // If the lookahead item would leave a perfect zero residual, big bonus.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    } else if next_item_size > 0 {
        // Lookahead cannot fit here: penalize slightly so a bin that can chain gets priority.
        score += 10.0;
    }

    // Penalize creating dead space that no plausible item (>=1) can reuse.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Prefer bins whose residual is tighter than the mean (well-utilized bins).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: neutralize its raw residual so it's chosen only when fits are bad.
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && next_item_size <= item_size {
            score += 10.0; // opening a fresh bin is fine when current item is small relative to lookahead
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small dead space) with a nonlinear bonus.
    score -= (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 12.0;

    // Penalize unusable dead space: if post_residual is too small for the
    // smallest plausible item, it's wasted capacity.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // this placement chains nicely — reward it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize more if this bin becomes dead.
            if post_residual < 10 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score += open_pressure * 0.5;

    // Mean residual coupling: when mean residual is high, tight fits matter more.
    score -= (mean_residual / bin_capacity as f64) * 5.0;

    // Time horizon: early in the stream, be more willing to open new bins
    // (preserve flexibility); late in the stream, squeeze existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized late.
        score -= 18.0 * (1.0 - progress);
        score += 10.0 * progress;
        // Opening a new bin is fine if no open bin fits well.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else {
        // Existing bin: more attractive as the stream progresses.
        score -= 6.0 * progress;
    }

    // Mild penalty for very large items into nearly full bins (fragmentation risk).
    if item_size as f64 > 0.7 * bin_capacity as f64 && post_residual < 30 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear polynomial coupling to progress
    let mut score = norm_pr * (1.0 + 1.5 * progress * progress);

    // Penalize dead space quadratically: small residuals are useless
    score += 0.8 * norm_pr * norm_pr;

    // Reward tight fits (item nearly fills residual) more strongly late in stream
    let fit_tightness = item_size as f64 / bin_residual as f64;
    score -= 2.0 * fit_tightness * (0.5 + progress);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.2 + 1.5 * progress;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 0.6 + 0.5 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // next item cannot use the leftover: mild penalty scaled by wasted space
        score += 0.3 * norm_pr * (1.0 - progress);
    }

    // Mean residual coupling: prefer bins below mean residual (consolidating space)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.5 * dev;

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        let poor_fit = (item_size as f64 / cap) < 0.35;
        let base_penalty = 2.5 + 2.0 * progress;
        let relief = if poor_fit { 2.0 } else { 0.0 };
        score += base_penalty - relief;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual after placement (capacity fraction buckets)
    let frac = post_residual as f64 / bin_capacity as f64;
    // Dead-space penalty: residuals that are hard to fill (small, awkward)
    if post_residual > 0 {
        // Harmonic class via integer division thresholds on post_residual
        let class = post_residual / 10; // 0..=10 classes
        match class {
            0 => score += 40.0,          // 1-9: nearly unusable
            1 => score += 18.0,          // 10-19
            2 => score += 8.0,           // 20-29
            3 => score += 3.0,           // 30-39
            4 | 5 => score -= 2.0,       // 40-59: good host space
            6 | 7 => score -= 4.0,       // 60-79
            _ => score -= 1.0,           // 80-100: large but maybe wasteful
        }
        // Modulo coupling: residuals that are multiples of common item sizes are friendlier
        if post_residual % 10 == 0 {
            score -= 5.0;
        }
        if post_residual % 5 == 0 && post_residual % 10 != 0 {
            score -= 2.0;
        }
    } else {
        // Perfect fit is ideal
        score -= 60.0;
    }

    // Perfect-fit-class reward: residual exactly matches next item size
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            // reward if next item also leaves a decent class residual
            if after <= 5 {
                score -= 12.0;
            } else if after % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // next item cannot fit here: penalize slightly more if this is the only fitting bin
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // current item is large and would leave a bad class residual in existing bins
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // baseline: new bin gets a moderate score (its post_residual is large)
        score += 4.0;
        // if the item is big (would consume most of any bin), new bin is fine
        if item_size >= 60 {
            score -= 8.0;
        }
        // late in stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // many open bins already: discourage new bins
        score += open_bins_count as f64 * 0.5;
        // but if no bin fits well (residual class would be tiny), allow opening
        if post_residual > 0 && post_residual < 15 && fitting_bins_count <= 2 {
            score -= 20.0;
        }
    }

    // Tie-break toward tighter existing bins relative to mean residual
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host
    // typical future items are "dead". Penalize the unusable zone hard.
    let min_useful = 1.0f64.max(next_item_size as f64 * 0.5);
    if (post_residual as f64) < min_useful && post_residual > 0 {
        score += 40.0 + min_useful - post_residual as f64;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; with few open bins, tolerate new-bin opening.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).powf(1.2) * 0.8 * (0.5 + 0.5 * (1.0 - progress));

    // Mean residual coupling: if open bins are already slack (large mean
    // residual), discourage spreading by opening new bins -> favor this bin.
    score -= (mean_residual / bin_capacity as f64) * 10.0;

    // Lookahead: if next item fits in the post-residual, reward; otherwise
    // penalize leaving a gap that neither helps nor hurts.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 5.0;
        }
    }

    // New-bin candidate: baseline attractiveness so that it is chosen only
    // when existing bins have poor fits (their dead-space penalties kick in).
    if bin_residual == bin_capacity {
        score = 55.0 + (open_bins_count as f64) * 0.3;
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are good: reward small post residual relative to capacity.
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * 30.0;

    if next_item_size > 0 {
        // Perfect 2-step match: this bin's post residual exactly fits next item.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits here too; reward closeness of the double fill.
            let next_post = post_residual - next_item_size;
            score -= 25.0 * (1.0 - next_post as f64 / bin_capacity as f64);
            if next_post == 0 {
                score -= 20.0; // perfect double fill
            }
        } else {
            // Next item cannot follow in this bin: penalize wasted space.
            let waste = next_item_size - post_residual;
            score += waste as f64 * 0.5;
        }
    }

    // Compare against mean residual: prefer bins that deviate favorably.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Early in the stream, allow more bin openings; later, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early, penalized later.
        score += progress * 20.0 - 5.0;
    } else if open_bins_count > 1 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 {
        score -= 40.0 * fill_ratio;
    } else if fill_ratio > 0.5 {
        score -= 15.0 * fill_ratio;
    }

    // Penalize tiny dead space only if the next item can't use it; reward if it can.
    if next_item_size > 0 {
        if (post_residual as u32) < next_item_size && post_residual > 0 {
            score += 12.0 * (post_residual as f64 / bin_capacity as f64);
        } else if next_item_size as f64 >= post_residual as f64 * 0.9 {
            score -= 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it over opening a new bin
    // unless the fit is very loose.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if fill_ratio > 0.35 {
            score -= 25.0;
        } else {
            score += 8.0;
        }
    }

    // New-bin candidate handling: opening a new bin is attractive when the current item is
    // large (leaves a versatile residual) or late in the stream, and unattractive when many
    // bins are open with slack we should consolidate.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let versatility = 1.0 - (post_residual as f64 / bin_capacity as f64);
        let mut new_bin_score = 30.0
            - 20.0 * versatility
            - 15.0 * progress
            + 2.0 * open_bins_count as f64;
        // If mean residual across open bins is large, discourage opening new bins.
        new_bin_score += 0.3 * mean_residual;
        // If no open bin fits tightly, allow a new bin.
        if fill_ratio < 0.25 && fitting_bins_count > 0 {
            new_bin_score += 18.0;
        }
        score = score.min(new_bin_score);
    }

    // Global pressure: when many bins are open, push toward consolidation of loose fits.
    score += 0.05 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Mean-residual coupling: bins far from the mean residual are slightly deprioritized
    // unless the fit is tight.
    let dev = (bin_residual as f64 - mean_residual).abs();
    if fill_ratio <= 0.8 {
        score += 0.1 * dev;
    }

    // Time-horizon scaling: early in the stream, be more conservative with tight fits
    // (keep flexibility); late in the stream, reward tight packing harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual, with non-linear polynomial shaping.
    let mut score = post;

    // Quadratic coupling: penalize mid-range waste more aggressively as the stream progresses.
    let mid_waste = pr * (1.0 - pr); // peaks at 0.5 residual
    score += 60.0 * mid_waste * (0.5 + progress);

    // Cubic term: strongly reward near-zero post residual (tight fits), smoothly.
    let tight = (1.0 - pr).powi(3);
    score -= 40.0 * tight * (0.4 + 0.6 * progress);

    // Interaction with mean residual: placing into a bin far above mean residual
    // balances the fleet; penalize if it creates an outlier small residual.
    let dev = (pr - mean_residual / cap).abs();
    score += 15.0 * dev * dev * cap;

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 25.0 * (1.0 - slack) * (0.5 + 0.5 * progress);
        } else {
            // post residual too small for next item: mild penalty growing with progress.
            score += 10.0 * (nxt - post) / cap * (0.3 + 0.7 * progress);
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening a new bin early; relax late in stream
    // or when the item is large relative to capacity (poor fit elsewhere anyway).
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let size_ratio = item_size as f64 / cap;
        score += 30.0 * (1.0 - progress) - 20.0 * size_ratio * progress;
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 25.0 * (fitting_bins_count as f64).ln();
        }
    }

    // Mild preference for fuller bins overall (best-fit flavor) with smooth scaling.
    score += 0.05 * (bin_residual as f64 - post) * (1.0 - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fill classes (post_residual % 10 == 0)
    // are highly reusable for typical item sizes; reward them.
    let post_mod = post_residual % 10;
    if post_mod == 0 {
        score -= 12.0;
    } else if post_mod <= 2 {
        score -= 4.0;
    } else {
        // penalize awkward remainders proportionally
        score += (post_mod as f64) * 1.5;
    }

    // Integer-division thresholds on post_residual: small leftovers are dead space.
    let half = bin_capacity / 2;
    if post_residual < 10 {
        score += 30.0; // unusable sliver
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < half {
        score += 3.0;
    } else {
        score -= 6.0; // large residual left = flexible bin
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let nmod = (post_residual - next_item_size) % 10;
            if nmod == 0 {
                score -= 10.0;
            } else {
                score += nmod as f64 * 0.8;
            }
        } else {
            // next item won't fit here; slight penalty for hoarding space
            score += 5.0;
        }
    }

    // Last-chance bin before opening a new one: strong reward.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0);
    }

    // Prefer filling already-open bins when many are open (bin count pressure).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.5 * (0.5 + progress);

    // New-bin candidate: neutral-ish baseline, only chosen if open bins score badly.
    if bin_residual == bin_capacity {
        score = 40.0 + 10.0 * (1.0 - progress) - open_bins_count as f64 * 0.3;
    }

    // Tie-break toward bins tighter than the mean residual (compactness).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Very tight fits (near-perfect packing) get a strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize bins whose residual after placement falls below half capacity
    // (creates fragmented space that few future items can use).
    if post_residual > 0 && post_residual < bin_capacity / 2 {
        score += (bin_capacity / 2 - post_residual) as f64 * 0.3;
    }

    // Open-bin pressure: with many open bins, favor consolidating into existing
    // bins over opening new ones.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make opening a new bin costly unless the current item
    // is large relative to residual (poor fit elsewhere).
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if lookahead item is large, a fresh bin may be worth it.
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 5.0;
        }
    }

    // Lookahead coupling: if next item fits exactly into the post_residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // If next item cannot fit in post_residual, mild penalty for wasting space.
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Slight preference for fuller bins relative to the mean residual across
    // open bins (pack into the tightest bins first).
    score -= (bin_residual as f64 - mean_residual) * 0.1;

    // Stream progression: early on, be more conservative about filling bins
    // tightly; later, prioritize closing out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

