    }

    // Near match: next item fits with small leftover (<= 10 slack).
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 200.0 - (post_residual - next_item_size) as f64 * 10.0;
