    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Penalize leaving large dead space relative to capacity.
    if post_residual < 10 {
        score -= 80.0; // near-perfect fill
    } else if post_residual > 50 {
        score += 30.0; // excessive slack
    }

    // Late in the stream, consolidate aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0;

    // Mild penalty for opening new bins when many are already open.
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

