    // Perfect fit bonus: zero dead space is maximally desirable.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Non-linear dead-space penalty: small residuals are disproportionately bad.
        let pr = post_residual as f64;
        score += (bin_capacity as f64 / (pr + 1.0)) * 0.5;
    }

    // Lookahead (k=2): if the next item exactly fills the post residual,
    // this placement chains perfectly — strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves leftover; mild reward scaled by how well it fills.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 50.0 * fill;
        } else {
            // Next item cannot use this residual; penalize leaving moderate gaps
            // that are too small for typical future items.
            if post_residual < 10 {
                score += 30.0;
            }
        }
    }

    // Last-chance bin: if this is the only open bin that can fit the item,
    // avoid opening a new bin — reward using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when the item
    // is large (poor fit elsewhere likely) or when open bins are already crowded.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Reward opening a fresh bin for big items or late in the stream.
        score -= 80.0 * item_frac + 60.0 * progress;
        // Penalize opening new bins when existing bins have plenty of slack.
        score += 0.8 * mean_residual;
        // More open bins -> prefer consolidating into one of them.
        score += 4.0 * open_bins_count as f64;
    } else {
        // Favor bins whose residual deviates below the mean (nearly-full bins),
        // keeping large average slack bins available for future awkward items.
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    // Global consolidation pressure: as the stream progresses, mildly discourage
    // spreading across many bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // base: prefer small post residual
    let mut score = pr;

    // non-linear polynomial coupling of post residual with stream progress
    let poly = norm_pr * norm_pr * (0.5 + progress) + norm_pr * norm_item * (1.0 - progress);
    score += poly * cap * 0.8;

    // lookahead: reward bins that leave room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 12.0 * (1.0 - (pr - nx) / cap) * (0.4 + 0.6 * progress);
        } else {
            score += 8.0 * (nx - pr) / cap * cap * 0.1;
        }
    }

    // last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // mild penalty when many bins are open and this bin is far from mean residual
    score += 0.05 * (pr - mean_residual).abs() * (open_bins_count as f64).ln().max(1.0);

    // penalize very tight fits slightly more as stream progresses (dead space risk)
    score += 20.0 * norm_pr * norm_pr * norm_pr * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into small
    // "dead zones" are excellent (waste is capped by the class width).
    let class_width = 10u32;
    let residual_class = post_residual / class_width; // 0..=10
    let within_class = post_residual % class_width;   // 0..9

    // Reward low harmonic classes (post_residual near zero) strongly.
    score -= (10 - residual_class.min(10)) as f64 * 6.0;

    // Perfect or near-perfect fills get an extra harmonic bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Penalize residuals in awkward mid classes (11..40) that few items fit.
    if post_residual >= 11 && post_residual <= 40 {
        score += 15.0;
    }

    // Coupling with lookahead: if next item fits the post residual exactly
    // or nearly, this is a chain placement — reward it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 25.0 - slack as f64;
            } else {
                // next item fits but leaves another mid residual: mild penalty
                score += 5.0;
            }
        } else {
            // next item cannot follow into this bin: penalize unless the
            // post residual is tiny (dead space already minimal).
            if post_residual > 10 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless the item
    // is large and no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // Base cost of a fresh bin; reduced when item is big.
        score = 100.0 - pressure * 60.0 - (item_size as f64 / 4.0);
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
        // If many open bins exist, opening another is costlier.
        score += open_bins_count as f64 * 2.0;
        return score;
    }

    // Tie-break: prefer tighter bins via squared post residual scaled down.
    score += (post_residual as f64) * (post_residual as f64) / 200.0;

    // Slight preference for bins below mean residual (tighter than average).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard dead-space penalty: residuals too small to fit the smallest plausible item (1..100 range)
    // are almost certainly wasted. Penalize gaps below a "usable" threshold super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10.0 - post_residual as f64) * 12.0;
    }

    // Medium dead space (hard to fill later) also penalized, scaled by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual >= 10 && post_residual < 25 {
        score += 8.0 + 10.0 * progress;
    }

    // Perfect or near-perfect fits are rewarded.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly reward this bin.
    if next_item_size > 0 && post_residual as f64 == next_item_size as f64 {
        score -= 30.0;
    } else if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 5.0;
    } else if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        score += 6.0; // next item cannot use this gap -> mild penalty
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones (avoid sprawl);
    // when few are open, tolerate opening/spreading.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 2.5;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // (otherwise a new bin gets opened and this residual becomes dead space).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless the item fits badly everywhere.
    // Empty bin has post_residual == bin_capacity - item_size; penalize mildly,
    // but relax the penalty when the current bin's post-residual would be unusable.
    if bin_residual == bin_capacity {
        score += 12.0;
        if post_residual < 10 {
            score -= 20.0; // opening fresh is fine when placement leaves no dead space anyway
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates below the mean
    // (tighter bins first), classic best-fit behavior with adaptive flavor.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact / near-exact fits (small dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // this is a perfect chaining placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 500.0;
        } else if gap < 10.0 {
            score -= 150.0;
        } else {
            // mild reward proportional to how well the next item nests
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize proportionally to wasted opportunity.
        let unusable = next_item_size.min(post_residual) as f64;
        score += 40.0 * (unusable / bin_capacity as f64);
    }

    // Relative-to-mean coupling: bins tighter than the mean are better targets.
    let resid_f = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.5 * (resid_f - mean_residual);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: prefer it only when post_residual would be very large
    // (i.e. current fits are all poor) — otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        score += 120.0;
        // But if the next item would pair perfectly with the current one in a fresh bin,
        // make the fresh bin attractive.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let pair_gap = bin_capacity - item_size - next_item_size;
            if pair_gap < 10 {
                score -= 250.0;
            }
        }
    }

    // Slight early-stream preference for consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * (1.0 - progress) * (open_bins_count as f64 / 50.0).min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post-residual, but reward "perfect" fits strongly.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    if post_residual == 0 {
        score -= 25.0; // perfect closure
    } else if post_residual <= 10 {
        score -= 8.0; // near-perfect fit, dead space negligible
    } else {
        // Penalize unusable dead space non-linearly: residual below the
        // smallest plausible next item is wasted.
        let waste = if post_residual < 10 { 0.0 } else { (post_residual - 10) as f64 };
        score += 0.35 * waste * waste / cap; // quadratic dead-space penalty
    }

    // Tightness reward: fraction of bin used after placement.
    let fill = 1.0 - post / cap;
    score -= 6.0 * fill * fill;

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size < post_residual {
            // mild reward proportional to how well next item uses leftover
            let nxt_fill = nxt / post;
            score -= 5.0 * nxt_fill;
        } else {
            // next item won't fit here: slight penalty if this leaves a big gap
            score += 0.05 * (nxt - post).min(30.0);
        }
    }

    // Last-chance bin: if this is the only open bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.1 * (open_bins_count as f64);
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the current item is large relative to capacity and no open bin
    // offers a good fit, or late in the stream when many bins are open.
    if bin_residual == bin_capacity {
        let frac_open = open_bins_count as f64 / (1.0 + step_index as f64).max(1.0);
        let item_frac = item_size as f64 / cap;
        // Penalize new bins early / when item is small (prefer filling open bins)
        score += 12.0 + 20.0 * (1.0 - item_frac) * (1.0 - frac_open.min(1.0));
        // Reward new bins when item is huge and stream is early (reserve space)
        if item_frac > 0.6 && step_index * 4 < total_items {
            score -= 8.0;
        }
    }

    // Global state coupling: when mean residual across open bins is high,
    // prefer bins below the mean (consolidate large gaps first).
    if bin_residual != bin_capacity {
        let dev = mean_residual - post;
        score += 0.03 * dev; // favor bins ending below-average residual
    }

    // Time horizon: late in the stream, be conservative — favor tight fits
    // even more, discourage spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.25 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits; quadratic penalty on wasted space.
    let mut score = x * x * cap;

    // Smooth non-linear coupling of wasted space with stream progress:
    // later in the stream, waste becomes progressively more costly.
    let coupling = (1.0 - progress) * x + progress * x * x;
    score += 12.0 * coupling * cap;

    // Reward bins whose post-residual can still fit the next item (chaining),
    // penalize dead space that cannot host the lookahead item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as f64 >= nx {
            score -= 8.0 * (1.0 - (nx / cap)) * (1.0 - progress * 0.5);
        } else {
            score += 6.0 * (1.0 - progress) * (nx - pr as f64) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * (1.0 - x);
    }

    // Slight preference for consolidating into few bins when many are open.
    score += (open_bins_count as f64).ln().max(0.0) * x * 3.0;

    // Mild pull toward bins near the mean residual to keep balance.
    score += ((mean_residual - pr) / cap).abs() * 2.0;

    // New-bin candidate: allow opening a fresh bin when current fit is poor,
    // more permissive early in the stream (future items can fill it).
    if bin_residual == bin_capacity {
        let poor_fit = (x - 1.0).abs(); // x==0 here, poor_fit==1
        let _ = poor_fit;
        let openness = 1.0 - progress;
        // Open new bin if placing here would leave a large unusable residue.
        if x < 0.15 {
            score -= 20.0 * openness + 5.0;
        } else {
            score += 4.0 + 8.0 * (1.0 - openness);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "reusable" is the leftover space?
    // Residuals that are multiples of common item-size classes (10, 20, 25, 50)
    // are more likely to be filled by future items -> reward them.
    let pr = post_residual;
    let mut reusability = 0.0;
    if pr % 10 == 0 { reusability += 4.0; }
    if pr % 20 == 0 { reusability += 3.0; }
    if pr % 25 == 0 { reusability += 3.0; }
    if pr % 50 == 0 { reusability += 4.0; }
    score -= reusability;

    // Dead-space penalty: small, non-harmonic residuals are wasted space.
    if pr > 0 && pr < 10 {
        score += 15.0;
    } else if pr > 0 && pr < 20 && pr % 10 != 0 {
        score += 6.0;
    }

    // Perfect fit bonus.
    if pr == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            // reward proportional closeness of fit for the next item
            let slack = (pr - next_item_size) as f64;
            let n = next_item_size as f64;
            score -= 10.0 * (1.0 - slack / (n + 1.0));
        } else {
            // next item won't fit here; slight penalty if post_residual
            // is small enough to be unusable
            if pr < 10 { score += 5.0; }
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist.
    if bin_residual == bin_capacity {
        // Prefer new bin only if no open bin fits well (many fitting bins means
        // open bins are viable; opening new bins unboundedly is bad).
        score += 8.0 + 2.0 * open_bins_count as f64;
        // Early in the stream, new bins are cheaper (future items can use them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's a tight fit; packing tight bins first consolidates waste.
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 0.5 * (mean_residual - res_f);
    } else {
        score += 0.3 * (res_f - mean_residual);
    }

    // Slight preference for filling larger items into tighter bins.
    score += 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps.
    // A gap is "dead" if it cannot hold even the smallest plausible item (size 1..100 stream).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize gaps too small for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward if post_residual can still fit the next item (keeps bin useful).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones
    // over opening new bins; new empty bin gets implicit penalty via this term.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: penalize proportionally to open bins pressure.
        score += 30.0 + pressure * 4.0;
    } else {
        // Slight reward for using existing bins, scaled by pressure.
        score -= pressure * 0.5;
    }

    // Prefer bins with below-average residual (tighter bins), spreading fills evenly.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score += (1.0 - fit_ratio) * 10.0;

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect two-item fill
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow in this bin: penalize dead space
            let dead = (post_residual as f64).min(next_item_size as f64);
            score += dead * 0.3;
        }
    }

    // Compare post_residual against mean residual: avoid creating outliers
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening new bins when reasonable alternatives exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 + 8.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Slight preference for filling bins with more content already (fewer bins overall)
    score += 0.05 * (bin_residual as f64 - bin_capacity as f64).abs() * 0.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit bias: strongly reward tight fits.
    let tight = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * tight * tight;

    // Penalize dead space: residuals too small for typical future items.
    let t = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - t);
    }

    // Lookahead coupling: reward bins whose post-residual fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Post-residual wastes space relative to lookahead need.
        score += 0.15 * (post_residual as f64 - (next_item_size as f64 - 1.0)).max(0.0);
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Global pressure: many open bins -> prefer consolidating into existing ones.
    score += 0.5 * open_bins_count as f64 * (1.0 - t);

    // Deviation from mean residual: prefer bins near/above average fullness.
    score += 0.3 * (mean_residual - bin_residual as f64).abs();

    // New-bin candidate: only attractive when no good existing option exists.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Mild time decay: early on, keep options open (favor looser fits less).
    score -= 5.0 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = pr / cap;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;

    // Core: prefer small post residual (tight fit), non-linearly scaled
    let mut score = pr * (1.0 + 0.8 * fit_ratio * fit_ratio);

    // Smooth polynomial coupling with stream progress: early on tolerate slack,
    // later demand tight packing (amplify dead space)
    score += 12.0 * progress * fit_ratio * fit_ratio * cap * 0.1;

    // Reward bins whose residual closely matches the next item (lookahead chaining)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 6.0 * (1.0 - gap / cap).max(0.0) * (1.0 + progress);
    } else {
        // last item: maximize fill, strongly prefer smallest post residual
        score += 0.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0 + 8.0 * progress;
    }

    // New-bin candidate: penalize mildly, but relax when existing bins are fragmented
    if is_new_bin {
        let fragmentation = (mean_residual - pr).abs() / cap;
        score += 5.0 - 4.0 * fragmentation.max(0.0).min(1.0) + 6.0 * (1.0 - progress);
        // opening a new bin is attractive if item leaves a very usable residual
        score -= 4.0 * (1.0 - (fit_ratio - 0.5).abs() * 2.0).max(0.0);
    }

    // Slight preference for bins whose residual deviates from mean (consolidate slack)
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 as "dead space classes"
    let residue = post_residual % 10;
    // Small nonzero residues (1..=9) are classic dead space; residue 0 is perfect packing
    if post_residual > 0 && residue > 0 {
        score += (10 - residue) as f64 * 0.9; // penalize proximity to-but-not-at a harmonic boundary
    }
    if post_residual == 0 {
        score -= 25.0; // perfect closure reward
    }

    // Integer-division thresholds: post_residual / 10 as usable "slots" for mid-size items
    let slots = post_residual / 10;
    if slots >= 1 && slots <= 3 {
        score -= 4.0; // a few slots left is still usable
    } else if slots > 6 {
        score += 3.0; // large residual = poorly compacted bin
    }

    // Capacity fraction classes of item_size (harmonic packing classes)
    let frac = item_size as f64 / bin_capacity as f64;
    if frac > 0.5 {
        score -= 6.0; // big items should go in tight bins
    } else if frac < 0.25 {
        score += 4.0; // tiny items in a fresh bin waste capacity
    }

    // Lookahead harmonic coupling: does next item's class fit post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 {
                score -= 8.0; // next item closes bin on a harmonic boundary
            } else {
                score += gap as f64 * 0.05;
            }
        } else {
            score += 5.0; // next item cannot follow here
        }
    }

    // Last-chance bin logic
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: empty bin should only win when nothing fits well
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score = score.max(0.0) + 30.0 * (1.0 - pressure.min(1.0));
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // save space for the bigger follower
        }
    }

    // Stream progression: tighten late
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins that can still host the lookahead item after placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0; // dead space that also blocks the next item
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New empty bin candidate: penalize so it is chosen only when fits are terrible.
    if bin_residual == bin_capacity {
        score += 55.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (dead-space minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item fits exactly or nearly: strong reward.
            if gap == 0.0 {
                score -= 500.0;
            } else if gap <= 5.0 {
                score -= 200.0;
            } else if gap <= 10.0 {
                score -= 80.0;
            }
            // Small penalty proportional to leftover after the lookahead chain.
            score += gap * 0.5;
        } else {
            // Next item would NOT fit here: penalize leaving a trap-sized gap
            // slightly below next_item_size (unusable dead space).
            if next_item_size - post_residual <= 8 {
                score += 60.0;
            }
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.3;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 250.0;
        // Late in the stream, be more conservative with new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 100.0;
        // If next item is small, a fresh bin is more flexible.
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 80.0;
        }
    }

    // Mild preference for using bins that are already partially filled.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that can never be reused by the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            let wasted = (next_item_size - post_residual) as f64;
            score += 0.6 * wasted;
        } else {
            // Reward bins whose leftover can host the lookahead item snugly.
            let slack = (post_residual - next_item_size) as f64;
            score -= 0.15 * (1.0 - slack / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer fuller ones (small residual).
        score += 0.1 * (bin_residual as f64);
    }

    // New-bin candidate handling: only attractive when item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 {
            -20.0
        } else {
            // Make fresh bins slightly unattractive when good fits exist.
            let frag = (item_size as f64 / bin_capacity as f64).powi(2);
            8.0 + 10.0 * frag + 0.5 * open_bins_count as f64
        };
        score += pressure;
    }

    // Global state coupling: many open bins with high mean residual ->
    // encourage consolidation into existing bins.
    let consolidation = mean_residual / bin_capacity as f64
        * (open_bins_count as f64).ln().max(0.0);
    score -= 2.0 * consolidation * (post_residual as f64 / bin_capacity as f64);

    // Time-horizon modulation: early in the stream, be picky about tight fits;
    // late in the stream, prioritize closing out bins quickly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * (1.0 - progress) * tightness;
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for very large residuals left after placement (waste).
    if post_residual > 50 {
        score += 0.05 * (post_residual - 50) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_n = pr / c;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Base: reward tight fits (low post residual), non-linearly
    let mut score = pr_n * pr_n * c;

    // Smooth polynomial coupling of post residual with stream progress:
    // later in the stream, dead space becomes more costly
    let coupling = (1.0 + 1.5 * progress * progress) * (1.0 - pr_n * (1.0 - progress));
    score += pr * coupling;

    // Reward high fill ratio smoothly
    score -= 20.0 * fit_ratio * fit_ratio * (1.0 + progress);

    // Last-chance bin bonus (smooth sigmoid on fitting count)
    let last_chance = (fitting_bins_count as f64 - 1.0).tanh();
    score -= 15.0 * (1.0 - last_chance.abs()) * (1.0 - pr_n);

    // Lookahead: favor bins whose post residual can host next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 10.0 * (1.0 - ((pr - nxt) / c).powi(2));
        } else {
            score += 5.0 * (nxt - pr) / c;
        }
    } else {
        // last item: fill as tightly as possible
        score -= 30.0 * (1.0 - pr_n);
    }

    // Mild penalty for spreading across many bins vs mean residual
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (pr_n - mean_residual / c).abs();

    // New-bin candidate: neutral-ish baseline, slightly penalized unless current bins are hopeless
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that divide capacity
    // into clean integer chunks (highly reusable "harmonic" residuals).
    let pr = post_residual;
    if pr > 0 {
        let mut harmonic_bonus = 0.0;
        for d in [10u32, 20, 25, 33, 50, 100].iter() {
            if pr % d == 0 {
                harmonic_bonus += 8.0;
            }
        }
        // Perfect power-of-two style residuals
        if pr % 50 == 0 { harmonic_bonus += 12.0; }
        score -= harmonic_bonus;
    } else {
        // Perfect closure: bin exactly filled.
        score -= 100.0;
    }

    // Penalize dead space: residual too small for the smallest plausible item.
    if pr > 0 && pr < 10 {
        score += 60.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0;
        } else if next_item_size <= pr {
            let new_post = pr - next_item_size;
            // reward if the chain continues harmonically
            if new_post % 10 == 0 || new_post == 0 {
                score -= 25.0;
            }
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot follow into this bin: slight penalty if we leave odd residual
            if pr % 10 != 0 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when current
    // bins are crowded or the fit here is terrible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0
            + 0.5 * (open_bins_count as f64)
            + (mean_residual / cap) * 30.0;
        // Early in the stream, opening fresh bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 20.0;
    }

    // Fractional capacity class of the item: big items (half-capacity classes)
    // prefer tight bins; small items tolerate loose fits.
    let item_class = item_size / 25; // 0..3 harmonic quartile
    let residual_quartile = bin_residual * 4 / bin_capacity;
    if item_class == residual_quartile {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest item are pure waste; penalize them heavily.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 - 6.0 * post_residual as f64; // tiny gap = big penalty
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // this placement is excellent; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual <= 8 {
            score += 10.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading items out.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that fits the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when the item is large relative
    // to residual space in typical open bins (poor fits everywhere).
    if bin_residual == bin_capacity {
        let tight_fit = (item_size as f64 / bin_capacity as f64) > 0.85;
        let no_good_homes = mean_residual < item_size as f64 * 1.15;
        if tight_fit || no_good_homes || fitting_bins_count == 0 {
            score -= 55.0;
        } else {
            score += 40.0; // discourage opening bins when decent fits exist
        }
    }

    // Slight preference for using emptier bins early, tighter bins later.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward bins whose post_residual exactly matches next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual >= next_item_size {
            // next item fits exactly or nearly: big reward
            let diff = pr - next;
            if diff == 0.0 {
                score -= 60.0;
            } else {
                score -= 25.0 * (1.0 - diff / 100.0);
            }
        } else {
            // next item won't fit: penalize wasted potential, worse if post_residual small
            score += 15.0 * (next - pr) / next;
        }
        // Coupling with mean residual: prefer bins tighter than the mean
        score += 0.3 * (mean_residual - pr);
    } else {
        // Last item: minimize post residual aggressively
        score += 0.5 * (post_residual as f64);
    }

    // Last-chance bin bonus: only fitting bin -> strong reward to avoid opening new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless current bin fit is terrible
    if bin_residual == bin_capacity {
        score += 30.0 + 0.4 * (open_bins_count as f64);
    }

    // Prefer filling bins with little residual left (tight packing)
    score += 0.2 * (post_residual as f64) * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio for dynamic time horizon
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: small post_residual already favored by base.
    // Penalize unusable dead space (< 10) but only mildly, since it's still base-favored.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0 * (1.0 - progress); // early on, dead space matters more
    }

    // Lookahead chain bonus: if the next item fits into post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Slight penalty: leftover won't serve the next item; add half its unusable bulk
        score += (next_item_size.saturating_sub(post_residual)) as f64 * 0.15;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Many alternatives: mild penalty so the best-fitting bin wins via base term
        score += (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized more when many bins are already open
        // and when mean residual suggests existing space could be consolidated.
        let open_penalty = 20.0 + 3.0 * (open_bins_count as f64).sqrt();
        let residual_pressure = if mean_residual >= item_size as f64 { 15.0 } else { 0.0 };
        // Late in the stream, prefer closing out existing bins rather than opening new ones.
        let late_penalty = 10.0 * progress;
        // But if post_residual after placement is tiny (item nearly fills a fresh bin),
        // a new bin is actually excellent.
        let fresh_fill_bonus = if post_residual < 10 { 40.0 } else { 0.0 };
        score += open_penalty + residual_pressure + late_penalty - fresh_fill_bonus;
    }

    // Coupling with mean residual: bins far below mean residual are "fresher";
    // prefer filling bins above the mean (older, fuller bins) to consolidate.
    score += (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear waste penalty: quadratic coupling of post_residual with progress
    let norm_pr = pr / cap;
    score += 8.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 6.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Penalize bins whose residual deviates from mean residual (fragmentation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    } else if next_item_size > 0 {
        score += 3.0 * (next_item_size as f64 / cap) * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large relative to capacity
    if bin_residual == bin_capacity {
        score += 10.0 - 8.0 * (item_size as f64 / cap);
    }

    // Mild dispersion penalty scaled by number of open bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 defines "waste class"
    let r = post_residual % 10;
    score += (r as f64) * 0.35;

    // Perfect or near-perfect fits are heavily rewarded
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Penalize dead space: residual below smallest plausible item (<=10) is unusable
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // Lookahead: if next item fits into the post-residual, reward this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0;
        // Extra reward if next item exactly fills the bin afterwards
        if post_residual - next_item_size <= 5 {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot follow here: mild penalty scaled by gap
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when current bins are crowded
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins are opened only when justified
        score += 20.0 + (open_bins_count as f64) * 0.5;
        // If mean residual across open bins is small, opening a new bin is fine
        if mean_residual < 25.0 {
            score -= 35.0;
        }
        // Small items tolerate a fresh bin less
        if item_size <= 30 {
            score += 15.0;
        }
    }

    // Fraction-of-capacity classes: item size quarters
    let quarter = (item_size * 4) / bin_capacity;
    match quarter {
        0 => score += 2.0,   // tiny item: keep it out of large-residual bins? slight penalty
        1 => score -= 1.0,
        2 => score -= 3.0,
        _ => score -= 5.0,   // large items: prefer tightest fit (post_residual already low)
    }

    // Stream progression: later in stream, be greedier about filling bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 6.0;

    // Coupling with mean residual: bins far below mean residual are attractive targets
    score -= (mean_residual - bin_residual as f64) * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // dead space, nothing can ever fill it
        } else if post_residual < 20 {
            score += 35.0;
        } else if post_residual < 35 {
            score += 15.0;
        }
    } else {
        score -= 40.0; // perfect fill
    }

    // Reward leaving a gap that exactly fits the lookahead item (k=2).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize leaving a gap that is too small for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // Open-bins pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual - (mean_residual % 10.0);
        let pressure = (open_bins_count as f64).ln().max(0.0);
        if mean_residual < 25.0 {
            score -= 20.0 + pressure * 2.0; // open a fresh bin
        } else {
            score += 15.0 + fragmentation * 0.5; // prefer existing bins
        }
    }

    // Mild best-fit bias: tighter residual placement preferred.
    score += (bin_residual - item_size) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor bins where the next item also fits (2-step lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits: reward proportionally to how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 + 0.3 * (bin_capacity as f64 - slack - post_residual as f64).max(0.0);
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item does not fit: penalize leftover dead space.
            let dead = post_residual as f64;
            score += 0.5 * dead;
            if dead < next_item_size as f64 {
                score += 10.0;
            }
        }
    }

    // Prefer tight fits overall: reward small post_residual relative to capacity.
    score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize bins far from the mean residual (avoid fragmenting typical bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.2 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mild preference for keeping the number of open bins low late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * progress * open_bins_count as f64;

    // Slight bonus for reusing partially filled bins vs. fresh empty bin.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: dead space is the enemy.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, use it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward for chaining: residual after next item is small.
        let chain = post_residual as f64 - next_item_size as f64;
        score -= (1.0 - chain / bin_capacity as f64) * 10.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize leaving residual too small for the next item (wasted space).
        score += (next_item_size as f64 - post_residual as f64) * 0.3;
    }

    // New-bin candidate: only prefer it when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_capacity as f64 - item_size as f64) > 30.0
            && fitting_bins_count > 0
            && mean_residual < item_size as f64 * 1.2;
        if poor_fit {
            score -= 5.0; // allow opening a new bin when open bins have tiny residuals
        } else {
            score += 45.0 + (open_bins_count as f64).sqrt() * 4.0; // discourage excessive bin opening
        }
    }

    // Mild preference for fuller bins (small residual before placement).
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Late in the stream: consolidate more aggressively, avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    } else {
        score -= progress * 8.0;
    }

    // Prefer bins below mean residual (relatively emptier bins absorb items better).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with non-linear polynomial coupling to progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Quadratic dead-space penalty: small residuals are wasteful unless perfectly filled
    score += 12.0 * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr) * cap * (0.5 + 0.5 * progress);

    // Reward tight fits more strongly later in the stream
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.3 + 0.7 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: penalize if post residual can't fit the next item but almost could
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 4.0 * (nx / cap) * (1.0 - progress * 0.5);
        } else {
            // dead space relative to next item
            score += 5.0 * ((nx - pr) / cap) * (1.0 + progress);
        }
    }

    // Slight preference to spread across bins when many are open with large mean residual
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (norm_pr - mean_residual / cap).abs();

    // Mild new-bin damping: empty bins should only win when fit is poor
    if bin_residual == bin_capacity {
        score += 3.0 + 6.0 * (1.0 - progress) - 4.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls in
    // "usable" residue classes (multiples of small item sizes) are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Reward tight fits strongly.
    if pr == 0 {
        score -= 1000.0;
    } else if pr <= 10 {
        score -= 300.0;
    } else {
        // Harmonic residue classes: post_residual mod 10
        let class = pr % 10;
        match class {
            0 => score -= 120.0, // leftover divisible by 10 -> likely reusable
            5 => score -= 60.0,
            2 | 4 | 6 | 8 => score -= 20.0,
            _ => score += 15.0, // odd awkward residues
        }
        // Dead-space penalty if leftover is too small for the minimum item (1..100 unknown, assume ~10)
        if pr < 10 {
            score += 200.0;
        }
    }

    // Lookahead: penalize if next item cannot fit in post_residual.
    if next_item_size > 0 {
        if next_item_size <= pr {
            // fraction of leftover consumed by next item
            let fit_frac = next_item_size as f64 / prf.max(1.0);
            score -= 150.0 * (1.0 - fit_frac);
        } else {
            score += 120.0;
        }
        // Harmonic match: next item divides leftover nicely
        if pr > 0 && pr % next_item_size.max(1) == 0 {
            score -= 80.0;
        }
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // New-bin candidate handling: only open a new bin if current bins are badly fragmented.
    if bin_residual == bin_capacity {
        let frag = mean_residual / cap;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // prefer existing bins when mean residual is high and stream is early
        score += 400.0 * (frag - 0.35) + 100.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 30.0;
        }
    }

    // Prefer filling bins with low residual relative to the fleet mean (balance consolidation).
    score += 0.5 * (prf - mean_residual);

    // Slight preference to close nearly-full bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 50.0 * progress * (1.0 - prf / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual <= 12 {
        // Dead space zone: gap too small for typical items (items >= 10).
        score += 60.0 + (13.0 - pr) * 8.0; // smaller gap => worse
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    } else {
        // Larger residual: mildly penalize wasting space in a big gap.
        score += 0.15 * pr;
    }

    // Reward tight fits (post_residual small but still usable).
    if post_residual >= 13 && post_residual <= 30 {
        score -= 12.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins => discourage spreading, prefer new bin
    // only when fit is bad. Encourage consolidation when bins are few.
    let ob = open_bins_count as f64;
    score += 0.6 * ob * (pr / bin_capacity as f64);

    // New-bin candidate handling: an empty bin gets a moderate baseline so it
    // wins only when all open bins would create dead space.
    if bin_residual == bin_capacity {
        score += 35.0;
        // If next item is large and current fit is bad, new bin is attractive.
        if next_item_size > 0 && next_item_size >= post_residual.min(100) {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // This bin can also host the next item: reward chaining.
        score -= 15.0;
    }

    // Stream progression: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // Mean residual coupling: prefer bins with residual below mean (tighter bins),
    // penalize outliers with excessive space.
    let res = bin_residual as f64;
    if res > mean_residual + 20.0 {
        score += 8.0;
    } else if res < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual relative to capacity.
    score += 0.5 * (post_residual as f64 / cap) * (post_residual as f64 / cap) * cap * 0.1;

    // 2-step lookahead: reward if the next item fits exactly or well into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let gap = (post_residual as f64 - nxt) / cap;
            // Perfect 2-chain match: strong reward.
            score -= 12.0 * (1.0 - gap) * (1.0 - gap);
            if (post_residual as i64 - next_item_size as i64) == 0 {
                score -= 10.0; // exact 2-chain fill
            }
        } else {
            // Next item won't fit here: penalize leaving stranded space sized near next item.
            let stranded = nxt.min(post_residual as f64);
            score += 0.05 * stranded;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening new bins when good open bins exist.
    if bin_residual == bin_capacity {
        // New bin candidate: attractive only if current item is small relative to capacity
        // and few bins are open, otherwise discourage.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap as f64 * (1.0 - 0.05 * open_bins_count as f64) + 8.0 * progress;
        if item_size >= 50 {
            score += 15.0; // big items: prefer packing into open bins
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0; // new bin can host a 2-chain
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post-residual (tight fit), normalized.
    score += (post_residual as f64 / bin_capacity as f64) * 40.0;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    }

    // Penalize dead space that no plausible future item can use.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (1.0 - progress); // small slivers are worse early
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    } else if fitting_bins_count == 1 {
        // The new-bin candidate is the only "fitting" option: opening a bin is
        // justified only if the item is large and would leave usable space.
        let waste = (bin_capacity - item_size) as f64;
        score -= 60.0 - waste * 0.5;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward this placement (chaining); if next item would be blocked, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            if post_residual - next_item_size <= 10 {
                score -= 30.0; // perfect chain
            } else {
                score -= 10.0; // decent chain
            }
        } else if next_item_size <= bin_residual && next_item_size > post_residual {
            // Placing current item blocks the next item in this bin.
            score += 12.0;
        }
        // If next item is large, avoid leaving mid-range gaps it can't use.
        if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // Last item: just minimize waste.
        score -= 20.0;
    }

    // Global state: with many open bins, discourage spreading; prefer consolidation.
    let open_f = open_bins_count as f64;
    score += open_f * 1.5;

    // Prefer bins whose residual is below mean (tighter bins get used first),
    // keeping looser bins available for larger future items.
    let dev = mean_residual - bin_residual as f64;
    score -= dev * 0.3;

    // Time horizon: early in the stream, be more conservative about filling bins
    // too tightly (future big items need space); later, pack greedily.
    score += progress * (-5.0);

    // New-bin candidate: only attractive when current bins have small residuals
    // relative to the item or when congestion is high.
    if bin_residual == bin_capacity {
        let avg_tightness = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 10.0 + avg_tightness * 30.0 + open_f * 0.8;
        // If next item is huge, a fresh bin is valuable.
        if next_item_size >= 70 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let norm_post = post_residual as f64 / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Smooth non-linear coupling: post_residual penalty modulated by stream progress
    score += (post_residual as f64) * (0.5 + 0.5 * progress) * norm_post;

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= (1.0 - norm_post).powi(3) * cap * (0.3 + 0.7 * progress);

    // Penalize dead space that next item cannot use (quadratic coupling)
    if next_item_size > 0 {
        let unusable = ((post_residual as f64) - (next_item_size as f64)).max(0.0);
        score += (unusable / cap).powi(2) * cap * (0.4 + 0.6 * progress);
        // Reward if next item exactly fits post_residual
        if post_residual as f64 == next_item_size as f64 {
            score -= 5.0 + 10.0 * progress;
        }
    }

    // Last-chance bin bonus: smooth in fitting_bins_count
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 * (1.0 - norm_post);
    }

    // Coupling with mean residual: prefer bins deviating from mean early, near mean late
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += dev * dev * cap * (0.5 - 0.4 * progress);

    // Mild preference for opening new bins when many bins open and item is large
    if bin_residual == bin_capacity {
        score -= 1.0 + 3.0 * norm_item * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo 10 define
    // "usable" classes. Residues 0 (perfect) are golden; small residues
    // 1..9 are dead-space risk, growing as residue shrinks toward 1.
    let r = (post_residual % 10) as f64;
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else if post_residual <= 10 {
        // tiny sliver: nearly dead space, but can pair with small items
        score += (11.0 - r) * 2.0;
    } else {
        // penalize awkward residue classes (r in 1..9), reward r==0
        score += r * (r - 10.0).abs() * 0.05;
        if r == 0.0 {
            score -= 12.0; // residual is a multiple of 10: highly reusable
        }
    }

    // Integer-division thresholds on post_residual: classify residual band
    let band = post_residual / 25; // 0..4
    score += match band {
        0 => 6.0,           // 0..24: risky small leftover
        1 => 0.0,           // 25..49: medium
        2 => -3.0,          // 50..74: comfortable
        _ => -1.5,          // 75..99: large but wasteful for big items
    };

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward; if next item cannot fit, residual must serve future
    // unknown items, mild penalty proportional to tightness.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 8.0 - (slack as f64).min(8.0) * 0.5;
        } else {
            score += ((next_item_size - post_residual) as f64) * 0.08;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 10.0 + (bin_residual - item_size) as f64 * 0.05;
    }

    // New-bin candidate (empty bin): only attractive when the item is large
    // relative to capacity or existing residuals are fragmented.
    if bin_residual == bin_capacity {
        let frag = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let large_item = (item_size as f64) / (bin_capacity as f64);
        score += 18.0 - large_item * 30.0 - frag * 10.0;
        if post_residual % 10 == 0 && post_residual > 0 {
            score -= 6.0; // clean multiple-of-10 residual in fresh bin
        }
    }

    // Stream progression: late in the stream, tighten packing (favor
    // filling existing bins more aggressively).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 4.0;
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items (1..=10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 - 3.0 * post_residual as f64;
    }

    // Penalize awkward mid-range dead space that few items can use.
    if post_residual > 10 && post_residual < 25 {
        score += 12.0 - 0.5 * post_residual as f64;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this bin's remainder; penalize proportionally.
        score += 0.15 * (next_item_size - post_residual) as f64;
    }

    // Last chance: only this bin can fit the item -> strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // but allow consolidation pressure when many bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when few bins are open (waste),
        // slightly less when many bins exist (spreading may help).
        score += 25.0 + 2.0 * open_bins_count as f64;
    } else {
        // Using an existing bin relieves open-bin pressure.
        score -= 1.0 * open_bins_count as f64;
    }

    // Prefer bins tighter than average (good fits concentrate waste).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Early in the stream, be more willing to open bins; later, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
    } else {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: leaving zero residual is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly (or closely) matches the next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.6;

        // Exact match for the next item: strong reward.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Next item would fit exactly in the bin's current residual (tight pairing).
        else if bin_residual == next_item_size + item_size {
            score -= 15.0;
        }

        // Penalize residuals that are too small to ever host the next item,
        // creating dead space relative to the lookahead.
        if post_residual > 0 && (post_residual as u32) < next_item_size {
            score += 8.0;
        }
    } else {
        // Last item: prefer minimal waste.
        score += 2.0;
    }

    // Relative-to-mean coupling: bins tighter than the mean are good targets.
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Last-chance bonus: if this is the only fitting bin, strongly avoid
    // opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when decent existing fits exist,
    // unless the item is large and fits would leave big fragments.
    if bin_residual == bin_capacity {
        let fragment_risk = (bin_capacity - item_size) as f64;
        score += 5.0 + fragment_risk * 0.1;
        // Opening a new bin is attractive when many bins are open and
        // mean residual is fragmented (small mean residual).
        if mean_residual < 25.0 && open_bins_count > 3 {
            score -= 10.0;
        }
    }

    // Mild progression scaling: early in the stream, be slightly more
    // conservative about filling bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but avoid leaving
    // dead space that nothing reasonable can fill.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize small-but-nonzero dead space (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item can still go here: mild reward proportional to fit quality
            let waste = post_residual - next_item_size;
            score -= 12.0 * (1.0 - waste as f64 / bin_capacity as f64);
        } else {
            // next item cannot follow into this bin: penalize slightly
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: discourage spreading, prefer filling existing bins.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 3.0 * (1.0 - t);
    }

    // Compare against mean residual: bins with residual far above mean are
    // "loose"; prefer placing into tighter-than-average bins.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Early in stream: slightly favor opening fresh bins for large items
    // to keep flexibility; late: squeeze into anything.
    let item_frac = item_size as f64 / bin_capacity as f64;
    if t < 0.3 && item_frac > 0.6 && bin_residual == bin_capacity {
        score -= 10.0 * (0.3 - t);
    }

    // Late stream: heavily favor filling existing bins.
    if t > 0.7 && bin_residual < bin_capacity {
        score -= 6.0 * (t - 0.7);
    }

    // Discourage wasting a nearly-empty bin on a tiny item.
    if item_size < 20 && bin_residual > 80 && bin_residual < bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual (tight fit), with quadratic sharpening.
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Non-linear coupling of post_residual with stream progress:
    // later in the stream, dead space becomes more costly.
    let progress_coupling = norm_pr * (1.0 + progress * progress * 3.0);
    score += 30.0 * progress_coupling;

    // Cubic smooth term: very small residuals are gold; slightly larger ones less so.
    score -= 25.0 * (1.0 - norm_pr).powi(3) * (1.0 + progress);

    // Mean residual interaction: if this bin's residual deviates from mean, adjust.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev - 8.0 * dev * (1.0 + progress);

    // Last-chance bonus: only one fitting bin, avoid opening new bins.
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = (pr - nxt) / cap;
            score -= 12.0 * (1.0 - gap * gap);
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // New-bin candidate: penalize mildly, less so early in the stream or when crowded.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + total_items as f64 / 10.0);
        score += 15.0 - 10.0 * progress - 5.0 * crowding.min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small residues are dead space.
    // Class A: residue <= 10 (unusable for items >= 10, but stream may have 1..100).
    if post_residual <= 10 {
        score -= 15.0; // actually acceptable: nearly full bin
    } else if post_residual <= 20 {
        score += 10.0; // awkward dead space
    } else if post_residual <= 40 {
        score += 4.0;
    }

    // Modulo-classes: residues divisible by common item sizes are reusable.
    if post_residual > 0 {
        let reusable = (post_residual % 10 == 0) || (post_residual % 20 == 0) || (post_residual % 25 == 0) || (post_residual % 50 == 0);
        if reusable {
            score -= 8.0;
        }
    }

    // Coupling with next item: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            if nxt_post <= 10 {
                score -= 25.0;
            } else {
                score += (nxt_post as f64) * 0.15;
            }
        } else {
            // next item cannot follow in this bin: mild penalty if residue stays large
            score += (post_residual as f64) * 0.05;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    // or the item is large and no bin is tight.
    if bin_residual == bin_capacity {
        let tight_exists = mean_residual < 30.0 && open_bins_count > 0;
        let waste = (bin_residual - item_size) as f64;
        if open_bins_count == 0 {
            score -= 50.0; // must open first bin
        } else if waste < 25.0 && !tight_exists {
            score -= 30.0; // large item, fresh bin gives good post-residual
        } else {
            score += 40.0 + 0.3 * (bin_residual as f64); // discourage new bins generally
        }
    }

    // Prefer filling bins tighter than the mean residual.
    score -= 0.1 * (mean_residual - post_residual as f64);

    // Late-stream pressure: consolidate as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 && bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // Integer-division threshold on item size: big items prefer tight bins.
    if item_size / 40 >= 2 {
        score -= 0.1 * (bin_residual as f64 - item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps too small for the minimum
    // plausible item (<= 10) are pure waste; penalize them heavily.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Gaps that cannot fit even a mid-size item but could fit a small one
    // are partially wasted; mild nonlinear penalty.
    if post_residual > 0 && post_residual < 25 {
        score += (25.0 - post_residual as f64).powf(1.3) * 0.35;
    }

    // Reward tight fits: the smaller the leftover relative to capacity, the better.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer packing into existing
    // bins (penalize new-bin candidate proportionally to open_bins_count).
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0;
    } else {
        score -= open_bins_count as f64 * 0.8;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this placement is excellent; if post-residual is smaller than the next
    // item but nonzero, the gap likely becomes dead space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // slightly more so late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += ((bin_residual as f64 - mean_residual).abs()) * (0.05 + 0.1 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/tight fits (low post_residual)
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Non-linear tightness bonus: small post_residual heavily favored
        let pr = post_residual as f64;
        score += 20.0 * (pr / bin_capacity as f64).sqrt();
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        let nd = diff as f64;
        if diff == 0 {
            score -= 800.0; // perfect chain: next item fills this bin exactly
        } else if next_item_size <= post_residual {
            // next item fits in the residual: reward closeness
            score -= 300.0 * (1.0 - nd / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize wasted potential
            score += 0.5 * nd;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 2.0 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a bin unless current bin would leave
    // unusable dead space (post_residual too small to matter)
    if bin_residual == bin_capacity {
        let dead = post_residual > 0 && next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual < 10;
        if dead {
            score -= 50.0; // opening new bin avoids dead space
        } else {
            score += 120.0; // default: prefer reusing open bins
        }
    }

    // Late-stream urgency: consolidate more aggressively toward the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of the item into the bin.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual too small to ever hold a typical item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: reward if the next item fits into the post residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else {
            // Penalize leaving a residual that nearly-but-not-quite fits next item.
            let gap = (next_item_size as f64 - post_residual as f64).min(20.0);
            score += 0.3 * gap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is discouraged unless
    // existing bins fit poorly or are scarce.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // New bins are penalized more when many bins are already open and mean residual is high.
        let crowding = (open_bins_count as f64).ln().max(0.0);
        score += 18.0 + 2.0 * crowding + 15.0 * (1.0 - progress);
        // But if mean residual across open bins is very low (bins nearly full),
        // opening a new bin becomes more attractive.
        score -= (mean_residual / 10.0).min(20.0);
        // If item is large relative to capacity, new bin may be better anyway.
        score -= 0.1 * item_size as f64;
    }

    // Global state: when mean residual is high, prefer bins with residual
    // below the mean (consolidate large holes).
    let residual_f = bin_residual as f64;
    if residual_f > mean_residual {
        score += 0.15 * (residual_f - mean_residual);
    } else {
        score -= 0.1 * (mean_residual - residual_f);
    }

    // Mild time-horizon effect: early in the stream, be more conservative
    // about wasting space; later, prioritize closing bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize wasted space, non-linearly (quadratic + cubic coupling)
    let mut score = post * (1.0 + 0.012 * post / cap) + 0.0035 * post * post / cap;

    // Smooth interaction: waste matters more as the stream progresses
    let prog_term = progress * (1.0 - progress);
    score += 8.0 * prog_term * post / cap;

    // Reward tight fits (small post_residual) with a smooth saturating bonus
    let tight = (1.0 - post / cap).max(0.0);
    score -= 6.0 * tight * tight;

    // Penalize dead space that cannot fit the lookahead item (smooth coupling)
    if next_item_size > 0 && post > 0.0 {
        let nx = next_item_size as f64;
        if post < nx {
            let gap = (nx - post) / cap;
            score += 10.0 * gap * (1.0 + progress);
        } else {
            let usable = (post - nx) / cap;
            score -= 2.0 * usable * usable;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - post / cap);
    } else if fitting_bins_count > 1 {
        // Mild penalty for spreading across many fitting bins
        score += 0.4 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Bias toward bins with below-average residual (consolidating fullness)
    score += 0.5 * (mean_residual - bin_residual as f64) / cap;

    // Slight preference for fewer open bins, smoothed by progress
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Favor new-bin candidate only when residuals are nearly full (smooth gate)
    if bin_residual == bin_capacity {
        let gate = ((mean_residual / cap) - 0.35).max(0.0);
        score = score.max(0.0) + 2.0 - 20.0 * gate * gate;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo small divisors
    // captures "how reusable" the leftover space is.
    let pr = post_residual;
    let mod8 = (pr % 8) as f64;
    let mod16 = (pr % 16) as f64;
    let div4 = (pr / 4) as f64;

    // Dead-space penalty: residuals too small for typical items are wasted.
    if pr < 10 && pr > 0 {
        score += 25.0 + (10 - pr) as f64 * 2.0;
    }

    // Harmonic reward: post_residual divisible by common item sizes/classes
    if pr % 10 == 0 && pr > 0 {
        score -= 12.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 8.0;
    }
    if pr % 20 == 0 && pr > 0 {
        score -= 6.0;
    }

    // Modulo texture: non-uniform residues get slight noise-like shaping
    score += 0.15 * mod8 - 0.1 * mod16 + 0.05 * div4;

    // Capacity fraction thresholds (quartiles)
    let frac = pr as f64 / bin_capacity as f64;
    if frac > 0.75 {
        score -= 5.0; // bin still very roomy, good target
    } else if frac < 0.10 && pr > 0 {
        score += 10.0; // nearly-full bin, deprioritize unless last chance
    }

    // Lookahead coupling: does post_residual fit the next item exactly / well?
    if next_item_size > 0 {
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap == 0 {
                score -= 20.0; // perfect fit for lookahead
            } else if gap < 10 {
                score -= 10.0;
            } else {
                score -= 3.0 * (1.0 - (gap as f64 / bin_capacity as f64));
            }
        } else {
            // leftover cannot host next item: mild penalty scaled by waste
            score += 0.05 * (next_item_size - pr) as f64;
        }
    }

    // Last-chance logic: this is the only bin that fits -> strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin when other
    // bins fit, unless current bins are nearly all full (crowded stream).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0);
        let crowded = mean_residual < item_size as f64 * 1.2;
        if fitting_bins_count > 0 && !crowded {
            score += 40.0 + 15.0 * (1.0 - progress);
        } else {
            score += 5.0;
        }
        // slight harmonic shaping on new-bin decision
        score += ((open_bins_count % 4) as f64) * 0.5;
    }

    // Tie-break shaping by item size class (large items prefer tight bins)
    if item_size > 60 {
        score += 0.1 * (bin_residual - item_size) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A residual gap is "dead" if it is smaller than the smallest plausible item (1..100 range),
    // so any post_residual below a threshold is heavily punished.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Perfect fit bonus: strongly reward zero or near-zero post residual.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // Penalize large leftover space only mildly (it's still usable),
    // but penalize mid-range awkward gaps more.
    let pr = post_residual as f64;
    if pr > 40.0 && pr < 60.0 {
        score += 12.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones
    // (discourage opening new bins / spreading items thin).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (0.6 + 0.8 * progress);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits: mildly reward leaving usable room.
        score -= 5.0;
    } else if next_item_size > post_residual {
        // Next item won't fit in leftover: penalize leaving a gap that blocks it.
        score += 6.0;
    }

    // Mean residual coupling: prefer bins with residual below the mean (tighter packing),
    // penalize bins that are already emptier than average.
    let residual = bin_residual as f64;
    if residual < mean_residual {
        score -= (mean_residual - residual) * 0.3;
    } else {
        score += (residual - mean_residual) * 0.3;
    }

    // New-bin candidate: empty bin should only win when no open bin is a good fit.
    // Penalize the brand-new empty bin (bin_residual == bin_capacity) unless few bins are open.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 45.0 + (open_bins_count as f64) * 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step match: post_residual equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        // Exact match bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving dead space that no item of typical size can use
        if post_residual > 0 && post_residual < 10 {
            score += 30.0;
        }
    } else {
        // Last item: prefer tightest fit overall
        score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Penalize last-chance bins slightly less when fit is tight (avoid wasting them)
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Reward bins below mean residual (using up scattered space) mildly
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Discourage opening a new bin when decent alternatives exist
    if bin_residual == bin_capacity {
        score += 15.0 + 5.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: prefer bins where the item fills a large fraction of residual.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 8.0 * tightness * tightness;

    // Penalize large dead space after placement (hard to reuse).
    if post_residual > 0 {
        let dead = post_residual as f64;
        score += 0.35 * dead.sqrt();
        // Extra penalty for awkward small leftovers that few items can use.
        if post_residual < 10 {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 3.0;
        } else {
            score += 4.0;
        }
        // Reward leaving space proportional to the next item's needs.
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score += 0.05 * gap;
    }

    // New-bin candidate handling: opening a new bin is attractive early in the
    // stream or when many bins are open but residuals are large and unusable.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_waste = (mean_residual - item_size as f64).max(0.0);
        // Prefer a fresh bin when existing bins would leave large waste.
        score += 2.0;
        score += 0.02 * (post_residual as f64) * progress;
        score -= 0.01 * avg_waste * (1.0 - progress);
        // Late in the stream, discourage opening new bins.
        if progress > 0.8 {
            score += 10.0;
        }
    }

    // Mild preference for bins below the mean residual (consolidating waste).
    score -= 0.03 * (mean_residual - bin_residual as f64);

    // Slight preference to spread load when many bins are open.
    if open_bins_count > 4 {
        score += 0.01 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping.
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // early on, keep bins flexible (penalize low post-residual slightly less);
    // late, compactness matters more.
    let flex = 1.0 - progress;
    score += flex * 20.0 * norm_pr * (1.0 - norm_pr);

    // Dead-space penalty: very small post-residual is fine late, bad early.
    score -= (1.0 - progress) * 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let tight = 1.0 - ((pr - nx) / cap);
            score -= 6.0 * tight * tight;
        } else {
            score += 3.0 * ((nx - pr) / cap);
        }
    }

    // Last-chance bin bonus: avoid opening new bins when only one fits.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Mild penalty tied to mean residual: prefer bins near the mean (balance).
    score += 0.15 * (pr - mean_residual).abs();

    // New-bin candidate: penalize mildly so real bins win unless they're poor fits.
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity divided into eighths
    let eighth = bin_capacity / 8;
    let class = post_residual / eighth.max(1);
    // Reward tight fits: post_residual in the lowest classes is strongly favored
    let class_bonus: [f64; 9] = [-30.0, -18.0, -10.0, -4.0, 0.0, 4.0, 10.0, 18.0, 28.0];
    score += class_bonus[class.min(8) as usize];

    // Exact-fill perfection
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: residual that no plausible item (1..=100) can pair with well
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Modulo coupling: post_residual congruence classes mod 10
    let m = post_residual % 10;
    if m == 0 {
        score -= 8.0; // round residual is friendly
    } else if m >= 8 {
        score += 6.0; // awkward residual
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 20.0 - (slack as f64).min(20.0);
        } else {
            score += 8.0; // next item cannot use this bin's leftover
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a bin should be discouraged unless
    // no open bin fits decently or current bin would leave a bad class.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64 + 1.0).ln();
        score = 40.0 + pressure * 6.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin can host future items
        }
        if fitting_bins_count <= 1 {
            score -= 50.0; // no real alternative: open new bin
        }
    }

    // Progress-aware mild regularization toward mean residual balance
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.15 * (post_residual as f64 - mean_residual) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (unusable by future items >= 10
    // under classic regime, but sizes can be 1..100) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }

    // Reward tight fits (small waste relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 8.0;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last chance: only this bin can fit the item -> strong preference.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if current bins are nearly full
        // or the fit would leave a bad gap.
        score += open_bins_count as f64 * 6.0;
        if post_residual < 10 && item_size >= 10 {
            score += 40.0; // don't open a bin to create dead space
        }
        // Lookahead: if next item is small, a fresh bin is more tolerable.
        if next_item_size > 0 && next_item_size <= 20 {
            score -= 10.0;
        }
    } else {
        // Existing bin: slight bonus for consolidating load.
        score -= 3.0;
        // Lookahead: if next item fits exactly in post_residual, reward strongly.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > 0 && next_item_size > post_residual {
            score += 5.0; // next item won't fit here anyway
        }
    }

    // Prefer filling bins whose residual deviates below the mean (tackle
    // lopsided bins first to normalize open-bin residuals).
    if bin_residual != bin_capacity {
        let dev = mean_residual - post_residual as f64;
        if dev > 0.0 {
            score -= dev * 0.5;
        } else {
            score += (-dev) * 0.3;
        }
    }

    // Early in stream: be conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward (zero residual is ideal).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward: nonlinear bonus as post_residual approaches 0.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Dead-space penalty: small but nonzero residual that the lookahead item
    // cannot use is likely wasted space.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        let unusable = (post_residual as f64 / bin_capacity as f64).min(0.5);
        score += 18.0 * unusable;
    }
    // Lookahead synergy: residual that exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when the
    // item leaves a large, reusable residual or no open bin fits well.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin by default.
        score += 10.0;
        // But if the item is large, a fresh bin is reasonable.
        if item_size >= bin_capacity / 2 {
            score -= 14.0;
        }
        // If many bins fit the item, opening a new one is wasteful.
        if fitting_bins_count > 2 {
            score += 8.0 * (fitting_bins_count as f64 - 2.0).min(4.0);
        }
    }

    // Prefer filling bins whose residual is already below the mean
    // (consolidate small holes rather than spreading placement).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score -= 6.0 * (dev / bin_capacity as f64).min(1.0);
        }
    }

    // Late in the stream: be more conservative with new bins, more aggressive
    // at compacting existing residual.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight penalty when many bins are open and this one is nearly empty
    // (encourage closing out bins with tiny residuals).
    if bin_residual > 0 && bin_residual <= 10 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;

    // Normalize post residual and item size
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    // Non-linear waste penalty grows as stream progresses
    let waste_curve = 0.5 + 2.0 * progress * progress;
    score += waste_curve * pr_norm * pr_norm * cap;

    // Reward tight fits: smooth exponential closeness term
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 8.0 * tightness * tightness * (1.0 + progress);

    // Lookahead coupling: penalize if post_residual can't host next item smoothly
    if next_item_size > 0 {
        let next_norm = next_item_size as f64 / cap;
        let gap = (pr - next_item_size as f64) / cap;
        let usable = 1.0 / (1.0 + (-6.0 * gap).exp()); // sigmoid: ~1 if next fits, ~0 if not
        score -= 5.0 * usable * next_norm;
        score += 4.0 * (1.0 - usable) * pr_norm;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize mildly unless residuals are large/fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).powi(2);
        score += 6.0 - 10.0 * fragmentation * progress;
        score += 2.0 * open_bins_count as f64;
    }

    // Mild penalty for spreading across too many bins late in stream
    score += 0.15 * open_bins_count as f64 * progress;

    // Mean residual alignment: prefer bins near mean residual to keep balance
    score += 0.3 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // capacity-fraction bands. Dead space below the smallest item class
    // (<= 10) is nearly unusable; penalize it hard.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap;

    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else if post_residual <= 10 {
        // Unusable sliver: heavy penalty.
        score += 45.0 * (1.0 - frac);
    } else if post_residual <= 20 {
        score += 12.0;
    } else if post_residual <= 30 {
        score += 4.0;
    } else if post_residual <= 50 {
        score -= 6.0;
    }

    // Integer-division harmonic classes: leftover that is a multiple of a
    // common small size (10/20/25) is more reusable.
    let harmonic_bonus = if post_residual % 10 == 0 {
        10.0
    } else if post_residual % 20 == 0 {
        8.0
    } else if post_residual % 25 == 0 {
        6.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size as f64) / cap;
            score -= 8.0 + 10.0 * slack;
        } else {
            // Next item cannot fit here: mild penalty proportional to mismatch.
            score += (next_item_size as f64 - post) / cap * 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the current item
    // is large and would leave a well-shaped residual elsewhere. The empty
    // bin's score is its full capacity; nudge it based on stream progress and
    // how fragmented the open bins are.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early on, prefer filling existing bins; later, opening fresh bins
        // with room for future items is more valuable.
        score += 30.0 - 20.0 * progress;
        if item_size > 70 {
            score -= 10.0; // big items fit anywhere; no need for a new bin
        }
        if open_bins_count > 0 && mean_residual > item_size as f64 * 1.5 {
            score += 15.0; // existing bins have plenty of room; don't open new
        }
    }

    // Mild pressure to consolidate: bins far below mean residual are less
    // attractive targets than bins near the mean (keeps some bins tight).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1..10)
    // are unusable "dead space" -> heavy penalty scaled by gap smallness.
