    // Perfect-fit lookahead: if the next item exactly fills post_residual, strongly favor.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits here: mildly favor leaving a workable residual.
        score -= 5.0;
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        // Next item cannot use this gap -> confirm dead-space penalty.
        score += 10.0;
    }

    // Open-bin pressure: discourage spreading across many bins when residuals
    // are already fragmented; encourage consolidation when few bins are open.
    let pressure = open_bins_count as f64 * 0.6;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Early in the stream, slightly prefer opening fresh bins to build structure;
    // later, prefer consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus early-stream discount.
        score += 10.0 - 8.0 * progress;
        // If nothing fits well elsewhere (large item vs mean residual), new bin is fine.
        if (item_size as f64) > mean_residual {
            score -= 6.0;
        }
    } else if progress < 0.3 {
        // Early: mildly prefer consolidating into existing bins anyway.
        score -= 3.0;
    }

    // Prefer bins whose residual is close to the mean (keeps bin states uniform,
    // simplifying future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.19;
    score
