pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (nonlinear).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no future item can plausibly use.
    let min_item = 1.0;
    if (post_residual as f64) < min_item {
        score -= 20.0;
    } else {
        score += (post_residual as f64) * 0.05;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0;
        }
        // Chain fit: post residual fits next item with small slack left.
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack < item_size {
                score -= 8.0;
            }
        }
    } else {
        // Last item: prefer zero-waste placement.
        score -= tightness * 20.0;
    }

    // Time horizon: early on, prefer spreading load (keep residuals balanced);
    // late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (mean_residual - post_residual as f64) * 0.3;

    // Many open bins: encourage consolidation into existing bins.
    score += (open_bins_count as f64) * 0.4;

    // Penalize bins deviating from mean residual (balance pressure), scaled by progress.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1 * (1.0 - progress);

    // Discourage opening new bins when a decent fit exists.
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable only if item is large or fit is otherwise poor.
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        if !large_item {
            score += 15.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    // base: prefer small post-residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);
    // smooth coupling with stream progress: tighten packing later in the stream
    let progress_coupling = 1.0 + 0.6 * progress * progress;
    score *= progress_coupling;
    // penalize dead space relative to mean residual of open bins (smooth interaction)
    let mean_norm = mean_residual / cap;
    score += 12.0 * (norm_pr - mean_norm) * (norm_pr - mean_norm);
    // last-chance bin: reward using it (subtract)
    if fitting_bins_count == 1 {
        score -= 8.0;
    }
    // lookahead: reward leaving space compatible with next item (smooth quadratic)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = pr - nxt;
        let d = diff / cap;
        score -= 6.0 * (1.0 - (2.0 * d).powi(2)).max(0.0);
    }
    // mild penalty for proliferating open bins
    score += 0.15 * open_bins_count as f64;
    // new-bin candidate: penalize opening a fresh bin unless residuals are all poor
    if bin_residual == bin_capacity {
        score += 10.0 + 25.0 * mean_norm;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo small integers
    // capture "clean" leftover classes (multiples of 10, 25, 50) that future
    // items are more likely to fill exactly.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -30.0 // perfect fit, strongly reward
    } else if pr % 100 == 0 {
        -20.0
    } else if pr % 50 == 0 {
        -14.0
    } else if pr % 25 == 0 {
        -9.0
    } else if pr % 10 == 0 {
        -6.0
    } else if pr % 5 == 0 {
        -3.0
    } else {
        0.0
    };
    score += class_bonus;

    // Penalize small dead space: post_residual below typical small item sizes
    // is likely unusable. Harmonic classes 1..9 are the worst.
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 4.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // reward heavily; if next item is bigger than post_residual but smaller
    // than bin_residual, this placement wastes the slot for the next item.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 18.0;
        } else if next_item_size < pr {
            // next item still fits after this placement: mild reward scaled
            // by how much room remains for it
            score -= 4.0;
        } else if next_item_size <= bin_residual {
            // this placement blocks the next item in this bin
            score += 6.0;
        }
        // harmonic match: next item's class aligns with post_residual class
        if pr > 0 && next_item_size % 10 == pr % 10 && next_item_size <= pr {
            score -= 5.0;
        }
    }

    // Last chance: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 12.0;
        if pr <= 5 {
            score += 8.0; // nearly-full bin anyway, fine
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer it when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score += 15.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin
        } else if (post_residual as f64) < mean_residual * 0.5 {
            score -= 25.0; // poor fits everywhere, fresh bin better
        }
        if open_bins_count == 0 {
            score -= 60.0;
        }
    } else {
        // Prefer tighter fits among open bins: reward closeness of item to residual
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += tightness * 10.0;
    }

    // Mean residual coupling: placing into a bin below mean residual tends to
    // balance residual distribution (avoid many half-empty bins).
    if bin_residual as f64 > mean_residual {
        score += 2.0;
    } else {
        score -= 1.0;
    }

    // Stream progression: late in the stream, prefer closing bins tightly
    // (large post_residual penalties grow) since fewer future items remain.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr as f64 * (0.15 + 0.35 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than large ones.
    // A gap below the minimum item size (1) is unusable; treat sub-10 gaps as near-dead.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // unusable sliver: heavy penalty
        } else if post_residual <= 20 {
            score += 15.0; // only fits tiny items: risky
        }
    } else {
        // Perfect fit: strong reward
        score -= 25.0;
    }

    // Reward tight fits generally: normalize post_residual by capacity
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Lookahead: if the next item fits exactly into the post residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 20.0; // sets up a perfect chain
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 10.0; // next item won't fit here: dead end likely
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize the new-bin candidate implicitly via its high residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * 0.5 * (0.5 + progress);

    // New-bin candidate handling: only attractive when the item is huge relative
    // to typical residuals or no open bin fits well.
    if bin_residual == bin_capacity {
        let tight_fit_exists = fitting_bins_count > 0 && mean_residual >= item_size as f64 * 1.2;
        if tight_fit_exists {
            score += 30.0; // keep existing bins attractive
        } else {
            score -= 5.0; // fresh bin is fine
        }
    }

    // Slight preference for bins below mean residual (consolidating emptier bins)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fits (small post_residual) are good.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // 2-step lookahead: reward exact or near match between post_residual and next_item_size.
    if next_item_size > 0 {
        let look = next_item_size as f64;
        let post = post_residual as f64;
        if post >= look {
            let gap = post - look;
            // Strong reward for perfect chain fit (post_residual == next_item_size).
            score -= 18.0 * (1.0 - gap / (bin_capacity as f64 * 0.5)).max(0.0);
            if gap == 0.0 {
                score -= 25.0;
            }
        } else {
            // Next item cannot fit here; penalize leaving dead space the lookahead can't use.
            let unusable = look - post;
            score += 6.0 + 0.15 * unusable;
        }
    }

    // Relative to mean residual: prefer bins whose post_residual sits below the mean
    // (concentrating waste in few bins rather than spreading it).
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using the only bin that fits to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize creating very small unusable slivers (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let early = step_index as f64 / (total_items.max(1) as f64);
        // Slight preference for new bins early (more future items to fill them),
        // aversion late (many half-empty bins would accumulate).
        score = 55.0 - 10.0 * early;
        // If next item is small enough to pair in a fresh bin, mildly favor opening.
        if next_item_size > 0 && (next_item_size as u64 + item_size as u64) <= bin_capacity as u64 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post-residual quadratically (dead space).
    score += 0.015 * (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0 + 0.05 * next_item_size as f64;
        } else {
            // Leftover too small for next item: penalize proportionally to waste.
            score += 0.03 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0;
    }
    // Many alternatives: mild penalty for hoarding space in a tight bin.
    if fitting_bins_count > 3 {
        score += 1.5;
    }

    // Time horizon: early in stream, be more selective (penalize mediocre fits);
    // late in stream, close bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.04 * post_residual as f64;
    score -= progress * 2.0;

    // Global residual state: if mean residual is high, prefer filling fullest bins
    // (small post_residual) to consolidate; if mean residual low, allow new bins.
    score += 0.05 * (mean_residual - post_residual as f64);

    // New-bin candidate: penalize slightly unless current fit is bad or no alternatives.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > 0.5 * bin_capacity as f64;
        if bad_fit || fitting_bins_count == 0 {
            score -= 4.0;
        } else {
            score += 5.0 + 0.02 * open_bins_count as f64;
        }
    }

    // Prefer bins with less residual overall (best-fit bias) modulated by openness.
    score += 0.01 * bin_residual as f64 / (1.0 + open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
