        } else {
            score += 8.0 * (nx - pr) / cap;
        }
    }

    // Dampen preference for many open bins as stream progresses
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // Mean-residual coupling: prefer bins near the mean (keeps balance)
    score += 5.0 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: neutral-ish baseline, opened only if open bins score poorly
    if bin_residual == bin_capacity {
        score = cap * (0.9 - 0.25 * progress) + 10.0 * (1.0 - tightness);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

