    // Strong reward for near-perfect fit (post_residual small)
    if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Modulo-classes: residuals that are multiples of 5 or 10 are "harmonic"
    // with typical item sizes (multiples of 5/10) -> more reusable
    if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 4.0;
    } else {
        score += 3.0; // awkward residual
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits: reward proportional to how much would remain
        let next_post = post_residual - next_item_size;
        if next_post <= 10 {
