    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here: penalize small leftover dead space
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral-ish baseline, opened only when
    // open bins have poor fits. Give it a mild penalty scaled by stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.5 + 20.0 * progress;
        // If next item is large and would leave a bad residual, opening fresh is fine
        if next_item_size > 0 && next_item_size <= post_residual && (post_residual - next_item_size) <= 10 {
            score -= 10.0;
        }
    }

    // Prefer filling bins that are already mostly full (small residual)
    let res_frac = bin_residual as f64 / cap;
    score += res_frac * 5.0;

    // Mean-residual coupling: when open bins are crowded, avoid wasting space
    if mean_residual < 15.0 && post_residual > 0 {
        score += post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
