    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.25 * next_item_size as f64;
        } else if post_residual > 0 {
            // Dead space that cannot host next item: penalize proportionally.
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many open bins: discourage spreading, prefer filling existing bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
    score += 0.05 * pressure * (item_size as f64);

    // Time horizon: early in stream, new bins are cheap; later, consolidate.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_bias = 30.0 * (1.0 - t);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, reduced early, raised late.
        score += 12.0 + new_bin_bias;
        // Opening a bin is attractive if item is large and mean residual is small.
        if item_size as f64 > mean_residual {
            score -= 10.0;
        }
    } else {
        // Filling an existing bin slightly better late in the stream.
        score -= 5.0 * t;
    }

    // Prefer bins whose residual is close to item size (best-fit coupling).
    score += 0.2 * ((bin_residual - item_size) as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual, with smooth polynomial shaping
    let mut score = norm_pr * norm_pr * (2.0 - progress) + norm_pr * (1.0 + progress);

    // Penalize dead space that nothing else can plausibly use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) / cap * (1.5 + progress);
        } else {
            // reward leaving room for the lookahead item
            score -= (pr - nxt).min(cap - nxt) / cap * 0.8;
        }
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 {
        score -= 1.0 + 0.5 * progress;
    } else if fitting_bins_count > 1 {
        // mild penalty for consuming a bin when alternatives exist
        score += 0.15 * (fitting_bins_count as f64 - 1.0).min(3.0);
    }

    // Tightness coupling: bins already tight get preference via smooth interaction
    let tightness = 1.0 - bin_residual as f64 / cap;
    score -= tightness * tightness * 0.5 * (0.5 + progress);

    // Crowding: many open bins -> prefer consolidating into existing bins
    let crowding = (open_bins_count as f64).ln1p();
    score -= crowding * 0.1 * (1.0 - norm_pr);

    // Mean residual context: if this bin's post residual is far below mean, it's a good fit
    score -= ((mean_residual - pr) / cap).tanh() * 0.3;

    // New-bin candidate handling: empty bin gets a smooth offset that shrinks late
    if bin_residual == bin_capacity {
        score += 0.9 - 0.6 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is always perfect.
    if post_residual == 0 {
        return -1000.0;
    }

    // Harmonic class of the post residual modulo small capacities:
    // post_residuals divisible by 10 (and by 5) are "harmonic" with typical item sizes.
    let harmonic10 = (post_residual % 10) == 0;
    let harmonic5 = (post_residual % 5) == 0;
    if harmonic10 {
        score -= 8.0;
    } else if harmonic5 {
        score -= 3.0;
    } else {
        // Penalize awkward classes: post_residual in {1,2,3,4,6,7,8,9} mod 10
        let cls = post_residual % 10;
        score += (cls as f64) * 0.4;
    }

    // Dead space threshold: residual too small for the smallest item (1) is fine,
    // but residuals that are small-but-not-tiny create unusable slivers.
    if post_residual < 5 && post_residual > 0 {
        score += 12.0;
    }

    // Coupling with next item: if the next item fits exactly into the post residual,
    // strongly reward; if next item would leave a bad class, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 6.0;
            }
            if next_post < 5 {
                score += 5.0;
            }
        } else {
            // next item can't fit here anyway; slight reward for keeping bin reusable
            score -= 1.0;
        }
    }

    // Integer-division thresholds on post_residual by quarters of capacity.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual >= half {
        score -= 4.0; // keep large-space bins attractive
    } else if post_residual >= quarter {
        score += 1.0;
    } else {
        score += 3.0; // small leftover bins deprioritized
    }

    // Last-chance bin: if this is the only fitting bin, avoid wasting it on bad fits.
    if fitting_bins_count == 1 {
        if post_residual % 10 == 0 && post_residual >= 10 {
            score -= 10.0;
        } else {
            score += 6.0;
        }
    }

    // New-bin candidate: empty bin starts with perfect harmonic residual.
    if bin_residual == bin_capacity {
        // Prefer new bin when existing fits would leave awkward classes.
        let awkward = post_residual % 10 != 0 && post_residual < 10;
        if awkward {
            score -= 5.0;
        } else {
            score += 2.0; // otherwise mild preference for reusing open bins
        }
    }

    // Stream progression: later in the stream, be slightly more conservative about
    // opening bins (reuse more aggressively).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 1.5;

    // Mean residual coupling: when mean residual is high, tight fits matter more.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to hold
    // even the smallest item are worthless; penalize them heavily.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    } else {
        // Larger usable gaps are rewarded proportionally.
        score -= (post_residual as f64) * 0.15;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Next-item lookahead: if the next item fits exactly in post_residual,
    // strongly favor this bin (chains well).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        if next_item_size == post_residual {
            score -= 18.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover: this creates dead space.
        score += 10.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading to new
    // bins; with few, allow opening a new bin for large items.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open.
        score += 5.0 + open_pressure * 2.0;
        // But a new bin is fine if the item is large relative to capacity.
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Slight bias toward bins tighter than the current mean residual
    // (prefer filling already-loose bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Stream progression: early on, be more selective about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post residual
    // closely matches the next item's size (perfect chaining).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let match_gap = (pr - nxt).abs();
        if pr >= nxt {
            // Next item fits exactly into this bin's leftover: strong reward.
            score -= 14.0 * (1.0 - match_gap / bin_capacity as f64);
            // Perfect wrap (post_residual == next_item_size): big bonus.
            if match_gap < 1.0 {
                score -= 10.0;
            }
        } else {
            // Leftover too small for the next item: penalize dead space
            // proportionally to how unusable it is.
            score += 0.6 * (nxt - pr);
        }
    } else {
        // Last item: minimize leftover as usual, slightly stronger.
        score += 0.15 * post_residual as f64;
    }

    // Compare against mean residual across open bins:
    // prefer bins that are already tighter than average (consolidation).
    let cap = bin_capacity as f64;
    let residual_frac = bin_residual as f64 / cap;
    let mean_frac = mean_residual / cap;
    score -= 6.0 * (mean_frac - residual_frac);

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let tightness = 1.0 - (post_residual as f64 / cap);
        score -= 12.0 * tightness;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and stream is early (room to fill it well), or no good open option exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let size_frac = item_size as f64 / cap;
        let fill_potential = (1.0 - size_frac) * (1.0 - progress);
        score += 18.0 - 22.0 * fill_potential;
        // If next item is large, a fresh bin is more attractive.
        if next_item_size > 0 {
            score -= 0.15 * next_item_size as f64 * (1.0 - progress);
        }
    }

    // Mild preference for fewer open bins (encourage closing bins out).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 10 {
        score -= 5.0;
    }

    // Penalize creating dead space that is too small for the smallest plausible item,
    // scaled by how tight the bin already was.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 1.5;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / 20.0).max(0.0);
        } else {
            // Next item cannot follow here; slight penalty proportional to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += (over / 40.0).min(6.0);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer bins tighter than the current mean residual (good fits).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 8.0;
    score += (bin_residual as f64 - mean_residual).max(0.0) * 0.15;

    // Global state coupling: many open bins -> prefer consolidation into existing bins;
    // few open bins -> more willing to open fresh bins for large items.
    let pressure = (open_bins_count as f64 / 20.0).min(3.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive when item is large or pressure is low.
        let large_item_bonus = (item_size as f64 / 100.0) * 10.0;
        score -= large_item_bonus + 6.0 - pressure * 2.5;
        // Discourage new bins late in the stream when open bins suffice.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 5.0;
    } else {
        // Existing bins get a mild base advantage, growing with pressure.
        score -= pressure * 1.2;
    }

    // Time-horizon modulation: early stream, be exploratory (favor tight fits more);
    // late stream, prioritize closing bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + progress * norm_pr - progress * (1.0 - norm_pr));
    score += 2.0 * poly * cap * 0.25;

    // Penalize residual that is too small to ever be useful (dead space), smoothly
    let dead = (1.0 - norm_pr).powi(6);
    score += 30.0 * dead * (0.5 + progress);

    // Reward tight fits more strongly later in the stream
    let tight = (1.0 - norm_pr).powi(3);
    score -= 12.0 * tight * (0.3 + 0.7 * progress);

    // Lookahead: reward leaving room for the next item, smoothly quadratic
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.08 * gap * gap / cap;
        if pr >= next_item_size as f64 {
            score -= 4.0 * (1.0 - next_item_size as f64 / cap);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (0.5 + 0.5 * progress);
    }

    // Mild penalty for spreading across many bins when mean residual is high
    score += 0.05 * (open_bins_count as f64).ln1p() * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals near multiples of common
    // item sizes are more reusable. Class = post_residual / 10 bucket.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;

    // Reward residuals that can host the next item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 8.0 * (next / cap);
        // Extra reward if post_residual is "harmonically aligned": divisible-ish
        // with next item size (next item would leave a tiny remainder).
        let rem = (post_residual % next_item_size.max(1)) as f64;
        score -= 6.0 * (1.0 - rem / next.max(1.0));
    } else if next_item_size > 0 {
        // Dead space for the lookahead item: penalize proportionally.
        score += 5.0 * (next / cap);
    }

    // Integer-division thresholds on post_residual: residuals in [1,10) are
    // nearly dead; residuals >= 50 are half-empty bins (fine). Penalize the
    // low tail hard.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0 - 2.0 * post as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well, i.e.
    // when mean residual is small or this item is huge relative to residuals.
    if bin_residual == bin_capacity {
        // Base penalty so new bins aren't opened frivolously.
        score += 20.0;
        // If open bins are nearly full on average, new bin is reasonable.
        score -= 10.0 * (mean_residual / cap);
        // Early in the stream, allow more bins (future items benefit).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
        // Big item in a fresh bin avoids fragmentation.
        score -= 4.0 * (item_size as f64 / cap);
    }

    // Tight fit bonus: filling a bin completely is ideal (harmonic zero class).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Penalize bins much emptier than the mean only mildly (prefer balanced use,
    // but keep best-fit character via post_residual base term).
    score += 0.05 * (mean_residual - post).max(0.0);

    // Modulo-class coupling: item sizes that are divisors of capacity (10,20,25,50)
    // tile bins well; reward placing them into large-residual bins.
    if bin_capacity % item_size.max(1) == 0 && post_residual >= 10 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space: post_residual too small for the next item is wasted capacity.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap_severity = 1.0 + (next_item_size - post_residual) as f64 / 100.0;
        score += 60.0 * gap_severity;
    }

    // Reward bins whose residual was already fragmented (tight packing now).
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness;

    // Penalize leaving large post_residual when many bins are open (pressure to close bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += 0.15 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: prefer it only when this bin would leave unusable dead space
    // or when open-bin count is high and residuals are fragmented.
    if bin_residual == bin_capacity {
        let mean_frag = mean_residual / bin_capacity as f64;
        let dead_here = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        if dead_here {
            score -= 50.0; // new bin better than creating dead space
        } else {
            score += 30.0 + 20.0 * mean_frag; // keep filling open bins
        }
        // Early stream: opening bins is cheap; late stream: avoid it.
        score += 60.0 * (1.0 - progress);
    }

    // Mild preference for bins closer to mean residual (balance).
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for dead space that is too small to fit typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 2-step lookahead: reward exact or near match between post_residual and next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect fit for the next item is excellent.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits here: reward closeness of match.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item does not fit after this placement: penalize proportionally.
            score += 15.0 * (diff / bin_capacity as f64);
        }
    }

    // Prefer tight fits relative to current bin residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Compare post_residual against mean residual: avoid leaving much more than average.
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when current bin would leave bad dead space
    // and lookahead suggests the next item pairs better with a fresh bin.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual < 10 || (next_item_size > 0 && next_item_size > post_residual);
        if bad_fit {
            score -= 20.0;
        } else {
            score += 55.0; // discourage opening new bins when existing ones fit well
        }
    }

    // Mild late-stream pressure to consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively when many bins compete.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    let competition = (fitting_bins_count.max(1) as f64).ln();
    score -= (1.0 - tight) * (1.0 + competition) * 12.0;

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.9;
        } else {
            // Reward residual that can still host the next item.
            score -= 4.0;
        }
    }

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bin is a poor host.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin, softened late in the stream or when bins are fragmented.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64 * (1.0 - 0.35 * progress);
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative, must open
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // Prefer filling fragmented bins when many open bins exist (consolidation pressure).
    let frag = (mean_residual - post_residual as f64).abs();
    score += frag * 0.05 * (open_bins_count as f64).sqrt();

    // Mild preference for bins whose residual is close to item size (best-fit flavor).
    score += (bin_residual as f64 - item_size as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual (tight fit)
    let mut score = pr as f64;

    // Smooth non-linear penalty on wasted space, amplified as stream progresses
    let waste = norm_pr * norm_pr * (1.0 + 3.0 * progress);
    score += 40.0 * waste;

    // Interaction: post_residual^2 coupled with progress (dead space matters more late)
    score += 0.02 * pr * pr * progress;

    // Lookahead coupling: reward residual that can hold the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = (pr >= nx) as i32 as f64;
        let tightness = 1.0 - ((pr - nx) / cap).abs();
        score -= 18.0 * fits_next * tightness * (0.5 + progress);
        // Penalize leaving residual just below next item (unusable sliver)
        let sliver = ((nx - pr) / cap).max(0.0);
        score += 25.0 * sliver * sliver * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0 + 20.0 * progress;
    }

    // Many open bins: mild penalty to spreading into extra bins late
    let ob = open_bins_count as f64;
    score += 0.5 * ob * progress * (1.0 - norm_pr);

    // Mean residual deviation: prefer bins near the mean (balanced packing)
    score += 4.0 * ((pr - mean_residual) / cap).abs() * (1.0 + progress);

    // New-bin candidate: neutral-ish but penalize slightly so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify post_residual by integer division
    // into capacity-fraction bands. Small classes (near zero) are prime dead space.
    let cap = bin_capacity as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Reward exact or tiny post_residual strongly (perfect fit classes).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= eighth {
        score -= 25.0;
    } else if post_residual <= quarter {
        score -= 8.0;
    } else if post_residual > bin_capacity / 2 {
        // Large leftover keeps the bin versatile; mild reward.
        score -= 6.0;
    } else {
        // Mid-range leftover (33%..50%) is the worst dead-space zone.
        score += 10.0;
    }

    // Modulo arithmetic on post_residual: leftovers that are multiples of small
    // harmonics (divisible by 10) tend to be re-usable by typical item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Lookahead coupling: if the next item fits the post_residual exactly,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= (15.0 * (1.0 - gap / cap)).max(0.0);
        } else {
            // Next item cannot use this leftover: penalize proportionally.
            score += 6.0;
        }
    } else {
        // Last item: minimize waste aggressively.
        score -= 20.0;
    }

    // Last-chance bin before opening a new one: strong reward to use it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 3 {
        // Many alternatives: prefer tight fits among them, mild penalty on slack.
        score += post_residual as f64 * 0.05;
    }

    // New-bin candidate: only attractive when open bins are congested or
    // the fit here is poor (mid-range dead space).
    let is_new_bin = bin_residual == bin_capacity && item_size < bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / cap);
        let penalty = 12.0 + 8.0 * (1.0 - progress) + congestion;
        // Penalize new bin unless current placement creates bad dead space.
        score += penalty;
        if post_residual > quarter && post_residual <= bin_capacity / 2 {
            score -= penalty * 0.9; // allow opening when fit is bad
        }
    }

    // Early stream: keep bins versatile (avoid fragmenting few bins early).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.25 {
        score += post_residual as f64 * 0.03;
    }

    // Slight tie-break toward bins below mean residual (consolidate slack).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in small unusable gaps is heavily penalized.
    // A residual is "dead" if it is too small to fit any plausible item (>= 1) but wasted.
    if post_residual > 0 {
        // Non-linear penalty that grows as post_residual shrinks toward tiny values.
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 25.0 * (10.0 - pr) / 10.0; // tiny slivers are pure waste
        } else if pr < 20.0 {
            score += 12.0 * (20.0 - pr) / 10.0; // small gaps rarely reusable
        }
        // Bonus if post_residual exactly fits the lookahead item (k=2 lookahead synergy).
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 30.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0 * (post_residual as f64 - next_item_size as f64).min(20.0) / 20.0;
        }
    } else {
        // Perfect fill: reward strongly.
        score -= 60.0;
    }

    // Reward tight fits relative to residual (small waste fraction).
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 20.0 * fill_ratio;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones;
    // when few bins are open, opening a new bin is less costly.
    if bin_residual == bin_capacity {
        // New-bin candidate: score it against mean residual of open bins.
        score = bin_capacity as f64 - 15.0 * open_bins_count as f64;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If open bins have large mean residual, opening a new bin is less attractive.
        score += 0.3 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong lookahead: reward exact/near matches between post_residual and next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0) * (1.0 - gap / (bin_capacity as f64));
        // Perfect chain bonus: next item exactly fills the bin.
        if next_item_size == post_residual {
            score -= 150.0;
        }
        // Penalize leaving residual that next item cannot use at all.
        if next_item_size > post_residual {
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Prefer bins whose residual is already small (tight packing).
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.15 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bonus: only bin that fits, avoid opening a new bin for a mediocre fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist,
    // unless post_residual of this bin would be a bad dead space.
    if bin_residual == bin_capacity {
        score += 25.0;
        if next_item_size > 0 && next_item_size <= item_size {
            score += 10.0;
        }
        // Allow new bin late in stream if many bins open and residuals fragmented.
        if open_bins_count > 5 && post_residual as f64 > mean_residual + 20.0 {
            score -= 10.0;
        }
    }

    // Penalize small unusable dead space (<10 cannot hold any item).
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // Early stream: be slightly conservative, keep bins flexible.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 500.0;
    }

    // Tight fit reward: smaller post_residual relative to capacity is better
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // Lookahead: penalize if post_residual can't fit next item but another residual could
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // leaves room for lookahead item
        } else {
            score += 10.0;
            // wasted space that can't serve next item
            score += (post_residual as f64) * 0.3;
        }
        // if post_residual exactly matches next item, strong reward
        if post_residual == next_item_size {
            score -= 60.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: neutral-ish baseline, only attractive when
    // existing fits are poor
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 120.0;
        // cheaper to open a new bin early when few bins open (still cheap phase)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 60.0;
        // opening new bin is more attractive when open bins are fragmented
        // (high mean residual spread) — approximate via mean_residual deviation
        let frag = (mean_residual - post_residual as f64).abs();
        score -= (frag * 0.5).min(40.0);
        // if next item is large, a fresh bin is valuable
        if next_item_size >= item_size {
            score -= 25.0;
        }
    } else {
        // Penalize placing into bins whose residual deviates from mean
        // (keeps bin residuals homogeneous for future packing)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    // Many open bins: discourage spreading, prefer filling existing bins tighter
    if open_bins_count > 4 {
        score += post_residual as f64 * 0.2;
    }

    // Late in stream: prioritize closing bins out (minimize residual)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * post_residual as f64 * 0.5;

    // Penalize leaving residuals in "dead zone" (too small for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear coupling: prefer small post_residual, amplified by progress
    score -= 40.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + progress);

    // Reward tight fits quadratically
    score -= 30.0 * fit * fit * (1.0 - norm_pr);

    // Penalize dead space relative to mean residual smoothly
    score += 0.5 * (pr - mean_residual) * (1.0 - progress);

    // Last-chance bonus (smooth ramp via fitting_bins_count)
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward leaving space for the next item, smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let match_term = 1.0 - ((pr - nx).abs()) / cap;
        score -= 15.0 * match_term * match_term * progress;
    }

    // Slight preference for consolidating into fewer bins
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr) * 2.0;

    // New-bin candidate: penalize mildly unless post_residual is large and progress late
    if bin_residual == bin_capacity {
        score += 10.0 - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover space is.
    // Residuals that divide capacity into nice fractions (50, 25, 20, 10) are valuable.
    let harmonic_bonus: f64 = match post_residual {
        0 => -60.0,                       // perfect fit: extremely desirable
        10 => -35.0,
        20 => -30.0,
        25 => -28.0,
        40 | 50 => -25.0,
        30 | 33 | 34 => -20.0,
        _ => {
            // penalize residuals in awkward dead zones via modulo classes
            let m = post_residual % 10;
            match m {
                0 => -5.0,                // multiples of 10 are semi-usable
                1 | 9 => 12.0,            // nearly-multiple: dead space trap
                _ => 4.0 + (m as f64) * 0.5,
            }
        }
    };
    score += harmonic_bonus;

    // Tight fit reward: item fills a large fraction of the residual
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.9 {
        score -= 25.0;
    } else if fill > 0.7 {
        score -= 12.0;
    } else if fill < 0.35 {
        score += 8.0; // wasteful placement
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) % 10;
            score -= 10.0 - slack as f64; // small slack => better chain
        } else {
            // next item won't fit here; mildly penalize hoarding space
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing bins fit badly
    if bin_residual == bin_capacity {
        // base cost of a new bin
        score += 55.0;
        // early in stream or many open bins with low mean residual => reuse is fine,
        // so keep new-bin penalty high; late stream with fragmented bins => allow new bin
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score -= progress * 15.0 + fragmentation * 0.2;
        // big items favor fresh bins
        if item_size > 70 {
            score -= 20.0;
        }
    }

    // Slight preference for bins with lower current residual (best-fit flavor)
    score += (bin_residual as f64) * 0.05;

    // Tie-break noise-free harmonic nudge on bin index class
    score -= ((open_bins_count % 4) as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

