    }

    // Open-bins pressure: with many open bins, discourage opening yet another bin;
    // the new-bin candidate (full residual) gets penalized proportionally.
    if bin_residual == bin_capacity {
        score += 30.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 1.0 * open_bins_count as f64;
    }

    // Prefer bins whose residual is below the mean (consolidate small gaps).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Early in the stream, be slightly more willing to open bins (build good structure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

