    let pr_frac = pr / cap;

    // Non-linear penalty on wasted space: cubic coupling with stream progress.
    // Late in the stream, dead space is more costly, so amplify the penalty smoothly.
    let waste_penalty = pr_frac.powi(3) * (1.0 + 2.0 * progress);
    score += waste_penalty * cap;

    // Reward near-perfect fits smoothly: subtract a bell-shaped bonus around pr≈0.
    let tight_bonus = (-(pr_frac * 4.0).powi(2)).exp() * (10.0 + 20.0 * progress);
    score -= tight_bonus;

    // Lookahead coupling: if the next item exactly fits the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        let lookahead_bonus = (-(gap / cap).powi(2) * 8.0).exp() * (15.0 + 10.0 * progress);
        score -= lookahead_bonus;
        // Penalize leaving a residual that is awkwardly large relative to next item
        if pr > nx {
            score += ((pr - nx) / cap).powi(2) * 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly encourage using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 + 15.0 * progress;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor fits.
    if bin_residual == bin_capacity {
        // Mild penalty so existing bins are preferred unless their scores are bad.
        score += 20.0 + 10.0 * (1.0 - progress);
        // But if many items remain and mean residual is fragmented, opening a new bin
        // becomes relatively more attractive.
        score -= progress * mean_residual * 0.3;
    }

    // Slight preference to fill bins with larger residuals relative to the mean
    // (consolidate space), smooth quadratic coupling.
    score -= ((bin_residual as f64 - mean_residual) / cap) * 3.0;

    // Mild encouragement to keep the number of open bins low late in the stream.
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into residue classes
    // modulo small integers to detect "good" leftover sizes (multiples of common item sizes).
    let pr = post_residual;
    let class10 = pr % 10;
    let class20 = pr % 20;

    // Reward leftover sizes that are "harmonic" (divisible by 10): highly reusable.
    if class10 == 0 && pr > 0 {
        score -= 6.0;
    } else if class10 <= 2 {
        score += 4.0; // nearly-dead slivers are useless
    }

    // Reward leftovers divisible by 20 (fits half-capacity classes).
    if class20 == 0 && pr >= 20 {
        score -= 4.0;
    }

    // Dead-space penalty: leftover below the minimum plausible item size.
    if pr < 10 && pr > 0 {
        score += 15.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 12.0;
        } else if next_item_size <= pr {
            // harmonic fit quality: how close next item is to filling the leftover
            let fill = next_item_size as f64 / pr as f64;
            score -= 5.0 * fill;
            // reward if post_residual - next_item is again a harmonic class
            if (pr - next_item_size) % 10 == 0 {
                score -= 3.0;
            }
        } else {
            // next item cannot use this leftover: penalize small leftovers more
            score += 3.0 + 5.0 * (1.0 - pr as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Prefer fuller bins generally (tight-fit bonus for small post_residual).
    if pr <= 5 {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless current leftovers are bad.
    if bin_residual == bin_capacity {
        score += 20.0;
        // but if the item is huge relative to capacity and few bins fit it, opening is fine
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Stream progression: later in the stream, be more conservative with new bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 2.0 * progress * (pr as f64 / bin_capacity as f64);
    }

    // Slight preference toward bins below mean residual (balance across bins).
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to residual (waste ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio;

    // Last-chance pressure: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor consolidation.
    score += 0.8 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit here: penalize leaving a large residual that becomes dead space.
            score += 5.0;
        }
    }

    // Mean residual coupling: placing into a bin below mean residual consolidates small gaps.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: only attractive when no open bin fits well or stream is early.
    if bin_residual == bin_capacity {
        let stream_frac = step_index as f64 / total_items.max(1) as f64;
        let desperation = (post_residual as f64 / bin_capacity as f64) * 30.0
            + (fitting_bins_count == 0) as i32 as f64 * 50.0
            + (1.0 - stream_frac) * 5.0;
        score = 55.0 - desperation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact-ish fits: small post_residual is good.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 + 10.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize dead space that next item cannot use.
        score += 8.0;
    }

    // Relative-to-mean coupling: bins tighter than average are preferred targets.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 12.0 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a brand-new bin when decent fits exist.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if next item is huge and post_residual is large, new bin is fine.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0;
        }
    }

    // Early stream: be slightly greedy toward tight fits; late stream: consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: exponential bonus for small post-residual
    let tight = post_residual as f64 / bin_capacity as f64;
    score -= 18.0 * (-14.0 * tight).exp();

    // Penalize dead space that no plausible future item can use
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny useless slivers
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are bad
    if bin_residual == bin_capacity {
        // penalize opening new bin, more so mid-stream and when many bins open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 15.0 * progress + 0.3 * open_bins_count as f64;
        // but if the item is huge relative to mean residual, allow it
        if (mean_residual < item_size as f64 * 0.5) {
            score -= 14.0;
        }
    }

    // Global balance: prefer bins whose residual deviates from the mean in a useful way
    let dev = bin_residual as f64 - mean_residual;
    score += 0.04 * dev;

    // Mild preference for fuller bins late in the stream (consolidation phase)
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * t * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let is_new_bin = (bin_residual as u64 == bin_capacity as u64) as f64;

    // Base: prefer minimal post residual, with a non-linear tightening reward.
    let mut score = post;

    // Smooth quadratic coupling of post_residual with stream progress:
    // late in the stream, dead space is more costly (bins are less likely reused).
    let dead_space_weight = 0.35 + 0.65 * progress * progress;
    score += dead_space_weight * (post / cap) * post * 0.5;

    // Lookahead: reward if the next item fits the post residual (smooth reward),
    // penalize residual that neither fits the next item nor is small.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 6.0 * (1.0 - post / cap) * (nxt / post.max(1.0));
        } else {
            // residual too small for next item: penalize proportionally to waste
            score += 3.0 * (post / cap) * (1.0 - post / nxt);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && is_new_bin < 0.5 {
        score -= 12.0 * (1.0 - post / cap);
    }

    // New-bin candidate: penalize mildly; allow opening when the item is large
    // relative to capacity (few open bins can host it well) and mean residual is low.
    score += is_new_bin * (10.0 + 8.0 * (1.0 - item_size as f64 / cap));

    // Interaction: when mean residual across open bins is small, opening a new
    // bin becomes relatively more attractive (subtract from new-bin penalty).
    score -= is_new_bin * (mean_residual / cap) * 9.0;

    // Smooth coupling with open bin count: many open bins -> prefer consolidation.
    let consolidation = (open_bins_count as f64).ln().max(0.0);
    score += (1.0 - is_new_bin) * consolidation * (post / cap) * 2.0;

    // Cubic smoothness term favoring near-perfect fits regardless of phase.
    let fit_quality = 1.0 - post / cap;
    score -= 5.0 * fit_quality * fit_quality * fit_quality * (1.0 - is_new_bin);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lands in
    // "reusable" residue classes (multiples of common item sizes) are favored.
    let pr = post_residual;
    let reusable = if pr == 0 { 60.0 }
        else if pr % 50 == 0 { 40.0 }
        else if pr % 25 == 0 { 30.0 }
        else if pr % 20 == 0 { 25.0 }
        else if pr % 10 == 0 { 18.0 }
        else if pr % 5 == 0 { 10.0 }
        else { 0.0 };
    score -= reusable;

    // Exact fill is golden.
    if pr == 0 { score -= 25.0; }

    // Penalize tiny dead space (unusable slivers) with a quadratic term.
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless post residual would be a bad sliver).
    if fitting_bins_count == 1 {
        score -= 15.0;
        if pr > 0 && pr < 10 { score += 20.0; }
    }

    // Lookahead coupling: reward if next item fits into post_residual exactly
    // or well; penalize if next item cannot use the leftover.
    if next_item_size > 0 && next_item_size <= pr {
        let next_fit = pr - next_item_size;
        score -= 12.0;
        if next_fit == 0 { score -= 20.0; }
        if next_fit > 0 && next_fit < 10 { score += 8.0; }
    } else if next_item_size > pr && pr > 0 {
        // leftover too small for lookahead: mild penalty scaled by sliver size
        score += (pr as f64).min(10.0) * 0.8;
    }

    // Prefer tighter bins generally: divide residual into capacity fractions.
    let frac = bin_residual as f64 / bin_capacity as f64;
    score += frac * 6.0;

    // When many bins are open, consolidate; when few, allow new bins.
    if open_bins_count > 3 {
        score -= 4.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default so that
    // only genuinely good open-bin placements beat it.
    if bin_residual == bin_capacity {
        score += 18.0;
        // Late in the stream, opening new bins is wasteful; make new bins costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mean residual coupling: if this bin's residual is far above mean,
    // it's a loose bin — mildly discourage leaving it even looser.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 35 {
        score += 4.0;
    } else {
        // Larger residuals are more reusable; mild reward relative to baseline.
        score -= 3.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward if the next item can fit into the post-residual gap.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // Even better if next item nearly fills the gap (keeps dead space tiny).
            let nxt_gap = post_residual - next_item_size;
            if nxt_gap < 10 {
                score -= 8.0;
            }
        } else {
            // Next item cannot use this gap: gap likely becomes dead space.
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidation into
    // existing bins; when few are open, new bins are cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 4.0;

    // Mean residual coupling: if mean residual is high, tighten selection
    // toward bins below mean (avoid spreading waste).
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 2.0;
    }

    // New-bin candidate: neutral-ish base; only attractive when current bins
    // are fragmented (low mean residual) or many bins already open.
    if bin_residual == bin_capacity {
        score = 30.0 + pressure * 2.0 - mean_residual * 0.15;
        if next_item_size > 0 && next_item_size >= bin_capacity - 10 {
            score -= 20.0; // big next item: fresh bin is good
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near match: next item almost fills the post residual
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 25.0 / (1.0 + gap);
    }

    // Penalize post_residual that is too small to hold the next item
    // (dead space the lookahead item cannot use)
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Prefer bins whose residual is tighter than the mean (good fill)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last fitting bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Discourage opening a new bin when a decent fit exists in an open bin
    if bin_residual == bin_capacity {
        // new empty bin candidate: baseline cost of a fresh bin
        score += 40.0;
        // but if post_residual matches the next item, a fresh bin is fine
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 60.0;
        }
    }

    // Late in the stream, consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Slight preference for fewer open bins (encourage closing bins)
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Lookahead: penalize residuals that fit the next item poorly but not exactly,
    // reward residuals that exactly fit next_item_size (chain packing)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let waste = (post_residual - next_item_size) as f64;
            score += waste * 0.3;
        }
        // residual too small for next item: dead space unless tiny
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // New-bin candidate handling: only attractive when current fit is poor
    if bin_residual == bin_capacity {
        if post_residual as f64 > bin_capacity as f64 * 0.45 {
            score -= 25.0; // opening fresh bin fine for small items
        } else {
            score += 60.0; // discourage opening bins for large items that fit open ones
        }
        // when many bins are open with slack, avoid spreading
        score += open_bins_count as f64 * 1.5;
    }

    // Prefer filling bins with above-average residual (consolidate slack)
    if bin_residual as f64 > mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Time horizon: early in stream be more conservative about new bins (handled above);
    // late in stream, prioritize zero-waste closure
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Smooth non-linear penalty for large residuals (dead space), growing with progress
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Coupling with mean residual: prefer bins below mean residual (tighter than average)
    score += 0.35 * (pr - mean_residual) * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // Lookahead: if next item fits exactly into post residual, reward heavily
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 10.0 * (1.0 - diff / cap).max(0.0);
        // Penalize post residuals that are unusable for the next item
        if pr < next_item_size as f64 && pr > 0.0 {
            score += 5.0 * norm_pr;
        }
    }

    // Mild penalty for spreading across many open bins early (encourage consolidation)
    score += 0.15 * open_bins_count as f64 * (1.0 - progress) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 20.0;

    // Harmonic class: bucket post_residual into capacity fractions via integer division.
    let class = post_residual / (bin_capacity / 4); // quarters
    let class_penalty = match class {
        0 => -30.0, // residual < 25: near-perfect fill, dead space minimal
        1 => -10.0, // 25..50: still usable for mid items
        2 => 5.0,   // 50..75: awkward mid zone
        _ => 15.0,  // >=75: wasteful unless bin was fresh
    };
    score += class_penalty;

    // Perfect fit reward: post_residual is an exact multiple of small item sizes.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual < 10 {
        score -= 5.0; // tiny dead space, effectively full
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic check: post_residual - next_item_size lands in a good class?
            let rem = post_residual - next_item_size;
            if rem < 10 {
                score -= 25.0; // next item nearly closes the bin
            } else if rem % 10 == 0 {
                score -= 12.0;
            } else {
                score -= 4.0;
            }
        } else {
            // Next item won't fit here: penalize proportionally to how close it is.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: fresh empty bin should only win when open bins are bad.
    if bin_residual == bin_capacity {
        // Penalize opening new bins early in the stream / when many bins open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 60.0 + 40.0 * (1.0 - progress);
        if post_residual >= 75 {
            score -= 20.0; // fresh bin keeps large residual for big future items
        }
    }

    // Dead-space penalty relative to mean residual across open bins.
    if (post_residual as f64) > mean_residual * 1.5 {
        score += 10.0;
    } else if (post_residual as f64) < mean_residual * 0.5 {
        score -= 6.0;
    }

    // Modulo threshold on item_size: odd-sized items create fragmentation; prefer
    // pairing them into bins whose residual stays in the same decade class.
    if item_size % 10 != 0 && post_residual % 10 != 0 {
        score += 3.0;
    }

    // Slight preference to balance across many open bins when residuals are small.
    if post_residual < 15 && open_bins_count > 1 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 8.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 2.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward near-perfect fits proportionally to item size (large item placed tightly is valuable).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * item_size as f64 * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score += 5.0; // would create dead space for the next item
        }
    }

    // Open bins pressure: mild penalty per open bin, encouraging consolidation,
    // but only when this bin is a real (non-new) bin.
    if bin_residual != bin_capacity {
        score += open_bins_count as f64 * 0.3;
    } else {
        // New-bin candidate: only attractive when open bins are crowded or fit is poor.
        score += 12.0;
        if open_bins_count == 0 {
            score -= 25.0;
        }
        if mean_residual > item_size as f64 * 1.5 {
            score += 10.0; // existing bins have room; discourage new bin
        }
    }

    // Late in the stream, be slightly more conservative about new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (dead space minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // 2-step lookahead: if next item exactly fills post_residual, huge bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // next item fits here too: reward proportionally to tightness
            let tightness = next_item_size as f64 / post_residual as f64;
            score -= 100.0 * tightness;
        } else {
            // next item won't fit in the leftover: penalize large dead gaps
            let waste = next_item_size as f64 - post_residual as f64;
            score += 0.5 * waste;
        }
    }

    // Compare post_residual against mean residual: leaving less than average
    // leftover is good (this bin becomes compact), more than average is bad.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
        if post_residual <= 15 {
            score -= 100.0;
        }
    }

    // New-bin candidate: neutral baseline with slight penalty so we only open
    // a new bin when open bins would leave genuinely bad residuals.
    if bin_residual == bin_capacity {
        score += 40.0;
        // If next item is large and current item small, a fresh bin may be
        // preferable; slightly soften the penalty.
        if next_item_size >= 60 && item_size <= 30 {
            score -= 30.0;
        }
    }

    // Late in the stream, be more conservative: prefer closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    // Mild pressure against spreading across many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual relative to item size.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 12.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize large dead space, especially if it can't fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 6.0 + 0.25 * post_residual as f64;
        } else {
            // Reward bins that can also accommodate the lookahead item.
            score -= 4.0 * (next_item_size as f64 / 100.0);
        }
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // When many bins are open, prefer consolidating into existing ones.
    if open_bins_count > 4 {
        score -= 0.4 * (open_bins_count as f64).ln();
    }

    // Compare against mean residual: bins with much more residual than average
    // are better candidates to absorb this item.
    score -= 0.15 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in the stream, be more conservative about opening
    // new bins; late in the stream, exact fits matter more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early, penalized later unless item is huge.
        score = score * 0.5 + 8.0 + 10.0 * progress - 0.05 * item_size as f64;
    } else {
        score -= 3.0 * progress * (1.0 - fit_ratio);
    }

    // Exact-fill reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear penalty for residual that is likely unusable (smooth polynomial)
    let prn = pr / cap;
    score += 8.0 * prn * prn * (1.0 - prn) * (1.0 - prn) * cap * 0.1;

    // Reward tight fits: post_residual near zero strongly favored
    score -= 20.0 * (-prn * 12.0).exp();

    // Stream progress coupling: late in stream, prefer minimizing dead space more aggressively
    score -= progress * 10.0 * prn * prn;

    // Last-chance bin bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - ((pr - nxt) / cap).abs());
        } else {
            score += 3.0 * ((nxt - pr) / cap);
        }
    }

    // Prefer bins with residual close to item size (tight relative fit), smooth coupling
    let fit_ratio = (bin_residual as f64 - item_size as f64) / cap;
    score += 5.0 * fit_ratio * fit_ratio * (1.0 - progress);

    // Mild penalty for spreading across too many open bins
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.88;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, or below min item) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Penalize gaps that no plausible future item can fill (gap too small relative to typical sizes).
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Reward perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward very tight fits (post residual close to zero).
    score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 55.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    }

    // Open-bin pressure: discourage spreading across many bins; favor filling existing bins.
    score += (open_bins_count as f64) * 1.5;

    // Prefer bins with below-mean residual (fill emptier bins first keeps tight bins for tight items).
    if (bin_residual as f64) > mean_residual {
        score += 8.0;
    } else {
        score -= 4.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when many bins already open
        // (consolidation hopeless) or late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 45.0 - 15.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            new_bin_score -= 10.0;
        }
        score = score.max(new_bin_score) + new_bin_score * 0.5;
        score = new_bin_score.max(score.min(new_bin_score + 1.0));
        score = new_bin_score;
        if fitting_bins_count == 1 {
            // A new bin should lose to a last-chance existing bin.
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: residual consumed by next item
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            // penalize by leftover after hypothetical next placement
            score += leftover as f64 * 0.3;
            score -= 15.0; // still reward a feasible chain
        } else {
            // next item cannot fit; residual becomes dead space
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Relative to mean residual: prefer bins with residual below mean (tight bins)
    score += (bin_residual as f64 - mean_residual) * 0.4;

    // Penalize large post_residual dead space nonlinearly
    if post_residual > 0 {
        score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 20.0;
    }

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening new bins unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 35.0;
        // allow new bin late in stream or when next item is large
        if next_item_size >= 70 {
            score -= 10.0;
        }
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 5.0;
    }

    // Prefer denser packing when many bins are open
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 12.0;

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Residual usable by next item: reward proportional to how snugly next item fits.
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= next_fit * 8.0;
        } else {
            // Dead space: penalize waste, especially if next item is large.
            let waste = post_residual as f64;
            score += waste * 0.6 + (next_item_size as f64 - post_residual as f64) * 0.4;
        }
    } else {
        // Last item: just minimize post_residual (already base).
        score -= 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a near-perfect
    // packing of the item plus expected future demand.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        // New bin wastes (C - item) initially; acceptable early or with big items.
        let mut new_bin_penalty = (bin_capacity - item_size) as f64 * 0.9;
        // Later in the stream, opening bins is more costly (fragmentation risk).
        new_bin_penalty *= 0.5 + progress;
        // If item is large, new bin is fine; if small, discourage.
        if item_frac < 0.35 {
            new_bin_penalty += 10.0;
        }
        // If no open bin fits (fitting_bins_count counts only open ones; new bin included
        // as candidate), the penalty above governs; but if many bins open, discourage more.
        new_bin_penalty += open_bins_count as f64 * 0.3;
        score += new_bin_penalty;
    }

    // Prefer bins whose residual deviates below the mean (consolidating fuller bins).
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.15;

    // Mild non-linear bonus for near-exact fills.
    let perfect = (post_residual as f64 / bin_capacity as f64).powi(2);
    score -= (1.0 - perfect * 4.0).max(0.0) * 3.0;

    // Slight time-dependent exploration: early stream, be tolerant; late stream, be greedy.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover space, with non-linear (quadratic) coupling to stream progress.
    let mut score = pr * (1.0 + 0.8 * progress) + 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) with a smooth superlinear bonus.
    score -= 30.0 * (1.0 - norm_pr).powi(3);

    // Lookahead: penalize if post_residual cannot fit next item, reward if it can.
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 8.0 * (1.0 - (next_item_size as f64) / cap) * (0.5 + progress);
        } else {
            score += 6.0 + 10.0 * progress;
        }
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Penalize bins far from mean residual (prefer homogeneous residual pool), smooth coupling.
    score += 0.5 * (pr - mean_residual).abs() * (0.5 + progress);

    // Mild pressure against opening many new bins late in the stream.
    score += 0.3 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals in [0,10) are near-perfect,
    // [10,20) still very usable for small items, larger classes progressively worse.
    let class = post_residual / 10;
    score += match class {
        0 => -30.0,                       // near-perfect fit
        1 => -10.0,                       // good
        2 => 0.0,
        3 => 6.0,
        4 => 12.0,
        _ => 18.0,                        // large dead space
    };

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // partial compatibility, scaled by how much slack would remain
            let slack = post_residual - next_item_size;
            score -= 10.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this residual: penalize proportionally to leftover
            score += 4.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin is a fallback.
    if bin_residual == bin_capacity {
        // attractive early (few open bins) or when the item is large relative to capacity
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fallback_penalty = 8.0 + 10.0 * progress + 6.0 * (item_size as f64 / bin_capacity as f64);
        score += fallback_penalty;
        // if no open bin could otherwise fit, new bin is the only option
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer placing into bins whose residual is already below the mean
    // (consolidates waste into few bins, keeps other bins flexible).
    score += 3.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    // Mild pressure against proliferating bins mid-stream.
    score += 0.15 * open_bins_count as f64;

    // Tie-break: exact-fill gets a deterministic nudge via integer division residue.
    score -= (post_residual % 3) as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever host
    // another typical item are pure waste; punish them super-linearly.
    let pr = post_residual as f64;
    if post_residual > 0 {
        if post_residual < 10 {
            // unusable sliver: nearly as bad as a full bin
            score += 40.0 * (10.0 - pr) / 10.0;
        } else {
            // usable gap: mild quadratic penalty to prefer tighter fits
            score += 0.02 * pr * pr;
        }
    } else {
        // perfect fill: strong reward
        score -= 60.0;
    }

    // Exact-fit lookahead: if the next item fits the post-residual exactly,
    // this placement chains perfectly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Last-chance pressure: if this is the only bin that fits the item,
    // strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins over spreading out.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual != bin_capacity {
        score -= 3.0 * open_pressure;
    } else {
        // New-bin candidate: only attractive when existing residuals are
        // fragmented (high mean residual) or few bins fit the item.
        score += 25.0 + 5.0 * open_pressure - 0.15 * mean_residual
                 + 8.0 * (fitting_bins_count as f64);
    }

    // Late in the stream, closing bins tightly matters more; tighten fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 15.0 * progress * (1.0 - pr / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near match: next item fits with small leftover
    else if next_item_size > 0 && post_residual > next_item_size {
        let leftover = (post_residual - next_item_size) as f64;
        score -= 200.0 - leftover * 2.0;
    }
    // Next item cannot fit in this residual: penalize proportionally
    else if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 1.5;
    }

    // Penalize dead space relative to mean residual across open bins
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Progression: later in stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    // Many open bins: prefer consolidating into existing bins
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate: only attractive when no open bin gives a good fit
    if bin_residual == bin_capacity {
        score += 80.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post residual.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Lookahead coupling: reward residual that can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Penalize dead space the next item cannot use, scaled by dead fraction.
            let dead = (post_residual as f64) / (next_item_size as f64);
            score += 4.0 * dead;
        }
    } else {
        // Last item: strongly prefer near-perfect fill.
        score += 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Mean-residual anchoring: prefer bins deviating favorably from the fleet mean.
    score += 0.35 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate control: only attractive early in the stream or when open
    // bins are heavily fragmented (mean residual low relative to item size).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (item_size as f64) / (mean_residual.max(1.0));
        let penalty = 22.0 + 30.0 * (1.0 - progress) * (1.0 - fragmentation.min(1.0));
        score += penalty;
        // If nothing else fits well, new bin becomes viable.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild diversity pressure: many open bins -> prefer consolidating into emptier bins.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Late-stream horizon: squeeze bins harder as the stream ends.
    let horizon = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * horizon * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear penalty on residual: dead space becomes more costly as stream progresses
    let dead = norm_pr * norm_pr * (0.5 + progress);
    score += 40.0 * dead;

    // Reward tight fits (small post_residual) with smooth cubic term
    score -= 15.0 * (1.0 - norm_pr).powi(3) * (1.0 + progress);

    // Lookahead coupling: reward if next item fits in post_residual, penalize if it nearly fits
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 8.0 * (1.0 - (next_item_size as f64) / cap);
        } else {
            let gap = (next_item_size as f64) - pr;
            score += 6.0 * (gap / cap) * (1.0 + progress);
        }
    }

    // Last-chance bonus: strongly favor this bin when it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mean-residual coupling: prefer bins below mean residual (consolidate emptier space)
    score += 0.3 * (mean_residual - pr);

    // New-bin candidate: penalize mildly so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 10.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual: quantize leftover space into capacity fractions ---
    // Residual classes: tiny (1-9), small (10-24), medium (25-49), large (50-99), exact (0)
    let post_class: f64 = if post_residual == 0 {
        0.0 // perfect fit: strongly reward
    } else if post_residual < 10 {
        1.0 // tiny dead space
    } else if post_residual < 25 {
        2.0
    } else if post_residual < 50 {
        3.0
    } else {
        4.0 // huge leftover: bin was nearly empty anyway
    };
    score += post_class * 6.0;

    // Exact fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Modular harmonic: post_residual divisible by common item sizes (10, 20, 25, 50) is reusable
    if post_residual > 0 {
        let reusable = (post_residual % 10 == 0) || (post_residual % 20 == 0) || (post_residual % 25 == 0) || (post_residual % 50 == 0);
        if reusable {
            score -= 5.0;
        }
        // Penalize post-residuals in "awkward" harmonic band (just below typical item sizes)
        if (post_residual % 10) > 0 && post_residual < 20 {
            score += 4.0; // sliver below small-item floor
        }
    }

    // --- Lookahead coupling: does the next item fit into the post-residual? ---
    if next_item_size > 0 && post_residual >= next_item_size {
        // Reward leaving exactly enough room for the next item (chain fit)
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - slack * 0.15;
        if post_residual == next_item_size {
            score -= 15.0; // perfect chain fill
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Post-residual cannot host next item: penalize proportionally to waste
        score += (next_item_size as f64) * 0.08;
    }

    // --- Last-chance bin: if this is the only bin that fits, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly
        // (large post_residual in this fresh bin is fine since it stays flexible)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base cost of a new bin: high, so it's chosen only on bad fits elsewhere
        score += 55.0 - 10.0 * progress;
        // If no open bin can fit the item, new bin is unavoidable-ish: soften penalty
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Late in the stream, prefer consolidating: make new bins slightly costlier
        score += progress * 8.0;
    } else {
        // Prefer fuller bins: reward small bin_residual (tight fits into existing load)
        score -= (bin_capacity - bin_residual) as f64 * 0.10;
    }

    // --- Mean-residual coupling: if open bins are generally full, discourage spreading ---
    if bin_residual != bin_capacity && (mean_residual as u32) < bin_residual {
        score += 2.0; // this bin is emptier than average: deprioritize
    } else if bin_residual != bin_capacity {
        score -= 2.0;
    }

    // Slight preference for reducing open bin count pressure
    if bin_residual != bin_capacity && open_bins_count > 4 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item (<= 10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Penalize moderate dead space that likely cannot absorb the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Reward perfect or near-perfect fills strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into
    // existing bins rather than spawning more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 2.0 * progress);

    // New-bin candidate: only attractive when current bins have poor fit
    // (item barely fits or huge residual mismatch). Make the empty bin
    // slightly unattractive by default so it is chosen only when needed.
    if bin_residual == bin_capacity {
        score += 12.0 + mean_residual * 0.3;
        // If the next item would fit nicely in the fresh residual, ease it.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 20.0;
        }
    }

    // Mild preference for bins whose residual is close to the item size
    // (tight fit relative to the open-bin population).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward tight match to lookahead item.
        score -= 30.0 / (1.0 + diff);
        // Penalize leftover that is smaller than next item (dead space for lookahead).
        if post_residual < next_item_size {
            score += 15.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
        // Bonus if the next item fits and leaves another small residual.
        if post_residual >= next_item_size {
            let chain = post_residual - next_item_size;
            if chain <= 10 {
                score -= 12.0;
            } else if chain < item_size {
                score -= 5.0;
            }
        }
    } else {
        // Last item: strongly prefer minimal residual.
        score += 10.0;
    }

    // Relative-to-mean coupling: bins with residual above mean are better targets
    // for large placements; below-mean bins should only take near-perfect fits.
    let res = post_residual as f64;
    if res > mean_residual {
        score -= 0.3 * (res - mean_residual);
    } else {
        score += 0.3 * (mean_residual - res);
    }

    // Last-chance bin: this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        let poor_fit = next_item_size > 0 && post_residual < next_item_size && post_residual > 0;
        score += 40.0;
        if poor_fit {
            score -= 55.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer filling tighter bins generally.
    score -= 0.2 * (bin_capacity - bin_residual) as f64;

    // Small tie-breaker toward larger items consuming big residuals.
    score -= 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early on, keep flexibility; late, fill aggressively.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: quadratic bonus for small post_residual.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space that is too small for the smallest plausible follow-up item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 4.0 * (1.0 - t);
        } else {
            score += 3.0 * t;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer bins below mean residual (sparser bins absorb big items better).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Many open bins: encourage consolidation into existing bins.
    score += 0.15 * open_bins_count as f64 * (1.0 - t);

    // New-bin candidate: penalize opening a new bin unless item is large
    // and no good fit exists; allow it late in the stream.
    if bin_residual == bin_capacity {
        let waste = bin_capacity as f64 - item_size as f64;
        score += 15.0 + waste * 0.4 - 10.0 * t;
        if fitting_bins_count > 0 {
            score += 8.0;
        }
    }

    // Slight preference for bins with larger residual among comparable fits.
    score -= 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap; // normalized post-residual in [0,1]

    // Base: penalize leftover space, with non-linear (quadratic/cubic) shaping.
    let mut score = pr * (1.0 + norm_pr * norm_pr);

    // Smooth polynomial coupling with stream progress:
    // early on, tolerate larger residuals slightly (bins may still be filled),
    // late in stream, penalize waste more aggressively.
    let prog_coupling = 1.0 + progress * progress * (1.0 - progress) * 2.0;
    score *= prog_coupling;

    // Perfect / near-perfect fit reward: subtract strongly when post_residual is tiny.
    let tightness = (cap - pr) / cap; // fraction of bin used after placement
    score -= tightness * tightness * tightness * cap * 0.5;

    // Lookahead: reward leaving room for the next item (smooth interaction).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = pr - nx;
        if diff >= 0.0 {
            // post-residual can accommodate next item: reward proportionally,
            // strongest when it's an exact-ish fit for the next item too.
            let fit_next = 1.0 - (diff / cap).abs();
            score -= fit_next * fit_next * nx * 0.4;
        } else {
            // leaves a gap smaller than next item: penalize dead space smoothly.
            score += (-diff) * (1.0 + progress) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= cap * 0.6 * (1.0 - progress * 0.5);
    }

    // Mild pressure against spreading across many open bins when residuals are large.
    score += open_bins_count as f64 * mean_residual * 0.01 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: post_residual mod 10 classes.
    let pr = post_residual;
    let class = pr % 10;
    // Dead-space penalty: small nonzero leftovers (1..9) are hard to fill.
    if pr > 0 && pr < 10 {
        score += 12.0 - class as f64; // tiny leftovers are the worst
    }
    // Perfect fit rewarded.
    if pr == 0 {
        score -= 30.0;
    }

    // Harmonic thresholds on post_residual: leftover that can host common sizes.
    if pr >= 50 {
        score -= 6.0;
    } else if pr >= 30 {
        score -= 3.0;
    } else if pr >= 20 {
        score += 1.0;
    }

    // Coupling with lookahead: does the leftover accommodate the next item exactly?
    if next_item_size > 0 {
        if pr >= next_item_size {
            let slack = pr - next_item_size;
            if slack == 0 {
                score -= 20.0; // leaves exact room for next item
            } else if slack < 10 {
                score += 5.0; // creates another dead space for next item
            } else {
                score -= slack as f64 * 0.1;
            }
        } else {
            // leftover too small for next item: penalize proportionally
            score += (next_item_size - pr) as f64 * 0.05;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many open bins: encourage consolidation (prefer filling existing bins).
    if open_bins_count > 3 {
        score -= (open_bins_count as f64).sqrt() * 0.8;
    }

    // Mean-residual alignment: prefer bins close to the mean residual (balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Early stream: be a bit more willing to spread; late stream: pack tight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 4.0;

    // New-bin candidate: make empty bins attractive only when fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, offset by how bad the alternatives look.
        score = bin_capacity as f64 * 0.35 + 10.0;
        if fitting_bins_count == 1 {
            score += 25.0; // an existing bin is the only fit: keep using it
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 5.0; // next item could pair here, but existing bins get priority
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space zone: residual too small for the smallest possible item (1).
    // Any post_residual > 0 that cannot fit the NEXT item is likely wasted.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize unusable gaps; worse when the gap is tiny relative to need.
        let gap_waste = (next_item_size - post_residual) as f64;
        score += 2.0 * gap_waste + 5.0;
        // Extra penalty if NO other bin could take the next item either.
        if fitting_bins_count == 1 {
            score += 10.0;
        }
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 3.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing bins are crowded
    // or no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        // Base cost of opening a new bin, offset by open-bin pressure.
        score += 30.0 - 1.5 * pressure;
        // If item is large, a fresh bin is fine; if small, prefer squeezing in.
        score -= 0.1 * item_size as f64;
        // If this is the only fitting option anyway, neutralize the penalty.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // Mild preference to place into bins with lower mean residual
    // (consolidate fullness across bins).
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    // Late in the stream: be slightly more conservative about new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

