    score += 0.10 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Slight preference for filling bins tighter when many bins are open
    score -= 0.05 * (item_size as f64) * (open_bins_count as f64).ln().max(1.0) / 10.0;

    // Progress-based tightening: later in stream, prefer low post_residual more
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    // New-bin candidate: make it mildly unattractive unless residual is huge
    if bin_residual == bin_capacity {
        score += 15.0 - 0.1 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize relative waste quadratically.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < 10 {
            // small dead space is tolerable
            score += 3.0;
        } else {
            // wasted mid-sized gap the next item can't use
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins have large, awkward residuals
    // or few bins fit the item.
    if bin_residual == bin_capacity {
        let awkward = mean_residual / bin_capacity as f64;
        score -= 5.0 + 30.0 * awkward;
        if fitting_bins_count <= 2 {
            score -= 15.0;
        }
    } else {
        // Penalize placing into bins already far below the mean residual (hoarding space).
        if (bin_residual as f64) < mean_residual - 15.0 {
            score += 6.0;
        }
    }

    // Late in the stream, consolidate aggressively to close out bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild pressure against proliferating many open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let isz = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r_norm = pr / c;
    let fit_norm = bin_residual as f64 / c;

    // Base: penalize wasted residual, non-linearly.
    let mut score = pr as f64;

    // Smooth polynomial coupling: residual waste interacts with stream progress.
    // Early on, tolerate some waste; late, punish dead space quadratically.
    let waste_curve = r_norm * r_norm * (0.5 + 2.5 * progress) + r_norm * (1.0 - progress);
    score += 60.0 * waste_curve;

    // Reward tight fits (small post_residual relative to item) with smooth term.
    let tightness = isz / (bin_residual.max(1) as f64);
    score -= 25.0 * tightness * (1.0 - tightness) * (1.0 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0 + 40.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward (smooth).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        let nx_fits = (nx <= pr) as i32 as f64;
        score -= nx_fits * (35.0 * (1.0 - gap / c).max(0.0));
        score += (1.0 - nx_fits) * 10.0 * (1.0 - progress) * r_norm;
    }

    // Penalize opening new bins when many bins already fit the item (fragmentation risk).
    let fit_ratio = fitting_bins_count as f64 / (open_bins_count.max(1) as f64);
    score += 15.0 * fit_ratio * r_norm * (1.0 + progress);

    // Mean-residual coupling: prefer bins whose post-residual aligns with fleet mean
    // to keep residuals harvestable together.
    let mean_gap = (pr - mean_residual).abs() / c;
    score += 8.0 * mean_gap * mean_gap * (1.0 - progress);

    // New-bin candidate: smooth gate favoring it only for large items / bad fits.
    if bin_residual == bin_capacity {
        let large = (isz / c).powi(2);
        score = 55.0 + 45.0 * large + 30.0 * (1.0 - progress) - 20.0 * (fitting_bins_count as f64).min(3.0) / 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small residue" classes are more valuable to preserve.
    let pr = post_residual;
    if pr > 0 {
        let class = pr / 10; // integer-division harmonic class (0..10)
        // Dead-space penalty grows for mid-sized residues that few items fit.
        score += match class {
            0 => -6.0,                       // near-perfect fit, excellent
            1 => -2.0,                       // residue 10..19, still very usable
            2 | 3 => 2.0,                    // 20..39, awkward zone
            4 | 5 => 5.0,                    // 40..59, half-empty
            _ => 8.0,                        // 60..99, wasteful placement
        };
        // Modulo coupling: residues divisible by 10 pair well with common sizes.
        if pr % 10 == 0 {
            score -= 3.0;
        } else if pr % 5 == 0 {
            score -= 1.0;
        }
    } else {
        // Perfect fill: strongly reward.
        score -= 25.0;
    }

    // Lookahead: reward leaving room for the next item exactly.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (ni - 1.0) <= post_residual as f64 {
            score -= 10.0 + ni * 0.05;       // next item fits here: big bonus
            // Harmonic alignment: post_residual exactly matches next size class
            if post_residual == next_item_size {
                score -= 4.0;
            }
        } else {
            // penalize creating a residue just below the next item's need
            let gap = ni - post_residual as f64;
            if gap < 10.0 {
                score += (10.0 - gap) * 0.8; // near-miss dead space
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only open a new bin when current fits are poor.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap; // average fullness of open bins
        // Opening a bin is cheap early / when bins are fragmented.
        score = 55.0 - pressure * 20.0 - (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && (next_item_size as f64) > cap * 0.5 {
            score += 5.0; // big item coming: a fresh bin is attractive
        }
    }

    // Slight progression term: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 1.5;

    // Prefer filling fuller bins (waste-avoidance coupling).
    score += (bin_residual as f64 / cap) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps that can't fit the next item
    // (or typical items) are heavily penalized.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Gap is dead for the lookahead item.
            score += (next_item_size - post_residual) as f64 * 2.0;
        } else if post_residual == next_item_size {
            // Perfect fit for next item: strong reward.
            score -= 30.0;
        } else {
            // Gap still usable for next item: mild reward proportional to tightness.
            score -= 8.0;
        }
    }

    // Penalize gaps too small to hold the minimum item size (dead space forever).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 4.0;
    }

    // Reward very tight fits (small post_residual overall).
    if post_residual <= 5 {
        score -= 25.0;
    }

    // Open-bins pressure: many open bins -> prefer filling existing ones,
    // and opening a new bin should be penalized.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 20.0 + pressure * 3.0;
        // Opening a new bin is acceptable early or when existing bins are too full.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // If mean residual across bins is small, existing bins are nearly full:
        // new bin less painful.
        if mean_residual < 15.0 {
            score -= 15.0;
        }
    } else {
        // Existing bin: reward when under open-bin pressure.
        score -= pressure * 0.5;
        // Last-chance bin: strongly favor using it to avoid waste.
        if fitting_bins_count == 1 {
            score -= 35.0;
        }
        // Favor bins tighter than the mean residual (well-packed bins).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Early stream: be more conservative, keep bins open for future items.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a convex penalty
    // so that large dead space is punished super-linearly.
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / bin_capacity as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches the
    // next item size (exact chain fit), penalize when it's slightly too
    // small or slightly too large (awkward leftover).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = pr - nxt;
        if diff.abs() < 1.0 {
            // Perfect chain: post_residual == next item size
            score -= 45.0 + 0.25 * nxt;
        } else if nxt <= pr {
            // Next item fits here afterwards: reward closeness of the match
            score -= 30.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item does not fit in the leftover: penalize near-misses
            // (wasted space just below next_item_size) more than big gaps.
            let miss = nxt - pr;
            if miss <= 20.0 {
                score += 18.0 * (1.0 - miss / 20.0);
            }
        }
    }

    // Relative-to-mean coupling: a bin with residual well below the mean
    // is already tight; placing here and leaving a small post_residual is
    // good. A bin far above the mean should absorb big items.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 6.0 * (mean_residual - res) / bin_capacity as f64;
    } else {
        score += 3.0 * (res - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless post_residual is tiny/wasteful).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // early in the stream or when the item is huge relative to the best
    // residual usage; otherwise keep bins tight.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Penalize new bins increasingly as the stream progresses,
        // unless the item is very large (would leave big dead space anyway).
        score += 20.0 + 55.0 * progress - 25.0 * item_frac;
        if next_item_size > 0 {
            // A fresh bin leaves room for the next item too; slight reward
            let nxt = next_item_size as f64;
            if item_size as f64 + nxt <= bin_capacity as f64 {
                score -= 10.0;
            }
        }
    }

    // Slight preference to fill bins when many are open (bin-count control).
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual already lowers score, amplify near-perfect fits.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 20.0;

    // Penalize bins that are much emptier than average (prefer filling fuller bins first).
    let residual_gap = bin_residual as f64 - mean_residual;
    score += residual_gap * 0.3;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item would be blocked by the leftover, mild penalty proportional to blocking.
    if next_item_size > post_residual && next_item_size > 0 {
        let waste = (next_item_size - post_residual) as f64;
        score += waste * 0.15;
    }

    // Time horizon: late in the stream, be more conservative (prefer tight packing, avoid new bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    // Many open bins: discourage opening new ones; new-bin candidate gets a penalty.
    if bin_residual == bin_capacity {
        score += 6.0 + open_bins_count as f64 * 1.5;
        // But late in the stream, a fresh bin may absorb odd leftovers well.
        if progress > 0.8 {
            score -= 4.0;
        }
    }

    // Penalize leaving dead space that is too small for the smallest plausible item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let norm_pr = pr / cap;

    // Base: post residual (waste), with smooth non-linear penalty growth
    let mut score = pr + 40.0 * norm_pr * norm_pr * (1.0 + progress);

    // Reward tight fits (small post_residual) with smooth coupling to progress
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + 0.5 * progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: reward bins whose residual after placement fits the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 12.0 * (1.0 - slack * slack);
        } else {
            score += 8.0 * (nx - pr) / cap;
        }
    }

    // Penalize bins far below mean residual (fragmentation) with smooth coupling
    score += 5.0 * ((mean_residual - pr) / cap).abs() * (1.0 - progress);

    // Mild penalty for many open bins to discourage spreading
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: prefer it only when no open bin fits well
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress) - (fitting_bins_count as f64).recip() * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins grouped by residue modulo 10.
    // Small residues are "dead space" classes -> penalize strongly.
    let r = post_residual;
    let class = if r == 0 { 0 } else if r <= 5 { 1 } else if r <= 10 { 2 } else if r <= 20 { 3 } else { 4 };
    score += match class {
        0 => -40.0,           // perfect fill, reward heavily
        1 => 25.0,            // tiny dead space, very bad
        2 => 10.0,            // small dead space
        3 => 2.0,             // medium
        _ => 0.0,
    };

    // Integer-division threshold: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 30.0; // perfect chained fit
        } else if next_item_size <= r {
            let slack = (r - next_item_size) as f64;
            score += slack * 0.4; // lookahead-aware penalty for slack after next item
        } else {
            // next item cannot use this residual: penalize proportionally to wasted capacity
            score += (r as f64 / bin_capacity as f64) * 12.0;
        }
    }

    // Last chance: this is the only bin that fits -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins are nearly full on average and item is small relative to capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight = mean_residual / bin_capacity as f64;
        // penalize new bin; relax penalty when existing bins are tight
        let mut nb = 15.0 + (1.0 - tight) * 25.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            nb -= 5.0; // fresh bin can chain with next item
        }
        if progress > 0.9 {
            nb -= 3.0; // end of stream, closing bins well is fine
        }
        score += nb;
    }

    // Mild preference for tighter bins overall (best-fit flavor)
    score += (bin_residual as f64 / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible
    // future item are pure waste. Penalize them super-linearly.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward tight fits: fraction of residual consumed by this item.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 25.0;

    // Penalize leaving a gap that is just barely too small for the lookahead
    // item (dead space with knowledge), reward gaps that fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (applied to the empty-bin candidate) and encourage consolidating.
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty that grows with open bins.
        score += 15.0 + 3.0 * open_bins_count as f64;
        // If some bin fits, opening a new bin should be rare.
        if fitting_bins_count >= 1 {
            score += 20.0;
        }
        // Early in the stream, opening bins is fine.
        let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0);
        score -= (1.0 - progress) * 10.0;
    } else {
        // Existing-bin consolidation bonus scaled by open-bin pressure.
        score -= (open_bins_count as f64).ln().max(0.0) * 4.0;
    }

    // Prefer bins whose residual is already below average (tighter bins first),
    // keeping large-residual bins flexible for larger future items.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // Mild penalty for leaving residual in the awkward 30..50 band where few
    // item sizes (1..100) pair well.
    if post_residual > 30 && post_residual < 50 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward when next item fits the post residual exactly or well
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // chain: post residual exactly matches next item
        } else if post_residual >= next_item_size {
            // next item fits; reward closeness of match
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit in post residual: penalize wasted space relative to next item
            let unusable = (next_item_size - post_residual) as f64;
            score += 0.5 * unusable;
        }
    }

    // Relative-to-mean residual shaping: prefer bins whose post residual deviates
    // favorably (smaller) from the mean residual
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize creating small dead space (< typical small item) that is hard to fill
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Early in the stream, be more willing to open new bins (keep residuals large)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, or when open bins are fragmented
        score = post_residual as f64;
        score -= 150.0 * (1.0 - progress);
        if mean_residual > 0.0 && mean_residual < item_size as f64 {
            score -= 100.0; // existing bins too fragmented, prefer fresh bin
        }
        if post_residual == next_item_size {
            score -= 400.0; // fresh bin perfectly chains with next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0; // residual remains usable by lookahead item
        } else {
            score += (post_residual as f64) * 1.5; // dead space penalty
        }
        // Bonus if post_residual exactly matches or near-matches next item
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        score -= 8.0 * (-gap as f64 / 20.0).exp();
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer bins with residual far below mean (consolidate fullness).
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // Slight penalty when many bins are open: encourage filling existing ones.
    score += open_bins_count as f64 * 0.05;

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late in the stream, pack tightly into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: cost grows with progress and with how well other bins fit.
        score += 30.0 * progress + 10.0 * (1.0 - fit_ratio);
        if fitting_bins_count == 1 {
            score += 60.0; // never open a new bin when this is the only fitting bin
        }
    } else {
        score -= 15.0 * progress;
    }

    // Mild preference for larger items going into larger-residual bins.
    score -= 0.05 * item_size as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;

    // Base: penalize post_residual, but the penalty softens with a smooth
    // non-linear (quadratic) coupling so large residuals matter more later.
    let mut score = pr + 0.02 * pr * pr / cap;

    // Stream-progress coupling: late in the stream, tight fills are rewarded.
    score -= progress * (cap - pr) * 0.3;

    // Smooth dead-space interaction: residual that cannot fit the next item
    // is dead space; penalize with a smooth saturating term.
    let dead = if nx > 0.0 { ((nx - pr).max(0.0)) / cap } else { 0.0 };
    score += dead * dead * cap * 0.5;

    // Reward near-perfect fits smoothly (small post_residual bonus).
    let tight = (1.0 - pr / cap).max(0.0);
    score -= tight * tight * it * 0.4;

    // Last-chance bonus: smooth exponential reward when this is the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 + progress);
    }

    // Mild preference to keep mean residual spread balanced (quadratic term).
    score += ((mean_residual - pr) / cap).abs() * 2.0;

    // Penalize opening a new bin when existing bins fit, smoothly with progress.
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress) - fitting_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "nice"
    // classes (multiples of common item sizes) are more reusable.
    let class = post_residual % 10;
    score += match class {
        0 => -6.0,                        // perfectly divisible leftover
        1 | 2 | 3 => 2.0,                 // awkward slivers
        4 | 5 => -1.0,                    // half-class usable
        _ => 1.5,
    };

    // Integer-division threshold: leftover that can host the lookahead item
    let can_host_next = next_item_size > 0 && post_residual >= next_item_size;
    if can_host_next {
        score -= 8.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 {
        // dead space relative to the lookahead item
        score += (next_item_size as f64 - post_residual as f64).max(0.0) * 0.5;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize new-bin candidate unless current bins are genuinely poor fits
    if bin_residual == bin_capacity {
        let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        let mut new_bin_score = 30.0 - 10.0 * tightness;
        if fitting_bins_count == 0 {
            new_bin_score -= 40.0; // nothing else fits: must open
        }
        if can_host_next {
            new_bin_score -= 5.0;
        }
        // later in the stream, prefer consolidating into open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score += 15.0 * progress;
        score = score.min(new_bin_score) * 0.0 + new_bin_score.max(score.min(new_bin_score));
        // final rule: new bin chosen only if it beats best open-bin score
        score = new_bin_score;
    } else {
        // favor bins whose residual is below the minimum item size (sealed bins)
        if post_residual < 10 {
            score -= 5.0;
        }
        // prefer bins tighter than the mean residual (best-fit flavor)
        score += (mean_residual - post_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    }

    // Reward tight fits (small post_residual relative to bin).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; prefer filling.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 8.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // dead space that next item cannot use
        score += 15.0;
    }

    // New-bin candidate handling: neutral-ish baseline so it's chosen only
    // when open bins create bad dead space.
    if bin_residual == bin_capacity {
        score += 35.0 + 3.0 * pressure;
        // But if no open bin fits well, allow new bin.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Late in stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight preference toward bins below mean residual (balance residuals).
    if (bin_residual as f64) > mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual)
    score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // 2-step lookahead: if next item fits exactly into post_residual, strongly favor this bin
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // next item fits, but penalize leftover slack after the hypothetical next placement
            let second_residual = post_residual - next_item_size;
            score -= 10.0 - 0.15 * second_residual as f64;
        } else {
            // next item won't fit here; penalize proportionally to the wasted gap
            score += 0.2 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins that keep residuals balanced/low
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize large dead space that nothing (>= min size 1) can use
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable sliver
    }

    // New-bin candidate: neutral-ish baseline, only attractive when open bins are all bad fits
    if bin_residual == bin_capacity {
        score += 20.0;
        // late in the stream, discourage opening new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // if many bins fit the item, opening new bins is wasteful
        score += 5.0 * (fitting_bins_count as f64).min(5.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 {
        let dead = (post_residual as f64 / bin_capacity as f64).sqrt();
        score += 12.0 * dead * (1.0 - fit_ratio);
    }
    if post_residual < 10 && post_residual > 0 {
        score -= 6.0; // tiny leftover is nearly perfect fill
    }

    // Lookahead: reward residual that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 4.0; // no chaining possible
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Time horizon: early in stream, be picky (penalize loose fits); late, accept more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 10.0 * (1.0 - fit_ratio);

    // Many open bins: prefer consolidating into existing bins rather than opening new ones.
    score += 0.4 * (open_bins_count as f64).ln().max(0.0) * (1.0 - fit_ratio);

    // Global mean residual coupling: if mean residual is high, prefer bins below mean (balance).
    if (bin_residual as f64) > mean_residual {
        score += 2.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
    } else {
        score -= 1.5 * ((mean_residual - bin_residual as f64) / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity && item_size < bin_capacity;
    if is_new_bin {
        let escape_bonus = if fitting_bins_count == 0 { 0.0 } else { 20.0 + 15.0 * (1.0 - progress) };
        score += escape_bonus + 10.0 * fit_ratio;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0; // new bin leaves good room for lookahead
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual (waste), with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth coupling: residual vs stream progress — later in stream, penalize large residuals more
    score += 30.0 * progress * norm_pr * (1.0 - norm_pr);

    // Reward tight fits: subtract when post_residual is small relative to item
    score -= 20.0 * (1.0 - norm_pr).powi(2) * norm_item;

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 25.0 * progress;
    }

    // Lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= pr {
            let fit_quality = 1.0 - ((pr - next) / cap).abs();
            score -= 10.0 * fit_quality * fit_quality;
        } else {
            score += 5.0 * (next - pr) / cap;
        }
    }

    // Discourage scattering across many bins when mean residual is high
    score += 2.0 * (open_bins_count as f64).ln() * (mean_residual / cap).max(0.0);

    // New-bin candidate: make it unattractive unless existing bins are hopeless
    if bin_residual == bin_capacity {
        score += 25.0 + 40.0 * progress - 10.0 * (1.0 - (mean_residual / cap).min(1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that form "nice" capacity fractions
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fit, excellent
    } else {
        // modulo classes: residuals divisible by 10 or 25 are more reusable
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 8.0; }
        if pr % 50 == 0 { score -= 10.0; }
        // dead-space penalty: small residuals are hard to fill
        if pr < 10 { score += 25.0; }
        else if pr < 20 { score += 10.0; }
    }

    // Lookahead coupling: does post_residual fit next item exactly / well?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0; // perfect chain
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            // integer-division thresholds on slack
            if slack % 10 == 0 { score -= 5.0; }
            score -= 8.0 * (1.0 - slack / cap).min(1.0);
        } else {
            score += 5.0; // next item can't use this bin's remainder
        }
    } else {
        // last item: prefer tightest fit strongly
        score += 0.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score = cap * 0.9;
        if next_item_size > 0 && (next_item_size as f64) > (post_residual as f64) {
            score -= 5.0;
        }
        if open_bins_count == 0 { score -= cap; } // must open a bin
        // late in stream, prefer packing into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    } else {
        // prefer bins whose residual is closest to item (tight fit) via fraction of capacity
        let fill = item_size as f64 / bin_residual.max(1) as f64;
        score -= 10.0 * fill;
        // reward bins tighter than mean residual (better consolidation)
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // mild scaling with many open bins to encourage consolidation
    score -= 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

