        score += 25.0;
        if open_bins_count == 0 {
            score -= 60.0;
        }
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            // (not applicable here, kept for symmetry)
        }
        // If the current item leaves a large gap in every existing bin, opening fresh is fine:
        // handled implicitly since existing-bin scores rise with dead-space penalties.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing large-then-large in fresh bins is reasonable
