            }
        }
    }

    // Relative-to-mean coupling: bins tighter than average are more valuable;
    // placing here preserves loose bins for awkward future items.
    let dev = mean_residual - bin_residual as f64;
    score += 0.5 * dev;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: discourage opening a new bin early on or when many
    // bins are open; encourage it late when residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 80.0 - 120.0 * fragmentation - 40.0 * progress;
    }

    // Waste fraction penalty: quadratic in wasted capacity.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste * waste;

    // Item size coupling: large items should prefer tightest fits (scale score
    // so residual differences matter more for big items).
    if item_size > bin_capacity / 2 {
        score *= 1.0 + (item_size as f64 / bin_capacity as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

