    // late in the stream, just fill bins to reduce total count.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * tightness;

    // Global state coupling: if mean residual across open bins is high,
    // encourage consolidating into existing bins rather than opening new ones.
    score -= 0.05 * mean_residual;

