    score -= 40.0 * (1.0 - norm_pr).powf(3.0) * (progress * 0.7 + 0.3);

    // Penalize dead space that nothing can use (post_residual too small for typical items).
    let dead = (norm_pr * (1.0 - norm_pr)).powf(2.0); // peaks at mid residuals (usable), small at extremes
    score -= 25.0 * dead;

    // Lookahead: if next item fits exactly in post residual, strongly reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = 1.0 - ((pr - nxt) / cap).powf(2.0);
            score -= 35.0 * fit_quality;
        } else {
            // Next item won't fit here: mild penalty scaled by overflow amount.
            score += 8.0 * ((nxt - pr) / cap).powf(1.5);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize bins deviating from mean residual (keep residuals homogeneous).
    score += 0.5 * (pr - mean_residual).abs();

    // Slight preference for using existing bins over opening new ones,
    // stronger early when many bins are open relative to progress.
    let open_pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += open_pressure * (2.0 - progress) * (norm_pr.powf(2.0));

    // New-bin candidate: make it costly unless residuals everywhere are tiny.
    if bin_residual == bin_capacity {
        score += 60.0 * (1.0 - (mean_residual / cap).powf(2.0));
        score -= 10.0 * progress; // late in stream, new bins slightly cheaper
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes of post_residual via modulo arithmetic (capacity 100 -> mod 10, mod 25)
    let mod10 = post_residual % 10;
    let mod25 = post_residual % 25;

    // Penalize residuals that are awkward classes: small nonzero remainders are dead space
    if post_residual > 0 {
        if mod10 > 0 && mod10 <= 4 {
            score += 8.0; // small awkward remainder (11-14, 21-24, ... small band)
        } else if mod10 == 0 {
            score -= 6.0; // perfectly aligned residual (multiple of 10)
        }
        if mod25 == 0 {
            score -= 4.0; // quarter-capacity aligned
        }
    } else {
        score -= 12.0; // perfect fit
    }

    // Integer-division thresholds: classify residual into harmonic bands
    let band = post_residual / 25; // 0..4
    score += band as f64 * 3.0;    // prefer tighter bins (smaller residual band)

    // Fraction of capacity left
    let frac = post_residual as f64 / cap;
    score += frac * 10.0;

    // Lookahead coupling: does next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic match: next item leaves another aligned residual?
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 10.0;
            } else {
                score -= 3.0;
            }
        } else {
            // next item won't fit: this residual becomes dead space unless small
            let waste = next_item_size - post_residual;
            score += (waste as f64) * 0.5;
            if post_residual > 0 && post_residual < 10 {
                score += 15.0; // tiny unusable sliver with no future use
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bin is a bad host
    if bin_residual == bin_capacity {
        // fresh bin: neutral base, slightly penalized so real fits win, but
        // relieved if all open bins are badly fragmented
        score = cap * 0.35 + (mean_residual - frac * cap) * 0.2;
        if fitting_bins_count == 0 {
            score -= 30.0; // no open bin fits: must open new bin
        }
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Late-stream consolidation: as stream progresses, tighten bin usage
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += frac * progress * 8.0;

    // Fragmentation pressure: if mean residual is high, prefer consuming large residuals
    if mean_residual > 40.0 && post_residual >= mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest plausible item are pure waste -> heavy penalty.
    let dead_threshold = 10u32.min(item_size);
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 + (dead_threshold - post_residual) as f64 * 5.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward fits that leave room for the lookahead item (good pairing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + next_item_size as f64 * 0.15;
    }
    // Penalize leaving a gap that blocks the next item but is still sizeable.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Pressure from number of open bins: discourage new bins when many open.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 5.0;
        // But if all existing bins fit poorly, new bin may win.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Mild penalty for wasting large residuals on small items.
    score += (post_residual as f64 / bin_capacity as f64) * (item_size as f64).recip() * 30.0;

    // Slight preference to keep mean residual balanced.
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Partial lookahead credit: post_residual can still hold the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        // Bonus proportional to how "tight" the fit for the next item is.
        let tightness = next_item_size as f64 / post_residual as f64;
        score -= 10.0 * tightness;
    } else {
        // Penalize creating dead space below the smallest item that could use it.
        score += 8.0;
    }

    // Penalize residual far below mean residual (wasting a big bin on a small gap).
    score += 0.5 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bins give poor fits.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
        score += 10.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild preference for tighter overall fits relative to capacity.
    score += 0.05 * (item_size as f64 / bin_capacity as f64) * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 60.0 * fill;

    // Penalize leaving large dead space relative to the smallest future item (10).
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score -= 40.0; // perfect seal, nearly zero waste
    } else if dead >= 10.0 && dead < 30.0 {
        score -= 10.0; // still usable by typical items
    } else if dead >= 60.0 {
        score += 15.0; // wasteful large gap when a smaller bin could do
    }

    // Lookahead: if the next item fits exactly or well into the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 35.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's remainder; penalize proportionally to how close it was.
            let miss = (next_item_size - post_residual) as f64;
            score += 8.0 * (1.0 - miss / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    if open_bins_count > 4 {
        score -= 5.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    // Compare against mean residual: placing into a bin whose residual is near/below mean
    // keeps the pool of large residuals for future big items.
    score += 0.25 * (mean_residual - bin_residual as f64).abs().min(50.0);
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    }

    // Time horizon: early in the stream, be conservative (favor tight fits only);
    // late in the stream, allow slight preference for closing bins out.
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * t * fill;

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    // Its post_residual is large, so baseline already deprioritizes it; add extra
    // penalty unless nothing else fits (fitting_bins_count == 0 among open bins).
    if bin_residual == bin_capacity {
        score += 25.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: open a new one
        }
        // If item is huge, a fresh bin is often the right home.
        if item_size >= 70 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic in post residual (waste grows super-linearly)
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth coupling with stream progress: later in stream, penalize residual more
    let prog_coupling = progress * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 60.0 * prog_coupling * cap;

    // Cubic interaction term: dead space near mid-residual is worst
    score += 25.0 * (norm_pr - 0.5) * (norm_pr - 0.5) * (norm_pr - 0.5) * cap;

    // Last chance bin: reward strongly if this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 35.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 18.0;
    } else if next_item_size > 0 {
        // smooth penalty if next item barely misses fitting
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 0.15 * gap;
    }

    // Mean residual comparison: bins with residual near mean are neutral,
    // far-from-mean residual penalized (keeps bin diversity)
    score += 0.5 * (pr - mean_residual).abs();

    // Many open bins: slightly discourage filling a fresh-ish bin poorly
    let open_norm = open_bins_count as f64;
    score += 0.05 * open_norm * norm_pr;

    // New-bin candidate handling: prefer opening a new bin only when it's early
    // in the stream or residual would be tiny dead space otherwise
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: capacity / 12 classes.
    let class = (post_residual * 12 / bin_capacity.max(1)) as f64;
    score += class * 1.3;

    // Perfect closure reward: residual near zero is excellent.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Penalize dead space in awkward modulo classes (hard-to-fill slivers).
    let awkward = post_residual % 10;
    if awkward > 0 && awkward < 5 {
        score += awkward as f64 * 2.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let next_fit_class = ((post_residual - next_item_size) * 12 / bin_capacity.max(1)) as f64;
            score -= 18.0 - next_fit_class * 1.5;
        } else {
            // Next item cannot fit here; slight penalty scaled by gap.
            score += ((next_item_size - post_residual) as f64).min(30.0) * 0.4;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Prefer filling bins when many are open (reduce bin count).
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Favor bins tighter than the mean residual.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= diff * 0.8;
    } else {
        score += (-diff) * 0.3;
    }

    // New-bin candidate: keep it slightly unattractive unless everything else is bad.
    if bin_residual == bin_capacity {
        score += 8.0;
        // But late in the stream with many open bins, opening fresh can be fine.
        if step_index as f64 / total_items.max(1) as f64 > 0.7 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< min item 10) are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0 * (10 - post_residual) as f64;
    }

    // Reward tight fits: fill rate of the residual consumed.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Perfect closure bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize leaving a small-but-usable gap that no known item can exploit:
    // if next item cannot fit into post_residual, that gap is likely dead.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 12.0;
    }
    // Reward bins that keep room for the lookahead item.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor consolidation
    // unless it's the new-bin candidate.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus penalty that grows with open bins
        // (opening bins is expensive when many are already open).
        score = bin_capacity as f64 + 40.0 * open_bins_count as f64;
        // Allow new bin only when open bins are very full on average and item is large.
        if mean_residual < 20.0 && item_size > 60 {
            score -= 45.0;
        }
    } else {
        score += 3.0 * open_bins_count as f64;
    }

    // Stream progression: late in the stream, waste matters more (fewer chances to recover).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small post_residual is already low).
    if post_residual == 0 {
        score -= 50.0; // perfect fit is ideal
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // 2-step lookahead: reward if next item fits the post_residual exactly.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (post_residual as f64) >= ni {
            let slack = post_residual as f64 - ni;
            if slack == 0.0 {
                score -= 40.0; // next item fills this bin perfectly
            } else if slack <= 10.0 {
                score -= 20.0;
            } else {
                score -= 10.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            // next item cannot fit here: penalize proportionally to waste
            score += 5.0 + 0.3 * (ni - post_residual as f64);
        }
    }

    // Penalize large dead space relative to mean residual across open bins.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        if pr > mean_residual {
            score += 0.5 * (pr - mean_residual);
        } else {
            score -= 0.3 * (mean_residual - pr);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when this bin's fit is bad
    // (large post_residual) or nothing meaningful fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 60.0;
        // Make new bin more attractive if current fit leaves big unusable gap
        // and the next item is large.
        if next_item_size > 0 {
            let ni = next_item_size as f64;
            if pr < ni && pr > 0.0 {
                score -= 10.0; // current bin would strand next item
            }
        }
        if fitting_bins_count <= 1 {
            score -= 45.0; // few alternatives -> new bin fine
        }
        if pr >= 40.0 {
            score += 20.0; // current fit is decent, keep using it
        }
    }

    // Late in the stream, consolidate more aggressively.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 5.0 * progress * (1.0 - pr / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it, else item forces a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent existing options exist,
    // but allow it early or when residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs() / bin_capacity as f64;
        score += 18.0 + 20.0 * (1.0 - progress) * fragmentation - 10.0 * fragmentation;
        // If next item fits nicely in the fresh bin alongside this one, soften penalty.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0;
        }
        // Many open bins with small mean residual: prefer consolidation into existing bins.
        score += 3.0 * open_bins_count as f64;
    }

    // Lookahead: penalize leaving a residual that fits neither current-followup well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space for the known next item.
            score += 5.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64 * 10.0;
        }
    }

    // Penalize large unusable leftovers (below typical minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Mild preference for bins already below mean residual (balance residuals).
    score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    // Time-decay exploration bonus: early on, be slightly adventurous with big bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;

    // Non-linear waste penalty: quadratic in post residual, slightly softened at high progress
    let mut score = pr * (1.0 + 0.9 * base * base);

    // Reward tight fits (small post_residual) with a smooth saturation term
    score -= 30.0 * (-pr / 25.0).exp();

    // Coupling: prefer leaving room for the next item; smooth interaction
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap >= 0.0 {
            score -= 12.0 * (1.0 - (gap / cap).min(1.0)) * (1.0 - progress);
        } else {
            score += 0.15 * (-gap);
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize smoothly, less so early in the stream
    if bin_residual == bin_capacity {
        score += 45.0 + 25.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
    } else {
        // Favor fuller bins relative to mean residual of open bins
        score += 0.1 * (mean_residual - pr).max(0.0);
    }

    // Mild progress-driven greed: later in the stream, pack tighter
    score *= 1.0 + 0.2 * progress * base;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into
    // "usable" classes (multiples of common item sizes), penalize dead space.
    let cap = bin_capacity as f64;

    // Class 1: exact fill is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic penalty: residual not expressible as a plausible future item
        // (items are 1..=100, but small residuals < 10 are near-dead).
        if post_residual < 10 {
            score += 60.0 * (10 - post_residual) as f64;
        }
        // Modulo-10 harmony: residuals divisible by 10 pair well with the
        // typical decile item grid.
        if post_residual % 10 == 0 {
            score -= 8.0;
        }
        // Integer-division thresholds: quarter classes of capacity.
        let quarter = (post_residual * 4) / bin_capacity;
        match quarter {
            0 => score += 25.0,               // <25% left: mostly dead
            1 => score -= 3.0,                // 25-50%: decent
            2 => score -= 10.0,               // 50-75%: good
            _ => score -= 6.0,                // 75-100%: fine (new bin)
        }
        // Harmony with lookahead: bonus if next item fits the post residual exactly
        // or leaves a harmonic remainder.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 120.0;
            } else if next_item_size < post_residual {
                let nxt_post = post_residual - next_item_size;
                if nxt_post % 10 == 0 {
                    score -= 15.0;
                }
                if nxt_post < 10 {
                    score -= 20.0; // chain that kills the bin cleanly
                }
            } else {
                // next item cannot fit here; slight penalty for wasting harmony
                score += 5.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin gets a baseline that keeps it
    // competitive only when existing bins would waste space.
    if bin_residual == bin_capacity {
        // Score of a fresh bin ~ its full residual, mildly discounted by
        // stream progress (late in stream, prefer closing bins).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = cap - 10.0 + 30.0 * progress;
        if fitting_bins_count == 0 {
            score -= 200.0; // forced new bin
        }
    }

    // Prefer denser packing when many bins are open: tie-break toward bins
    // below mean residual (filling the emptier ones first balances classes).
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward small post_residual relative to item size.
    let fit_ratio = post_residual as f64 / bin_residual.max(1) as f64;
    score += fit_ratio * 20.0;

    // Aggressive 2-step lookahead: if next item exactly fills post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect two-item closure
        } else if next_item_size <= post_residual {
            score -= 25.0; // next item can still fit here
            let leftover = post_residual - next_item_size;
            score += leftover as f64 * 0.5;
        } else {
            // next item cannot use the residual; penalize dead space more
            score += (post_residual as f64 - mean_residual).abs() * 0.8;
            score += 10.0;
        }
    }

    // Prefer bins whose residual is below mean residual (dense bins).
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize unless residual would be badly fragmented.
    if bin_residual == bin_capacity {
        score = 100.0 - (item_size as f64); // mild baseline; open new bin only if no good fit
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0; // fresh bin can host a clean pair
        }
        if fitting_bins_count <= 1 {
            score -= 45.0; // nothing fits well elsewhere -> open new bin
        }
    }

    // Late in stream: avoid opening new bins, squeeze existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 8.0;
    } else {
        score += progress * 15.0;
    }

    // Many open bins: prefer consolidation into existing bins.
    score += open_bins_count as f64 * 0.05 * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: squared penalty on wasted space, scaled by fill fraction.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score += (post_residual as f64).powi(2) / bin_capacity as f64;
    score -= fill * 20.0;

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: penalize leaving a residual that cannot fit the next item
    // (dead space), reward residuals that can still host it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
        // Reward exact pairing: residual left equals next item size.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // New-bin candidate handling: opening a fresh bin is attractive early in
    // the stream or when many bins are open, but wasteful if a good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (bin_capacity - item_size) as f64;
        score = waste * (1.0 - 0.4 * progress);
        if fitting_bins_count > 0 {
            // Disfavor opening a new bin when an existing bin can fit,
            // unless all existing fits would leave tiny dead space.
            score += 25.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Global state coupling: prefer filling bins below the mean residual
    // (consolidating sparse bins), penalize draining already-tight bins.
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Late-stream pressure: as the stream nears its end, close out bins
    // aggressively by rewarding high fill ratios.
    let urgency = step_index as f64 / total_items.max(1) as f64;
    score -= urgency * fill * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let ir = item_size as f64;

    // Base: quadratic coupling of post_residual with stream progress.
    // Early on, large residuals are acceptable (bins can absorb future items);
    // late in the stream, leftover space is increasingly wasted, so the
    // quadratic penalty coefficient grows smoothly with progress.
    let progress_curve = 0.5 + 1.5 * progress * progress;
    let mut score = pr * pr * progress_curve / cap;

    // Smooth dead-space term: residuals that no plausible item (>=10) can
    // use are penalized super-linearly.
    let dead = ((10.0f64).max(pr + 1.0) - 10.0).max(0.0);
    score += 2.0 * dead * dead / cap;

    // Reward tight fits: coupling between item size and residual fill ratio.
    let fill = 1.0 - pr / cap;
    score -= 3.0 * fill * fill * (ir / cap);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (smooth sigmoid-like weight).
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (pr >= nxt) as i32 as f64;
        let snug = 1.0 - ((pr - nxt).abs() / cap).min(1.0);
        score -= 4.0 * fits_next * snug * snug;
        // If next item would leave this bin nearly empty anyway, mild penalty
        // for wasting a big residual on a small item now.
        score += 1.5 * (1.0 - fits_next) * (nxt / cap) * fill;
    }

    // Mean-residual coupling: placing into a bin far below the mean residual
    // (i.e. leaving it much emptier than average) is slightly penalized,
    // encouraging balanced residual distribution across open bins.
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev;

    // New-bin candidate (residual == capacity): make it a smooth function of
    // item size and progress so it wins only when no open bin offers a
    // reasonable fit. Its raw quadratic score is already large; add a mild
    // progress-dependent surcharge so late in the stream we prefer filling
    // existing bins.
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
    } else {
        // Slight preference for bins with fewer siblings fitting the item
        // (consolidation pressure), smoothly scaled.
        score += 0.3 * (fitting_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post-residual, but avoid perfect-fit obsession creating fragmentation.
    // Harmonic class of post_residual: residual modulo 10 classes
    let r = post_residual;
    let class = r % 10;
    // Harmonic bonus: residuals that are multiples of 10 (or 5) are more reusable
    if class == 0 {
        score -= 6.0;
    } else if class == 5 {
        score -= 3.0;
    } else {
        score += class as f64 * 0.3; // penalize awkward residues
    }

    // Integer division thresholds on post_residual: dead-space zones
    if r > 0 && r < 10 {
        score += 12.0; // unusable sliver (min item is 10 per original spec; small items 1..10 possible)
    } else if r >= 10 && r < 20 {
        score += 2.0; // only tiny items fit
    }

    // Lookahead coupling: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= r {
            score -= 5.0 + (next_item_size as f64) * 0.05;
            // harmonic match: next item exactly fills remainder class
            if r % next_item_size.max(1) == 0 {
                score -= 4.0;
            }
        } else {
            score += 3.0; // next item won't fit here; keep residual large-ish elsewhere
            if r < next_item_size {
                score += (next_item_size - r) as f64 * 0.05;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when current bins fit poorly
    if bin_residual == bin_capacity {
        // opening a new bin wastes capacity if open bins could take it
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score = 100.0 - 8.0 * pressure - 5.0 * progress;
        // if item is large relative to capacity, new bin is natural
        if item_size >= bin_capacity / 2 {
            score -= 6.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 4.0; // companion packing potential
        }
    }

    // Mean residual alignment: prefer bins whose residual is close to mean (balance)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Late-stream tightening: be greedier about tight fits as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 0.0 + progress * (bin_capacity - bin_residual) as f64 * 0.02;

    // Modulo threshold on item_size vs residual: perfect division reward
    if item_size > 0 && bin_residual % item_size == 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (unusable by typical items) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else {
        // Usable leftover: mild reward scaled by how much room remains.
        score -= 2.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: penalize adding load to a new bin when many bins are already open;
    // encourage consolidating when open_bins_count is large.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to current open bins.
        score += open_bins_count as f64 * 4.0 + 10.0;
    } else {
        // Reward filling existing bins more when many are open.
        score -= open_bins_count as f64 * 0.5;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Leftover too small for the next item: mild penalty proportional to gap.
            let gap = next_item_size - post_residual;
            score += gap as f64 * 0.3;
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter packing).
    score += (mean_residual - post_residual as f64) * 0.2;

    // Progress: slightly more greedy (favor zero residual) later in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 0.0 + progress * (100.0 - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits the post_residual exactly or well
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 1.0 {
            score -= 500.0; // perfect chain match
        } else if next_item_size <= post_residual {
            // next fits: reward proportional to how snugly
            score -= 200.0 * (1.0 - (post_residual as f64 - nxt) / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize wasted post_residual relative to next item
            score += 0.5 * (post_residual as f64 - nxt).min(post_residual as f64);
        }
    }

    // Compare post_residual against mean residual: prefer bins that become tighter than average
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // Penalize new-bin opening unless current open bins would leave large dead space
    if bin_residual == bin_capacity {
        let waste_if_open = post_residual as f64;
        score += 50.0; // base reluctance
        // open a new bin only if best alternative would create big dead space
        if waste_if_open < 20.0 {
            score -= 200.0;
        }
    }

    // Dead-space penalty: small post_residual that cannot hold typical items
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Progression: later in stream, prefer tighter packing (favor filling existing bins)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Lookahead: reward leaving space exactly usable by the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize large dead space
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * (open_bins_count as f64).ln().max(0.0);
        // new bin is acceptable if item is large relative to capacity
        score -= 0.35 * item_size as f64;
    }

    // Global state coupling: prefer filling bins with above-average residual
    score -= 0.15 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in stream, be conservative about fragmenting space
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = pr_norm * pr_norm * (0.5 + 3.0 * p2 + 2.0 * p3);
    score += coupling * cap * 0.6;

    // Penalize post-residuals that waste space relative to mean residual
    let mean_norm = mean_residual / cap;
    score += 0.4 * (pr_norm - mean_norm).abs() * cap;

    // Reward tight fits (small post residual) more strongly later in the stream
    score -= (1.0 - pr_norm) * (1.0 + 2.0 * p2) * 5.0;

    // Lookahead: prefer leaving post_residual that fits next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (1.0 - (nx / cap - pr_norm).abs());
        } else {
            score += 3.0 + (nx - pr) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Mild penalty for spreading across too many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 0.3 * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post-residual (modulo arithmetic) ----
    // Residuals divisible by common item classes (10/20/25/50) are "usable"
    // dead space; odd residuals are penalized.
    let pr = post_residual;
    if pr > 0 {
        if pr % 50 == 0 {
            score -= 18.0;
        } else if pr % 25 == 0 {
            score -= 12.0;
        } else if pr % 20 == 0 {
            score -= 10.0;
        } else if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 2.0;
        } else {
            // irregular remainder -> dead space risk
            score += 4.0 + ((pr % 5) as f64) * 1.5;
        }
    }

    // Perfect fit is ideal
    if pr == 0 {
        score -= 60.0;
    }

    // ---- Coupling with next item (lookahead) ----
    if next_item_size > 0 {
        if next_item_size == pr {
            // next item exactly fills the leftover: superb
            score -= 45.0;
        } else if next_item_size < pr {
            let nxt_res = pr - next_item_size;
            // harmonic class of the double residual
            if nxt_res % 10 == 0 {
                score -= 15.0;
            } else {
                score += (nxt_res % 10) as f64 * 0.8;
            }
        } else {
            // next item cannot use this bin's leftover
            score += 8.0;
        }
    }

    // ---- Last-chance bin before opening a new one ----
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive early in the stream or when few
        // bins are open; it must otherwise be penalized so we prefer fills.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 30.0 + (1.0 - progress) * 25.0 - (open_bins_count as f64).min(10.0) * 0.5;
        // If the current item is large relative to capacity, a fresh bin wastes less
        if item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
        // If existing bins are already crowded on average, a new bin is fine
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
        return score;
    }

    // ---- Fill ratio reward: tighter packing preferred ----
    let fill = item_size as f64 / bin_residual as f64;
    score -= fill * 10.0;

    // Slight preference for bins with residuals near the item (integer division threshold)
    let quanta = bin_residual / item_size.max(1);
    score -= (quanta.min(4)) as f64 * 2.0;

    // Mild penalty for spreading across too many bins late in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (min item size 1..30) are heavily penalized.
    if post_residual > 0 {
        let dead = if post_residual < 10 {
            60.0 // unusable tiny gap
        } else if post_residual < 30 {
            25.0 // only very small items can use it
        } else if post_residual < 50 {
            8.0
        } else {
            0.0
        };
        score += dead * (post_residual as f64 / 100.0);
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Lookahead: if the next item can exactly fill the resulting residual,
    // this is a great pairing; if next item cannot fit at all, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise a new bin must be opened.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer
    // filling existing bins rather than opening new ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score -= pressure * (bin_residual - post_residual) as f64 * 0.3;

    // New-bin candidate handling: only attractive early in the stream or
    // when the current bin would leave a badly fragmented residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = score - 5.0 + progress * 20.0 + fragmentation * 0.2;
        if post_residual < 30 && next_item_size > post_residual && next_item_size > 0 {
            score -= 25.0; // open fresh bin rather than create dead space
        }
    }

    // Mild normalization against mean residual state.
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fits post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            // next item fits: mild reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit: penalize large post_residual (dead space)
            score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);
        }
    }

    // Reward tight fits relative to residual
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 120.0 * fit_ratio * fit_ratio;

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Prefer bins with residuals below mean (fill fuller bins first)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when existing bins fit poorly
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) as f64;
        // penalize new bin unless it would otherwise waste much space
        score += 150.0 + 0.5 * mean_residual - 0.3 * poor_fit;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 50.0; // pairing large items together in a fresh bin
        }
    }

    // Slight preference to consolidate early in stream
    score -= 10.0 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: bins that end up nearly full are strongly favored.
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 6.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if next item fits exactly into the post-residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly reward using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer bins whose residual is close to the mean residual (harmonic packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.5 * dev;

    // Late in the stream: consolidate more aggressively into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Mild penalty for opening new bins when many are already open.
    if bin_residual == bin_capacity {
        score += 3.0 + 0.5 * open_bins_count as f64;
    }

    // Prefer filling the emptiest bins first when several could fit.
    score += 0.3 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with smooth non-linear shaping.
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Coupling: post_residual vs stream progress — late in stream, tighten packing harder.
    score += 20.0 * norm_pr * progress * (1.0 - progress) * 2.0;

    // Lookahead: reward leaving space for the next item (smooth gaussian-like affinity).
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        let affinity = (-diff * diff / 400.0).exp();
        score -= 12.0 * affinity;
        // Penalize if post residual is just barely below next item (dead space).
        if pr < next_item_size as f64 {
            score += 6.0 * (1.0 - pr / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize bins with residuals far from the mean residual (fragmentation avoidance).
    score += 0.5 * (pr - mean_residual).abs();

    // Slight penalty when many bins are open: prefer consolidation.
    score += 0.02 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: mild penalty so it's chosen only when clearly better.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction does leftover fall into?
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class boundaries: 0, cap/4, cap/2, 3cap/4
    let q = post_residual / (bin_capacity / 4).max(1); // 0..4 harmonic class
    match q {
        0 => { score -= 6.0; }             // perfect fit
        1 => { score += 4.0; }             // tiny dead space, penalize
        2 => { score += 0.0; }             // half class, neutral
        _ => { score -= 2.0; }             // large residual, reusable
    }

    // Can next item fit into post_residual? (harmonic pairing)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward exact/loose pairing
            let slack = (post_residual - next_item_size) as f64;
            score -= 3.0 + 2.0 * (1.0 - slack / cap);
        } else {
            // next item can't use this residual; penalize proportionally
            score += (next_item_size as f64 - pr) * 0.05;
        }
    }

    // Integer-division threshold: residual divisible into common item sizes
    let common: [u32; 8] = [10, 20, 25, 30, 40, 50, 60, 80];
    let mut div_bonus = 0.0;
    for &c in &common {
        if post_residual >= c && post_residual % c == 0 {
            div_bonus += 1.5;
        }
    }
    score -= div_bonus;

    // Last-chance bin: strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize unless residuals are all tight
    if bin_residual == bin_capacity {
        let tight = mean_residual < 15.0 && open_bins_count > 0;
        score += if tight { 25.0 } else { 12.0 + pr * 0.1 };
    }

    // Prefer bins below mean residual (fill emptier-but-usable bins first)
    score += (pr - mean_residual).max(-50.0).min(50.0) * 0.03;

    // Late-stream tightening: waste matters more near the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * 0.02 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=10) are unusable for
    // typical items (min size 1..100 stream, but tiny gaps rarely help).
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 + (11 - post_residual as i32) as f64 * 4.0;
    }
    // Medium gaps 11..=25 are semi-dead: moderate penalty scaled by gap.
    else if post_residual > 10 && post_residual <= 25 {
        score += (26 - post_residual as i32) as f64 * 2.0;
    }
    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits relative to residual (fill fraction).
    if bin_residual > 0 {
        let fill = item_size as f64 / bin_residual as f64;
        score -= fill * 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer
    // filling existing bins; few open bins -> allow opening new ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 3.0;

    // New-bin candidate handling: only attractive when existing fit is bad
    // or this bin is the last chance with a poor fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; offset by potential for future items.
        score += 25.0;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Early in stream, new bins are cheap; later, expensive.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > post_residual {
        // Next item cannot use the gap: gap is dead for lookahead.
        score += 12.0;
    }

    // Mean-residual coupling: penalize bins whose residual is far below mean
    // (they are nearly full anyway; prefer them only if very tight fit).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score += dev * 0.2;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size exactly.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if post_residual as u32 == next_item_size {
            score -= 45.0; // perfect 2-step chain
        } else if post_residual >= next_item_size {
            // leftover after hypothetically placing the next item: tighter chain = better
            score -= (post_residual - next_item_size) as f64 / (1.0 + 0.03 * post_residual as f64);
        } else {
            // next item cannot follow: post_residual becomes dead space
            score += 12.0 + diff * 0.5;
        }
    } else {
        // last item: prefer minimal leftover
        score += 2.0;
    }

    // Reward closeness to mean residual (harmonized bins), penalize outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.08;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when item is huge relative to capacity
    // or no good chain exists; otherwise penalize spreading.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.6 {
            score -= 8.0 * fill_ratio;
        } else {
            score += 15.0;
        }
    }

    // Late in the stream: consolidate, prefer tight fits even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - bin_residual) as f64 * (0.1 + 0.15 * progress);

    // Small bonus when many open bins: encourage closing them out.
    score -= open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit bias: reward tight fits.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 60.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Small dead-space penalty (nonlinear): residuals that can't fit typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // If next item would exactly fill the post residual, extra reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Penalize if next item is larger than post_residual but this bin could have held it too
    // (i.e., we consumed space the future needs elsewhere) — mild.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Many open bins: prefer consolidation (favor bins with small residual already).
    if open_bins_count > 4 {
        score -= (bin_capacity - bin_residual) as f64 * 0.3;
    }

    // Global state: if mean residual is large, encourage filling bins aggressively.
    score += (mean_residual - post_residual as f64) * 0.2;

    // Time horizon: early in stream, be more exploratory (favor new bins slightly less);
    // late in stream, consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.7 {
        score += tightness * 30.0; // extra tightness pressure late
    } else if progress < 0.2 {
        score -= 5.0; // slight exploration bonus early
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity && item_size > 0 {
        // Opening a new bin is penalized unless it's early or open bins are crowded.
        let mut new_bin_penalty = 70.0 + post_residual as f64;
        if fitting_bins_count == 0 {
            new_bin_penalty -= 200.0; // no alternative
        }
        if progress < 0.15 {
            new_bin_penalty -= 20.0;
        }
        if open_bins_count > 0 && mean_residual > 60.0 {
            new_bin_penalty -= 15.0; // open bins are full-ish anyway
        }
        score = score.min(new_bin_penalty) + 0.0;
        score = new_bin_penalty.max(score * 0.0 + new_bin_penalty); // ensure new-bin uses penalty scale
        score = new_bin_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Core: prefer tight fits, with non-linear (quadratic) emphasis on small residuals.
    let mut score = post + 0.35 * post * post / cap;

    // Stream-progress coupling: as the stream progresses, dead space becomes
    // increasingly costly (quadratic ramp), pushing toward tighter packing.
    let urgency = progress * progress;
    score *= 1.0 + 0.8 * urgency;

    // Coupling with mean residual: if this bin is much emptier than average,
    // mildly penalize leaving it as a candidate for larger future items.
    let rel_post = post / cap;
    let rel_mean = mean_residual / cap;
    score += 4.0 * (rel_post - rel_mean) * (rel_post - rel_mean) * cap * 0.05;

    // Last-chance bonus: if this is the only bin that fits, strongly reward using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * urgency;
    }

    // Lookahead: if the next item would fit exactly in the post-residual,
    // reward this placement; if the next item would not fit, add a small penalty.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = post - nxt;
            score -= 6.0 * (1.0 - slack / cap);
        } else {
            score += 3.0 * urgency * (nxt - post) / cap;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive early in
    // the stream or when no open bin fits well. Penalize new bins when existing
    // bins offer a decent fit; reward slightly when open bins are crowded.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score = post - 50.0; // nothing fits anywhere: must open
        } else {
            let crowd = open_bins_count as f64;
            score = post + 25.0 + 10.0 * urgency - 2.0 * (fitting_bins_count as f64).ln() * 5.0;
            // late in the stream, avoid scattering items across many bins
            score += 0.5 * crowd * urgency;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any plausible
    // future item (below the minimum item size) are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 1000.0; // unusable sliver -> heavy penalty
    }

    // Dead space that cannot fit the lookahead item is less valuable.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 30.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few are open, opening a new bin is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure, but attractive if
        // the item fits poorly everywhere else (large post_residual elsewhere).
        score += 40.0 + pressure;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0; // fresh bin guarantees room for lookahead
        }
    } else {
        // Using an existing bin slightly relieves pressure.
        score -= pressure * 0.3;
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // unless it is a fresh bin.
    if bin_residual != bin_capacity {
        score += (bin_residual as f64 - mean_residual).abs() * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills
    // the post-residual of this bin (perfect chaining).
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain: next item seals this bin
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // penalize leftover after hypothetical next placement,
            // scaled harder for small dead space
            score += slack * (1.0 + 30.0 / slack.max(1.0));
        } else {
            // next item cannot use residual: dead space likely
            score += post_residual as f64 * 0.6;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // keep bins with low residual (tight fits) preferred.
    score -= (mean_residual - post_residual as f64) * 0.35;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when other
    // bins exist and the item fits reasonably elsewhere.
    if bin_residual == bin_capacity {
        let base = 20.0 + (open_bins_count as f64) * 2.0;
        let waste = (bin_capacity - item_size) as f64;
        score += base + waste * 0.5;
        // if next item is small, a fresh bin is less wasteful
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
    }

    // Slight preference to fill older bins early in the stream.
    score += (step_index as f64 / (total_items as f64).max(1.0)) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Penalize leaving dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny sliver = wasted capacity
    } else if post_residual >= 10 && post_residual < 25 {
        score += 6.0;  // moderate dead space penalty
    }

    // Lookahead: reward if the next item fits into the post-residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let chain_tightness = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 12.0 * chain_tightness;
        } else {
            // Next item won't fit here: slight penalty for large leftover if it's stranded.
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only when
    // no good fit exists among open bins, or the stream is early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Opening a new bin costs ~1 bin of potential waste; bias against it,
        // but relax when many open bins have large residuals (fragmentation high).
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 15.0 + fragmentation * 0.1 - 20.0 * (1.0 - progress);
    }

    // Mild pressure to consolidate: prefer bins with below-mean residual
    // (i.e., already partially filled relative to the fleet).
    let residual_gap = mean_residual - bin_residual as f64;
    score += 0.08 * residual_gap;

    // Slight preference for bins with more remaining usable space early on,
    // tighter bins later (horizon-aware packing).
    score += (1.0 - progress) * 0.05 * post_residual as f64
           - progress * 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;
    let fit_norm = item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = prn * prn * (0.5 + 1.5 * progress) - prn * (0.3 * progress + 0.1);
    score += 40.0 * poly;

    // Reward tight fits more strongly as the stream progresses
    score -= 25.0 * fit_norm * (1.0 + progress * (1.0 - fit_norm));

    // Penalize dead space that cannot hold a typical next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 15.0 * (nx - pr) / cap * (1.0 + progress);
        } else {
            score -= 8.0 * (1.0 - (pr - nx) / cap) * progress;
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening bins early, allow late in stream
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) * (1.0 + (open_bins_count as f64 / (1.0 + mean_residual / cap)) * 0.05);
        score -= 10.0 * progress;
    }

    // Mild preference for bins with residuals near the mean (balance)
    score += 3.0 * ((pr - mean_residual) / cap).abs();

    // Small smooth tie-breaker
    score += 0.01 * ((prn * 100.0).sin());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: harmonic classes of post_residual via integer division.
    let class = post_residual / 10; // coarse capacity-fraction class
    score -= match class {
        0 => 60.0,          // near-perfect fit (post_residual < 10)
        1 => 30.0,          // excellent fit
        2 => 12.0,          // good fit
        3 => 4.0,           // acceptable
        _ => 0.0,           // wasteful
    };

    // Modulo arithmetic on post_residual: residues that are awkward (small prime-ish leftovers)
    let r = post_residual % 10;
    if r == 1 || r == 2 || r == 3 {
        score += 8.0; // dead slivers unlikely to be filled
    }

    // Lookahead coupling: does the next item fit in the post residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // chain placement possible
            // bonus scaled by how snugly next item fits
            let snug = (post_residual - next_item_size) as f64;
            score -= (30.0 - snug.min(30.0)) * 0.4;
        } else {
            // penalty proportional to unusable leftover for the known next item
            score += (next_item_size as f64 - post_residual as f64).min(40.0) * 0.5;
        }
    } else {
        // last item: just minimize residual
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a bin unless current bin is a poor fit
    if bin_residual == bin_capacity {
        let waste = bin_residual as f64 - item_size as f64;
        score = 100.0 + waste * 0.3; // base high score for a fresh bin
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open
        }
    }

    // Mild pressure against hoarding many open bins late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.5 * progress;

    // Prefer bins whose residual is far below the mean (consolidate emptier bins)
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item size are wasted.
    // Penalize "unusable" gaps heavily; tiny gaps (1..=9) are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + 4.0 * (10 - post_residual as i32) as f64;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill;

    // Reward perfect closure.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            // mild preference proportional to how well next item fills the gap
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use the gap: penalize leaving a gap next item can't fill
            score += 6.0;
        }
    }

    // Last-chance bonus: only bin that fits -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.6 * open_bins_count as f64;

    // Slight preference toward bins with below-mean residual (consolidate emptier bins).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate: make it attractive only when existing fits are poor.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.4 * open_bins_count as f64;
        if fitting_bins_count <= 1 {
            score -= 20.0; // nothing fits well elsewhere, open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly matches leftover
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 50.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // dead space: next item can't use it
        score += 30.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Prefer filling nearly-full bins over sparse ones
    score += (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // New-bin candidate: penalize mildly, allow only when no good fit exists
    if bin_residual == bin_capacity {
        score += 60.0 + mean_residual * 0.3;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect or near-perfect fill.
    if post_residual == 0 {
        score -= 1000.0;
    } else if next_item_size == post_residual && next_item_size > 0 {
        // Lookahead: this placement sets up an exact fit for the next item.
        score -= 900.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item can still fit here: mild reward proportional to tightness.
        let tight = (post_residual - next_item_size) as f64;
        score -= 50.0 * (1.0 - tight / bin_capacity as f64);
    }

    // Penalize large dead space, especially when it cannot host the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 40.0 + (post_residual as f64) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless it enables a
    // great future pairing (e.g. item + next item nearly fills it).
    if bin_residual == bin_capacity {
        let pair_fill = (item_size + next_item_size.min(bin_capacity)) as f64 / bin_capacity as f64;
        if next_item_size > 0 && pair_fill > 0.95 {
            score -= 400.0; // opening a bin for a near-perfect pair is great
        } else if fitting_bins_count > 0 {
            score += 150.0; // don't open new bins when one fits
        } else {
            score -= 60.0; // no alternative: new bin is fine
        }
    }

    // Prefer bins whose residual is below the mean (consolidating fullness).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Mild preference for using more-open bins early vs late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (open_bins_count as f64).ln().max(0.0);

    // Small tie-break favoring larger items into this bin (less fragmentation).
    score -= (item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = x * (1.0 + 0.8 * progress) - 1.6 * x * x + 0.9 * x * x * x * (1.0 - progress);

    // Penalize dead space relative to mean residual across open bins
    score += 0.35 * (x - mean_residual / cap).abs();

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Lookahead: reward residual that can still host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fits_next = (pr >= next_item_size as f64) as i32 as f64;
        score -= 1.2 * fits_next * (1.0 - nx);
        score += 0.6 * nx * (1.0 - fits_next);
    }

    // Slight preference for tight fits (small post_residual relative to item)
    score += 0.4 * (item_size as f64 / cap) * x;

    // Encourage consolidation as stream progresses (avoid hoarding open bins)
    score += 0.05 * open_bins_count as f64 * (1.0 - progress) * x;

    // New-bin candidate: penalize opening a new bin unless current fits are poor
    if bin_residual == bin_capacity {
        score += 2.5 - 1.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: tiny leftovers are "dead space".
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class-based dead-space penalty: leftover in (0,10] is nearly unusable
    // for items >=10, but with sizes 1..100 use finer harmonic bands.
    if post_residual == 0 {
        score -= 40.0; // perfect fit: strongly reward
    } else if post_residual <= 5 {
        score += 8.0; // near-dead space
    } else if post_residual <= 15 {
        score += 4.0;
    } else if post_residual <= 30 {
        score -= 2.0; // sweet spot: fits small items
    }

    // Modulo-arithmetic coupling: leftover divisible by common item sizes
    // is more reusable (harmonic resonance).
    if post_residual > 0 {
        let mut resonance = 0.0;
        for m in [10u32, 20, 25, 50] {
            if post_residual % m == 0 {
                resonance += 2.5;
            }
        }
        score -= resonance;
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward proportional to how snugly next item fits
            let snug = 1.0 - ((post_residual - next_item_size) as f64 / cap);
            score -= 6.0 + 6.0 * snug;
        } else {
            // next item won't fit here: penalize wasting a good residual
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate (empty bin): make it attractive only when current
    // bin would leave bad residual or many bins already open.
    if bin_residual == bin_capacity {
        score = 25.0 + 0.1 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size <= post_residual.max(next_item_size) {
            // placeholder-free: next fits anywhere in empty bin
            score -= 5.0;
        }
    }

    // Slight preference for fuller bins as stream progresses.
    score -= 0.02 * (step_index as f64 / total_items.max(1) as f64) * (bin_capacity - bin_residual) as f64;

    // Mild tie-break toward consolidating residuals near the mean.
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
