pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small post_residual is already favored by base term).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 30.0;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: reward if the next item fits exactly or well into post_residual.
    if next_item_size > 0 {
        let lookahead_gap = post_residual as i64 - next_item_size as i64;
        if lookahead_gap == 0 {
            score -= 80.0; // perfect chain
        } else if lookahead_gap > 0 {
            // next item fits: reward proportionally to how tight the chain is
            let tight = 1.0 - (lookahead_gap as f64 / bin_capacity as f64);
            score -= 20.0 + 40.0 * tight * tight;
        } else {
            // next item does NOT fit: penalize leaving awkward residual
            score += 25.0;
            // worse if post_residual is small (dead space) and next item is large
            if post_residual < 10 {
                score += 20.0;
            }
        }
    }

    // Relative to mean residual: prefer bins that are tighter than average.
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: neutral-ish default; discourage unless few open bins or early.
    if bin_residual == bin_capacity {
        score += 60.0;
        if open_bins_count == 0 {
            score -= 200.0; // must open a bin
        }
        // late in the stream, prefer packing into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // if next item is large, opening fresh bin is more attractive
        if next_item_size >= 60 {
            score -= 30.0;
        }
    }

    // Penalize opening bins when many are already open with room.
    if bin_residual == bin_capacity && open_bins_count > 3 {
        score += (open_bins_count as f64 - 3.0) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize by normalized fit quality.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0;
        }
        // Perfect two-item packing: post_residual exactly fits next item.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else {
        // Last item: prefer fullest packing.
        score -= 15.0 * fit_ratio;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: prefer it only when current bins have poor fits.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln().max(0.0);
        score = 45.0 + pressure * 8.0;
        if fitting_bins_count == 0 {
            score = 5.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Time horizon: early stream, tolerate spread; late stream, tighten packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 5.0 * (mean_residual / bin_capacity as f64);

    // Prefer bins with residual close to mean (balanced depletion) mildly.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit = item_size as f64 / cap;
    let mut score = post;

    // Reward tight fits: subtract a non-linear function of fill ratio.
    let fill = 1.0 - post / cap;
    score -= 30.0 * fill * fill * fill;

    // Penalize residuals that are small but unusable (dead space) — smooth coupling.
    let dead = (post / cap) * (1.0 - post / cap);
    score += 25.0 * dead * (1.0 - fill);

    // Lookahead: reward residual that could host the next item, penalize near-misses.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let margin = post - nx;
        if margin >= 0.0 {
            let exact = 1.0 - (margin / cap).abs();
            score -= 12.0 * exact * exact;
        } else {
            score += 8.0 * (-margin / cap);
        }
    }

    // Stream progress: late in stream, prefer packing into existing bins more aggressively.
    score -= 15.0 * progress * (fit * fit);

    // Last-chance bin: strongly favor using it to avoid opening a bin for one item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it attractive only when existing bins fit poorly.
    let is_new = bin_residual == bin_capacity && item_size <= bin_capacity;
    if is_new {
        let crowd = open_bins_count as f64;
        let spread = (mean_residual - post).abs() / cap;
        score = cap * 0.9 - 10.0 * progress - spread * 5.0 + crowd.min(20.0);
        if fitting_bins_count == 0 {
            score -= cap; // no alternative: new bin is fine
        }
    }

    // Mild penalty for spreading across too many open bins early.
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fractions
    let frac = post_residual as f64 / cap;
    let class = (frac * 8.0).floor() as u32; // 0..7 harmonic octant

    // Reward bins whose leftover falls into "usable" harmonic classes
    // Classes: 0 (perfect/near-perfect fit), 7 (nearly empty bin -> still flexible)
    match class {
        0 => score -= 30.0,                       // tight fit, minimal waste
        1 => score -= 18.0,                       // small gap, likely dead space but acceptable
        2 => score -= 8.0,
        3 => score += 4.0,                        // awkward middle gap
        4 => score += 6.0,
        5 => score += 3.0,
        6 => score -= 2.0,
        _ => score -= 10.0,                       // bin still mostly empty, flexible
    }

    // Integer-division thresholds on post_residual: can it host common item bands?
    let bands = [1, 10, 20, 25, 30, 40, 50, 60, 80];
    let mut usable = 0usize;
    for &b in &bands {
        if post_residual >= b { usable += 1; }
    }
    score -= 3.0 * usable as f64;

    // Lookahead coupling: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here: penalize proportionally to wasted opportunity
            score += 6.0;
        }
        // modulo resonance: next_item_size divides post_residual evenly
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral baseline, slightly high so it's chosen only
    // when all open bins are poor fits; adjust with stream progress and load.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 45.0 + 20.0 * progress + 0.3 * open_bins_count as f64;
        // if mean residual across open bins is large, prefer reusing open bins
        score += 0.15 * mean_residual;
    }

    // Mean residual coupling: penalize bins far above the mean residual (fragmentation)
    score += 0.10 * ((post_residual as f64 - mean_residual).abs());

    // Mild tie-breaker against opening many bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps (below min item size) are pure waste.
    if post_residual < 10 {
        score -= 50.0; // perfect or near-perfect fill is excellent
    } else if post_residual < 20 {
        score += 40.0; // tiny dead gap: strongly penalize
    } else if post_residual < 30 {
        score += 15.0;
    }

    // Exact fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: penalize placements that don't close bins when many are open.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if post_residual > 0 {
        score += pressure * 4.0;
    } else {
        score -= pressure * 2.0; // closing a bin relieves pressure
    }

    // Lookahead: if next item fits the post residual, reward keeping this bin viable.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // New-bin candidate: make it moderately attractive only when residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 25.0 - pressure * 6.0 + fragmentation * 0.3;
        if fitting_bins_count == 1 {
            score += 80.0; // don't open a new bin when a last-chance bin exists
        }
    }

    // Late-stream tightening: consolidate more aggressively as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) via non-linear reward.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Coupling: reward grows with how snugly the next item fills the remainder.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 10.0 * snug;
        } else {
            // Dead space penalty scaled by how much the next item misses the hole.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.35 * miss;
        }
    } else {
        // Last item: strongly prefer tightest possible fit.
        score -= 8.0 * (1.0 - fit_ratio);
    }

    // Relative-to-mean coupling: bins far below mean residual are precious; penalize wasting them.
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        if rel < 1.0 {
            score += 6.0 * (1.0 - rel);
        } else {
            score -= 2.0 * (rel - 1.0).min(2.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to what open bins can absorb, or many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        score += 18.0 - 10.0 * item_frac - 4.0 * progress - 0.4 * open_bins_count as f64;
        // If no open bin fits (fitting_bins_count == 0 for open bins), opening is natural.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Slight preference for reusing bins when many are open (consolidation pressure).
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 12.0;

    // Penalize dead space that is too small for typical items (wasted).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 3.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else {
            score += 4.0;
        }
    }

    // Prefer filling bins with larger residuals when many bins are open (consolidation).
    let residual_gap = bin_residual as f64 - mean_residual;
    score += residual_gap * 0.05 * (open_bins_count as f64).sqrt();

    // Time horizon: early in stream, be conservative (favor new bins less);
    // late in stream, squeeze into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    // New-bin candidate adjustment: only attractive when item is large relative to
    // mean residual of open bins or few fitting bins exist.
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / mean_residual.max(1.0);
        if pressure > 1.0 && fitting_bins_count > 1 {
            score -= 15.0 * (pressure - 1.0);
        } else {
            score += 30.0;
        }
    }

    // Mild penalty for leaving very large residuals (poor space usage).
    if post_residual > bin_capacity / 2 {
        score += (post_residual as f64 - bin_capacity as f64 / 2.0) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (low post_residual), with a mild non-linear
    // penalty on very small residuals (dead space that is hard to reuse).
    let mut score = post;
    score += 0.35 * (post / cap).powi(3) * cap; // extra push toward tight packing

    // Smooth stream-progress coupling: early in the stream, keep residuals
    // flexible (penalize tiny residuals slightly more); late, pack tightly.
    let norm_post = post / cap;
    score += (1.0 - progress) * 12.0 * (1.0 - norm_post).powi(2) * 0.5;
    score -= progress * 6.0 * (1.0 - norm_post);

    // Last-chance bin: strong reward so we don't open a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin, more when many bins are open
    // or when the item fits elsewhere with a reasonable residual.
    if bin_residual == bin_capacity {
        let fit_elsewhere = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        let mut penalty = 8.0 + 1.5 * open_bins_count as f64;
        penalty += fit_elsewhere * (10.0 + 20.0 * (1.0 - progress));
        // If the next item is large and this new bin would hold it well,
        // soften the penalty slightly (smooth lookahead coupling).
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            let compat = (nx / cap) * (1.0 - nx / cap);
            penalty -= 8.0 * compat * (1.0 - progress);
        }
        score += penalty;
    }

    // Lookahead: reward leaving room for the next item (smooth interaction).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = post - nx;
        if diff >= 0.0 {
            score -= 4.0 * (1.0 - (diff / cap).abs()) * (1.0 - progress);
        } else {
            score += 2.0 * (-diff / cap) * cap * 0.1;
        }
    }

    // Slight tie-break toward bins whose residual is near the mean
    // (keeps the bin pool homogeneous and reusable).
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well it matches common item sizes
    let post = post_residual as u32;
    if post == 0 {
        score -= 60.0; // perfect fill
    } else {
        // Residual class quality: residuals that are multiples of common sizes
        let class_bonus: f64 = if post % 10 == 0 {
            18.0
        } else if post % 5 == 0 {
            10.0
        } else if post >= 10 && post <= 30 {
            6.0
        } else if post < 10 {
            -14.0 // tiny dead space
        } else {
            0.0
        };
        score -= class_bonus;

        // Does the lookahead item fit the post-residual exactly or well?
        if next_item_size > 0 {
            if next_item_size == post {
                score -= 45.0; // perfect pair
            } else if next_item_size <= post {
                let rem2 = post - next_item_size;
                if rem2 == 0 {
                    score -= 40.0;
                } else if rem2 % 10 == 0 {
                    score -= 20.0;
                } else if rem2 < 10 {
                    score += 8.0; // would leave tiny dead space
                } else {
                    score -= 6.0;
                }
            } else {
                score += 10.0; // lookahead cannot use this bin
            }
        }
    }

    // Tightness: prefer bins where the item fills a large fraction of residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly
    if bin_residual == bin_capacity {
        let poor_fit = mean_residual < item_size as f64 * 0.6
            || (next_item_size > 0 && next_item_size > mean_residual);
        if poor_fit {
            score -= 20.0 + 0.3 * open_bins_count as f64;
        } else {
            score += 30.0 + 2.0 * open_bins_count as f64; // discourage spreading
        }
    }

    // Late in stream: consolidate, penalize opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 12.0 * progress * (mean_residual - post_residual as f64).abs() / 10.0;
    score -= 15.0 * progress * fill_ratio;

    // Penalize bins far from mean residual (fragmentation control)
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (min size 1,
    // but treat < 10 as likely dead) are heavily penalized.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 20.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item cannot fit in post residual but could fit in bin_residual
    // only if we don't place here... penalize slightly when chaining matters.
    if next_item_size > post_residual && next_item_size <= bin_residual {
        score += 5.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones
    // over spreading out; also discourage opening new bins when mean residual is high.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: penalize opening a new bin unless existing bins have
    // very poor residuals (mean_residual high means current bins are full-ish).
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        // Opening a new bin is attractive only if mean residual across open bins
        // is small (they are nearly full).
        score = 120.0 - mean_residual.clamp(0.0, bin_capacity as f64);
        if mean_gap < 0.0 {
            score += 40.0; // bins can't even fit the item anyway
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits next item -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item still fits here: reward proportional to closeness.
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 / (1.0 + gap / 10.0);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space: next item cannot use the leftover.
        score += 15.0;
        // Extra penalty if leftover is unusably small (below min item size).
        if post_residual < 10 {
            score += 20.0;
        }
    }

    // Reward tight fits relative to bin residual (small post_residual is good anyway).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 10.0 * tightness;

    // Penalize bins far above mean residual (fragmented bin), reward below-mean bins.
    score += 0.3 * ((post_residual as f64) - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 30.0;
        // As stream progresses, discourage proliferation of open bins slightly.
        score += 5.0 * (step_index as f64 / (total_items as f64).max(1.0));
    }

    // Slight bias toward bins that leave residuals in reusable mid-range.
    if post_residual >= 10 && post_residual <= 40 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Penalize large dead space: residual that no future item (min size 1..10) can use well.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // small residual likely unusable anyway -> fine
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 4.0; // awkward mid-range dead space
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item also fits here -> great chaining.
            let after_next = post_residual - next_item_size;
            score -= 10.0;
            if after_next == 0 {
                score -= 15.0; // exact two-item fill
            } else if after_next < 10 {
                score -= 6.0;
            }
        } else {
            // Next item won't fit here; penalize leaving just-barely-unusable space.
            if post_residual > 0 && post_residual < next_item_size {
                score += 3.0;
            }
        }
    }

    // New-bin candidate logic: only attractive when open bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so we prefer existing bins with decent fits.
        score += 20.0;
        // More open bins -> higher penalty for opening yet another.
        score += open_bins_count as f64 * 2.0;
        // Early in stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // If next item is large and this bin would be fresh, a new bin is more valuable.
        if next_item_size > item_size {
            score -= 8.0;
        }
        // If mean residual across open bins is already high, opening new bin is wasteful.
        score += mean_residual * 0.15;
        // If this bin is the only fitting bin, opening a new one is less attractive.
        if fitting_bins_count == 1 {
            score += 10.0;
        }
    }

    // Mild global pressure: when many bins are open with high mean residual,
    // prefer consolidating into bins with residual near mean (balanced packing).
    if !is_new_bin {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    let fill = 1.0 - pr_norm;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = 1.0 + 0.6 * t - 0.4 * t * t;
    score -= 30.0 * poly * (1.0 - pr_norm).powi(2);

    // Reward tight fits more strongly as stream advances
    let tightness = (item_size as f64 / bin_residual.max(1) as f64).powi(3);
    score -= 25.0 * tightness * (0.5 + t);

    // Penalize large dead space quadratically, amplified late in stream
    score += 0.8 * pr_norm * pr_norm * cap * (1.0 + t);

    // Lookahead coupling: favor residuals matching next item
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score += 0.3 * diff;
        if pr >= next_item_size as f64 && diff < 5.0 {
            score -= 8.0 * (1.0 - t);
        }
    }

    // Last-chance bin: strong reward to avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + t);
    }

    // Mild pressure toward consolidating into fewer bins
    score -= 0.5 * (mean_residual - pr).abs() / cap;

    // New-bin candidate: penalize mildly unless current residuals are all poor
    if bin_residual == bin_capacity {
        let poor = ((mean_residual / cap) - 0.2).max(0.0);
        score += 12.0 - 20.0 * poor * (1.0 + t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: modulo arithmetic on capacity fractions ---
    let pr = post_residual as i64;
    let cap = bin_capacity as i64;
    // Classes: post_residual divisible by 10 -> "clean" slots reusable by typical items
    let class_mod = pr % 10;
    if class_mod == 0 {
        score -= 12.0; // perfectly reusable residual
    } else if class_mod <= 3 || class_mod >= 7 {
        score += 6.0 + (class_mod as f64) * 1.5; // awkward dead space
    }

    // Integer division thresholds: how many average items still fit
    let slots = pr / 10;
    score -= (slots as f64).min(9.0) * 2.0;

    // --- Coupling with next item (lookahead k=2) ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item also fits here -> strong reward
            score -= 20.0;
            let combo_waste = (post_residual - next_item_size) as f64;
            score += combo_waste * 0.3;
        } else {
            // next item won't fit -> penalize, but less if post_residual is tiny
            let gap = (next_item_size - post_residual) as f64;
            score += (gap * 0.15).min(15.0);
        }
        // harmonic class match: next_item_size aligns with residual mod 10
        if (next_item_size as i64) % 10 == class_mod {
            score -= 5.0;
        }
    }

    // --- Last chance bin: if this is the only fitting bin, avoid opening a new one ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate: keep it competitive only when fits are poor ---
    if bin_residual == bin_capacity {
        // opening fresh is penalized mildly; attractive only if all fits are bad
        score = 55.0
            - (mean_residual / bin_capacity as f64) * 10.0
            - (open_bins_count as f64).min(10.0);
        if next_item_size > 0 && next_item_size >= 70 {
            score -= 10.0; // big item coming, fresh bin useful
        }
        if post_residual as f64 >= mean_residual * 0.9 && bin_residual < bin_capacity + 1 {
            score += 5.0;
        }
    }

    // --- Progression-aware pressure: late in stream, consolidate ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins tighter than mean residual (good fits)
    if (post_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += ((post_residual as f64) - mean_residual) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // anything useful (1..=min_item) are pure waste; penalize them hard.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0;
    }
    // Small unusable gaps (below typical item sizes) get escalating penalty.
    if post_residual > 0 && post_residual <= 10 {
        score += (11 - post_residual) as f64 * 12.0;
    } else if post_residual <= 25 {
        // Mid-range gaps are partially usable; mild penalty scaled by waste ratio.
        score += (post_residual as f64) * 0.35;
    }

    // Reward tight fits: perfect fill is ideal.
    if post_residual == 0 {
        score -= 150.0;
    } else {
        let fit_quality = item_size as f64 / bin_residual as f64;
        score -= fit_quality * 60.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a bin is expensive when few bins
    // are open, but attractive when many open bins have scattered residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = open_bins_count as f64;
        // Base cost of a new bin.
        let mut new_bin_score = 55.0;
        // If mean residual across open bins is small (poor future usability),
        // a fresh bin is more attractive.
        new_bin_score -= (mean_residual / 100.0).min(1.0) * 40.0;
        // Late in the stream, avoid proliferating bins.
        new_bin_score += progress * 30.0;
        // Many open bins: prefer consolidating into one of them.
        new_bin_score += openness * 3.0;
        // Lookahead: if next item fits in this fresh bin alongside current item,
        // opening is fine; if next item is large, prefer keeping residuals big.
        if next_item_size > 0 {
            if next_item_size + item_size <= bin_capacity {
                new_bin_score -= 20.0;
            } else {
                new_bin_score += 15.0;
            }
        }
        score = score.min(new_bin_score + score * 0.5);
        // Ensure new bin never wins when a decent fit exists.
        if fitting_bins_count > 0 && post_residual <= 10 {
            score += 200.0;
        }
    }

    // Open-bins pressure: mildly discourage adding load to bins when many
    // bins are open and residual is large (spread risk), encourage using
    // bins with residuals close to item size.
    let gap = (bin_residual - item_size) as f64;
    if bin_residual != bin_capacity {
        score += (gap / bin_capacity as f64) * (open_bins_count as f64) * 2.0;
        // Bonus when bin residual is just slightly larger than item.
        if gap <= 5.0 {
            score -= 45.0;
        }
    }

    // Lookahead coupling: prefer leaving residuals that can host next item.
    if next_item_size > 0 && bin_residual != bin_capacity {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits (small post_residual).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as f64 >= next_item_size as f64 {
            // Next item fits exactly or nearly: strong reward.
            score -= 300.0 / (1.0 + gap);
        } else {
            // Next item won't fit here: penalize proportionally to wasted lookahead potential.
            score += 50.0 + gap * 0.5;
        }
    }

    // Compare post_residual relative to mean residual of open bins.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Penalize opening a new bin when good fitting bins exist, unless current bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = if open_bins_count == 0 { 0.0 } else { mean_residual / bin_capacity as f64 };
        // Open new bin if existing residuals are all small (crowded); otherwise penalize.
        score += 120.0 - crowding * 200.0;
    }

    // Mild preference early in the stream to keep bins open and flexible.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 10.0;

    // Slight penalty proportional to item size to prefer filling bins with big items now.
    score += item_size as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any item (min size 1, but small
    // residuals under ~10 are effectively dead for typical distributions).
    let tiny = post_residual as f64 / bin_capacity as f64;
    if post_residual < 10 {
        score += 25.0 + 50.0 * tiny;
    } else {
        score -= 8.0 * (1.0 - tiny) * (1.0 - tiny); // reward tight fits
    }

    // Lookahead coupling: if the next item fits the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            // next item won't fit: penalize proportionally to wasted pairing chance
            score += 4.0 + 0.10 * (next_item_size as f64 - post_residual as f64).min(40.0);
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (unless post-residual would be dead space).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
        if post_residual < 10 { score += 15.0; }
    }

    // New-bin candidate handling: opening a new bin is expensive when open bins
    // still have room; make the empty-bin call attractive only for large items
    // that would leave good residuals elsewhere unusable.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 0.05 * open_bins_count as f64;
        // late in the stream, be more willing to open new bins
        score -= 18.0 * progress;
        if item_size >= 50 { score -= 8.0; }
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into bins with residual near mean (avoid fragmenting).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild time-horizon modulation: early items -> tighter packing matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // early on, tolerate larger residuals (bins stay flexible);
    // late, penalize residual super-linearly to force tight packing.
    let tightness = 1.0 + 2.5 * progress * progress;
    score += pr * (pr / cap) * tightness;

    // Smoothly reward near-perfect fits, stronger as stream progresses.
    let fit_frac = 1.0 - (pr / cap);
    score -= fit_frac * fit_frac * (10.0 + 20.0 * progress);

    // Lookahead: if the next item fits into post_residual, reward this bin smoothly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= (1.0 - slack * slack) * (5.0 + 15.0 * progress);
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty growing with progress.
        score += 3.0 + 7.0 * progress;
    }

    // Last-chance bin: strongly discourage opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 + 12.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin, less so early in the stream
    // and less when many open bins are already nearly full (high mean residual).
    if bin_residual == bin_capacity {
        let openness = 1.0 - (mean_residual / cap).min(1.0);
        score += 12.0 * (1.0 - progress) * openness + 6.0 * openness;
        // Slight preference to keep new bins when few bins exist.
        if open_bins_count <= 1 {
            score -= 10.0;
        }
    }

    // Mild diversity pressure: many open bins with high mean residual -> favor filling existing ones.
    score += (open_bins_count as f64).sqrt() * (1.0 - (mean_residual / cap).min(1.0)) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (multiples of common small sizes) are favored.
    let pr = post_residual;
    if pr > 0 {
        // Dead-space penalty: leftovers that are awkward (prime-ish / odd small gaps)
        let mut awkward = 0.0;
        if pr < 10 {
            awkward = 8.0; // tiny slivers are nearly useless
        } else if pr % 10 != 0 && pr % 5 != 0 {
            awkward = 3.0; // not aligned to common item granularities
        }
        // Class bonus: leftover exactly matches a plausible next-item size bucket
        let class_bonus = match pr / 5 {
            0..=1 => 0.0,
            2..=5 => 2.0,   // 10..=25 leftover: easy to fill
            6..=11 => 1.0,  // 30..=55 leftover: moderate
            _ => 0.5,
        };
        score += awkward - class_bonus;

        // Perfect-fit harmonic reward: post_residual divisible by small harmonics
        if pr % 10 == 0 { score -= 4.0; }
        else if pr % 20 == 0 { score -= 5.0; }
        if pr == 0 { score -= 12.0; } // exact fill
    }

    // Lookahead coupling: does post_residual accommodate next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0 + (post_residual - next_item_size) as f64 * 0.05;
        } else {
            score += 2.0; // bin closes, forcing new bin for next item
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bin
    // would leave a bad fit and mean residual is already large.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: keep it competitive only when reuse is bad
        score = 45.0 + post_residual as f64;
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative: new bin is fine
        } else if fitting_bins_count == 1 {
            score += 8.0;  // discourage abandoning the last usable bin
        }
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 5.0; // item barely fits anyway
        }
    }

    // Stream progression: early on, be conservative (keep bins tight);
    // late in stream, allow looser packing since fewer items remain.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // Many open bins: favor filling existing ones to cap bin count growth
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // A post_residual gap in 1..=9 is nearly unusable (items are >= 1..100 but
    // small gaps waste capacity). Penalize heavily so the new-bin candidate
    // (which preserves a large usable residual) wins instead.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }
    // Gaps of 10..=14 are marginally usable; mild penalty.
    else if post_residual < 15 {
        score += 20.0;
    }

    // Perfect fit: zero waste, reward strongly.
    if post_residual == 0 {
        score -= 25.0;
    }

    // --- Open-bins pressure: mildly discourage spreading across many bins ---
    score += open_bins_count as f64 * 0.5;

    // --- Last-chance bin: if this is the only open bin that fits, use it
    // rather than opening a new bin (unless it creates dead space). ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // --- New empty bin candidate: penalize so we prefer consolidating into
    // open bins unless all alternatives create dead space / fit poorly. ---
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    // --- Lookahead (k=2): reward leaving exactly the space the next item needs. ---
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
        // Extra reward for an exact lookahead match.
        if post_residual == next_item_size {
            score -= 8.0;
        }
    }

    // --- Mean-residual coupling: prefer bins whose residual is tighter than
    // the fleet average (they are the "closest fit" candidates). ---
    let excess = bin_residual as f64 - mean_residual;
    if excess > 0.0 {
        score += excess * 0.1;
    } else {
        score += excess * 0.05; // smaller reward magnitude below average
    }

    // --- Stream progression: late in the stream, slightly favor closing out
    // bins (perfect/near-perfect fits matter more as the stream ends). ---
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if post_residual == 0 {
            score -= 10.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor exact/near-exact fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 400.0;
        } else {
            score += diff as f64 * 0.8;
        }
        // Penalize leaving a residual that is too small for the next item (dead space).
        if (post_residual as u32) < next_item_size {
            score += (next_item_size - post_residual as u32) as f64 * 0.5;
        }
    }

    // Penalize deviations from mean residual (prefer balanced or tight bins).
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bonus: if this is the only fitting bin, prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large relative to capacity.
    if bin_residual == bin_capacity {
        score += 60.0 + (bin_capacity - item_size) as f64 * 0.2;
    }

    // Late in the stream, be more conservative: prefer tighter fills.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * (bin_capacity as f64 * 0.5);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 && post_residual > 0 {
        if (post_residual as u32) < next_item_size {
            score += (next_item_size as f64 - post_residual as f64) * 0.8;
        } else {
            // Reward residual that can still accommodate the next item
            score -= (post_residual as f64 - next_item_size as f64).min(next_item_size as f64) * 0.3;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bin is a poor fit
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = post_residual as f64 > bin_capacity as f64 - item_size as f64 - 1.0;
        // A new empty bin always has post_residual == capacity - item_size
        let perfect_waste = (bin_capacity - item_size) as f64;
        // Penalize new bin more when many open bins exist and mean residual is high
        score += perfect_waste * 0.6 + open_bins_count as f64 * 2.0 + mean_residual * 0.2;
        // Slightly less penalty late in the stream (less future to plan for)
        score -= progress * 10.0;
        if poor_fit {
            score += 5.0;
        }
    } else {
        // Reward using existing bins, more so when many bins are open (consolidation)
        score -= open_bins_count as f64 * 1.5;
        // Prefer bins with residual close to mean (balanced usage)
        score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;
    }

    // Prefer filling larger items into bins with proportionally matching residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 {
        score -= 15.0 * fill_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth polynomial coupling: dead space penalized super-linearly as stream progresses
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual), stronger late in the stream
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.3 + 0.7 * progress);

    // Coupling with mean residual: placing into a bin far above mean residual wastes flexibility
    score += 0.15 * (pr - mean_residual) * (0.5 + progress);

    // Lookahead: reward leaving space for the next item, penalize near-miss
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 12.0 * (1.0 - ((pr - nx) / cap).abs());
        } else {
            score += 8.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mildly discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // small "usable" residue classes (divisible by common item sizes) are favored.
    let pr = post_residual;
    let mut harmonic_bonus = 0.0;
    for d in [10u32, 20, 25, 50, 100] {
        if d == 0 { continue; }
        if pr % d == 0 && pr > 0 {
            harmonic_bonus += 8.0 * (d as f64 / 10.0);
        }
    }
    score -= harmonic_bonus;

    // Penalize tiny dead space that no item (1..=100) can realistically use:
    // post_residual in awkward mid ranges (e.g. 1..=9) is nearly unusable.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }
    // Mid-range awkward residuals (just above common item sizes) are dead zones.
    if pr > 10 && pr <= 15 { score += 6.0; }
    if pr > 25 && pr <= 30 { score += 4.0; }
    if pr > 50 && pr <= 55 { score += 3.0; }

    // Integer-division threshold: reward near-perfect fills.
    if pr == 0 { score -= 40.0; }
    if pr <= 5 { score -= 15.0; }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size <= pr {
            // fraction of next item's size consumed by this residual
            let fit_frac = next_item_size as f64 / pr.max(1) as f64;
            score -= 12.0 * fit_frac;
        } else {
            // next item cannot use this residual: penalize proportionally
            let waste = (next_item_size - pr) as f64 / cap;
            score += 10.0 * waste;
        }
    }

    // Tightness: reward filling a large fraction of the bin now.
    let fill_frac = item_size as f64 / cap;
    score -= 15.0 * fill_frac;

    // Progress modulation: late in the stream, prefer tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * fill_frac;

    // If this bin is much emptier than average, mildly discourage scattering.
    let resid_frac = bin_residual as f64 / cap;
    if resid_frac > mean_residual / cap + 0.2 {
        score += 4.0;
    }

    // New-bin candidate: make it attractive only when no open bin is a good fit
    // (poor fits elsewhere) — otherwise discourage opening bins freely.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && mean_residual >= item_size as f64 * 0.9;
        if good_fit_exists {
            score += 30.0;
        } else {
            score += 5.0;
        }
        // scale new-bin cost with number of already open bins
        score += 1.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fit reward
    }

    // Reward tight fits (post_residual small relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += tightness * 12.0;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when item leaves large usable
    // space or no open bin fits well.
    if bin_residual == bin_capacity {
        score += 20.0; // base cost of opening a new bin
        if post_residual >= 50 {
            score -= 15.0; // roomy new bin is fine for big items
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 10.0; // new bin wasted if next item can't use leftover
        }
    }

    // Lookahead: favor bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += 4.0;
    }

    // Slight preference for fuller bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity - bin_residual) as f64 * 0.1 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-item pairing
        } else if post_residual >= next_item_size {
            // leftover after both items: penalize proportionally to waste
            let leftover = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.35 * leftover;
        } else {
            // next item won't fit here: penalize dead space relative to mean residual
            score += (post_residual as f64 - mean_residual).abs() * 0.5;
        }
    }

    // Tight fit reward: small post_residual means efficient packing now.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Penalize opening new bins early in the stream when a fit exists.
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        // but if no open bin fits tightly, new bin is more attractive
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 55.0;
        }
    }

    // Spread-aware coupling: prefer bins near the mean residual to keep balance.
    score += 0.2 * (post_residual as f64 - mean_residual);

    score.max(0.0)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post_residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize post_residual that is small but unusable (dead space trap):
    // residual that can't fit typical future items is wasted.
    let dead = (post_residual > 0 && post_residual < 10) as i32 as f64;
    score += 8.0 * dead;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual >= next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty scaled by how much overflow
            score += 2.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Prefer filling bins with large residual when many bins are open
    // (bin consolidation) — compare bin_residual to mean_residual.
    let res_diff = bin_residual as f64 - mean_residual;
    score += 0.03 * res_diff * (open_bins_count as f64).sqrt();

    // Time horizon: early in stream, encourage spreading (slight bonus for new bins);
    // late in stream, consolidate to close out bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses
        score += 5.0 * progress;
        if fitting_bins_count > 0 {
            score += 3.0; // avoid opening new bin when alternatives exist
        }
    } else {
        score -= 2.0 * progress; // favor existing bins late
    }

    // Mild penalty for very full bins early (keep flexibility), reward late
    let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score += 3.0 * fill * (1.0 - progress) - 2.0 * fill * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let coupling = norm_pr * norm_pr * (1.0 - t) + norm_pr * t * t;
    score += 40.0 * coupling;

    // Reward high fill ratio smoothly
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: penalize if post_residual is just below next item (dead space)
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap < 0.0 {
            score += 8.0 * (-gap / cap);
        } else {
            score -= 6.0 * (gap / cap) * (1.0 - gap / cap);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins with residual near mean (balance), smooth term
    score += 3.0 * ((pr - mean_residual) / cap).powi(2);

    // Mild penalty for many open bins late in stream
    score += 0.5 * (open_bins_count as f64) * t * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod 10 and mod 20
    let r10 = post_residual % 10;
    let r20 = post_residual % 20;

    // Penalize residuals that are "dead" (too small to ever fit, min item = 1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10 - post_residual) as f64;
    }

    // Reward residuals in "usable" harmonic classes (multiples of 10 preferred)
    if r10 == 0 {
        score -= 8.0;
    } else if r20 == 0 {
        score -= 4.0;
    } else {
        // distance to nearest multiple of 10
        let d = r10.min(10 - r10) as f64;
        score += 1.5 * d;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            score -= 12.0;
            if leftover % 10 == 0 {
                score -= 5.0;
            }
            if leftover < 10 && leftover > 0 {
                score += 6.0;
            }
        } else {
            // next item cannot follow here; slight penalty for tight fits that strand space
            score += 2.0 * (next_item_size - post_residual) as f64 / 10.0;
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral-ish baseline, opened only when fits are bad
    if bin_residual == bin_capacity {
        score += 10.0;
        // open a new bin if existing fits would leave stranded space
        if post_residual > 0 && post_residual < 10 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size > item_size && post_residual < next_item_size {
            score -= 5.0;
        }
    }

    // Progress-aware: late in stream, consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild tie-break toward bins with below-mean residual (denser bins)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item are pure waste.
    if post_residual < 10 {
        score -= 50.0; // perfect closure of the bin is excellent
    } else if post_residual <= 20 {
        // small gap: only usable by tiny items; penalize harshly
        score += 40.0;
    } else if post_residual <= 40 {
        score += 10.0;
    }

    // Reward tight fits (low post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: prefer consolidating when many bins open
    score += 2.0 * open_bins_count as f64;

    // Prefer bins whose residual is near the item (avoid fragmenting large residuals)
    score += 0.15 * (bin_residual as f64 - item_size as f64);

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // Penalize leaving a gap that the next item just barely misses
    if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        score += 8.0;
    }

    // New-bin candidate: neutral baseline, becomes attractive when open bins are fragmented
    if bin_residual == bin_capacity {
        score = 60.0 + 3.0 * open_bins_count as f64 - mean_residual.min(100.0);
        if fitting_bins_count == 1 {
            score += 80.0; // don't abandon the only fitting bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the leftover space can be
    // exactly (or nearly) consumed by the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        if pr >= nxt {
            // Perfect match: leftover space is exactly consumed next step.
            if diff < 0.5 {
                score -= 60.0;
            } else {
                // Reward closeness of fit, scaled by tightness.
                score -= 40.0 * (1.0 - diff / bin_capacity as f64);
            }
        } else {
            // Next item does not fit in the leftover: penalize dead space,
            // worse when the leftover is small and unusable.
            score += 15.0 * (1.0 - pr / bin_capacity as f64);
        }
    } else {
        // Last item in stream: just minimize leftover waste.
        score += 10.0;
    }

    // Penalize creating very small dead space (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Early in the stream, allow more exploration of new bins; later,
    // consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses, and when
        // many bins are already open.
        score += 8.0 * progress + 1.5 * open_bins_count as f64;
        // But if the current item is large, a fresh bin is reasonable.
        score -= 0.15 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual (non-linear).
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tight * tight;

    // Perfect / near-perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 5 {
        score -= 20.0;
    }

    // Lookahead: reward if next item fits in post_residual, penalize if it nearly fits.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            score -= 12.0 * (1.0 - nxt / cap);
        } else if nxt <= bin_residual as f64 {
            // Next item would fit here only if we place better; mild penalty for wasting.
            score += 6.0 * (nxt - post_residual as f64) / cap;
        } else {
            // Next item won't fit regardless; residual waste is less costly.
            score -= 3.0;
        }
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: be pickier about loose fits.
        score += 4.0 * (post_residual as f64) / cap;
    }

    // New-bin candidate handling: empty bin has full residual.
    if bin_residual == bin_capacity {
        // Prefer new bin only if no open bin gives a good fit (post_residual small)
        // or there are no open bins at all.
        let good_fit_elsewhere = post_residual == 0; // placeholder; for empty bin post_residual = cap - item
        let waste = post_residual as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Late in the stream, avoid opening new bins more aggressively.
        let open_penalty = 40.0 + 30.0 * progress;
        if open_bins_count == 0 {
            score -= open_penalty;
        } else {
            // Penalize new bin unless this item would leave large unusable waste anywhere.
            score += open_penalty - 0.1 * waste;
            if good_fit_elsewhere && item_size as f64 > 0.9 * cap {
                score -= open_penalty; // huge item: fresh bin is fine
            }
        }
    }

    // Global state coupling: if mean residual is high, spread items less; prefer bins below mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0 * ((bin_residual as f64) - mean_residual) / cap;
    }

    // Mild penalty for proliferating bins early.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * open_bins_count as f64 * (1.0 - progress) / 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted residual, with non-linear (quadratic) dead-space growth.
    let mut score = norm_pr * (1.0 + 2.0 * norm_pr * norm_pr) * cap * 0.05;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills; later, tolerate larger residuals slightly less.
    let coupling = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += coupling * norm_pr * 8.0;

    // Reward near-perfect fits smoothly (small post_residual relative to capacity).
    let tightness = (1.0 - norm_pr).powi(3);
    score -= 10.0 * tightness;

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: reward leaving room for the next item (smooth quadratic gap match).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 6.0 * (1.0 - (gap / cap).min(1.0)).powi(2);
    }

    // Mild pressure to consolidate when many bins are open relative to mean residual.
    let mean_norm = mean_residual / cap;
    score += 0.5 * (open_bins_count as f64).sqrt() * mean_norm;

    // New-bin candidate: neutral baseline so it only wins when open bins score poorly.
    if bin_residual == bin_capacity {
        score += 4.0 + coupling * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify dead space by divisibility
    let pr = post_residual as i64;
    let class_bonus: f64 = if pr == 0 { 0.0 }
        else if pr % 50 == 0 { -30.0 }        // half-capacity residual: highly reusable
        else if pr % 25 == 0 { -20.0 }
        else if pr % 10 == 0 { -12.0 }
        else if pr % 5 == 0 { -6.0 }
        else if pr < 10 { 40.0 }              // tiny dead space: unusable
        else { 0.0 };
    score += class_bonus;

    // Small residuals are dead space; penalize quadratically below threshold
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * (10 - post_residual) as f64 * 2.0;
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: mildly penalize opening bins when decent fits exist
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64 * (1.0 - mean_residual / bin_capacity as f64);
    }

    // Tight fit reward: item fills most of the bin
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * fill * 20.0;

    // Late in stream: prefer consolidation into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
