    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Favor bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.4;

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
