        score += 25.0 + gap_penalty + open_bins_count as f64 * -0.5;
        // If next item could use the fresh bin's large residual, mild bonus.
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64) < 15.0 {
            score -= 10.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 15.0;
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / tight fits
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        if next <= pr {
            let gap = pr - next;
            if gap <= 10.0 {
                score -= 80.0; // next item fits almost perfectly
            } else {
                score -= 30.0 * (1.0 - gap / 100.0);
            }
        } else {
            // next item won't fit here; mildly penalize large leftover
            score += 0.3 * (pr - next).abs();
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.5 * (pr - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        // new-bin candidate: score is capacity; add penalty unless stream is early
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    }

    // Slight preference for consolidating among many open bins
    score -= 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 12.0;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize dead space that no plausible item can fill
    if post_residual > 0 {
        let min_item = 1.0f64;
        if (post_residual as f64) < min_item {
            score += 5.0;
        }
        // residual too small relative to typical items: dead space
        let typical = if next_item_size > 0 { next_item_size as f64 } else { item_size as f64 };
        if (post_residual as f64) < typical * 0.35 {
            score += 8.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }
    // Many fitting bins: mild penalty to encourage spreading load / consolidation choice
    if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Global state: favor filling bins when many are open
    let open_pressure = (open_bins_count as f64 / (1.0 + total_items as f64 * 0.05)).min(3.0);
    score += open_pressure * 2.0 * fit_ratio;

    // Mean residual alignment: prefer bins whose residual is near the mean (balanced usage)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Time horizon: early in stream, slightly prefer new bins (exploration); late, consolidate
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: accept early, penalize late
        score -= 10.0 * (1.0 - progress);
        score += 25.0 * progress;
        // If no open bin fits well, opening is fine
        if post_residual == 0 {
            score -= 5.0;
        }
    } else {
        // Late stream: reward using existing bins
        score -= 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = 1.0 + 2.0 * t - 3.0 * t * t + 2.0 * t * t * t;
    score += norm_pr * norm_pr * 40.0 * poly;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 15.0 * (0.5 + t);

    // Penalize post_residual that cannot fit the lookahead item (dead space)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (0.8 + 1.2 * t);
        } else {
            score -= 4.0 * (1.0 - (pr - nxt) / cap);
        }
    }

    // Last-chance bin bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize slightly so we prefer reusing open bins,
    // unless existing residuals are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - norm_item * cap).abs() / cap;
        score += 10.0 - 8.0 * fragmentation.min(1.0) + 5.0 * t;
    }

    // Mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.3 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "nice"
    // multiples / divisors of capacity fractions (usable by future items).
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit, always best
    } else {
        // Harmonic bonus: residual divisible by common small sizes
        let mut harmonic = 0.0;
        for d in [1u32, 2, 4, 5, 10, 20, 25, 50] {
            if pr % d == 0 {
                harmonic += 10.0;
            }
        }
        score -= harmonic;

        // Integer-division thresholds: classify residual into dead-space classes
        let class = pr / 10; // 0..=10 classes
        score -= (class as f64) * 3.0;

        // Penalize residuals that no plausible item (1..=100) can pair well with:
        // tiny residuals (< 10) are dead space
        if pr < 10 {
            score += 60.0;
        }
    }

    // Reward tight fits relative to item size
    let tightness = item_size as f64 / cap;
    score -= tightness * 40.0;

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead: if next item fits in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 25.0 + (next_item_size as f64 / cap) * 20.0;
        } else {
            // penalize leaving residual that next item almost fits
            let gap = (next_item_size - pr) as f64;
            if gap < 10.0 {
                score += gap * 2.0;
            }
        }
    }

    // Prefer using bins with low mean residual (consolidating waste)
    score += (mean_residual - post_residual as f64).max(0.0) * 0.3;

    // Mild penalty for opening new bin when many open bins exist
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64) * 2.0;
        // but acceptable if nothing fits well
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Slight time decay: later in stream, favor closing bins tightly
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: residuals of 1..=9 are essentially unusable
    // for future items (min size 1..100 stream, but small gaps waste capacity).
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0; // heavy penalty for creating tiny dead gaps
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit strongly rewarded
    }

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize leaving a gap just below the next item (blocking lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }
    // Reward when post_residual can host the next item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open bins pressure: prefer filling existing bins when many are open.
    score += 0.6 * open_bins_count as f64;

    // New-bin candidate: make it unattractive unless no open bin fits well.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
        // Allow new bin if the best-case placement would still be wasteful.
        if post_residual > 40 {
            score -= 20.0;
        }
    }

    // Mild phase bias: later in stream, be greedier about closing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual small relative to item).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward if next item fits the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_tightness = next_item_size as f64 / post_residual as f64;
        score -= 15.0 * lookahead_tightness;
        // Perfect chain: post_residual exactly equals next item.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // Penalize creating residual that cannot host the next item,
        // scaled by how dead the space is.
        let dead = post_residual as f64;
        let unusable = (dead / (next_item_size as f64)).min(1.0);
        score += 8.0 * unusable * (dead / bin_capacity as f64);
    }

    // Penalize large leftover relative to mean residual (wasteful bin).
    score += 0.4 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no existing bin offers a reasonable fit (fit_ratio small means good fit).
    if bin_residual == bin_capacity {
        // Mild base preference to reuse bins.
        score += 6.0;
        // If the item would fit poorly in any bin (few fitting bins) and the
        // item is large, a fresh bin is fine.
        if fitting_bins_count <= 1 && item_size > bin_capacity / 2 {
            score -= 10.0;
        }
        // If next item is large too, a fresh bin keeps room for pairing.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Slight pressure to consolidate when many bins are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of the bin after placement.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill;

    // Penalize small dead space that can never be reused by typical items.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 25.0 * (10.0 - dead) / 10.0; // tiny slivers are nearly useless
        }
    }

    // Lookahead: bonus if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for leaving a mid-sized gap.
            let gap = post_residual as f64;
            if gap >= next_item_size as f64 * 0.5 {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when existing bins are crowded.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 12.0;
        // Cheaper to open a new bin when few bins are open (early stream).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // If open bins are nearly full on average, a new bin is fine.
        score -= 6.0 * (mean_residual / bin_capacity as f64);
        // If many bins already fit the item, discourage the new bin.
        if fitting_bins_count > 1 {
            score += 10.0 * (fitting_bins_count as f64).min(4.0);
        }
        // Perfect fit alternative exists? Then new bin is wasteful.
        if post_residual == 0 {
            score += 40.0;
        }
    }

    // Mild preference to keep open-bin count low (consolidation pressure).
    score += 0.05 * open_bins_count as f64;

    // Slight time-decay: later in the stream, favor filling existing bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global residual alignment: prefer bins whose residual is near the mean
    // (keeps residuals homogeneous, easier for future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * (1.0 - progress);

    // Reward tight fits (small post_residual), increasingly so late in the stream
    let mut score = pr + poly * cap * 0.5;

    // Penalize last-chance bins less (favor using them)
    if fitting_bins_count == 1 {
        score -= 8.0 + 12.0 * progress;
    }

    // Lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 6.0 * (1.0 - diff / cap).max(0.0);
    }

    // Slight penalty when bin residual is far above mean residual (poor global fit)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Make new bins slightly costly so existing bins are preferred unless fit is bad
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: integer-division thresholds on capacity fractions
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let item_class = item_size / quarter; // 0..3
    let next_class = if next_item_size > 0 { next_item_size / quarter } else { 0 };

    // Reward exact / near-exact fits strongly
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    }

    // Modulo-arithmetic dead-space penalty: residual classes that are hard to fill
    let mod_class = post_residual % 10;
    let dead_penalty = match mod_class {
        0 => -30.0,                 // round residual, easy to reuse
        1 | 2 | 3 => 15.0,          // awkward slivers
        8 | 9 => 8.0,
        _ => 0.0,
    };
    score += dead_penalty;

    // Lookahead coupling: reward if next item fits harmonically into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let pair_waste = post_residual - next_item_size;
        if pair_waste == 0 {
            score -= 250.0;
        } else if pair_waste <= 10 {
            score -= 80.0;
        }
        // complementary classes (small item into large bin residual)
        if item_class >= next_class {
            score -= 20.0;
        }
    } else if next_item_size > post_residual {
        // next item won't fit here anyway; slightly prefer keeping residual usable
        score += 10.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize unless it enables a tight future packing
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = open_bins_count as f64;
        // opening a new bin is bad when few bins are open; acceptable when many open
        // bins with large mean residual exist (fragmentation pressure)
        let mut nb = 150.0 + congestion * 10.0;
        if mean_residual < (bin_capacity as f64) * 0.35 {
            nb += 50.0; // existing bins are tight-ish, new bin more tempting
        } else {
            nb += 100.0;
        }
        if progress > 0.9 {
            nb += 40.0; // late stream: consolidate
        }
        score += nb;
    }

    // Mild preference for bins with residual close to item size (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 40.0;

    // Prefer using bins with lower-than-mean residual (fill fuller bins first)
    let diff = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += diff * 25.0;

    // Harmonic class bonus: pairing large item with large-residual bin
    score -= (item_class as f64) * (bin_residual as f64 / bin_capacity as f64) * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste, but residuals that can't fit the NEXT item are also risky.
    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            // Dead space relative to the lookahead item: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
        // Very small unusable gaps (below the global minimum item size 1 => none,
        // but gaps < 10 in the nominal regime are near-waste).
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 3.0;
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (2.0 + progress * 3.0);

    // Penalize bins whose residual is far from the mean (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e. when the current bin's fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.9;
        // If this bin is a last resort, opening fresh is fine.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // Early in the stream, opening bins is cheaper.
        score -= (1.0 - progress) * 20.0;
        // If the item would leave a bad gap in existing bins, prefer a new bin.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

