    }

    // Dead-space penalty: residual too small to ever be useful (min item size 1, but tiny residuals are hard to fill).
    if post_residual < 10 {
        score += 200.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 80.0;

    // Prefer bins whose residual is below the mean (consolidating fuller bins).
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res).min(50.0) * 2.0;
    } else {
        score += (res - mean_residual).min(50.0) * 1.5;
    }

    // Last-chance bonus: only this bin fits; using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Early in the stream, be more willing to open new bins for good future packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: accept only if placement in open bins would leave very bad residual.
        if next_item_size > 0 && (next_item_size as f64) > res {
            score -= 60.0 + progress * 50.0; // empty bin is fine if next item won't fit here anyway
        } else {
            score += 120.0 - progress * 60.0; // discourage opening new bins, more so early on
        }
    }

    // Mild penalty for spreading across many open bins late in the stream.
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: square the post-residual discount so near-perfect fits win hard.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Penalize dead space relative to capacity, nonlinearly.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 25.0;

    // Lookahead coupling: if the next item fits exactly in the post-residual, reward;
    // if it leaves a bad remainder, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 - (post_residual - next_item_size) as f64 * 0.15;
        } else if next_item_size <= bin_residual {
            // next item fits in bin but not after this placement: mild penalty
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // Global state: when many open bins with slack exist, discourage spreading.
    if open_bins_count > 0 {
        score += mean_residual * 0.08 * (open_bins_count as f64).ln().max(1.0);
    }

    // Time horizon: late in the stream, consolidation matters more.
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 6.0;

    // New-bin candidate handling: make an empty bin attractive only when it
    // genuinely beats poor fits (large item, big post-residual is naturally bad,
    // but give it a calibrated baseline so it competes fairly).
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
        if fitting_bins_count <= 1 {
            // No good alternative: opening fresh is fine.
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let prog_sq = progress * progress;
    let prog_cu = prog_sq * progress;
    score -= 18.0 * prn * (progress + 0.5 * prog_sq + 0.25 * prog_cu);

    // Penalize large dead space quadratically, more strongly late in stream
    score += 0.9 * prn * prn * (1.0 + 2.0 * progress);

    // Reward tight fits (small post_residual) with smooth saturating term
    score -= 12.0 * (1.0 - prn) * (1.0 - prn) * (1.0 - 0.5 * progress);

    // Lookahead: reward if next item fits the post residual (smooth decay)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = (pr - nxt).max(0.0) / cap;
        score -= 8.0 * (1.0 - fits) * (1.0 - progress * 0.5);
        // Penalize if post residual cannot fit next item
        let miss = (nxt - pr).max(0.0) / cap;
        score += 6.0 * miss * (0.5 + progress);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins
    score += 0.15 * open_bins_count as f64 * prn;

    // Deviation from mean residual: prefer bins near mean (balance)
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: make it moderately attractive only when existing fits are poor
    if bin_residual == bin_capacity {
        score += 14.0 * (1.0 - progress) - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: which "slot band" does the leftover fall in?
    // Capacity 100 -> classes of width 10 (deciles). Residuals in the same decile are
    // functionally equivalent for future items, so we add a mild class-based bonus/penalty.
    let class = post_residual / 10;
    let class_offset = (post_residual % 10) as f64;
    match class {
        0 => score -= 30.0,                       // near-perfect fit: strongly reward
        1 => score -= 12.0,                       // still very tight
        2 => score -= 4.0,                        // decent
        3 => score += 2.0,                        // mediocre
        4 => score += 6.0,                        // wasteful
        _ => score += 10.0,                       // half-empty bin left behind
    }
    // Fine-grain tiebreak within a decile: prefer rounder (harmonic) leftovers
    // that many item sizes can land in (multiples of 5 and 10).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    } else if post_residual % 5 == 0 {
        score -= 2.5;
    }
    score += class_offset * 0.05;

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this placement is golden. If next item can't fit, penalize proportionally.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 + 0.1 * (next_item_size as f64);
        } else {
            // next item won't fit here: penalize leftover dead space more
            score += 0.15 * (post_residual as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: opening a new bin should only win when no good fit exists.
    if bin_residual == bin_capacity {
        // base cost of opening a bin; relax late in the stream when many bins are open
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut open_cost = 45.0 - 10.0 * progress;
        if open_bins_count as f64 > mean_residual.max(1.0) {
            open_cost += 5.0;
        }
        // if item would leave a terrible residual in any existing bin, new bin is fine
        if post_residual == 0 {
            score -= 20.0; // exact fit in fresh bin (item == capacity edge)
        }
        score += open_cost;
    }

    // Prefer bins that are already well-filled (small residual relative to mean):
    // concentrate waste into few bins.
    score += 0.3 * ((bin_residual as f64) - mean_residual).max(-20.0).min(20.0);

    // Slight preference for using more-open bins when many are open (bin-count pressure).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 6.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 4 {
        score -= 10.0;
    }

    // Dead space is worse if no future item can use it: check lookahead fit.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += (next_item_size - post_residual) as f64 * 0.8;
    } else if next_item_size > 0 && next_item_size > 0 && next_item_size <= post_residual && post_residual - next_item_size < 12 {
        score -= 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing ones.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 5.0;
    if bin_residual < bin_capacity {
        score -= pressure;
    } else {
        // New-bin candidate: only attractive when few bins open or mean residual is low.
        score -= pressure * 0.5;
        score += (mean_residual / bin_capacity as f64) * 10.0;
        if fitting_bins_count > 0 {
            score += 15.0; // discourage abandoning bins that already fit
        }
    }

    // Mild preference for bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual - item_size) as f64;
    score += tightness * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: exact fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward bins whose post_residual exactly
    // matches the next item, or can pair with it tightly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Two-item chain fit: penalize leftover after the hypothetical pair.
            let pair_left = post_residual - next_item_size;
            score -= 120.0 - (pair_left as f64).min(120.0);
            score += pair_left as f64 * 0.8;
        } else {
            // Next item cannot follow: dead space penalty scaled by gap size.
            let gap = next_item_size - post_residual;
            score += gap as f64 * 0.6;
        }
    }

    // Tightness relative to mean residual: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Penalize opening a brand-new bin unless the current fit is bad.
    if bin_residual == bin_capacity {
        // New bin starts with full residual; make it unattractive unless the
        // item leaves a large useful chunk and no open bin fits well.
        score += 250.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0;
        }
    }

    // Small bonus for consolidating when many bins are open.
    score -= (open_bins_count as f64).ln() * 2.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness * tightness;

    // Penalize post_residual that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space penalty
    } else if post_residual >= 10 && post_residual < 25 {
        score += 6.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly or well, reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 10.0 * (1.0 - slack as f64 / bin_capacity as f64);
            if slack == 0 {
                score -= 15.0; // perfect pairing bonus
            }
        } else {
            score += 4.0; // next item cannot follow here
        }
    } else {
        // Last item: just minimize residual.
        score -= 5.0 * tightness;
    }

    // Last-chance bin: if this is the only fitting bin, heavily favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.5 * item_size as f64;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current bins fit poorly and many items remain.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened late in the stream.
        score += 30.0 - 10.0 * progress;
        if fitting_bins_count >= 1 {
            score += 15.0; // extra penalty when existing bins could fit
        }
        // If item is large and would leave a small residual in any bin, new bin is fine.
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 20.0;
        }
    } else {
        // Reward filling existing bins more when many bins are open.
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * tightness;
    }

    // Global state: penalize bins whose residual deviates wildly from the mean
    // (keeps residual distribution homogeneous for future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild time-decay: prefer tight fits more strongly as the stream progresses.
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear penalty for small-but-unusable residuals (dead space), smoothed.
    let dead_zone = (1.0 - norm_pr).powi(3) * (norm_pr * (1.0 - norm_pr)).sqrt().max(0.0);
    score += 12.0 * dead_zone;

    // Reward tight fits with smooth quadratic coupling of item size and residual.
    let fit_quality = 1.0 - (item_size as f64 / bin_residual as f64).powi(2).min(1.0);
    score -= 8.0 * fit_quality * (1.0 + progress);

    // Lookahead: penalize if next item fits poorly into the post-residual.
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).abs();
        let lookahead_fit = (next_item_size as f64 / pr.max(1.0)).min(1.0);
        score += 0.35 * gap * (1.0 - lookahead_fit) * (1.0 - progress);
        score -= 6.0 * lookahead_fit * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: mild penalty early, discount late when open bins are fragmented.
    let fragmentation = (open_bins_count as f64 / (mean_residual / cap + 1.0)).ln().max(0.0);
    if bin_residual == bin_capacity {
        score += 15.0 - 20.0 * progress + 3.0 * fragmentation;
    } else {
        // Favor bins with residuals close to the mean (balance open bins).
        score += 0.5 * (pr - mean_residual).abs() / cap;
    }

    // Mild reward for consolidating into bins that are already partly filled.
    score -= 4.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: quantize post_residual into capacity-fraction bands.
    // Residuals that form "useful" classes (small enough to likely be filled
    // by future items, i.e. <= 40) are favored; large dead space penalized.
    let cap_frac = post_residual as f64 / bin_capacity as f64;
    if cap_frac <= 0.10 {
        score -= 120.0; // near-perfect class
    } else if cap_frac <= 0.25 {
        score -= 60.0;  // quarter-class: very fillable
    } else if cap_frac <= 0.40 {
        score -= 20.0;  // still fillable by typical items
    } else if cap_frac <= 0.60 {
        score += 15.0;  // awkward middle class
    } else {
        score += 40.0;  // large dead space, bin nearly wasted
    }

    // Modulo structure on post_residual: divisible-by-10 residuals align with
    // common item sizes (multiples of 10), making them more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 25.0;
    }
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 8.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 35.0 + 0.3 * (next_item_size as f64);
        } else if post_residual > 0 {
            // dead space that next item cannot use
            score += 0.5 * (next_item_size as f64 - post_residual as f64).min(60.0);
        }
        // If post_residual is exactly next_item_size, chain fit is ideal
        if next_item_size == post_residual {
            score -= 50.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Avoid scattering across many open bins when a tight fit exists elsewhere:
    // prefer bins with residual close to item_size (tight packing).
    let tightness = (bin_residual - item_size) as f64;
    score += 0.2 * tightness;

    // Slight preference for consolidating into fewer bins early in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Mean-residual alignment: bins far from the mean residual are either
    // outliers; mildly favor bins near the mean to keep residual profile balanced.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // New-bin candidate: only attractive when no open bin fits well
    // (large item relative to mean residual) or stream is early.
    if bin_residual == bin_capacity {
        let must_open = fitting_bins_count == 0
            || (item_size as f64 > mean_residual + 15.0);
        if must_open {
            score -= 200.0;
        } else {
            score += 150.0; // discourage opening when decent fits exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item (<= 12) are essentially unusable -> heavy penalty.
    if post_residual < 12 {
        score += 60.0;
    } else if post_residual < 20 {
        // "Awkward gap" band: quadratic penalty peaking just below 20.
        score += 0.25 * (20 - post_residual) as f64 * (20 - post_residual) as f64;
    }

    // Reward near-perfect fits superlinearly.
    if post_residual == 0 {
        score -= 45.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // strongly reward; if post_residual can't fit next item but is small, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins rather than spreading; new empty bin gets penalized progressively.
    if bin_residual == bin_capacity {
        score += 25.0 + 4.0 * open_bins_count as f64;
        // Early in stream, opening bins is cheaper; late in stream, consolidate.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    } else {
        // Favor bins whose residual is below the mean (tighter bins first),
        // gently, to keep mean residual high for future items.
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Mild global preference for using existing bins as stream progresses.
    score += 0.05 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor small post_residual
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * tightness * tightness;

    // 2-step lookahead: reward if next item fits into post_residual (perfect chaining)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // next item cannot chain here; penalize proportionally to leftover gap
            let gap = (next_item_size - post_residual) as f64;
            score += 3.0 * gap / bin_capacity as f64;
        }
    }

    // Relative to mean residual: prefer bins already below-average residual (denser bins)
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate penalty: opening a new bin is costly unless current bin fit is terrible
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > mean_residual.max(1.0);
        score += if poor_fit { -2.0 } else { 12.0 };
        // slightly discourage new bins early in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 4.0 * (1.0 - progress);
    }

    // Mild pressure to consolidate when many bins are open
    score -= 0.1 * open_bins_count as f64 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on post_residual
    score += (post_residual as f64 / cap) * (post_residual as f64 / cap) * 30.0;

    // Perfect fit gets a big bonus
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 60.0;
    }

    // Penalize bins with large residual wasting a good fit opportunity
    let residual_frac = bin_residual as f64 / cap;
    score -= residual_frac * residual_frac * 10.0;

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            score -= 25.0 + 20.0 * (nxt / cap);
        } else {
            // next item won't fit here; penalize leaving awkward gap
            score += 8.0 * (nxt / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Time horizon: early in stream, be more selective (penalize mediocre fits);
    // late in stream, close out bins aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 15.0;

    // Global state: many open bins -> prefer filling existing ones over opening new
    score += (open_bins_count as f64) * 1.5;

    // Mean residual coupling: if this bin's residual is below mean, it's a good filler
    let mean_res = mean_residual;
    if (bin_residual as f64) < mean_res {
        score += 5.0;
    } else {
        score -= 3.0 * ((bin_residual as f64 - mean_res) / cap);
    }

    // New-bin candidate: make opening a new bin costly unless current fits are terrible
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64) * 2.0;
        // but if item is huge relative to typical residuals, new bin is fine
        if (item_size as f64) > mean_res * 1.2 && fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling: post_residual normalized, polynomial shaping
    let x = pr / cap; // in [0,1]
    // Reward tight fits: quadratic + cubic shaping of residual
    score += 40.0 * x * x * (1.0 + 0.5 * x) - 20.0 * x * x * x;

    // Stream progress interaction: later in stream, penalize wasted residual more (smooth)
    let prog_term = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += (1.0 - prog_term) * 15.0 * x * x;

    // Dead-space penalty if post_residual too small for typical items (smooth logistic-ish)
    let nr = next_item_size as f64;
    if nr > 0.0 {
        let gap = (nr - pr).max(0.0) / cap;
        let lookahead_penalty = (gap * 6.0).tanh() * 25.0;
        // But reward if post_residual exactly near next item (perfect chaining)
        let chain_bonus = (-((pr - nr).powi(2)) / (0.005 * cap * cap)).exp() * 12.0;
        score += lookahead_penalty - chain_bonus;
    }

    // Last-chance bin: strong reward to use it (avoid opening new bin)
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        // Crowding: many fitting bins -> mild penalty for using scarce-capacity bins
        score += (fitting_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Mean residual coupling: penalize bins far from mean residual (smooth deviation)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Penalize opening new bins when many open bins exist and bin is empty candidate
    if bin_residual == bin_capacity {
        score += 25.0 + 5.0 * (open_bins_count as f64).sqrt() - 20.0 * progress;
    }

    // Small fill bonus: reward larger item_size relative to bin (dense packing)
    score -= 10.0 * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo-10 classes matter since
    // items are integers in 1..=100; small post-residuals in "nice" classes
    // are more likely to be filled by future items.
    let pr = post_residual;
    let class = pr % 10;
    let half = (bin_capacity / 2) as f64;

    // Reward small, "harmonically friendly" residuals (multiples of 5 or 10).
    if pr == 0 {
        score -= 60.0; // perfect fit: extremely desirable
    } else if class == 0 {
        score -= 18.0;
    } else if class == 5 {
        score -= 10.0;
    } else if pr <= 10 {
        score -= 6.0;
    } else if pr > 50 {
        // large dead space is a mild penalty beyond its raw size
        score += (pr as f64 - 50.0) * 0.25;
    }

    // Coupling with the lookahead item: if the next item can exactly fill
    // the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if pr >= next_item_size && (pr - next_item_size) % 10 == 0 {
            score -= 12.0;
        } else if next_item_size > pr {
            // next item won't fit here; residual likely becomes dead space
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity (large items start fresh bins well).
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        score = half + (0.5 - frac) * 40.0;
        if next_item_size > 0 && next_item_size <= pr - item_size {
            score -= 10.0; // room for lookahead too
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Mild stream-progression pressure: late in the stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item (>=1) can use well.
    // A residual below 10 is nearly guaranteed dead space; penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Gaps that cannot fit the lookahead item are risky if lookahead is significant.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0 + (next_item_size - post_residual) as f64 * 0.3;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }
    // Reward filling a bin substantially (tight packing).
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 12.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading into new bins;
    // when few bins are open, opening a new bin is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline competitive score, penalized by open-bin pressure.
        score = bin_capacity as f64 * 0.5 + pressure * 6.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // a fresh bin always fits the next item
        }
    } else {
        // Existing bins get a mild bonus for being reused as pressure grows.
        score -= pressure * 1.5;
    }

    // Slight preference for bins below mean residual (keeps residual distribution even).
    score += (post_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

