        score -= 25.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // perfect match bonus
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // if next item cannot fit anywhere else after this placement, penalize waste
        if post_residual < next_item_size {
