    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer fuller bins relative to mean residual
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Opening a new bin: penalize unless it enables a tight future fit
    if bin_residual == bin_capacity {
        score += 45.0;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 20.0; // pair next item with current in fresh bin
        }
        if progress > 0.8 {
            score -= 15.0; // late stream: fresh bin fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post_residual.
    score -= 0.35 * ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(3) * bin_capacity as f64;

    // Perfect fill gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: reward if next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // partial credit scaled by how well it fits
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot fit: post residual becomes dead space
            score += 0.5 * post_residual as f64;
        }
    } else {
        // Last item: strongly prefer filling existing bins as tightly as possible.
        score -= 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize bins whose residual is far below the mean (fragmented bins).
    let resid_f = bin_residual as f64;
    let dev = resid_f - mean_residual;
    score += 0.08 * dev.abs();

    // Favor using bins that are already quite full (keep emptier bins flexible).
    let fullness = 1.0 - resid_f / bin_capacity as f64;
    score -= 10.0 * fullness;

    // New-bin candidate handling: make it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; increases as stream progresses.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = bin_capacity as f64 - 25.0 + 15.0 * progress;

        // If next item is large, opening fresh space is more valuable.
        if next_item_size > 60 {
            score -= 10.0;
        }
        // If many bins are open, prefer consolidating into them instead.
        score += 2.0 * (open_bins_count as f64).sqrt();
        // If the mean residual comfortably fits the item, penalize opening a new bin.
        if mean_residual >= item_size as f64 {
            score += 20.0;
        }
    }

    // Late in the stream, close out bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * fullness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let norm_post = post_residual as f64 / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Smooth non-linear coupling: post_residual penalized more heavily as stream progresses
    let progress_coupling = progress * norm_post * norm_post;
    score += 4.0 * progress_coupling;

    // Quadratic interaction between item size and remaining space (favor tight fits)
    let tightness = (1.0 - norm_post).max(0.0);
    score -= 3.0 * tightness * tightness * (0.5 + progress);

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && norm_post >= norm_next {
        score -= 2.5 * (1.0 - (norm_post - norm_next)) * (1.0 - progress);
    }

    // Penalize creating residual that no plausible item can use
    if post_residual > 0 && post_residual < 10 {
        score += 6.0 * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // Mean residual coupling: prefer bins deviating favorably from the mean
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 1.5 * dev * (0.5 + progress);

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64 * norm_post;

    // New-bin candidate: penalize opening a new bin, more so early on
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: quantize post_residual into capacity-fraction bands
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Penalize residual classes that are "dead" (too small to hold typical items)
    // Class boundaries at 1/8 capacity fractions via integer division
    let class = post_residual / (bin_capacity / 8).max(1);
    score += match class {
        0 => -6.0,                 // near-perfect fit
        1 => -2.0,                 // small but usable
        2 => 0.0,
        3 => 1.5,
        4 => 2.0,                  // ~half-full residual: mediocre
        _ => -0.5,                 // large residual: fine for future
    };

    // Nonlinear dead-space penalty: residual too small for next item is wasted
    if next_item_size > 0 && post_residual < next_item_size {
        score += 4.0 + 0.05 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can chain the next item exactly
        let chain = post_residual - next_item_size;
        if chain <= 5 { score -= 5.0; }
        else { score -= 1.0; }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap;
        score = cap as f64 * 0.6 + 10.0 * (1.0 - crowding);
        if open_bins_count == 0 { score -= 15.0; }
    }

    // Mild preference to pack into emptier-than-average bins early, tighter bins late
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (bin_residual as f64 - mean_residual) * 0.05;

    // Modulo coupling: reward residuals in multiples of common item sizes
    if post_residual % 10 == 0 { score -= 1.0; }
    if post_residual % 25 == 0 { score -= 0.5; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the minimum item are worthless.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fit, ideal
    } else if post_residual <= 12 {
