        score += 60.0 + (12 - post_residual) as f64 * 8.0;
    } else if post_residual <= 25 {
        // moderate dead zone
        score += 15.0;
    }

    // Reward tight fits (small but usable remainder)
    let tightness = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= tightness * 20.0;

    // Last chance: if this is the only bin that fits, strongly prefer it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded or fit would be terrible
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // baseline cost of opening a bin, modulated by pressure
        score += 30.0 + (open_bins_count as f64).sqrt() * 4.0;
        // if the current bin's post-fit residual is a bad sliver, new bin becomes attractive
        if post_residual > 0 && post_residual <= 12 && bin_residual != bin_capacity {
            score -= 70.0;
        }
    } else {
        // pressure: with many open bins, prefer filling existing ones harder
        score -= (open_bins_count as f64).ln().max(0.0) * 3.0;
    }

    // Lookahead: if next item fits in post_residual, bonus; if next item is large and
    // post_residual can't hold it, mild penalty for wasting space
    if next_item_size > 0 {
        if (post_residual as i64 - next_item_size as i64) == 0 {
            score -= 50.0; // perfect chain fit
        } else if next_item_size as f64 <= post_residual as f64 {
            score -= 10.0;
        } else if next_item_size as f64 > post_residual as f64 && post_residual > 0 {
            score += 5.0;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (more filled) early on
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let dev = post_residual as f64 - mean_residual;
    score += dev * (0.1 + 0.2 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
