    }

    // Penalize the brand-new empty bin candidate moderately; allow it when
    // open bins fit poorly (large post_residual relative to capacity)
    if bin_residual == bin_capacity {
        score += 0.35 + 0.25 * progress;
        score -= (post / cap) * 0.0; // no-op to keep structure
        // If existing bins are very fragmented, opening new bin is less bad
        score -= (mean_residual / cap).powi(2) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 0.5;
    }

    // Mild preference to fill bins that deviate from mean residual (consolidation)
    score += ((res - mean_residual) / cap).abs() * 0.1;

    // Small penalty scaling with number of open bins to encourage consolidation
    score += (open_bins_count as f64).ln().max(0.0) * 0.02 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fill classes are gold
    let post = post_residual;
    if post == 0 {
        score -= 200.0; // perfect fill
    } else if post <= 5 {
        score -= 100.0;
    } else if post % 10 == 0 {
        score -= 40.0; // decadal residual is reusable
    }

    // Modulo coupling: post_residual and next_item_size in same residue class
    if next_item_size > 0 && post > 0 {
        let nxt = next_item_size;
        if nxt <= post {
            // lookahead fits: reward, stronger if residue classes align
            score -= 30.0;
            if post % nxt == 0 {
                score -= 25.0;
            } else if post % 10 == nxt % 10 {
                score -= 10.0;
            }
        } else {
            // lookahead cannot use this residual: penalize small dead space
            score += (nxt - post) as f64 * 0.5;
            if post < 10 {
                score += 20.0; // tiny unusable residue
            }
        }
    }

    // Integer-division threshold on residual fraction
    let frac = post as f64 / bin_capacity as f64;
    let class = (frac * 4.0).floor() as i32; // quarters of capacity
    score -= match class {
        0 => 15.0,
        1 => 5.0,
        2 => 0.0,
        _ => -5.0,
    } as f64;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when open bins are nearly full
    if bin_residual == bin_capacity {
        let base = 40.0 + (post_residual as f64);
        if mean_residual < 20.0 {
            score = base - 30.0; // open bins nearly exhausted -> open new bin
        } else {
            score = base + 50.0; // keep filling existing bins
        }
    }

    // Late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post as f64).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for typical
    // future items (likely unusable) are heavily penalized.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) > 0.0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward tight fits strongly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * tightness * 20.0;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing
    // ones rather than spreading; penalize placements that leave a bin
    // nearly empty of use while many bins are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += (post_residual as f64 / bin_capacity as f64) * pressure * 0.5;

    // Last-chance bin: strongly favor using the only bin that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits
    // well (large post_residual relative to capacity) or when open-bin
    // count is low and mean residual is small.
    if bin_residual == bin_capacity {
        let bad_fit = (bin_residual as f64 - item_size as f64) / (bin_capacity as f64);
        let open_benefit = if mean_residual < item_size as f64 { 40.0 } else { 0.0 };
        let few_bins = if open_bins_count <= 2 { 25.0 } else { 0.0 };
        let lookahead_need = if next_item_size > 0 && next_item_size as f64 > (bin_residual as f64 - item_size as f64) { 10.0 } else { 0.0 };
        score = bad_fit * 100.0 - open_benefit - few_bins - lookahead_need;
        // Never open a new bin when a decent fit exists elsewhere.
        if (bin_residual as f64 - item_size as f64) < dead_threshold && open_bins_count > 0 {
            score += 200.0;
        }
    }

    // Lookahead: if the next item would fit the post residual, reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += (next_item_size as f64 - post_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits strongly (post_residual near zero).
    score -= 30.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(3);

    // 2-step lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        if slack == 0.0 {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // post_residual cannot host next item: penalize dead space, worse if small residual.
        score += 10.0 + 0.3 * (bin_capacity as f64 - post_residual as f64) * (1.0 - progress);
    }

    // Compare against mean residual: prefer bins already below-average residual
    // (concentrate packing), but keep above-average bins open for big items.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    // or no real benefit from squeezing into open bins.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        let squeeze_penalty = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score += 15.0 - 20.0 * tightness + 25.0 * squeeze_penalty + 5.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    }

    // Slight bias early in stream to keep bins open (more future flexibility).
    score += 3.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward if next item can fit in the post-residual (chaining),
    // penalize if next item is slightly too big (near-miss dead space).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
        } else if next_item_size <= post_residual + 8 && post_residual > 0 {
            score += 5.0;
        }
    }

    // Penalize bins whose residual is far from mean (fragmentation shaping).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or open-bin population is small.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 25.0 * pressure
            + 10.0 * (1.0 - progress)
            + 0.5 * open_bins_count as f64;
        // A new bin is fine if the item is large (little waste risk).
        if item_size >= bin_capacity * 3 / 4 {
            score -= 20.0;
        }
    }

    // Prefer filling more-opened bins first: mild penalty scaled by bin residual
    // for bins that are still very full (keep them for smaller future items).
    if post_residual > bin_capacity / 2 && bin_residual < bin_capacity {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: waste measured by squared post-residual (non-linear dead space penalty)
    let mut score = norm_pr * norm_pr * cap;

    // Smooth coupling: large residuals hurt more later in the stream
    score += 20.0 * norm_pr * (progress * progress);

    // Reward tight fits: subtract for small post_residual
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: reward if next item fits in post_residual
    if next_item_size > 0 && next_item_size as f64 <= pr {
        score -= 8.0 * (1.0 - (next_item_size as f64 / pr).min(1.0));
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Smooth mean-residual coupling: prefer bins below mean residual (tighter bins)
    score += 3.0 * (mean_residual / cap - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residual buckets by capacity fraction.
    let post = post_residual as f64;
    let frac = post / cap;
    let class = (post as u32 / 10) as f64; // integer-division threshold class (0..10)

    // Reward tight fits: small post_residual gets strong subtraction.
    if post_residual == 0 {
        score -= 500.0; // perfect fill
    } else {
        score -= 40.0 / frac.max(0.05); // harmonic reward shrinking with residual
    }

    // Dead-space penalty: residuals too small for the smallest plausible item (<=10)
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    }

    // Modulo-arithmetic coupling: residuals divisible into nice chunks are reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 10.0;
    }

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            score -= 30.0 * (next_item_size as f64 / post.max(1.0));
        } else {
            // next item won't fit here: penalize large leftover classes mildly
            score += 0.3 * class;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin should only win when current
    // fits are poor (many open bins with slack, or item is large and fits badly).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = frac < 0.25 && post_residual > 0; // current best fit leaves <25% usable? (we're the new bin: frac==1)
        let _ = poor_fit;
        // Base cost of a new bin, discounted when item is large (fills it well)
        // and early in the stream when consolidation options are low.
        score = 150.0 - 0.5 * item_size as f64 - 20.0 * progress;
        if open_bins_count == 0 {
            score -= 200.0; // must open
        }
        if item_size >= 60 {
            score -= 40.0; // big item: fresh bin is attractive
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 25.0; // next item can pair in the fresh bin
        }
        // discourage hoarding many open bins
        score += 5.0 * open_bins_count as f64;
    } else {
        // Mild preference to balance load across bins: favor bins with residual
        // near the mean residual (keeps classes uniform).
        score += 0.2 * (bin_residual as f64 - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are pure waste.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable sliver: heavy penalty scaled by how close to zero.
            score += (10 - post_residual) as f64 * 25.0;
        } else if post_residual <= 20 {
            // Marginal gap: only useful for tiny items; moderate penalty.
            score += (20 - post_residual) as f64 * 4.0;
        } else {
            // Usable residual: reward larger remaining space mildly.
            score -= (post_residual as f64 - 20.0) * 0.15;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits (small post_residual relative to capacity) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 30.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins is penalized implicitly.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure from open bins.
        score = bin_capacity as f64 * 0.5 + open_pressure * 3.0;
        // If the next item would fit the residual created here, soften cost.
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
            score -= 15.0;
        }
    } else {
        // Existing bin: reward grows with number of open bins (consolidation).
        score -= open_pressure * 1.5;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        score -= 5.0;
    }

    // Early in the stream, be slightly more willing to fill existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0;

    // Slight preference for bins below mean residual (balance residuals).
    if bin_residual != bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact or near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item fits after this placement: reward proportional to closeness.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize wasted space that blocks the lookahead.
            score += 0.5 * gap;
        }
    }

    // Compare post_residual against mean residual: avoid creating outliers.
    let dev = post_residual as f64 - mean_residual;
    score += 0.2 * dev.abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Prefer denser bins (less residual before placement).
    score += 0.1 * (bin_residual as f64 - item_size as f64);

    // Mild penalty for opening a new bin when many bins are already open.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * open_bins_count as f64;
        // But if no open bin fits well, new bin is fine.
        if post_residual as f64 > 0.5 * bin_capacity as f64 {
            score -= 15.0;
        }
    }

    // Early in stream: be more willing to open bins; late: consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize progress through the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: fraction of bin filled by this item
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill;

    // Penalize large dead space non-linearly (waste grows superlinearly)
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste * waste;

    // Lookahead coupling: if the next item fits in the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if next item exactly matches residual (perfect chaining)
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // Penalize creating residual too small for a likely future item
        let gap = (next_item_size as f64 - post_residual as f64).max(0.0);
        score += 0.15 * gap;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer the fullest (smallest residual relative to mean)
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    // Time horizon: early on, prefer spreading across bins (keep flexibility);
    // late in the stream, consolidate into existing bins to avoid opening new ones.
    if progress < 0.3 {
        score += 8.0 * (1.0 - progress / 0.3) * (bin_residual as f64 / bin_capacity as f64 - 0.5).abs();
    } else {
        score -= 10.0 * progress;
    }

    // Penalize opening a new bin when open bins can already fit the item,
    // unless the item is large and would leave a very tight fit elsewhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let best_existing_waste = if fitting_bins_count > 0 {
            (bin_residual as f64 - item_size as f64).max(0.0)
        } else {
            bin_capacity as f64
        };
        score += 15.0; // base cost of opening a new bin
        // But if the item is huge, a fresh bin is often fine
        if item_size >= 60 {
            score -= 10.0;
        }
        // If many bins fit the item, discourage new bin more strongly
        score += 2.0 * fitting_bins_count as f64;
        // Late in stream, new bins are expensive
        score += 10.0 * progress;
        // If mean residual is high, existing bins have room; discourage new bin
        score += 0.1 * mean_residual;
    } else {
        // Prefer bins with residual closest to the item (best fit flavor)
        let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score += 5.0 * tightness;
        // Slight bonus for using bins with low mean residual spread
        score -= 0.05 * (bin_capacity as f64 - mean_residual);
    }

    // Mild preference to keep the count of open bins from exploding
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    // Non-linear polynomial coupling of post_residual with progress
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    // Progress-weighted penalty on residual: later in stream, dead space costs more
    let progress_penalty = norm_pr * norm_pr * (0.5 + 1.5 * progress) * cap * 0.5;
    score += progress_penalty;
    // Reward if the next item exactly fills the post residual (smooth coupling)
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        let fit_bonus = (-diff / cap * 6.0).exp() * (10.0 + 20.0 * progress);
        score -= fit_bonus;
    }
    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * tightness * 8.0;
    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 25.0 * progress;
    }
    // Slight penalty for spreading across many open bins late in the stream
    score += (open_bins_count as f64).sqrt() * (1.0 + progress) * 0.5;
    // Mild pull toward bins with residuals near mean (keeps bin states homogeneous)
    score += ((pr - mean_residual).abs() / cap) * 4.0 * (1.0 - progress);
    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score -= 6.0;
        // penalize opening new bins early
        score += 20.0 * (1.0 - progress);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "useful" is the leftover space?
    // Class 0: post_residual == 0 (perfect fit) -> strong reward
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Fraction of capacity wasted
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += waste_frac * waste_frac * 40.0;

        // Harmonic classes via integer division: residuals in (0,10] are dead space
        // (smallest item is >= 10 in classic setting; unknown dist here, use small threshold)
        let dead_threshold = 10u32;
        if post_residual < dead_threshold {
            score += 50.0; // unusable dead space penalty
        } else if post_residual <= bin_capacity / 4 {
            score += 15.0; // small leftover, hard to fill
        } else if post_residual <= bin_capacity / 2 {
            score += 5.0;
        }

        // Modulo logic: residual divisible by common item sizes (10, 20, 25, 50)
        // is more likely to be exactly filled later -> reward
        let pr = post_residual;
        if pr % 10 == 0 || pr % 25 == 0 {
            score -= 8.0;
        }
        if pr % 50 == 0 {
            score -= 6.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size < post_residual {
            // next item fits, but measure how tightly
            let after_next = post_residual - next_item_size;
            score -= 20.0 - (after_next as f64) * 0.3;
            // harmonic class of the double-fill leftover
            if after_next == 0 {
                score -= 30.0;
            } else if after_next % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot use this bin's leftover; slight penalty
            score += 10.0;
            // but if next item is small it may still fit smaller leftovers
            if next_item_size <= 20 && post_residual >= 20 {
                score -= 6.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: neutral-ish baseline, penalize opening new bins unless
    // the current fit is terrible or many bins are open with slack
    if bin_residual == bin_capacity {
        let baseline = 25.0 + mean_residual * 0.15 + (open_bins_count as f64) * 1.5;
        score = score.max(baseline);
        // early stream: opening bins is fine; late stream: consolidate
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Prefer fuller bins overall: tie-break toward bins below mean residual (tighter)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // Mild stream-phase coupling: late in stream, reward tight fits more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 0.0 + progress * (post_residual == 0) as i32 as f64 * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space below minimum item size
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill is excellent
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else if post_residual > 0 {
            score += 8.0; // gap likely wasted for the known future item
        }
    }

    // Last-chance bonus: this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: be picky, prefer tight fits elsewhere.
        score += 4.0 * (fitting_bins_count as f64 - 2.0).min(6.0);
    }

    // Open-bin pressure: discourage proliferation of bins; reuse keeps count low.
    score += 3.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; reduced when the item is large (little choice)
        // or when existing residuals are all poor fits.
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 25.0;
        let poor_alternatives = if fitting_bins_count == 0 { 40.0 } else { 0.0 };
        score += 55.0 - large_item_bonus - poor_alternatives;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // fresh bin can also take the next item
        }
    }

    // Slight drift: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual alignment: prefer bins close to the mean residual (balanced packing).
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near-exact match with next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if gap == 0 {
            // Perfect: this bin can host the next item exactly.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits here; reward tightness of the pair.
            let tightness = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= 40.0 * (1.0 - tightness);
        } else {
            // Next item won't fit after this placement; penalize leftover that
            // is likely dead space relative to the lookahead.
            score += 0.35 * (post_residual as f64 - (next_item_size as f64 - post_residual as f64).max(0.0));
        }
        // Small extra penalty if post_residual is a tiny unusable sliver.
        if post_residual > 0 && post_residual < 10 {
            score += 8.0;
        }
    }

    // Relative-to-mean coupling: bins with residual below mean are "tighter"
    // and generally preferable targets (they hold more packed content).
    let dev = mean_residual - post_residual as f64;
    score -= 0.25 * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Late in the stream, favor consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (open_bins_count as f64).ln().max(1.0) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make an empty bin attractive only when it offers a
    // genuinely better 2-step future than any open bin.
    if bin_residual == bin_capacity {
        score = 0.55 * bin_capacity as f64
            - 25.0 * (next_item_size as f64 / bin_capacity as f64)
            + 4.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize (subtract) when post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize leaving dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable sliver
    } else if post_residual >= 10 {
        // residual usable by future items: mild reward scaled by how well it matches mean residual
        let usable = (post_residual as f64 - mean_residual).abs();
        score -= 4.0 * (1.0 - usable / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty for wasting space next item could use in another bin
            score += 3.0;
        }
    }

    // Prefer filling bins with larger residual when many bins are open (consolidation).
    score -= 0.15 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    // Time horizon: early in stream, be pickier about tight fits (more future items to place);
    // late in stream, just minimize bin count now.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.25 * progress;

    // New-bin candidate: make it moderately attractive only when current fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        let waste = post_residual as f64 / bin_capacity as f64; // = 1.0 for empty bin, item fully fills nothing
        let _ = waste;
        // Base cost of opening a new bin, discounted if no good alternative exists.
        score += 15.0 - 20.0 * poor_fit;
        // Late in stream with few items left, prefer new bin to keep bins clean? No: reuse existing.
        score += 5.0 * (1.0 - progress);
    }

    // Slight preference for bins whose residual deviates from mean (steer distribution of residuals).
    score += 0.5 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * (1.0 - pr_norm);
    score -= 40.0 * poly * (0.5 + progress);

    // Penalize large post-residual as stream progresses (dead space late = wasted)
    score += pr_norm * pr_norm * cap * (0.2 + 0.6 * progress);

    // Reward tight fits (small post residual) with smooth decay
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * item_size as f64 * 0.5;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 * (1.0 - pr_norm);
    }

    // New-bin candidate: penalize opening a new bin unless it's early or item is huge
    if bin_residual == bin_capacity {
        let early_bonus = (1.0 - progress) * 20.0;
        let big_item = (item_size as f64 / cap).powi(2) * 30.0;
        score += 25.0 - early_bonus - big_item;
    }

    // Lookahead: if next item fits into post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 15.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 8.0 * (next_item_size as f64 / cap);
    }

    // Mild penalty for bin proliferation
    score += open_bins_count as f64 * 0.5 * progress;

    // Coupling with mean residual: prefer bins deviating from mean in useful way
    score -= 0.3 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 classes group residuals into
    // "reusable bands". Residuals that are multiples of 10 are prime targets
    // for future items (which are often multiples of 10 in many streams).
    let pr_mod = post_residual % 10;
    if pr_mod == 0 {
        score -= 12.0; // perfectly aligned residual: strongly favored
    } else if pr_mod <= 2 {
        score += 6.0;  // dead sliver: nearly unusable
    } else if pr_mod >= 8 {
        score -= 3.0;  // close to an aligned band
    }

    // Integer-division thresholds: residual in [next, next+10) can host the
    // lookahead item exactly within one harmonic band.
    if next_item_size > 0 {
        let q = post_residual / next_item_size.max(1);
        if q >= 2 {
            score -= 8.0; // bin can host the next item AND more
        } else if q == 1 {
            score -= 4.0; // exact next-item fit possible
        } else {
            score += 5.0; // next item won't fit here: dead-ish space
        }
        // Reward when post_residual lands exactly on next_item_size
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else {
        // Last item: just minimize waste, prefer tightest fit
        score += (bin_capacity as f64 - post_residual as f64) * 0.001;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible (large post_residual).
    if fitting_bins_count == 1 {
        score -= 10.0;
        if post_residual > bin_capacity / 2 {
            score += 8.0; // but a half-empty result is still bad
        }
    }

    // New-bin candidate handling: an empty bin has post_residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing residuals are
        // fragmented (mean residual small) or the item is large.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64
            - 5.0 * (item_size as f64 / bin_capacity as f64)
            - 4.0 * (1.0 - mean_residual / bin_capacity as f64)
            - 2.0 * progress;
        // Penalize opening new bins when plenty of bins already fit the item
        if fitting_bins_count >= 2 {
            score += 10.0;
        }
    }

    // Mild preference for filling bins more fully overall (coupling with mean).
    score -= 0.02 * (bin_capacity as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Favor bins whose residual is close to the item (tight fit).
    score += 0.3 * (bin_residual as f64 - item_size as f64).abs();

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    score += 0.8 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins deviating from mean residual toward tighter states.
    score += 0.2 * (bin_residual as f64 - mean_residual).abs();

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln() + 1.0;
        score = bin_capacity as f64 + 10.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 0.1 * next_item_size as f64;
        }
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if next item nearly fits but leaves a sliver.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 15 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Aggressive 2-step lookahead: strongly reward when the next item fits
    // exactly into the post residual (perfect 2-item packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize proportionally to overflow
            let over = (next_item_size - post_residual) as f64;
            score += 15.0 * (over / bin_capacity as f64);
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are scarce
    // capacity; penalize wasting them on loose fits.
    let rel = post_residual as f64 - mean_residual;
    score += 0.3 * rel;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer consolidating into fewer bins early on.
    score += 2.0 * open_bins_count as f64;

    // Dead-space penalty for tiny unusable residuals (but not zero).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect closure is excellent.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 60.0;
    }

    // Lookahead: reward residuals that can host the next item, penalize
    // residuals that are just below the next item (dead space trap).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 40.0 + 0.5 * (post_residual - next_item_size) as f64;
        } else if post_residual > 0 {
            // Dead space that cannot fit the next item.
            score += 0.8 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise the item forces a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: it's only attractive when nothing else fits well.
    // Make the fresh bin mildly unattractive by default so existing bins win,
    // but keep it viable if it would otherwise be the only option.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut penalty = 120.0;
        // Late in the stream, prefer consolidating into open bins more strongly.
        penalty += 80.0 * progress;
        // If many bins are open, opening yet another is worse.
        penalty += 4.0 * open_bins_count as f64;
        // If the fresh bin would be nearly as empty-fitting as others, allow it.
        if fitting_bins_count == 0 {
            penalty = 0.0;
        }
        score += penalty;
    }

    // Global residual pressure: if mean residual across open bins is small,
    // space is scarce, so reward using this bin's remaining space efficiently.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * mean_residual.max(0.0) * 0.3;

    // Prefer bins whose residual is close to the item (tight fit signal).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear (quadratic) penalty growth
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Tight fits (very small post-residual) get extra reward, smoothly
    let tightness = (1.0 - norm_pr).clamp(0.0, 1.0);
    score -= 25.0 * tightness * tightness * tightness;

    // Dead-space penalty: post-residual too small for typical items (smooth sigmoid-ish)
    let unusable = 1.0 / (1.0 + (pr / 12.0).exp());
    score += 30.0 * unusable * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: if next item could fit into the post-residual, reward leaving that space
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = 1.0 / (1.0 + ((pr - nxt) / 8.0).exp());
        score -= 20.0 * fits_next * (1.0 - progress);
    }

    // Penalize bins far below mean residual (keeps balanced residual pool), smoothly
    score += 0.15 * ((bin_residual as f64 - mean_residual) / cap).powi(2) * 100.0 * progress;

    // Mild new-bin preference late in the stream when residuals are fragmented
    let new_bin_bonus = if bin_residual == bin_capacity { 8.0 * (1.0 - progress) } else { 0.0 };
    score += new_bin_bonus;

    // Slight crowding penalty: many open bins -> favor consolidation
    score += (open_bins_count as f64).sqrt() * 0.8;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which quarter of the bin remains.
    let quarter = (post_residual / (bin_capacity / 4 + 1)) as f64;
    score -= 12.0 * quarter; // larger leftover chunks are reusable -> reward

    // Dead-space penalty: post residual too small for the smallest plausible item (1..100).
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    } else if post_residual < 25 {
        score += 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item chains nicely: reward proportionally to how snug it is
            let snug = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * snug;
        } else {
            // next item won't fit here; slight penalty if residual is awkward
            let awkward = post_residual as f64 / cap;
            score += 10.0 * awkward;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins are full-ish.
    if bin_residual == bin_capacity {
        let mean_frac = mean_residual / cap;
        // if open bins still have lots of room, opening new bin is wasteful
        score += 25.0 + 50.0 * mean_frac;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open new bin
        }
        // late in stream, consolidating matters more
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer filling bins that are already small-residual (harmonic tightness).
    let tight = 1.0 - (bin_residual as f64 / cap);
    score -= 15.0 * tight;

    // Many open bins: encourage using existing ones to limit bin count.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold even the smallest item
    // (size 1..=10) are nearly unusable; penalize the "wasted" portion.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }
    // Semi-dead zone: residual 10..=19 can only fit tiny items; mild penalty.
    else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits: the smaller the item relative to the residual,
    // the better the packing.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 25.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open-bin pressure is high or no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        // Penalize new bins when few bins are open (early stream).
        score += 30.0 + open_bins_count as f64 * -0.5 + progress * 10.0;
        // If the next item would fit perfectly with this item in a fresh bin,
        // make the new bin more attractive.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            let combined = (item_size + next_item_size) as f64;
            if combined / bin_capacity as f64 > 0.9 {
                score -= 35.0;
            }
        }
        // If many bins are open with high mean residual, new bin is fine.
        if mean_residual > 60.0 && open_bins_count > 4 {
            score -= 15.0;
        }
    } else {
        // Prefer bins whose residual is close to the item (minimize fragmentation).
        let gap = (bin_residual - item_size) as f64;
        score += gap * 0.3;
        // Slight penalty for spreading across too many open bins.
        score += open_bins_count as f64 * 0.2;
    }

    // Lookahead: if the post residual cannot accommodate the next item,
    // this placement is terminal for the bin; slight penalty unless it was a tight fit.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward when post_residual matches next item size exactly
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }
    // Reward when next item fits exactly in the post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 150.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space penalty relative to next item
        score += 60.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Compare post_residual to mean residual: avoid creating outlier small residuals
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when open bins exist that could fit reasonably
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 80.0 + 50.0 * progress;
        // New bin is attractive only if item is large relative to capacity
        score -= 0.6 * item_size as f64;
    }

    // Prefer tighter bins (smaller residual before placement)
    score += 0.2 * (bin_residual as f64 - item_size as f64);

    // Mild waste normalization
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post-residual is already good; amplify it)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small to ever be useful (min item = 1)
    if post_residual > 0 && post_residual < 5 {
        score += 25.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bin: only bin that fits -> strong preference to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits in the post-residual, reward; else penalize
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
        } else if next_item_size <= bin_residual && post_residual > 0 {
            score += 4.0;
        }
        // If next item is huge, prefer keeping small residuals around? No: prefer filling this bin now
        if next_item_size > post_residual && post_residual < next_item_size.min(10) {
            score += 8.0;
        }
    }

    // New-bin candidate logic: empty bin should only win when fits are bad
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 10.0;
        // more open bins => opening new bins is more attractive (spread load)
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
        // early in stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 15.0;
        // if next item is large, a fresh bin is valuable
        if next_item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    } else {
        // Prefer bins whose residual is close to item (best-fit flavor)
        let gap = (bin_residual as f64 - item_size as f64).abs();
        score += gap * 0.15;
        // Prefer bins with residual below mean (consolidate small bins)
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 1.5;
        }
    }

    // Mild penalty for too many open bins relative to progress (encourage closing bins)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count as f64 > 4.0 + 10.0 * (1.0 - progress) {
        score += 2.0;
    }

    // Small noise-free deterministic tie-breaker via bin_residual parity coupling
    score += (bin_residual % 3) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with non-linear polynomial coupling to progress.
    let mut score = pr * (1.0 + 0.5 * progress * pr_norm);

    // Strongly reward near-perfect fits, smoothly scaled by stream progress.
    score -= 30.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 + 0.8 * progress);

    // Penalize dead space that cannot fit the next item (smooth interaction).
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let waste = (pr - ns).max(0.0);
        score += 0.6 * waste * (0.5 + 0.5 * progress);
        // Reward leaving room exactly for the lookahead item.
        let gap = (pr - ns).abs();
        score -= 12.0 * (-gap * gap / 200.0) * (1.0 - pr_norm);
    } else {
        // Last item: heavily reward zero post-residual.
        score -= 40.0 * (1.0 - pr_norm) * (1.0 - pr_norm);
    }

    // Last-chance bonus: if this is the only fitting bin, favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // New-bin candidate: penalize opening a new bin mildly, more so early in the stream
    // and when many bins are already open but underfilled.
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - 0.6 * progress) + 0.5 * open_bins_count as f64 * (1.0 - progress);
        // But allow new bins when mean residual of open bins is small (all tight).
        score -= 10.0 * (mean_residual / cap).max(0.0) * (1.0 - progress);
    }

    // Mild penalty for fragmenting relative to mean residual state.
    score += 0.15 * (pr - mean_residual).abs() * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, but strongly penalize unusable dead space
    // (dead space = residual too small for the smallest plausible item).
    let dead_threshold = 10u32.min(bin_capacity / 10);
    if post_residual > 0 && post_residual < dead_threshold {
        score += 25.0 + (dead_threshold - post_residual) as f64 * 2.0;
    }

    // Perfect fit reward: harmonic class where post_residual is a small divisor-like residue.
    if post_residual == 0 {
        score -= 40.0;
    } else if bin_capacity % post_residual == 0 && post_residual <= bin_capacity / 4 {
        score -= 15.0;
    }

    // Harmonic class of the item: items near capacity fractions (1/2, 1/3, 1/4 of C)
    // pack best with bins whose residual is in the same harmonic class.
    let item_class = bin_capacity / item_size.max(1);
    let residual_class = if post_residual > 0 { bin_capacity / post_residual } else { item_class };
    if item_class == residual_class {
        score -= 12.0;
    }

    // Integer-division threshold on post_residual: quantize into capacity fractions.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual <= quarter {
        score += 8.0; // tiny leftover, mildly risky
    } else if post_residual <= half {
        score -= 6.0; // sweet spot: can host mid-size items
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // harmonic-class match of next item with post_residual
            let next_class = bin_capacity / next_item_size.max(1);
            if next_class == residual_class {
                score -= 18.0;
            } else {
                score -= 8.0;
            }
        } else {
            // next item won't fit here: penalize leaving large residual that strands it
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if stream is early or many open bins are fragmented, new bin can be good.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress < 0.15 {
            score -= 20.0;
        }
        if mean_residual < bin_capacity as f64 / 3.0 {
            score -= 25.0; // open bins are fragmented; fresh bin attractive
        }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 {
            score -= 30.0; // big item coming: keep a fresh bin
        }
    }

    // Mild pressure against bin proliferation.
    score += open_bins_count as f64 * 0.3;

    // Prefer bins tighter than the mean residual (compact packing).
    score += (mean_residual - post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize residual just below the smallest item size band (unusable for typical items).
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current item is large and residual pressure is high.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64 / (1.0 + mean_residual / 10.0)) * (0.5 + progress);
        score += 60.0 - pressure * 5.0;
        // Lookahead: if next item fits into leftover of this bin after placement, discourage new bin.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 15.0;
        }
        if item_size >= 60 {
            score -= 10.0;
        }
    }

    // Lookahead synergy: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 4.0;
    }

    // Open-bin pressure: mildly discourage proliferating bins with large mean residual.
    score += open_bins_count as f64 * 0.3 - mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly prefer bins whose post_residual is tiny.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tightness: reward small post_residual nonlinearly.
        score -= 200.0 / (post_residual as f64).powf(0.5);
    }

    // 2-step lookahead: if the next item exactly fits the post_residual,
    // this is a chained perfect fit — reward heavily.
    if next_item_size > 0 {
        if post_residual as f64 == next_item_size as f64 {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            // Next item fits: residual gets consumed, good.
            score -= 0.5 * next_item_size as f64;
        } else {
            // Next item won't fit here: leftover dead space penalized
            // proportionally to how much is wasted.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 150.0 * waste;
        }
    }

    // Compare residual against mean residual across open bins:
    // prefer filling below-average-residual (tighter) bins.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin
    // fit is very poor (large post_residual relative to capacity).
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        score += 400.0 * (1.0 - poor_fit);
        // Early in the stream, be more willing to open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 100.0 * (1.0 - progress);
    }

    // Late in the stream, consolidate into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 80.0 * progress * (open_bins_count as f64).recip().max(0.001);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead: reward if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 12.0 * (post_residual as f64 - next_item_size as f64).min(20.0) / 20.0;
        } else {
            // next item won't fit here; mild penalty proportional to wasted potential
            score += 6.0;
        }
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // current fits are poor or the item is large relative to residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fits = if fitting_bins_count == 0 { 0.0 } else { (item_size as f64 - mean_residual.min(item_size as f64)).abs() };
        // Prefer new bin early or when item is huge and fits are loose.
        let new_bin_bonus = 35.0 * (1.0 - progress) + (item_size as f64 / bin_capacity as f64) * 20.0
            - (post_residual as f64); // an empty bin has post_residual = C - item; lower is better
        score = score - new_bin_bonus + 10.0 * poor_fits / bin_capacity as f64;
        // Discourage proliferation of open bins late in the stream.
        score += 2.5 * open_bins_count as f64 * progress;
    }

    // Global pressure: when many bins are open, prefer consolidating into
    // bins whose residual is near the mean (keeps residuals uniform).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Slight preference for bins with larger residual when item is small
    // (keeps small bins for small items).
    if item_size <= 30 {
        score -= 0.05 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual in [0,1]

    // Base: reward tight fits (small post_residual), non-linearly
    let mut score = post;

    // Polynomial coupling: waste term grows superlinearly with post residual
    score += 40.0 * x * x * cap * (0.3 + 0.7 * progress);

    // Smooth interaction with stream progress: late in the stream, prefer filling
    // existing bins more aggressively (tight fit weighted up)
    score -= (1.0 - progress) * 20.0 * x;

    // Lookahead: if next item fits in post residual, reward this placement smoothly
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let fits_next = (nxt <= post) as i32 as f64;
        let tightness = 1.0 - (post - nxt) / cap;
        score -= 25.0 * fits_next * tightness * (0.5 + 0.5 * progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Mild penalty when bin residual is far below mean residual (keeps balance)
    score += 0.15 * (mean_residual - bin_residual as f64).abs();

    // Slight preference to keep number of open bins small early on
    score += 0.5 * open_bins_count as f64 * (1.0 - progress) * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the residual (integer division thresholds) ---
    let cap = bin_capacity as f64;
    let res = post_residual as f64;

    // Class residual into octaves of capacity: 0..12, 12..25, 25..50, 50..100
    let class: f64 = if post_residual == 0 { -4.0 }
        else if post_residual <= 12 { -2.0 }
        else if post_residual <= 25 { -0.5 }
        else if post_residual <= 50 { 1.5 }
        else { 3.0 };
    score += class * 3.0;

    // Modulo arithmetic: residuals that are multiples of common item granularities
    // are more likely reusable by future items -> reward them.
    let mods = [(10u32, 4.0), (20, 3.0), (5, 2.0), (25, 2.5), (50, 3.5)];
    for (m, w) in mods.iter() {
        if post_residual % m == 0 && post_residual > 0 {
            score -= w;
        }
    }

    // Dead-zone penalty: residuals in awkward ranges (1..9, 13..19, 26..34) rarely fit
    // typical item sizes (multiples of 5/10 dominate many streams).
    if (1..9).contains(&post_residual) { score += 15.0; }
    else if (13..19).contains(&post_residual) { score += 8.0; }
    else if (26..34).contains(&post_residual) { score += 4.0; }

    // Perfect fit: huge reward
    if post_residual == 0 { score -= 100.0; }

    // Lookahead coupling: does post_residual fit the next item exactly or well?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // chain fit
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            // harmonic class of slack after the lookahead item
            if slack == 0 { score -= 20.0; }
            else if slack <= 12 { score -= 4.0; }
            else if slack > 50 { score += 3.0; }
        }
    }

    // Fraction-of-capacity coupling: prefer bins whose fill ratio crosses
    // quarter thresholds (integer division on residual).
    let quarter = (post_residual / 25) as f64;
    score += quarter * 2.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item
    // is large relative to capacity or all fits would be very wasteful.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin
        score = cap - item_size as f64; // ~ post_residual for new bin
        let wasteful = fitting_bins_count > 0 && (mean_residual - item_size as f64) < 15.0;
        let big_item = item_size as f64 > 0.6 * cap;
        let crowded = open_bins_count > 8;
        if wasteful || big_item || crowded {
            score -= 20.0; // opening new bin is good here
        }
        if fitting_bins_count == 0 {
            score -= 50.0; // must open
        }
    }

    // Slight preference to fill older/many bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;
    score -= (open_bins_count as f64).min(10.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item (1..=9) are toxic.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward residuals that can still host a typical item (>=10): usable space is fine.
    if post_residual >= 10 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, strong bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual {
            // Next item won't fit here; dead space risk depends on size of gap.
            if post_residual < 10 && post_residual > 0 {
                score += 20.0;
            }
        } else {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += pressure * 0.3;

    // Relative fill quality: prefer bins whose residual is close to item size (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 15.0;

    // Mean residual coupling: if this bin is far below mean residual (already tight), favor it.
    score -= (mean_residual - post_residual as f64) * 0.15;

    // New-bin candidate: opening a new bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin, softened if many bins are open or stream is early.
        score += 20.0 - pressure * 0.1;
        if next_item_size > 0 && next_item_size >= 40 {
            score -= 10.0; // large upcoming item pairs well with a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: minimize post_residual nonlinearly
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // 2-step lookahead: reward when next_item_size fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0; // perfect chain: bin becomes exactly full after next item
        } else if next_item_size <= post_residual {
            // reward proportional to how much of post_residual the next item consumes
            let fill_after = (post_residual - next_item_size) as f64;
            score -= (bin_capacity as f64 - fill_after) * 0.5;
            score += fill_after * 0.3; // penalize leftover after the lookahead item
        } else {
            // next item cannot use post_residual: dead space penalty
            score += post_residual as f64 * 0.4;
        }
    } else {
        // last item: prefer fullest possible bin
        score -= 50.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.6;

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so as stream progresses
    if bin_residual == bin_capacity {
        score += 60.0 + (step_index as f64 / total_items.max(1) as f64) * 40.0;
        // but if no open bin can fit, opening is necessary
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Slight preference for fewer open bins when residuals are similar
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins whose residual is barely larger than item.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness * tightness;

    // Penalize creating small dead space that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    } else if post_residual >= 10 && post_residual <= 30 {
        score += 0.0; // usable zone
    } else {
        score -= 2.0; // large leftover is flexible
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 {
        score += 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // or bin count is low (early stream, consolidation less valuable).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_fit = tightness < 0.55;
        if bad_fit && open_bins_count > 2 {
            score -= 18.0; // fresh bin better than wasting an open bin's space
        } else {
            score += 20.0 + 10.0 * progress;
        }
    }

    // Prefer bins below mean residual (relatively full bins) to consolidate.
    score -= 0.05 * (mean_residual - bin_residual as f64);

    // Mild preference for already-open bins as stream progresses.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let next_ratio = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let wave = (progress * std::f64::consts::PI).sin();
    score += 12.0 * pr_norm * pr_norm * (1.0 - progress) * (1.0 + 0.5 * wave);

    // Penalize large dead space more than linearly when few fitting bins
    let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
    score += 8.0 * pr_norm * pr_norm * pr_norm * scarcity;

    // Reward tight fits smoothly
    score -= 15.0 * fit_ratio * fit_ratio * (1.0 - pr_norm);

    // Lookahead: bonus if next item fits the post-residual smoothly
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 * (next_ratio * (1.0 - pr_norm)) * (0.5 + 0.5 * progress);
    } else if next_item_size > 0 {
        score += 4.0 * pr_norm * progress;
    }

    // Mean residual coupling: prefer bins near mean early, diverge later
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev * (0.3 + 0.7 * progress);

    // New-bin candidate handling: mild penalty so new bins only win on poor fits
    if bin_residual == bin_capacity {
        score += 18.0 - 14.0 * progress + 10.0 * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo 10: dead space in small remainders
    // is more likely to be filled by future items.
    let post_class = post_residual % 10;
    let class_bonus = match post_class {
        0 => 25.0,          // perfect fit class -> strong reward
        1..=5 => 8.0,       // small usable gap
        6..=9 => -6.0,      // awkward gap, penalize
        _ => 0.0,
    };
    score -= class_bonus;

    // Integer-division thresholds on post_residual: buckets of 10
    let bucket = post_residual / 10;
    score -= (bucket as f64) * 1.5;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) % 10;
            score -= 15.0 - slack as f64;
        } else {
            // next item can't use this bin's gap: slight penalty
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New empty-bin candidate: penalize opening a new bin unless current bin
    // residual is small (already nearly full) or item is tiny.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 + 20.0 * progress - (post_residual as f64) * 0.3;
    }

    // Prefer bins whose residual deviates from the mean (specialization).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= dev * 0.15;

    // Tight fits rewarded: closeness of item to residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 10.0;

    // Small global pressure: more open bins -> prefer filling existing ones.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..10)
    // are perfect; residuals in the "unusable small gap" band are heavily penalized.
    let dead_threshold = 10.0;
    if post_residual == 0 {
        score -= 50.0; // perfect fit: best possible outcome
    } else if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 4.0; // unusable sliver
    }

    // Tight-fit reward: proportion of bin consumed by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Penalize leaving a gap that the lookahead item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // gap is usable by lookahead: mild bonus scaled by snugness
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= snug * 8.0;
        } else if post_residual > 0 {
            // lookahead cannot use this gap -> dead space penalty
            score += 6.0;
        }
    }

    // Open-bin pressure: discourage proliferation of bins unless fit is tight.
    score += (open_bins_count as f64) * 0.35;

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when the current
    // item is large relative to capacity and existing residuals are poor fits.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // baseline cost of opening a bin, modulated by stream progress and fit quality
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut open_cost = 55.0 + (1.0 - progress) * 10.0;
        // If item nearly fills a fresh bin, opening is attractive.
        if fill_ratio > 0.6 {
            open_cost -= (fill_ratio - 0.6) * 60.0;
        }
        // If many bins fit the item, no reason to open a new one.
        open_cost += (fitting_bins_count as f64) * 5.0;
        // If mean residual is large, prefer existing bins.
        open_cost += mean_residual * 0.4;
        score = score.max(0.0) + open_cost;
    }

    // Mild bonus for consuming bins whose residual is close to mean (consolidation).
    if !is_new_bin {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= (1.0 - dev / bin_capacity as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves waste; mild reward scaled by how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space: post_residual too small for the lookahead item.
            // Penalize more sharply the smaller the leftover fragment is.
            let frag = post_residual as f64;
            score += 60.0 * (1.0 - frag / bin_capacity as f64);
        }
    }

    // Compare post_residual against mean residual: leaving more than average
    // slack is fine (bin stays useful); leaving much less than average is waste.
    score += 2.0 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 120.0;
    }

    // Penalize wasting a large, reusable residual on a small item early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if (post_residual as f64) > mean_residual * 1.5 {
        score += 40.0 * (1.0 - progress);
    }

    // Slight preference to consolidate into existing bins rather than open new ones.
    if bin_residual == bin_capacity {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual) with a nonlinear term.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to ever hold a plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0; // unusable sliver
    }
    if post_residual > 0 && post_residual < item_size {
        score += 8.0; // residual smaller than current item: hard to refill
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
            // Extra reward for exact two-item chain fill.
            let chain = post_residual - next_item_size;
            if chain < 10 {
                score -= 10.0;
            }
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Many open bins: prefer consolidating into bins with large residuals.
    let mean_diff = bin_residual as f64 - mean_residual;
    score -= 0.15 * mean_diff * (open_bins_count as f64).ln().max(1.0);

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late in the stream, squeeze existing bins hard.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        // Penalize new bins, less so early on.
        score += 30.0 + 40.0 * progress;
        // But if no open bin fits well, opening fresh is fine.
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
        // If item is large and would leave a tiny residual in any open bin,
        // a fresh bin keeps usable space.
        if item_size >= 70 {
            score -= 15.0;
        }
    }

    // Reward filling bins completely (post_residual == 0 is perfect).
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual in [0,1]

    // Smooth polynomial coupling: penalize mid-range dead space more as stream progresses
    let coupling = (1.0 - progress) * x * x + progress * (x * (1.0 - x) * 4.0);
    score += 8.0 * coupling;

    // Reward tight fits, stronger late in the stream
    let tight = 1.0 - x;
    score -= (1.0 + progress) * 6.0 * tight * tight;

    // Penalize when post residual can't fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post as u32 >= next_item_size {
            score -= 3.0 * (1.0 - (nx / cap));
        } else {
            score += 2.0 + 4.0 * (nx / cap) * progress;
        }
    }

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 {
        score -= 5.0 + 5.0 * progress;
    }

    // Mild pressure toward consolidating bins
    score += 0.05 * (open_bins_count as f64) * (mean_residual / cap - x).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in low quarters is worse.
    let quarter = bin_capacity / 4;
    match post_residual {
        0 => score -= 40.0,                      // perfect fit, best outcome
        r if r < quarter => score += 25.0,       // tiny dead space, hard to reuse
        r if r < 2 * quarter => score += 8.0,
        r if r < 3 * quarter => score -= 6.0,    // still half-full, quite reusable
        _ => score -= 2.0,
    }

    // Modulo classes: residuals divisible by common item sizes (10, 20, 25, 50) are reusable.
    if post_residual % 10 == 0 { score -= 6.0; }
    if post_residual % 25 == 0 { score -= 4.0; }
    if post_residual % 20 == 0 { score -= 3.0; }

    // Lookahead: penalize if next item cannot fit the post residual.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 15.0;
        } else if post_residual - next_item_size < quarter {
            score -= 12.0; // next item would nearly fill this bin
        } else {
            score -= 5.0;
        }
    }

    // Last chance: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (mean_residual / bin_capacity as f64);

    // New empty bin: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 60.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that no future item can use are pure waste.
    // Classify post_residual into usable (>50), marginal (21..=50), and dead (1..=20) zones.
    let dead_space = post_residual <= 20;
    let marginal = post_residual > 20 && post_residual <= 50;

    if dead_space {
        // Unusable dead space: heavy penalty, scaled by how far below the smallest
        // plausible item (10) the gap falls. A gap of 0 is perfect fit, not dead.
        if post_residual == 0 {
            score -= 40.0; // perfect fill is excellent
        } else {
            score += (20 - post_residual) as f64 * 1.5 + 15.0;
        }
    } else if marginal {
        // Mid-size gaps are risky: penalize mildly, but reward if lookahead item fits.
        score += 5.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
        }
    } else {
        // Large usable gap: mild reward, stronger if the next item fits well.
        score -= 4.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0;
            // Bonus for tight fit of lookahead item (gap after next placement is small).
            let after_next = post_residual - next_item_size;
            if after_next <= 20 {
                score -= 6.0;
            }
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (especially tight ones) rather than spreading out.
    let bin_pressure = open_bins_count as f64 / 8.0;
    if bin_residual != bin_capacity {
        score -= bin_pressure * 2.0;
    } else {
        // New-bin candidate: penalize opening a new bin, more so when many bins are open
        // and mean residual across open bins is still substantial (they can absorb items).
        score += 10.0 + bin_pressure * 3.0 + mean_residual * 0.3;
    }

    // Early stream: keep bins open and flexible; late stream: tighten packing aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0;

    // Slight preference for bins whose residual is close to the item (tight fits).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect match of post_residual with next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - next).abs();
        if diff < 0.5 {
            score -= 60.0; // perfect lookahead match: next item exactly fills this bin
        } else if post >= next {
            // next item still fits after this placement: mild reward scaled by tightness
            score -= 12.0 * (1.0 - diff / (bin_capacity as f64)) * (next / 100.0);
        } else {
            // next item cannot use the leftover: penalize dead space proportional to gap
            score += 0.35 * diff;
        }
    }

    // Tight fit reward: small post_residual is good (classic best-fit behavior)
    score -= 0.25 * (1.0 - post_residual as f64 / bin_capacity as f64) * item_size as f64;

    // Penalize bins whose residual deviates strongly below mean (wasting larger spaces on small items)
    if post_residual as f64 > mean_residual + 20.0 {
        score += 0.15 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer filling nearly-full bins early in the stream to keep many residual options open
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual <= 10 {
        score -= 25.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize opening a new bin unless it's a genuinely good idea
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive only if existing bins fit poorly
        // (post_residual == 100 - item_size is large) and there are few open bins
        let waste_open = (bin_capacity as f64 - item_size as f64);
        if waste_open > 45.0 && fitting_bins_count > 0 {
            score += 55.0; // discourage new bin when open bins would leave big waste
        } else if fitting_bins_count == 0 {
            score -= 10.0; // no alternative, new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect fit is extremely attractive.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        // Small dead space is nearly unusable for items >= 10; penalize.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            score -= 6.0; // chain potential
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15; // leftover mismatch
        }
    }

    // Prefer fuller bins over emptier ones (global state coupling).
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Discourage opening new bins early; allow more exploration late.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + progress * 3.0);
        score += 18.0 - pressure.min(18.0);
        // If no open bin fits well, new bin is more attractive.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mild preference to spread load when many bins are open and residual is high.
    if bin_residual > item_size * 2 && open_bins_count > 2 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) + norm_pr * (1.0 - progress) * 0.5;

    let mut score = pr + 20.0 * poly;

    // Reward tight fits (small post residual), more strongly later in stream
    score -= (1.0 - norm_pr) * (10.0 + 30.0 * progress);

    // Penalize last-chance bins that would leave large dead space
    if fitting_bins_count == 1 {
        score += norm_pr * 15.0;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let next_fit_quality = 1.0 - (pr - ns) / cap;
            score -= 8.0 + 12.0 * next_fit_quality * (0.5 + progress);
        } else {
            score += 6.0 * (ns - pr) / cap;
        }
    }

    // Mild penalty for opening new bins when many bins already fit the item
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 10.0 + 5.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Coupling with mean residual: prefer bins near the mean residual to keep balance
    score += 0.3 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that future items can reuse.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: residuals divisible by common item-size divisors are reusable
    if post_residual > 0 {
        let mut harmony = 0.0;
        for d in [10u32, 20, 25, 50].iter() {
            if post_residual % d == 0 {
                harmony += 8.0;
            }
        }
        // residual in small dead zone (1..10) is dead space
        if post_residual < 10 {
            harmony -= 15.0;
        }
        score -= harmony;
    }

    // Lookahead: does the next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // penalize leftover that is awkward (small dead space)
            if slack < 10.0 {
                score += 12.0;
            } else {
                score -= 5.0 * (1.0 - slack / cap);
            }
        } else {
            // next item won't fit here: mild penalty, this bin becomes closed-ish
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Fraction of capacity used by this placement
    let fill = item_size as f64 / cap;
    score -= 20.0 * fill;

    // Prefer filling bins with low residual relative to mean (balance avoidance of fragmentation)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // Late in stream: prefer tightening existing bins over opening new ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses
        score += 30.0 * (0.5 + progress);
    } else {
        score -= 10.0 * progress;
    }

    // Modulo threshold on item_size: large items (>=50) prefer tightest bins
    if item_size >= 50 {
        score += post * 0.1;
    } else {
        score += post * 0.02;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use are wasted.
    // Penalize "unusable" small gaps harder than proportionally large gaps.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // gaps below the smallest item size (1) can't exist, but treat tiny gaps
        // (<= 10, below the classic min item size) as fully dead space.
        if gap <= 10.0 {
            score += 40.0 * (1.0 - gap / 10.0) + 20.0;
        } else if gap < 25.0 {
            // small gaps are hard to fill: superlinear penalty
            score += 15.0 * (25.0 - gap) / 15.0;
        } else {
            // large residuals are valuable; reward them mildly
            score -= 6.0 * (gap - 25.0) / (bin_capacity as f64 - 25.0);
        }
    } else {
        // perfect fill is ideal
        score -= 50.0;
    }

    // Exact-fit lookahead: if the next item exactly consumes post_residual, strongly favor.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        // next item fits here: mild bonus proportional to how well it fills
        let fill_after_next = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - fill_after_next / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item won't fit after this placement: penalize creating a stranded gap
        score += 12.0;
    }

    // Open-bins pressure: discourage spreading across many bins when few fit,
    // encourage consolidation; but allow new bins when this bin is a bad host.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // brand-new bin candidate: base cost of opening a bin
        score += 25.0 + 4.0 * pressure;
        // opening a new bin is attractive when no existing bin fits well
        if fitting_bins_count <= 1 && post_residual > 0 {
            score -= 30.0;
        }
    } else if fitting_bins_count == 1 {
        // last chance to use an open bin: strongly favor filling it
        score -= 20.0 + 5.0 * pressure;
    }

    // Prefer bins whose residual is close to the item (tight fit)
    let tightness = (bin_residual - item_size) as f64;
    score += 0.05 * tightness;

    // Slight preference for bins below mean residual (use emptier bins first
    // keeps fuller bins available for small future items)
    if bin_residual as f64 > mean_residual {
        score += 3.0;
    }

    // Late in the stream, be more conservative about opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - gap / (bin_capacity as f64));
        if gap == 0.0 {
            score -= 40.0; // exact two-item chain fill
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize leaving awkward small residue.
        if post_residual > 0 && post_residual < 10 {
            score += 15.0; // tiny dead space
        }
        score += 5.0;
    }

    // Relative to mean residual: prefer bins with residual below mean (denser bins),
    // penalize dumping into already-sparse bins.
    score += 0.5 * ((post_residual as f64) - mean_residual);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is large
    // or all open bins would leave big waste.
    if bin_residual == bin_capacity {
        let waste_if_open = (bin_capacity - item_size) as f64;
        let best_open_waste = if fitting_bins_count > 0 {
            // approximate: mean residual minus item
            (mean_residual - item_size as f64).abs()
        } else {
            waste_if_open + 1.0
        };
        if best_open_waste >= waste_if_open {
            score += 25.0; // opening new bin is fine
        } else {
            score += 60.0; // prefer existing bins
        }
        // Early in stream, new bins are cheap; later, avoid proliferation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress * (open_bins_count as f64).ln().max(0.0);
    }

    // Slight preference for filling bins that are already quite full.
    score += 0.05 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Perfect fit bonus (waste-free placement).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize dead space that no future item can use (items >= 10 traditionally,
    // but sizes are 1..100, so scale dead-space penalty by how "unusable" the gap is).
    let dead = post_residual as f64;
    score += 0.35 * dead * dead / bin_capacity as f64;

    // Lookahead coupling: if the next item fits the post-residual exactly or well,
    // this bin is doubly valuable; if next item cannot fit, slight penalty.
    if next_item_size > 0 {
        if next_item_size as f64 <= post_residual as f64 {
            let next_fit = 1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= 30.0 * next_fit;
        } else {
            score += 12.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when open bins
    // are crowded (low mean residual) or many bins are already open with poor fits.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 55.0 * (1.0 - crowding) * pressure;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // Big items into fresh bins are fine early on.
        score -= (item_size as f64 / 100.0) * 15.0 * (1.0 - progress);
    }

    // Mild preference for filling bins that are already partially loaded vs. nearly full duplicates.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill_ratio;

    // Global balance: penalize placing into bins whose residual deviates from mean
    // (keeps residual distribution tight, easier future packing).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let fit_ratio = it / cap;

    // Base: penalize leftover space (waste), with non-linear (quadratic) growth
    let mut score = pr * (1.0 + 0.008 * pr / cap);

    // Smooth non-linear coupling: tight fits are increasingly valuable as the stream progresses
    let tightness = 1.0 - pr / cap; // 1.0 = perfect fit
    score -= tightness * tightness * (1.0 + 2.0 * progress) * 12.0;

    // Penalize dead space that cannot fit the next item (lookahead coupling)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            // unusable gap for the lookahead item
            score += (nxt - pr) * (0.6 + 1.4 * progress);
        } else {
            // reward bins that can also host the next item, smoothly scaled by slack
            score -= (1.0 - (pr - nxt) / cap) * 4.0;
        }
    }

    // Last-chance bonus: strongly prefer using the only bin that fits before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate handling: make empty bin attractive only when existing bins fit poorly
    if bin_residual == bin_capacity {
        // Mild default penalty so open bins are preferred unless they waste a lot
        score = cap * 0.55 + 8.0 * (1.0 - progress)
            - fit_ratio * fit_ratio * 10.0;
        // Late in the stream, new bins are cheaper than spreading waste
        score -= 20.0 * progress * progress;
    }

    // Slight penalty for fragmenting across many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * (pr / cap);

    // Deviation from mean residual: prefer bins whose residual stays near the pack norm
    score += 0.15 * (pr - mean_residual).abs() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod small integers
    let r = post_residual;
    let mod3 = (r % 3) as f64;
    let mod5 = (r % 5) as f64;
    let mod10 = (r % 10) as f64;

    // Reward residuals in "harmonic" classes that are likely reusable
    // (residuals divisible by common item sizes are more valuable)
    if r > 0 && r % 10 == 0 { score -= 4.0; }
    if r > 0 && r % 5 == 0 && r % 10 != 0 { score -= 1.5; }
    if r > 0 && r % 20 == 0 { score -= 2.0; }

    // Penalize awkward dead space: small nonzero residuals
    if r > 0 && r < 10 {
        score += (10 - r) as f64 * 1.2;
    }

    // Integer-division threshold: residuals in [10, 30] can host small items
    let div_bucket = r / 10;
    score -= (div_bucket as f64) * 0.4;

    // Lookahead: if next item fits exactly in post_residual, strongly favor
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 12.0;
        } else if next_item_size <= r {
            score -= (r - next_item_size) as f64 * 0.15;
        } else {
            score += (next_item_size - r) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate: make it moderately attractive only when open bins
    // have small residuals or many bins are open
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mean_r = mean_residual;
        let openness = (open_bins_count as f64) / (1.0 + mean_r / 10.0);
        score = 100.0 - openness * 0.5 - progress * 5.0;
        // new bin has perfect harmonic residual (100)
        score -= 4.0;
    }

    // Coupling with mean residual: prefer bins tighter than the mean
    score -= (mean_residual - bin_residual as f64) * 0.08;

    // Modulo coupling penalty: penalize residuals whose mod-3/mod-5 phases
    // combine poorly with typical item granularities
    score += (mod3 * 0.3 + mod5 * 0.2 + mod10 * 0.1) * (r as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item (1..=10) are pure waste — penalize hard.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 + (10 - post_residual) as f64 * 4.0;
    }
    // "Awkward" residuals that only very few item sizes can use.
    if post_residual > 10 && post_residual < 25 {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward using a bin that is already tight (high fill ratio).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill;

    // Pressure from number of open bins: prefer consolidating into fewer bins
    // when many are open; prefer a fresh bin when few are open.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin is attractive when the fit in
    // existing bins would leave large dead space, or when mean residual is low.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin; make it competitive.
        score = 45.0 - 0.5 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 50.0; // no open bin fits: must open new bin
        }
        // If next item is large, a fresh bin is valuable.
        if next_item_size > 60 {
            score -= 10.0;
        }
    } else {
        // Lookahead: if placing here leaves room exactly for the next item, reward.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        // If placement leaves a gap just below the next item (dead space for it), penalize.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Mild progression term: later in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item still fits, but slack remains: mild reward proportional to closeness.
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize dead space creation.
        let dead = (next_item_size - post_residual) as f64;
        score += 0.8 * dead;
    }

    // Penalize post_residual too small to ever be useful (below min item size 1..100 range, treat <15 as near-dead).
    if post_residual > 0 && post_residual < 15 {
        score += 30.0;
    }

    // Relative to mean residual: prefer bins tighter than average (best-fit flavor).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize so we only open when open bins have poor fits.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Late in stream, slightly more willing to open new bins (keep bins clean).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on post_residual.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space avoidance: penalize residuals too small for the smallest plausible item (1..100 unknown => use next item and a floor).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward; if next item won't fit, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size > post_residual {
            score += 15.0;
        } else {
            score -= (next_item_size as f64 / (post_residual as f64 + 1.0)) * 20.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost that grows with how wasteful opening is.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) + 60.0
            - 40.0 * (fitting_bins_count as f64).recip()
            + (post_residual as f64 - item_size as f64).abs() * 0.0;
        // Early in the stream, opening new bins is cheaper (builds inventory of partial bins).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 50.0 * (1.0 - progress);
        // If item is large relative to capacity, opening fresh is more attractive.
        score -= (item_size as f64 / bin_capacity as f64) * 30.0;
        // Many open bins with high mean residual: discourage another new bin.
        score += 0.5 * open_bins_count as f64 + 0.2 * mean_residual;
    } else {
        // Prefer filling bins with larger residuals relative to mean (balance consolidation).
        if (bin_residual as f64) > mean_residual {
            score -= 8.0;
        } else {
            score += 5.0;
        }
        // Mild penalty for spreading across many bins late in stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 0.1 * open_bins_count as f64 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual (prefer tight fits), non-linearly shaped
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth progress coupling: late in stream, penalize leftover dead space more strongly
    let progress_coupling = 1.0 + 2.5 * progress * progress;
    score *= progress_coupling;

    // Penalize residuals that are small but unusable for typical future items
    let waste_term = (norm_pr - 0.5) * (norm_pr - 0.5) - 0.25;
    score += 20.0 * waste_term * (1.0 - progress);

    // Lookahead: reward if next item fits into post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - pr / cap);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // Deviation from mean residual: prefer bins below mean residual (tighter bins)
    score += 0.3 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: small classes are "dead space" if
    // no future item can fit. Class by integer division thresholds (C=100).
    let class = post_residual / 10; // 0..=10 harmonic classes
    score += match class {
        0 => 0.0,                     // perfect fit, reward below
        1 => 4.0,                     // residual 1..10: nearly dead
        2 => 2.0,
        3 => 1.0,
        4 => 0.5,
        5 => 0.0,
        6 => 0.3,
        7 => 0.6,
        8 => 0.9,
        9 => 1.2,
        _ => 1.5,
    };

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward chain packing, scaled by how snugly next item fits.
            let snug = (post_residual - next_item_size) as f64;
            score -= 18.0 - snug * 0.15;
        } else {
            // Next item won't chain here: penalize proportionally to waste.
            score += 6.0 + (next_item_size - post_residual) as f64 * 0.1;
        }
        // Modulo coupling: if next item divides evenly into post residual,
        // it can tile the remaining space perfectly.
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 10.0;
        }
    } else {
        // Last item: any placement closing a bin is fine; prefer tightest.
        score -= 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate (empty bin): penalize so we only open when all
    // alternatives are poor; scale with how many bins already fit the item.
    if bin_residual == bin_capacity {
        score += 25.0 + 5.0 * fitting_bins_count as f64;
        // Early in stream, opening bins is cheaper (building diversity).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
    }

    // Prefer bins below mean residual (fill emptier bins first keeps
    // tight bins for tight fits) — mild harmonic pull.
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Penalize very large items into nearly-full bins creating tiny residue.
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        score += 3.0;
    }

    // Slight preference for fewer open bins when many are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: post residual, but strictly penalize "dead space" gaps
    // that are too small to be useful for typical future items.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Dead-space threshold: residuals below this are likely unusable.
    let dead_threshold = 10.0_f64.min(cap * 0.1);

    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 50.0;
    } else if (post_residual as f64) < dead_threshold {
        // Small unusable gap: penalize heavily.
        score += 40.0 + pr;
    } else {
        // Usable residual: mildly prefer smaller residuals (tighter fit)
        score += pr * 0.5;
    }

    // Reward bins whose residual tightly matches the item (small waste ratio).
    let waste_ratio = pr / (bin_residual as f64).max(1.0);
    score += waste_ratio * 20.0;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap < dead_threshold {
            score -= 25.0; // next item will nearly fill this bin perfectly
        } else {
            score -= 10.0 * (1.0 - gap / cap);
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: slight penalty.
        score += 5.0;
    }

    // Open bins pressure: encourage filling existing bins when many are open,
    // but allow new bins early in the stream when few bins exist.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let pressure = (open_bins_count as f64).sqrt() * (2.0 + 6.0 * progress);
    score += pressure;

    // New-bin candidate handling: neutral base, but discouraged when
    // open bins are plentiful or item fits reasonably somewhere.
    if bin_residual == bin_capacity {
        let fit_bonus = if fitting_bins_count > 0 { 12.0 } else { 0.0 };
        score += 55.0 + fit_bonus + pressure * 0.5;
        // If the next item is huge and current bins are tight, new bin is fine.
        if next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 20.0;
        }
    }

    // Mild mean-residual coupling: prefer bins below mean residual
    // (fill the emptier bins first to consolidate).
    if (bin_residual as f64) > mean_residual {
        score += 3.0;
    } else {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward scaled by tightness of fit
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 150.0 * tightness;
        } else {
            // next item does not fit: penalize wasted residual that likely becomes dead space
            score += 60.0;
        }
    }

    // Compare post_residual against mean residual across open bins
    let mr = if mean_residual.is_finite() && mean_residual > 0.0 { mean_residual } else { bin_capacity as f64 };
    let rel = post_residual as f64 - mr;
    score += 0.8 * rel;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Penalize large dead space that nothing (min size 1) can't still use, but discourage
    // residual too small to be useful relative to mean item size
    if post_residual > 0 && (post_residual as f64) < mr * 0.35 {
        score += 90.0;
    }

    // Progress factor: later in stream, prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Prefer filling already-open bins when many are open
    score += 5.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good (already base), amplify near-perfect fits.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.85 {
        score -= 6.0 * (fit_ratio - 0.85);
    }

    // Penalize creating small unusable dead space (post_residual too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 3.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to wasted opportunity.
            score += 2.0;
        }
    }

    // Prefer bins whose residual is below the mean (compact bins first), keep spread bins open.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 10.0 * dev;

    // Time horizon: early in the stream, be more willing to open new bins (favor tight fits less
    // desperately); late in the stream, squeeze existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * fit_ratio;

    // Many open bins with slack: penalize spreading items across too many bins.
    if open_bins_count > 4 && bin_residual as f64 > mean_residual {
        score += 2.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperation = (fitting_bins_count == 0) as i32 as f64
            + (fit_ratio > 0.0 && fit_ratio < 0.5) as i32 as f64;
        score += 12.0 - 10.0 * desperation;
        // Late in stream, prefer reusing bins over opening new ones.
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress (smooth, no piecewise constants)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with progress:
    // early on, favor tight fits strongly (post_residual low); later, weight
    // residual dispersion less aggressively since stream statistics stabilize.
    let pr = post_residual as f64;
    let norm_pr = pr / bin_capacity as f64;
    let coupling = norm_pr * norm_pr * (1.0 - progress) * 40.0
                 + norm_pr * progress * 15.0;
    score += coupling;

    // Smooth cubic penalty on wasted fraction, modulated by open-bin pressure
    let pressure = (open_bins_count as f64 / (1.0 + progress * 5.0)).tanh();
    score += (norm_pr * norm_pr * norm_pr) * (1.0 + pressure) * 25.0;

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: if next item fits perfectly in post_residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item won't fit here: mild penalty scaled by mismatch
        let mismatch = (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        score += 8.0 * mismatch;
    }

    // Mean residual attraction: bins far from mean residual are penalized smoothly
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += dev * dev * 20.0;

    // Small smooth reward for filling bins deeply as stream progresses
    score -= progress * (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Harmonic class of post_residual: bins whose leftover belongs to a
    // "usable" residue class (divisible by small sizes / large chunks)
    // are rewarded, since future items are more likely to fill them exactly.
    let class = post_residual % 10;
    let class_bonus = match class {
        0 => 12.0,               // perfectly modular leftover
        5 => 6.0,                // half-class
        2 | 4 | 6 | 8 => 3.0,    // even class
        _ => 0.0,                // odd dead space
    };
    score -= class_bonus;

    // Integer-division threshold on post_residual: tiny leftovers are dead
    // space; large leftovers are flexible. Penalize the awkward middle band.
    let band = post_residual / 20; // 0..=5 bands
    score += match band {
        0 => 15.0, // 0..19: near-dead
        1 => 8.0,
        2 => 0.0,
        3 => -4.0,
        _ => -8.0, // >=80: very flexible
    };

    // Coupling with lookahead item: if the next item fits exactly into the
    // post residual, strongly reward this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // partial fit quality via harmonic fraction
            let frac = next_item_size as f64 / pr.max(1.0);
            if frac > 0.5 {
                score -= 8.0 * frac;
            } else {
                score += 4.0 * (1.0 - frac);
            }
        } else {
            // next item cannot use this bin's leftover; leftover must stand alone
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    // New-bin candidate: opening a bin is only attractive when the item is
    // large relative to capacity (packing fresh) or all fits are poor.
    if is_new_bin {
        let fill_frac = item_size as f64 / cap;
        // reward opening when item is big (leaves clean large residual class)
        score -= 18.0 * fill_frac;
        // penalize opening when many bins could fit (fragmentation risk)
        if fitting_bins_count > 1 {
            score += 20.0;
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // if mean residual of open bins comfortably fits item, discourage new bin
        if mean_residual >= item_size as f64 {
            score += 12.0;
        }
    } else {
        // Reward tight fits: small post_residual relative to capacity
        score -= 10.0 * (1.0 - pr / cap);
        // prefer bins with below-average residual (fill the fullest bins first)
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Modulo coupling: item and post_residual sharing a common divisor class
    // suggests future divisibility.
    if post_residual % 5 == 0 && item_size % 5 == 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let mut score = post;

    // Dead space avoidance: residuals in (0, 10) are unusable for any item
    // (min item size 1..100 unknown, but tiny gaps waste capacity) -> heavy penalty
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // "Awkward" gap zone: residual too small for typical items but nonzero
    if post_residual >= 10 && post_residual < 25 {
        score += 25.0 * (1.0 - post / 25.0);
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage opening new ones,
    // encourage packing into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (10.0 + 20.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or stream is early
        score += 15.0 + 8.0 * pressure + 10.0 * progress;
        // But if existing fit is terrible (large dead space), new bin becomes attractive
        if post_residual >= 30 && post_residual < bin_capacity as u32 {
            score -= post * 0.3;
        }
    } else {
        // Existing bin: reward using it, scaled by open-bin pressure
        score -= 5.0 * pressure.min(3.0);
    }

    // Lookahead: if next item fits in post_residual, reward leaving a useful gap
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If post_residual would be too small for the next item, slight penalty
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Prefer bins whose residual is close to the mean (balance load)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Mild preference for tighter-than-item-size residual relative to item
    score += (item_size as f64 / cap) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = post_residual - next_item_size;
        score -= (bin_capacity as f64 - diff as f64) * 0.5;
        // exact match for next item
        if diff == 0 {
            score -= 500.0;
        }
    } else if next_item_size > post_residual {
        // next item won't fit here: penalize creating unusable dead space
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Penalize bins with large residual relative to mean (wasteful use)
    score += (post_residual as f64 - mean_residual) * 0.2;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Mild preference for tight fits relative to bin capacity
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Late in stream: prefer consolidating into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 15.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make it moderately unattractive unless item is large
    if bin_residual == bin_capacity {
        score += 50.0 - (item_size as f64 * 0.2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward high fill ratio of this placement.
    let fill = (bin_residual - post_residual) as f64 / cap;
    score -= fill * 25.0;

    // Lookahead: if the next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Dead space risk: post_residual too small for the next item.
            score += (post_residual as f64 / cap) * 6.0;
        }
    }

    // Last-chance bin: prefer using the only bin that fits before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Penalize leaving tiny unusable slivers unless perfectly tight.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // New empty bin candidate: discourage unless the item is large or few bins fit.
    if bin_residual == bin_capacity {
        let mut penalty = 28.0;
        penalty -= 0.25 * item_size as f64;      // large items justify a fresh bin
        if item_size >= 60 { penalty -= 15.0; }
        if fitting_bins_count <= 1 { penalty -= 12.0; } // no good alternative exists
        penalty *= (1.0 - 0.3 * progress);       // later in stream, reuse more aggressively
        score += penalty.max(-5.0);
    }

    // Global pressure: many open bins with high mean residual -> favor consolidation.
    if open_bins_count > 4 && mean_residual > 30.0 && bin_residual < bin_capacity {
        score -= 4.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr
        + 40.0 * norm_pr * norm_pr * (1.0 + progress)
        - 25.0 * norm_pr * (1.0 - progress) * progress;

    // Penalize dead space relative to mean residual, scaled by progress
    score += (mean_residual - pr).max(0.0) * (0.5 + progress);

    // Reward using a tight fit (small post residual) more strongly late in stream
    score -= (cap - pr) * 0.2 * progress;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if next item fits in post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 + 10.0 * progress;
    } else if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 5.0 * (1.0 - progress);
    }

    // Slight penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space in low classes is worse.
    let class = post_residual / 10;
    score += match class {
        0 => -6.0,               // near-perfect fit
        1 => -2.0,
        2 => 0.0,
        3 => 3.0,
        _ => 6.0,                // large dead space
    };

    // Reward exact or near-exact fills nonlinearly.
    if post_residual == 0 {
        score -= 12.0;
    } else if post_residual <= 3 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 4.0 + (slack as f64).min(10.0) * 0.3;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't chain here; penalize proportionally to wasted potential.
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate: only attractive when current fit is very poor.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        if waste > 40.0 {
            score -= 10.0;       // open fresh bin instead of dumping into a roomy one
        } else {
            score += 15.0;       // prefer existing bins for decent fits
        }
    }

    // Penalize bins far above mean residual (fragmentation risk).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold the smallest plausible item are wasted.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fit, extremely desirable
    } else if post_residual <= 10 {
        // small gap likely unusable later -> strong penalty on top of base
        score += 25.0 + (10 - post_residual) as f64 * 2.0;
    } else if post_residual <= 25 {
        score += 8.0;
    }

    // Reward tight fits relative to item size.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 12.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, favor filling existing ones;
    // when few are open, opening a new bin is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 0.8;

    // Prefer bins whose residual is close to the mean (keeps residuals balanced),
    // but only mildly.
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;

    // Lookahead: if the next item fits exactly in the post_residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // next item cannot fit in the gap -> dead space risk
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // New-bin candidate: make it attractive only when the item is large relative
    // to typical residuals or no good fit exists.
    if bin_residual == bin_capacity {
        let fresh_bias = 40.0
            - (item_size as f64 / bin_capacity as f64) * 25.0
            - if fitting_bins_count == 0 { 200.0 } else { 0.0 };
        score += fresh_bias;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // 2-step lookahead: perfect match where next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // exact two-item completion
        } else if next_item_size <= post_residual {
            let next_tightness = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 25.0 * next_tightness;
        } else {
            // next item cannot use this bin's leftover: penalize dead space
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste;
        }
    }

    // Compare against mean residual: bins with residual below mean are scarcer, favor filling them
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Last-chance bonus: only this bin can fit the item
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize opening new bins as stream progresses / many bins open
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (step_index as f64 / (total_items as f64).max(1.0));
        if open_bins_count > 0 {
            score += 5.0;
        }
    }

    // Avoid leaving tiny unusable slivers unless they complete the bin
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: squared post-residual punishes awkward leftover space.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score += slack as f64 * 0.3;
        } else {
            // Next item cannot use the leftover: mild penalty for dead space.
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Crowding: with many open bins, prefer consolidating into existing space.
    let crowd = open_bins_count as f64 / (1.0 + step_index as f64);
    score += crowd * 0.5;

    // Compare bin residual against mean residual: prefer bins with less space (denser bins).
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // Time horizon: early in the stream, allow new bins more freely; later, consolidate hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 6.0;

    // New-bin candidate: only attractive when item is large relative to typical residual
    // (i.e., would leave open bins badly fragmented anyway).
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let fragmentation = (mean_residual - item_size as f64).max(0.0);
        score = 55.0
            - fill_ratio * 30.0
            + fragmentation * 0.6
            + (fitting_bins_count as f64) * 3.0
            - progress * 10.0;
        // A new bin is bad if the next item is small and any open bin could chain-fit.
        if next_item_size > 0 && next_item_size <= 30 && fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover space, with a non-linear (quadratic) dead-space penalty.
    let mut score = pr * (1.0 + norm_pr * norm_pr);

    // Smooth coupling: early in the stream, tolerate larger residuals (keep bins flexible);
    // late in the stream, demand tight fits. Multiply the residual penalty by a progress-scaled factor.
    let tightness = 0.5 + 1.5 * progress * progress;
    score *= tightness;

    // Reward near-perfect fits smoothly (small post_residual gets an extra bonus).
    let perfect_fit_bonus = (1.0 - norm_pr).powi(8) * 10.0;
    score -= perfect_fit_bonus;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement smoothly.
    if next_item_size > 0 {
        let fits_next = (post_residual >= next_item_size) as f64;
        let gap = ((post_residual as i64 - next_item_size as i64).abs()) as f64 / cap;
        score -= fits_next * (1.0 - gap) * 8.0;
    }

    // Slight preference for consolidating into fewer bins when many are open.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Mild pull toward bins whose residual is near the mean residual (smooth normalization).
    score += ((bin_residual as f64 - mean_residual) / cap).powi(2) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues mod 10 and mod 25
    let r10 = post_residual % 10;
    let r25 = post_residual % 25;
    let dead = (r10 == 1 || r10 == 2 || r10 == 3) as f64 * 12.0
        + (r25 == 0) as f64 * (-10.0);

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Small post-residual bands (integer-division thresholds)
    let band = post_residual / 10;
    score += match band {
        0 => -25.0,
        1 => -12.0,
        2 => 0.0,
        3 => 6.0,
        4 => 10.0,
        _ => 14.0,
    };

    // Lookahead coupling: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= (next_item_size as f64) * 0.35;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate penalty unless nothing else is good
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64) * 0.5;
    }

    // Tight bins: residual close to item size
    if bin_residual - item_size <= 5 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Mean-residual alignment
    score += (mean_residual - post_residual as f64).abs() * 0.15;

    // Stream progression: prefer filling existing bins early
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0 - progress * 2.0;

    score += dead;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible item are pure waste. Penalize them quadratically.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) + 9 {
        score += 25.0 * (1.0 + (10 - post_residual as i64) as f64).powi(2);
    }

    // Reward very tight fits (post_residual near zero but usable).
    if post_residual <= 3 {
        score -= 15.0;
    }

    // If the next item can use the leftover space, this bin is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 {
        // Leftover won't serve the lookahead: mild dead-space penalty.
        score += 4.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.6 + 0.4 * progress);

    // New-bin candidate: only attractive when it beats poor fits, i.e. when
    // this bin's residual is large relative to the mean and the item is big.
    if bin_residual == bin_capacity {
        score = 55.0 + open_bins_count as f64 * 0.5 - item_size as f64 * 0.3;
    } else {
        // Prefer fuller bins relative to the fleet mean.
        score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale down score when post_residual is small relative to item size.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * (bin_capacity as f64 - post_residual as f64) * 0.5;

    // Strong reward for exact fit (zero waste).
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual >= next_item_size {
            // Next item fits: mild reward proportional to how well it nests.
            let nest = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 20.0 * nest;
        } else {
            // Next item won't fit: penalize leaving dead space that traps the lookahead.
            score += 15.0;
        }
    }

    // Penalize bins far from mean residual (outliers create fragmentation).
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: make it attractive only when open bins are badly fragmented
    // (high mean residual spread) or when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        // Base penalty so new bins aren't opened casually.
        score += 30.0;
        // But if open bins are fragmented (mean residual low = lots of small holes),
        // opening fresh becomes more attractive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < item_size as f64 * 0.5 && fitting_bins_count <= 2 {
            score -= 40.0 * (0.5 + progress);
        }
        // Late in the stream, prefer consolidating into open bins.
        if progress > 0.8 {
            score += 25.0;
        }
    }

    // Mild preference for bins with larger residual when many bins are open (consolidation).
    score -= (post_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // Penalize small unusable dead space (waste), but tolerate large residuals
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Tight fit bonus: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 60.0 * fill_ratio * fill_ratio;

    // Lookahead: reward bins whose post-residual can host the next item exactly or well
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; mild penalty proportional to overshoot
            score += 8.0;
        }
    } else {
        // Last item: strongly prefer closing bins out
        score -= 100.0;
    }

    // Last-chance bin: if this is the only bin that fits, favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Prefer bins below mean residual (pack into emptier bins, keep tight bins tight)
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Time horizon: early in the stream, be conservative about opening new bins;
    // late in the stream, allow opening fresh bins for large items
    let t = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize early, relax later; penalize more when many bins open
        score += 30.0 + 50.0 * (1.0 - t) + 2.0 * open_bins_count as f64;
        // opening a new bin is fine if item is large relative to capacity
        score -= 40.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Crowd penalty: with many open bins, prefer consolidating into existing ones
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for bins with residual close to item size (best-fit flavor)
    let diff = (bin_residual as i64 - item_size as i64) as f64;
    score += 0.2 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling: waste penalty grows quadratically with
    // residual, modulated by stream progress (late items punish waste more).
    let progress_coupling = 0.5 + 1.5 * progress;
    score += 2.0 * norm_pr * norm_pr * progress_coupling * cap;

    // Reward near-perfect fits with a smooth cubic bonus.
    let fit_quality = 1.0 - norm_pr;
    score -= 3.0 * fit_quality * fit_quality * fit_quality * cap;

    // Last-chance bonus: smooth sigmoid-like reward when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 0.35 * cap * (1.0 + progress);
    }

    // Lookahead coupling: bonus if the next item fits in the post residual,
    // penalized smoothly if it wastes space relative to next item size.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            let slack = (pr - n) / cap;
            score -= 0.5 * cap * (1.0 - slack * slack) * (0.5 + progress);
        } else {
            score += 0.25 * cap * progress;
        }
    }

    // Mild dispersion penalty: bins far from the mean residual are less attractive.
    let dev = (pr - mean_residual) / cap;
    score += 0.3 * dev.abs() * cap * (0.5 + 0.5 * progress);

    // New-bin candidate: penalize opening a fresh bin smoothly, but relax the
    // penalty late in the stream when consolidation matters most.
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        score += (0.8 + 0.1 * open_f) * cap * (1.2 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact fit / near-exact fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Harmonic class logic: partition post_residual into dead-space classes
    // via modulo arithmetic. Residuals that are multiples of small common
    // item sizes are more reusable.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 8.0; // reusable by any item from a 10-grid
        } else if pr % 5 == 0 {
            score -= 4.0;
        }
        // Penalize awkward tiny remainders that waste space.
        if pr < 10 && pr > 0 {
            score += 15.0;
        }
        // Integer-division thresholds: how many "typical" items (say ~30)
        // could still fit.
        let fits_typical = pr / 30;
        score -= 6.0 * fits_typical as f64;
    }

    // Lookahead coupling: if the next item fits the post residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
        // Extra bonus if next item fills it exactly (harmonic pairing).
        if post_residual - next_item_size <= 5 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; mildly penalize leaving large residuals
        // that nothing upcoming can use.
        score += 3.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // the item fits poorly everywhere else. Empty-bin call has
    // bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; adjusted by stream progress and
        // how many bins are already open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 45.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
        // If next item is large, a fresh bin is more attractive.
        if next_item_size >= 50 {
            score -= 10.0;
        }
        // Exact-fit potential with a fresh bin and next item.
        if next_item_size > 0 && next_item_size + item_size == bin_capacity {
            score -= 25.0;
        }
    }

    // Mild preference for bins already below mean residual (consolidating
    // slack into few bins).
    score -= 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals that are too small to fit any future item
    // (min item size 1, but practically small gaps are waste) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 25 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // otherwise we open a new bin and strand this one's residual.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new ones (penalize the new-bin candidate).
    score += 2.0 * open_bins_count as f64;

    // New-bin candidate (empty bin): make it unattractive unless this bin's
    // residual would be badly wasted or the fit is poor.
    if bin_residual == bin_capacity {
        score += 25.0;
        // If current bin residual is small relative to item, new bin may be better:
        if bin_residual < item_size {
            score -= 100.0;
        }
        // Lookahead: if next item is large and this bin can't hold both,
        // opening a fresh bin is reasonable.
        if next_item_size > 0 && next_item_size + item_size > bin_residual {
            score -= 10.0;
        }
    }

    // Lookahead synergy: if the next item fits exactly into post_residual,
    // reward creating that residual (chained packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // residual too small for next item: mild penalty scaled by wasted fraction
        score += 0.2 * (post_residual as f64);
    }

    // Stream progression: later in stream, be more conservative about new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's a good filler bin; if far above, deprioritize slightly.
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: if next item exactly fills post_residual, huge reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // reward chains where the next item also fits reasonably
            let chain_fit = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * chain_fit;
        } else {
            // next item won't fit in the leftover: penalize dead space
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual against mean residual: leaving post_residual near
    // the mean keeps flexibility; tiny unusable leftovers are penalized.
    if (post_residual as f64) < mean_residual * 0.5 && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin before opening a new one: slight reward to avoid new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: only attractive if this item is huge relative to capacity
    // or the stream is early and no good open bin exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score += 15.0 + 20.0 * progress;
        if item_size >= 70 {
            score -= 25.0;
        }
        // penalize new bin if next item would fit here too (keep bins shared)
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score += 10.0;
        }
    }

    // Prefer bins with larger current residual (less fragmentation overall).
    score += 0.05 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on leftover space
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 20.0;

    // Perfect fit gets a strong bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits into the post-residual, this is a great chain
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // exact chain fit is even better
            if next_item_size == post_residual {
                score -= 10.0;
            }
        } else if next_item_size <= post_residual + 10 {
            score += 2.0; // near-miss: mild penalty
        }
        // If next item is large and this placement leaves a large gap, penalize
        if next_item_size > post_residual && post_residual > 25 {
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Compare against mean residual: placing into a bin with residual far below
    // mean (a "small" hole) preserves larger holes for future items
    let residual_gap = mean_residual - bin_residual as f64;
    score += residual_gap * 0.3;

    // Penalize opening new bins when many bins already fit the item
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline cost of a fresh bin
        score = bin_capacity as f64 * 0.9;
        // opening a new bin is more attractive early in the stream
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 15.0;
        // attractive if the item is large (hard to place later)
        score -= (item_size as f64 / 100.0) * 10.0;
        // less attractive if several bins already fit
        score += (fitting_bins_count as f64) * 8.0;
        // if next item could pair with this one in a fresh bin, favor it
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 8.0;
        }
    }

    // Slight preference for bins that are already fairly full
    score -= (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Late in the stream, avoid creating dead space even more strongly
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth polynomial shaping.
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Stream-progress coupling: as the stream advances, tighten tolerance for
    // leftover dead space via a smooth quartic ramp.
    let progress_coupling = 1.0 + 2.0 * progress * progress * (1.0 - 0.5 * progress);
    score *= progress_coupling;

    // Penalize post-residuals that are small-but-unusable relative to the
    // upcoming item: smooth quadratic interaction with next_item_size.
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 0.6 * gap * gap / cap;
        // Reward bins that can also fit the next item (chained fit).
        if pr >= next_item_size as f64 {
            score -= 4.0 * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new
    // bin unless post-residual is terrible (smooth penalty trade).
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - norm_pr);
    }

    // Mild reward when this bin's residual is below the mean residual
    // (compact bin selection), scaled by open-bin count pressure.
    let mean_norm = mean_residual / cap;
    score -= 1.5 * (mean_norm - norm_pr).max(0.0) * (1.0 + open_bins_count as f64 / 10.0);

    // New-bin candidate: make empty bins slightly attractive only when the
    // item is large relative to capacity (smooth term, no hard threshold).
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        score += 2.0 - 3.0 * item_frac * item_frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse when it falls in
    // "awkward" residue classes modulo common item sizes.
    let pr = post_residual;
    if pr > 0 {
        // Penalize dead space that cannot combine with the lookahead item.
        if next_item_size > 0 && pr < next_item_size {
            score += (next_item_size - pr) as f64 * 0.6;
        }
        // Modulo-10 classes: residuals in awkward classes are harder to fill.
        let cls = pr % 10;
        score += match cls {
            1 | 2 | 3 => 3.0,
            8 | 9 => 1.5,
            0 => -2.0,
            _ => 0.0,
        };
        // Integer-division threshold: large leftover halves are still useful.
        if pr >= bin_capacity / 2 {
            score -= pr as f64 * 0.25;
        } else {
            score += (bin_capacity / 2 - pr) as f64 * 0.1;
        }
    } else {
        // Perfect fill: strongly reward.
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 {
            (next_item_size as f64) / bin_capacity as f64
        } else {
            0.5
        };
        score += 12.0 - 10.0 * pressure;
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Tight fit reward: item consumes most of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 {
        score -= 10.0 * (fill_ratio - 0.8);
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Slight preference toward bins below mean residual (keeps balance).
    score += 0.05 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in the "unusable gap" zone
    // (small, unlikely to fit future items) is heavily penalized.
    if post_residual > 0 {
        let dead_threshold = 15.0; // gaps <= 15 are mostly dead space
        if (post_residual as f64) <= dead_threshold {
            score += (dead_threshold - post_residual as f64 + 1.0) * 6.0;
        }
        // Perfect fit gets a strong bonus
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Reward bins whose residual closely matches the item (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 25.0;

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the empty-bin candidate has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64 / 8.0).min(3.0);
        score += 15.0 + pressure * 10.0;
        // If no open bin fits well, allow a new bin more easily
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Lookahead: if next item fits the post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if post_residual is just barely too small for the next item (wasted gap)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Stream progression: early on, be conservative about fragmenting bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (mean_residual - post_residual as f64).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residual too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 2-step lookahead: reward when the next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain match
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64); // near-perfect chain
        } else {
            // next item does not fit here; penalize proportionally to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 0.35 * over;
        }
    }

    // Tight fit reward relative to capacity
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Relative-to-mean residual coupling: prefer bins tighter than average
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Discard new-bin preference unless residuals are fragmented
    if bin_residual == bin_capacity {
        // New bin: neutral-ish score = capacity; add mild penalty so good fits win
        score += 15.0;
        // But if item is large and mean residual is low, opening fresh is fine
        if fill_ratio > 0.7 && mean_residual < item_size as f64 {
            score -= 45.0;
        }
        // Late in stream, avoid opening bins for small items
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress * (1.0 - fill_ratio);
    }

    // Slight penalty for many open bins (encourage consolidation)
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
