    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 60.0;
        } else if gap < 10 {
            score -= 20.0;
        } else {
            score += gap as f64 * 0.15;
        }
    } else if next_item_size > 0 {
        // Next item cannot use leftover: leftover may become waste unless small.
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Compare against mean residual: placing into a bin with residual far below
    // mean concentrates waste in few bins (good); above mean spreads it (bad).
    let dev = (bin_residual as f64) - mean_residual;
    score += dev * 0.25;

    // New-bin candidate handling: only attractive early in the stream or when
    // the item is large and no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mut new_bin_penalty = 20.0 + 60.0 * progress;
        if item_frac > 0.5 && fitting_bins_count <= 1 {
            new_bin_penalty -= 45.0;
        }
        if open_bins_count == 0 {
            new_bin_penalty = -100.0;
        }
        score += new_bin_penalty;
    }

    // Mild pressure to fill already-open bins rather than proliferate.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post_residual, with smooth non-linear shaping
    let mut score = post * (1.0 + 0.5 * norm_post * norm_post);

    // Progress coupling: later in the stream, dead space matters more (smooth polynomial in progress)
    let progress_coupling = 1.0 + 0.8 * progress * progress + 0.4 * progress * progress * progress;
    score *= progress_coupling;

    // Reward tight fits: subtract for small normalized post residual (quadratic reward)
    let tightness = 1.0 - norm_post;
    score -= 6.0 * tightness * tightness * (1.0 + progress);

    // Mean residual interaction: if this bin's post residual is far below mean, it's a good consolidation
    let mean_gap = mean_residual - post;
    score -= 0.15 * mean_gap;

    // Last-chance bonus: only one fitting bin, avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + 0.5 * progress);
    }

    // Lookahead: penalize if next item can't use the post residual
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post < next {
            score += 0.3 * (next - post) * (0.5 + progress);
        } else {
            // reward leaving space the next item can use
            score -= 2.0 * (1.0 - (post - next) / cap);
        }
    }

    // Mild penalty for many open bins to encourage consolidation
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by small classes are "usable"
    let pr = post_residual;
    let class_bonus = match pr % 10 {
        0 => 6.0,
        5 => 3.0,
        2 | 4 | 6 | 8 => 1.5,
        _ => 0.0,
    };
    score -= class_bonus;

    // Exact fill is perfect
    if pr == 0 {
        score -= 40.0;
    }
    // Dead space penalty: small unusable residuals (below smallest plausible item)
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward if next item fits the post residual (chaining)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item won't fit here; penalize leftover that is near but below next size
        let gap = next_item_size as f64 - post_residual as f64;
        if gap < 10.0 {
            score += gap * 0.8;
        }
    }

    // New-bin candidate: score it so it only wins when existing fits are poor.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // base cost of a new bin, slightly cheaper late in stream
        score = cap * 0.75 - 20.0 * progress + (cap - item_size as f64) * 0.15;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Prefer bins with below-average residual (tighter bins first)
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score -= 0.15 * dev;
    }

    // Mild pressure to reuse many open bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that cannot hold even the smallest
    // item are pure waste. Penalize them quadratically.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 + (10 - post_residual as i32).pow(2) as f64 * 3.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= item_size {
        // Residual small enough that this item itself could still fit again:
        // good tight fit.
        score -= 15.0;
    }

    // Reward placements that leave room for the lookahead item (k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 && post_residual < next_item_size.min(10) {
            // Would create dead space relative to the next item.
            score += 12.0;
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Pressure from number of open bins: when many bins are open, prefer
    // packing into existing bins (penalize the new-bin candidate).
    let openness = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty growing with open bins.
        score += 20.0 + openness * 2.0;
        // Opening a bin is more acceptable late in the stream when mean
        // residual is low (few useful gaps remain).
        if mean_residual < 15.0 {
            score -= 25.0;
        }
    } else {
        // Existing bins get a mild bonus when bin count is high.
        score -= openness * 0.5;
        // Prefer the fullest bin among fits: subtract relative fullness.
        score -= (bin_capacity - bin_residual) as f64 * 0.3;
    }

    // Stream progression: early on, keep bins flexible (slight penalty for
    // very tight fits); later, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 8.0;
    if progress < 0.2 && post_residual > 0 && post_residual < 20 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly favored.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // 2-step lookahead: reward if next item fits the post residual (chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward proportional to how well the leftover serves the next item.
            let leftover_gap = (post_residual - next_item_size) as f64;
            score -= 18.0 - 0.35 * leftover_gap;
            if post_residual == next_item_size {
                score -= 25.0; // exact two-item chain fill
            }
        } else {
            // Post residual too small for next item: penalize dead space creation.
            let waste = post_residual as f64;
            score += 0.6 * waste;
            // Extra penalty if next item is large relative to capacity.
            score += 0.3 * (next_item_size as f64 / bin_capacity as f64) * waste;
        }
    }

    // Compare against mean residual across open bins.
    score -= 2.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    // Last-chance bin before opening a new one: strong reward to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer it only when it enables a good future fit
    // and existing residuals are fragmented; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 25.0 + 3.0 * open_bins_count as f64;
        // But if no open bin can chain with the next item, opening is attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
        // Late in the stream, avoid opening bins unless truly needed.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Early stream: be slightly conservative with existing bins to keep flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual is already base score; amplify nonlinearity)
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 20.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize leaving dead space that no future item (min size 1) could plausibly use:
    // small residuals (< 10) are near-wasted unless zero.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            score -= (next_item_size as f64 / post_residual as f64) * 10.0;
        } else {
            // next item won't fit here; slight penalty for fragmenting
            score += 5.0;
        }
    }

    // Time horizon: early in stream, be more willing to open new bins (penalize cramming
    // into many open bins); late in stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (open_bins_count as f64) * 2.0;
    score -= progress * 5.0;

    // Global residual pressure: if mean residual is high relative to item, prefer bins
    // below mean (avoid spreading waste evenly); if low, tighter packing matters more.
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64) * 8.0;

    // New-bin candidate: opening a new bin is attractive early or when the item is large
    // and would leave open bins fragmented. Make it costly when an open bin fits tightly.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.5;
        if fitting_bins_count > 0 {
            // some open bin fits; new bin costs more as stream progresses
            score += 25.0 + progress * 20.0;
            if large_item {
                score -= 10.0; // large items still benefit from fresh bins early
            }
        } else {
            score -= 100.0; // must open a bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Smooth polynomial base: reward tight fits (low post_residual), penalized more heavily at higher x
    let mut score = x.powf(2.0) * (1.0 + 2.0 * progress) * 40.0
        + x * 10.0
        - 30.0 * (1.0 - x).powf(3.0);

    // Exact fit bonus (smooth via x)
    score -= 25.0 * (1.0 - x).powf(6.0);

    // Lookahead: penalize if next item fits post_residual (wasted opportunity elsewhere is fine,
    // but leaving space exactly matching next item is good)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let diff = x - nx;
        score += 12.0 * diff * diff;
        score -= 8.0 * (1.0 - (x / nx).max(0.0)).abs().powf(2.0) * (nx > 0.0 && x >= nx) as i32 as f64;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    }

    // New-bin candidate: penalize unless residuals of open bins are all small (tight packing achieved)
    if bin_residual == bin_capacity {
        let mean_x = mean_residual / cap;
        score += 35.0 * (1.0 - mean_x).powf(2.0);
        score -= 10.0 * progress * (open_bins_count as f64).powf(0.5) / 10.0;
    }

    // Mild penalty for many open bins with large mean residual (fragmentation)
    score += 0.05 * open_bins_count as f64 * mean_residual / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "usable slots"
    // for common item sizes (multiples of 10, 20, 25, 50).
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fit, ideal
    } else {
        let mut bonus = 0.0;
        if pr % 10 == 0 { bonus += 6.0; }
        if pr % 20 == 0 { bonus += 4.0; }
        if pr % 25 == 0 { bonus += 4.0; }
        if pr % 50 == 0 { bonus += 8.0; }
        // dead-space penalty grows when residual falls into awkward narrow band
        if pr < 10 { bonus -= 12.0; } // tiny dead space
        else if pr < 20 { bonus -= 6.0; }
        score -= bonus;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual,
    // or into a harmonic class of it.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0; // exact chain fit
        } else if next_item_size <= pr {
            score -= 10.0 * (next_item_size as f64 / cap);
            if pr % next_item_size.max(1) == 0 {
                score -= 5.0; // residual divisible by next item: multi-fill potential
            }
        } else {
            score += 4.0; // next item won't fit here: mild penalty
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless the
    // current item is large relative to capacity or bins are few.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = item_size as f64 / cap;
        score += 20.0 - 25.0 * large_item - 10.0 * (1.0 - progress);
        if open_bins_count == 0 { score -= 40.0; }
        if next_item_size > 0 && next_item_size as f64 + item_size as f64 <= cap {
            score -= 8.0; // new bin can host a pair
        }
    }

    // Prefer tight fits overall: penalize large waste relative to mean residual.
    let waste = post_residual as f64 / cap;
    score += 8.0 * (waste - mean_residual / cap).abs();

    // Slight preference for filling fuller bins (harmonic quarter classes).
    let fill_class = ((bin_capacity - bin_residual) * 4) / bin_capacity;
    score -= fill_class as f64 * 2.0;

    // Mild regularization with stream progress: later in stream, be greedier.
    score *= 1.0 - 0.1 * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + next_item_size as f64 * 0.1;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0; // creates a gap the next item cannot use
    }

    // Open-bin pressure: with many bins open, discourage spreading; prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.8 + 0.6 * progress);

    // New-bin candidate handling: only attractive when item is huge relative to capacity
    // or no decent fit exists; otherwise penalize opening a new bin.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / cap;
        if fill_frac < 0.7 {
            score += 25.0 + (0.7 - fill_frac) * 60.0;
        } else {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer bins tighter than the current mean residual (consolidation).
    score += (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits (post_residual small).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 60.0 / post_residual as f64;
    }

    // 2-step lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (nr - post_residual as f64).abs() <= 2.0 {
            score -= 80.0; // perfect chain: next item exactly fills leftover
        } else if nr <= post_residual as f64 {
            // next item fits; better if it fills more of the leftover
            score -= 25.0 * (nr / post_residual as f64);
        } else {
            // next item cannot use the leftover: penalize dead space
            score += 15.0 * (nr - post_residual as f64) / 100.0;
        }
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (tighter bins),
    // penalize dumping into very loose bins.
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 0.5 * (res_f - mean_residual);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Penalize creating tiny unusable gaps (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Early in the stream, be slightly more willing to open/use fresh bins;
    // later, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: prefer it early or when open bins are tight on average.
        score -= 30.0 * (1.0 - progress);
        if mean_residual < item_size as f64 {
            score -= 40.0;
        }
    } else {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are good: reward small post_residual non-linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty for wasting residual
            score += 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: only attractive when current fits are poor
    // or the item is large relative to available residuals.
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / bin_capacity as f64;
        let scarcity = 1.0 / fitting_bins_count as f64;
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        let penalty = 90.0 - 55.0 * pressure - 30.0 * scarcity - 2.0 * crowded.min(10.0);
        score += penalty.max(0.0);
        // Empty bin keeps full flexibility; small base reward late in stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Prefer fuller bins overall (relative fill).
    let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 12.0 * fill;

    // Mild preference to spread across many open bins when mean residual is high.
    if mean_residual > 40.0 && open_bins_count > 2 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = 1.0 - (pr / cap); // fraction of bin filled after placement
    let mut score = pr;

    // Smooth polynomial coupling: reward tight fits non-linearly, amplified by stream progress.
    let tightness = fit_frac * fit_frac * fit_frac;
    score -= 24.0 * tightness * (0.5 + progress);

    // Penalize large dead space quadratically (unusable gaps for future items).
    score += 0.06 * pr * pr / cap;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: reward leaving room for the next item if it plausibly fits.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let snug = 1.0 - ((pr - ns) / cap).abs();
            score -= 8.0 * snug * snug;
        } else {
            score += 4.0;
        }
    }

    // New-bin candidate handling: mildly penalize opening a bin unless fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = pr as f64 / cap; // large => item small relative to bin
        score += 10.0 - 18.0 * poor_fit * poor_fit;
    }

    // Mild global balance: prefer bins whose residual deviates from mean in useful ways.
    score += 0.03 * (pr as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals divisible by small
    // granularities are more reusable by typical item sizes.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -50.0 // perfect fill
    } else if pr % 10 == 0 {
        -8.0
    } else if pr % 5 == 0 {
