    } else if pr % 25 == 0 {
        -3.0
    } else {
        0.0
    };
    score += class_bonus;

    // Penalize tiny dead space (< 10 = smallest item class): unusable.
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Lookahead coupling: reward if next item exactly fits the leftover,
    // penalize if next item cannot fit and leftover is stranded.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr && next_item_size >= pr / 2 {
            score -= 6.0;
        } else if next_item_size > pr && pr > 0 && pr < 10 {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): only attractive when this bin would
    // otherwise become badly fragmented or the item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // Prefer new bin when open bins are tight/fragmented and item is big.
        let bias = 18.0 * fragmentation + 10.0 * progress + (item_size as f64 - 50.0) * 0.3;
        score += bias.max(-12.0).min(30.0);
    }

    // Mild penalty for leaving residuals in awkward mid-range classes (e.g. 11..19)
    if (11..=19).contains(&pr) {
        score += 5.0;
    }

    // Small reward for filling large fraction of the bin.
    score -= 10.0 * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // are heavily penalized (unusable gaps below threshold).
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Penalize leaving large gaps that a typical item could still use poorly:
    // prefer bins whose post_residual matches plausible future item sizes.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            // Perfect setup for the lookahead item.
            score -= 80.0;
        } else if gap < 0 && gap > -10 {
            // Next item barely won't fit here: mild penalty, this bin becomes dead space.
            score += 15.0;
        } else if gap > 0 && gap <= 10 {
            // Next item fits with small slack: good.
            score -= 25.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // encourage consolidation when many bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 * (0.5 + progress);
    score += bin_pressure * 0.8;

    // New-bin candidate handling: empty bin gets a baseline cost so it is only
    // chosen when open bins have bad fits.
    if bin_residual == bin_capacity {
        score += 70.0 + mean_residual * 0.2;
    } else {
        // Prefer bins tighter than the mean residual (consolidate fullest bins).
        score -= (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) more aggressively than linearly.
    if post_residual <= 5 {
        score -= 25.0; // near-perfect fit bonus
    } else {
        score += (post_residual as f64 / bin_capacity as f64) * 15.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            // penalize based on leftover after the hypothetical next placement
            score += slack as f64 * 0.4;
            if slack <= 5 {
                score -= 12.0;
            }
        } else {
            // next item won't fit here; slight penalty proportional to overshoot
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Compare against mean residual: bins with residual far below mean are
    // "small leftovers" — prefer filling them to consolidate space.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no existing bin gives a decent fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if post_residual as f64 >= mean_residual + 0.5 * bin_capacity as f64
            && fitting_bins_count > 0
        {
            // penalize opening a new bin when open bins could fit
            score += 30.0;
        } else if fitting_bins_count == 0 {
            score -= 10.0; // only option
        }
    }

    // Early in the stream, slightly prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 / open_bins_count.max(1) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively than linear.
    let tight = post_residual as f64 / bin_capacity as f64;
    score += tight * tight * 40.0;

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Dead-space penalty: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: bonus if the next item fits into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + (next_item_size as f64 / bin_capacity as f64) * 10.0;
        } else {
            // Penalize creating a residual that wastes future capacity.
            score += (next_item_size as f64 - post_residual as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Crowding: when many bins are open, prefer consolidation; when few, allow spread.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowd = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += crowd * 0.5 * (0.5 + progress);

    // Prefer bins with residual close to item_size (minimal waste) relative to mean.
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += diff * 0.08;

    // New-bin candidate: penalize opening a bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        let base = 30.0;
        let pressure = if fitting_bins_count == 0 { -100.0 } else {
            (mean_residual - item_size as f64).max(0.0) * 0.6
        };
        score += base + pressure + progress * 10.0;
    }

    // Mild preference for bins whose residual exceeds item size by a "useful" margin.
    if post_residual >= 20 && post_residual <= 50 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with non-linear polynomial shaping
    let mut score = pr;

    // Smooth polynomial coupling: post_residual interacting with stream progress
    // Early on (progress ~ 0): mild preference for tight fills.
    // Late (progress ~ 1): strongly penalize wasted residual (dead space).
    let poly = norm_pr * norm_pr * (0.5 + 2.5 * progress * progress) * cap;
    score += poly;

    // Cubic interaction: penalize medium residuals more as stream progresses
    score += norm_pr * norm_pr * norm_pr * cap * (progress * (1.0 - progress) * 4.0);

    // Reward fitting into a bin when alternatives are scarce
    if fitting_bins_count == 1 {
        score -= 8.0 + 20.0 * progress;
    } else {
        score += (fitting_bins_count as f64 - 1.0).min(5.0) * (1.0 + 3.0 * progress);
    }

    // Lookahead: bonus if next item fits into resulting post-residual (smooth kernel)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let kernel = (-gap / 25.0).exp();
        score -= 12.0 * kernel * (0.5 + progress);
        // Slight penalty if next item leaves a tiny awkward residual
        if next_item_size as f64 > pr {
            score += 4.0 * (1.0 - progress);
        }
    }

    // Deviation from mean residual: prefer bins whose residual is atypical-large
    // (use them up) with smooth quadratic coupling to progress
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= dev * (6.0 + 10.0 * progress * progress) * 10.0;

    // Mild penalty for opening new bins early; smooth decay over stream
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 30.0 + open_bins_count as f64 * 2.0;
    }

    // Small tie-breaker on exact fills
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let pr = post_residual;
    let mut score = pr as f64;

    // ---- NEW BIN CANDIDATE (empty bin) ----
    if bin_residual == bin_capacity {
        // Baseline: opening a new bin is expensive; only attractive when no
        // open bin fits (fitting_bins_count == 0) or all fits are terrible.
        let mut nb = cap * 0.85 + open_bins_count as f64 * 1.5;
        if fitting_bins_count == 0 {
            nb -= cap * 0.6; // forced: nothing else fits
        }
        // Lookahead: if the next item is at least as big as this one, a fresh
        // bin is more valuable (it can host the big next item too).
        if next_item_size >= item_size && next_item_size > 0 {
            nb += 8.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        nb += progress * 12.0;
        return nb;
    }

    // ---- HARMONIC CLASSES on post_residual ----
    // Residuals that are multiples of 10 (and 20/25/50) are "harmonic" with
    // typical item sizes; reward low residue classes.
    let residue10 = (pr % 10) as f64;
    score += residue10 * 0.35;
    if pr % 20 == 0 { score -= 3.0; }
    if pr % 25 == 0 { score -= 3.0; }
    if pr % 50 == 0 { score -= 4.0; }

    // Dead-space classes: post_residual in ranges that no item (1..=100)
    // can usefully fill are the worst.
    if pr == 0 {
        score -= 45.0; // perfect fit
    } else if pr < 10 {
        score -= 22.0; // nearly perfect: only tiny items can follow
    } else if pr > 80 {
        score += 6.0; // large leftover: bin was underfilled
    }

    // ---- LOOKAHEAD (k=2) ----
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= pr {
            // chain fit: next item lands here too -> strong reward,
            // scaled by how snugly the pair packs.
            score -= 14.0 + (1.0 - (pr as f64 - nxt) / cap) * 8.0;
        } else {
            // next item won't fit here: penalize proportional to overshoot
            score += (nxt - pr as f64) * 0.45;
        }
    }

    // ---- LAST-CHANCE BONUS ----
    if fitting_bins_count == 1 {
        score -= 26.0; // this is the only bin that can take the item
    } else {
        // competition: more fitting bins -> prefer the tightest anyway (score already does)
        score += fitting_bins_count as f64 * 0.3;
    }

    // ---- GLOBAL COUPLINGS ----
    // Penalize using a large-residual bin for a small item (waste of space).
    score += (bin_residual as f64 - item) * (1.0 - item / cap) * 0.08;

    // Prefer bins whose residual is below the mean residual (tighter than average).
    score += (mean_residual - pr as f64) * 0.06;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps left over are almost unusable
    // (items are >= 1, but typical items are much larger), so quadratically
    // penalize small positive post_residual.
    if post_residual > 0 {
        let p = post_residual as f64;
        let dead_zone = 20.0; // gaps <= 20 are treated as dead space
        if p < dead_zone {
            score += (dead_zone - p) * (dead_zone - p) * 0.5;
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64).max(1.0);
        score -= tightness * 15.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are open;
    // conversely, mildly favor consolidating into existing bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when item is large relative to
        // remaining gaps or next item needs the space.
        score += 30.0 + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && next_item_size > post_residual.max(0) && post_residual >= next_item_size {
            score -= 10.0; // (defensive; post_residual==cap here so rarely true)
        }
        // Large items justify a fresh bin more than small ones.
        score -= (item_size as f64) * 0.35;
    } else {
        // Using an existing bin slightly reduces pressure as bins accumulate.
        score -= open_bins_count as f64 * 0.5;
    }

    // Lookahead: if the next item would fit exactly in the post residual,
    // reward this placement (chaining fits).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_after_next = post_residual - next_item_size;
        if gap_after_next == 0 {
            score -= 30.0; // perfect two-item chain
        } else if (gap_after_next as f64) < 20.0 {
            score += 10.0; // would create dead space after next item
        } else {
            score -= 8.0;
        }
    }

    // Late in the stream, be more conservative: prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is an outlier bin; prefer filling it to normalize the pool.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= (mean_residual - bin_residual as f64) * 0.1;

    // Clamp deviation influence to avoid instability.
    if dev > 80.0 {
        score += (dev - 80.0) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward when the next item fits exactly into the post-residual (perfect 2-step chain).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - slack * 0.8; // perfect match (slack 0) gets big reward
    }

    // Penalize post-residuals that are too small for the next item (dead space for lookahead).
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Compare residual against mean residual: prefer tighter-than-average bins.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Late in the stream, consolidate: penalize opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 40.0 + 60.0 * progress; // new-bin candidate penalty
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 30.0; // new bin is great if next item needs full space
        }
    }

    // Mild preference for high fill ratio.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual), strongly for perfect fit
    if post_residual == 0 {
        score -= 500.0;
    } else {
        score -= (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 120.0;
    }

    // Penalize dead space that cannot fit typical items
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // sliver waste
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 200.0;
    } else if fitting_bins_count > 1 {
        score += 15.0 * (fitting_bins_count as f64 - 1.0).log2();
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 80.0;
        // extra reward if next item fills perfectly after this
        if post_residual == next_item_size {
            score -= 120.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // post_residual too small for next item: penalize proportionally
        score += 0.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Global state: prefer filling bins when many bins are open (reduce fragmentation)
    let open_f = open_bins_count as f64;
    score -= 3.0 * open_f.min(40.0);

    // Mean residual coupling: if this bin's residual is far below mean, it's a poor bin to leave
    let res_f = bin_residual as f64;
    let dev = res_f - mean_residual;
    score += 0.3 * dev;

    // Time horizon: early in stream, be more conservative about opening new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_penalty = 150.0 * (1.0 - 0.5 * progress);
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
    } else {
        score -= 40.0 * (1.0 - progress); // prefer existing bins early on
    }

    // Slight preference for bins whose residual is close to item (best-fit flavor)
    score += 0.2 * (res_f - item_size as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer tight fits, penalize wasted space quadratically
    let mut score = pr as f64;
    score += 30.0 * x * x;

    // Smooth stream-progress coupling: later in stream, value tight packing more
    score -= (1.0 - progress) * 10.0 * x;

    // Non-linear interaction: post_residual vs mean residual divergence
    let dev = (mean_residual - pr) / cap;
    score += 8.0 * dev * dev - 4.0 * dev * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: if next item fits into post residual, reward this placement
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let nx = next_item_size as f64 / cap;
        score -= 12.0 * (1.0 - nx) * (1.0 - progress);
    } else if next_item_size > 0 {
        // next item won't fit here; mild penalty scaled by leftover dead space
        score += 6.0 * x * x * progress;
    }

    // Penalty for opening new bins when many already open and space is plentiful
    let ob = open_bins_count as f64;
    score += 0.5 * (ob / (ob + 5.0)) * (1.0 - progress) * (x * cap - 10.0).max(0.0);

    // New-bin candidate: penalize opening a fresh bin unless residual would be tiny
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.9 {
        score -= 60.0;
    } else if fit_ratio > 0.75 {
        score -= 35.0;
    } else if fit_ratio > 0.5 {
        score -= 10.0;
    }

    // Harmonic classes of post_residual: dead space in low-value residue classes is worse.
    let pr = post_residual;
    let small_dead = if pr == 0 { 0.0 }
        else if pr <= 5 { 45.0 }
        else if pr <= 10 { 25.0 }
        else if pr <= 20 { 10.0 }
        else { 0.0 };
    score += small_dead;

    // Modulo classes on post_residual: residuals divisible by common small item sizes
    // (2,5,10) remain reusable; odd/prime-ish leftovers are dead space.
    if pr > 0 {
        let reusable = (pr % 10 == 0) as i32 * 2 + (pr % 5 == 0) as i32 + (pr % 2 == 0) as i32;
        score -= reusable as f64 * 4.0;
        // Prime-like residuals are hard to fill
        if pr % 2 != 0 && pr % 5 != 0 && pr % 3 != 0 && pr > 3 {
            score += 6.0;
        }
    }

    // Integer-division thresholds: residual bucket vs next item size.
    if next_item_size > 0 {
        if pr >= next_item_size {
            // This bin can also serve the next item: reward chain potential.
            let chain_fit = (pr - next_item_size) as f64;
            score -= (chain_fit / 10.0).min(15.0);
        } else {
            // Next item cannot follow here; leftover is likely final dead space.
            score += 8.0;
        }
        // Harmonic alignment: post_residual is an integer multiple of next item size
        if next_item_size > 0 && pr % next_item_size == 0 && pr > 0 {
            score -= 12.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else if fit_ratio < 0.5 && pressure < 0.25 {
            score -= 12.0; // poor fits everywhere and bins are quite full
        } else {
            score += 25.0; // prefer existing bins generally
        }
    }

    // Mild exploration: early in the stream, tolerate opening bins for big items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if item_size > 60 && progress < 0.2 {
        score -= 3.0;
    }

    // Slight preference to equalize residuals toward mean (balance load).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever fit the next
    // item (or a minimum plausible item) are heavily penalized.
    let min_useful = if next_item_size > 0 { next_item_size.min(80) } else { 10 };
    if post_residual < min_useful {
        // Dead space: scale penalty by how far below usable range we fall.
        let dead = (min_useful - post_residual) as f64;
        score += 3.0 * dead + 8.0;
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual <= 3 {
        score -= 10.0;
    }

    // Reward tight fits relative to residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 5.0 * fit_ratio;

    // Last chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // encourage consolidation when bins are few.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when item is large and would
        // leave a clean residual, or when existing bins are very fragmented.
        score += 15.0 * (open_bins_count as f64 / (1.0 + mean_residual / 10.0));
        if item_size >= 50 && post_residual >= 10 {
            score -= 5.0;
        }
        if post_residual > 0 && post_residual < min_useful {
            score += 10.0; // new bin with immediate dead space is bad
        }
    } else {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mean residual coupling: prefer bins whose residual is near the mean
    // (balanced packing), penalize outliers creating fragmentation.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Slight preference for using older bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward when the next item exactly fills the remaining space.
        if diff == 0.0 {
            score -= 60.0;
        } else if diff <= 5.0 {
            score -= 30.0 - diff * 4.0;
        } else if diff <= 15.0 {
            score -= 10.0 - diff * 0.3;
        } else {
            // Large mismatch: dead-space penalty grows with gap.
            score += diff * 0.5;
        }

        // If next item cannot fit anywhere else but fits here after placement, reward strongly.
        if next_item_size <= post_residual && fitting_bins_count <= 2 {
            score -= 25.0;
        }
        // If next item would NOT fit in post_residual, mild penalty for stranding space.
        if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    } else {
        // Last item: prefer tightest fill.
        score -= 10.0;
    }

    // Compare against mean residual: bins tighter than average are good targets.
    let resid = post_residual as f64;
    if resid < mean_residual {
        score -= (mean_residual - resid) * 0.6;
    } else {
        score += (resid - mean_residual) * 0.3;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count == 2 {
        score -= 12.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // open bins are all nearly full or the fit here is bad.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // If open bins are loose (high mean residual), opening new bin is wasteful.
        score += 55.0 * (1.0 - pressure);
        // Early in stream, opening bins is fine; later, avoid fragmentation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Reward near-perfect fills directly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Slight preference to keep fewer bins open (consolidation).
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    score -= 0.5 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(4) * (bin_capacity as f64);

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: reward if the next item fits exactly in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here: penalize leaving a large awkward gap.
            score += 0.3 * post_residual as f64;
        }
    } else {
        // Last item: prefer perfect fill above all.
        score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent open bins exist and stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        score += 15.0 * (1.0 - progress) * (1.0 + open_pressure);
        // But if mean residual is small (open bins nearly full), new bin is fine.
        score -= 0.2 * mean_residual;
        // If item is large and few bins fit it, opening a new bin is reasonable.
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Mild preference for bins already below mean residual (balance load).
    score += 0.1 * (mean_residual - bin_residual as f64);

    // Slight time-decay on waste tolerance: later in stream, be tighter.
    score += 0.05 * (step_index as f64 / total_items.max(1) as f64) * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += 12.0 * norm_pr * norm_pr * (0.5 + p2);
    score -= 8.0 * norm_pr * (p3 * 1.5 + 0.5);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 14.0 * tightness * (0.4 + progress);

    // Lookahead coupling: favor bins whose post_residual fits the next item
    if next_item_size > 0 && (post_residual as u64) >= next_item_size as u64 {
        let nxt = next_item_size as f64 / cap;
        score -= 10.0 * nxt * (1.0 - norm_pr) * (0.5 + p2);
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - norm_pr) * (0.3 + progress);
    }

    // Penalize creating dead space relative to mean residual
    let dead = (pr - mean_residual).max(0.0) / cap;
    score += 9.0 * dead * dead * (1.0 + p3);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (0.5 + progress);
    }

    // Mild encouragement to reuse open bins vs. new-bin candidate
    if bin_residual != bin_capacity {
        score -= 2.0 + 3.0 * progress;
    } else {
        score += 3.0 + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "usable" residue classes (multiples of common item sizes) are favored.
    let cap = bin_capacity as f64;
    let fill = (bin_capacity - post_residual) as f64 / cap; // occupancy fraction

    // Reward tight fits (post_residual near 0 or small dead space).
    if post_residual == 0 {
        score -= 50.0; // perfect closure
    } else if post_residual <= 10 {
        score -= 25.0;
    } else {
        // Penalize dead space that no typical item (>=1, but large items dominate)
        // can fill: post_residual in awkward ranges.
        if post_residual > 50 {
            score += 6.0; // bin left too empty -> wasteful placement
        }
        // Modulo-class reward: leftover divisible by small common sizes is
        // more likely reusable by future items.
        let pr = post_residual;
        let mut reusable = 0.0;
        if pr % 10 == 0 { reusable += 8.0; }
        if pr % 5 == 0 { reusable += 3.0; }
        if pr % 20 == 0 { reusable += 4.0; }
        if pr % 25 == 0 { reusable += 3.0; }
        if pr % 50 == 0 { reusable += 4.0; }
        score -= reusable;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0;
        if next_item_size == post_residual {
            score -= 22.0; // chain-closing pair
        }
        // Harmonic coupling: next item leaves another clean residue.
        if (post_residual - next_item_size) % 10 == 0 {
            score -= 6.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space: next item cannot use this leftover.
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Many open bins: encourage closing bins (low post residual) to limit spread.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let spread_pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += spread_pressure * (post_residual as f64 / cap) * 4.0;

    // Prefer bins below mean residual (tighter bins) to keep residuals balanced.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when nothing fits well; make an empty
    // bin moderately costly so we prefer existing bins unless they are bad.
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 10.0; // existing bins can host; opening new bin is wasteful
        }
        if next_item_size > 0 && next_item_size >= 70 {
            score -= 15.0; // big upcoming item: fresh bin is valuable
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals in [1, 9] are nearly unusable (min item = 1..100 unknown,
    // but tiny gaps rarely match) — penalize heavily with a quadratic bump.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0 - 2.0 * post_residual as f64;
    }
    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Small-but-usable residual that still fits the lookahead item: reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Lookahead just barely misses: penalize near-miss gaps.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Tightness reward: fraction of bin filled by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins; encourage closing bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 1.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last chance before opening a new bin: strong reward to use this bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only when open bins are few or item is huge.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / 8.0 + fill_ratio;
        score -= 5.0 * pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            // chain fit quality: small leftover after the chained placement is great
            score -= 150.0 * (1.0 - leftover as f64 / bin_capacity as f64);
            if leftover < 10 {
                score -= 100.0;
            }
        } else {
            // next item won't chain here; penalize proportionally to the gap
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize wasting a nearly-full bin on a tiny item
    if item_size < post_residual / 4 && post_residual > 30 {
        score += 50.0;
    }

    // New-bin candidate: only attractive when existing bins would leave large dead space
    if bin_residual == bin_capacity {
        score += 40.0 + 0.5 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: late in the stream, prefer filling existing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Tightness of fit: exact or near-exact fits are heavily rewarded.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many open bins: discourage spreading; prefer bins below mean residual (already loose).
    if open_bins_count > 1 {
        let diff = mean_residual - bin_residual as f64;
        score += 0.15 * diff;
        score += 0.5 * open_bins_count as f64;
    }

    // Time horizon coupling: early on, tolerate opening new bins; late, penalize them.
    let new_bin_penalty = 10.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
        // A new bin is attractive for very large items or when nothing fits well.
        if item_size > bin_capacity / 2 {
            score -= 6.0 * (item_size as f64 / bin_capacity as f64);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;
    let fit_norm = item_size as f64 / cap;
    let mut score = post;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer tight fills (low post_residual); later, tolerate residual
    // slightly more but penalize dead space super-linearly.
    let progress_coupling = 1.0 + 0.8 * progress - 0.6 * progress * progress;
    score += 6.0 * progress_coupling * post_norm * post_norm * cap;

    // Penalize residual that cannot fit the lookahead item (dead space).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            let deficit = (nxt - post) / cap;
            score += 12.0 * deficit * deficit * cap;
        } else {
            // Reward bins that keep the next item fitting snugly.
            let snug = (post - nxt) / cap;
            score -= 4.0 * (1.0 - snug) * (1.0 - snug);
        }
    }

    // Reward filling bins nearly completely (smooth non-linear bonus).
    score -= 8.0 * (1.0 - post_norm) * (1.0 - post_norm) * (1.0 - post_norm) * cap * 0.1;

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * fit_norm;
    }

    // Mean residual coupling: prefer bins deviating below mean residual (tighter bins).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev - 2.0 * dev;

    // New-bin candidate: penalize so it is only chosen when all open fits are poor.
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress;
        // But if the item is huge relative to capacity and few bins fit it,
        // soften the penalty (opening a fresh bin for a big item is fine).
        score -= 12.0 * fit_norm * fit_norm;
    }

    // Mild open-bin pressure: with many open bins, favor consolidating into them.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let mut score = pr;

    // Perfect fit: dominant choice, nothing else can compete.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // New-bin candidate detection: fresh empty bin.
    let is_new_bin = bin_residual == bin_capacity;

    // --- Harmonic class structure on post_residual (deciles of capacity) ---
    let pr_class = (post_residual / 10).min(9) as f64; // 0..9

    // Convex amplification: penalize loose fits super-linearly (stronger Best Fit).
    score += 0.006 * pr * pr;

    // Round-number harmony: residuals on capacity-friendly grids are more
    // likely to be exactly consumed by future items.
    if post_residual % 25 == 0 {
        score -= 6.0;
    } else if post_residual % 10 == 0 {
        score -= 3.0;
    }

    // Sliver residuals (class 0: 1..9): near-dead space; bump so marginal
    // tight fits don't crowd out slightly larger, more usable residuals.
    if pr_class == 0.0 {
        score += 4.0;
    }

    // --- Lookahead coupling with next_item_size (k=2) ---
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            // Perfect pairing: this bin is exactly completed by the next item.
            score -= 400.0;
        } else if next_item_size < post_residual {
            // Next item fits after this one: reward proportional to pair fill.
            score -= 0.35 * nx + 8.0;
            let pr2 = post_residual - next_item_size;
            if pr2 % 10 == 0 {
                score -= 5.0; // pair leaves a round residual too
            }
        } else {
            // Next item cannot use this residual: penalize by shortfall,
            // scaled by next item's size class (integer division thresholds).
            let nx_class = (next_item_size / 20).min(4) as f64; // 0..4
            score += 0.10 * (nx - pr) + 1.5 * nx_class;
        }
    }

    // --- Last-chance dynamics ---
    if fitting_bins_count == 1 && !is_new_bin {
        // Only open bin that fits: prefer using it over opening a new bin.
        score -= 25.0 + 0.25 * it;
    }

    // --- New-bin candidate calibration ---
    if is_new_bin {
        // Default: prefer existing bins; new bin must win on raw merit.
        score += 18.0 + 0.6 * open_bins_count as f64;
        // If open bins carry plenty of mean residual, discourage a new one.
        score += 0.05 * (mean_residual - pr).max(0.0);
    }

    // --- Progress modulation: late in the stream, tighten greedily ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * progress * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 15.0;
    }

    // Reward tight fits: post_residual near zero (exact or near-exact fill).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last-chance bin pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin count pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 8.0 + (open_bins_count as f64) * 1.5;
    } else {
        score -= 2.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if next item almost fits but not quite (would leave awkward split).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Slight preference for filling bins with larger residuals early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_residual as f64 / bin_capacity as f64) * (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near-perfect match: next item fits with small waste
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // reward tight fits for the two-item chain
        score -= 40.0 / (1.0 + slack / 10.0);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // next item won't fit here: penalize proportionally to how wasted the residual is
        let unusable = (next_item_size - post_residual) as f64;
        score += unusable * 0.6;
    }

    // Penalize dead space relative to mean residual (fragmentation)
    let residual_f = post_residual as f64;
    if residual_f > mean_residual * 1.5 {
        score += (residual_f - mean_residual * 1.5) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Reward filling bins very tightly (post residual small but not zero-waste for next)
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0;
    }

    // Early in stream: slightly prefer keeping residuals flexible (larger post_residual)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * residual_f * 0.05;

    // New-bin candidate: mild penalty so open bins are preferred unless fit is terrible
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward bins where the lookahead item still fits afterward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leaving dead space the next item cannot use.
        score += 0.15 * post_residual as f64;
    }

    // Reward tight fits (low post residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize spreading across many open bins when mean residual is high
    // (bins are fragmented); encourage consolidation into emptier bins.
    score += 0.05 * mean_residual * (open_bins_count as f64).ln().max(1.0);

    // Progress horizon: later in the stream, prefer closing bins tightly
    // (avoid many nearly-empty bins at the end).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 0.10 * post_residual as f64;

    // New empty bin candidate: it has maximal residual, so by default it
    // loses; but if the item is large and no open bin fits well, give the
    // fresh bin a fair shot via a calibrated discount.
    if bin_residual == bin_capacity {
        let large = (item_size as f64) / (bin_capacity as f64);
        score -= 20.0 * large * large * (1.0 - progress);
    }

    // Mild penalty for wasting a big residual on a tiny item.
    if item_size < bin_residual / 4 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // smooth non-linear coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 40.0 * poly;

    // tight fits are better late in the stream
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // penalize dead space relative to mean residual, scaled by progress
    score += 10.0 * (pr - mean_residual) / cap * (0.5 + progress);

    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress + 0.5);
    }

    // lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 15.0 * (1.0 - ((pr - nxt) / cap).abs());
        } else {
            score += 12.0 * ((nxt - pr) / cap);
        }
    }

    // discourage opening new bins when good fits exist
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - norm_pr) + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction bands.
    // post_residual in [0, cap); classes: tiny (<5), low (<20), mid (<35), high (<50), open (>=50)
    let pr = post_residual as f64;
    if pr < 5.0 {
        // near-perfect fit: strong reward
        score -= 60.0;
    } else if pr < 20.0 {
        // dead-space class: penalize, but less if another item may still fit
        score += 10.0;
        if next_item_size as f64 > pr {
            score += 15.0;
        }
    } else if pr < 35.0 {
        // mid band: mildly good
        score -= 10.0;
        if next_item_size as f64 <= pr {
            score -= 20.0;
        }
    } else if pr < 50.0 {
        // high band: keep residual usable for future mid items
        score -= 5.0;
        if next_item_size as f64 <= pr {
            score -= 15.0;
        }
    } else {
        // large residual left: wasteful placement of a small item
        score += 12.0;
        if next_item_size as f64 <= pr {
            score -= 8.0;
        }
    }

    // Integer-division thresholds on next_item_size (harmonic classes of lookahead)
    let ni = next_item_size;
    if ni > 0 {
        let ni_class = ni / 25; // 0,1,2,3 harmonic classes of lookahead size
        match ni_class {
            0 => {
                // tiny lookahead: any residual >= ni works; reward tight fits
                if post_residual >= ni {
                    score -= 10.0;
                }
            }
            1 => {
                if post_residual >= ni {
                    score -= 14.0;
                }
            }
            2 => {
                if post_residual >= ni {
                    score -= 18.0;
                }
            }
            _ => {
                // big lookahead: prefer bins whose post_residual still hosts it
                if post_residual >= ni {
                    score -= 22.0;
                } else {
                    score += 8.0;
                }
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral baseline, slightly penalized so we prefer
    // existing bins unless all are poor fits; scale penalty with how full
    // existing bins are (mean_residual).
    if bin_residual == bin_capacity {
        score = 55.0 + mean_residual * 0.2;
        // allow opening new bin late in stream when many bins are open
        if open_bins_count > 8 {
            score -= 5.0;
        }
    }

    // Stream progression coupling: early on, keep bins loose (favor larger residuals);
    // late, prefer tight packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (pr * 0.15);
    score -= progress * (cap - pr) * 0.05;

    // Modulo tie-breaker on post_residual to prefer residuals in nice classes (multiples of 10)
    if post_residual % 10 == 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that is too small to hold even the smallest plausible item is dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Bonus for residual that still accommodates the lookahead item (chain fits).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Residual too small for the next item: likely dead space unless tiny.
        score += 12.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, unless the fit would create dead space.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if post_residual < 10 && post_residual > 0 {
            score += 20.0; // undo bonus if it creates dead space
        }
    }

    // Open-bin pressure: with many open bins, discourage opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to pressure and mean residual.
        score += 45.0 + bin_pressure * 10.0 + mean_residual * 0.3;
    } else {
        // Slight preference for filling bins with larger residuals (larger mean usage).
        score -= (bin_residual as f64 - mean_residual) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fits (low post_residual), but not too tight.
    if post_residual == 0 {
        score -= 30.0; // perfect fit is excellent
    } else if post_residual < 10 {
        score += 5.0; // tiny dead space is nearly useless
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + diff * 0.15); // closer post_residual to next item => better
        if post_residual as i64 == next_item_size as i64 {
            score -= 25.0; // exact 2-step chain
        }
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0; // dead space that cannot host next item
        }
    } else {
        // Last item: only tightness matters
        score -= 15.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 0.9 + open_bins_count as f64 * 0.5;
        // Allow a new bin when the item would leave a large hole in an existing bin
        // and no exact 2-step chain exists.
        if post_residual == bin_capacity {
            if next_item_size > 0 && (bin_residual as i64 - next_item_size as i64).abs() <= 5 {
                score -= 60.0; // fresh bin chains perfectly with next item
            }
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.2;

    // Stream progression: late in stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_residual - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space.
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Last-chance bin: strong incentive to use it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        if slack as u32 == 0 {
            score -= 30.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Post residual too small for next item: penalize proportional dead space.
        score += 0.5 * waste;
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, softened late in stream or with many bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64 * (0.9 + 0.3 * progress) + 0.1 * open_bins_count as f64;
        // If next item is large, opening fresh may be attractive.
        if next_item_size > 0 && next_item_size >= 70 {
            score -= 45.0;
        }
        // If this is a last-chance situation, never open a new bin.
        if fitting_bins_count == 1 {
            score += 500.0;
        }
    }

    // Prefer bins below mean residual (consolidate space) mildly.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 0.15 * (mean_residual - res);
    } else {
        score += 0.05 * (res - mean_residual);
    }

    // Time-horizon modulation: early stream, be conservative with tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap;

    let mut score = post;

    // Non-linear dead-space penalty: cubic in normalized post-residual
    score += 12.0 * x * x * x * cap * (0.5 + 0.5 * progress);

    // Reward tight fits (small post_residual) increasingly as stream progresses
    score -= (1.0 - x).powi(3) * 10.0 * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Lookahead coupling: reward if next item fits into post_residual
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let fit_quality = 1.0 - ((post - next_item_size as f64) / cap);
        score -= 6.0 * fit_quality * (1.0 - progress);
    } else if next_item_size > 0 {
        // Penalize leaving space unusable by next item
        score += 4.0 * x * (1.0 - progress);
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.5 * (post - mean_residual) * (0.5 + progress);

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.15 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity-fraction buckets.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let class = (post / cap * 4.0).floor(); // 0..=3 harmonic quarter classes
    match class as u32 {
        0 => score += 25.0,           // near-perfect fill, dead space almost zero
        1 => score -= 10.0,           // usable small leftover
        2 => score -= 18.0,           // half-capacity leftover, very reusable
        _ => score -= 8.0,            // large leftover, wasteful but flexible
    }

    // Integer-division threshold on post_residual: leftovers divisible into common item classes
    if post_residual % 10 == 0 {
        score -= 6.0; // leftover aligns with decile item classes (10..80 multiples)
    }

    // Lookahead: does next item fit in the post residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Harmonic match bonus scaled by how snugly next item fits
        let snug = (post_residual - next_item_size) as f64;
        score -= 12.0 + snug * 0.15;
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to how much it overshoots
        score += (next_item_size - post_residual) as f64 * 0.10;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize opening a new bin when open bins with reasonable residual exist
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.20;
        // But allow new bin early in stream or when open bins are crowded
        if open_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 12.0;
        }
    }

    // Progress-aware mild tightening: later in stream, prefer tighter fills
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post * 0.05 * progress;

    // Penalize bins far from mean residual (keep pool homogeneous)
    score += ((post - mean_residual).abs()) * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 40.0 * (10.0 - dead); // tiny gap => very bad
    } else if dead < 20.0 {
        score += 8.0 * (20.0 - dead);
    }

    // Reward tight fits (small post_residual relative to item).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item can't use the leftover gap: penalize proportional to gap size if gap is awkward
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.15 * post_residual as f64;
        }
    }

    // Open-bin pressure: discourage spreading across too many bins.
    score += 1.2 * open_bins_count as f64;

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive if current bins would leave bad dead space
    // or no bin fits well. Fresh empty bin keeps full flexibility.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: new bin is mandatory
        } else if post_residual < 10.0 || fit_ratio > 0.9 {
            score += 55.0; // existing bins give a great fit; don't open new bin
        } else {
            // mild preference for new bin when fits are mediocre
            score -= 5.0 + 0.1 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor exact fits (post_residual near zero is already low; deepen reward)
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // 2-step lookahead: if the next item fits perfectly into post_residual, big bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize leaving residual it can't use
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Compare residual against mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin when decent fits exist, especially early in the stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        let waste = (bin_capacity - item_size) as f64;
        score += 25.0 + waste * (1.0 - progress) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a superlinear penalty on waste.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Reward perfect fit strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits into post_residual, bonus; if it would
    // be blocked by this placement, penalize proportionally.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            let blocked = (next_item_size - post_residual) as f64;
            score += 0.25 * blocked;
        }
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global congestion: when many bins are open and mean residual is small,
    // discourage spreading; when mean residual is large, encourage filling.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (mean_residual - post_residual as f64) * (0.15 + 0.35 * progress);

    // Prefer bins whose residual is already close to the item (best-fit flavor).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 20.0 * tightness;

    // New-bin candidate handling: an empty bin should only win when the item
    // is large or fits are poor elsewhere.
    if bin_residual == bin_capacity {
        // Baseline handicap so open bins with decent fits win.
        score += 8.0;
        if item_size >= 50 {
            score -= 20.0; // large items benefit from a fresh bin
        }
        if post_residual > 0 && post_residual < 20 {
            score -= 5.0; // fresh bin leaves a usable small residual
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Mild late-stream pressure to consolidate into fewer bins.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling: reward tight fits more as stream progresses.
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let tightness = 1.0 - norm_post; // 0 = empty, 1 = perfectly full
    score -= tightness * tightness * (1.0 + 2.0 * progress) * 20.0;

    // Penalize dead space quadratically, scaled by stream progress.
    score += norm_post * norm_post * (10.0 + 30.0 * progress);

    // Lookahead: reward bins whose post-residual can host the next item,
    // with a smooth cubic interaction with progress.
    if next_item_size > 0 {
        let fits_next = (post_residual as f64 - next_item_size as f64).max(0.0) / bin_capacity as f64;
        score -= fits_next * fits_next * fits_next * 15.0;
    }

    // Last-chance bonus: smooth sigmoid-like term when this bin is nearly the only fit.
    if fitting_bins_count <= 1 {
        score -= 8.0 * (1.0 + progress);
    }

    // Mild penalty proportional to crowding of open bins.
    score += (open_bins_count as f64).ln() * 2.0;

    // Coupling with mean residual: prefer bins deviating from mean when mean is high.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.05 * dev * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity fractions (C=100)
    // Class 0: perfect fit (post_residual 0) -> best possible
    // Classes by residual bands: (0..=5), (6..=15), (16..=30), (31..=50), (>50)
    let cls = if post_residual == 0 {
        0.0
    } else if post_residual <= 5 {
        1.0
    } else if post_residual <= 15 {
        2.0
    } else if post_residual <= 30 {
        3.0
    } else if post_residual <= 50 {
        4.0
    } else {
        5.0
    };
    score += cls * 8.0;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // Dead-space penalty: small unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item exactly fits the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize by leftover-after-next (chained waste)
            let chain = post_residual - next_item_size;
            score += chain as f64 * 0.5;
        } else {
            // next item cannot use this residual: penalize residual further
            score += 12.0;
        }
    }

    // Last chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Prefer fuller bins: relative fill fraction
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 30.0;

    // Spread pressure: penalize bins far from mean residual (harmonic alignment)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate handling: empty bin gets a mild default score,
    // only attractive when no open bin offers a decent fit
    if bin_residual == bin_capacity {
        let base = 70.0;
        // more open bins -> slightly favor reusing them over opening new
        score = base + (open_bins_count as f64) * 1.5;
        if next_item_size > 0 && next_item_size >= 50 {
            // large next item: a fresh bin may serve it well
            score -= 10.0;
        }
    }

    // Stream progression: late in the stream, be more conservative (avoid new bins)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1)
    // are pure waste; anything below a "useful gap" threshold is penalized hard.
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    }
    // Penalize if next item cannot fit in post_residual but this bin could hold
    // a configuration better suited to it.
    if next_item_size > post_residual && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // discourage opening new bins.
    let new_bin_penalty = 15.0 + open_bins_count as f64 * 4.0;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
    } else {
        score -= new_bin_penalty * 0.5;
    }

    // Progress pressure: late in the stream, be more conservative with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    // Deviation from mean residual: prefer bins whose residual is close to the
    // mean (keeps the bin pool homogeneous) or well below it (tight bins).
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score += (post_residual as f64) * 0.5;

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (next_item_size as u32) == post_residual {
            score -= 40.0; // perfect chaining
        } else if next_item_size <= post_residual {
            score -= 15.0 * (nr / (post_residual as f64 + 1.0)); // next item fits well
        } else {
            // next item cannot use leftover: penalize wasted residual
            score += 10.0 * ((post_residual as f64).min(nr) / 100.0);
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin before opening a new one: strong reward to use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        // Slight bias toward using existing bins when fit is decent.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 + 5.0 * progress;
        // But if next item is huge and current fit is loose, allow new bin.
        if next_item_size > post_residual && post_residual > 0 {
            score -= 6.0;
        }
    }

    // Penalize large dead space (unusable residual < 10).
    if post_residual < 10 {
        score -= 5.0; // fully-packed bin is good
    } else if post_residual < item_size.min(20) {
        score += 3.0; // awkward small gap
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fill_ratio * fill_ratio;

    // Penalize small dead space that few future items can use (post_residual < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 30.0; // perfect closure bonus
    }

    // Lookahead: if next item fits the post-residual exactly or well, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = next_item_size as f64 / post_residual as f64;
        score -= 40.0 * next_fit * next_fit;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 12.0; // next item won't fit here; slight penalty
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Time horizon: early in stream, be conservative (favor new bins for large items);
    // late in stream, squeeze into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (mean_residual / bin_capacity as f64);

    // Many open bins: encourage consolidation into existing bins.
    score += 0.8 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin's residual deviates low from mean, it's a good target.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.15 * dev;

    // New-bin candidate adjustment: opening a fresh bin is attractive early or when fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = fill_ratio < 0.5;
        if poor_fit || progress < 0.2 {
            score -= 18.0;
        } else {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual, with non-linear sharpening.
    let mut score = pr + 12.0 * (pr / cap).powi(3);

    // Tight-fit reward: strongly favor placements that nearly fill the bin.
    let fill = 1.0 - pr / cap;
    score -= 30.0 * fill * fill;

    // Dead-space penalty: residuals too small for typical future items.
    if pr > 0.0 && pr < 10.0 {
        score += 25.0 * (1.0 - pr / 10.0);
    }

    // Lookahead: reward if next item fits into post-residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (nx / cap);
        } else {
            score += 6.0 * (1.0 - pr / cap) * (nx / cap);
        }
    }

    // Late-stream consolidation: prefer existing bins more as stream progresses.
    score -= 10.0 * progress * (1.0 - pr / cap);

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless it beats consolidation.
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * (1.0 - progress);
    }

    // Mild pull toward bins deviating from mean residual (spread management).
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near multiples of 10 are
    // more likely to be fillable by future items, so reward them.
    let r = post_residual % 10;
    let residue_bonus = match r {
        0 => 18.0,
        1 | 9 => 9.0,
        2 | 8 => 4.0,
        3 | 7 => 0.0,
        4 | 6 => -4.0,
        _ => -8.0, // r == 5 : half-slots are awkward
    };
    score -= residue_bonus;

    // Integer-division thresholds: a post_residual that leaves a "clean"
    // quarter/half/empty slot deserves priority.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else if frac <= 0.25 {
        score -= 15.0;
    } else if frac <= 0.5 {
        score -= 5.0;
    } else if frac > 0.75 {
        score += 6.0; // leaving mostly-empty bin is wasteful if bin was full-ish
    }

    // Coupling with next item: if next item exactly matches post_residual,
    // this is an ideal chain placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // harmonic class match: next item shares residue class with post slot
            let nr = next_item_size % 10;
            let pr = post_residual % 10;
            if nr == pr {
                score -= 10.0;
            }
            score -= (post_residual - next_item_size) as f64 * 0.1;
        } else {
            // next item cannot use this residual: mild penalty
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Slight preference for reusing existing bins over opening new ones as
    // the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // brand-new bin candidate: penalize more as stream progresses
        score += 12.0 + 20.0 * progress;
    } else {
        score -= 2.0;
    }

    // Tie-break: tighter current fit is better.
    score += (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful later
    // are heavily penalized. A gap is "dead" if it is below the minimum item size
    // or below the lookahead item's needs.
    let dead_threshold = 10.0_f64.max(next_item_size as f64);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving a gap that exactly fits the next item (k=2 lookahead pairing)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        score -= 5.0; // mild reward for still being usable by the next item
    }

    // Fit quality: fraction of bin filled by this item
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 20.0;

    // Open-bins pressure: prefer consolidating into existing bins
    // when many bins are open; scale penalty for spreading items.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly prefer using the only bin that fits,
    // otherwise a new bin gets opened and this residual is stranded.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mean residual coupling: bins with residual far below the mean are
    // already fragmented; prefer placing into bins near/above mean residual
    // so small residuals get consumed rather than multiplied.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += dev * 0.4;
    } else {
        score += dev * 0.1;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity and no open bin offers a tight fit. Penalize opening bins early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 - fill * 40.0 + progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post residual exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Prefer bins where the next item leaves minimal leftover again.
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
            if slack <= 5.0 {
                score -= 100.0;
            }
        } else {
            // Next item cannot fit here: penalize leaving a gap smaller than next item
            // (dead space relative to lookahead).
            let gap = (next_item_size - post_residual) as f64;
            score += 40.0 * (gap / bin_capacity as f64).min(1.0);
        }
    }

    // Relative to mean residual: prefer bins tighter than average (first-fit-like concentration).
    let mean_gap = mean_residual - post_residual as f64;
    score += 0.5 * mean_gap.max(-bin_capacity as f64).min(bin_capacity as f64);

    // Penalize wasting a nearly-full bin on a small item when other bins could also fit.
    if fitting_bins_count > 1 {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 30.0 * (1.0 - fill_ratio);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive if no good fit exists (large item, tight residuals).
    if bin_residual == bin_capacity {
        let tightness = mean_residual / bin_capacity as f64;
        score += 120.0 * (1.0 - tightness);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0;
        }
        if item_size >= 70 {
            score -= 80.0;
        }
    }

    // Late in the stream: consolidate harder, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 && bin_residual != bin_capacity {
        score -= 50.0 * progress;
    }

    // Mild penalty scaled by number of open bins to discourage bin sprawl.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: squared dead-space penalty scaled to capacity.
    let dead = post_residual as f64;
    score += (dead * dead) / cap;

    // Perfect-fit bonus: nearly empty residual is excellent.
    if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement (chain packing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (dead - nxt).abs();
        if diff <= 2.0 {
            score -= 20.0;
        } else if nxt <= dead {
            score -= 8.0 * (1.0 - diff / cap);
        } else {
            // next item won't fit here; mild penalty proportional to leftover
            score += 4.0 * (dead / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Many alternatives: mild penalty to keep competition meaningful.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: opening a new bin is expensive early and
    // when open bins already fit; cheap when the stream is nearly done or
    // this item leaves a very usable residual for future items.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let usable = dead / cap; // residual of new bin after placement
        let mut penalty = 40.0;
        penalty -= 15.0 * progress; // late stream: new bins less costly long-term
        penalty -= 10.0 * (1.0 - usable); // leaves big residual => more attractive
        if next_item_size > 0 && (next_item_size as f64) <= dead {
            penalty -= 5.0; // new bin can also host next item
        }
        if fitting_bins_count == 0 {
            penalty -= 100.0; // no alternative, must open
        }
        score += penalty.max(0.0);
    }

    // Global state nudges: prefer filling bins below mean residual (balance),
    // and slightly prefer denser packing when many bins are open.
    if !is_new_bin {
        let dev = dead - mean_residual;
        score += 0.05 * dev;
        score -= 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = post / cap; // normalized post residual in [0,1]

    // Smooth polynomial coupling of post residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 - progress) + x * (1.0 - x) * (1.0 - x) * progress;
    let mut score = post + 40.0 * poly;

    // Reward tight fits smoothly
    let fit = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit * fit * (1.0 - progress);

    // Penalize waste relative to mean residual (smooth interaction)
    score += 0.05 * (post - mean_residual).abs() * (0.5 + progress);

    // Last-chance bin bonus (smooth, not piecewise)
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - post / cap);
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let room = if post >= nx { post - nx } else { 0.0 };
        score -= 10.0 * (room / cap) * (1.0 - room / cap);
    } else {
        score -= 5.0 * x * (1.0 - x); // last item: prefer balanced fill
    }

    // Mild pressure against bin proliferation late in stream
    score += 0.3 * open_bins_count as f64 * progress * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: dead space is worse when it falls into
    // an "unusable" class (too small for the smallest plausible items).
    let pr = post_residual as f64;
    let small_item_floor = 1.0f64.min(10.0);
    if pr < 10.0 {
        score += 25.0; // unusable dead space
    } else if pr < 20.0 {
        score += 8.0;
    }

    // Perfect / near-perfect fit reward via capacity-fraction classes.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Modulo-class coupling: leftover that is an exact divisor-friendly
    // fraction of capacity is more reusable.
    let frac = pr / cap;
    if (post_residual % 25 == 0) && post_residual > 0 {
        score -= 12.0;
    } else if (post_residual % 10 == 0) && post_residual > 0 {
        score -= 6.0;
    }
    let _ = frac;

    // Tight fit reward: item fills most of the residual.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness * tightness;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
        if next_item_size == post_residual {
            score -= 15.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; mild penalty if we leave large gap.
        score += 0.05 * (pr - mean_residual).abs();
    }

    // New-bin candidate handling: an empty bin should only win when existing
    // bins are poor fits. Give the empty bin a moderate baseline.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
        if fitting_bins_count <= 1 {
            score -= 30.0; // opening a new bin is fine when nothing fits well
        }
    }

    // Stream progression: early on, be more willing to open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

