        // Existing bin: mild reward when many bins already open
        score -= open_bins_count as f64 * 0.5;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 25.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space for the known next item
        score += 15.0;
    }

    // Early stream: be slightly more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

