    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (waste-minimization core).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space: small post-residuals are good, but avoid
    // leaving slivers that nothing (>=10 historically) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits in post_residual,
    // this placement chains nicely; reward it.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && (post_residual as u32) > 0 {
        // Next item won't fit here; penalize leaving awkward gaps.
        score += 6.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer
    // consolidating into existing bins rather than spreading.
    let pressure = mean_residual / bin_capacity as f64;
    if open_bins_count > 2 {
        score -= 10.0 * pressure * (open_bins_count as f64).ln();
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // early in the stream or when the item fits existing bins poorly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let desperation = (item_size as f64 / bin_capacity as f64 - pressure).max(0.0);
        score += 20.0 + 30.0 * progress - 25.0 * desperation;
        // Late in stream, a new bin is almost always wasteful.
        if progress > 0.7 {
            score += 15.0 * progress;
        }
    }

    // Mild bonus for filling bins that are already mostly full.
    let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 8.0 * fullness;

    // Time-horizon adaptation: early on, keep bins flexible (avoid tiny gaps);
    // late, maximize packing density aggressively.
    if progress < 0.3 && post_residual > 0 && post_residual <= 20 {
        score += 10.0 * (1.0 - progress / 0.3);
    } else if progress > 0.7 {
        score -= 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let post_norm = post / cap;

    // Smooth base: reward tight fits (low post_residual), with non-linear sharpening
    let mut score = post * (1.0 + 0.8 * post_norm * post_norm);

    // Progress-coupled polynomial: later in the stream, tighten more aggressively
    let tighten = 1.0 + 1.5 * progress * progress + 0.5 * progress;
    score *= tighten;

    // Smooth interaction: dead space below next item size is penalized softly (quadratic falloff)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - post).max(0.0) / cap;
        score += 12.0 * gap * gap * (1.0 - progress * 0.5);
        // Reward leaving room exactly for the next item (smooth quadratic bonus)
        let fit_gap = (next_item_size as f64 - post).abs() / cap;
        score -= 8.0 * (1.0 - fit_gap * fit_gap);
    }

    // Last-chance bonus: smooth sigmoid-like reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many bins (encourages consolidation)
    score += (open_bins_count as f64) * 0.15 * (1.0 - progress);

    // Mean residual coupling: prefer bins near the mean (smooth quadratic)
    let dev = (post - mean_residual) / cap;
    score += 3.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify post_residual into capacity fractions.
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left over

    // Dead-space penalty: residuals that cannot host typical items are wasteful.
    // Classes: (0,10) useless, [10,50) poor, [50,100) good.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // nearly dead space
        } else if post_residual < 25 {
            score += 15.0;
        } else if post_residual < 50 {
            score += 5.0;
        } else {
            score -= 10.0; // large leftover is flexible
        }
    } else {
        score -= 60.0; // perfect fill
    }

    // Modulo-class coupling: does post_residual align with next_item_size?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward exact/near-exact divisibility (harmonic match).
            let r = post_residual % next_item_size;
            if r == 0 {
                score -= 30.0;
            } else if r < 10 {
                score -= 12.0;
            }
            // Also reward if next item leaves a further useful class.
            let pr2 = post_residual - next_item_size;
            if pr2 == 0 {
                score -= 25.0;
            } else if pr2 >= 50 {
                score -= 8.0;
            }
        } else {
            // Next item cannot use this leftover; penalize tight fits that strand space.
            score += 8.0 + (next_item_size as f64 - pr).min(50.0) * 0.2;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: prefer opening a fresh bin early in the stream
    // or when the fit into existing bins is bad (post_residual small but nonzero).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Baseline: new bin score tracks mean residual pressure.
        let mut nb = 0.35 * cap + 0.3 * mean_residual;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            nb -= 10.0; // fresh bin guarantees fit for lookahead
        }
        if progress < 0.2 {
            nb -= 5.0;
        }
        if open_bins_count > 6 {
            nb += 0.5 * (open_bins_count as f64 - 6.0); // discourage bin proliferation
        }
        score = score.max(nb) - (score - nb).abs() * 0.0; // placeholder no-op
        score = nb;
    }

    // Small tie-breaking noise via deterministic arithmetic (no RNG).
    score += ((item_size as f64 * 0.017 + step_index as f64 * 0.003) % 0.5) - 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space: gaps below the minimum item size are pure waste
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 1000.0;
    }
    // Strong penalty for tiny gaps that likely can't fit typical items
    if post_residual > 0 && post_residual < 10 {
