    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open bins pressure: with many open bins, favor filling existing ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.6 * (0.5 + progress);

    // Prefer bins whose residual is close to the mean (avoid fragmenting outliers)
    score += ((bin_residual as f64) - mean_residual).abs() * 0.15;

    // Lookahead: if next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    }
    // If next item fits in post_residual, mild reward; if not, mild penalty for wasting
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else if post_residual > 0 {
            score += (post_residual as f64) * 0.3;
        }
