    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // closely matches the next item's size (perfect chain fit).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let match_gap = (post - nxt).abs();
        if post >= nxt {
            // Next item can chain into this bin: reward tight match.
            score -= 18.0 * (1.0 - match_gap / bin_capacity as f64);
            if match_gap < 1.0 {
