    // Relative-to-mean residual coupling: prefer bins tighter than average.
    let post_f = post_residual as f64;
    score += 0.25 * (mean_residual - post_f).max(-40.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize leaving very small unusable slivers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }
    if post_residual == 0 {
        score -= 8.0; // perfect fill
    }

    // New-bin candidate: make it mildly attractive only when open bins
    // would leave large unusable residuals, otherwise discourage it.
    if bin_residual == bin_capacity {
        score += 14.0 + 0.1 * open_bins_count as f64;
    }

    // Late-stream tightening: near the end, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - post_f / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
