    let progress = step_index as f64 / total_items.max(1) as f64;
    if mean_residual > 40.0 && open_bins_count > 3 {
        score += 4.0 * (1.0 - progress);
    }

    // Late in the stream: be conservative, prefer filling existing bins
    if progress > 0.8 {
        score += 2.0 * progress;
    }

    // Discourage opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        let decent_fit_exists = post_residual < bin_capacity as f64 * 0.5_f64.ln().exp().min(2.0) as u32;
        if decent_fit_exists && fitting_bins_count > 0 {
