    }

    // Slight preference for keeping fewer open bins when fits are plentiful
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: mildly discourage opening a new bin unless residual is large
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress);
        score += 5.0 * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space by capacity fraction.
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;

    // Class A: near-perfect fit (post_residual <= 10) -> strong reward.
    if post_residual <= 10 {
        score -= 40.0 + 5.0 * (11 - post_residual) as f64;
    }
    // Class B: residual fits next item exactly or well -> reward lookahead synergy.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 25.0;
        } else {
            score -= 8.0 * (1.0 - slack as f64 / cap);
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here; penalize dead space proportionally.
        score += 6.0 * (next_item_size as f64 - post_residual as f64) / cap;
    }

    // Integer-division thresholds on post_residual (harmonic bands of C=100).
    let band = post_residual / 25; // 0..=4
    score += match band {
        0 => -10.0,                       // 0-24: tight leftover, good
        1 => 3.0,                         // 25-49: awkward band
        2 => 8.0,                         // 50-74: half-full-ish, mediocre
        3 => 5.0,                         // 75-99: still roomy
        _ => 0.0,                         // empty/new bin
    };

    // Modulo arithmetic: penalize residuals in "unusable" congruence classes.
    // Residuals that are small odd numbers waste more space than multiples of 5/10.
    if post_residual > 0 && post_residual <= 20 {
        if post_residual % 10 == 0 {
            score -= 6.0;
        } else if post_residual % 5 == 0 {
            score -= 3.0;
        } else if post_residual % 2 == 1 {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin fit is poor and
    // mean residual across open bins is low (bins nearly exhausted).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = post_frac >= 0.5; // item small relative to fresh bin
        if mean_residual < 15.0 || fitting_bins_count == 0 {
            score -= 20.0;
        } else if poor_fit && post_residual as f64 > mean_residual + 20.0 {
            score -= 5.0;
        } else {
            score += 15.0 + 10.0 * progress;
        }
    }

    // Mild preference for fuller bins when many bins are open.
    score += 0.05 * open_bins_count as f64 * post_frac;

    // Small tie-breaker: favor bins whose residual is closest to item granularity.
    score += (bin_residual as f64 - mean_residual).abs() * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (< 10) are unusable by any item,
    // so penalize them heavily (super-linear dead-zone penalty).
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward: item fills a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a
    // reasonably tight fit exists; encourage consolidation early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Lookahead: if next item can use this post_residual, reward leaving it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }
    // If next item cannot fit in the leftover, penalize the gap mildly.
    if next_item_size > post_residual && post_residual > 0 {
        score += 4.0;
    }

    // Mean residual coupling: prefer bins below the mean residual (tighter bins)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: make it attractive only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened by stream progress and load.
        score = 55.0 + 20.0 * progress + 0.5 * open_bins_count as f64;
        // If the current item is large and mean residual is small, new bin is fine.
        if item_size > 60 && mean_residual < item_size as f64 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let fit_ratio = (item_size as f64) / (bin_residual as f64);

    // Reward exact/near-exact matches strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            // next item fits: good chain, penalize leftover gap
            let gap = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // next item won't fit here: dead space risk grows with gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap;
        }
    }

    // Relative to mean residual: bins with residual near mean are "normal";
    // prefer placing into bins with larger-than-mean residual (consume slack).
    let residual_f = bin_residual as f64;
    if residual_f > mean_residual {
        score -= 0.3 * (residual_f - mean_residual);
    } else {
        score += 0.3 * (mean_residual - residual_f);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Penalize very tight fits that leave unusable slivers when more bins exist.
    if post_residual > 0 && post_residual < 10 && fitting_bins_count > 2 {
        score += 25.0;
    }

    // Early in stream: slightly prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress) * fit_ratio;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized mildly so it wins only over bad fits.
        score += 90.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 20.0; // fresh bin is flexible for the future
        }
        if fitting_bins_count == 0 {
            score -= 200.0; // nothing fits: new bin is correct
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) nonlinearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space that is too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 4.0;
        }
        // Perfect chain fit bonus.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Global state coupling: prefer filling bins when many are open.
    let t = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += 0.05 * pressure * (1.0 - t);

    // Deviation from mean residual: prefer bins near the mean (balance) early,
    // prefer extreme (fuller) bins late.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev * t;

    // Mild bonus for fuller bins overall.
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to residual space in typical open bins.
    if bin_residual == bin_capacity {
        score += 20.0 - 0.15 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr
        - 30.0 * norm_pr * (1.0 - norm_pr) * (1.0 + progress)
        + 20.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) increasingly late in the stream
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 25.0 * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly prefer the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize creating dead space that cannot fit the lookahead item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + 10.0 * progress;
    }
    // Reward leaving room for the lookahead item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 * (1.0 - progress);
    }

    // Mild penalty when many bins are open and this placement wastes space
    if bin_residual != bin_capacity {
        score += 0.02 * open_bins_count as f64 * norm_pr;
    }

    // Encourage new bins early when mean residual is low
    if bin_residual == bin_capacity {
        score += 5.0 * mean_residual / cap - 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: items with small mod-10 residues
    // are "harmonically compatible" with typical item sizes.
    let post_class = post_residual % 10;
    let next_class = next_item_size % 10;

    // Perfect fit: zero post-residual is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward when the next item fits exactly into the post-residual (lookahead harmony).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item fits but leaves a residue; scale reward by tightness.
        let post_next = post_residual - next_item_size;
        score -= 15.0 * (1.0 - (post_next as f64) / (bin_capacity as f64));
        // Harmonic bonus if residues align (both multiples of 5 or 10).
        if next_class == 0 || next_class == 5 {
            score -= 5.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize dead space proportionally.
        score += 8.0;
        if post_residual < 10 {
            score += 10.0; // tiny unusable sliver
        }
    }

    // Penalize odd harmonic classes that tend to create dead space.
    if post_class != 0 && post_class != 5 {
        score += 2.0 + 0.3 * post_class as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless open bins are very full.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.1 * (mean_residual / (bin_capacity as f64).max(1.0)) * 100.0;
        // Early in stream, opening bins is cheap; late, prefer filling existing.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * progress;
    }

    // Prefer bins whose residual is below mean (filling the fullest bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps (1..=10) are nearly unusable -> heavy penalty
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (1.0 - (post_residual as f64) / 11.0);
    }
    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit reward scaled by waste ratio
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste * waste;

    // If this bin is the last chance to avoid opening a new bin, favor it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: discourage spreading when many bins open
    score += 0.6 * open_bins_count as f64;

    // Prefer bins below mean residual (more roomy bins absorb big items later)
    score += 0.3 * ((post_residual as f64) - mean_residual);

    // Lookahead: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here anyway; mild penalty for leaving gap next item can't use
        score += 8.0;
    }

    // Early in stream, be more willing to use existing bins (open fewer)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: perfect match between post_residual and next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 60.0; // exact 2-step chain: place here
        } else {
            score += diff as f64 * 0.35; // penalize mismatch
        }
        // Bonus if next item fits exactly after this placement relative to mean residual
        if (post_residual as f64 - next_item_size as f64).abs() < mean_residual.abs().max(1.0) * 0.25 {
            score -= 10.0;
        }
    } else {
        // Last item: minimize residual tightly
        score += post_residual as f64 * 0.5;
    }

    // Penalize creating unusable dead space (small residuals that few items can use)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless current open bins have tight residuals
    if bin_residual == bin_capacity {
        let tight = mean_residual < item_size as f64 * 0.5;
        let pressure = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if tight || fitting_bins_count == 0 {
            score -= 15.0 + 20.0 * pressure;
        } else {
            score += 30.0 + 25.0 * (1.0 - pressure);
        }
    }

    // Mild preference for bins tighter than the mean (compact packing)
    score += (bin_residual as f64 - mean_residual).max(0.0) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    score -= 0.35 * (bin_capacity as f64 - post_residual as f64);

    // Penalize dead space: post residual too small to be useful later
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 15.0;
        } else if (post_residual as u32) >= next_item_size / 2 {
            score -= 5.0;
        } else {
            score += 6.0;
        }
    }

    // Prefer fuller bins relative to the mean residual of open bins
    if bin_residual as f64 > mean_residual {
        score -= (bin_residual as f64 - mean_residual) * 0.15;
    } else {
        score += (mean_residual - bin_residual as f64) * 0.15;
    }

    // Time horizon: early in stream, be more open to new bins; later, consolidate
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_penalty = 10.0 + 40.0 * progress;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
    }

    // Many open bins: encourage filling existing ones
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (low post_residual), with non-linear sharpening
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Stream-progress coupling: later in the stream, waste matters more
    let progress_coupling = 1.0 + 1.5 * progress * (1.0 - progress * 0.5);
    score *= progress_coupling;

    // Dead-space penalty: post_residual too small for any plausible future item
    if post > 0.0 {
        let dead = (1.0 - post / cap).max(0.0);
        score += 12.0 * dead * dead * (post / cap);
    }

    // Last-chance bonus: only one bin fits, avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * progress;
    }

    // Lookahead: reward bins whose post-residual fits the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (post - next_item_size as f64) / cap);
        } else {
            score += 3.0 * (next_item_size as f64 - post) / cap;
        }
    }

    // Mild penalty for proliferating bins relative to mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap).max(0.0);

    // New-bin candidate: neutral-ish baseline, penalized unless open bins are fragmented
    if bin_residual == bin_capacity {
        score = cap * (1.0 + 0.5 * progress) + 0.05 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space by capacity fraction.
    let post = post_residual as f64;
    let class = (post / cap * 8.0).floor(); // 0..7 harmonic octant of residual

    // Reward tight fits: post residual in the lowest octants is excellent.
    match class as u32 {
        0 => score -= 30.0,           // near-perfect fit (0..=12.5 left)
        1 => score -= 18.0,           // good fit
        2 => score -= 8.0,
        3 => score -= 2.0,
        4 => score += 0.0,
        5 => score += 4.0,
        6 => score += 10.0,
        _ => score += 16.0,           // wasteful large leftover
    }

    // Dead-space penalty: residuals below the smallest plausible item are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Modulo arithmetic on post_residual: divisible residuals pair well with common item sizes.
    let pr = post_residual;
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;                 // residual aligned to decimal item classes
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 4.0;                 // quarter-capacity alignment
    }

    // Integer-division thresholds: how many "typical" items still fit.
    let slots = pr / 10;
    if slots == 0 && pr > 0 {
        score += 12.0;                // leftover too small for any item
    } else if slots >= 7 {
        score += 6.0;                 // bin nearly empty; better saved for a big item
    }

    // Lookahead coupling: if the next item exactly fills the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;            // perfect chaining
        } else if next_item_size <= pr {
            score -= 10.0 * (pr / next_item_size.max(1)) as f64 / 4.0;
        } else {
            score += 8.0;             // next item cannot use this bin anyway
        }
    }

    // Last-chance bin: strongly prefer filling the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Progress-aware pressure: early in the stream, keep bins open/loose; later, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post / cap);

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += 0.15 * (post - mean_residual).max(0.0);

    // Mild penalty when many bins are open: encourage consolidation.
    score += 0.3 * open_bins_count as f64;

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 35.0;                // default: prefer existing bins
        if fitting_bins_count == 0 || (post_residual as f64) < 0.15 * cap {
            score -= 45.0;            // opening fresh is right for big items / poor fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small leftover gaps are "unusable dead space": penalize them aggressively,
    // scaled by how far below the practical usability threshold they fall.
    if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin cleanly.
        score -= 15.0;
    } else if post_residual < 10 {
        // Tiny sliver: almost nothing can use it later.
        score += 40.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual < 20 {
        // Marginal gap: mild penalty.
        score += 8.0;
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // The next item can also land here: this bin remains useful.
            score -= 6.0;
        } else {
            // Gap is dead with respect to the upcoming item.
            score += 3.0;
        }
    }

    // --- open_bins_count pressure / new-bin gating ---
    if bin_residual == bin_capacity {
        // Brand-new empty bin candidate: penalize opening it, growing with
        // the number of already-open bins (consolidation pressure).
        score += 10.0 + open_bins_count as f64 * 0.3;
    } else {
        // Existing bin: slight bonus to prefer reuse over expansion.
        score -= 2.0;
        // Last-chance bin: if this is the only bin that fits, avoid a new bin.
        if fitting_bins_count == 1 {
            score -= 8.0;
        }
    }

    // --- Global tightness coupling: prefer bins tighter than the mean ---
    score += (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills this bin afterwards.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-item completion
        } else if next_item_size <= post_residual {
            // next item fits: reward closeness of the two-step residual to zero
            let two_step = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - two_step / bin_capacity as f64);
            // small penalty for leaving awkward mid-range slack after two placements
            if two_step > 0.0 && two_step < 10.0 {
                score += 6.0;
            }
        } else {
            // next item cannot use the leftover: penalize proportionally to wasted space
            score += 0.35 * (post_residual as f64 - post_residual.min(next_item_size - 1) as f64);
        }
    } else {
        // last item: strongly favor tightest fit
        score -= 40.0;
    }

    // Penalize dead space relative to typical slack across open bins
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.25 * (mean_residual - post_residual as f64);
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Mild penalty for opening a brand-new bin when other bins could fit (encourage consolidation)
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 8.0 + 0.1 * open_bins_count as f64;
    }

    // Slight preference for filling bins more completely as the stream progresses
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tight * tight;

    // Dead-space penalty for very small leftovers that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else {
            score += 8.0;
        }
        // Perfect pair: item + next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Crowding: when many bins are open, prefer consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowd = (open_bins_count as f64).ln() + 1.0;
    if bin_residual < bin_capacity {
        score -= 6.0 * crowd * (0.3 + progress);
    }

    // Prefer bins below mean residual (keeps residuals balanced, avoids many half-full bins).
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    // New-bin candidate handling: default is heavily penalized, but allow opening
    // a fresh bin when all fits are poor (large post_residual) or the current bin
    // would leave a useless gap.
    if bin_residual == bin_capacity {
        score += 55.0 + 10.0 * (1.0 - progress);
        let poor_fit = post_residual as f64 > 30.0 || next_item_size == 0;
        if fitting_bins_count <= 2 && poor_fit {
            score -= 70.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post residual (waste), modulated by stream progress.
    let mut score = pr * (1.0 + 1.5 * norm_pr * norm_pr);

    // Late in the stream, penalize residual more strongly (consolidation pressure).
    score += 40.0 * progress * norm_pr * norm_pr;

    // Reward tight fits: subtract when post_residual is small relative to item size.
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness;

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score -= 20.0 * (1.0 - gap / cap).max(0.0);
        // Penalize leaving residual just above next item (blocking dead space).
        if pr >= nxt {
            score -= 10.0 * (1.0 - (pr - nxt) / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Mean residual coupling: prefer bins deviating below mean (tighter bins first).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Slight preference for fewer open bins early, more consolidation late.
    score += 0.5 * (1.0 - progress) * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by 10 are
    // "harmonic" (likely to absorb future items drawn from 10..80 grids).
    let harmonic = post_residual % 10 == 0;
    if harmonic {
        score -= 6.0;
    } else {
        // Penalize non-harmonic dead space proportionally to distance
        // from the nearest multiple of 10.
        let dist = (post_residual % 10).min(10 - post_residual % 10) as f64;
        score += dist * 0.8;
    }

    // Integer division thresholds on post_residual: classify residual
    // into coarse bands (dead space vs usable space).
    let band = post_residual / 25; // 0..4
    score += match band {
        0 => 12.0, // tiny residual (<25): nearly dead space
        1 => 4.0,  // 25..49: awkward
        2 => 0.0,  // 50..74: decent
        _ => -3.0, // 75..99: very usable
    };

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: this placement keeps a chain alive.
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 + slack * 0.05;
            // Bonus if next item also lands on a harmonic boundary.
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 4.0;
            }
        } else {
            // Next item won't fit here; penalize more if this residual
            // becomes truly unusable (below minimum item size 10).
            if post_residual < 10 {
                score += 15.0;
            } else {
                score += 3.0;
            }
        }
    } else {
        // Last item: prefer tightest fit overall.
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive
    // when the item is huge (poor fit anywhere) or many bins are open
    // with fragmented residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Cost of a fresh bin, discounted if current bin would waste a lot.
        score += 55.0
            - (item_size as f64 / bin_capacity as f64) * 20.0
            - fragmentation * 0.3
            - progress * 5.0;
        // Discourage hoarding bins when few are open.
        if open_bins_count < 3 {
            score += 10.0;
        }
        // A fresh bin gives a perfect harmonic residual of 100.
        if item_size % 10 == 0 {
            score -= 5.0;
        }
    }

    // Mild preference for bins whose residual deviates from the mean
    // in the "more full" direction (consolidation).
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.15;
    } else {
        score += (-dev) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A gap is "dead" if it is too small to fit the smallest plausible item (<= 1 here,
    // but practically gaps below ~10-15 are hard to fill). Use a nonlinear wedge:
    // gaps in (0, 12) are penalized super-linearly.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 12.0 {
        score += (12.0 - gap) * (12.0 - gap) * 2.5;
    }
    // Perfect fit bonus: zero post-residual is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Reward near-perfect fits that still leave a usable gap.
    if gap >= 12.0 && gap < 25.0 {
        score -= 5.0;
    }

    // Open-bins pressure: when many bins are open, prefer filling existing ones
    // (penalize the new-bin candidate more as open_bins_count grows).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0 + 3.0 * open_bins_count as f64;
    } else {
        // Mild reward for using an existing bin, stronger when bins are numerous.
        score -= 2.0 + 0.5 * open_bins_count as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement
    // (chaining placements into the same bin).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }
    // If next item does NOT fit the post-residual but the gap is dead space, penalize.
    if next_item_size > post_residual && gap > 0.0 && gap < next_item_size as f64 {
        score += 0.5 * (next_item_size as f64 - gap);
    }

    // Stream progression: early in the stream, be slightly more willing to open bins
    // (spread items); late in the stream, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score -= 10.0 * (1.0 - progress);
    } else {
        score += 5.0 * progress;
    }

    // Mean-residual coupling: if this bin's post-residual is far below the mean,
    // it means we are compacting well; reward that.
    score -= 0.3 * (mean_residual - gap).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    // Near match: next item still fits tightly with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the next item: penalize.
        let dead = (next_item_size - post_residual) as f64;
        score += 0.35 * dead;
    }

    // Reward tight fits relative to mean residual.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.5 * (mean_residual - pr);
    } else {
        score += 0.25 * (pr - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize opening a new bin when open bins exist and fit is decent.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (bin_capacity - item_size) as f64;
        score += 25.0 + 0.3 * waste - 10.0 * progress;
        // If next item would fit in the fresh bin's residual, soften penalty.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
        // If no existing bin fits well (few fitting bins), opening is more acceptable.
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Small bonus for filling bins nearly completely.
    score -= 8.0 * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit even the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward if next item fits the post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= fill_ratio * open_bins_count as f64 * 0.5;

    // Compare against mean residual: bins below mean residual are "dying" bins,
    // prefer to use them up.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Early stream: be more open to new bins (exploration); late stream: consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_penalty = 10.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
        // New bin looks attractive if lookahead is large relative to current item.
        if next_item_size > item_size {
            score -= 6.0;
        }
    }

    // Slight preference for bins whose residual is close to item size (snug fit).
    let snug = 1.0 - ((bin_residual - item_size) as f64) / (bin_capacity as f64);
    score -= snug * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: prefer small post-residual, with non-linear penalty on tight-but-wasteful fits
    let mut score = pr * (1.0 + 0.8 * prn * prn);

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, tight fits (small post_residual) matter more.
    let coupling = prn * (1.0 - prn) * (progress - 0.5) * 120.0;
    score -= coupling;

    // Penalize residuals that are dead space relative to mean residual of open bins
    score += 0.35 * (pr - mean_residual).max(0.0) * (1.0 + progress);

    // Reward using a bin when it is the only fitting bin (avoid new bin)
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: bonus if next item fits exactly into post_residual
    if next_item_size > 0 {
        if (next_item_size as f64 - pr).abs() < 1.0 {
            score -= 40.0;
        } else if (next_item_size as u32) <= post_residual {
            score -= 12.0 * (pr - next_item_size as f64) / cap;
        } else {
            score += 6.0 * (next_item_size as f64 - pr) / cap;
        }
    }

    // Slight penalty for spreading across many open bins early
    score += open_bins_count as f64 * 0.4 * (1.0 - progress);

    // New-bin candidate: make it moderately attractive only for poor fits
    if bin_residual == bin_capacity {
        score += 18.0 - 20.0 * progress - 0.2 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes on post_residual: dead space in low classes is more wasteful.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is ideal
    } else {
        // Class of dead space modulo capacity quarters
        let quarter = bin_capacity / 4;
        let class = pr / quarter;
        score += match class {
            0 => pr as f64 * 0.4,      // tiny dead space: bad (wasted sliver)
            1 => pr as f64 * 0.9,      // mid-small gap: very bad
            2 => pr as f64 * 0.7,      // moderate gap
            _ => pr as f64 * 0.35,     // large gap: still usable
        };
        // Harmonic bonus: post_residual divisible by common item sizes (10,20,25,50)
        if pr % 10 == 0 { score -= 4.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 50 == 0 { score -= 3.0; }
    }

    // Lookahead: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits exactly or leaves a good class
            let nxt_post = pr - next_item_size;
            if nxt_post == 0 {
                score -= 30.0;
            } else if nxt_post % 10 == 0 {
                score -= 12.0;
            } else {
                score -= 5.0;
            }
        } else {
            // next item won't fit here: penalize proportionally
            score += (next_item_size - pr) as f64 * 0.3;
        }
    } else {
        // last item: prefer filling as much as possible
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: encourage consolidation into emptier bins
    if open_bins_count > 4 {
        score += (mean_residual - bin_residual as f64) * 0.15;
    }

    // New-bin candidate logic: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty so new bins are used only when worthwhile
        score += 45.0;
        // early stream: opening bins is cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 20.0;
        // large current item that would leave bad dead space in open bins
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
        // if next item is huge, a fresh bin is valuable
        if next_item_size >= bin_capacity / 2 {
            score -= 8.0;
        }
    } else {
        // prefer tighter bins (small residual before placement)
        score += (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // Integer-division threshold: bins whose residual is in the awkward (25,40) band are penalized
    if bin_residual > 25 && bin_residual < 40 && bin_residual >= item_size {
        score -= 6.0; // use up awkward residual now
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Dead-space penalty: gaps too small to hold the minimum item (size 1..=100,
    // but practically treat <10 as near-dead) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits the post residual exactly, reward; if it
    // doesn't fit, penalize leaving a residual that blocks the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            if next_item_size == post_residual {
                score -= 20.0;
            }
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity, so its fill
    // ratio is low and this term won't fire for it).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64).ln().max(0.0) * (2.0 + 4.0 * progress);
    } else {
        // New-bin candidate: penalize more when many bins are already open.
        score += (open_bins_count as f64) * (1.5 + 2.0 * progress);
    }

    // Prefer bins whose residual deviates from the mean (consolidate waste):
    // bins with residual well above mean are good targets for large items.
    if bin_residual as f64 > mean_residual && bin_residual < bin_capacity {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact/near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // 2-step lookahead: reward when next item fits the post residual exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_post = post_residual - next_item_size;
        if next_post == 0 {
            score -= 120.0;
        } else if next_post <= 10 {
            score -= 40.0;
        }
        // If next item cannot fit anywhere else later, keep chain going.
    } else if next_item_size > 0 {
        // Post-residual too small for next item: penalize dead space relative to next size.
        let dead = post_residual as f64;
        score += dead * 0.5;
        if dead < (next_item_size as f64) * 0.5 {
            score += 15.0;
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Penalize new-bin candidate unless current bins are nearly full on average.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let tight = mean_residual / bin_capacity as f64;
        // Open a new bin when mean residual is small (bins nearly full) or few bins open.
        score -= 60.0 * (1.0 - tight.min(1.0)) * (1.0 - progress * 0.5);
        if open_bins_count <= 1 {
            score -= 30.0;
        }
        // Discourage opening new bin if existing bins fit well.
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // Mild preference for fuller bins relative to mean residual.
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Strongly penalize dead space: leftovers too small for the smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead: if the leftover can still host the next item, this is valuable.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // leftover useless for next item; acceptable if it's a near-perfect fit now
            score += 3.0;
        }
        // Perfect chain: item + next item exactly fills bin
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is costly; only attractive when
    // no open bin fits well (item large relative to mean residual) or stream is early.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fit = (bin_residual as f64) < item_size as f64; // never true for new bin; proxy via mean residual
        let _ = poor_fit;
        let open_residuals_tight = mean_residual < item_size as f64;
        if open_bins_count == 0 || (open_residuals_tight && item_size > 50) {
            score -= 10.0 + 5.0 * (1.0 - progress);
        } else {
            score += 18.0 + 10.0 * (open_bins_count as f64).sqrt();
        }
    }

    // Mild preference for filling bins that are already small-residual (consolidation).
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    // Slight time decay: later in the stream, prefer tighter packing even more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth polynomial shaping
    let mut score = norm_pr * norm_pr * (1.0 + 2.0 * progress);

    // Non-linear coupling: post_residual interacting with mean residual
    let norm_mean = mean_residual / cap;
    score += 0.8 * norm_pr * norm_mean * (1.0 - norm_pr);

    // Penalty when item barely fits (near-perfect fit is good, but tiny leftover is wasted)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 1.5 * fit_ratio * fit_ratio * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 2.0;
    } else {
        score += 0.3 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: reward if next item could fit in the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 1.2 * (1.0 - slack * slack) * (0.5 + 0.5 * progress);
        } else {
            score += 0.6 * (nx - pr) / cap * (1.0 - progress);
        }
    }

    // New-bin candidate: mildly penalize opening a new bin unless residual is large
    if bin_residual == bin_capacity {
        score += 1.5 - 0.5 * progress;
        score += 0.05 * open_bins_count as f64;
    }

    // Mild penalty for too many open bins relative to stream progress
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residual buckets by modulo arithmetic.
    // Residuals divisible by 10 are "clean" (likely to fit future items drawn
    // from typical 10-aligned distributions); odd/prime-ish residuals are dead space.
    let clean = post_residual % 10 == 0;
    let semi_clean = post_residual % 5 == 0;
    if clean {
        score -= 6.0;
    } else if semi_clean {
        score -= 2.0;
    } else {
        score += 4.0; // penalize ragged residuals
    }

    // Integer-division thresholds on post_residual: tiny leftovers are dead space.
    let dead_class = post_residual / 10; // 0 => residual < 10 (unusable dead space)
    if dead_class == 0 {
        score += 12.0;
    }

    // Coupling with lookahead item: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic compatibility: next item leaves a clean residual again?
            let nr = post_residual - next_item_size;
            if nr % 10 == 0 {
                score -= 10.0;
            } else if nr % 5 == 0 {
                score -= 5.0;
            }
            score -= 3.0;
        } else {
            // next item won't fit here regardless; slight penalty for tight bins
            score += 2.0;
        }
    } else {
        // last item: prefer fullest bin, no future considerations
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only attractive when current item is huge relative to mean residual
    // or no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let open_penalty = 30.0
            - 10.0 * (item_size as f64 / bin_capacity as f64)
            + 2.0 * open_bins_count as f64;
        // If the item would leave a clean residual in the new bin, new bin is fine.
        let pr_clean = post_residual % 10 == 0;
        score = if pr_clean { open_penalty - 4.0 } else { open_penalty + 4.0 };
        // Late in the stream, opening fresh bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * progress;
        // If many bins already fit the item, discourage new bin.
        if fitting_bins_count > 2 {
            score += 10.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
        }
    } else {
        // Existing bin: reward tight fits (small post_residual relative to item).
        let tightness = item_size as f64 / bin_residual.max(1) as f64;
        score -= 8.0 * tightness;
        // Reward bins whose residual deviates favorably from the mean
        // (a below-mean residual here means we're consolidating fullness).
        score -= 0.5 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.1;
        // Early stream: be slightly greedy on the fullest bins to consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable tiny gaps are the worst outcome.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0 * (11.0 - post_residual as f64); // small gap => big penalty
        } else if post_residual < 25 {
            score += 15.0 * (25.0 - post_residual as f64) / 15.0;
        } else {
            // Larger leftovers are more reusable: mild reward relative to mean residual.
            score -= 0.5 * (post_residual as f64 - mean_residual).max(-20.0);
        }
    } else {
        // Perfect fill is ideal.
        score -= 40.0;
    }

    // Reward when this bin's leftover can still host the next item (lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize if post-residual is a small gap just below the next item size.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 15 {
        score += 12.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into fresh space
    // unless the fit is tight; encourage consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * progress);
    score += pressure * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: default is mildly unattractive; only wins when open bins
    // would leave dead space or are overcrowded.
    if bin_residual == bin_capacity {
        score += 18.0 + 0.3 * open_bins_count as f64;
        // But opening a bin is attractive for huge items that would wreck a bin.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_gap = post_residual - next_item_size;
        score -= 3.0 * (1.0 - fit_gap as f64 / bin_capacity as f64);
        if fit_gap == 0 {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // next item cannot fit here; penalize dead space below next_item_size
        score += 0.5 * (next_item_size as f64 - post_residual as f64).min(20.0);
    }

    // Penalize residual far below mean (creating unusable dead space)
    score += 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Prefer keeping tight fits in existing bins over opening new bins
    if bin_residual == bin_capacity {
        score += 6.0;
    }

    // Late in stream: tighten packing, prefer fuller bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio).powi(6);

    // Penalize dead space: post_residual too small for the smallest possible item (1).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: only this bin fits -> strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 60.0;
        } else if gap < 10 {
            score -= 20.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize leaving a sliver the next item cannot use.
        score += 15.0;
    }

    // Prefer fuller bins when many bins are open.
    let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 10.0 * fill * (open_bins_count as f64).ln().max(1.0);

    // Time horizon: early in stream, be more willing to open new bins;
    // late in stream, consolidate into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 5.0 + 25.0 * progress;
        // But early on, opening a fresh bin for good future packing is okay.
        if progress < 0.3 {
            score -= 10.0;
        }
    }

    // Deviation from mean residual: prefer bins with less residual than average.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64 / cap;
    let nxt = next_item_size as f64 / cap;
    let mean_res_n = mean_residual / cap;

    let mut score = pr;

    // Smooth polynomial coupling: post_residual interacts with stream progress
    let coupling = norm_pr * (1.0 + 2.0 * progress * progress) * (1.0 - 0.5 * item);
    score += 12.0 * coupling;

    // Penalize dead space quadratically as stream advances
    score += 40.0 * norm_pr * norm_pr * (0.3 + 0.7 * progress);

    // Reward tight fits (small post residual) more strongly late in stream
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Lookahead: reward if next item fits into post residual (smooth sigmoid-like)
    if next_item_size > 0 {
        let fits = (pr - nxt).max(0.0) / cap;
        let ratio = if pr > 0.0 { nxt / pr } else { 2.0 };
        let bonus = (1.0 / (1.0 + (ratio - 1.0) * (ratio - 1.0) * 4.0)) * (1.0 + fits);
        score -= 15.0 * bonus;
    }

    // Last-chance bin: strong reward to use it rather than open new bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    } else {
        // Slight penalty when many alternatives exist, scaled by bin count
        score += (fitting_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Deviation from mean residual: prefer bins near mean early, tighter later
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * (1.0 - progress) - 4.0 * dev * dev * progress;

    // Mild penalty for opening new bins as stream progresses
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress + 3.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // --- Harmonic class of the post-fit residual (mod-10 classes) ---
    // Residuals near 0 are gold; residuals in "dead zones" (tiny slivers)
    // are penalized since almost no future item (min size 1..100) fits well.
    let pr = post_residual;
    let class = (pr % 10) as f64;
    if pr == 0 {
        score -= 40.0; // perfect fill
    } else if pr < 10 {
        score += 25.0; // unusable sliver: dead space penalty
    } else {
        // Harmonic coupling: residual divisible by 5 pairs better with
        // even/odd item classes; reward clean classes.
        if pr % 10 == 0 {
            score -= 8.0;
        } else if pr % 5 == 0 {
            score -= 4.0;
        }
        // mild penalty proportional to class irregularity
        score += class * 0.15;
    }

    // --- Tightness reward: fraction of bin consumed by this placement ---
    let fill = item_size as f64 / cap;
    score -= 20.0 * fill * fill; // quadratic reward for big consumption

    // --- Lookahead compatibility (k=2) ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // next item can still fit here: strong bonus, scaled by how snug
            let snug = 1.0 - (post - nxt) / cap;
            score -= 15.0 + 10.0 * snug;
            // harmonic match: next item shares a mod-10 class with post_residual
            if (post_residual % 10) == (next_item_size as u32 % 10) {
                score -= 6.0;
            }
        } else {
            // next item will NOT fit here: this bin becomes dead after use
            score += 10.0 * (1.0 - fill);
        }
    } else {
        // last item in stream: prefer zero-waste completion
        score -= 12.0 * (1.0 - fill);
    }

    // --- Last-chance bin before opening a new one ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base aversion to opening new bins grows with stream progress
        // and with the number of already open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut nb = cap - 30.0 * fill + 30.0 * progress + 2.0 * open_bins_count as f64;
        // If this bin is the only fitting option, opening a new bin is
        // competitive: relax the penalty.
        if fitting_bins_count <= 1 {
            nb -= 45.0;
        }
        // If mean residual across open bins is large, existing bins are
        // wasteful anyway; opening fresh is less bad.
        nb -= 0.3 * mean_residual;
        score = nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward tight fits.
    score -= (item_size as f64 / bin_capacity as f64) * 25.0;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: penalize spreading across many bins slightly.
    score += open_bins_count as f64 * 0.8;

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate: neutral baseline with mild preference early in stream,
    // penalized later to force consolidation.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 25.0 + progress * 30.0 - mean_residual * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-perfect match for the next item (small slack tolerable).
    else if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 5 {
        score -= 500.0 - (post_residual - next_item_size) as f64 * 50.0;
    }

    // Penalize dead space: post_residual too small to host the next item.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Waste is worse if it's small-but-unusable; scale with progress.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (next_item_size - post_residual) as f64 * (5.0 + 10.0 * progress);
    }

    // Reward tight packing relative to current mean residual.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New empty bin candidate: penalize so it's chosen only when nothing fits well.
    if bin_residual == bin_capacity {
        score += 300.0 + open_bins_count as f64 * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional tightness: reward placing into bins that become nearly full.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Lookahead: if the next item can fit into post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Dead space for the known next item: penalize proportionally.
        let dead = (post_residual as f64 - 0.0).max(0.0);
        score += 0.25 * dead;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when all open bins fit poorly.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin, decaying as the stream progresses
        // (early on, opening bins is cheap and useful; late, prefer packing).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 55.0 + 45.0 * progress;
        // If item is large relative to mean residual of open bins, new bin is fine.
        let mean_res_u = mean_residual.max(0.0);
        if (mean_res_u < item_size as f64) || open_bins_count == 0 {
            new_bin_cost -= 50.0;
        }
        // Large items deserve fresh bins more than small ones.
        new_bin_cost -= 0.3 * item_size as f64;
        score = post_residual as f64 + new_bin_cost;
    }

    // Mild global pressure: many open bins -> prefer consolidating into existing ones.
    if bin_residual != bin_capacity {
        score += 0.05 * open_bins_count as f64;
        // Prefer bins whose residual deviates below the mean (more "specialized" space).
        score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = post * (1.0 + 0.6 * progress * pr);

    // Reward tight fits quadratically
    let fit_quality = 1.0 - pr;
    score -= 12.0 * fit_quality * fit_quality;

    // Penalize dead space that becomes unusable relative to mean residual
    if post > 0.0 {
        let dead = (post - mean_residual).max(0.0) / cap;
        score += 8.0 * dead * dead * (1.0 + progress);
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (nx / cap)) * (1.0 + 0.5 * progress);
        } else {
            score += 4.0 * (1.0 - post_residual as f64 / nx.max(1.0));
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).ln().max(0.0);
    }

    // Mild preference for keeping few open bins early, more freedom late
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modular arithmetic on capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class A: post_residual in "perfect" slots (0, or small multiples of common item sizes)
    if post_residual == 0 {
        score -= 1000.0; // perfect fit, always best
    } else if post_residual <= 10 {
        score += 40.0; // dead space too small for any item (min size 1..100, but tiny gaps rarely reusable)
    } else if post_residual < 25 {
        score += 15.0;
    }

    // Integer-division harmonic class: post_residual / 10 residue classes
    let class = (post_residual / 10) % 4;
    match class {
        0 => score -= 5.0,   // multiples of 40-ish usable chunks
        1 => score += 0.0,
        2 => score += 8.0,   // awkward mid gaps
        _ => score += 3.0,
    }

    // Reward bins whose residual matches next item size well (lookahead harmony)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let slack = post as f64 - nxt;
            // prefer post_residual close to next_item_size (tight two-item harmony)
            score -= 25.0 * (1.0 - slack / cap);
            if post_residual == next_item_size {
                score -= 30.0; // exact pairing
            }
        } else {
            // post_residual can't hold next item: dead end unless class is tiny
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: high, so it's chosen only when open bins waste space
        score = cap - item_size as f64; // residual after placement in fresh bin
        score += 120.0; // opening cost
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open
        } else if fitting_bins_count == 1 {
            // competing with last-chance bin: only open if that bin would leave huge waste
            score -= 40.0;
        }
        // Late in stream, opening new bins is less costly (bins get flushed anyway)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * progress;
    }

    // Mild preference for tighter bins overall (low residual before placement)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Encourage filling bins with many open bins (reduce bin sprawl)
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0; // dead space in [1,9] is nearly worthless
    }
    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Tightness reward: fraction of residual consumed by this item.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 80.0;
    }
    // Penalize leaving a gap the next item cannot use.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no open bin offers a decent fit; make the empty bin moderately costly by default.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Late in the stream, opening new bins is less useful (tail waste).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 50.0 * progress;
        // But if many bins are open and mean residual is small, a new bin is fine.
        if mean_residual < 15.0 && open_bins_count > 3 {
            score -= 45.0;
        }
    }

    // Mild preference for bins whose residual deviates favorably from the mean.
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits into the post residual: good lookahead
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.3 * (post_residual - next_item_size) as f64;
    }
    // Next item cannot fit: penalize proportional to wasted residual
    else if next_item_size > 0 && post_residual > 0 {
        let wasted = post_residual as f64 / bin_capacity as f64;
        score += 20.0 * wasted;
    }

    // Penalize small unusable gaps (dead space) relative to capacity
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Favor tighter fits: small post_residual relative to mean residual
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Last chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a bad fit
    if bin_residual == bin_capacity {
        score += 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 5.0;
        }
    }

    // Late in the stream: consolidate, avoid opening new bins
    let progress = step_index as f64 / total_items as f64;
    score -= 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Penalize large dead space that can never be used by typical items.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-perfect fill
    }
    if post_residual > 50 {
        score += 8.0; // wasteful large gap when item was small
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.3 * item_size as f64;
    }

    // New-bin candidate handling: make empty bins mildly attractive only when
    // no open bin fits well or the lookahead item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let lookahead_pressure = if next_item_size > 0 {
            (next_item_size as f64 / bin_capacity as f64).powi(2)
        } else {
            0.0
        };
        // Prefer new bins early or when many open bins already exist (fragmentation).
        score += 20.0 - 15.0 * progress - 0.5 * open_bins_count as f64
                 - 30.0 * lookahead_pressure;
        // If the current item leaves a good residual for the next item, favor the new bin less.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 10.0;
        }
    }

    // Lookahead synergy: reward placements whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // perfect chain
        } else if post_residual > next_item_size {
            score -= 2.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            score += 3.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Global state coupling: when mean residual is high, prefer bins that
    // reduce variance (post_residual near mean_residual).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: normalized fill ratio, amplified by progress
    let fill = (bin_residual as f64 - post) / cap;
    score -= fill * fill * (30.0 + 40.0 * progress);

    // Non-linear dead-space penalty: small post_residual is fine, mid-range residuals are wasteful
    let dead = post / cap;
    score += dead * dead * (1.0 - dead) * 25.0 * (1.0 - progress);

    // Last-chance bonus: strongly prefer the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0 + 25.0 * progress;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 12.0 * (1.0 - (post - nxt) / cap) * (0.5 + 0.5 * progress);
        } else if post > 0.0 {
            score += 8.0 * (1.0 - post / cap);
        }
    }

    // New-bin candidate: attractive early, less so as stream progresses
    if bin_residual == bin_capacity {
        score -= 55.0 * (1.0 - progress) * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    // Mild preference relative to mean residual spread
    score -= (mean_residual - post) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets (integer division on post_residual).
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Dead-space classes: residual below a half-item quantum is nearly unusable.
    if post_residual < eighth {
        // Tiny leftover: excellent packing (near-perfect fit).
        score -= 30.0;
    } else if post_residual < quarter {
        // Small leftover: still good.
        score -= 12.0;
    } else if post_residual < bin_capacity / 2 {
        // Medium leftover: neutral to slightly penalized.
        score += 5.0;
    } else {
        // Large leftover: wasteful placement for a big item.
        score += 15.0;
    }

    // Modulo-arithmetic harmonic classes on post_residual:
    // residues divisible by common item-size steps (10, 20, 25) are
    // more likely to be filled by future items.
    let r = post_residual;
    if r > 0 && (r % 10 == 0 || r % 20 == 0 || r % 25 == 0) {
        score -= 8.0;
    }
    // Odd, awkward residues are harder to fill later.
    if r % 2 == 1 && r > 0 {
        score += 3.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this bin (harmonic pair).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves another leftover: mild reward scaled
            // by how well it harmonizes (integer division threshold).
            let pair_left = post_residual - next_item_size;
            if pair_left < eighth {
                score -= 15.0;
            } else {
                score -= 4.0;
            }
        } else {
            // Next item cannot use this bin's leftover: penalize slightly,
            // unless the leftover is tiny anyway.
            if post_residual >= eighth {
                score += 6.0;
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, opening a new bin
    // would strand this bin's residual forever.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Base aversion to opening a new bin while others fit.
        score += 45.0;
        // But if the item is huge and would leave a very small residual in
        // any existing bin, opening fresh is fine: reduce penalty.
        if item_size > bin_capacity / 2 && post_residual < eighth {
            score -= 35.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // Few open bins => new bin less costly.
        if open_bins_count <= 2 {
            score -= 15.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (tighter bins get filled first, keeping large residuals flexible).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Prefer bins that can also host the lookahead item afterwards,
    // scaled by how many alternatives exist.
    if fitting_bins_count > 3 {
        score += 2.0; // many alternatives: be pickier (mild penalty via positive shift)
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
