    // Penalize near-miss residuals that block the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Discourage spreading across many bins when mean residual is low (bins nearly full)
    score += 0.3 * mean_residual;

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins have poor fit or the item is large relative to residuals
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_aversion = (item_size as f64 / bin_capacity as f64).powf(2.0);
        // penalize new bin mildly, less so late in stream or for large items
        score += 60.0 - 40.0 * progress - 30.0 * waste_aversion;
        // opening a bin when many are open and residuals are tight is fine
        score -= 5.0 * open_bins_count as f64 * (1.0 - mean_residual / bin_capacity as f64);
    }

    // Prefer tighter bins (small residual before placement) slightly
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear penalty for residual that is hard to reuse later.
    let pr_norm = pr / cap;
    score += 25.0 * pr_norm * pr_norm * (1.0 - pr_norm) * (1.0 - progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    score -= (1.0 - pr_norm) * (1.0 + 3.0 * progress) * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = pr - nxt;
            score -= 12.0 * (1.0 - gap / cap);
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Prefer bins with below-average residual (keep large residuals for future large items).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev.abs();

    // Mild penalty for spreading across many open bins early on.
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) - 8.0 * progress;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify dead space by capacity fraction.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Reward near-perfect fits (post_residual in low harmonic classes).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    } else if post_residual <= 20 {
        score -= 80.0;
    } else if post_residual <= 30 {
        score -= 30.0;
    }

    // Modulo arithmetic on post_residual: multiples of 10 are "harmonic slots"
    // that other items (sizes 10..80, often multiples of 10) can fill.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 40.0;
    } else {
        // Non-harmonic residue: penalize proportionally to how unusable it is.
        score += (10 - (post_residual % 10)) as f64 * 2.0;
    }

    // Integer-division thresholds: can the lookahead item fit here?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Lookahead fits: reward, more so if it lands on a harmonic boundary.
            score -= 60.0;
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 25.0;
            }
        } else {
            // Lookahead stranded: penalize dead space this creates.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item is large relative to mean residual capacity elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Slight bias toward compacting early, opening bins late.
        score += 30.0 + 40.0 * (1.0 - progress);
        if mean_residual >= item_size as f64 {
            score += 120.0; // an open bin already accommodates it
        }
        if next_item_size > 0 && bin_capacity - item_size >= next_item_size {
            score -= 20.0; // new bin can host both current and next item
        }
    }

    // Coupling with mean residual: prefer bins whose residual deviates
    // favorably (tighter than average) from the fleet mean.
    score += (mean_residual - pr) * 0.15;

    // Mild preference for filling bins with larger current residual when
    // many bins are open (spread load), else concentrate.
    if open_bins_count > 8 {
        score += pr * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit gets strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward placements that leave room for the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // gap that blocks the next item
    }

    // Last-chance bin before opening a new bin: prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, favor compacting into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.6 + 0.4 * progress);

    // Prefer bins whose residual is close to the mean residual (balanced packing).
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    // Discourage opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fits (dead space elimination)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // 2-step lookahead: reward when next item fits perfectly in the post-residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportional to tightness of the 2-step match
            if slack <= 10.0 {
                score -= 25.0 * (1.0 - slack / 10.0);
            } else {
                // penalize leaving large unusable gaps relative to next item
                score += slack * 0.15;
            }
        } else {
            // next item cannot fit here: mild penalty scaled by overflow
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.1;
        }
    }

    // Compare post_residual against mean residual: avoid making bin much
    // worse than the fleet average (keeps bins homogeneous)
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += dev * 0.25;
    } else {
        score += dev * 0.05;
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current post
    // residual would be large dead space and next item needs a fresh bin
    if bin_residual == bin_capacity {
        let base = 45.0;
        // cheaper to open new bin when no open bin has a good fit
        if next_item_size > 0 && post_residual == bin_capacity {
            score = base;
        } else {
            score = base + 20.0;
        }
        // if this is the only fitting bin scenario is impossible for empty bin
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // late in stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Slight preference for filling fuller bins (small residual before placement)
    score += (bin_residual as f64 / bin_capacity as f64) * 3.0;

    // Mild pressure to keep number of open bins low
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), but with diminishing returns
    // so that tiny dead space matters more than moderate leftovers.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 40.0;

    // Penalize small "unusable" leftovers (dead space) nonlinearly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / 100.0);
        } else {
            // leftover too small for the next item: penalize proportionally
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    } else {
        // Last item: just minimize waste directly.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Multiple options: mild penalty to encourage keeping options open for other items.
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: empty bin gets a dynamic cost that decreases
    // when open bins are mostly full or numerous.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        // Opening cost: high early, lower late; reduced when open bins are well-filled.
        let open_cost = 45.0 * (1.0 - 0.5 * progress) * (1.0 - 0.6 * avg_fill);
        score = open_cost + item_size as f64 * 0.2;
        // If next item is large and won't fit anywhere else, opening fresh is fine.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Prefer filling bins that are already below-average residual (consolidate fullness).
    let residual_gap = bin_residual as f64 - mean_residual;
    score += residual_gap * 0.15;

    // Slight preference for fewer open bins (bin-count pressure grows over stream).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;

    // Base: penalize post_residual with a convex (quadratic) term so tight fits are favored.
    let norm_post = post / cap;
    let mut score = post * (1.0 + norm_post);

    // Non-linear coupling: as the stream progresses, waste becomes more costly.
    score *= 1.0 + 0.6 * progress * norm_post;

    // Reward near-perfect fits (small post_residual) more aggressively late in the stream.
    score -= 12.0 * (1.0 - norm_post) * (1.0 - norm_post) * (0.5 + progress);

    // Lookahead: if the next item fits exactly into post_residual, strongly reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = (post - nxt) / cap;
            score -= 10.0 * (1.0 - gap) * (1.0 - gap);
        } else {
            // Dead space that next item cannot use: penalize proportionally to overflow.
            score += 4.0 * ((nxt - post) / cap);
        }
    } else {
        // Last item: any residual is pure waste.
        score += 6.0 * norm_post;
    }

    // Last-chance bin: if this is the only bin that fits, opening a new bin is wasteful.
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        // Many alternatives: mild penalty so the emptiest-best fit wins.
        score += 0.5 * (fitting_bins_count as f64).ln();
    }

    // Contextual term: prefer bins whose residual deviates favorably from mean residual.
    score += 0.3 * (resid - mean_residual) / cap;

    // New-bin candidate: make it moderately attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        let tightness = (post / cap).min(1.0);
        score = 20.0 * (1.0 - progress) * (1.0 - tightness) + 15.0 * tightness;
        if fitting_bins_count <= 1 {
            score += 5.0; // discourage abandoning the only fitting bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: waste quantization.
    // Residuals in the "dead zone" (1..10) are nearly unusable (min item = 1,
    // but tiny residuals pair poorly) — penalize them super-linearly.
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0 * (11.0 - post_residual as f64);
    }

    // Perfect fit: zero waste is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Harmonic pairing: does the leftover exactly accommodate the next item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0; // chain fit
        } else if post_residual > next_item_size {
            // leftover can still host the next item: mildly good
            score -= 4.0;
            // extra bonus if leftover is a near-multiple of next item
            if post_residual % next_item_size == 0 {
                score -= 6.0;
            }
        } else {
            // leftover too small for next item: penalize dead space
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when current residuals
    // are fragmented or the item fits nothing well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so we prefer existing bins with good fits...
        score += 12.0;
        // ...but if many bins compete (item fits several), keep new bin unattractive.
        if fitting_bins_count >= 2 {
            score += 15.0;
        }
        // If residuals across open bins are large and fragmented, a fresh bin
        // is attractive: subtract to allow opening.
        if mean_residual > 30.0 && fitting_bins_count >= 1 {
            score -= 10.0;
        }
        // Large items early in the stream benefit from a fresh bin.
        if item_size >= 60 {
            score -= 14.0;
        }
        // Late in the stream, avoid spawning bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    } else {
        // Prefer tighter existing bins: reward small post_residual nonlinearly.
        score -= (bin_capacity - post_residual) as f64 * 0.15;
        // Reward bins whose residual is in a "harmonious" class (multiple of 10).
        if bin_residual % 10 == 0 {
            score -= 3.0;
        }
        // Slight preference for bins below mean residual (tighter than average).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    // Penalize creating residual that is awkwardly between usable classes
    // (e.g., 11..19 is only usable by small items).
    if post_residual >= 11 && post_residual <= 19 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small for typical items are wasted.
    // Penalize gaps that are tiny but nonzero far more than linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item can fit in the post residual, reward this bin;
    // if the next item would exactly fill it, reward even more.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            score -= 15.0;
        } else {
            // Next item cannot use this gap -> gap is likely dead space.
            score += post_residual as f64 * 0.5;
        }
    }

    // Open-bin pressure: discourage opening new bins when several bins are open.
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        // Baseline penalty grows with number of open bins, but relaxes if this
        // item is a poor fit everywhere (only one fitting bin => last chance).
        let pressure = 18.0 + (open_bins_count as f64) * 4.0;
        let last_chance_relief = if fitting_bins_count <= 1 { 25.0 } else { 0.0 };
        score += pressure - last_chance_relief;
        // If mean residual across open bins is large, opening a new bin is wasteful.
        score += mean_residual * 0.3;
    } else {
        // Reward using existing bins, especially when many are open.
        score -= 5.0 + (open_bins_count as f64).sqrt() * 2.0;
    }

    // Slight preference to fill tighter bins first (relative fill ratio).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    // Mild stream-progress adaptation: later in stream, be more frugal with new bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if new_bin_candidate {
            score += progress * 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack_after_next / bin_capacity as f64);
        } else {
            // Next item cannot follow in this bin: penalize dead space.
            score += 12.0 + (post_residual as f64) / bin_capacity as f64 * 10.0;
        }
    } else {
        // Last item: prefer tightest fit.
        score += 5.0;
    }

    // Compare residual against mean residual of open bins: prefer filling below-average-residual bins.
    score -= 0.35 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Penalize opening a new bin when open bins exist and fit is decent.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0 + 0.25 * post_residual as f64;
    }

    // Late in the stream, tighten packing more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward low post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize creating dead space that the next item cannot use (lookahead k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Post residual can host the next item: reward usable slack.
            let usable = (post_residual - next_item_size) as f64;
            score -= 3.0 * (1.0 - usable / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize proportionally.
            let gap = (next_item_size - post_residual) as f64;
            score += 2.0 * gap / 100.0;
        }
    } else {
        // Last item: pack as tightly as possible.
        score -= 5.0 * tightness;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 15.0;
        // Late in the stream, opening new bins wastes capacity; penalize more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 6.0 * (fitting_bins_count as f64).min(5.0);
        }
        // If mean residual across open bins is large, prefer reusing them.
        score += (mean_residual / bin_capacity as f64) * 8.0;
    }

    // Mild preference for bins with below-average residual (keep some bins
    // tight, others free) to preserve placement flexibility.
    if !is_new_bin {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.5 * diff / bin_capacity as f64;
    }

    // Slight penalty for accumulating many open bins: encourage consolidation.
    score += 0.05 * open_bins_count as f64 * (1.0 - tightness);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) - norm_pr * (1.0 - progress);
    score += 12.0 * poly * cap * 0.1;

    // Reward tight fits increasingly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (8.0 + 14.0 * progress);

    // Penalize dead space relative to mean residual
    score += 0.35 * (pr - mean_residual).abs();

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0 + 10.0 * progress;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= fits_next * (6.0 * (1.0 - progress) + 3.0);
        let gap = (pr - next_item_size as f64).abs();
        score += 0.2 * gap;
    } else {
        score -= 4.0 * tightness;
    }

    // Mild penalty for proliferating many open bins late in stream
    score += 0.05 * open_bins_count as f64 * progress;

    // Slight preference to keep new-bin option available early
    if bin_residual == bin_capacity {
        score += 3.0 * (1.0 - progress) - 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common
    // item sizes (or landing in coarse quarter-classes) are more reusable.
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter; // 0..=4 harmonic class
    score += 8.0 * class as f64; // prefer smaller residual classes

    // Modulo bonus: residual divisible by 10 (or 20) is highly reusable
    // for integer-sized future items.
    if post_residual % 20 == 0 {
        score -= 12.0;
    } else if post_residual % 10 == 0 {
        score -= 6.0;
    }

    // Penalize tiny dead space (unusable slivers) but also penalize
    // leaving a residual that is smaller than the minimum plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // strongly reward this placement (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            // next item cannot use this residual: mild penalty proportional
            // to how much would be stranded.
            score += 0.1 * (post_residual as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity as u32 {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when current fits are poor (large post_residual waste
    // elsewhere) or late in the stream when many bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base cost of opening a new bin.
        score += 40.0;
        // If the mean residual across open bins is small, open bins are
        // nearly full -> a fresh bin is reasonable.
        if mean_residual < 20.0 {
            score -= 35.0;
        }
        // Late in stream with many open bins, keep consolidation.
        if progress > 0.7 && open_bins_count > 4 {
            score += 20.0;
        }
        // If next item is large, a fresh bin is valuable.
        if next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Slight preference for tighter bins among equals.
    score += 0.05 * (bin_residual as f64 - post_residual as f64) * 0.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (gaps too small for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Strong penalty for dead space in the 10..30 range (hard to fill later)
    if post_residual >= 10 && post_residual < 30 {
        score += 12.0 * (1.0 - (post_residual as f64 - 10.0) / 20.0);
    }

    // Reward tight fits: exact or near-exact fills
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Open bins pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 0.5;

    // Last-chance bonus: if this is the only fitting bin, prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item cannot fit in post_residual but could fit elsewhere, mild penalty
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // New-bin candidate handling: prefer new bin only when it avoids bad fragmentation
    if bin_residual == bin_capacity {
        // New bin is neutral baseline; slight bias so tight fits in open bins win
        score += 5.0;
        // But if open bins are very full on average, opening a fresh bin is fine
        if mean_residual < 15.0 {
            score -= 30.0;
        }
    }

    // Progression: later in the stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    // Prefer bins whose residual deviates favorably from the mean (filling fuller bins)
    score -= (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual can host next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 / (1.0 + slack / 10.0);
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Penalize dead space relative to mean residual of open bins.
    let dead = post_residual as f64;
    if dead > mean_residual {
        score += (dead - mean_residual) * 0.25;
    } else {
        score -= (mean_residual - dead) * 0.1;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current bin fit would be very poor.
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && post_residual == bin_capacity - item_size && post_residual < next_item_size {
            score -= 30.0;
        }
    }

    // Tight fits are good.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 8.0;

    // Late in stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post-residual, with a superlinear penalty on mid-size waste.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_frac * waste_frac;

    // Lookahead: strongly reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 + 8.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Penalize bins that would leave a gap just below the next item's size (dead space trap).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: default penalty so open bins are preferred, but relax it
    // when the item is large and fits nowhere well (poor fit in open bins).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let big_item = item_size as f64 > 0.6 * bin_capacity as f64;
        let mut new_bin_score = 40.0 - 25.0 * progress;
        if big_item {
            new_bin_score -= 10.0; // large items pair well with fresh bins
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 60.0; // must open a new bin anyway
        }
        // If open bins are all crowded (low mean residual), fresh bin is attractive.
        new_bin_score -= (mean_residual / bin_capacity as f64) * 10.0;
        score += new_bin_score;
    } else {
        // Prefer filling bins that are already relatively full (best-fit flavor).
        let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 20.0 * fullness * fullness;
        // Slight penalty for spreading across too many open bins.
        score += 0.3 * open_bins_count as f64;
    }

    // Exact fit celebration.
    if post_residual == 0 {
        score -= 25.0;
    }
    // Tiny unusable residue is bad unless it's an exact fit.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear waste penalty: quadratic growth of dead space cost.
    let norm_post = post / cap;
    score += 2.0 * norm_post * norm_post * cap;

    // Reward tight fits with smooth saturating term.
    score -= 10.0 * (item / cap) * (1.0 - norm_post).powi(2);

    // Stream-progress coupling: late in the stream, waste is more costly.
    score += progress * norm_post * cap * 0.5;

    // Last-chance bin before opening a new bin: strong reward.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: penalize if the next item cannot use this bin's post-residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 8.0 + 4.0 * (nxt - post) / cap;
        } else {
            score -= 4.0 * (1.0 - (nxt / cap));
        }
    }

    // Prefer bins below mean residual (balance load) with smooth coupling.
    score += 0.3 * (post - mean_residual);

    // New-bin candidate: neutral-ish score so it wins only when open bins waste much.
    if bin_residual == bin_capacity {
        score = cap * (1.0 + progress) - 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 and modulo 25.
    let r10 = post_residual % 10;
    let r25 = post_residual % 25;

    // Dead-space penalty: residuals < 10 are nearly unusable (min item size 10).
    if post_residual < 10 {
        score += 40.0;
    } else {
        // Reward residuals that are multiples of 10 (perfectly divisible space).
        if r10 == 0 {
            score -= 12.0;
        }
        // Penalize awkward odd residues in the mid-range.
        if r10 >= 1 && r10 <= 3 && post_residual > 20 {
            score += 6.0;
        }
        // Reward residuals that are multiples of 25 (harmonic with 100).
        if r25 == 0 {
            score -= 8.0;
        }
    }

    // Integer-division thresholds: how many min-size items still fit.
    let slots = post_residual / 10;
    score -= (slots as f64) * 3.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 25.0;
        } else if gap < 10 {
            score -= 15.0;
        } else {
            score -= 5.0;
        }
    }
    // Penalize when next item would leave this bin stranded anyway.
    if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: fresh bin only attractive if current fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 55.0;
        // More attractive early in the stream or when open bins are tight.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        }
        // Discourage new bins when mean residual is still large.
        score += (mean_residual / bin_capacity as f64) * 30.0;
        if fitting_bins_count == 1 {
            score += 25.0;
        }
    }

    // Mild pressure to consolidate: fewer open bins relative to stream is better.
    score += (open_bins_count as f64) * 0.15;

    // Small tie-breaker on tighter fit.
    score += (item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never be used
    // (smaller than the minimum plausible item) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }
    // Mid-range dead space (hard to fill) gets a graded penalty.
    if post_residual >= 10 && post_residual < 25 {
        score += (25 - post_residual) as f64 * 2.5;
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 3.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // New-bin candidate bias: only attractive when existing bins are crowded
    // or the fit is bad.
    if bin_residual == bin_capacity {
        score += 18.0 + mean_residual * 0.15;
    }

    // Stream progression: late in the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    } else {
        score -= progress * 4.0;
    }

    // Slight preference for bins below mean residual (balancing loads).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary objective: tight packing -> penalize large post_residual.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);

    // Aggressive 2-step lookahead: reward exact match of next item into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let match_slack = (post_residual - next_item_size) as f64;
        // Perfect follow-up (post_residual == next_item_size) is heavily rewarded.
        if match_slack == 0.0 {
            score -= 60.0;
        } else {
            score -= 40.0 * (1.0 - match_slack / (bin_capacity as f64));
        }
    } else if next_item_size > 0 {
        // Next item cannot follow: penalize dead space creation.
        score += 12.0;
    }

    // Relative-to-mean coupling: prefer bins below mean residual when fit is tight.
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.05 * mean_gap;

    // Last-chance bin before opening a new bin: strong reward to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when it enables a perfect 2-step chain
    // (item + next item exactly fills a fresh bin) or open bins are very fragmented.
    if bin_residual == bin_capacity {
        let mut bonus = 30.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            bonus -= 45.0 * (1.0 - leftover as f64 / bin_capacity as f64);
        }
        // Dampen new-bin eagerness as stream progresses / many bins open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        bonus += 10.0 * progress + 0.5 * open_bins_count as f64;
        score += bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Opening a new bin is only attractive when no open bin fits,
        // or when all fitting bins would leave terrible dead space.
        if fitting_bins_count == 0 {
            score -= 1000.0; // forced open
        } else {
            // mild preference for fresh bin only for huge items
            score += 40.0 + 0.5 * (item_size as f64);
        }
        return score;
    }

    // Reward near-perfect fits (small post residual already does this; amplify).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual > 50 {
        score += 8.0; // heavy dead-space penalty
    }

    // Lookahead: reward bins whose residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.05 * next_item_size as f64;
        } else if post_residual > 0 && post_residual < 10 {
            score += 5.0; // creates unusable sliver for typical items
        }
        // If next item fits this bin exactly after placement, strong bonus
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins below mean residual (tighter bins absorb items better).
    score += 0.15 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // Late in the stream, consolidate: favor already-open bins more strongly.
    score -= 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits less aggressively; later, punish wasted space more.
    let progress_warp = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 12.0 * progress_warp * x * (1.0 - x) * cap * 0.5;
    score -= 20.0 * (1.0 - progress_warp) * x * x;

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 6.0 + 10.0 * progress_warp;
    }

    // Reward bins that leave room for the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 5.0 * (1.0 - progress_warp);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mild penalty when bin residual deviates from mean residual (keeps diversity)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate: penalize slightly so open bins are preferred unless fit is bad
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * x * (1.0 - x) * 0.0 + 3.0 * progress_warp;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover is a small
    // multiple of the smallest item quantum (mod classes) are "dead" space.
    let pr = post_residual;
    if pr > 0 {
        // Penalize residuals that fall into awkward modulo classes.
        let class = pr % 10;
        let class_penalty: f64 = match class {
            0 => -12.0,          // perfectly quantized leftover: reusable
            1 | 2 | 3 => 8.0,    // sliver classes: nearly unusable
            4 | 5 | 6 => 2.0,
            _ => -2.0,
        };
        score += class_penalty;

        // Dead-space threshold: leftover below typical minimum item size.
        if pr < 10 {
            score += 25.0;
        }
    } else {
        // Perfect fill is excellent.
        score -= 40.0;
    }

    // Integer-division harmony: does the leftover exactly fit the lookahead item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual >= next_item_size {
            let q = post_residual / next_item_size.max(1);
            match q {
                1 => score -= 6.0,
                2 => score -= 3.0,
                _ => {}
            }
            if post_residual % next_item_size.max(1) == 0 && q >= 1 {
                score -= 4.0;
            }
        } else {
            // Lookahead cannot use this bin's leftover at all.
            score += 6.0;
        }
    } else {
        // Last item: prefer tightest fill, ignore future concerns.
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: only attractive when open bins are crowded or the
    // fit would create large dead space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let crowded = mean_residual < item_size as f64 * 1.2;
        let bad_fit = post_residual > 0 && (post_residual as f64) > bin_capacity as f64 * 0.4;
        if crowded && bad_fit {
            score -= 20.0;
        } else if bad_fit && progress > 0.5 {
            score -= 5.0;
        } else {
            score += 12.0;
        }
    }

    // Slight preference for bins tighter than average.
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are nearly worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + 4.0 * (10 - post_residual) as f64;
    }
    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item (k=2).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Penalize if post-residual is just barely too small for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, prefer packing tighter bins.
    score += 2.0 * open_bins_count as f64;
    score -= 0.5 * mean_residual;

    // New-bin candidate: only attractive when current fit creates big dead space
    // or no good alternative exists.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 20.0
            + 3.0 * open_bins_count as f64
            + (item_size as f64).max(0.0) * 0.1;
        if fitting_bins_count <= 1 {
            score -= 70.0;
        }
        if next_item_size > 0 && item_size >= next_item_size {
            score -= 10.0; // big-first into fresh bin is good
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 15.0;

    // Aggressive 2-step lookahead: reward when next item fits the post_residual exactly
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_gap = post_residual - next_item_size;
            score -= 10.0 * (1.0 - next_gap as f64 / bin_capacity as f64);
        } else {
            // Next item cannot follow into this bin: penalize dead space
            score += 5.0 + (post_residual as f64 / bin_capacity as f64) * 10.0;
        }
    } else {
        // Last item: pure tightness
        score -= 8.0;
    }

    // Perfect chain: post_residual == next_item_size exactly
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    // Relative to mean residual: prefer bins that are tighter than average
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize opening a new bin when open bins exist with decent fit
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 6.0;
    }

    // Early in stream: slightly favor new bins to build diversity
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        let leftover_after_next = post_residual - next_item_size;
        if leftover_after_next < 10 {
            score -= 8.0; // perfect pair placement
        }
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // This bin wastes the chance to also fit the next item.
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: prefer consolidating into fuller bins (higher mean fill).
    if open_bins_count > 3 {
        let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 10.0 * fill;
        // Penalize bins far below the mean residual (they're outliers).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Time horizon: early in the stream, be conservative (avoid fragmenting);
    // late in the stream, squeeze every bin.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * tight;

    // New-bin candidate: only attractive when no open bin fits well or
    // the item is huge relative to remaining residuals.
    if bin_residual == bin_capacity {
        let crowding = if fitting_bins_count == 0 { 0.0 } else { 1.0 / fitting_bins_count as f64 };
        score += 18.0 * crowding; // penalize new bin if other bins fit
        if item_size >= 60 {
            score -= 10.0; // large items start fresh bins more willingly
        }
        if progress > 0.8 {
            score += 10.0; // late stream: avoid new bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear shaping.
    let mut score = pr + 12.0 * pr_norm * pr_norm * cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, dead space matters less; late, it is heavily penalized.
    let coupling = pr_norm * (1.0 - pr_norm);
    score += 40.0 * coupling * (0.5 - progress).powi(2) * (1.0 - progress);

    // Penalize post_residual that is small-but-unusable (dead space zone).
    let dead = (pr_norm * (1.0 - pr_norm) * 4.0);
    score += 8.0 * dead * (1.0 - dead);

    // Last-chance bonus: only fitting bin -> strong reward (subtract).
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: reward if next item fits the post residual.
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 6.0 * (next_item_size as f64 / cap);
        } else {
            score += 4.0 * (1.0 - pr_norm);
        }
    }

    // Prefer bins with residual below mean (consolidation).
    score += 2.0 * (pr - mean_residual) / cap;

    // Slight preference for fewer bins being consumed by this placement.
    score += (open_bins_count as f64).sqrt() * pr_norm * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small" classes are more valuable (less dead space).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class 0: near-perfect fit -> strong reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    }

    // Harmonic ladder: post_residual divisible by small classes (10, 20, 25)
    // tends to remain usable for common item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Dead-space penalty: leftover too small for the smallest plausible item (1..100 range)
    // treat leftovers below ~15 as risky unless zero.
    if post_residual > 0 && post_residual < 12 {
        score += 6.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 35.0;
        } else if gap <= 10 {
            score -= 12.0;
        } else {
            score -= (10.0 - gap as f64).max(0.0);
        }
    } else if next_item_size > 0 {
        // next item won't fit here: slight penalty proportional to wasted potential
        score += (next_item_size as f64 - post) * 0.15;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when current bin fits poorly
    // or stream is early with few open bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = cap * 0.75 + 30.0;
        // Early stream: opening bins is cheaper (build diversity).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 25.0;
        // If no open bin fits (fitting_bins_count counts open bins that fit;
        // a new bin always "fits", so >1 means others fit too).
        if fitting_bins_count <= 1 {
            score -= 55.0; // forced open
        }
        // Large items leave less usable residual in shared bins; prefer new bin
        // for big items when mean residual is low anyway.
        if item_size > 60 && mean_residual < 25.0 {
            score -= 15.0;
        }
    }

    // Prefer tighter bins overall: compare against mean residual.
    score += (mean_residual - (bin_residual as f64)) * 0.1;

    // Mild penalty for accumulating many open bins with large residuals (fragmentation).
    if open_bins_count > 8 && post > 50.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (size 1) are fine, but residuals that are tiny relative
    // to plausible item sizes represent unusable gaps.
    // Penalize post_residual in the "dead zone" [1..=12] heavily.
    if post_residual > 0 && post_residual <= 12 {
        score += 40.0 * (13.0 - post_residual as f64);
    }

    // Reward tight fits (post_residual near 0 but not in dead zone).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // If this bin can also host the lookahead item well, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
        // Extra reward if lookahead fills the bin almost exactly.
        let pr2 = post_residual - next_item_size;
        if pr2 <= 5 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Lookahead won't fit here: this bin becomes dead after placement.
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage proliferation of open bins slightly,
    // but encourage opening a new bin when many poorly-fitting bins exist.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate handling: empty bin gets a baseline cost so it is
    // only chosen when existing bins score poorly (poor fits / dead space).
    if bin_residual == bin_capacity {
        score += 30.0 + 1.5 * open_bins_count as f64;
        // Late in the stream, prefer consolidating into open bins.
        score += 20.0 * progress;
    }

    // Compare against mean residual: bins far below mean residual are
    // already cramped; prefer filling those first (lower residual = lower score).
    score -= 0.2 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect fits (post_residual == 0)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item can also fit here afterward: reward tight leftover
            let gap = (post_residual - next_item_size) as f64;
            score -= 100.0 / (1.0 + gap / 10.0);
        } else {
            // next item cannot fit in leftover: penalize dead space
            let dead = (next_item_size - post_residual) as f64;
            score += dead * (1.0 + dead / 50.0);
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual
    let residual_f = bin_residual as f64;
    score += (residual_f - mean_residual) * 0.5;

    // Penalize large post_residual waste nonlinearly
    score += (post_residual as f64).powi(2) / 200.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Slight preference to reuse existing bins over opening new ones early
    if bin_residual == bin_capacity {
        score += 50.0 + (open_bins_count as f64) * 2.0;
    }

    // Late-stream pressure: consolidate more aggressively near the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness: reward small post-residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Lookahead: penalize leaving a residual that is awkward for the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // reward residuals that can host the next item
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 / (1.0 + slack);
        } else {
            // dead space relative to next item
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
        // exact next-item fit is excellent
        if post_residual == next_item_size {
            score -= 250.0;
        }
    } else {
        // last item: just minimize residual
        score -= 100.0;
    }

    // Global state coupling: many open bins with high mean residual -> prefer filling existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (10.0 + progress * 40.0);
    if bin_residual < bin_capacity {
        score -= 30.0 * pressure * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate handling: opening a new bin wastes the residual of this empty slot;
    // only attractive when current item leaves a very poor fit elsewhere or stream is early.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score += 150.0;                     // base penalty for opening a new bin
        score += waste * (0.8 - 0.5 * progress); // large leftover space is worse later
        if next_item_size > 0 && waste >= next_item_size as f64 {
            score -= 0.3 * waste;           // fresh bin can absorb the next item too
        }
        if fitting_bins_count <= 1 {
            score -= 120.0;                 // no real alternative anyway
        }
    }

    // Prefer bins whose residual is close to item size (fractional tightness)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = norm_pr * norm_pr * (0.5 + 0.5 * progress) - norm_pr * (0.3 + 0.4 * progress);
    score += 20.0 * poly;

    // Reward tight fits more strongly as the stream progresses.
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 20.0 * progress);

    // Penalize residual that no plausible next item fits (dead space).
    if next_item_size > 0 {
        if (next_item_size as f64) > pr {
            score += 8.0 * (pr / cap) * (1.0 + progress);
        } else {
            let waste = pr - (pr - next_item_size as f64);
            score -= 4.0 * (next_item_size as f64 / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (0.5 + 0.5 * progress);
    }

    // Mild penalty for spreading across many open bins late in stream.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * progress;

    // Prefer bins whose residual is below the mean (consolidating emptier space).
    score += 0.3 * (pr - mean_residual) * (1.0 - progress);

    // Penalize opening new bins, more so early in the stream.
    if bin_residual == bin_capacity {
        score += 25.0 * (1.2 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (residue 0) heavily rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward near-exact fits with modulo-style harmonic classes.
    let class = post_residual % 10;
    if class == 0 {
        score -= 25.0; // dead-space-free class
    } else if class <= 2 {
        score -= 12.0; // nearly-unusable sliver -> treat as full
    } else if class >= 8 {
        score += 10.0; // awkward leftover
    }

    // Integer-division thresholds on post_residual: unusable if smaller than
    // the smallest plausible item (harmonic bucket = pr / 20).
    let bucket = post_residual / 20;
    score -= bucket as f64 * 3.0; // larger usable buckets are better

    // Lookahead coupling: if next item fits into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        // Extra reward if next item exactly fills remaining space (harmonic 0).
        if post_residual - next_item_size == 0 {
            score -= 20.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize slightly so bins that chain better win.
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no
    // open bin offers a decent fit (item much larger than mean residual).
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / cap;
        let mean_fit = mean_residual / cap;
        if pressure > mean_fit + 0.15 {
            score -= 20.0; // open new bin when open bins are too full
        } else {
            score += 40.0; // prefer existing bins otherwise
        }
    }

    // Late-stream tightening: conserve capacity as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / cap) * 10.0;

    // Mild preference for spreading across many open bins early.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps much more strongly than large residuals.
    if post_residual < 10 {
        score += 60.0; // dead space below minimum item size
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= (bin_capacity as f64 / item_size as f64) * 2.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Pressure from many open bins: discourage spreading across bins.
    score += 0.8 * open_bins_count as f64;

    // Lookahead: if next item fits the post_residual, reward leaving that space.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }
    // Penalize if post_residual is a gap smaller than the next item (likely dead).
    if next_item_size > post_residual && post_residual < 10 {
        score += 20.0;
    }

    // Early in the stream, be more willing to open new bins (keep residuals large).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 4.0;

    // New-bin candidate: neutral-ish baseline, only chosen when open bins are bad.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64;
    }

    // Mean residual context: if this bin's residual is far below mean, it's already tight.
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 && bin_res_f < mean_residual {
        score += 0.3 * (mean_residual - bin_res_f);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_quality = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - match_quality / bin_capacity as f64);
        if match_quality == 0.0 {
            score -= 200.0; // exact 2-step chain: item + next item perfectly fills
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // dead space: next item cannot use leftover
        score += 30.0 + (next_item_size - post_residual) as f64;
    }

    // Penalize waste relative to mean residual
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Prefer filling already-open bins; discourage opening new bins when reasonable fit exists
    if bin_residual == bin_capacity {
        score += 80.0 + open_bins_count as f64;
    }

    // Late in stream: tighten packing, avoid fragmentation
    let progress = step_index as f64 / total_items as f64;
    score += progress * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness * tightness;

    // Penalize small dead space that is hard to reuse (below typical small item size).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to overshoot.
            score += 3.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; grows with number of open bins.
        score = bin_capacity as f64 + 2.0 * open_bins_count as f64;
        // Late in the stream, be more reluctant to open new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If the item is large relative to capacity, a fresh bin is more attractive.
        score -= 0.15 * item_size as f64;
        // If many bins fit the item, opening a new bin is unnecessary.
        if fitting_bins_count > 1 {
            score += 15.0;
        }
    } else {
        // Reward using bins whose residual deviates from the mean (consolidation).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
        // Mild bonus for using already-open bins as pressure builds.
        score -= 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post_residual (tight fit), with non-linear polynomial shaping.
    let mut score = 3.0 * pr + 40.0 * norm_pr * norm_pr;

    // Smooth coupling: tight fits are progressively more valuable later in the stream.
    score -= 25.0 * progress * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Penalize dead space relative to mean residual, amplified by progress.
    let dev = (pr - mean_residual) / cap;
    score += 20.0 * dev * dev * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward leaving room for the next item via smooth interaction.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            let norm_gap = gap / cap;
            score -= 15.0 * norm_gap * (1.0 - norm_gap) * (0.5 + 0.5 * progress);
        } else {
            score += 10.0 * (-gap / cap);
        }
    }

    // Mild penalty for opening a new bin when many bins are already open.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: items in [1,100] pair well with
    // residuals that are small or exactly re-fillable by common sizes.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: strongly reward.
        score -= 1000.0;
    } else if pr <= 10 {
        // Near-perfect fit, dead space is minimal.
        score -= 200.0;
    } else {
        // Penalize residuals that fall into "dead zones": too small for the
        // smallest plausible item (<= ~15) but not zero.
        if pr < 15 {
            score += 150.0;
        }
        // Modulo-classes: residuals divisible by common item granularities
        // (10, 20, 25, 50) are more likely to be exactly filled later.
        if pr % 10 == 0 { score -= 60.0; }
        if pr % 20 == 0 { score -= 30.0; }
        if pr % 25 == 0 { score -= 25.0; }
        if pr % 50 == 0 { score -= 40.0; }
    }

    // Lookahead coupling: reward residuals that can exactly host the next item.
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 300.0;
        } else if pr >= next_item_size {
            // Residual can host next item: mild reward, stronger if slack is small.
            score -= 40.0 + (pr - next_item_size) as f64 * 0.3;
        } else {
            // Residual cannot host the next item: penalize proportionally.
            score += (next_item_size - pr) as f64 * 0.8;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling: empty bins are only attractive when current
    // bins would leave large unusable residuals.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 180.0;
        // If the current item is large relative to capacity, opening fresh
        // space is less wasteful.
        if item_size >= bin_capacity / 2 {
            score -= 90.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 60.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor with
    // harmonic correction).
    let tightness = mean_residual - bin_residual as f64;
    score += tightness * 0.5;

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 3.0;

    // New-bin candidate: must not be chosen unless existing fits are bad.
    if bin_residual == bin_capacity {
        score += 25.0 + pressure * 5.0;
        // If the next item could use this fresh bin well, soften slightly.
        if next_item_size > 0 && next_item_size as f64 >= mean_residual {
            score -= 10.0;
        }
    }

    // Lookahead: if the residual left behind can host the next item, reward it.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    // Prefer bins tighter than the mean residual (compact packing).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how snugly
            let slack_after_next = post_residual - next_item_size;
            score -= 150.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize large dead space
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize post_residual that is too small to ever be useful (below min item size 1..100)
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New empty bin candidate: penalize unless current bin fits poorly
    if bin_residual == bin_capacity {
        score += 60.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0; // fresh bin good for upcoming large item
        }
    }

    // Late in stream: consolidate, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 100.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 20.0;

    // Penalize dead space that no plausible item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable sliver
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits perfectly in the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            score -= 6.0;
        } else {
            score += 5.0; // next item cannot use this leftover space
        }
    }

    // Prefer filling bins with larger residuals when mean residual is high (fragmentation risk).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if (bin_residual as f64) > mean_residual {
        score -= 4.0 * (1.0 - progress);
    } else {
        score += 2.0 * progress;
    }

    // When many bins are open, prefer compacting into existing ones.
    score -= (open_bins_count as f64).ln().max(0.0) * 1.5;

    // New-bin candidate: penalize mildly so it's chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if current bin fit is terrible and next item is large, allow opening.
        if post_residual < item_size as f64 * 0.15 && next_item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let pre = bin_residual as f64;
    let fit_frac = item_size as f64 / cap;

    // Base: quadratic-ish preference for low post residual (dense packing).
    let mut score = post * (1.0 + 0.8 * post / cap);

    // Smooth non-linear coupling: post_residual weighted by stream progress.
    score += 4.0 * post * (progress - 0.5) * (progress - 0.5) * (progress - 0.5);

    // Reward high fill ratio (item large relative to residual) with cubic term.
    let fill = 1.0 - post / cap;
    score -= 12.0 * fill * fill * fill;

    // Dead-space penalty: residuals too small for typical items (smooth sigmoid-like).
    let dead = ((cap * 0.35 - post) / cap).max(0.0);
    score += 25.0 * dead * dead;

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0 + 10.0 * fit_frac;
    } else {
        // Mild penalty for spreading across many open bins.
        score += 0.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: if next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            score -= 8.0 * (1.0 - nx / post.max(1.0));
        } else {
            // Next item won't fit here: penalize leaving awkward residual.
            score += 5.0 * (1.0 - post / cap);
        }
    }

    // Mean-residual coupling: prefer bins deviating favorably from mean.
    score += 0.3 * (mean_residual - pre);

    // New-bin candidate handling: empty bin gets baseline score; penalize opening
    // a new bin when good fits exist, but allow it when remaining fits are tight.
    let is_new = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new {
        // Baseline comparable to a mediocre fit; slightly worse than tight fits.
        score = cap * 0.45 + 10.0 * fit_frac;
        if fitting_bins_count <= 1 {
            // No real alternative: opening a new bin is fine.
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: capacity / post_residual ratio.
    // Residuals that are "useful" harmonic fractions of capacity (e.g. 50, 33, 25, 20)
    // are more likely to host future items; reward them.
    if post_residual > 0 {
        let frac = bin_capacity as f64 / post_residual as f64;
        let near_integer = (frac - frac.round()).abs();
        score -= 8.0 * (1.0 - near_integer); // exact divisors get full reward
    } else {
        // Perfect fill: best possible outcome.
        score -= 60.0;
    }

    // Penalize tiny dead space (< 10, minimum item size): unusable waste.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mildly penalize leaving medium residuals
            // that nobody will use, favor compacting now.
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Prefer tighter bins when many bins are open (reduce fragmentation).
    score -= 3.0 * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive if no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 30.0 };
        score += pressure + open_bins_count as f64 * 0.5;
        // If the item is large relative to mean residual, opening fresh is fine.
        score -= 20.0 * (item_size as f64 / mean_residual.max(1.0)).min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for any plausible
    // future item (sizes >= 1, but realistically >= 10 in classic streams)
    // are pure waste. Penalize unusable gaps hard.
    let dead_threshold = 9u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual) as f64;
    }
    // Perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight fits (small positive post_residual) are mildly preferred.
    score -= 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Open-bins pressure: discourage spreading into many bins when pressure high.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward;
    // if it would be blocked by a small gap, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap < dead_threshold {
                score -= 12.0; // chains nicely into a near-perfect follow-up
            } else {
                score -= 4.0;
            }
        } else if post_residual > 0 {
            score += 5.0; // next item cannot use this gap
        }
    }

    // Mean residual coupling: prefer bins deviating below the mean residual
    // (filling the emptiest-but-fitting bins keeps compact bins intact).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Give it a mild baseline penalty that grows
    // with stream progression (early on, opening bins is cheaper).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 15.0 * progress;
        // But if it's a large item and no other bin fits well, allow opening.
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
