    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Prefer filling already-open bins over opening new ones; scale with crowding.
    score += (open_bins_count as f64) * 2.0;

    // Early in stream: be conservative, keep residuals large for future items.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * post_residual as f64 * 0.3;

    // New-bin candidate: penalize slightly so it only wins when open bins are bad fits.
    if bin_residual == bin_capacity {
        score += 300.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that becomes unusable: post_residual below smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item can fit into the post residual,
    // reward; otherwise penalize creating residual that blocks next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if next_item_size > bin_capacity {
            // next item bigger than capacity; ignore
        } else {
            score += 5.0;
        }
    }

    // Time horizon: later in the stream, consolidate more (favor filling open bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * tightness;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins -> favor filling existing bins; few bins -> new bins are cheap.
    let open_f = open_bins_count as f64;
    score += 0.4 * open_f * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin's residual deviates from mean residual,
    // mildly prefer bins whose residual is near the mean (keeps bin profile uniform).
    let bin_res_f = bin_residual as f64;
    let dev = (bin_res_f - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer bins with larger residual when item is large (big items need room),
    // prefer smaller residual when item is small (fill gaps first).
    let item_f = item_size as f64;
    if item_f > 50.0 {
        score -= 0.1 * bin_res_f;
    } else {
        score += 0.05 * bin_res_f;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor
    // or no open bins fit well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let poor_fit = (post_residual as f64 / bin_capacity as f64) > 0.5;
        if poor_fit {
            score -= 15.0;
        } else {
            score += 20.0;
        }
        // Early stream: new bins are cheap; late stream: discourage opening new bins.
        score += 20.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_frac = post / cap;
    let item_frac = item_size as f64 / cap;

    // Base: prefer tight fits (small post_residual), with non-linear emphasis.
    let mut score = post + 20.0 * post_frac * post_frac * cap;

    // Smooth coupling with stream progress: early on, tolerate slack (keep bins
    // flexible); later, punish residual waste more aggressively.
    let progress_penalty = 30.0 * progress * post_frac * (1.0 - post_frac + 0.25);
    score += progress_penalty;

    // Reward filling bins that leave little dead space, quadratically.
    let fill = item_frac;
    score -= 15.0 * fill * fill * cap * 0.1;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when many bins are open and mean residual is high.
    let new_bin = (bin_residual == bin_capacity) as i32;
    if new_bin == 1 {
        let mean_frac = mean_residual / cap;
        let congestion = (open_bins_count as f64).sqrt();
        score += 8.0 + 10.0 * mean_frac * congestion + 20.0 * progress;
    }

    // Lookahead: if next item fits the post-residual, reward this placement smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            score -= 12.0 * (1.0 - slack * slack);
        } else {
            let miss = (nxt - post) / cap;
            score += 10.0 * miss * miss * cap * 0.1;
        }
    }

    // Non-linear interaction: squared deviation of post_residual from mean residual,
    // encouraging consolidation toward the average slack level.
    let dev = post - mean_residual;
    score += 0.05 * dev * dev / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: small post_residual classes are
    // valuable dead-space sinks; reward them nonlinearly.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class boundaries via integer-division thresholds on post_residual.
    let class = post_residual / 10; // 0..10 harmonic classes
    match class {
        0 => score -= 45.0,        // near-perfect fit
        1 => score -= 30.0,        // excellent fit
        2 => score -= 18.0,        // good fit
        3 => score -= 10.0,        // decent fit
        4 => score -= 5.0,         // moderate
        5 => score -= 2.0,         // half-empty bin
        6 => score += 2.0,         // wasteful
        7 => score += 5.0,
        8 => score += 9.0,
        _ => score += 14.0,        // mostly empty placement
    }

    // Exact-fill bonus: modulo arithmetic — residual divisible cleanly.
    if post_residual == 0 {
        score -= 60.0;
    } else if bin_residual % 25 == 0 && post_residual < 25 {
        score -= 8.0;
    }

    // Lookahead coupling: reward if next item fits the post residual exactly
    // or tightly (harmonic chaining).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
        } else {
            // Next item cannot use this bin's leftover; penalize proportionally
            score += 6.0 * (next / cap);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // fits are all poor (high post_residual everywhere).
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap; // average emptiness of open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base penalty keeps new bins closed; relax late in the stream or
        // when open bins are already crowded with large residuals.
        let mut new_bin_penalty = 55.0 - 25.0 * pressure - 10.0 * progress;
        if next_item_size > 0 && next_item_size as u32 > post_residual.max(0) && pressure > 0.6 {
            new_bin_penalty -= 20.0; // item + big next item pair well in fresh bin
        }
        if open_bins_count == 0 {
            new_bin_penalty = -100.0; // must open
        }
        score += new_bin_penalty.max(-100.0);
    }

    // Mild preference for tighter (smaller-residual) bins among equals,
    // scaled by stream progress (best-fit bias strengthens over time).
    score += 0.05 * (post / cap) * (1.0 + step_index as f64 / (total_items.max(1) as f64));

    // Deter fragmentation: penalize leaving residuals that no typical item
    // (1..100) can use well — residuals in awkward bands.
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0; // tiny dead space is fine (bin nearly full)
    } else if post_residual >= 60 && bin_residual != bin_capacity {
        score += 10.0; // large awkward leftover in a partially used bin
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize small unusable gaps (dead space below minimum item size 1..100 range).
    // A post_residual that is tiny (e.g. 1..=10) is nearly worthless.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 20.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // If the next item fits exactly in the post residual, heavily reward this placement (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 + 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post residual can't host next item: penalize proportionally to how much it wastes.
        score += (next_item_size as f64 - post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: with many open bins, discourage new-bin usage.
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: penalize proportional to open bins count and stream progress.
        score += 10.0 + open_bins_count as f64 * 5.0 + (step_index as f64 / total_items.max(1) as f64) * 20.0;
        // But if mean residual across open bins is small (all bins are nearly full),
        // opening a new bin is reasonable: reduce the penalty.
        score -= (mean_residual * 0.4).min(30.0);
    }

    // Mild preference for bins with residual close to mean (balanced usage).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, penalize dead space nonlinearly.
    let wasted = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * wasted * wasted;

    // Perfect 2-step chain: post_residual exactly equals next item size -> huge reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / bin_capacity as f64).max(0.0).powi(6);
        // Also reward near-perfect chains (post_residual can host next item snugly).
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64).max(0.0).powi(3);
        } else {
            // Next item cannot fit here; penalize slightly if we leave large residue.
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Compare bin residual against mean residual: prefer filling below-average-residual bins.
    score += 8.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: make it unattractive unless the current item is huge relative
    // to capacity or no good fit exists (post_residual would be large in any bin anyway).
    if bin_residual == bin_capacity {
        // New bin baseline: neutral-ish, penalized so it's chosen only when fits are terrible.
        score += 25.0;
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 30.0; // fresh bin chains perfectly with next item
        }
        if item_size >= 70 {
            score -= 20.0; // big items better in fresh space
        }
        // Early in stream, opening bins is cheap; later, conserve.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-perfect fills (small post_residual gets extra bonus).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Dead-space penalty: residuals too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty for stranding space
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Time horizon: early in stream, be conservative (prefer good fits, avoid
    // wasting bins); late in stream, prefer closing out bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * tight;

    // Crowding: many open bins -> prefer filling existing ones over new bins.
    if open_bins_count > 0 {
        score += (open_bins_count as f64).ln() * 2.0;
    }

    // New-bin candidate handling: empty bin should only win when it's genuinely
    // better (e.g., item is large and would leave open bins fragmented).
    if bin_residual == bin_capacity {
        score += 8.0;
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's
    // already fragmented; using it consolidates waste.
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64 / bin_capacity as f64;
    let fit = item_size as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling: waste term quadratic in post_residual,
    // modulated by stream progress and item size.
    let waste = pr * pr * (0.5 + progress);
    score += 40.0 * waste * (0.5 + fit);

    // Reward tight fits with a smooth saturating term.
    score -= 15.0 * (1.0 - pr) * (1.0 - pr) * fit;

    // Last-chance bonus: strongly prefer the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress + 0.5);
    }

    // Lookahead: penalize if next item cannot use the post-residual space.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > post_residual as f64 {
            score += 8.0 * (nx - post_residual as f64) / bin_capacity as f64;
        } else {
            score -= 6.0 * (nx / bin_capacity as f64) * (1.0 - pr);
        }
    }

    // Mild penalty when bin residual deviates from mean residual (balance bins).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate: penalize opening a bin unless current item is large
    // relative to capacity or many bins already open.
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * fit - 5.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

