        1 => score -= 12.0,          // excellent
        2 | 3 => score -= 4.0,       // good: leaves room for small items
        4 | 5 | 6 => score += 2.0,   // mid zone: awkward dead space
        _ => score += 6.0,           // large residual: wasteful placement
    }

    // Modulo arithmetic on post_residual: residuals matching common small item
    // sizes (mod 10) are reusable; odd/misaligned residuals are penalized.
    let m = post_residual % 10;
    if m == 0 {
        score -= 8.0;
    } else if m >= 5 {
        score += m as f64 * 0.4;
    } else {
        score += m as f64 * 0.2;
    }

    // Lookahead coupling: does the next item fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect harmonic division is best
            if post_residual % next_item_size == 0 {
                score -= 15.0;
            } else {
                score -= (post_residual - next_item_size).min(20) as f64 * 0.3;
            }
        } else {
            // next item cannot follow into this bin: slight penalty
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Progression-aware tightening: late in the stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.25;

    // Discourage opening new bins when many bins are open and this one fits well
    if bin_residual != bin_capacity {
        score -= 3.0 + 0.5 * open_bins_count.min(20) as f64;
    } else {
        // New-bin candidate: penalize unless residual logic says it's a bad fit
        score += 20.0;
        if post_residual < 20 {
            score += 10.0; // opening a bin for a huge item relative to capacity
        }
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is already tightly packed -> prefer filling it further
    let diff = mean_residual - bin_residual as f64;
    score -= diff * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
