        }
        // Bonus for post residual close to next item size (good chaining).
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score -= 6.0 * (-gap / 20.0).exp();
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late in the stream, consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate.
        let mut new_bin_score = 30.0;
        new_bin_score -= 20.0 * (1.0 - progress); // cheaper early on
        // Penalize new bins when many bins are open but residuals are fragmented.
        new_bin_score += (open_bins_count as f64).ln().max(0.0) * 3.0;
        // If existing bins fit poorly (high mean residual but item barely fits),
        // opening a new bin is attractive.
        let waste = (bin_residual - item_size) as f64;
        if waste > mean_residual {
            new_bin_score -= 5.0;
        }
        // If next item is large, a fresh bin keeps room for it.
        if next_item_size > 0 && next_item_size >= 60 {
            new_bin_score -= 10.0;
        }
        return new_bin_score;
    }

    // Prefer bins with residual below mean (consolidate fragmentation).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev;

    // Slight preference for using fewer bins overall as stream progresses.
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with quadratic shaping
    let mut score = norm_pr * norm_pr * cap * 0.5 + pr;

    // Non-linear coupling: post_residual penalty grows with stream progress
    let progress_coupling = norm_pr * norm_pr * (1.0 + 3.0 * progress);
    score += progress_coupling * cap;

    // Dead-space term: residuals too small for typical future items are wasteful
    let dead = if pr > 0.0 && pr < 10.0 { (10.0 - pr) * (10.0 - pr) } else { 0.0 };
    score += dead * (0.5 + progress);

    // Lookahead synergy: reward if next item fits into post_residual
    if next_item_size > 0 {
        let next_fits = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        score -= next_fits / cap * (2.0 + 2.0 * progress);
        let next_exact = (post_residual as i64 - next_item_size as i64 == 0) as f64;
        score -= next_exact * 5.0;
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 6.0 * progress;
    }

    // Mild penalty when bin is far below mean residual (avoid unbalanced bins)
    score += ((mean_residual - pr) / cap).abs() * (1.0 + progress);

    // Slight preference for filling existing bins over opening new ones early
    let is_new_bin = (bin_residual as f64 == cap) as f64;
    score += is_new_bin * (3.0 - 2.0 * progress) + is_new_bin * fit_ratio * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "usable" bands.
    let pr = post_residual as u32;
    let usable_band = match pr {
        0 => 6.0,               // perfect fit
        1..=10 => 4.0,          // near-perfect
        11..=20 => 2.0,         // small dead space, still fillable
        21..=40 => 0.0,         // mediocre
        41..=60 => -2.0,        // risky dead space
        _ => -4.0,              // large residual left = wasteful placement
    };
    score -= usable_band;

    // Modulo-class bonus: residuals divisible into common item chunks (10s) are reusable.
    if pr % 10 == 0 && pr > 0 {
        score -= 3.0;
    }
    if pr % 5 == 0 && pr > 0 {
        score -= 1.0;
    }

    // Lookahead: if next item fits in the post residual, reward strongly.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 8.0;
            // harmonic bonus if next item exactly fills post residual
            if post_residual as u32 == next_item_size {
                score -= 6.0;
            }
        } else {
            // dead space the next item cannot use
            score += (post_residual as f64 - next_item_size as f64).max(0.0) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 15.0;
        // but if the item is large relative to capacity, a fresh bin is fine
        if item_size as f64 > 0.7 * cap {
            score -= 10.0;
        }
    }

    // Prefer filling fuller bins (relative fill fraction, harmonic weighting).
    let fill_frac = (bin_capacity - bin_residual) as f64 / cap;
    score -= 6.0 * fill_frac * fill_frac;

    // Mean residual coupling: when mean residual is high, spreading waste is bad.
    score += 0.15 * (mean_residual - post_residual as f64).max(0.0);

    // Late in stream: be greedy, minimize post residual harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A residual below the smallest possible item (1) is impossible, but
    // residuals that no plausible item (10..80 legacy / small items) can use
    // are dead space. Penalize residuals in the "awkward" low band.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 6.0; // tiny unusable slivers are worst
    } else if pr >= 10.0 && pr < 20.0 {
        score += (20.0 - pr) * 1.5; // only very small items fit
    }

    // Reward tight fits (low post residual relative to item size).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 8.0;

    // Open-bin pressure: with many bins open, prefer consolidation
    // (fill existing bins) rather than spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item can exactly use the post residual,
    // reward this placement strongly (perfect pairing).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (ni - pr).abs() < 0.5 && pr > 0.0 {
            score -= 25.0;
        } else if ni <= pr && pr - ni < 10.0 {
            score -= 8.0; // next item fits leaving near-zero waste
        } else if ni > pr && ni <= bin_residual as f64 {
            // next item would NOT fit here after placement; slight penalty
            score += 3.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (tighter bins) when the item fits well there.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    // New-bin candidate: opening a new bin wastes capacity. Only attractive
    // when open-bin fits are poor (large post residual) or few bins fit.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin, modulated by how bad existing options are.
        // If this is the only fitting option, opening a new bin is unavoidable
        // but still gets a neutral score so real fits win.
        let fresh_cost = 30.0 + cap * 0.25;
        if fitting_bins_count == 0 {
            score = fresh_cost - 20.0; // must open a bin
        } else {
            score = fresh_cost;
        }
        // If the item perfectly fills a fresh bin later with next item, allow it.
        if next_item_size > 0 && (bin_capacity as u32).saturating_sub(item_size) == next_item_size {
            score -= 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit
    score += (post_residual as f64) * 0.5;

    // Aggressive 2-step lookahead: reward exact match of next item into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect 2-step chain
        } else if post_residual > next_item_size {
            let leftover = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - leftover / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize large dead space
            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap;
        }
    } else {
        // last item: strongly prefer minimal residual
        score += 0.3 * post_residual as f64;
    }

    // Relative to mean residual: prefer bins already below-average residual (dense bins)
    score += 0.4 * ((bin_residual as f64) - mean_residual);

    // Last-chance bin: if this is the only fitting bin, heavily reward using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless no good fit exists
    if bin_residual == bin_capacity {
        score += 60.0;
        // allow new bin if few bins fit the item (avoid fragmenting)
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if fitting_bins_count == 1 {
            score -= 55.0; // last chance: new bin competes closely
        }
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Slight preference to fill bins when many are open (consolidation)
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to ever be useful again
    // (smallest possible item is 1). Dead space below ~10 is nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (10.0 - post_residual as f64);
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // Extra reward if post_residual is a snug fit for the next item.
            let slack = post_residual - next_item_size;
            if slack <= 5 {
                score -= 4.0;
            }
        } else {
            // Post-residual kills the next item's chance in this bin.
            score += 3.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
        if post_residual < 10 {
            score -= 10.0; // near-perfect fill on last chance
        }
    }

    // New-bin candidate handling: opening a new bin should only win when
    // existing bins fit poorly. Give the empty bin a moderate default score
    // so good fits in open bins beat it, but bad fits don't.
    if bin_residual == bin_capacity {
        // Neutral baseline: slightly above typical decent-fit scores.
        score = 55.0;
        // Early in the stream, opening bins is cheap and useful for diversity.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // If many bins are open with lots of residual space, discourage new bins.
        score += 0.4 * open_bins_count as f64;
        score += 0.15 * mean_residual;
        // If next item is large, having a fresh bin is valuable.
        if next_item_size >= 50 {
            score -= 5.0;
        }
        // Last chance: never open a new bin when this is the only fitting bin.
        if fitting_bins_count == 1 {
            score += 40.0;
        }
    }

    // Prefer bins with below-average residual (consolidate space).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Mild preference to fill older/dense state as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 60.0 * poly * (1.0 + progress);

    // Penalize large wasted residual later in the stream (quadratic growth)
    score += 0.5 * norm_pr * norm_pr * (0.5 + progress) * cap;

    // Reward tight fits: small post residual relative to item size
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio * fit_ratio * (1.0 - progress);

    // Last-chance bonus: only fitting bin, avoid opening new bin early
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - progress);
    }

    // Lookahead: reward residual that can fit the next item smoothly
    if next_item_size > 0 {
        let fits_next = (pr >= next_item_size as f64) as i32 as f64;
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= 20.0 * fits_next * (1.0 - gap * gap);
    }

    // Discourage spreading across many bins when mean residual is low
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap).powi(2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in low thirds is worse.
    let third = bin_capacity / 3;
    if post_residual < third {
        score += (third - post_residual) as f64 * 0.6; // tiny unusable slivers penalized
    } else if post_residual < 2 * third {
        score -= 2.0; // mid-class residual is reusable
    } else {
        score -= 5.0; // large residual remains flexible
    }

    // Modulo-10 harmonic class: residuals divisible by 10 align with typical item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // guaranteed dead space
    }

    // Lookahead coupling: can next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0; // perfect pairing
        } else if next_item_size <= post_residual {
            score -= 4.0;
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 { score -= 2.0; }
        } else {
            // next item won't fit here: residual becomes dead unless another bin takes next
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: fresh bin should only win when fit is poor.
    if bin_residual == bin_capacity {
        score += 6.0 + 0.25 * (open_bins_count as f64);
        if post_residual > 20 { score -= 8.0; } // big item into fresh bin is fine
    }

    // Stream progression: late in stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64 / cap) * 4.0;

    // Prefer bins tighter than average (best-fit flavor with mean coupling).
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are worse than large leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    }

    // Pressure from number of open bins: discourage spreading across many bins.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize leaving a gap just under the next item size (near-miss dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // New-bin candidate: baseline competitive score, slightly penalized by stream progress.
    if bin_residual == bin_capacity {
        score = 55.0 + (step_index as f64 / total_items.max(1) as f64) * 20.0;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it is tighter; prefer it.
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // Next item fits exactly into the leftover space
            score -= 120.0 * (1.0 - diff / bin_capacity as f64);
            if diff < 1.0 {
                score -= 200.0;
            }
        } else {
            // Dead space penalty scaled by gap to next item
            score += 0.5 * diff;
        }
    }

    // Penalize bins far below mean residual (fragmented space) unless last chance
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.3 * (mean_residual - res).abs();
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when current fit is terrible
    if bin_residual == bin_capacity {
        score += 40.0 + 0.5 * item_size as f64;
        if fitting_bins_count == 1 {
            score -= 60.0;
        }
    }

    // Late-stream tightening: prefer tighter fits as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 30.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 60.0;

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 100.0;
    } else if post_residual < 20 {
        score -= 40.0;
    }

    // Penalize dead space that no future item can plausibly use.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers are waste
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, bonus.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Next item won't fit here; penalize more as post_residual grows (wasted space).
            score += post_residual as f64 * 0.3;
            if next_item_size > post_residual && post_residual < 10 {
                score += 20.0;
            }
        }
        // Ideal: post_residual exactly matches next item size.
        if post_residual == next_item_size {
            score -= 70.0;
        }
    }

    // Compare against global state: prefer bins whose residual is below mean
    // (filling the emptiest bins first keeps tight bins for tight items).
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 8.0;
    }

    // Time horizon: early in stream, prefer keeping residuals flexible (mid-sized);
    // late in stream, just fill bins tightly.
    if t < 0.5 {
        // favor moderate residuals early
        let mid = 50.0f64;
        score += ((post_residual as f64 - mid).abs() / mid) * 15.0;
    } else {
        score -= (1.0 - t) * 10.0;
    }

    // Many open bins: discourage spreading into fresh-ish bins; prefer dense packing.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate handling: empty bin gets a baseline penalty so it is only
    // chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 120.0;
        // If current item is large, opening a fresh bin is more acceptable.
        if item_size > bin_capacity / 2 {
            score -= 40.0;
        }
        // If no existing bin fits, new bin is the only choice anyway.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post residual, with non-linear (quadratic/cubic) shaping
    let mut score = pr + 40.0 * pr_norm * pr_norm + 25.0 * pr_norm.powi(3);

    // Stream-progress coupling: later in the stream, punish wasted space more aggressively
    score += 30.0 * progress * pr_norm * (1.0 - pr_norm);

    // Reward tight fits smoothly: small post_residual relative to item size
    let item = item_size as f64;
    score -= 20.0 * (item / cap) * (1.0 - pr_norm).powi(2);

    // Penalize bins far below mean residual (fragmentation), smooth coupling with progress
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 15.0 * dev * dev - 10.0 * dev * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 50.0 + 30.0 * progress;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (next_item_size as f64 / cap) * (1.0 - progress);
    } else if next_item_size > 0 {
        // smooth penalty when next item can't use the leftover space
        score += 8.0 * ((next_item_size as f64 - pr) / cap).min(1.0) * (0.5 + 0.5 * progress);
    }

    // Mild pressure against proliferating bins when many are open
    score += 0.5 * open_bins_count as f64 * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: waste buckets via integer division.
    let class = post_residual / 10; // residual class 0..=9
    // Penalize dead space superlinearly within each class.
    score += (class as f64) * (class as f64) * 1.7;

    // Tiny residuals are dead space: heavy penalty unless exactly zero.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    }

    // Harmonic fraction of bin filled: reward filling near capacity fractions.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    let harmonic = 1.0 / (1.0 + (fill * 10.0).floor());
    score -= 12.0 * (1.0 - harmonic);

    // Lookahead coupling: does next item fit into post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chain reward scaled by how snugly next item fits
            let snug = (post_residual - next_item_size) as f64;
            score -= 18.0 - 0.25 * snug;
        } else {
            // next item won't fit: penalize by leftover gap size
            score += 6.0 + 0.15 * ((next_item_size - post_residual) as f64);
        }
    } else {
        // last item: prefer closing bins perfectly
        score += 3.0 * (post_residual as f64);
    }

    // Last-chance bin: strong reward to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // base penalty so we prefer existing bins with good fits
        score += 55.0;
        // more attractive late in stream or when many bins are already open and fragmented
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
        if open_bins_count > 0 && mean_residual < item_size as f64 {
            score -= 35.0; // existing bins are tight; new bin is good
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // fresh bin can host the next item too
        }
    }

    // Modulo-structure on item size: items in "hard" classes (leave awkward gaps)
    let hard_class = item_size % 10 == 1 || item_size % 10 == 9;
    if hard_class && post_residual > 0 {
        score += 4.0;
    }

    // Mild pressure against bin proliferation when many bins are open.
    if bin_residual != bin_capacity {
        score += 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

