    // Penalize dead space that likely becomes unusable for future items
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score -= 20.0; // small dead space is fine
    } else if post_residual >= 10 && post_residual <= 80 {
        // residual in the item-size range is reusable -> reward
        score -= 15.0 * (1.0 - progress);
    } else {
        score += 10.0; // large residual but item was big; keep neutral-positive
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 25.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // wasted residual relative to next item
            let waste = post_residual as f64 - if post_residual >= next_item_size { next_item_size as f64 } else { 0.0 };
            score += 8.0 * (waste / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(10.0);
    }

    // Global state: when many bins are open, prefer consolidating into existing ones
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins with residual far from the mean (fill outliers) mildly
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.05 * dev;

    // New-bin candidate handling: opening a new bin is only attractive early
    // or when this bin would be a very poor fit otherwise.
    if bin_residual == bin_capacity {
        let early = 1.0 - progress;
        // penalize new bins late in the stream or when good alternatives exist
        let penalty = 55.0 * (1.0 - early) + 20.0 * (fitting_bins_count as f64).min(5.0);
        score += penalty;
        // but if next item is huge and won't fit anywhere typical, fresh bin ok
        if next_item_size >= 70 {
            score -= 30.0 * early;
        }
        // empty bin has full residual: baseline should reflect that potential
        score -= 10.0 * early;
    }

    // Small time-horizon modulation: late in stream, be greedy about tight fits
    score -= 10.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
