    // early on, waste is cheap; late, dead space is heavily punished.
    let waste_penalty = pr / cap;
    score += 40.0 * waste_penalty * waste_penalty * (0.5 + progress);

    // Penalize bins whose leftover cannot fit the next item (smooth logistic-ish gate)
    if next > 0.0 {
        let fits_next = (pr - next).max(0.0) / cap;
        let unusable = 1.0 - (fits_next * 8.0).min(1.0);
