    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - waste_penalty);
    } else {
        // mild spread reward when many bins compete
        score -= 3.0 / fit;
    }

    // Bias toward bins below mean residual (consolidating space)
    score += (mean_residual - pr) * 0.1;

    // New-bin candidate: empty bin has large post_residual; add explicit smooth surcharge
    // that decays with progress, so early stream may open bins, late stream avoids it.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
