        if pr % 10 == 0 { score -= 12.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 6.0; }
        if pr % 50 == 0 { score -= 8.0; }
        // integer division thresholds
        let half = bin_capacity / 2;
        if pr <= half / 2 { score -= 10.0; } // very tight bin, good packing
    }

    // Lookahead coupling: next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 400.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            score -= 30.0 - (slack as f64).min(30.0) * 0.5;
            if slack < 10 { score -= 40.0; }
        } else {
            // next item won't fit here: slight penalty for wasting the slot
            score += 15.0;
        }
        // harmonic class match: next item shares modulo class with post_residual
        if next_item_size > 0 && pr % 10 == 0 && next_item_size % 10 == 0 {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bin is a poor fit
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 150.0;
        // but if this bin is the only fitting option, new bin is attractive
        if fitting_bins_count == 1 {
