        // large items prefer fresh bins
        if item_size > bin_capacity * 3 / 4 {
            score -= 60.0;
        }
        // late in stream, avoid bin proliferation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Prefer fuller bins relative to mean residual
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f) * 0.5;
    } else {
        score += (res_f - mean_residual) * 0.3;
    }

    // many open bins: encourage consolidation
    if open_bins_count > 4 {
        score += 0.5 * open_bins_count as f64 * (1.0 - res_f / cap);
    }

    score
}

