        // If many bins already fit the item, opening a new one is clearly worse.
        if fitting_bins_count > 1 {
            score += 25.0;
        }
        // Large item nearly filling a fresh bin alone is a decent new-bin reason.
        if item_size * 5 >= bin_capacity * 4 {
            score -= 15.0;
        }
    }

    // Tight-fit bonus: item consumes most of the bin's current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 {
        score -= 18.0 * (fill_ratio - 0.8) * 5.0;
    }

    // Mild preference for bins below mean residual (balance the pool).
    score += 0.05 * (mean_residual - post_residual as f64).max(0.0);

    // Slight pressure against accumulating too many open bins.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward filling bins tightly relative to capacity.
    score -= 30.0 * (item_size as f64 / bin_capacity as f64);

    // Open bins pressure: prefer consolidating into fewer bins.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    }
    // Penalize leaving a gap that the next item just barely misses.
    if next_item_size > 0 && (post_residual as u32) > 0 && (post_residual as u32) < next_item_size {
        score += 15.0;
    }

    // New-bin candidate: only attractive when open bins are congested.
    if bin_residual == bin_capacity {
        let congestion = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score = 70.0 + congestion - (fitting_bins_count as f64) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 50.0;
    }

    // 2-step lookahead: reward when next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 100.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit after this placement: penalize proportionally.
            score += 30.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer minimal residual.
        score += 0.0;
    }

    // Compare residual against mean residual: prefer using bins with more slack than average.
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening new bins early in the stream.
    if bin_residual == bin_capacity {
        score += 80.0 + 20.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        // But a new bin is fine if the item fits poorly everywhere else.
        if post_residual == 0 {
            score -= 900.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less leftover relative to capacity is better.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 18.0 * tightness * tightness;

    // Penalize small dead space that no future item can plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward strongly.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 10.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Next item won't fit here; mild penalty scaled by wasted potential.
        score += 0.05 * (next_item_size as f64 - post_residual as f64).min(60.0);
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 14.0;
    }

    // Time horizon: early in the stream, prefer consolidating into open bins;
    // late in the stream, packing tightly matters more than bin count.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0;
    score += progress * 0.05 * post_residual as f64;

    // Global residual pressure: if mean residual across open bins is high,
    // favor filling existing bins rather than opening new ones.
    score -= 0.08 * mean_residual;

    // Many open bins -> discourage opening yet another.
    if bin_residual == bin_capacity {
        score += 4.0 + 0.6 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit = item_size as f64;
    let progress = (step_index as f64) / (total_items as f64).max(1.0);

    // Base: minimize post residual, with non-linear shaping
    let mut score = post * (1.0 + 0.8 * post / cap);

    // Reward tight fits (small post_residual) more aggressively
    let tightness = 1.0 - post / cap;
    score -= 30.0 * tightness * tightness;

    // Stream progress coupling: later in stream, penalize large dead space more
    score += 20.0 * progress * (post / cap) * (post / cap);

    // Penalize opening a new bin when open bins could fit, unless fit is poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_ratio = fit / cap;
        // New bin attractive only if this item would leave awkward residue elsewhere
        score += 15.0 + 40.0 * fit_ratio * fit_ratio;
        score -= 25.0 * (1.0 - fit_ratio);
    } else if fitting_bins_count == 1 {
        // Last chance bin: strongly favor using it
        score -= 25.0;
    }

    // Dead-space penalty relative to mean residual of open bins
    score += 5.0 * (post - mean_residual).abs() / cap;

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 12.0 * (next_item_size as f64) / cap;
    } else if next_item_size > 0 {
        score += 6.0 * (1.0 - post / cap);
    }

    // Mild penalty for proliferating bins
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo capacity fractions
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;
    let cls = post_residual % (bin_capacity / 4).max(1); // quarter-capacity class

    // Reward exact-fit harmonics: post_residual in {0, 25, 50, 75} are "clean" states
    match cls {
        0 => score -= 30.0,
        _ => {}
    }

    // Penalize dead space just above small thresholds (unusable slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Coupling with lookahead: if next item fits the post residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0 + 0.3 * (next_item_size as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * (next_item_size as f64 - post);
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral baseline, prefer opening only when
    // current bin would leave large awkward residue relative to mean
    if bin_residual == bin_capacity {
        score = 0.5 * cap_f - 0.5 * mean_residual;
        if post_residual == bin_capacity {
            // empty-bin call for the new-bin candidate itself
            score = 0.25 * cap_f;
        }
    }

    // Mild pressure to consolidate as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post / cap_f);

    // Prefer bins whose residual is below mean (tighter bins first)
    score += 0.15 * (post - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: a leftover gap that cannot fit the next item
    // (or is suspiciously tiny) is wasted capacity. Penalize proportionally.
    if post_residual > 0 {
        let dead_threshold = if next_item_size > 0 { next_item_size } else { item_size / 2 };
        if (post_residual as u64) < (dead_threshold as u64) {
            let dead = (dead_threshold - post_residual) as f64;
            score += 2.0 * dead + 5.0;
        }
        // Very small gaps (< ~5% of capacity) are almost certainly dead space.
        if post_residual < bin_capacity / 20 {
            score += 8.0;
        }
    }

    // Perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Open-bins pressure: discourage opening yet another bin when many are
    // already open, unless the fit elsewhere would be terrible.
    if bin_residual == bin_capacity {
        score += 3.0 + 0.15 * open_bins_count as f64;
        // Allow a new bin when the item would leave a good chunk of usable space
        // and current mean residual is already fragmented.
        if post_residual as f64 >= mean_residual {
            score -= 2.0;
        }
    } else {
        // Mild reward for consolidating into existing bins.
        score -= 0.5;
    }

    // Lookahead coupling: reward leaving exactly the space the next item needs.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 20.0;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chaining: item exactly fills space for the next item.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item can still fit here; small gap is fine.
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit; penalize dead space proportional to waste.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Compare against mean residual: bins deviating strongly from mean are
    // either nearly full (good) or oddly empty (bad candidates).
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev.abs();

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless it enables
    // a perfect lookahead chain or current bins are all nearly full.
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
        // Late in the stream, be conservative: reuse existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild bonus for keeping the number of open bins low.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual dominates).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * bin_capacity as f64;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Lookahead: reward leaving space exactly usable by the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // Next item won't fit here; slight penalty proportional to waste.
            score += 2.0 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., this empty bin has large residual and mean residual is small or fragmented).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Prefer packing into existing bins early; allow new bins more later.
        let new_bin_bonus = 8.0 + 10.0 * progress;
        // If mean residual across open bins is small (all nearly full), new bin is good.
        let scarcity = (mean_residual - item_size as f64).max(0.0);
        score = score.max(0.0) + new_bin_bonus - scarcity.min(15.0);
        // If the current item is large and would leave big post-residual anyway, favor fresh bin.
        if item_size > bin_capacity / 2 {
            score -= 5.0;
        }
    }

    // Mild penalty for spreading across many open bins (fragmentation control).
    score += 0.05 * open_bins_count as f64;

    // Time horizon: slightly tighten packing as stream nears end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual, with smooth polynomial shaping
    let mut score = x * (1.0 - x * (1.0 - x));

    // Non-linear coupling of post_residual with stream progress:
    // later in the stream, tighter packing matters more
    score += 0.35 * x * x * progress;

    // Penalize dead space relative to mean residual (smooth quadratic)
    let dead = (pr - mean_residual).abs() / cap;
    score += 0.2 * dead * dead;

    // Reward using nearly-full bins smoothly
    score -= 0.5 * (1.0 - x) * (1.0 - x) * (1.0 - progress);

    // Last-chance bonus: only one fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 0.6 * (1.0 - x);
    }

    // Lookahead: penalize if post residual can't fit next item but is small-ish
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = x - nx;
        if gap >= 0.0 {
            // next item fits: reward mildly, smooth in closeness
            score -= 0.15 * (gap * (1.0 - gap));
        } else {
            // next item won't fit: penalize wasted space smoothly
            score += 0.25 * (-gap) * (-gap);
        }
    }

    // Mild penalty for too many open bins relative to progress
    score += 0.01 * open_bins_count as f64 * (0.2 + progress);

    // New-bin candidate: prefer it only when no open bin is a good fit
    if bin_residual == bin_capacity {
        score += 0.4 + 0.5 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
