pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        // Dead space: gap too small for typical items (min size 1..100, but small gaps waste space).
        score += (10 - pr) as f64 * 6.0;
    } else if pr == 0 {
        // Perfect fit: strongly rewarded.
        score -= 40.0;
    } else if pr >= 10 && pr <= 20 {
        // Usable but risky gap: mild penalty to prefer better fits elsewhere.
        score += 4.0;
    } else if pr > 60 {
        // Large leftover keeps the bin flexible for future items: reward.
        score -= 6.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        // Still penalize if it creates dead space, but less harshly.
        if pr > 0 && pr < 10 {
            score -= 12.0;
        }
    }

    // Open-bins pressure: when many bins are open, discourage opening new ones
    // and encourage consolidating into existing bins.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 15.0 + 8.0 * open_pressure;
        // But if no existing bin fits well (large item, few fitting bins), allow it.
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else if fitting_bins_count == 1 {
            // Only one fitting bin: opening a new bin is usually worse.
            score += 20.0;
        }
    } else {
        // Existing bin: reward slightly more when consolidation is desirable.
        score -= 2.0 * open_pressure;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this placement sets up a perfect future fit.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // Keep enough room for the next item: mild reward proportional to slack.
            score -= 3.0;
        } else {
            // Placement kills the chance to co-locate the next item: penalty
            // proportional to how close we were to fitting it.
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 10.0 {
                score += 0.8 * miss;
            }
        }
    }

    // Mean-residual coupling: placing into a bin far below the mean residual
    // (i.e., a nearly full bin) is good; placing into a very empty bin wastes flexibility.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual - 20.0 {
        score -= 5.0;
    } else if resid_f > mean_residual + 30.0 {
        score += 3.0;
    }

    // Stream progression: early in the stream, be more willing to open new bins
    // (flexibility); late in the stream, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if the next item fits the post residual exactly.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-step chain: bin becomes exactly full
        } else if next_item_size <= post_residual {
            // reward proportional to how much would remain after the next item
            let after_next = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - after_next / bin_capacity as f64);
        } else {
            // next item cannot continue in this bin: penalize wasted residual
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual against mean residual: leaving below-average residual is good.
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize opening new bins when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus cost of lost packing opportunity
        score += 15.0 + 0.1 * open_bins_count as f64;
        // if next item is large, a fresh bin is more attractive
        if next_item_size >= item_size && next_item_size > 50 {
            score -= 20.0;
        }
    }

    // Mild pressure to consolidate as stream progresses.
    score += 10.0 * (step_index as f64 / total_items.max(1) as f64) * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item fills most of the residual.
    let fill_ratio = 1.0 - (post_residual as f64) / (bin_residual as f64).max(1.0);
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize dead space: post_residual that cannot fit the average future item.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dead = (post_residual as f64) / 100.0;
    score += 12.0 * dead * dead;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless the item
    // fits poorly everywhere (large item, few fitting bins).
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count == 0 { 1.0 } else { (1.0 - fill_ratio) };
        let big_item = item_size as f64 / 100.0;
        score += 20.0 + 15.0 * (1.0 - poor_fit) * (1.0 - big_item);
        // Late in the stream, prefer closing out open bins rather than opening new ones.
        score += 10.0 * progress;
    }

    // Lookahead: reward leaving a residual that can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 5.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Global state coupling: when mean residual is high, prefer bins that
    // reduce variance (post_residual close to mean_residual).
    let dev = ((post_residual as f64 - mean_residual) / 100.0).abs();
    score += 6.0 * dev;

    // Many open bins: encourage consolidation into existing bins.
    score += 0.15 * open_bins_count as f64 * (1.0 - fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: minimize post-residual (tight fit preferred)
    let mut score = norm_pr;

    // Smooth polynomial coupling of post-residual with stream progress:
    // late in the stream, dead space is increasingly costly.
    let dead_penalty = norm_pr * norm_pr * (0.5 + 1.5 * progress);
    score += dead_penalty;

    // Reward near-perfect fits with a smooth cubic term
    let perfect = 1.0 - norm_pr;
    score -= 0.35 * perfect * perfect * perfect;

    // Penalize opening a new bin when existing bins fit, more strongly late
    let is_new_bin = (bin_residual as u32 == bin_capacity) && post_residual == bin_residual - item_size && item_size > 0 && bin_residual == bin_capacity;
    if is_new_bin {
        let fit_pressure = 1.0 / (fitting_bins_count as f64 + 1.0);
        score += 0.4 + 0.6 * progress + 0.3 * fit_pressure;
        // If lookahead item also fits the residual, opening a new bin is fine
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            score -= 0.3;
        }
    }

    // Last-chance bin bonus: avoid wasting the only fitting bin's space badly
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 0.25 * (1.0 - norm_pr);
    }

    // Mean residual context: prefer bins below mean residual (filling emptier bins)
    score += 0.1 * ((mean_residual - pr) / cap).tanh();

    // Lookahead synergy: smooth reward if next item matches post-residual well
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs() / cap;
        score += 0.2 * gap * gap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fraction buckets
    let frac = item_size as f64 / bin_capacity as f64;
    let class = (frac * 10.0).floor() as i64; // 0..10

    // Reward tight fits: post_residual small relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    } else {
        // Penalize dead space that can only fit tiny items
        let dead = if post_residual < 30 { 15.0 } else { 0.0 };
        score += dead;
    }

    // Modulo arithmetic on post_residual: residuals that are "harmonic"
    // divisors of capacity (50, 25, 20, 10) are reusable for common item sizes.
    let harmonics = [50u32, 25, 20, 10, 5];
    for h in harmonics.iter() {
        if post_residual == *h {
            score -= 8.0;
        }
    }
    // Odd/awkward residuals penalized
    if post_residual % 2 == 1 && post_residual > 0 {
        score += 3.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // near-dead sliver
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 30.0;
        } else if slack <= 10 {
            score -= 15.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual && post_residual < next_item_size.min(30) {
        // post_residual too small for next item: dead space penalty
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: prefer reusing open bins unless fit is terrible
    if bin_residual == bin_capacity {
        // brand-new bin: baseline slightly above good existing fits
        score = bin_capacity as f64 * 0.6;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // big next item benefits from fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open new bin anyway
        }
    }

    // Late in stream: consolidate, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 5.0;
    }

    // Mild pressure toward bins below mean residual (more packed bins)
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Open-bin count pressure: many open bins -> favor filling existing ones
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= (open_bins_count.min(20) as f64) * 0.5;
    }

    // Class-based tiebreak: prefer pairing large-class items with tight bins
    score += class as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.83;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    // Aggressive 2-step lookahead: reward when next item exactly fills the post-residual
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + gap);
        // penalize leaving residual just below the next item (dead space for k=2)
        if (post_residual as u32) < next_item_size {
            score += 25.0;
        }
    }
    // Prefer tight fits relative to mean residual
    score += 0.4 * (post_residual as f64 - mean_residual).max(0.0);
    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }
    // Penalize opening a new bin when an open bin fits well
    if bin_residual == bin_capacity && open_bins_count > 0 && fitting_bins_count > 0 {
        score += 30.0 + post_residual as f64;
    }
    // Early stream: slightly prefer consolidating into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress) * (1.0 - post_residual as f64 / bin_capacity as f64);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual), with non-linear emphasis.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * bin_capacity as f64;

    // Penalize dead space: residuals too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits in the post-residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 4.0 * (1.0 - post_residual as f64 / next_item_size as f64).min(1.0);
        }
    }

    // Perfect fill reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // New-bin candidate handling: make a fresh bin attractive only when fits are poor.
    if bin_residual == bin_capacity {
        // Base new-bin cost; slightly cheaper as stream progresses (less future to protect).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 25.0 - 8.0 * progress;
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 12.0;
        }
        // If the next item is large, a fresh bin may serve it well.
        if next_item_size > 50 {
            score -= 5.0;
        }
        // Too many open bins with high mean residual: consolidate instead.
        if open_bins_count > 8 && mean_residual > 30.0 {
            score += 10.0;
        }
        return score;
    }

    // Prefer filling bins with larger residuals when mean residual is high (consolidation).
    if (bin_residual as f64) > mean_residual {
        score -= 1.5;
    } else {
        score += 1.0;
    }

    // Mild penalty for opening bins late vs. many open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear coupling: wasted-space penalty grows quadratically with progress
    let waste = pr / cap;
    score += waste * waste * (0.5 + 1.5 * progress) * cap * 0.5;

    // Reward tight fits (small post_residual) more strongly as stream advances
    let tight = 1.0 - waste;
    score -= tight * tight * (1.0 + 2.0 * progress) * 5.0;

    // Lookahead: bonus if next item fits the post-residual exactly or well
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_gap = (pr - next_item_size as f64) / cap;
        score -= (1.0 - fit_gap) * 4.0 * (0.5 + progress);
    } else if next_item_size > 0 {
        // next item cannot use leftover: penalize large residuals
        score += waste * 3.0 * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // New-bin candidate: neutral baseline slightly above well-fitting open bins
    if bin_residual == bin_capacity {
        score = cap * 0.6 + 10.0 * (1.0 - progress) - 2.0 * progress;
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Deviation from mean residual: prefer bins below mean residual (denser bins)
    score += (mean_residual - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 classes
    let post_mod = post_residual % 10;
    // Dead-space penalty: residuals that are tiny but nonzero are worst
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_mod == 0 {
        // perfectly divisible residual is reusable by harmonic classes
        score -= 6.0;
    } else {
        score += post_mod as f64 * 0.4;
    }

    // Fractional fill coupling
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * fill * fill;

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // partial fit reward, stronger when residual class matches
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 {
                score -= 10.0;
            }
            score -= 6.0 * (1.0 - gap as f64 / cap);
        } else {
            // next item cannot use this residual: penalize large residuals less
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral baseline, open new bin when
    // current open bins are fragmented (mean residual low relative to item)
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64) / mean_residual.max(1.0);
        // if open bins are tight, opening a new bin is attractive
        score = cap * 0.9 - 10.0 * pressure;
        if open_bins_count == 0 {
            score -= 40.0;
        }
        // late in stream, prefer consolidating into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
    }

    // Slight preference for bins whose residual is near mean (balanced packing)
    score -= 2.0 * (1.0 - ((post_residual as f64 - mean_residual).abs() / cap).min(1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are wasted.
    // Items are 1..=100, but treat residual < 10 as near-dead space and penalize heavily.
    if post_residual < 10 {
        score -= 50.0; // perfect or near-perfect fill is excellent
    } else if post_residual < 25 {
        score += 30.0; // small unusable gap: strong penalty
    } else if post_residual < 50 {
        score += 10.0; // moderate gap
    } else {
        score -= 15.0; // large residual keeps flexibility
    }

    // Reward tight relative fit.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Open-bin pressure: discourage opening new bins when many bins are open,
    // but allow it when few bins are open (early stream, spread load).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 8.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count.min(20) as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // Lookahead: if next item would fit in the post residual, reward leaving that space.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 5.0; // residual blocks the next item; slight penalty
    }

    // Mean-residual coupling: prefer bins whose residual is below average (tighter bins)
    // when the mean is high, to consolidate space.
    score += 0.1 * (mean_residual - post_residual as f64);

    // Stream progression: later in the stream, be more aggressive about filling bins
    // rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if !is_new_bin {
        score -= 10.0 * progress;
    } else {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact-fit bonus: post_residual == next_item_size is perfect 2-step packing
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits here: reward proportionally to tightness
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 40.0 * tightness;
        } else {
            // next item cannot use the leftover: penalize dead space
            score += 15.0;
        }
    }

    // Penalize very small unusable leftovers (< 10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strong incentive to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer tighter bins relative to mean residual
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Late in the stream, favor filling existing bins over opening new ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    // Mild penalty for many open bins to discourage proliferation
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Mild bonus proportional to how many alternatives exist (prefer well-filled bins).
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 10.0 / (1.0 + gap);
        } else {
            // Next item cannot use leftover space; penalize small leftovers.
            let waste = post_residual.min(next_item_size.saturating_sub(1)) as f64;
            score += 0.15 * waste;
        }
    }

    // Global state coupling: when mean residual is high, prefer filling fuller bins.
    let mean_frac = mean_residual / (bin_capacity as f64);
    score += 8.0 * mean_frac * (post_residual as f64) / (bin_capacity as f64);

    // Time horizon: early in the stream, be more willing to open new bins for large items;
    // late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: accept only if item is large relative to capacity or few bins fit it.
        score += 18.0
            - 10.0 * (item_size as f64 / bin_capacity as f64)
            - 12.0 * progress
            - 5.0 * (fitting_bins_count as f64).recip();
    } else {
        // Existing bin: late in stream, reward usage more strongly.
        score -= 6.0 * progress * (item_size as f64 / bin_capacity as f64);
    }

    // Slight preference for bins whose residual is close to item size (best-fit flavor).
    let slack = (bin_residual - item_size) as f64;
    score += 0.05 * (slack - mean_residual).abs();

    // Penalize proliferating many open bins when residuals are fragmented.
    if open_bins_count > 4 {
        score += 0.3 * ((open_bins_count as f64).ln());
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear emphasis
    let mut score = norm_pr * (1.0 + 0.9 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post-residual with stream progress:
    // later in the stream, tighter packing matters more
    let coupling = norm_pr * (1.0 - progress) * (1.0 - progress) - 0.5 * norm_pr * progress * progress;
    score += 2.0 * coupling;

    // Lookahead: reward residual that can fit the next item, penalize near-miss dead space
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let fit_quality = (pr - n) / cap;
            score -= 1.5 * (1.0 - fit_quality) * (1.0 - 0.5 * progress);
        } else {
            let miss = (n - pr) / cap;
            score += 0.8 * miss * miss * (0.5 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 - norm_pr);
    } else if fitting_bins_count > 1 {
        score += 0.2 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize bins far below mean residual (keeps residual distribution tight)
    score += 0.4 * ((pr - mean_residual) / cap).abs();

    // Slight preference for consolidating into fewer bins late in the stream
    score += 0.05 * (open_bins_count as f64) * progress;

    // New-bin candidate: make it moderately attractive only when open bins are poor fits
    if bin_residual == bin_capacity {
        score -= 0.6 + 0.8 * progress;
        if next_item_size > 0 && (next_item_size as f64) <= cap * 0.5 {
            score -= 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "reusable" the leftover space is.
    // Residuals that are multiples of common item sizes (or land in friendly
    // integer-division classes) are more likely to be filled later.
    let cap = bin_capacity as f64;

    // Class A: post_residual divisible by 10 -> aligns with typical size grid.
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    // Class B: post_residual divisible by 5 (half-grid harmony).
    if post_residual % 5 == 0 {
        score -= 2.5;
    }
    // Class C: post_residual can exactly host the lookahead item (perfect pairing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }
    // Class D: post_residual >= next_item_size -> lookahead still fits here.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    } else if next_item_size > 0 {
        // Lookahead would NOT fit: penalize creating a stranded small residual.
        score += 5.0;
    }

    // Dead-space penalty: very small leftovers are nearly unusable (sizes >= 1).
    if post_residual < 10 && post_residual > 0 {
        score += 8.0 * (10 - post_residual) as f64 / 10.0;
    }

    // Integer-division threshold classes on post_residual relative to capacity.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual >= half {
        score -= 3.0; // still roomy bin, keep it attractive
    } else if post_residual >= quarter {
        score -= 1.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin gets a mild baseline penalty so we
    // only open when existing bins look bad, but reward it when the item fits
    // nearly exactly (tight packing from scratch).
    if bin_residual == bin_capacity {
        score += 4.0;
        if post_residual <= quarter {
            score -= 8.0;
        }
    }

    // Waste-fraction coupling: penalize proportional waste in this placement.
    score += (post_residual as f64 / cap) * 6.0;

    // Mean-residual harmony: prefer bins whose residual is close to the mean
    // (balanced depletion), measured via squared deviation class.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Late-stream tightening: as the stream progresses, favor filling existing
    // bins more aggressively over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 3.0;
    }

    // Exact-fill reward: item perfectly closes the bin.
    if post_residual == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no future item (min size 1..=small)
    // could ever use are the worst waste. Penalize tiny unusable gaps heavily.
    let min_item = 1u32;
    if post_residual < item_size.min(100) && post_residual >= min_item {
        // gap smaller than the current item class: likely dead space
        score += (bin_capacity as f64 - post_residual as f64) * 0.5;
    }
    if post_residual == 0 {
        score -= 60.0; // perfect fit is always best
    }

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 30.0;

    // Dead-space trap: residual left that is smaller than the lookahead item
    // but the lookahead could have fit here otherwise.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage proliferation of bins; stronger early in stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (2.0 + 4.0 * (1.0 - progress));

    // New-bin candidate (empty bin): make it unattractive unless this bin would
    // otherwise be a terrible fit (large post_residual dead space).
    if bin_residual == bin_capacity {
        score += 55.0;
        if post_residual as f64 > mean_residual + 20.0 {
            score -= 70.0; // opening fresh is better than dumping into fragmented bins
        }
    }

    // Slight preference for bins below mean residual (balance loads)
    score += (post_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward bins whose post_residual matches the next item exactly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // Next item fits: strongly reward exact/tight matches.
            score -= (bin_capacity as f64 / (1.0 + gap)) * 0.9;
            if gap < 1.0 {
                score -= 25.0; // perfect chain: this bin then next item
            }
        } else {
            // Dead space smaller than the next item: penalize proportionally.
            score += (nxt - post_residual as f64) * 0.35;
        }
    } else {
        // Last item: just minimize waste.
        score -= 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when the item is large relative
    // to residual capacity of open bins, or no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are preferred for normal fits.
        score += 30.0;
        // But large items benefit from a fresh bin (avoid fragmentation).
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 55.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // If many bins are open, discourage adding more.
        score += 2.0 * open_bins_count as f64;
    } else {
        // Reward bins tighter than the mean residual (denser bins first).
        score -= 0.25 * (mean_residual - bin_residual as f64);
        // Mild reward for filling bins nearly full.
        if post_residual <= 10 {
            score -= 15.0;
        }
    }

    // Small general preference for high occupancy.
    score -= (item_size as f64 / bin_capacity as f64) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small to hold even the smallest item (1).
    // Instead penalize residuals smaller than next_item_size (lookahead waste).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 * (next_item_size - post_residual) as f64;
    }
    // Reward residuals that exactly accommodate the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer the bin where item is a large fraction of residual.
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 10.0 * fill_ratio;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Time horizon coupling: late in the stream, consolidate aggressively
    // (avoid new bins); early, allow spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 8.0 + 30.0 * progress;
        // Opening a new bin is worse if other bins fit.
        if fitting_bins_count >= 1 {
            score += 15.0 + 10.0 * (fitting_bins_count as f64).ln();
        }
    }

    // Global state: if mean residual is high, prefer filling the emptiest bins;
    // if mean residual is low, prefer bins tighter than the mean.
    if bin_residual as f64 > mean_residual {
        score -= 4.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    } else {
        score += 4.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.6 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (low post_residual), with non-linear polynomial shaping.
    let mut score = post * (1.0 + 0.35 * progress) + 40.0 * norm_post * norm_post;

    // Dead-space penalty grows super-linearly for small residuals.
    if post > 0.0 {
        score += 12.0 * (1.0 - norm_post).powi(3) * norm_post;
    }

    // Smooth stream-progress coupling: later in the stream, favor compacting bins harder.
    score -= 15.0 * (1.0 - norm_post) * progress * (1.0 - progress) * 4.0;

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: penalize if the next item won't fit in the post residual (wasted potential),
    // reward if it fits nicely.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 10.0 * (1.0 - (nxt / cap)) * (1.0 - progress);
        } else {
            score += 8.0 * (nxt - post) / cap;
        }
    }

    // Slight penalty when this bin is far below the mean residual (fragmentation risk).
    score += 0.15 * (mean_residual - post).abs();

    // New-bin candidate: make it moderately attractive only when open bins are poor fits.
    if bin_residual == bin_capacity {
        score = cap * 0.55 - 10.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible into capacity quarters
    let quarter = bin_capacity / 4;
    let residue_class = (post_residual % quarter) as f64;
    score += residue_class * 0.15; // penalize residuals that waste capacity granularity

    // Integer-division class: post_residual / quarter tells how "full" the bin is
    let fullness_class = post_residual / quarter;
    score -= (4 - fullness_class.min(4)) as f64 * 8.0; // reward fuller bins

    // Dead-space penalty: tiny unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score += 12.0; // would create new dead space
            }
        } else {
            score += 8.0; // next item won't fit here; deprioritize slightly
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor
    if bin_residual == bin_capacity {
        let crowded = mean_residual / bin_capacity as f64;
        score = 30.0 + crowded * 20.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        if item_size > 70 {
            score -= 15.0;
        }
    }

    // Modulo-3 harmonic tiebreak on item size classes
    let size_class = item_size % 3;
    score -= size_class as f64 * 1.5;

    // Mild pressure to consolidate as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: penalize small unusable gaps
    // (gaps below the minimum possible item size are wasted forever).
    if post_residual > 0 && post_residual < 10 {
        score += 120.0 + (10 - post_residual) as f64 * 15.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // Moderately tight gaps are risky: only few item sizes can use them.
        score += 30.0 * (1.0 - (post_residual as f64 - 10.0) / 15.0);
    }

    // Lookahead synergy: reward if the next item fits the post-residual exactly,
    // penalize if post-residual is too small for the next item (dead chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 250.0;
        } else if post_residual >= next_item_size {
            score -= 40.0;
        } else if post_residual > 0 {
            score += 20.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score += pressure * 2.0;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate calibration: an empty bin should only win when
    // no open bin offers a good fit. Penalize it mildly by its raw residual
    // plus a fixed offset so tight existing fits beat it.
    if bin_residual == bin_capacity {
        score += 60.0 + open_bins_count as f64 * 5.0;
        // Late in the stream, opening new bins is more wasteful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 50.0;
    }

    // Slight preference for using bins with lower residuals overall (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit reward: strongly favor bins whose residual is exactly consumed.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fills the post residual,
    // this is a perfect two-item chain — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but leaves slack: penalize proportionally to slack.
            score += 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Next item cannot use this bin's leftover: penalize the dead space.
            score += 0.25 * post_residual as f64;
        }
    }

    // Small leftover space is hard to use later: superlinear penalty on tiny residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Compare against mean residual: bins tighter than average are precious,
    // bins looser than average are better targets.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Prefer filling fuller bins (relative fill fraction bonus).
    score -= 10.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Early in the stream, slightly favor consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 15.0 * (1.0 - progress) * (open_bins_count as f64 / 50.0).min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post-residual so small leftovers dominate.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Penalize bins whose post-residual is a "dead zone": too small for any
    // plausible future item (min size 1), but wastefully large.
    let dead_zone = (post_residual > 0 && post_residual < 8) as f64;
    score += dead_zone * 25.0;

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly reward this placement (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item cannot follow here; slight penalty proportional to gap
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should generally lose to decent fits,
    // but win when open bins are fragmented / residual is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base handicap: prefer reusing open bins.
        score += 35.0 + open_bins_count as f64 * 1.5;
        // But if the mean residual across open bins is small (fragmented),
        // opening a fresh bin becomes attractive.
        if mean_residual < item_size as f64 * 1.2 {
            score -= 45.0;
        }
        // Late in the stream, avoid spawning extra bins.
        score -= progress * 10.0;
        // If the item is large relative to capacity, new bin is fine.
        score -= (item_size as f64 / bin_capacity as f64) * 15.0;
    }

    // Mild reward for filling bins that are already mostly full (consolidation).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 6.0;

    // Spread-awareness: keep residuals balanced; penalize placing into a bin
    // far below the mean residual when that bin is nearly empty of use.
    if bin_residual as f64 > mean_residual + 30.0 && bin_residual < bin_capacity {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress) - 8.0 * norm_pr * prog2;

    // Reward tight fits more strongly as stream progresses
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fit_ratio * fit_ratio * (0.3 + prog3);

    // Penalize dead space relative to next item lookahead
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            score += 3.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        } else {
            score -= 2.0 * (-gap / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Mild penalty when many open bins with high mean residual (fragmentation)
    score += 0.05 * (open_bins_count as f64) * (mean_residual / cap) * (0.5 + prog2);

    // Slight incentive to use existing bins over opening new ones early
    if bin_residual == bin_capacity {
        score += 4.0 * (1.0 - progress) + 2.0 * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 create "dead zones"
    // whose usability depends on the smallest plausible item size.
    let residue = post_residual % 10;
    let dead_zone = if post_residual == 0 {
        0.0 // perfect fit: best possible outcome
    } else if post_residual < 10 {
        25.0 // tiny unusable sliver
    } else {
        match residue {
            0 => -8.0,                 // round residual: many items fit exactly
            1..=4 => 6.0 + 2.0 * residue as f64,
            5 => -3.0,                 // half-decade residual
            _ => 3.0 + (9 - residue) as f64,
        }
    };
    score += dead_zone;

    // Integer-division harmonic classes: how many "average items" still fit?
    let avg_item = 50.0f64;
    let fits_class = (post_residual as f64 / avg_item).floor();
    score -= 4.0 * fits_class;

    // Lookahead coupling: does next_item_size fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact/modulo harmony bonus
            let harmony = if post_residual % next_item_size == 0 { 12.0 } else { 5.0 };
            score -= harmony;
        } else {
            // next item won't fit here: residual likely becomes dead space
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 + gap * 0.15;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer a new bin when current item creates a poor fit elsewhere
        // or when open bins are already fragmented (high mean residual spread).
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let poor_fit = (post_residual as f64 / bin_capacity as f64) < 0.25 && post_residual > 0;
        if poor_fit || (next_item_size > 0 && next_item_size > post_residual && post_residual < 30) {
            score -= 30.0;
        } else {
            score += 15.0 + fragmentation * 0.3;
        }
        // Early in the stream, opening bins is cheap; late, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Slight preference for bins whose residual is far below mean (tight bins)
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item (<= 10) are nearly worthless -> heavy penalty.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual <= 15 {
        score += 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another
    // one; make the empty-bin candidate less attractive.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.5 * open_bins_count as f64;
    } else {
        // Slight consolidation bonus when many bins are open.
        score -= 0.5 * open_bins_count as f64;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this placement is excellent; if it barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual {
            score += 6.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably
    // from the mean (below-mean residual bins are tighter, better to fill).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Late-stream urgency: as the stream nears its end, close out bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as i64 == next_item_size as i64 {
            score -= 400.0; // perfect chain: next item fills this bin exactly
        } else if (post_residual as i64 - next_item_size as i64) > 0 {
            score -= 150.0 - diff; // next item still fits, prefer tight chain
        } else {
            score += diff * 2.0; // next item would not fit: penalize dead space risk
        }
    }

    // Compare against mean residual: prefer bins that are tighter than average.
    score += (post_residual as f64 - mean_residual) * 1.5;

    // Last-chance bin bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin when existing bins could take the item,
    // unless the fit is very poor.
    if bin_residual == bin_capacity {
        score += 60.0;
        if post_residual as f64 > mean_residual {
            score += 40.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0; // a fresh bin chains well with the next item
        }
    }

    // Late-stream bias: consolidate more aggressively as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 10.0;

    // Mild penalty for large leftover fragments that are hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny slivers are nearly useless
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize tight-but-wasteful fits: dead space below the minimum item size is unusable.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score -= 50.0; // perfect fit
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0 + 0.05 * next_item_size as f64;
        } else {
            // Penalize leaving residual too small for the next item (dead space).
            score += 0.10 * (next_item_size as f64 - post_residual as f64).max(0.0);
        }
    }

    // New-bin candidate handling: penalize opening a new bin, but allow it when
    // existing bins are very full (high mean fill) or fit is poor.
    if bin_residual == bin_capacity {
        let mean_fill = 1.0 - mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut open_penalty = 8.0 + 4.0 * mean_fill; // more bins open & fuller => prefer existing bins
        open_penalty *= 1.0 + 0.5 * progress;
        // If the item would leave huge waste in any existing bin anyway, new bin is fine:
        // approximate best existing alternative via mean_residual.
        if mean_residual < item_size as f64 * 1.2 {
            open_penalty -= 6.0;
        }
        score += open_penalty;
    } else {
        // Prefer bins that are already partially filled (reduce bin count pressure).
        let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 2.0 * fill;
        // Mild penalty proportional to open bins count to encourage consolidation.
        score += 0.02 * open_bins_count as f64;
    }

    // Non-linear waste shaping: quadratically penalize mid-range leftover space.
    let pr = post_residual as f64;
    score += 0.02 * pr * pr / 10.0;

    // Reward close-to-full outcomes slightly super-linearly.
    if pr <= 5 {
        score -= 6.0 + (5.0 - pr) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear waste penalty: dead space hurts more as it approaches half-capacity
    let waste = post / cap;
    score += 8.0 * waste * (1.0 - waste) * (0.5 + progress);

    // Tight fit reward (small post_residual) — smooth quadratic
    score -= 6.0 * (1.0 - waste) * (1.0 - waste);

    // Last-chance bonus: only one bin fits -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Prefer bins below mean residual (keep big residuals for big items)
    score += 0.05 * (post - mean_residual);

    // Lookahead coupling: reward if next item fits in post_residual
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 3.0 * (next_item_size as f64 / cap);
    }

    // Penalize opening a new bin when existing bins fit well
    if bin_residual == bin_capacity {
        score += 6.0 + 2.0 * (open_bins_count as f64).sqrt();
        if fitting_bins_count > 0 {
            score += 12.0;
        }
    }

    // Late-stream consolidation pressure
    score += progress * post * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the residual: residues divisible by large chunks (25/20/10)
    // are more reusable, so reward them; odd/tiny residues are dead space.
    let r = post_residual;
    if r == 0 {
        score -= 60.0; // perfect fit
    } else if r % 25 == 0 {
        score -= 18.0;
    } else if r % 20 == 0 {
        score -= 12.0;
    } else if r % 10 == 0 {
        score -= 6.0;
    } else if r < 10 {
        score += 25.0; // unusable dead space
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= r {
            let slack = (r - next_item_size) as f64;
            score -= 10.0 + 0.15 * slack;
            // harmonic match: next item lands exactly on a residual class
            if (r - next_item_size) % 10 == 0 {
                score -= 6.0;
            }
        } else {
            score += 8.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when all open bins fit poorly
    // (large post_residual everywhere) or many bins are already open.
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual - item_size as f64;
        let poor_fits = if fitting_bins_count > 1 { (avg_waste.max(0.0)) } else { 0.0 };
        score = 40.0 + 0.5 * poor_fits + 0.3 * open_bins_count as f64
            - (step_index as f64 / total_items.max(1) as f64) * 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity as u32 {
            // a fresh bin guarantees the next item fits too
            score -= 5.0;
        }
    }

    // Mild normalization: prefer tighter bins overall.
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest possible item
    // (size 1) are less severe than gaps below common item sizes; penalize any
    // residual that is "unusable" relative to the incoming item stream.
    let pr = post_residual as f64;
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 1000.0;
    } else if post_residual < 10 {
        // Dead space below the minimum item size is permanently wasted.
        score += 60.0 + (10.0 - pr) * 8.0;
    } else if post_residual < 30 {
        // Small gaps risk becoming dead space: super-linear penalty.
        score += (30.0 - pr) * (30.0 - pr) * 0.12;
    }

    // Reward tight fits: small post_residual relative to item size is good.
    let it = item_size as f64;
    if it > 0.0 {
        score -= 40.0 * (it / (it + pr)) - 20.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: prefer placing into existing bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize mildly so it's chosen only for poor fits
        // elsewhere, but relax late in the stream when consolidation is hopeless.
        score += 25.0 + pressure * 1.2 - 20.0 * progress;
    } else {
        // Slight reward for reusing bins, scaled by open-bin count.
        score -= pressure * 0.8;
    }

    // Prefer bins whose residual deviates from the mean in useful ways:
    // a bin with residual far below mean is "specialized" — good for small items.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Lookahead: if the next item fits exactly into the post_residual, reward heavily.
    if next_item_size > 0 && next_item_size as f64 == pr {
        score -= 120.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 15.0;
    } else if next_item_size > 0 {
        // Next item won't fit here: post_residual likely becomes dead space.
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item fits exactly into the post residual (2-step lookahead).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        // Partial reward proportional to how well the next item would fill the bin.
        score -= 30.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    } else if next_item_size > post_residual {
        // Next item cannot fit here; penalize wasted space relative to mean residual.
        score += (post_residual as f64 - mean_residual).abs() * 0.5;
    }

    // Penalize large unusable post residuals (dead space).
    if post_residual > 0 && post_residual < 10 {
        score -= 10.0; // tiny residual is great (nearly perfect fit)
    } else if post_residual > 0 && post_residual < 25 {
        score -= 4.0;
    } else if post_residual >= 25 && post_residual < 50 {
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Favor filling bins when many bins are open (reduce fragmentation).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 0.1 * open_bins_count as f64 * (1.0 - progress);

    // Reward tight fits relative to capacity.
    score -= 20.0 * (item_size as f64 / bin_capacity as f64);

    // New-bin candidate: make it moderately attractive only when current bin wastes space.
    if bin_residual == bin_capacity {
        score += 15.0 - 0.2 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squashed post-residual matters less than raw value.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness) * (1.0 - tightness);

    // Lookahead: if next item exactly fills post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // reward partial compatibility, scaled by how much next item consumes
            let use_ratio = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * use_ratio;
        } else {
            // next item cannot use this residual: penalize large dead space
            score += 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent open bins exist and stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if fitting_bins_count > 0 {
            score += 40.0 * (1.0 - progress);
        }
        // new bins more acceptable late in the stream
        score -= 10.0 * progress;
    }

    // Prefer bins with residuals close to the mean (balanced packing),
    // penalize outliers that strand capacity.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Mildly prefer using bins that are already open (avoid bin proliferation)
    if bin_residual != bin_capacity && open_bins_count > 0 {
        score -= 3.0;
    }

    // Waste-aversion: heavily penalize residuals too small for any future item
    // (items are >= 1, but small fragments are typically unusable).
    if post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with smooth non-linear shaping
    let mut score = norm_pr * (1.0 + 2.0 * norm_pr * (1.0 - progress));

    // Non-linear coupling: wasted space weighted by stream progress
    let waste_term = (norm_pr / cap).powi(2) * (1.0 + 3.0 * progress);
    score += waste_term * 10.0;

    // Reward bins whose post-residual could fit the next item (smooth lookahead)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0 * (1.0 - (next_item_size as f64 / cap)) * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 1.5 * progress;
    }

    // Last-chance bin: strong smooth reward to avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 3.0 + 2.0 * progress;
    }

    // Mild preference for consolidating into fewer bins
    score += (open_bins_count as f64).ln() * 0.1 * norm_pr;

    // Penalize bins far from mean residual (smooth deviation coupling)
    score += ((mean_residual - pr).abs() / cap) * 0.5;

    // New-bin candidate: baseline competitive score, better late in stream if fit is bad
    if bin_residual == bin_capacity {
        score = 8.0 + 6.0 * progress * (1.0 - norm_pr) - 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the post-residual: residuals in the "usable band"
    // (>= next plausible item size, ~10..100) are valuable; tiny residuals are dead space.
    let dead = post_residual < 10;
    if dead {
        score += 60.0; // penalize creating dead space
    }

    // Modulo-class logic on post_residual: residuals that are multiples of common
    // item sizes (divisors of 100: 10,20,25,50) are re-usable "harmonic" slots.
    let harmonic = (post_residual % 10 == 0) || (post_residual % 25 == 0) || (post_residual % 50 == 0);
    if harmonic {
        score -= 12.0;
    }

    // Lookahead coupling: reward if the next item fits exactly or well in post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 300.0; // chain a perfect fit
        } else {
            score -= (next_item_size as f64) * 0.8;
            if slack % 10 == 0 {
                score -= 8.0;
            }
        }
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // Next item fits this bin only if we DON'T fill it too much — mild penalty
        // for consuming space the lookahead needs.
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin wastes its full capacity.
    if bin_residual == bin_capacity {
        // Prefer a new bin only when current bin would leave a bad (dead-space) residual
        // or when no open bin fits (fitting_bins_count==0 means only new bin candidate).
        if post_residual < 10 && next_item_size > 0 {
            score -= 55.0; // opening fresh bin better than leaving dead space
        } else {
            score += 30.0 + 0.25 * (open_bins_count as f64);
        }
    }

    // Mild preference to pack into fuller bins (small residual before placement)
    score += 0.15 * (bin_residual as f64);

    // Stream progression: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let min_useful = if next_item_size > 0 { next_item_size.min(80) } else { 10 };
    if post_residual < min_useful {
        // Gap is dead space relative to the next item: quadratic-ish penalty.
        let dead = (min_useful - post_residual) as f64;
        score += dead * dead * 0.5;
    }

    // Reward very tight fits (post_residual near zero).
    if post_residual <= 5 {
        score -= 40.0;
    }

    // Perfect fit gets an extra bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins count and progress.
        score = bin_capacity as f64 + open_bins_count as f64 * 8.0 + progress * 20.0;
    } else {
        // Mild penalty for bins that deviate from mean residual (fragmentation signal).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    // Slight preference for fuller bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

