    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to tightness
            let tightness = next_item_size as f64 / post_residual as f64;
            score -= 200.0 * tightness;
        } else {
            // next item does not fit: penalize wasted space relative to next item
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Relative to mean residual: prefer bins with residuals near item size (tight fits)
    let mean_r = mean_residual;
    if mean_r > 0.0 {
        let rel = post_residual as f64 / mean_r;
        score += 10.0 * (rel - 1.0).abs();
    }

    // Penalize large dead space (unusable for typical items)
    if post_residual > 0 && post_residual < 10 {
        score -= 50.0; // small dead space is nearly a perfect fit
    } else if post_residual > 50 {
        score += 5.0; // large leftover is fine (flexible)
    } else {
        score += (50 - post_residual) as f64 * 0.2; // awkward middle zone penalty
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: neutral baseline; only choose it when open bins score poorly
    if bin_residual == bin_capacity {
        score += 120.0 + (post_residual as f64 - mean_residual.max(1.0)) * 0.1;
        // but if next item is large and no tight fits likely, opening a new bin is okay
        if next_item_size > 0 && next_item_size >= bin_capacity - 20 {
            score -= 60.0;
        }
    }

    // Slight preference to fill older/more bins when many open
    if open_bins_count > 8 {
        score -= 2.0;
    }

    // Progress-based mild tightening: later in stream, be greedier about fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small post_residual) with a non-linear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 60.0 * (1.0 - fit_ratio).powi(6);

    // Penalize small-but-unusable residuals: dead space below half the smallest plausible item.
    if post_residual > 0 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 1.5;
    }

    // Lookahead coupling: bonus if the next item fits exactly into the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            // Reward good pairings, penalize leaving space that barely misses next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / 100.0).powi(3);
        } else {
            // Next item won't fit here: slight penalty proportional to overshoot.
            score += ((next_item_size - post_residual) as f64).min(40.0) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer the one with residual closest to item size.
        score += (fitting_bins_count as f64 - 1.0).sqrt() * 2.0;
    }

    // Time horizon: early in the stream, encourage consolidation to keep bins open;
    // late in the stream, allow opening new bins more freely.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_penalty = 30.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty plus discouragement when many bins are open
        // but their mean residual is small (poor global state).
        score += new_bin_penalty + (open_bins_count as f64).sqrt() * 4.0
                 - mean_residual * 0.15;
    } else {
        // Existing bin: reward using bins when mean residual is high (lots of slack around).
        score -= mean_residual * 0.05;
    }

    // Mild penalty for very full bins being "wasted" on small items.
    if item_size < 25 && post_residual > 70 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;
    let p2 = progress * progress;

    // Dead space penalty grows super-linearly as stream progresses (less time to fill gaps).
    score += prn * prn * (1.0 + 3.0 * p2) * 20.0;

    // Smooth reward for tight fits, stronger early when residual space is valuable later.
    let tightness = 1.0 - prn;
    score -= tightness * tightness * (1.0 + 2.0 * (1.0 - progress)) * 8.0;

    // Last-chance bin: strongly favor using it, scaled smoothly by scarcity.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - prn);
    }

    // Prefer bins with residual below mean residual (better consolidation), smooth quadratic.
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 10.0;

    // Lookahead: bonus if next item fits exactly into post_residual (smooth exponential-like).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= (1.0 - gap / cap).exp() * 6.0;
    }

    // Mild penalty for proliferating open bins, smoothed by progress.
    score += open_bins_count as f64 * (0.2 + 0.8 * p2);

    // New-bin candidate: penalize unless it enables a much better future fit.
    if bin_residual == bin_capacity {
        score += 30.0 - 15.0 * tightness * (next_item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into
    // "reusable" residue classes (small, or near sizes likely to arrive).
    let pr = post_residual;
    let class_bonus = match pr {
        0 => 60.0,                          // perfect fit
        1..=10 => 40.0,                     // tiny dead space
        11..=20 => 25.0,
        21..=35 => 12.0,
        _ => 0.0,
    };
    score -= class_bonus;

    // Modulo coupling: residual divisible by common size blocks is reusable.
    if pr > 0 && (pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0 || pr % 50 == 0) {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 70.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / cap);
        } else {
            // next item cannot follow here: penalize proportionally
            score += 10.0 * (1.0 - (next_item_size - pr) as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Many open bins: prefer tightening existing bins, discourage sprawl.
    if open_bins_count > 4 {
        score -= 5.0 * ((open_bins_count as f64).ln() + 1.0);
    }

    // Prefer bins with residual close to the item (tight fit).
    let tightness = 1.0 - (bin_residual as f64 - item_size as f64) / cap;
    score -= 20.0 * tightness * tightness;

    // Late in the stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress;

    // New-bin candidate: baseline so it wins only when fits are poor.
    if bin_residual == bin_capacity {
        let base = 55.0
            - if next_item_size > 0 && next_item_size <= bin_capacity {
                10.0
            } else {
                0.0
            };
        return base + 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Small but potentially usable gap: mild penalty scaled by gap size.
        score += (20 - post_residual) as f64 * 0.8;
    }

    // Reward tight fits (near-perfect packing).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if post_residual == 0 {
        score -= 40.0; // perfect fit, close the bin
    } else {
        score -= 12.0 * fill_ratio; // larger items deserve the scarce space
    }

    // Lookahead: if the next item would fit exactly in the post residual,
    // strongly favor this placement (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else if post_residual > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
            // next item fits in this bin only if we place current item here loosely
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual >= 0 {
        score -= 15.0;
        // but if the fit leaves a bad dead gap, soften the reward
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; penalize placements into bins
    // far from the mean residual (fragmentation signal).
    score += open_bins_count as f64 * 0.3;
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins are very full
        // (low mean residual) or no good fit exists. Penalize mildly so tight
        // fits in open bins win, but allow it when open bins are nearly full.
        score += 10.0 + mean_residual * 0.2;
        // If this is a large item and open bins are tight, new bin is fine.
        if fill_ratio > 0.6 && mean_residual < 15.0 {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidation.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += progress * 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead match: strongly reward bins whose post_residual
    // exactly accommodates the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Penalize leftover after a hypothetical second placement,
            // scaled by how much slack remains (dead-space avoidance).
            score += 0.3 * slack;
        } else {
            // Next item cannot follow: leftover is likely dead space.
            score += 0.6 * (next_item_size - post_residual) as f64;
        }
    }

    // Reward tight fits relative to mean residual across open bins.
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.2 * (post_f - mean_residual).abs();
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when the
    // item fits poorly everywhere (large dead space would be created).
    if bin_residual == bin_capacity {
        // Neutral baseline for a fresh bin; slightly discouraged early on
        // so existing bins get used, more acceptable as stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 70.0 - 10.0 * progress;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
    }

    // Small penalty for leaving residuals too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post_residual.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize small unusable post_residual (< 10, min item size) — dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let best_open = if fitting_bins_count == 0 {
            0.0
        } else {
            (bin_residual.saturating_sub(item_size)) as f64
        };
        // Opening a new bin wastes (capacity - item_size); penalize unless current
        // fit would leave a bad residual and next item could use the fresh bin.
        score += 18.0;
        if fitting_bins_count > 0 {
            score += 10.0;
        }
        // Lookahead: fresh bin is good if next item fits the new residual well.
        if next_item_size > 0 {
            let nr = bin_capacity.saturating_sub(next_item_size);
            if nr < 15 {
                score -= 20.0;
            }
        }
        // Late in stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // Many open bins: discourage opening more.
        score += open_bins_count as f64 * 1.5;
        // High mean residual means open bins have room; avoid new bin.
        score += (mean_residual - 20.0).max(0.0) * 0.4;
    }

    // Lookahead coupling for open bins: leaving room for next item is good.
    if next_item_size > 0 && bin_residual != bin_capacity {
        if post_residual as f64 >= next_item_size as f64 {
            score -= 6.0;
        } else if post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
            score += 4.0;
        }
    }

    // Prefer bins whose residual is close to item (minimal waste relative to mean).
    let waste_gap = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += waste_gap * 0.1;

    // Mild preference for fuller bins overall.
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual_frac = post / cap;

    // Base: prefer small post residual (tight fit), smoothed polynomial.
    let mut score = post;

    // Non-linear coupling: tight fits matter more as the stream progresses.
    let tightness = 1.0 - residual_frac; // 1 = perfect fit
    score -= tightness * tightness * (cap * (0.35 + 0.65 * progress));

    // Penalize large wasted residual quadratically (dead space).
    score += residual_frac * residual_frac * cap * 0.6;

    // Interaction: penalize residual that is too small to hold a typical future item.
    let next = next_item_size as f64;
    if next > 0.0 {
        let gap = (next - post).max(0.0) / cap;
        score += gap * gap * cap * 0.5;
        // Reward residual that exactly accommodates the next item.
        if post >= next && post - next < 10.0 {
            score -= 12.0 * (1.0 - progress);
        }
    }

    // New-bin candidate handling: opening a bin is expensive; discourage unless
    // no good alternative exists (few fitting bins) or fit is very tight.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin {
        let scarcity = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        let discount = 0.45 * scarcity + 0.25 * (1.0 - progress);
        score = cap * (0.9 - discount) + post;
    } else {
        // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
        if fitting_bins_count == 1 {
            score -= 18.0;
        }
        // Mild penalty for spreading across many open bins.
        score += open_bins_count as f64 * 0.15;
        // Prefer bins whose residual deviates from the mean in a useful way.
        score -= (mean_residual - post).abs() * -0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward small, "clean" residuals
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit
    } else if pr <= 5 {
        score -= 120.0;
    } else if pr <= 10 {
        score -= 60.0;
    } else if pr <= 20 {
        score -= 25.0;
    } else {
        // modulo arithmetic on dead space: multiples of common item sizes are reusable
        let m = pr % 10;
        if m == 0 {
            score -= 15.0;
        } else if m >= 6 {
            score += (m as f64) * 1.5;
        }
    }

    // Penalize residuals that cannot host next item (dead space)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0 + 0.3 * (post_residual - next_item_size) as f64;
        } else {
            score += 40.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
        // harmonic coupling: next item fits exactly into a class of the residual
        if post_residual > 0 && next_item_size % post_residual.max(1) == 0 && post_residual > 5 {
            score -= 20.0;
        }
    }

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when current fits are poor
    if bin_residual == bin_capacity {
        score = (bin_capacity - post_residual) as f64;
        // opening a new bin is penalized mildly; fewer open bins keep packing tight
        score += 60.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 50.0; // big next item: fresh bin useful
        }
        if fitting_bins_count == 1 {
            // competing with a single tight bin: keep new-bin score moderate
            score += 150.0;
        }
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative
        }
    }

    // Tight-fit reward: item fills most of the bin
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 80.0 * fill_frac * fill_frac;

    // Mean-residual coupling: prefer bins deviating from mean toward tighter state
    score += 0.4 * (mean_residual - bin_residual as f64).abs().signum() * (mean_residual - bin_residual as f64);

    // Late-stream tightening: waste hurts more as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 40.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest possible item (1..100 unknown distribution) are pure waste.
    // Penalize unusable gaps nonlinearly (quadratic growth).
    if post_residual < item_size {
        score += (post_residual as f64) * (post_residual as f64) * 0.05;
    }

    // Perfect-fit reward: zero post_residual is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize leaving a gap that is small but nonzero (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // If next item cannot fit into post_residual, mild penalty (wasted gap).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0;
    }

    // Open-bins pressure: discourage spreading across many open bins,
    // favor filling existing bins when there are many.
    score += (open_bins_count as f64) * 0.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        score += 60.0 + (item_size as f64).min(100.0) * 0.2;
        // If item nearly fills a fresh bin, reduce penalty.
        if item_size as f64 / bin_capacity as f64 > 0.8 {
            score -= 40.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates below
    // mean (tighter bins get filled first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Stream progression: later in the stream, be more conservative about
    // dead space (amplify post_residual penalty).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match lookahead: next item fits into the post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (post_residual as f64 - next_item_size as f64 + 1.0).ln().max(0.0);
    } else if next_item_size > 0 {
        // Next item cannot follow in this bin: penalize proportionally to wasted potential
        let waste = next_item_size as f64 - post_residual as f64;
        score += 0.15 * waste.min(60.0);
    }

    // Penalize leaving residual far below mean_residual (dead space relative to fleet)
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += 0.10 * dev;
    } else {
        score += 0.05 * (-dev);
    }

    // Tight packing bonus: small post residual relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    // New-bin candidate: prefer it early or when no good match exists among open bins
    if bin_residual == bin_capacity {
        score -= 8.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 20.0; // fresh bin gives a perfect lookahead match for the NEXT item
        }
        // penalize opening new bins when many bins are already open and one fits well
        if post_residual == 0 {
            score -= 15.0;
        } else {
            score += 5.0 + 0.2 * open_bins_count as f64;
        }
    }

    // Late stream: consolidate aggressively into existing bins
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize large unusable post-residual ("dead space") relative to typical item sizes.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score -= 8.0; // small but useless slivers are actually good to consume elsewhere
    } else if dead >= 10.0 && dead < 20.0 {
        score += 3.0; // moderately reusable, mild penalty vs perfect fits
    } else if dead >= 20.0 {
        score += 6.0 * (dead / 100.0);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits in the post-residual, this is a
    // great chaining opportunity.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_quality = next_item_size as f64 / post_residual as f64;
        score -= 12.0 * chain_quality;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize blocking the next item if post-residual is a tempting-but-failing gap.
        let gap_waste = (post_residual as f64 - 0.0).min(next_item_size as f64);
        score += 4.0 * (gap_waste / 100.0);
    }

    // Global state: when many bins are open with high mean residual, prefer
    // consolidating into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins have plenty of room
        // or when we're early in the stream with few bins.
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 50.0);
        score += 18.0 + 10.0 * (1.0 - progress) - 2.0 * crowding.min(10.0);
        // If no existing bin fits well, new bin becomes attractive (handled by
        // the last-chance subtraction above on the other candidate).
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Existing bin: slight reward when mean residual is high (use up slack).
        score -= 1.5 * (mean_residual / 100.0);
        // Prefer bins whose residual is close to the item (best-fit refinement).
        let slack_diff = (bin_residual as f64 - item_size as f64);
        score += 0.05 * slack_diff;
    }

    // Mild time-horizon term: late in the stream, be greedier about tight fits.
    score -= 5.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 - progress) + pr_norm * progress * (1.0 - pr_norm);
    score += 4.0 * poly * cap * 0.1;

    // Reward tight fits (small post_residual) more strongly later in the stream
    let tightness = 1.0 - pr_norm;
    score -= 2.0 * tightness * tightness * (0.5 + progress);

    // Lookahead: reward if next item fits in post_residual, penalize otherwise
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 3.0 * (next_item_size as f64 / cap) * (1.0 - progress);
        } else {
            score += 2.0 * (next_item_size as f64 / cap) * progress;
        }
    }

    // Penalize spreading residual far from mean residual (imbalance)
    score += 0.3 * ((pr - mean_residual) / cap).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Penalize opening a new bin when open bins could fit, less so early on
    if bin_residual == bin_capacity {
        score += 6.0 - 3.0 * progress;
        if fitting_bins_count > 0 {
            score += 2.0;
        }
    }

    // Mild penalty for many open bins
    score += 0.05 * open_bins_count as f64 * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo structure on capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Dead-space penalty: residuals in awkward modular classes are hard to fill
    // Residuals that are multiples of 8 (esp. 16, 32, 64) are "usable" classes
    if post_residual > 0 {
        let m16 = post_residual % 16;
        let m8 = post_residual % 8;
        if m16 == 0 {
            score -= 6.0; // highly reusable harmonic class
        } else if m8 == 0 {
            score -= 3.0;
        } else {
            score += 2.0 + m8 as f64 * 0.4; // non-harmonic remainder penalized
        }
        // Very small residual = near-perfect fit, strong reward
        if post_residual <= eighth {
            score -= 8.0;
        }
        // Integer-division thresholds: residual in (25,50] is a "half-class" sweet spot
        if post_residual / quarter == 1 {
            score -= 2.5;
        }
        // Tiny but nonzero residual (dead space < 10, hard to fill with items >=10)
        if post_residual < 10 {
            score += 12.0; // wasted space penalty (interface note: sizes can be small)
        }
    } else {
        score -= 20.0; // perfect closure
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0 + (next_item_size as f64) * 0.05;
        // Bonus if next item exactly consumes a harmonic class of the residual
        if post_residual % next_item_size.max(1) == 0 {
            score -= 3.0;
        }
    } else if next_item_size > post_residual {
        score += 1.5; // residual too small for lookahead
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: mildly discourage opening new bins early,
    // more strongly when many bins are already open with slack
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 4.0 + 10.0 * (1.0 - progress) + open_bins_count as f64 * 0.8;
        // If mean residual across open bins is large, opening new bin is wasteful
        if mean_residual > 25.0 {
            score += (mean_residual - 25.0) * 0.3;
        }
        // But if nothing fits well (large post_residual would result anyway),
        // a fresh bin is fine: offset the penalty when item is large
        if item_size >= 3 * quarter {
            score -= 8.0;
        }
    }

    // Tight-fit reward: residual consumed exactly
    if post_residual == 0 {
        score -= 5.0;
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 4.0 * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to ever hold
    // anything (min item size 1, but practically < ~10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Tightness ratio: prefer bins where the item fills a large fraction
    // of the residual.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill;

    // Last chance: if this is the only fitting bin, strongly prefer using
    // it over opening a new bin (unless the dead-space penalty dominates).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Pressure from many open bins: discourage spreading across bins when
    // the fleet is already large; encourage consolidating into open bins.
    let open_pressure = (open_bins_count as f64 / 20.0).min(2.0);
    if bin_residual < bin_capacity {
        score -= 6.0 * open_pressure;
    } else {
        // New-bin candidate: penalize opening a new bin, more so when many
        // bins are open and the stream is early (long future to fill bins).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 + 12.0 * open_pressure * (1.0 - 0.5 * progress);
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 35.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here: mild penalty if post residual becomes
        // a stranded gap.
        score += 5.0;
    }

    // Slight preference for bins whose residual deviates above the mean
    // (keep low-residual bins for small future items).
    if bin_residual as f64 > mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: residual after placing equals next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Partial reward for near-perfect match.
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= (20.0 * (1.0 - slack / bin_capacity as f64)).max(0.0);
    }
    // Penalize dead space that the next item cannot use at all.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 15.0;
    }

    // Tight fit reward relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness;

    // Penalize leaving residuals far below the mean (fragmentation).
    let diff = post_residual as f64 - mean_residual;
    score += 0.15 * diff.abs();

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current bin would leave unusable residue.
    if bin_residual == bin_capacity {
        let bad_fit = next_item_size > 0 && post_residual < next_item_size && post_residual > 0;
        if bad_fit {
            score += 40.0; // opening new bin is fine when fit is poor
        } else {
            score += 70.0; // otherwise prefer existing bins
        }
    }

    // Mild pressure to consolidate as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual is primary, sharpen it non-linearly.
    if post_residual == 0 {
        score -= 50.0; // perfect closure is always great
    } else {
        let pr = post_residual as f64;
        score += (pr / bin_capacity as f64) * 30.0; // penalize large leftover space
        // Dead-space penalty: leftover that no plausible item can use
        if pr < 10.0 {
            score += 20.0; // tiny unusable sliver is wasted space
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty if we leave a big hole
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Crowding: when many bins are open, prefer consolidating into fuller bins.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0 * (open_bins_count as f64).ln().max(1.0);

    // Compare against mean residual: penalize burning a bin that is much fuller than average.
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 && residual_f > mean_residual * 1.5 {
        score += (residual_f - mean_residual) * 0.5;
    }

    // New-bin candidate handling: opening a new bin should only win when no open bin
    // is a decent fit. Make the empty bin attractive only if it promises future utility.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // base cost of opening a bin
        score = 60.0;
        // late in the stream, opening new bins is cheaper (less future to waste)
        score -= 40.0 * progress;
        // if the item is large, a fresh bin is more acceptable
        score -= (item_size as f64 / 100.0) * 25.0;
        // if next item is large too, fresh bin helps
        if next_item_size >= 50 {
            score -= 15.0;
        }
        // if only one bin can fit the item, opening new bin is wasteful
        if fitting_bins_count == 1 {
            score += 100.0;
        }
    }

    // Mild time-horizon modulation: early stream, be frugal with near-full bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= fill_ratio * 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: quadratic penalty on wasted space, growing with stream progress.
    let mut score = pr * (1.0 + 0.9 * progress) + 1.5 * fit_norm * fit_norm * cap;

    // Smooth interaction: small residuals are dead space; penalize more as stream progresses.
    let deadness = (1.0 - fit_norm).powi(3);
    score += 8.0 * deadness * (0.3 + 0.7 * progress) * cap;

    // Reward tight fits: subtract when post_residual is small relative to capacity.
    score -= 6.0 * (1.0 - fit_norm).powi(2) * (1.0 + progress);

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = if pr >= nxt { 1.0 } else { 0.0 };
        let slack = (pr - nxt) / cap;
        score -= 4.0 * fits_next * (1.0 - slack).max(0.0);
        // Penalize leaving residual just below next item size (smooth barrier).
        let gap = (nxt - pr).max(0.0) / cap;
        score += 5.0 * (1.0 - gap).max(0.0) * (1.0 - fits_next);
    }

    // Mild pressure against opening many bins when mean residual is high.
    score += 0.15 * (open_bins_count as f64) * (mean_residual / cap) * (1.0 - progress);

    // New-bin candidate: make empty bins moderately attractive only for large items / bad fits.
    if bin_residual == bin_capacity {
        score = pr + 2.0 - 3.0 * (item_size as f64 / cap) - 2.0 * progress;
        if fitting_bins_count == 1 {
            score += 6.0; // prefer the last existing fitting bin over a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: quantize into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Class A: perfect fit -> strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }
    // Class B: tiny dead space (<= 10% capacity) -> reward
    else if frac <= 0.10 {
        score -= 60.0;
    }
    // Class C: awkward mid-range residual (30..60% of capacity) -> penalize,
    // since most items (1..100) either fit or create unusable gaps
    else if frac >= 0.30 && frac <= 0.60 {
        score += 25.0;
    }
    // Class D: large residual (> 60%) -> mild reward, keeps flexibility
    else if frac > 0.60 {
        score -= 15.0;
    }

    // Integer-division threshold classes on post_residual (harmonic bands of 25)
    let band = post_residual / 25;
    score += match band {
        0 => -20.0,  // 0..24 : near-perfect slot
        1 => -5.0,   // 25..49
        2 => 10.0,   // 50..74 : awkward
        3 => 0.0,    // 75..99
        _ => -10.0,  // 100+ : new bin
    };

    // Modulo coupling: residual compatible with next item's size class
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            // Next item fits exactly into this residual -> big reward
            if (pr - nx).abs() < 1e-9 {
                score -= 80.0;
            } else if pr - nx <= 10.0 {
                score -= 30.0;
            } else {
                score -= 10.0;
            }
        } else {
            // Next item cannot use this residual: penalize proportional to gap
            score += 0.3 * (nx - pr);
        }
        // Harmonic residue: next item shares a divisor class with residual
        if next_item_size % 10 == post_residual % 10 && pr >= nx {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive if it beats poor fits
    if bin_residual == bin_capacity {
        score += 12.0 + 0.15 * open_bins_count as f64;
        // If item is huge relative to capacity, opening fresh is fine
        if item_size as f64 > 0.8 * cap {
            score -= 30.0;
        }
    }

    // Progress-based tightening: later in stream, waste matters more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.4 * progress;

    // Mean residual coupling: keep this bin's residual near the mean
    score += 0.2 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps (<10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Coupling: dead space is worse when the lookahead item cannot use it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Last-chance bin before opening a new one: strong reward to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into existing bins.
    let pressure = (open_bins_count as f64).min(20.0) * 1.5;
    if bin_residual != bin_capacity {
        score -= pressure;
    } else {
        // New-bin candidate: penalize slightly more as bins accumulate,
        // but allow opening when residual mean suggests poor fits everywhere.
        score += 10.0 + pressure * 0.5;
        if mean_residual < item_size as f64 {
            score -= 25.0;
        }
    }

    // Late in the stream, tighten up: avoid leaving scraps that never get filled.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += progress * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: exact match of post_residual with next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as u32 == next_item_size {
            score -= 400.0;
        } else if (post_residual as u32) > next_item_size {
            // next item fits here afterwards: mild reward scaled by tightness
            let tight = 1.0 - ((post_residual as f64 - next) / cap);
            score -= 50.0 * tight;
        } else {
            // next item cannot follow into this bin: penalize proportionally
            let waste = next - post_residual as f64;
            score += 0.5 * waste;
        }
    }

    // Prefer bins whose residual is below mean (tight bins get used first)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when no open bin is a good fit
    if bin_residual == bin_capacity {
        let good_fit = (item_size as f64 / cap) > 0.7
            || (next_item_size > 0 && next_item_size >= item_size && next_item_size <= bin_capacity);
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 150.0 };
        score = if good_fit { score + pressure - 50.0 } else { score + 500.0 };
    }

    // Late-stream tightening: waste less as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.2 * post_residual as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 3.0;
        }
        // Exact two-item completion is excellent.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else {
        // Last item: any bin that fits is fine; strongly prefer not opening a bin.
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * (open_bins_count as f64).sqrt();
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0;
        }
    }

    // Mild pressure to consolidate as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    let fit_norm = pr_norm * pr_norm;

    // Base: waste after placement, with smooth non-linear penalty on mid-range residuals
    let mut score = pr * (1.0 + 0.8 * fit_norm * (1.0 - fit_norm) * 4.0);

    // Stream-progress coupling: late in the stream, penalize residual more strongly
    // (encourage tight packing as stream ends), smoothly.
    score *= 1.0 + 0.6 * progress * progress;

    // Reward tight fits (small post_residual) especially when many bins compete
    if fitting_bins_count > 0 {
        score -= 6.0 * (1.0 - pr_norm) * (1.0 - pr_norm) / (fitting_bins_count as f64);
    }

    // Last-chance bonus: strongly favor this bin if it is the only one that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let compat = 1.0 - (pr - nx).abs() / cap;
        score -= 4.0 * compat.max(0.0) * compat.max(0.0);
        // Penalize post-residual that is too small to be useful
        if pr > 0.0 && pr < nx {
            score += 3.0 * (nx - pr) / cap;
        }
    }

    // Mean-residual context: if this bin is far below average residual (already tight),
    // prefer using it (smooth interaction).
    let dev = (mean_residual - pr) / cap;
    score -= 2.0 * dev * dev * dev.signum();

    // Mild penalty for opening a new bin when open bins exist and fit is easy
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 8.0 + 4.0 * (1.0 - item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small item friendly" classes (multiples of small divisors) are reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward tiny residuals (near-perfect fit) nonlinearly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    }

    // Harmonic class check: post_residual divisible by common small item sizes
    // (10, 20, 25, 50) means the leftover is exactly fillable by typical items.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 8.0;
        }
        if post_residual % 20 == 0 {
            score -= 4.0;
        }
        if post_residual % 25 == 0 {
            score -= 3.0;
        }
        if post_residual % 50 == 0 {
            score -= 3.0;
        }
    }

    // Lookahead coupling: reward if next item fits the post residual well.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / cap);
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > post_residual {
        // Next item won't fit here; penalize leaving large unusable gaps.
        score += 0.15 * pr;
    }

    // Dead-space penalty: residuals in awkward bands (just above small items)
    let awkward = (post_residual >= 11 && post_residual <= 14)
        || (post_residual >= 21 && post_residual <= 24)
        || (post_residual >= 31 && post_residual <= 34);
    if awkward {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer filling existing bins over opening new ones, more so early in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New bin candidate: base cost, cheaper late in the stream.
        score += 40.0 - 20.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        score -= 5.0 + 10.0 * (1.0 - progress);
    }

    // Tie-break toward bins tighter than the mean residual.
    score += 0.1 * (pr - mean_residual);

    // Mild preference for compact bins as open bin count grows.
    score += 0.05 * (open_bins_count as f64) * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized,
    // since almost no item (min size 1... but practically 10+) can fill them.
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0;
    } else if post_residual <= 15 && post_residual > 0 {
        score += 12.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 - 0.4 * slack;
    }
    // Penalize if next item cannot fit here (bin will be dead for the next step).
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Pressure from number of open bins: prefer consolidating into fewer bins.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are terrible.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Opening a new bin is more acceptable late in the stream or when few bins are open.
        score -= 10.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Slight preference for bins whose residual is close to the mean (balance residuals).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly matches the next item's size (perfect chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Next item cannot follow here: penalize wasted lookahead potential
        score += 5.0;
    }

    // Penalize post_residual far below the minimum plausible item size
    // (dead space that likely nothing can fill).
    if post_residual < 10 {
        score += 12.0 * (10 - post_residual) as f64;
    }

    // Tight fits are good: small post_residual relative to capacity is rewarded.
    score -= 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Relative-to-mean coupling: prefer bins whose residual deviates
    // favorably from the mean residual of open bins.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral baseline; encourage it when open bins are
    // numerous and fragmented (their mean residual is high but unusable),
    // discourage it early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 45.0 + 20.0 * progress - 2.0 * open_bins_count as f64;
        // If lookahead item fits a fresh bin perfectly, keep new bin attractive
        if next_item_size == bin_capacity {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize unusable dead space: post_residual too small for any plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty for wasting large residual
            score += 0.05 * (post_residual as f64 - mean_residual).abs();
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Crowding: when many bins are open, prefer consolidation into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowd = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += 0.3 * crowd;

    // Prefer bins with residual below mean (fill fuller bins first)
    score += 0.2 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: make it moderately attractive only when no good fit exists
    if bin_residual == bin_capacity {
        // base cost of opening a bin; tight fits elsewhere will beat this
        score = 45.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size.saturating_mul(2).min(bin_capacity) {
            score -= 5.0; // fresh bin useful if item is large
        }
        if item_size > 60 {
            score -= 10.0; // large items benefit from empty bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    score += 12.0 * norm_pr * norm_pr * (0.5 + t) * cap * 0.01;

    // Reward tight fits more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= 10.0 * tightness * tightness * (0.3 + t);

    // Penalize residuals that are too small to be useful (dead space)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let usable = if pr >= nxt { 1.0 } else { 0.0 };
        // smooth version: sigmoid-like falloff as pr approaches nxt
        let ratio = (pr / nxt).max(0.0);
        let smooth_usable = ratio / (1.0 + ratio);
        score -= 6.0 * smooth_usable * usable;
        score += 5.0 * (1.0 - smooth_usable) * (1.0 - usable);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0 * (1.0 - t);
    }

    // Mild penalty when many bins are open and residual is large (fragmentation)
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 2.0;

    // Deviation from mean residual: prefer bins near the mean (balance)
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: keep neutral baseline so it only wins when fits are bad
    if bin_residual == bin_capacity {
        score += 3.0 + 4.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: harmonic classes on post_residual
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    } else if post_residual <= 30 {
        score -= 4.0;
    } else {
        // large dead space penalized super-linearly
        score += (post_residual as f64 - 30.0) * 0.35;
    }

    // Modulo-class coupling: post_residual classes vs capacity fractions
    let pr = post_residual;
    if pr % 10 == 0 {
        score -= 6.0; // clean class residual likely reusable
    }
    if pr % 25 == 0 {
        score -= 3.0;
    }
    let quarter = bin_capacity / 4;
    if pr < quarter {
        score += 5.0; // sub-quarter slivers are hard to fill
    }

    // Lookahead: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 14.0; // chain placement possible
            // exact harmonic match bonus
            if next_item_size == pr {
                score -= 12.0;
            } else if pr - next_item_size <= 10 {
                score -= 6.0;
            }
        } else {
            score += 4.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when all open fits are poor
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 40.0 + open_bins_count as f64 * 0.5;
        // but if this item would leave bad residuals elsewhere, new bin is fine
        if post_residual >= bin_capacity - item_size && item_size >= bin_capacity / 2 {
            score -= 30.0;
        }
        if fitting_bins_count == 0 {
            score -= 55.0; // no alternative
        }
    } else {
        // prefer reusing existing bins over opening new ones
        score -= 8.0;
    }

    // Progression: late in stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64).abs() * 0.1;
    score += progress * 5.0;

    // Prefer bins below mean residual (denser bins)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Post-residuals below the minimum item size (1) are impossible; residuals
    // in the "unusable small gap" band (1..=10) are the worst kind of waste:
    // almost no future item fits, so penalize them super-linearly.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }
    // Medium gaps (11..=30) are partially usable; mild penalty slope.
    if post_residual > 10 && post_residual <= 30 {
        score += 8.0;
    }

    // Reward exact / near-exact fills.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // --- Tight-fit coupling: prefer bins where item fills a large fraction of residual ---
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio > 0.9 {
            score -= 25.0 * fill_ratio;
        } else if fill_ratio < 0.4 {
            score += 10.0 * (0.4 - fill_ratio); // sloppy fit penalty
        }
    }

    // --- Lookahead (k=2): if next item would fit the post-residual, reward heavily ---
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
        // Extra reward if post_residual is a snug container for the next item.
        let snug = (post_residual - next_item_size) as f64;
        score -= 10.0 / (1.0 + snug);
    }
    // If next item cannot fit the post-residual, the gap is likely dead weight.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // --- Last-chance pressure: this is the only bin that fits; avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins are crowded
        // and the item is large relative to capacity (poor fit prospects).
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        let item_burden = item_size as f64 / bin_capacity as f64;
        let base_new = 45.0 // default: prefer reusing open bins
            - 55.0 * crowding
            - 30.0 * item_burden;
        // If no open bin is even close, allow the new bin.
        if fitting_bins_count == 0 {
            score = base_new - 80.0;
        } else {
            score = base_new + post_residual as f64;
        }
    }

    // --- Open-bin count pressure: mild reward for consolidating into fewer bins ---
    score += open_bins_count as f64 * 0.5;

    // --- Stream progression: late in the stream, tighten up and reuse aggressively ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills the remaining space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 1000.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward tight coupling, penalize leftover gap.
            let gap_after_next = post_residual - next_item_size;
            score -= 50.0 - gap_after_next as f64 * 0.5;
        } else {
            // Next item does not fit: penalize proportionally to overshoot.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Penalize dead space relative to mean residual across open bins.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.4;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Favor keeping many open bins consolidated when few bins are open.
    score -= (open_bins_count as f64).sqrt() * 0.1;

    // Slight early-stream preference for tight fits to build good structure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    // Prefer bins that are already substantially filled.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic bonus for small post_residual.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= (1.0 - tight) * (1.0 - tight) * 12.0;

    // Perfect fit gets a strong extra reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 20.0;
