    // Lookahead: penalize leaving residual that barely fails to fit the next item
    // (dead space), reward residual that can host the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (post_residual as f64) >= ni {
            score -= 8.0;
        } else if (post_residual as f64) > ni * 0.6 {
            // awkward dead space: next item won't fit but gap is large
            score += (post_residual as f64) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when the fit is bad or
    // many bins are already open with low mean residual (fragmentation).
    if bin_residual == bin_capacity {
        let fit_quality = item_size as f64 / bin_capacity as f64;
        let mut new_bin_score = 45.0; // base cost of opening a new bin
        new_bin_score -= fit_quality * 30.0; // big items justify new bins
        if fitting_bins_count == 1 {
            new_bin_score += 40.0; // the only fitting bin is bad? still costly, offset last-chance
        }
        if open_bins_count > 3 && mean_residual < 20.0 {
            new_bin_score -= 15.0; // fragmented state: fresh bin may be better
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += progress * 10.0;
        return new_bin_score;
    }

    // Mild penalty for wasting a nearly-empty bin on a tiny item.
    let fill = item_size as f64 / bin_residual as f64;
    if fill < 0.2 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, non-linearly in post_residual
    let mut score = pr * (1.0 + 0.9 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // early on tolerate larger residuals; late, demand tight fits.
    let prog_coupling = 30.0 * (1.0 - progress) * (norm_pr * norm_pr) + 15.0 * progress * (norm_pr * norm_pr * norm_pr);
    score += prog_coupling;

    // Reward using an existing bin (penalize new-bin candidate mildly)
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * progress;
    }

    // Last-chance bonus: this is the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score -= 6.0 * (1.0 - gap / cap).max(0.0) * (1.0 - progress);
        // penalize leaving a sliver the next item cannot use
        if nxt > pr {
            score += 4.0 * (nxt - pr) / cap;
        }
    } else {
        // last item: just minimize waste
        score -= 5.0;
    }

    // Mild preference to balance residuals across open bins
    score += 2.0 * (pr - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: strongly penalize opening a new bin unless it's a
    // last-chance situation or the item leaves a very usable residual.
    if bin_residual == bin_capacity {
        let fresh_penalty = 120.0
            + (open_bins_count as f64) * 3.0
            + (mean_residual - item_size as f64).max(0.0) * 0.8;
        // If this bin is the only fitting option, opening is fine.
        if fitting_bins_count <= 1 {
            score = 5.0;
        } else if post_residual as f64 >= mean_residual {
            // Fresh bin leaves a larger-than-average residual: mildly attractive.
            score = fresh_penalty - 60.0;
        } else {
            score = fresh_penalty;
        }
        return score;
    }

    // Harmonic class of post_residual: residues divisible by 10 are more
    // reusable against typical item sizes; reward them.
    let class = post_residual % 10;
    score += match class {
        0 => -6.0,
        5 => -3.0,
        1 | 9 => 2.0,
        _ => 0.0,
    };

    // Tight fits are excellent: reward small post_residual non-linearly.
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Dead-space penalty: post_residual that no plausible item (>=1, but
    // practically >=10 in classic streams) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Lookahead coupling: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's remainder: slight penalty if
            // remainder is small (dead end), else neutral.
            if post_residual < 10 {
                score += 8.0;
            }
        }
    }

    // Last-chance bonus: if this is the only open bin that fits, prefer it
    // heavily to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Early stream: keep bins flexible (prefer larger post_residual),
    // late stream: squeeze hard (prefer smaller post_residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.15
           - progress * (post_residual as f64) * 0.10;

    // Prefer filling bins with larger residuals slightly (consolidation),
    // scaled by how many bins are open.
    score -= (bin_residual as f64 / bin_capacity as f64) * (2.0 + open_bins_count as f64 * 0.2);

    // Alignment with mean residual: bins far from mean get mild regularization.
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small unusable gaps are the worst outcome: they waste capacity forever.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64; // 10..9 => +600..+60, strongly penalized
    }
    // Perfect fit is the ideal outcome.
    if post_residual == 0 {
        score -= 500.0;
    }

    // --- Tightness reward: prefer bins where the item dominates the residual ---
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 80.0 * tightness;

    // --- Open-bin pressure: discourage scattering items across many bins ---
    score += 2.5 * open_bins_count as f64;

    // --- Last-chance bonus: if this is the only bin that fits, use it hard ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // --- New-bin candidate handling (bin_residual == bin_capacity) ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no open bin fits, or the
        // current item leaves a large useful residual for the NEXT item.
        let next_fits_new = next_item_size as f64 <= post_residual as f64 && next_item_size > 0;
        let next_fits_here = next_item_size as f64 <= post_residual as f64;
        if fitting_bins_count > 0 {
            // Some open bin fits: new bin must be clearly justified.
            score += 90.0;
            if !next_fits_new {
                score += 40.0; // opening a bin that won't help the next item either
            }
        } else {
            // No open bin fits: new bin is the only option.
            score -= 100.0;
        }
        // Slight preference for a fresh bin early in the stream (future flexibility).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * (1.0 - progress);
    } else {
        // --- Lookahead coupling: reward residual that exactly accommodates next item ---
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 90.0; // residual perfectly consumed by next item
            } else if post_residual > next_item_size {
                score -= 0.3 * next_item_size as f64; // residual remains usable
            } else {
                // residual smaller than next item: partially dead space
                score += 0.4 * (next_item_size - post_residual) as f64;
            }
        }
        // --- Mean-residual coupling: prefer bins deviating below the mean residual
        // (concentrate filling into emptier bins keeps other bins' residual intact) ---
        score += 0.2 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fills
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits exactly in the post residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize leftover that wastes space
            let waste = (next_item_size - post_residual) as f64;
            score += 0.3 * waste;
        }
    } else {
        // Last item: strongly prefer tightest fit
        score -= 300.0;
    }

    // Prefer bins whose residual is below mean (denser bins get filled first)
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only bin that can fit the item, use it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Penalize opening a new bin when decent fits exist, unless residual is very small
    if bin_residual == bin_capacity {
        score += 120.0;
        // But if all open bins would leave large waste, new bin is attractive
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0;
        }
        if mean_residual < item_size as f64 {
            score -= 100.0;
        }
    }

    // Mild penalty for leaving awkward medium residuals that rarely fit future items
    if post_residual > 10 && post_residual < 20 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: keep it competitive but not dominant.
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity;
    if is_new_bin {
        score += 25.0;
        // Late in the stream, opening a new bin is cheaper than dead space.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * progress;
        return score;
    }

    // Reward tight fits: small post_residual is good (already in base score).
    // Penalize post_residual that is unusable for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Residual can host the next item: reward proportional to slack.
            score -= 8.0 * (post_residual as f64 / bin_capacity as f64);
        } else {
            // Dead space relative to lookahead: penalize.
            let waste = post_residual as f64 / next_item_size.max(1) as f64;
            score += 12.0 * (1.0 - waste).max(0.0) + 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Global pressure: many open bins with low mean residual -> consolidate.
    let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
    score -= 3.0 * pressure;

    // Prefer bins already below mean residual (balancing residuals).
    score += 2.0 * (bin_residual as f64 - mean_residual);

    // Early stream: slightly favor filling few bins densely.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = (post_residual as f64 / cap).clamp(0.0, 1.0);
    let pr2 = pr * pr;
    let pr3 = pr2 * pr;
    let p2 = progress * progress;
    let p3 = p2 * progress;

    // Dead-space penalty grows with stream progress (late stream => waste hurts more).
    score += (0.5 + 1.5 * progress) * (pr2 * 30.0) - (pr3 * 10.0);

    // Smooth interaction: tight fits rewarded more as stream advances.
    score -= (1.0 - pr2) * (10.0 + 20.0 * p2);

    // Lookahead: reward leaving room for the next item, smoothly.
    let ni = next_item_size as f64;
    if ni > 0.0 {
        let gap = (post_residual as f64 - ni).abs();
        let gnorm = (gap / cap).clamp(0.0, 1.0);
        score -= 12.0 * (1.0 - gnorm * gnorm);
    }

    // Penalize the fresh-bin candidate unless current bins fit poorly.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        score += 25.0 + 15.0 * p2 - 8.0 * (fitting_bins_count as f64).ln().max(0.0);
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strong reward to use it.
        score -= 20.0;
    }

    // Mild congestion pressure: spread load when many bins are open.
    score += (open_bins_count as f64).sqrt() * 0.3 * pr2;

    // Mean-residual coupling: prefer bins deviating from the mean residual.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 5.0 * (1.0 - dev * dev);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize leftover space into capacity fractions.
    let post_frac = post_residual as f64 / cap;
    let class = (post_frac * 8.0).floor(); // 8 harmonic classes of residual size

    // Reward placements that land the residual in a "small" class (tight fit).
    score -= (8.0 - class) * 2.0;

    // Penalize large dead space nonlinearly: residual above half capacity is wasteful.
    if post_frac > 0.5 {
        score += (post_frac - 0.5) * 60.0;
    }

    // Perfect / near-perfect fit gets strong reward.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Integer-division threshold coupling with the lookahead item.
    if next_item_size > 0 {
        // If the next item fits exactly in the post-residual, big reward.
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Next item can still fit: mild reward proportional to leftover-after-next.
            let after_next = post_residual - next_item_size;
            score -= (after_next as f64) * 0.15;
        } else {
            // Next item cannot fit here: penalize proportional to the gap.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
        // Modulo harmony: reward when post_residual mod next_item_size is small.
        if next_item_size > 0 && post_residual > 0 {
            let m = post_residual % next_item_size;
            if m == 0 {
                score -= 10.0;
            } else {
                score += m as f64 * 0.3;
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly so we only open when fits are truly bad,
    // but relax the penalty as the stream progresses and bins accumulate.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (open_bins_count as f64).sqrt() * 2.0 + mean_residual * 0.2;
        score = cap * 0.6 + progress * 10.0 - pressure;
        // Opening a fresh bin is fine if the item is huge relative to capacity.
        score -= item_size as f64 * 0.5;
    }

    // Prefer bins whose residual is close to the item (tight packing) via ratio term.
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 8.0;
    }

    // Small tie-breaker toward bins already below mean residual (consolidation).
    score += (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A residual gap is "dead" if it can hold at least 1 but is too small to
    // plausibly accept a future item (gap < 10 is pure waste).
    let gap = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10.0 - gap) * 8.0; // smaller dead gap => worse
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit is strongly rewarded
    }

    // Penalize leaving gaps that are just barely below typical item sizes,
    // creating awkward "almost fits" that waste capacity.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing bins
    // (tight packing) over spreading out; with few open bins, opening is cheap.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open,
        // unless the current placement would leave a tiny dead gap.
        score += 15.0 + open_pressure * 2.5;
        if gap > 0.0 && gap < 10.0 {
            score -= 55.0; // override: opening beats creating dead space
        }
    } else {
        score -= open_pressure.min(10.0) * 1.5;
    }

    // Lookahead: if the next item would fit in the post residual, reward it;
    // if it would fit only in a fresh bin, mildly discourage wasting space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if gap >= nxt {
            score -= 10.0;
        } else if gap > 0.0 && nxt > gap {
            score += 6.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins (cheap),
    // late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 10.0;
    } else {
        score -= progress * 5.0;
    }

    // Mean residual coupling: if this bin's post-residual is far below the
    // mean residual, we are compacting well; reward that.
    if gap < mean_residual {
        score -= (mean_residual - gap).min(30.0) * 0.5;
    } else {
        score += (gap - mean_residual).min(30.0) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit: small leftover relative to capacity
    if post_residual as f64 <= 0.1 * bin_capacity as f64 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: reward bins where next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // next item fits in leftover: penalize proportional leftover after next
            let leftover2 = post_residual - next_item_size;
            score -= 100.0 - (leftover2 as f64 * 0.8);
        } else {
            // next item won't fit in leftover: penalize large dead space
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Relative to mean residual: prefer bins with residual below mean (consolidating)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Many open bins: discourage opening new bins
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 200.0 + open_bins_count as f64 * 10.0 + progress * 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large post-residual waste, nonlinearly (dead space is superlinearly bad).
    let waste = post_residual as f64;
    score += 0.35 * (waste / 10.0).powf(1.6);

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64);
        score -= 6.0 * tightness * tightness;
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            // Reward leaving a usable remainder for the next item, penalize tiny leftovers.
            if slack_after_next >= 10 {
                score -= 4.0;
            } else {
                score += 5.0;
            }
        } else {
            // Next item won't fit here anyway; slight reward for leaving flexible residual.
            score += (post_residual as f64) / 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins below mean residual (keep residual distribution balanced).
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    // Time horizon: early in the stream, be conservative about filling bins unevenly;
    // late in the stream, prioritize closing bins out (small post residual).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (1.0 - waste / bin_capacity as f64);
    score += 4.0 * (1.0 - progress) * (open_bins_count as f64 / 20.0).min(1.0);

    // Many open bins: encourage consolidating into existing bins rather than new ones.
    score -= (open_bins_count as f64).ln().max(0.0) * 1.2;

    // New-bin candidate handling: make an empty bin attractive only when the fit here
    // is poor (large post residual) — otherwise prefer existing bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 10.0;
        // But if placing here would leave awkward dead space, a fresh bin is better.
        if post_residual > 0 && post_residual < 15 && item_size < bin_capacity {
            score -= 18.0;
        }
        // Late in stream with few bins, opening fresh is cheap.
        if progress > 0.7 && open_bins_count < 5 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr);
    score -= 40.0 * poly * (0.5 + progress);
    // penalize large dead space late in the stream
    score += progress * norm_pr * norm_pr * 30.0;
    // reward tight fits
    score -= (item_size as f64 / cap) * 10.0;
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }
    // lookahead coupling: favor residuals that fit the next item
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 12.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 8.0 * (next_item_size as f64 / cap);
    }
    // mild penalty when bin residual deviates from mean residual
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();
    // new-bin candidate: penalize slightly unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 6.0 - 10.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class logic: classify post_residual into modulo classes.
    // Residuals that are "usable" (large enough to host a typical future item)
    // are rewarded; tiny unusable slivers are penalized.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Class of the post-residual via integer division thresholds.
    let class = post_residual / 10; // harmonic class of width 10
    match class {
        0 => {
            // Dead space: 0..9 remaining. Highly undesirable unless it's a perfect fit.
            score += 40.0 * (1.0 - progress);
        }
        1 => {
            // 10..19: marginal, only useful for small items.
            score += 18.0 * (1.0 - progress);
        }
        2 => {
            // 20..29: moderate usability.
            score += 8.0;
        }
        3 | 4 => {
            // 30..49: good harbor for medium items.
            score -= 6.0;
        }
        _ => {
            // 50+: plenty of room left, excellent.
            score -= 10.0;
        }
    }

    // Perfect-fit harmonic bonus: post_residual exactly divisible by 10
    // (aligned with capacity fractions) is a cleaner state.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }
    // Perfect closure bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // strongly reward; if next item cannot fit, mildly penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 20.0;
    }

    // New-bin candidate: neutral-ish baseline; open a new bin only when all
    // existing fits would leave bad residuals, or when the system is crowded.
    if bin_residual == bin_capacity {
        let avg_penalty = (mean_residual - post_residual as f64).abs();
        score = 55.0 + 0.1 * open_bins_count as f64 + avg_penalty * 0.1 - 30.0 * progress;
        // If no open bin fits at all, new bin is essential.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild regularization toward mean residual state.
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for small unusable gaps after placement (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits: post_residual near zero is best.
    score -= 15.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(6);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Pressure: when many bins are open, prefer consolidating into existing bins
    // (penalize the new-bin candidate more heavily).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 + 3.0 * open_bins_count as f64 * (0.3 + progress);
    } else {
        score -= 2.0 * (open_bins_count as f64).sqrt();
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer bins with below-average residual (tighter bins first).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 150.0;
        } else if post_residual < next_item_size {
            // dead space relative to next item: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Penalize large leftover residual that is unlikely usable (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // tiny slivers are near-useless
    }

    // Compare against mean residual: prefer bins that are tighter than average
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless it is genuinely needed
    if bin_residual == bin_capacity {
        // base penalty for opening a new bin
        score += 60.0;
        // if few bins can fit, opening new bin is more acceptable
        if fitting_bins_count <= 1 {
            score -= 80.0;
        }
        // early in stream, more willing to open bins
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += progress * 40.0;
        }
        // if next item is large, a fresh bin is valuable
        if next_item_size > 50 {
            score -= 30.0;
        }
    }

    // Many open bins: prefer consolidation into existing bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (best-fit core with non-linear sharpening)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Last-chance bin: heavily favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a brand-new bin unless it's necessary or the fit is bad
    if bin_residual == bin_capacity {
        let necessity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // allow new bin when existing fits would leave large dead space
        let poor_fit = if post_residual < item_size / 2 { 1.0 } else { 0.0 };
        score += 25.0 * (1.0 - necessity) * (1.0 - poor_fit) - 30.0 * (necessity + poor_fit).min(1.0);
        // early in the stream, new bins are cheap; later they are costly
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * progress;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual > next_item_size {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty for wasting residual
            score += 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Prefer bins whose residual is below the mean (consolidate small leftovers)
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // Slight preference for bins with many fitting alternatives being skipped
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Dead-space avoidance: residual too small for any plausible future item
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items - 1) as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = 1.0 - norm_pr;

    // Base: prefer tight fits, scaled non-linearly with stream progress.
    let mut score = pr * (1.0 + 0.8 * fill * fill);

    // Smooth polynomial coupling of post_residual with progress:
    // early on, residual waste matters less; late, it matters much more.
    let coupling = 1.0 + progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score *= coupling;

    // Reward bins whose leftover matches the lookahead item (smooth kernel).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 6.0 * (1.0 - gap / cap).max(0.0) * (1.0 - gap / cap);
    }

    // Last-chance bin bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Mild penalty for spreading across many bins; favor consolidation
    // when mean residual is low (bins nearly full).
    let mean_gap = (mean_residual - pr).abs();
    score += 0.05 * mean_gap;

    // New-bin candidate: penalize opening a fresh bin unless existing
    // fits are bad; smooth ramp with how much space the item leaves.
    if bin_residual == bin_capacity {
        score = cap * (1.1 + 0.4 * progress) - 8.0 * fill;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post residual (capacity fractions) ----
    // Class residuals into eighths of capacity: dead space near a fraction
    // boundary is more likely reusable by a future item.
    let cap = bin_capacity as f64;
    let eighth = cap / 8.0;
    let pr = post_residual as f64;
    let class = (pr / eighth).floor(); // 0..=8
    let class_center = class * eighth + eighth / 2.0;
    let dist_to_class = (pr - class_center).abs();

    // Reward being close to a harmonic class center (predictable dead space)
    score -= 3.0 * (1.0 - dist_to_class / (eighth / 2.0)).max(0.0);

    // ---- Exact / near-exact fit bonus ----
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual <= 10 {
        score -= 40.0; // tiny unusable sliver => effectively perfect
    } else if post_residual <= 20 {
        score -= 20.0;
    }

    // ---- Modulo arithmetic on post_residual ----
    // Residuals divisible by small harmonics (10, 20, 25, 50) are reusable.
    let pr_u = post_residual;
    if pr_u > 0 {
        if pr_u % 10 == 0 { score -= 8.0; }
        if pr_u % 20 == 0 { score -= 6.0; }
        if pr_u % 25 == 0 { score -= 6.0; }
        if pr_u % 50 == 0 { score -= 10.0; }
    }

    // ---- Lookahead pairing (k=2) ----
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0; // next item closes this bin exactly
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 { score -= 25.0; } else { score -= (15.0 * next_item_size as f64 / cap).min(12.0); }
        } else {
            // next item cannot use this bin's remainder: penalize large leftover
            score += 0.15 * (post_residual as f64 - (next_item_size as f64 % cap).min(pr));
        }
    } else {
        // last item: strongly prefer closing bins
        score -= 30.0 * (1.0 - pr / cap);
    }

    // ---- Last-chance bin ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0; // avoid opening a new bin when this is the only fit
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; scale with how full the fleet is.
        let base = 45.0 + 10.0 * (open_bins_count as f64).sqrt();
        // If item leaves a nice harmonic remainder in a fresh bin, discount.
        let fresh_bonus = if item_size % 10 == 0 { 8.0 } else { 0.0 };
        score = base - fresh_bonus;
        // Late in the stream, opening new bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    } else {
        // Existing bin: reward using bins below the mean residual (balancing).
        score += 0.5 * (mean_residual - pr) * 0.1;
    }

    // ---- Integer-division threshold tiers on post_residual ----
    let tier = pr_u / 15; // harmonic buckets of 15
    score -= tier as f64 * 1.5; // larger usable remainder => slightly better

    // ---- Mild penalty for over-fragmenting the fleet ----
    score += 0.3 * open_bins_count as f64 / (total_items.max(1) as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Dead-space penalty: small unusable gaps are worse than large ones.
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += (10.0 - pr) * 8.0; // gap of 1..9 is nearly dead space
        } else if pr < 25.0 {
            score += (25.0 - pr) * 1.5; // moderately wasteful
        }
        // Reward gaps that can still host the smallest plausible item later.
        if pr >= 10.0 {
            score -= 5.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; penalize small leftovers more.
            let lost = next_item_size - post_residual;
            score += lost as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.2;

    // Mean residual coupling: prefer bins whose residual is below average (tighter packs).
    score += (mean_residual - bin_residual as f64).max(-50.0) * 0.2;

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., this empty bin must beat bad fits, but not good fits).
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin anyway
        }
    }

    // Slight early-stream conservatism: keep bins open early, merge later.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += (1.0 - progress) * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect 2-step match: next item exactly fills post_residual -> strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - gap / cap);
        // Next item fits tightly after this placement
        if gap <= 10.0 {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here afterwards: penalize proportionally to wasted potential
        score += 0.15 * (next_item_size as f64);
    }

    // Reward tight fits relative to current residual (small post_residual is good).
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tightness * tightness;

    // Penalize leaving dead space far from mean residual (fragmentation).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Late in stream, consolidate into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (post_residual as f64 / cap);

    // New-bin candidate: neutral-ish baseline, only attractive when no tight fit exists.
    if bin_residual == bin_capacity {
        score += 45.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post-residual) with non-linear shaping.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize large post-residuals that are unlikely to be reusable:
    // dead space is worst when it's small-but-not-tiny (e.g. 1..=15).
    if post_residual > 0 && post_residual < 20 {
        score += 12.0 * (20.0 - post_residual as f64) / 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, heavily favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: reward leaving space exactly usable by the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0; // perfect chain fit
        } else if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // residual too small for next item: mild penalty scaled by waste
            score += 4.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0));
        }
    }

    // Global state: if many bins are open with large mean residual, prefer
    // consolidating into existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins have plenty of room
        // and late in the stream.
        let crowding = (open_bins_count as f64) / (open_bins_count as f64 + 3.0);
        score += 8.0 + 14.0 * crowding * (0.5 + 0.5 * progress) + 0.05 * mean_residual;
    } else {
        // Favor bins whose residual is below mean (fill the emptier-relative ones less;
        // actually prefer bins closer to being filled: residual below mean is good).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
        // Early stream: slight preference to spread items to build flexible bins.
        score += 4.0 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64);
    }

    // Mild penalty for very large item into nearly-empty open bin (waste of a good bin).
    if item_size as f64 > 0.8 * bin_capacity as f64 && bin_residual as f64 > 0.9 * bin_capacity as f64 && bin_residual != bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.35 * progress * progress);

    // Reward tight fits: strongly penalize when post_residual is small relative to item
    score -= (cap - pr) * (it / cap) * 0.25;

    // Non-linear penalty for awkward residuals (mid-range dead space)
    let mid = 0.5 * cap;
    score += 0.15 * (pr - mid) * (pr - mid) / cap;

    // Lookahead: reward bins whose post_residual can host the next item
    if nx > 0.0 && pr >= nx {
        score -= 6.0 * (nx / cap) * (1.0 - pr / cap);
    } else if nx > 0.0 && pr > 0.0 {
        score += 4.0 * (nx / cap);
    }

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize opening new bins, especially early with many open bins
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * (open_bins_count as f64).sqrt() + 8.0 * progress;
    }

    // Mild preference for bins deviating favorably from mean residual
    score -= 0.05 * (mean_residual - pr);

    // Small fill-rate bonus
    score -= 0.1 * ((cap - pr) / cap) * ((cap - pr) / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: classify dead space into
    // modulo classes relative to the smallest item size class (10).
    let class = post_residual / 10; // integer-division threshold classes
    match class {
        0 => score -= 40.0,          // near-perfect fill (residual < 10): excellent
        1 => score -= 15.0,          // residual 10..19: can host a small item
        2 => score -= 5.0,           // residual 20..29
        3 => score += 0.0,           // neutral
        4 => score += 5.0,           // residual 40..49: awkward gap
        5 => score += 10.0,          // residual 50..59
        _ => score += 15.0,          // large leftover: bin was underused
    }

    // Modulo-10 harmonic bonus: residuals that are exact multiples of 10
    // align with the classic item-size grid, making future packing easier.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: reward if the next item fits the post residual exactly
    // or within one harmonic class.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect two-step chain
        } else if next_item_size <= post_residual {
            score -= 12.0;
            // extra reward when the chained post-residual is again small
            let chained = post_residual - next_item_size;
            if chained < 10 {
                score -= 10.0;
            }
        } else {
            // next item cannot use this residual: penalize proportionally
            let overflow = (next_item_size - post_residual) as f64;
            score += (overflow / 40.0).min(10.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral-ish baseline. It should only win when no open
    // bin offers a decent fit, so give it a mild penalty that tight fits can beat.
    if bin_residual == bin_capacity {
        score = 55.0;
        // early in the stream, opening bins is cheap and useful
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // if many bins are open already, discourage spreading
        score += open_bins_count as f64 * 0.5;
        // if next item is large, a fresh bin is attractive
        if next_item_size >= 60 {
            score -= 8.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a tight bin worth consuming; if far above, it is loose.
    let diff = mean_residual - bin_residual as f64;
    score += (diff * 0.05).clamp(-6.0, 6.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving residuals that can accommodate common future item sizes.
    if post_residual >= 10 {
        score -= 8.0;
    }

    // Penalize wasting a large residual on a small item when gap becomes awkward.
    if post_residual > 0 && post_residual < item_size as f64 * 0.5 {
        score += 10.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && post_residual as u32 >= next_item_size {
        score -= 15.0;
    }
    // If next item cannot fit in post residual, mild penalty (it must go elsewhere).
    if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        score += 5.0;
    }

    // Open-bins pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current placement is terrible.
    if bin_residual == bin_capacity {
        score += 35.0;
        // But if item is large relative to capacity, opening new bin is fine.
        if item_size as f64 > bin_capacity as f64 * 0.6 {
            score -= 20.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably (tighter than mean).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Progress pressure: as stream advances, tighten packing (favor fuller bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: item followed exactly by next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if post_residual > next_item_size {
            // Next item fits too: reward tight coupling.
            let slack = (post_residual - next_item_size) as f64;
            score -= (1.0 - slack / bin_capacity as f64) * 60.0;
        } else {
            // Next item cannot fit: penalize leftover dead space, worse when close-but-unusable.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    } else {
        // Last item: pure tightness fit.
        score -= (1.0 - post_residual as f64 / bin_capacity as f64) * 50.0;
    }

    // Prefer bins with residual already below average (consolidating waste).
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when nothing fits well;
    // penalize opening new bins early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 120.0 + 200.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 60.0; // big next item makes a fresh bin more sensible
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fits
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin wastes residual; penalize heavily unless no good fit exists.
        // If an open bin fits with small post_residual, discourage new bin.
        let waste = bin_capacity as f64; // full residual unused for now
        let desperation = if fitting_bins_count == 0 {
            0.0 // no alternative; new bin is fine
        } else {
            1.0
        };
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Late in stream, prefer consolidating into existing bins more strongly.
        let time_pressure = 40.0 + 60.0 * progress;
        score += desperation * time_pressure;
        // If item nearly fills a fresh bin perfectly, opening is attractive.
        let perfect = (bin_capacity - item_size) as f64;
        score -= (bin_capacity as f64 - perfect) * 0.5;
        let _ = waste;
        return score;
    }

    // Reward perfect fills
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 80.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    }

    // Penalize dead space that no future item can plausibly use.
    // Small residuals (<10, min item size) are dead weight.
    if post_residual < 10 && post_residual > 0 {
        score += 15.0; // already penalized via base, add a nudge but tight bins are good
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here regardless; mild penalty for wasting space now.
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
        // Extra reward if fit is decent.
        if post_residual <= 20 {
            score -= 40.0;
        }
    }

    // Global state coupling: many open bins with high mean residual ->
    // prefer consolidation into bins below mean residual (tighter bins).
    if open_bins_count > 1 {
        let dev = mean_residual - bin_residual as f64;
        // Positive dev means this bin has less residual than average (tighter) -> good.
        score -= 0.3 * dev;
        // Encourage closing out bins when many are open.
        if post_residual <= 15 {
            score -= 10.0 * (open_bins_count as f64).sqrt();
        }
    }

    // Time horizon: early in stream, slightly more willing to leave slack
    // (future items may fill it); late in stream, prefer tight packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0 * fit_ratio;
    score -= progress * 10.0 * fit_ratio;

    // Mild penalty when many bins fit, to spread preference toward best fits only.
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;
    let nxt = next_item_size as f64 / cap;

    // Base: quadratic penalty on wasted post-residual (dead space)
    let mut score = norm_pr * norm_pr * cap + norm_pr * 10.0;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 + progress) * 8.0;

    // Non-linear coupling: post_residual vs lookahead item size.
    // If next item fits in post_residual, reward; smooth polynomial interaction.
    let compat = if nxt > 0.0 {
        let x = (nxt - norm_pr) / cap; // negative when next fits
        -x * x * cap + x * 5.0
    } else { 0.0 };
    score += compat * (1.0 + progress);

    // Penalize bins far below mean residual (avoid scattering)
    score += ((pr - mean_residual) / cap).powi(2) * 4.0;

    // Last-chance bonus: strong reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln() * 0.5;

    // Slight preference for fuller bins overall (cubic in fill ratio)
    let fill = 1.0 - norm_pr;
    score -= fill * fill * fill * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: how well the leftover divides the capacity.
    let pr = post_residual;
    if pr > 0 {
        // Residuals that are exact capacity fractions are highly reusable.
        for &d in &[2u32, 3, 4, 5, 6, 8, 10, 20] {
            if pr == bin_capacity / d {
                score -= 18.0 * (d as f64).ln();
                break;
            }
        }
        // Integer-division class: large remainders of pr against common item sizes.
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if pr == half || pr == third || pr == quarter {
            score -= 12.0;
        }
        // Dead space penalty: tiny leftovers that few items can use.
        if pr < bin_capacity / 10 {
            score += 25.0 + (bin_capacity / 10 - pr) as f64;
        }
    } else {
        // Perfect closure: bin exactly filled.
        score -= 40.0;
    }

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 && next_item_size <= pr {
        let slack_after_next = pr - next_item_size;
        // Favor bins where next item also fits snugly.
        score -= 8.0 + (pr - next_item_size) as f64 * 0.05;
        if slack_after_next == 0 {
            score -= 15.0;
        }
    } else if next_item_size > pr {
        // This bin's leftover will likely be dead space for the next item.
        score += 6.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / cap_f;
    if fill_ratio > 0.7 {
        score -= 10.0 * fill_ratio;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = cap_f * 0.9;
        // If many bins fit the item, discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 20.0 * fitting_bins_count as f64;
        }
        // Late in the stream, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If next item is large and current bins are fragmented, new bin is fine.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 15.0;
        }
    }

    // Mild preference for bins below mean residual (balancing fragmentation).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for typical future items are wasted.
    // Treat gaps below a "dead zone" threshold as pure loss, with superlinear penalty.
    let dead_threshold = 10.0f64.min(mean_residual * 0.5).max(1.0);
    if (post_residual as f64) < dead_threshold {
        // Nearly full bin is actually great, but a tiny unusable sliver is worthless:
        // reward tight packing strongly instead of linearly.
        score -= 25.0 + 0.5 * (bin_residual as f64);
    } else {
        // Superlinear penalty on leftover space to prefer tight fits.
        let pr = post_residual as f64;
        score += 0.02 * pr * pr;
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // Penalize if next item cannot use the leftover gap (dead space likely).
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 0.3 * (post_residual as f64);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.2 * item_size as f64;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into fuller bins
    // (penalize leaving lots of residual when bin count is high).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += 0.05 * pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate (empty bin): make it attractive only when the current item
    // would leave a bad gap in existing bins or no bins fit well.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin; slightly worse than a perfect fit,
        // better than creating large unusable gaps.
        score = bin_capacity as f64 * 0.35 + 0.05 * open_bins_count as f64;
        // If item is small and some bin has a matching residual, discourage new bin.
        if fitting_bins_count > 0 && item_size <= mean_residual as u32 {
            score += 20.0;
        }
        // Late in the stream with few bins fitting, opening fresh is fine.
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Lookahead: reward exact/near-exact match between post_residual and next item.
    if next_item_size > 0 && (next_item_size as f64) <= score {
        let gap = score - next_item_size as f64;
        score -= 30.0 * (1.0 - gap / cap) - 20.0 * (gap / cap);
    }

    // Penalize residuals that are large relative to mean residual (wasting space).
    score += 0.5 * (score - mean_residual);

    // Normalize by capacity slightly.
    score += 0.1 * (score * score / cap);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Late in the stream, prefer tightening existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / cap);

    // Slight preference for opening new bins early when fits are poor.
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Reward exact or near-exact fills heavily
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Penalize residual fragments that are unlikely to be useful
    // (dead space: too small for typical items but nonzero)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.1 * next_item_size as f64;
            // chain bonus: next item nearly fills the remainder too
            let chain_left = post_residual - next_item_size;
            if chain_left < 10 {
                score -= 6.0;
            }
        } else {
            // penalty grows with wasted opportunity relative to residual
            let gap = (next_item_size - post_residual) as f64;
            score += 0.05 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: prefer filling existing ones over spreading
    let crowding = open_bins_count as f64;
    score += 0.02 * crowding * (post_residual as f64 / bin_capacity as f64);

    // Global mean residual coupling: if this bin's residual is far below mean,
    // it is a "tight" bin; using it keeps mean residual high for future items
    let residual_diff = mean_residual - bin_residual as f64;
    score += 0.03 * residual_diff;

    // Time horizon: early in stream, be conservative (keep bins flexible);
    // late in stream, aggressively fill
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0 * tightness;
    score += (1.0 - progress) * 0.02 * post_residual as f64;

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        let mut new_bin_score = 55.0;
        // cheaper to open a new bin when few bins are open
        new_bin_score -= 2.0 * (open_bins_count.min(10) as f64);
        // if item is large, fresh bin is fine
        new_bin_score -= 0.1 * item_size as f64;
        // if this is the last item, opening a bin is fine
        if next_item_size == 0 {
            new_bin_score -= 30.0;
        }
        // late in stream, avoid opening new bins
        new_bin_score += 20.0 * progress;
        score = score.max(new_bin_score);
        score = new_bin_score.max(score.min(new_bin_score + 1e-9));
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core waste term, mildly super-linear so large residuals are punished more.
    let mut score = pr * (1.0 + 0.004 * pr);

    // Smooth progress coupling: as the stream advances, waste becomes costlier
    // (fewer chances to fill gaps later), so scale the waste term up.
    score *= 1.0 + 0.35 * progress * progress;

    // Lookahead: reward residuals that can host the next item (smooth coupling).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap >= 0.0 {
            // The next item fits into the would-be residual: strong reward,
            // tuned by how snugly it fits.
            score -= 18.0 * (1.0 - gap / cap) * (1.0 - 0.5 * progress);
        } else {
            // Residual too small for next item: smooth penalty for near-misses.
            let miss = (-gap / cap).min(1.0);
            score += 10.0 * miss * (1.0 - miss);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin for a small leftover.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Prefer bins that are already partially filled relative to the fleet mean:
    // consolidating into tighter bins smooths residual distribution.
    let norm = bin_residual as f64 / cap;
    let mean_norm = mean_residual / cap;
    score += 8.0 * (norm - mean_norm);

    // New-bin candidate: baseline score so it only wins when open bins have
    // large residuals (poor fits). Slight bias toward opening bins early.
    if bin_residual == bin_capacity {
        score = cap * (1.0 + 0.004 * cap) * (1.0 + 0.35 * progress * progress);
        score -= 12.0 * (1.0 - progress);
        // If nothing fits well elsewhere, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), scaled.
    score = (post_residual as f64).powf(1.35);

    // Dead-space penalty: residual that is too small to hold any item (min size 1..small).
    // Classify post_residual into harmonic classes via integer division thresholds.
    let pr = post_residual as u32;
    let class = pr / 10; // harmonic class of usable space
    match class {
        0 => score += 40.0,          // 0-9: nearly dead space, heavy penalty
        1 => score += 15.0,          // 10-19: only fits tiny items
        2 => score += 6.0,           // 20-29
        3 => score += 2.0,           // 30-39
        4 => score += 0.0,           // 40-49: sweet spot for mid items
        _ => {}                      // large residual: neutral (base term dominates)
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = pr - next_item_size;
        score -= 12.0 - (slack as f64 * 0.15); // exact follow-up fit gets biggest reward
    }
    // If next item does NOT fit in post_residual, mildly penalize blocking the chain.
    if next_item_size > 0 && next_item_size > pr {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: opening a new bin should be costly unless all
    // open bins would create dead space (class 0 or 1) or many bins are open.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.95 + open_bins_count as f64 * 0.5;
        // Allow new bin when existing placements would waste heavily.
        if class <= 1 && fitting_bins_count >= 1 {
            score -= 25.0;
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    }

    // Mild preference to balance residuals across bins (avoid many nearly-full + one huge).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever host a plausible item
    // (min item size 1, but practically items <= 100) are pure waste.
    // Penalize unusable gaps super-linearly.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // and discourage opening new ones.
    score += open_bins_count as f64 * 3.0;

    // New-bin candidate: empty bin. Penalize it so it only wins when no open bin
    // offers an acceptable fit (i.e. open bins have bad dead-space scores).
    if bin_residual == bin_capacity {
        score += 45.0 + open_bins_count as f64 * 5.0;
        // If nothing else fits, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item would fit into the post_residual,
    // reward leaving that exact gap; penalize if the gap is just barely too small.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual <= 10 {
            score += 12.0;
        }
    }

    // Mean residual alignment: bins deviating far from the mean residual are
    // less attractive (keeps the bin pool homogeneous).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Mild stream-progression term: later in the stream, waste matters more.
    if total_items > 0 {
        score += (step_index as f64 / total_items as f64) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, penalize large dead space quadratically.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 6.0 * tightness * (item_size as f64) / cap;

    // 2-step lookahead: reward if the next item fits the post residual exactly/well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if nxt <= post {
            let gap = (post - nxt) as f64;
            // Perfect follow-up match strongly rewarded.
            score -= 14.0 * (1.0 - gap / cap);
            if gap == 0.0 {
                score -= 10.0;
            }
        } else {
            // Next item cannot use this bin's remaining space: penalize wasted residual.
            score += 0.35 * post;
        }
    } else {
        // Last item: only zero-residual matters.
        if post_residual == 0 {
            score -= 20.0;
        }
    }

    // Relative to mean residual: bins with more residual than average are better targets.
    score -= 1.2 * ((bin_residual as f64) - mean_residual);

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (i.e., many bins but few fitting, or residual too small for lookahead chain).
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 {
            30.0
        } else {
            let avg_fit = (open_bins_count as f64).max(1.0);
            -4.0 * (fitting_bins_count as f64 / avg_fit)
        };
        let lookahead_ok = next_item_size > 0 && next_item_size <= item_size;
        let horizon = step_index as f64 / total_items.max(1) as f64;
        // Early stream: opening bins is cheap; late stream: avoid fragmentation.
        score = 10.0 + pressure * (1.0 - 0.5 * horizon);
        if lookahead_ok {
            score += 6.0; // prefer existing bins when the chain can continue
        }
        if post_residual == 0 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post_residual)
    score -= (bin_capacity as f64 - post_residual as f64) * 1.5;

    // Penalize large post_residual relative to capacity (dead space)
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score += dead_frac * dead_frac * 30.0;

    // Lookahead coupling: if the next item fits exactly in the post_residual, reward heavily
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_gap = (post_residual - next_item_size) as f64;
            score -= (1.0 - next_gap / bin_capacity as f64) * 20.0;
        } else {
            // next item won't fit here: mild penalty if we waste post_residual
            score += (post_residual as f64 - (bin_capacity as f64 - next_item_size as f64)).abs() * 0.1;
        }
    } else {
        // last item: prefer any bin, minimize post_residual
        score -= 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize opening new bins when many open bins have residual space
    if bin_residual == bin_capacity && bin_capacity >= item_size {
        // new-bin candidate: penalize unless current open bins are badly fragmented
        let fragmentation = if open_bins_count > 0 {
            (mean_residual - (bin_capacity as f64 - item_size as f64)).abs()
        } else { 0.0 };
        score += 25.0 - fragmentation.min(25.0);
        // early stream: opening bins is fine
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
    }

    // Reward using bins with residual close to mean (balance)
    score -= (bin_residual as f64 - mean_residual).abs() * -0.05;

    // Slight preference for fewer open bins
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr;

    // Smooth non-linear penalty on leftover space: large residuals are wasted potential.
    let norm_pr = pr / cap;
    let waste = norm_pr * norm_pr * (1.0 + 3.0 * progress) * cap * 0.5;

    // Reward tight fits more strongly as stream progresses.
    let tight_fit = (1.0 - norm_pr).powi(3) * cap * (0.4 + 0.6 * progress);

    // Dead-space coupling: residual that cannot fit the next item is likely lost.
    let dead = if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        (gap / cap).powi(2) * cap * (0.3 + 0.7 * progress)
    } else {
        0.0
    };

    // Last-chance bonus: strongly prefer using the only fitting bin.
    let last_chance = if fitting_bins_count == 1 { cap * 1.5 } else { 0.0 };

    // Mild penalty for scattering across many open bins relative to mean residual.
    let scatter = if open_bins_count > 1 {
        (pr - mean_residual).abs() * 0.05 * (open_bins_count as f64).ln()
    } else {
        0.0
    };

    // Slight preference for keeping residual aligned with typical future item sizes.
    let align = if next_item_size > 0 && pr >= next_item_size as f64 {
        -0.2 * (pr - next_item_size as f64).min(20.0)
    } else {
        0.0
    };

    base + waste - tight_fit + dead - last_chance + scatter + align
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: which eighth of capacity it occupies
    let item_class = item_size / 13;
    let next_class = next_item_size / 13;
    let post_class = post_residual / 13;

    // Reward perfect and near-perfect fits (post_residual in low harmonic classes)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_class == 0 {
        score -= 20.0;
    }

    // Penalize dead space that no plausible future item can use.
    // Smallest item is 1, but practical unusability threshold couples with next item.
    if post_residual > 0 && next_item_size > post_residual {
        // next item cannot use this leftover space: leftover becomes dead
        score += (post_residual as f64) * 0.9;
    }

    // Lookahead coupling: if next item exactly fills the post residual, big reward
    if next_item_size == post_residual && post_residual > 0 {
        score -= 55.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits into the leftover: mild reward scaled by tightness
        let tightness = (next_item_size as f64) / (post_residual as f64);
        score -= 25.0 * tightness;
    }

    // Harmonic class matching: leftover class equal to next item class is promising
    if post_residual >= next_item_size && post_class == next_class && next_item_size > 0 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so we prefer
    // reusing open bins with good fits, but it stays competitive when fits are bad.
    if bin_residual == bin_capacity {
        score += 12.0;
        // If no open bin fits well (post residual large relative to capacity),
        // relax the penalty so opening a fresh bin is attractive.
        if post_residual as f64 > 0.55 * bin_capacity as f64 {
            score -= 30.0;
        }
        // Late in the stream, opening fresh bins is cheaper than fragmenting
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 {
            score -= 8.0;
        }
    }

    // Discourage spreading: if many bins are open and this bin is far below mean
    // residual, placing here fragments capacity unevenly.
    if bin_residual as f64 > mean_residual + 25.0 && open_bins_count > 2 {
        score += 6.0;
    }

    // Prefer keeping a buffer of medium residuals for medium items:
    // penalize leaving residuals in awkward harmonic classes (e.g. 20..30 zone)
    if post_residual >= 20 && post_residual <= 30 {
        score += 8.0;
    }

    // Modulo coupling: post_residual divisible into clean quarters is reusable
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // accept another item (min item size = 1) are pure waste; but gaps in
    // the "awkward zone" (small but nonzero) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // nearly-unusable sliver
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual == 0 {
        score -= 30.0; // perfect closure: reward strongly
    }

    // Reward tight fits relative to bin capacity.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 12.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: discourage spreading when many
    // bins are already open; encourage consolidation.
    score += (open_bins_count as f64) * 1.5;

    // Prefer bins whose residual is already below the mean (denser bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Lookahead: if the next item would fit exactly in the post residual,
    // reward this placement (sets up a perfect closure next step).
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the known next item: penalize.
        score += 10.0;
    }

    // New-bin candidate: only attractive when no open bin fits well or
    // open-bin pressure is low; otherwise keep it expensive.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64) * 2.0;
        // If stream is near its end, opening a bin is cheaper than waste.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.9 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact-ish matches between post_residual and next item (2-step lookahead).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect lookahead match: strongly subtract.
        if (post_residual as i64) == (next_item_size as i64) {
            score -= 30.0;
        } else if gap <= 5.0 {
            score -= (6.0 - gap) * 2.5;
        } else if gap > 40.0 {
            // Next item leaves a huge leftover again -> penalize wasteful fit.
            score += (gap - 40.0) * 0.3;
        }
        // Bonus if after placing next item residual would be tiny (chain fit).
        if next_item_size <= post_residual {
            let chained = post_residual as u32 - next_item_size;
            if chained <= 3 {
                score -= 12.0;
            }
        }
    } else {
        // Last item: minimize leftover hard.
        score += post_residual as f64 * 0.5;
    }

    // Compare against mean residual across open bins.
    let res = post_residual as f64;
    if res < mean_residual - 15.0 {
        // Creates much less residual than average -> good compaction.
        score -= (mean_residual - res) * 0.4;
    } else if res > mean_residual + 15.0 {
        // Worse than average fit -> penalize.
        score += (res - mean_residual) * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + (item_size as f64 / bin_capacity as f64) * 10.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current item
    // is large and would leave big fragmentation elsewhere.
    if bin_residual == bin_capacity {
        let tight_fit_elsewhere = fitting_bins_count >= 1 && (bin_residual - item_size) < 5;
        let base = 45.0 + item_size as f64 * 0.35;
        score += if tight_fit_elsewhere { 10.0 } else { base };
        // Early in stream, prefer filling existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 15.0;
    }

    // Mild pressure to keep number of open bins low.
    score += open_bins_count as f64 * 0.05;

    // Prefer near-perfect fills.
    if post_residual <= 2 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 3.0 * tightness * tightness * cap * 0.1;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits the post residual, big reward.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 15.0 + 0.25 * (next_item_size as f64);
        } else {
            // Waste if leftover can't host next item; scale by how close it came.
            let gap = (next_item_size as i64 - post_residual as i64) as f64;
            score += 0.15 * gap.min(60.0);
        }
    } else {
        // Last item: strongly prefer zero waste.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strong penalty for opening a new bin when only this bin fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        score = 12.0 + 0.4 * (post_residual as f64);
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a bin
        }
        // Early in stream, opening fresh bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 5.0 * (1.0 - progress);
        // If mean residual across open bins is small, new bin is attractive.
        score -= 0.2 * mean_residual.max(0.0).min(50.0);
    }

    // Fragmentation pressure: many open bins with high mean residual -> prefer filling.
    let frag = open_bins_count as f64 * (mean_residual / cap);
    score += 0.05 * frag;

    // Mild preference for bins with residual close to item (minimal waste).
    let waste_ratio = (bin_residual - item_size) as f64 / cap;
    score += 10.0 * waste_ratio * waste_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: prefer tight fits, penalized smoothly by stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear coupling: squared normalized post-residual interaction with progress.
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward low dead space relative to mean residual of open bins.
    score -= 0.35 * (mean_residual - pr);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: if next item fits exactly in post-residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score -= 10.0 * (1.0 - gap / cap).max(0.0);
        // Penalize if post-residual is slightly too small for next item (near-miss waste).
        if pr < nxt && pr > 0.0 {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for spreading across many bins when residuals are plentiful.
    score += 0.6 * open_bins_count as f64 * (1.0 - progress) * norm_pr;

    // New-bin candidate: keep it viable but not dominant unless fits are poor.
    if bin_residual == bin_capacity {
        score += 5.0 - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that fall into
    // "usable" classes (large chunks divisible into common item sizes).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity remaining after placement.
    let frac = pr / cap;

    // Modulo-based harmonic classes: residuals that are multiples of 10 or 25
    // pair well with typical item sizes; reward exact class matches.
    let mod10 = post_residual % 10;
    let mod25 = post_residual % 25;
    if mod10 == 0 {
        score -= 6.0;
    } else if mod10 == 5 {
        score -= 2.0;
    } else {
        score += mod10 as f64 * 0.4;
    }
    if mod25 == 0 {
        score -= 4.0;
    }

    // Perfect fit: zero residual is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead-space penalty: tiny unusable residuals (below min item size 1..10 band).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Integer-division thresholds: residual bucket via division by 20.
    let bucket = post_residual / 20;
    score -= bucket as f64 * 1.5;

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score -= (1.0 - gap as f64 / cap) * 10.0;
            if gap < 10 {
                score += 8.0; // would create near-dead space after next item
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, penalize opening a new bin
    // alternative by rewarding this placement.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Discourage excessive open bins early; encourage packing into existing bins
    // as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;
    score += open_bins_count as f64 * 0.3;

    // Mean-residual coupling: prefer bins whose residual is below mean
    // (tighter packing first).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.0;
    }

    // New-bin candidate: make empty bins less attractive unless the item is large
    // relative to open-bin residuals (large items deserve fresh space).
    if bin_residual == bin_capacity {
        let large_item_bonus = if item_size as f64 > 0.6 * cap { 8.0 } else { 0.0 };
        score += 20.0 - large_item_bonus;
    }

    // Mild non-linear shaping on fill fraction.
    score -= (1.0 - frac).powi(2) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be usable
    // later are heavily penalized (dead space), while moderate residuals are fine.
    let pr = post_residual as f64;
    let dead_threshold = 10.0_f64.min(bin_capacity as f64 * 0.10);
    if post_residual > 0 && pr <= dead_threshold {
        // Pure dead space: full capacity wasted for future items.
        score += (dead_threshold - pr) * 6.0 + 25.0;
    }

    // Reward very tight fits (post_residual near zero is ideal only if exactly 0).
    if post_residual == 0 {
        score -= 30.0;
    }

    // Coupling with next item lookahead: if the next item fits exactly into
    // post_residual, strongly favor this bin; if it can't fit, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.15;
        } else {
            score -= (post_residual - next_item_size) as f64 * 0.10;
        }
    }

    // Open-bin pressure: discourage spreading across many open bins when
    // alternatives exist; encourage consolidation.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when the fit into open bins is poor
    // (large post_residual relative to capacity) or no real alternative exists.
    if bin_residual == bin_capacity {
        let waste = pr; // empty bin: post_residual == capacity - item_size
        // Baseline penalty so a new bin is chosen only when open-bin fits are bad.
        score += 35.0 + open_bins_count as f64 * 2.0;
        // A fresh bin is more attractive if it leaves a large usable residual
        // (i.e., item was small) — but never if it creates a mid-size gap.
        if waste >= 20.0 {
            score -= 10.0;
        }
    }

    // Slight preference for bins whose residual deviates favorably from the mean:
    // prefer bins with below-average residual (tighter bins) to consolidate.
    score += (mean_residual - bin_residual as f64) * 0.20;

    // Mild stream-position term: late in the stream, be more conservative
    // about opening bins (consolidation matters more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits the leftover space.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 + 0.5 * slack;
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize dead space relative to mean residual.
        let dead = post_residual as f64;
        let rel = dead / (mean_residual + 1.0);
        score += 10.0 + 15.0 * rel.min(3.0);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: make it attractive only if current bin fits are poor.
    if bin_residual == bin_capacity {
        score = 20.0 + post_residual as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
        if fitting_bins_count <= 1 && bin_residual < bin_capacity + 1 {
            // never trigger (this is the new-bin call itself)
        }
    }

    // Prefer filling bins with larger residual relative to mean (waste reduction).
    score += 0.1 * (post_residual as f64 - mean_residual).max(0.0);

    // Slight early-stream preference to open bins to build diversity.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post_residual (nonlinear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Dead-space penalty: leftover space too small for the smallest possible item.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when existing fits are poor or crowded.
    if bin_residual == bin_capacity {
        score += 8.0; // base reluctance to open new bins
        if fitting_bins_count == 0 {
            score -= 40.0;
        } else if fitting_bins_count == 1 {
            score += 12.0; // don't steal the last-chance bin's job unless lookahead says otherwise
            if next_item_size > 0 && next_item_size <= bin_residual {
                score -= 10.0;
            }
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        // Many open bins: discourage opening more.
        score += 1.5 * open_bins_count as f64;
        // High mean residual among open bins: opening a new bin is wasteful.
        score += 0.3 * mean_residual;
    }

    // Mild preference for fuller bins relative to the fleet average.
    score += 0.2 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tight_fit = 1.0 - pr / cap; // high when item nearly fills bin
    let tight_sq = tight_fit * tight_fit;

    let mut score = pr;

    // Reward tight fits with a smooth quadratic bonus
    score -= 12.0 * tight_sq * cap * 0.1;

    // Penalize leaving residuals that match the next item poorly
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let gap = (pr - next).abs();
        let gap_norm = gap / cap;
        score += 8.0 * gap_norm * gap_norm * cap;
        // Smooth reward if next item fits snugly into post-residual
        let snug = 1.0 - gap_norm;
        score -= 6.0 * snug * snug * (pr / cap);
    }

    // Stream-progress coupling: early on, mildly prefer consolidating into open bins;
    // late in the stream, tighten preference for minimizing residual
    let prog_coupling = progress * progress * (1.0 - progress) * 4.0;
    score -= prog_coupling * (cap - pr) * 0.05;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize scattering across many open bins when mean residual is large
    let scatter = (open_bins_count as f64).ln1p() * (mean_residual / cap);
    score += 3.0 * scatter;

    // New-bin candidate: make it slightly less attractive unless residual would be large
    if bin_residual == bin_capacity {
        score += 4.0 + 0.05 * (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: how "usable" the leftover is.
    // Classes keyed on capacity fractions (1/4, 1/3, 1/2) and modulo structure.
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;
    let quarter = cap_f / 4.0;
    let third = cap_f / 3.0;
    let half = cap_f / 2.0;

    // Dead-space penalty: residuals that are too small for any realistic item
    // (min item size 1, but typical items > 10) are wasted.
    if post_residual < 10 {
        score += 45.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Harmonic bonus: residuals near capacity fractions pair well with future items.
    let dist_q = (post - quarter).abs();
    let dist_t = (post - third).abs();
    let dist_h = (post - half).abs();
    let best_harmonic = dist_q.min(dist_t).min(dist_h);
    score -= (cap_f - best_harmonic) * 0.35;

    // Modulo classes on post_residual: multiples of 10 align with common item sizes.
    let mod10 = post_residual % 10;
    if mod10 == 0 {
        score -= 8.0;
    } else if mod10 >= 7 {
        score += 3.0 + (mod10 - 6) as f64 * 2.5;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly reward (perfect 2-chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 - slack * 0.4;
            // next item leaves another harmonic residual? extra reward.
            let post2 = post_residual - next_item_size;
            if post2 % 10 == 0 && post2 > 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot use this bin's leftover; penalize by mismatch.
            score += ((next_item_size - post_residual) as f64).min(30.0) * 0.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral-ish baseline, penalized when good fits exist,
    // rewarded when open bins are fragmented.
    if bin_residual == bin_capacity {
        score = cap_f * 0.55 + open_bins_count as f64 * 1.2;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 12.0; // big upcoming item: fresh bin useful
        }
        if mean_residual < quarter && open_bins_count > 2 {
            score -= 15.0; // fragmentation high, prefer opening new bin
        }
    }

    // Mild time decay: early in the stream, keep bins tighter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    // Penalize creating residual far above mean (wasteful spread).
    if post as f64 > mean_residual {
        score += (post - mean_residual) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = 10.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight fit bonus: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Penalize leaving a gap that exactly fits nothing useful (residual in 1..10 zone already covered),
    // but also penalize mid-range waste mildly.
    score += (post_residual as f64 / bin_capacity as f64) * 5.0;

    // Open bins pressure: with many open bins, prefer filling existing ones over spreading.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.8 * (0.5 + progress);

    // Mean residual coupling: if mean residual is low, keep bins tight.
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as u64) <= post_residual as u64 {
        score -= 12.0;
    }
    // If next item would leave this bin useless anyway, mild penalty.
    if next_item_size > 0 && post_residual > 0 && (next_item_size as f64) > post_residual as f64 {
        score += 3.0;
    }

    // New-bin candidate: opening a new bin should be costly unless current fit is terrible.
    if bin_residual == bin_capacity {
        // Base cost of a new bin, reduced when this bin is a last resort elsewhere.
        score = bin_capacity as f64 * 0.35 + open_bins_count as f64 * 0.5;
        if post_residual == 0 {
            score -= 10.0;
        }
        if item_size > 50 {
            score += 5.0; // large items in fresh bins are fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: item + next item exactly fill the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Next item fits into the residual: strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.5;
    }
    // Next item cannot use the residual: penalize dead space proportionally.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Compare residual against mean residual across open bins.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.25;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.25;
    }

    // Last chance: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only if no open bin fits well.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.1;
    }

    // Slight preference to fill bins more tightly early vs late in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: bonus proportional to fill ratio.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot fit a typical future item.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        score += 25.0 * dead;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 3.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Time horizon: early in the stream, be conservative with new bins;
    // late in the stream, allow tighter packing decisions.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - fit_ratio);

    // Many open bins with large mean residual: discourage spreading items
    // across bins; prefer filling the emptiest viable bin.
    if open_bins_count > 0 {
        let spread = (mean_residual - post_residual as f64).abs();
        score += 0.05 * spread * (open_bins_count as f64).sqrt();
    }

    // New-bin candidate: prefer opening a fresh bin only when current item
    // is large and no open bin is a good home.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 18.0 - 14.0 * pressure - 6.0 * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.6 * x * x) - 8.0 * x * (1.0 - x);

    // Smooth coupling with stream progress: early on, tolerate slack; later, punish it
    let progress_penalty = 12.0 * t * x * x * cap / 100.0;
    score += progress_penalty;

    // Reward tight fits via smooth sigmoid-like term on x
    let tight = (-((x - 0.05) * (x - 0.05)) * 80.0).exp();
    score -= 10.0 * tight;

    // Lookahead coupling: if next item fits in post residual, reward smoothly
    if next_item_size > 0 {
        let fits = if (next_item_size as f64) <= pr { 1.0 } else { 0.0 };
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= 6.0 * fits * (1.0 - gap) * (1.0 - 0.5 * t);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty for proliferating bins with large mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
