    // Integer-division thresholds: post_residual classes
    if pr == 0 {
        score -= 100.0; // perfect fit
    } else if pr < 10 {
        score += 15.0; // unusable sliver
    } else if pr >= 10 && pr <= 20 {
        score -= 6.0; // next small item can slot in
    }

    // Fraction of capacity wasted
    let waste_frac = pr as f64 / cap;
    score += waste_frac * waste_frac * 40.0;

    // Lookahead coupling: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 - slack * 0.15; // chain-friendly
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate: only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64;
        let tight = mean_residual / cap;
        // prefer opening a new bin when open bins are cramped or item is large
        score = 55.0 + item_size as f64 * 0.3 - tight * 30.0 - (fitting_bins_count == 0) as i32 as f64 * 60.0;
        // late in stream, reuse bins more aggressively
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        let _ = crowded;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for even the
    // smallest plausible item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Moderately small gaps are risky too.
    if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Reward tight fits (small absolute waste) super-linearly.
    let waste = post_residual as f64;
    score += 0.004 * waste * waste;

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; with few,
    // opening a new bin is cheaper so existing bins get mild preference.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.35 * (1.0 - progress);

    // If the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + slack);
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        // Next item would fit this bin now but not after placement -> penalty.
        score += 10.0;
    }

    // Mean residual coupling: bins far below mean residual are "loose";
    // prefer bins whose residual is closer to the item (efficient packing).
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * diff;

    // New-bin candidate: only attractive when no open bin fits well or
    // residuals are nearly exhausted.
    if bin_residual == bin_capacity {
        let bad_fit_penalty = if post_residual > 0 && post_residual < 10 { 0.0 } else { 0.0 };
        let _ = bad_fit_penalty;
        // Base cost of opening a bin, reduced when open bins are scarce or
        // stream is early (future items may need the space).
        let mut new_bin_cost = 55.0;
        new_bin_cost -= 30.0 * (1.0 - progress);
        new_bin_cost -= 2.0 * open_bins_count as f64;
        // If the current item leaves a tiny unusable gap in an existing bin,
        // opening a fresh bin becomes relatively better.
        if post_residual > 0 && post_residual < 10 {
            new_bin_cost -= 45.0;
        }
        // If item fills the new bin exactly, opening is great.
        if post_residual == 0 {
            new_bin_cost -= 60.0;
        }
        score += new_bin_cost.max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
