pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor minimal post residual (non-linear).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 12.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly or well in the post residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover; penalize proportionally to wasted space.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 20.0;
        // If several bins fit, opening a new bin is unattractive.
        if fitting_bins_count > 0 {
            score += 15.0 * (fitting_bins_count as f64).sqrt();
        }
        // Early in the stream, new bins are cheaper (future packing flexibility).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // If many open bins already have large residuals, prefer using them.
        if mean_residual > item_size as f64 * 1.5 {
            score += 8.0;
        }
        // Small item into a fresh bin wastes potential; penalize more for small items.
        score += 0.2 * (bin_capacity as f64 - item_size as f64);
    } else {
        // Reward placing into bins whose residual deviates from the mean (consolidation).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 0.05 * dev;
        // Slightly favor bins that will be nearly full after placement.
        let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        score -= 10.0 * fill * fill * fill;
    }

    // Global load balancing: many open bins -> prefer filling existing ones harder.
    if open_bins_count > 4 {
        score -= 0.5 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: wasted residual, with smooth non-linear polynomial coupling to progress.
    // Late in the stream, dead space is costlier, so weight grows smoothly.
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Reward tight fits (small post_residual relative to capacity) super-linearly.
    let tightness = 1.0 - pr / cap;
    score -= 12.0 * tightness * tightness * tightness;

    // Penalize leaving residuals that are "almost useful" (unusable dead space):
    // post_residual just below typical item sizes is bad; smooth quadratic trough.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = pr - n;
        // If next item fits exactly, big reward; if slightly too small, penalty.
        score += 0.35 * gap.abs() - 0.015 * gap * gap;
        if gap >= 0.0 && gap < 10.0 {
            score -= 6.0 * (1.0 - gap / 10.0);
        }
    }

    // Last-chance bin: strongly favor to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: prefer it only when no good fit exists.
    if bin_residual == bin_capacity {
        score = cap * (1.1 + 0.4 * progress) + 8.0 * open_bins_count as f64;
        if next_item_size > 0 && (bin_capacity as u32).saturating_sub(item_size) >= next_item_size {
            score -= 10.0;
        }
    }

    // Mild preference for bins already below mean residual (consolidating waste).
    score += 0.05 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Perfect and near-perfect fits: strong reward ----
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // ---- Harmonic classes: post_residual modulo structure ----
    // Residuals divisible by common item sizes (10/20/25/50) are reusable.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 5.0; }
        if pr % 50 == 0 { score -= 4.0; }
        // Odd tiny residuals (1..9, not class-aligned) are dead space.
        if pr < 10 && pr % 10 != 0 { score += 15.0; }
    }

    // ---- Lookahead coupling: does the next item fit the post residual? ----
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Chain fit: reward, scaled by tightness of the chain fit.
            let slack = (pr - next_item_size) as f64;
            score -= 25.0 - slack * 0.3;
            if (next_item_size as i64 - pr as i64).abs() % 10 == 0 {
                score -= 5.0; // harmonic class match with lookahead
            }
        } else {
            // Next item cannot use the remainder: mild penalty for waste.
            let gap = (next_item_size - pr) as f64;
            score += gap * 0.15;
        }
        // If next item exactly fills post residual, big reward.
        if next_item_size == pr && pr > 0 {
            score -= 80.0;
        }
    }

    // ---- Last-chance bin: avoid opening a new bin unnecessarily ----
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // ---- New-bin candidate logic (bin_residual == bin_capacity) ----
    if bin_residual == bin_capacity {
        // Opening a new bin wastes the residual of existing bins; only
        // attractive if no existing bin fits well.
        let best_existing = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        // Base cost of a new bin grows with number of open bins.
        score += 35.0 + open_bins_count as f64 * 2.0;
        if best_existing > 0.0 && post_residual <= 15 {
            // A fresh bin with a tight first item is fine.
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual && post_residual > 0 {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 25.0;
    }

    // ---- Mean residual context: penalize bins far from the mean waste ----
    let res_f = post_residual as f64;
    let dev = (res_f - mean_residual).abs();
    score += dev * 0.05;

    // ---- Small tie-breaker toward filling fuller bins first ----
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 10) can use are pure waste.
    if post_residual < 10 {
        score -= 60.0; // perfectly tight fit, ideal
    } else if post_residual < item_size.min(next_item_size.max(10)) {
        // gap smaller than anything useful next: dead space
        score += 40.0;
    } else {
        // graded dead-space penalty: quadratic waste growth
        score += (post_residual as f64) * 0.35;
    }

    // Reward bins whose residual matches the next item well (lookahead pairing)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 / (1.0 + gap);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // allow consolidation when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress);
    if bin_residual == bin_capacity {
        score += 20.0 + pressure * 2.0; // new-bin candidate penalized by open-bin pressure
    } else {
        score -= 5.0 + pressure * 0.5; // existing bins slightly favored
    }

    // Prefer bins below mean residual (tighter bins get used first)
    score += ((mean_residual - bin_residual as f64) * 0.1).max(-10.0).min(10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Near match: next item fits with small slack left -> moderate reward
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 60.0;
    }
    // Next item cannot fit this bin afterwards: penalize proportionally to wasted lookahead
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.5;
    }

    // Penalize dead space relative to mean residual (small unusable leftovers)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: only bin that fits -> reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins tighter than the mean residual (best-fit bias)
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: penalize opening a new bin unless current bin would leave large waste
    if bin_residual == bin_capacity {
        score += 25.0;
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            // opening fresh is fine if it perfectly accommodates the lookahead pair
            score -= 15.0;
        }
    }

    // Early stream: be slightly greedy toward tight fills; later: consolidate
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * (bin_residual - item_size) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squash post_residual into a concave penalty.
    let tightness = (post_residual as f64 / bin_capacity as f64).powi(2);
    score += tightness * 30.0;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if next item fits almost exactly afterwards.
        let chain_gap = post_residual - next_item_size;
        score -= (1.0 - chain_gap as f64 / bin_capacity as f64) * 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize creating dead space smaller than the next item.
        score += 6.0 + (next_item_size - post_residual) as f64 * 0.25;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the item is large or
    // open bins are heavily fragmented.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let frag = (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64;
        let large_item = item_size as f64 / bin_capacity as f64;
        score = bin_capacity as f64 * 0.9
            - large_item * 20.0
            - frag * 25.0
            - progress * 10.0
            + open_bins_count as f64 * 0.5;
        if post_residual == 0 {
            score -= 50.0;
        }
    } else {
        // Prefer bins below mean residual (more usable space concentrated).
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += dev * 15.0;
    }

    // Mild pressure to consolidate as the stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: post residual, non-linearly coupled with stream progress.
    // Early on, leaving residual is cheap; late, dead space is costly.
    let mut score = post * (1.0 + 1.5 * progress * progress);

    // Smooth penalty for very small post residuals that are hard to fill later:
    // penalize residuals below ~ item_size scale via quadratic bowl.
    let tiny = (post / cap - 0.05).max(0.0);
    score += 30.0 * tiny * tiny;

    // Reward tight fits: item fills most of the bin.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill * fill;

    // Last chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist; keeps flexibility.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead coupling: if next item fits into post_residual, reward leaving this exact space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            // Perfect chain: next item exactly fills the remaining space.
            let chain_fit = nxt / post;
            score -= 15.0 * chain_fit * chain_fit;
        } else {
            // Next item won't fit here; penalize residuals slightly smaller than next item (wasted sliver).
            let gap = (nxt - post) / cap;
            score += 20.0 * gap * gap;
        }
    }

    // Mean-residual coupling: if this bin's residual deviates strongly from mean,
    // encourage normalization (prefer bins below mean residual for large items).
    let dev = post - mean_residual;
    score += 0.15 * dev * dev / (mean_residual + 1.0);

    // New-bin candidate handling: empty bin should only win when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decreasing as stream progresses
        // (fewer future opportunities to amortize early-opened bins).
        score = cap * (1.2 - 0.5 * progress);
        // If last chance exists among open bins, make new bin clearly worse.
        if fitting_bins_count >= 1 {
            score += 15.0 + 25.0 * (1.0 - progress);
        }
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > 0 {
            score -= 0.3 * next_item_size as f64 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
