    }

    // Harmonic class of post_residual: bins whose residual lies in "usable" classes
    // (residual >= 10 can still hold future small items) get a bonus; tiny dead space penalized.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 60.0; // dead space
    }

    // Modulo arithmetic: residuals divisible by common item sizes are reusable
    if pr % 10 == 0 && pr > 0 {
        score -= 15.0;
    }
    if pr % 20 == 0 && pr > 0 {
        score -= 10.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 8.0;
    }

    // Capacity fraction classes: how full the bin becomes
    let fill = (bin_capacity - pr) as f64 / bin_capacity as f64;
    if fill >= 0.9 {
        score -= 40.0;
    } else if fill >= 0.7 {
        score -= 20.0;
    } else if fill < 0.4 {
        score += 15.0; // avoid scattering into mostly-empty bins
    }

    // Lookahead coupling: if next item fits in the post residual, big reward
    if next_item_size > 0 && next_item_size <= pr {
        score -= 35.0;
    } else if next_item_size > pr {
        score += 12.0; // next item won't fit here anyway
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 120.0 - pressure * 200.0
            + (open_bins_count as f64) * 2.0
            + (post_residual as f64) * 0.5;
        if next_item_size > 0 && next_item_size > bin_capacity {
            score += 50.0;
        }
    }

    // Late-stream consolidation: fewer open bins preferred as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * 3.0 * progress;
    score += (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
