    }

    // Prefer bins with below-mean residual (tighter bins absorb the item better).
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Slight bias toward closing bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (post_residual == 0) as i32 as f64;

    // New-bin candidate: make it slightly unattractive unless the fit is poor.
    if bin_residual == bin_capacity {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // 2-step lookahead: reward when next item fits the post-residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: bin fully consumed over two items
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64); // good chain, small slack better
        } else {
            // next item cannot follow into this bin: penalize proportional to wasted chain potential
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.15 * overflow;
        }
    } else {
        // Last item: prefer zero-waste finish.
        score += 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Compare against mean residual: bins with residual far from item size create fragmentation.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when open bins exist that fit reasonably.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let pressure = open_bins_count as f64;
        score += 15.0 + 2.0 * pressure;
        // But allow new bin if all open residuals are hopeless for typical sizes.
        if mean_residual < 12.0 {
            score -= 25.0;
        }
    }

    // Early stream: slightly prefer consolidation into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: progress through the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward near-full placements (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residual too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here after placement; slight penalty
            score += 8.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Global state coupling: many open bins with high mean residual -> consolidate
    let mean_res_norm = mean_residual / bin_capacity as f64;
    score += 10.0 * mean_res_norm * (open_bins_count as f64).sqrt();

    // Reward filling bins that are already mostly used
    let used_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 12.0 * used_ratio;

    // New-bin candidate handling: opening a bin is expensive; only attractive
    // when the item fits poorly everywhere (large item, late stream, many bins)
    if bin_residual == bin_capacity {
        let poor_fit_penalty = (bin_residual - item_size) as f64;
        let pressure = progress * 0.5
            + (fitting_bins_count == 0) as i32 as f64 * 1.5
            + (item_size as f64 / bin_capacity as f64) * 0.5;
        // Base cost of a new bin, discounted by pressure to open one
        score += 90.0 - 45.0 * pressure.min(2.0);
        // Empty bins waste capacity; penalize less if residual after placement stays useful
        if post_residual >= 50 {
            score -= 10.0;
        }
        let _ = poor_fit_penalty;
    }

    // Mild exploration term: non-linear coupling of progress and openness
    score += 3.0 * (progress * std::f64::consts::PI).sin();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64 / cap;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;

    let mut score = pr * pr * 40.0 + pr * 10.0;

    // smooth non-linear coupling of post_residual with stream progress
    score += 30.0 * (1.0 - progress) * pr * (1.0 - pr);
    score -= 25.0 * progress * pr * (1.0 - pr);

    // dead-space penalty: small post-residual that can't fit typical items
    let dead = (1.0 - pr * 2.5).max(0.0);
    score += 20.0 * dead * dead * (0.5 + 0.5 * progress);

    // lookahead: reward bins leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 12.0 * (1.0 - (post_residual as f64 - nxt) / cap);
        } else {
            score += 8.0 * (nxt - post_residual as f64) / cap;
        }
    }

    // last-chance bin: strong reward to fill it rather than open new
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0 * (1.0 + progress);
    }

    // penalize spreading across many open bins
    score += 2.0 * (open_bins_count as f64).ln() * (1.0 - pr);

    // new-bin candidate: prefer it only when residuals are tight
    if is_new_bin {
        score += 35.0 * (1.0 - progress) * (1.0 - mean_residual / cap).min(1.0);
        score -= 10.0 * progress;
    }

    // mean residual alignment: prefer bins close to the mean residual
    let dev = (post_residual as f64 - mean_residual).abs() / cap;
    score += 6.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover space is.
    // Residuals divisible by small harmonic bases (10, 20, 25, 50) are more likely
    // to be exactly filled by future items, so reward them.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit: best possible outcome
    } else {
        let mut harmony = 0.0;
        if pr % 10 == 0 { harmony += 4.0; }
        if pr % 20 == 0 { harmony += 3.0; }
        if pr % 25 == 0 { harmony += 3.0; }
        if pr % 50 == 0 { harmony += 2.0; }
        score -= harmony;

        // Dead-space penalty for awkward residuals (prime-ish / non-harmonic zones)
        let class = pr / 10; // integer division harmonic class 0..9
        let class_penalty = match class {
            0 => 2.0,           // 1..9: nearly useless sliver
            1 => 1.0,           // 10..19: only tiny items fit
            2 | 3 => 0.5,       // 20..39: marginal
            4..=6 => 0.0,       // 40..69: decent
            _ => -1.0,          // 70..99: very reusable
        };
        score += class_penalty;
    }

    // Lookahead coupling: does the next item fit exactly into the post residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0; // guaranteed perfect follow-up placement
        } else if next_item_size <= pr {
            // partial compatibility: reward proportional to how much of next item's need is covered
            score -= 5.0 * (next_item_size as f64 / pr.max(1) as f64);
        } else {
            // next item cannot use this bin's leftover: mild penalty proportional to overflow
            score += (next_item_size - pr) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default so that
    // only genuinely bad fits in existing bins trigger opening a new bin.
    if bin_residual == bin_capacity {
        score = 55.0 + (post_residual as f64) * 0.1;
        if fitting_bins_count == 0 {
            score -= 30.0; // no open bin fits: must open new bin
        }
        return score;
    }

    // Tightness bonus: reward filling a large fraction of the bin now.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual deviates from the mean in a useful (smaller) way.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 3.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space < 10, or < next item size)
    if post_residual > 0 {
        let min_gap = if next_item_size > 0 { next_item_size.min(10) } else { 10 };
        if post_residual < min_gap {
            score += 40.0 * (min_gap - post_residual) as f64;
        }
        // Extra penalty if gap cannot fit the lookahead item
        if next_item_size > 0 && post_residual < next_item_size {
            score += 15.0;
        }
    } else {
        // Perfect fit reward
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open bins pressure: discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Early stream: be more conservative (keep bins flexible)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fits (dead space minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0 + (5.0 - post_residual as f64) * 40.0;
    } else {
        // Non-linear dead-space penalty: small residuals are disproportionately bad.
        let r = post_residual as f64;
        score += (100.0 / r) * 12.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            // Chain fit: excellent — penalize less as post_residual approaches next size.
            let slack = post_residual as f64 - nxt;
            score -= 200.0 - slack * 2.0;
            if slack <= 10.0 {
                score -= 80.0; // tight chain: nearly perfect two-item packing
            }
        } else {
            // Next item cannot follow here; penalize more if we leave a big orphan gap.
            let gap = nxt - post_residual as f64;
            if gap < 20.0 {
                score += 60.0; // near-miss: mildly bad
            } else {
                score += 25.0; // clearly unusable for next item
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Reward using bins with residual below mean residual (consolidate waste),
    // penalize dipping into large-residual bins that remain flexible.
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= diff * 1.5;
    }

    // New-bin candidate handling: make an empty bin attractive only when the item
    // is large relative to capacity or the fit elsewhere is poor.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.7 {
            // Large items: opening a fresh bin is fine, even good.
            score -= 60.0 + fill_ratio * 50.0;
        } else {
            // Small/medium items should prefer existing bins.
            score += 120.0 - fill_ratio * 100.0;
        }
        // Late in the stream, avoid opening needless bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
    }

    // Mild preference to fill bins that are already mostly full (compactness).
    let used_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= used_ratio * 30.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 30.0;

    // Penalize leaving dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly discourage opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would leave bad residual.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, amortized by stream progress.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 15.0 * (1.0 - progress);
        // If an existing bin fits tightly, opening new bin is bad.
        let best_existing_tightness = (bin_capacity as f64 - item_size as f64) / bin_capacity as f64;
        score += best_existing_tightness * 10.0;
        // Reward opening new bin when many open bins have large residuals (fragmented state).
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 12.0;
    }

    // Prefer filling bins with smaller residuals overall (reduce fragmentation).
    score -= (bin_residual as f64 / bin_capacity as f64) * 8.0;

    // Mild penalty for accumulating too many open bins.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Time-horizon: later in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap;
    let t = progress;
    let coupling = prn * prn * (1.0 - t) * (1.0 - t) - prn * t * t;
    score += 6.0 * coupling;

    // Reward tight fits (low post residual) more strongly as stream progresses
    score -= 4.0 * (1.0 - prn) * (1.0 - prn) * t;

    // Lookahead: reward if next item fits into post_residual (chain packing)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 3.0 * (nxt / cap) * (1.0 - t);
        } else {
            // penalize leaving residual that nothing can use
            score += 2.0 * (prn * prn) * (1.0 - t * 0.5);
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Penalize opening a new bin when many open bins can fit the item
    if bin_residual == bin_capacity {
        let fit = fitting_bins_count as f64;
        score += 5.0 + 2.0 * fit * (1.0 - t);
        // allow new bin when residuals are large and fragmented
        score -= 3.0 * (mean_residual / cap) * (1.0 - t);
    } else {
        // mild preference for bins below mean residual (consolidate emptier bins)
        score += 1.5 * (pr - mean_residual) / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band does it land in?
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = bin_capacity / 4 * 3;

    // Reward tight fits: small post_residual is good (already base score).
    // Harmonic bonus: post_residual exactly divisible by common item sizes (10, 20, 25, 50)
    // is "reusable" dead space; penalize odd/tiny unusable slivers.
    if post_residual > 0 {
        let mut reusability = 0.0;
        if post_residual % 10 == 0 { reusability += 3.0; }
        if post_residual % 20 == 0 { reusability += 2.0; }
        if post_residual % 25 == 0 { reusability += 2.0; }
        if post_residual % 50 == 0 { reusability += 3.0; }
        score -= reusability;
        // Penalize slivers: post_residual below 10 is dead space forever.
        if post_residual < 10 {
            score += 12.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 15.0;
    }

    // Harmonic band classification of post_residual via integer division thresholds.
    let band = post_residual / quarter; // 0..4
    match band {
        0 => score -= 4.0,                 // nearly full bin: great
        1 => score += 0.0,                 // residual in (0,25): ok
        2 => score += 2.0,                 // residual in [25,50): moderate
        3 => score += 4.0,                 // residual in [50,75): wasteful unless new bin
        _ => score += 6.0,                 // residual >= 75: very empty bin
    }

    // Lookahead coupling: harmonic class of next item vs post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here too: reward, especially on harmonic boundaries.
            score -= 5.0;
            if post_residual % next_item_size == 0 {
                score -= 3.0; // exact harmonic division: chain of perfect fits
            }
        } else {
            // Next item won't fit after placement: penalize slightly.
            score += 2.0;
            // Unless this is the last fitting bin, then it's still forced.
            if fitting_bins_count == 1 {
                score -= 4.0;
            }
        }
    }

    // Last-chance bonus: only one bin can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate handling: empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Prefer opening a new bin when existing fits are poor (large post_residual)
        // or when this is the last fitting bin among open bins (then opening new is neutral).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early in stream: opening bins liberally is fine; later: consolidate.
        let open_penalty = open_bins_count as f64 * 1.5 * (0.5 + progress);
        score += 20.0 + open_penalty;
        // But if the item is huge (> half capacity), a fresh bin is attractive.
        if item_size > half {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size > half {
            score -= 5.0; // big next item: keep fresh capacity
        }
    }

    // Mild pressure toward fuller bins using mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 1.0;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Medium gaps (10..25) are also poor fits.
    if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Gaps that exactly fit the lookahead item are valuable.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // Penalize gaps too small for the next item (dead space going forward).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }
    // Reward large comfortable gaps only mildly (they remain usable).
    if post_residual >= 50 {
        score -= 4.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 12.0 + open_bins_count as f64 * 1.5;
    } else {
        // Prefer consolidating into fewer bins.
        score -= 2.0 / open_bins_count.max(1) as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid waste elsewhere.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    // Early in the stream, be slightly more willing to open bins to build diversity.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin && progress < 0.2 {
        score -= 5.0;
    }

    // Slight tilt toward bins below mean residual (spread the load evenly).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, penalize large post_residual quadratically (dead space).
    score += 0.02 * (post_residual as f64).powi(2);

    // Aggressive 2-step lookahead: reward if the next item exactly fills post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if nxt == post {
            // Perfect chaining: this bin will be closed by the next item.
            score -= 60.0;
        } else if nxt <= post {
            // Next item still fits: mild reward proportional to how much remains after.
            let after2 = post - nxt;
            score -= 25.0 - 0.3 * after2;
        } else {
            // Next item won't fit here: penalize wasted space that strands the lookahead.
            let gap = nxt - post;
            score += 0.5 * gap;
        }
    }

    // Relative to mean residual: bins tighter than average are more valuable to fill now.
    let dev = mean_residual - post_residual as f64;
    score -= 0.15 * dev;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive late in the stream or when item is huge
    // (poor fit anywhere else). Penalize opening new bins when open bins are loose.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = item_size as f64 > bin_capacity as f64 * 0.6;
        score += 30.0 - 20.0 * progress;
        if tight {
            score -= 25.0;
        }
        if open_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 15.0; // an open bin can take it; don't open a new one
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are good: reward small post_residual non-linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space that no future item can plausibly use.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 0.0 } else { (post_residual as f64).powf(1.35) };
        score += 0.35 * dead;
    }

    // Perfect fill jackpot.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            // usable leftover for next item
            score -= 25.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // leftover too small for next item: penalize proportionally
            score += 15.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // mild diversity pressure: prefer bins with tighter fit among many candidates
        score += 3.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Global residual context: placing into a bin far below mean residual
    // helps balance; placing into an unusually full bin wastes little.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Time horizon: early in stream, be more conservative (favor tight fits,
    // avoid fragmentation); late in stream, just pack greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 30.0 * fit_ratio * (1.0 - progress);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: encourage closing them out (fill nearly-full bins harder).
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: opening a new bin is a last resort.
    if bin_residual == bin_capacity {
        // Base penalty: prefer any existing bin with a decent fit.
        score += 90.0;
        // But if nothing else fits, allow opening a new bin (it is the only option).
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // If the current item plus next item would combine well in a fresh bin,
        // opening early can be worthwhile.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            let pair_eff = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_eff > 0.9 {
                score -= 70.0 * (pair_eff - 0.9) / 0.1;
            }
        }
        // Late in the stream, avoid opening bins for small items.
        if progress > 0.8 && item_size < 40 {
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr2 = norm_pr * norm_pr;
    let pr3 = pr2 * norm_pr;
    let coupling = norm_pr - 2.0 * pr2 + 0.8 * pr3;
    score += coupling * cap * (0.6 + 0.8 * progress);

    // Penalize large dead space more as stream progresses (fewer future chances to fill it)
    score += 12.0 * pr2 * progress;

    // Reward tight fits: small post residual gets a discount
    score -= (1.0 - norm_pr).powi(3) * 8.0;

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: reward bins whose post residual can still fit the next item
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 6.0;
        } else {
            score += 3.0 * (next_item_size - post_residual as u32) as f64 / cap;
        }
    }

    // Diverge from mean residual: prefer bins that are already more filled than average
    score += 0.05 * (mean_residual - pr).abs();

    // Mild penalty for spreading across many open bins late in the stream
    score += 0.3 * open_bins_count as f64 * progress;

    // New-bin candidate: make it attractive only for large items or very late stream
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / cap;
        score += 20.0 - 25.0 * tightness - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Capacity fraction classes of post-residual (harmonic bins of leftover size)
    let frac = post_residual as f64 / cap;
    if post_residual == 0 {
        score -= 30.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 18.0; // near-perfect fit, dead space negligible
    } else if frac <= 0.10 {
        score -= 8.0;
    } else if frac <= 0.25 {
        score -= 2.0;
    } else if frac <= 0.50 {
        score += 3.0;
    } else {
        score += 8.0; // large dead space
    }

    // Harmonic class of post_residual via integer division thresholds:
    // leftover divisible by common item sizes is more reusable.
    if post_residual > 0 {
        let mut reuse = 0.0f64;
        for d in [10u32, 20, 25, 50] {
            if post_residual % d == 0 {
                reuse += 4.0;
            }
        }
        if post_residual % 100 == 0 {
            reuse += 6.0;
        }
        score -= reuse;
    }

    // Lookahead: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits: reward, scaled by how snugly it fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 - 0.08 * slack;
        } else {
            // next item won't fit: penalize wasting a big residual
            score += 0.10 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Progression: late in the stream, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus pressure from open bins / progress
        score += 20.0 + 25.0 * progress + 0.5 * open_bins_count as f64;
        // opening a fresh bin is fine if mean residual is small (all bins congested)
        score -= 10.0 * (1.0 - mean_residual / cap).max(0.0);
    } else {
        // mildly prefer tighter bins as stream progresses
        score += 2.0 * (1.0 - progress);
    }

    // Tie-break toward bins whose residual is close to item (snug fit)
    score += 0.05 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }
    // Perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Prefer bins whose residual tightly matches the item (good fit quality).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score += (1.0 - fit_ratio).abs() * 30.0;

    // Pressure from number of open bins: consolidate when many bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.8 * (0.5 + progress);

    // Deviation from mean residual: prefer bins near the mean (balanced packing).
    score += (bin_residual as f64 - mean_residual).abs() * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item cannot fit in post-residual, mild penalty for stranding space.
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // New-bin candidate: neutral baseline with slight penalty so it's chosen
    // only when all open-bin options score poorly.
    if bin_residual == bin_capacity {
        score += 70.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 30.0;

    // Aggressive 2-step lookahead: if the next item fits exactly in the
    // post_residual, strongly favor this bin (perfect pairing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // Next item fits, penalize leftover slack after the pair.
            let pair_slack = post_residual - next_item_size;
            score += pair_slack as f64 * 0.8;
            score -= 20.0;
        } else {
            // Next item will need another bin; penalize wasting residual.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Compare residual against the mean residual of open bins:
    // prefer bins whose residual deviates favorably (less wasted space).
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual <= bin_capacity / 4 {
        score -= 15.0;
    }

    // Penalize dead space that is too small for typical items (unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate: make it moderately unattractive so we prefer
    // good fits into existing bins, but attractive over very poor fits.
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Tight fit reward: squared discount on remaining space
    score -= 0.35 * (bin_capacity as f64 - post_residual as f64).sqrt();

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 + 6.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize tiny unusable dead space (< 10) unless next item could use it
    if post_residual < 10 && (next_item_size == 0 || next_item_size > post_residual) {
        score += 12.0 * (1.0 - progress);
    }

    // Last-chance bonus: this is the only bin that fits the item
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Many open bins: discourage fragmenting capacity across bins; prefer consolidation
    score += 0.02 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    // Early stream: be more selective (favor leaving room); late stream: just fill
    score *= 1.0 + 0.15 * (1.0 - progress);

    // New-bin candidate: make it attractive only when item is large relative to capacity
    if bin_residual == bin_capacity {
        let largeness = item_size as f64 / bin_capacity as f64;
        score -= 20.0 * largeness;
        // but penalize opening a bin for small items when bins exist
        if open_bins_count > 0 && largeness < 0.4 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;

    // Base: quadratic coupling of post_residual with stream progress.
    // Later in the stream, large residuals are more costly (fewer chances to fill them).
    let mut score = pr * (1.0 + 1.5 * progress) + 0.004 * pr * pr * (0.5 + progress);

    // Smooth penalty for residual that cannot fit the average future item.
    // Encourage residuals close to multiples of typical small-item space.
    let norm_pr = pr / cap;
    score += 8.0 * norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 + progress);

    // Reward tight fits: post_residual near zero gets a smooth quadratic bonus.
    score -= 12.0 * (1.0 - norm_pr).powi(3);

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly (smooth).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let fit_quality = (-gap / (0.25 * cap)).exp();
        score -= 15.0 * fit_quality * (0.6 + 0.4 * progress);
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mean-residual divergence penalty: prefer bins whose resulting residual
    // stays coherent with the fleet average (smooth, non-linear).
    let div = pr - mean_residual;
    score += 0.03 * div * div;

    // New-bin candidate handling: smooth penalty that grows with stream progress
    // and with the number of open bins, but relaxes when the item is large
    // (opening a bin for a big item wastes less relative space).
    if is_new_bin {
        let item_norm = item_size as f64 / cap;
        let size_relief = (1.0 - item_norm).powi(2);
        score += 18.0 * (0.4 + 0.6 * progress) * (1.0 + 0.15 * open_bins_count as f64).ln() * size_relief;
        // Slight reward if no existing bin fits tightly anyway.
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: post_residual modulo small integers
    // detects "perfectly harmonic" leftovers (multiples of 10 / 25 / 50) that
    // future items are likely to fill exactly.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -12.0 // perfect fill: ideal
    } else if pr % 50 == 0 {
        -8.0
    } else if pr % 25 == 0 {
        -6.0
    } else if pr % 10 == 0 {
        -4.0
    } else if pr % 5 == 0 {
        -2.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Dead-space penalty for tiny unusable residuals (integer division thresholds)
    if pr > 0 && pr < 10 {
        score += 6.0; // nothing in [1,100] guaranteed to fit well; residual < 10 is nearly dead
    }

    // Coupling with lookahead item: reward if next item fits harmonically
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 9.0; // exact chain fill
        } else if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap % 10 == 0 {
                score -= 5.0;
            } else if gap < 10 {
                score += 3.0; // next item leaves near-dead space
            }
        } else {
            score += 2.0; // next item won't fit here at all
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 7.0;
    } else if fitting_bins_count > 1 {
        // with many options, prefer tighter fits (already via post_residual)
        score += (fitting_bins_count as f64).ln() * 0.8;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score += (post_residual as f64 - mean_residual) * 0.35;

    // New-bin candidate handling: opening a bin is justified only when this bin
    // would leave a bad (non-harmonic, small) residual and a new bin would be clean.
    if bin_residual == bin_capacity {
        // neutral base; new bin's post_residual is large so it starts high,
        // give it a mild discount so it wins only against genuinely bad fits
        score -= 1.5;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 0.5;
        }
    }

    // Slight preference to consolidate among fewer open bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 0.5 * (open_bins_count as f64).min(10.0) / 10.0
        * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    // Treat post_residual in (0..=15] as "dead space" and amplify its penalty.
    if post_residual > 0 && post_residual <= 15 {
        score += 60.0 * (1.0 - post_residual as f64 / 15.0);
    } else if post_residual > 15 && post_residual <= 30 {
        score += 10.0;
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into the post-residual, this placement
    // chains nicely — reward it proportionally to how snug the chain is.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 12.0 * (1.0 - slack as f64 / 40.0);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this bin's leftover; leftover likely wasted.
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit
    // is genuinely tight (post_residual small).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (2.0 + 3.0 * progress);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has huge post_residual; make it
    // attractive only when the item would leave a very small gap in existing
    // bins anyway (i.e., all fits are bad). Penalize new bins mildly otherwise.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.05;
    }

    // Mild tie-break toward bins whose residual is close to the item (snug fit).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.15;

    // Mean-residual coupling: prefer bins below the mean residual (tighter bins).
    score -= (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) especially exact fits.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual >= next_item_size {
            // next item can still fit here: mild reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit: dead-space penalty grows as post_residual gets small
            let dead = post_residual as f64;
            score += 30.0 * (1.0 - dead / bin_capacity as f64);
        }
    }

    // Penalize leaving residuals that few future items could use (very small leftovers).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: discourage opening a new bin unless current fit is very poor.
    if bin_residual == bin_capacity {
        score += 120.0;
        // but if item is large and would leave big residual anyway in existing bins, allow it
        if item_size as f64 >= 0.6 * bin_capacity as f64 {
            score -= 60.0;
        }
        // early in stream, allow more bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * (1.0 - progress);
    }

    // Compare against mean residual: prefer bins with below-mean residual (tighter bins)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Prefer fuller bins overall
    score -= 0.3 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportionally wasted fraction of the bin.
    let wasted = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * wasted * wasted;

    // Reward filling the bin well relative to current item size.
    score -= 12.0 * (item_size as f64 / bin_capacity as f64);

    // Dead-space penalty: small residuals that likely nothing can use later.
    if post_residual < 10 {
        score -= 25.0; // perfectly (nearly) closed bin is great
    } else if post_residual <= 15 {
        score += 8.0; // awkward dead zone
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to leftover
            score += 4.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Prefer bins with below-average residual (pack fuller bins first).
    score -= 3.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    // Early in the stream: keep bins open and flexible; late: consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - wasted);

    // New-bin candidate: opening a new bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin; becomes attractive only if score above is high
        score += 45.0 - 20.0 * wasted; // wasted == 0 for empty bin, so ~ +45
        if fitting_bins_count == 0 {
            score -= 60.0; // no open bin fits: must open new bin
        }
        // if next item is large, a fresh bin preserves room
        if next_item_size > 50 && item_size > 50 {
            score -= 15.0;
        }
    }

    // Mild penalty for accumulating too many open bins.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post_norm = post / cap;
    let item_norm = item_size as f64 / cap;

    // Base: penalize wasted residual, non-linearly (quadratic dead space).
    let mut score = post * (1.0 + post_norm * post_norm);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills (low post residual) strongly; later, allow
    // looser fits to keep bins flexible — modulated by a cubic in progress.
    let progress_cubic = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += post_norm * post_norm * (1.0 - progress_cubic) * cap * 0.5;
    score -= post_norm * progress_cubic * 4.0;

    // Reward large item placement relative to residual (good fit ratio).
    let fit_ratio = item_norm / (bin_residual as f64 / cap).max(1e-6);
    score -= fit_ratio * 6.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress_cubic;
    }

    // More fitting alternatives -> mild penalty for wasting a flexible bin.
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post {
            let slack = (post - next) / cap;
            score -= 10.0 * (1.0 - slack * slack);
        } else {
            // next item won't fit here: penalize leaving large unusable gaps.
            score += post_norm * 6.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (consolidate waste) with smooth quadratic term.
    let dev = (post - mean_residual) / cap;
    score += dev * dev * cap * 0.25;

    // Many open bins: prefer closing out nearly-empty-residual bins.
    let open_norm = open_bins_count as f64 / (1.0 + open_bins_count as f64);
    score += post_norm * open_norm * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into buckets.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class boundaries via integer division thresholds (harmonic quarters of capacity).
    let class = post_residual / (bin_capacity / 4); // 0..4 harmonic class
    match class {
        0 => { score -= 30.0; }              // near-perfect fit: strongly reward
        1 => { score -= 10.0; }              // small leftover still reusable for small items
        2 => { score += 5.0; }               // awkward mid-range gap
        _ => { score += 12.0; }              // large leftover: wasteful unless bin was empty
    }

    // Reward exact tight fits with a bonus.
    if post_residual == 0 { score -= 40.0; }

    // Lookahead compatibility: if the next item fits the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 - slack * 0.1; // prefer next item also fitting snugly
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here: penalize more if the leftover is a small dead zone
        if post_residual < 10 { score += 25.0; } else { score += 8.0; }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / cap;
        // Prefer new bin when mean residual of open bins is small (fragmented)
        // and early in the stream; penalize new bins when good reuse is possible.
        score = cap * 0.5 + fragmentation * 20.0 - progress * 10.0;
        if fitting_bins_count == 0 { score -= 60.0; } // must open a bin
        if post_residual == 0 { score -= 0.0; }
    }

    // Slight preference to fill fuller bins overall (best-fit flavor).
    score += (mean_residual - post) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item
    // (min item size 1, but small gaps < 12 are statistically dead) are heavily penalized.
    if post_residual > 0 && post_residual < 12 {
        score += 40.0;
    } else if post_residual < 25 {
        score += 12.0;
    }

    // Perfect fit reward: subtract heavily when the bin is exactly filled.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit bonus: reward placements leaving a large item's worth of usable gap
    // (post_residual in a "useful" band, e.g. >= 30), encouraging compact packing.
    if post_residual >= 30 {
        score -= 8.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: mildly penalize opening a new bin unless the
    // current item is large relative to residual, or many bins are open.
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size > 60 {
            score -= 30.0; // large items start fresh bins happily
        }
        if open_bins_count > 8 {
            score -= 5.0; // spread pressure when many bins open
        }
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // reward this placement strongly (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 12 {
            score += 15.0; // next item would create dead space here
        }
    }

    // Open-bin consolidation pressure: mildly prefer filling existing bins
    // when many are open, to avoid bin sprawl.
    score += (open_bins_count as f64) * 0.3;

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize outliers slightly.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Early stream: be slightly more conservative (favor new bins) so later
    // items have flexible residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits
    score += (post_residual as f64 / bin_capacity as f64) * 40.0;

    // Aggressive 2-step lookahead: reward if next item fits the post residual exactly/well
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_fit_gap = post_residual as f64 - next_item_size as f64;
            // Perfect chain (post_residual == next_item_size) is ideal
            score -= 60.0 * (1.0 - next_fit_gap / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leftover that becomes dead space
            score += 15.0;
        }
    } else {
        // Last item: minimize post residual aggressively
        score += 0.0;
    }

    // Compare residual against mean residual of open bins:
    // bins with residual below mean are "tighter" — favor filling them
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are terrible
    if bin_residual == bin_capacity {
        score += 120.0;
        // But if next item is large and no bin can chain, opening fresh may help
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 30.0;
        }
    }

    // Late in stream: consolidate into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (open_bins_count as f64) * 0.3;

    // Penalize very small unusable leftovers
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: tight fit preference (normalized waste)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that few future items can use
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable sliver
    }

    // Last-chance bonus: only this bin fits, avoid opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward bins where the next item also fits after this placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
            // extra reward if next item is large (hard to place later)
            if next_item_size >= 50 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; mildly penalize very tight packing
            score += 5.0;
        }
    }

    // New-bin candidate handling: strongly penalize opening a new bin
    // unless it's genuinely better than a poor existing fit.
    if bin_residual == bin_capacity {
        score += 45.0;
        // late in the stream, new bins are cheaper (less time to accumulate waste)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
        // if many bins are open and none fit well, opening is more acceptable
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Prefer filling bins that deviate from the mean residual upward
    // (use the emptier bins for large items, keep tight bins tight)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev * (item_size as f64 / 100.0);

    // Prefer using bins with larger residuals when many bins are open
    // (consolidation pressure)
    score -= 0.05 * (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 / bin_capacity as f64);

    // Time-horizon coupling: early on, keep residuals flexible; late, pack greedily
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 6.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * (0.5 + 1.5 * progress * progress);

    let mut score = pr + 40.0 * poly;

    // Penalize tight fits less as stream progresses (favor filling bins late)
    let tight_fit = (pr < 5.0) as i32 as f64;
    score -= tight_fit * (10.0 + 30.0 * progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: penalize if post_residual can't fit next item but another bin could
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt && nxt > 0.0 && pr - nxt < 5.0 {
            score += 8.0; // creates tiny dead space unusable by next item
        }
        if pr < nxt {
            score += 4.0 * (1.0 - progress);
        }
    }

    // New-bin candidate handling: mildly penalize opening new bins early
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins whose residual is close to item usage
    score += 0.3 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band it falls into.
    let pr = post_residual;
    let class = pr / (bin_capacity / 10); // integer division: 0..10 harmonic classes
    score -= class as f64 * 6.0; // reward bins landing in high classes (tighter fills)

    // Perfect / near-perfect fills get strong rewards.
    if pr == 0 {
        score -= 1000.0;
    } else if pr <= 5 {
        score -= 400.0;
    } else if pr <= 10 {
        score -= 150.0;
    }

    // Penalize dead space that no plausible item can use.
    if pr > 0 && pr < 10 {
        score += 120.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits: excellent, reward proportionally to tightness.
            score -= 60.0 + 2.0 * (next_item_size as f64);
        } else {
            // Next item won't fit; penalize leftover that becomes stranded.
            score += 1.5 * (next_item_size as f64 - pr as f64);
        }
        // Harmonic class of next item relative to capacity.
        let nclass = next_item_size / (bin_capacity / 10);
        score -= nclass as f64 * 2.0; // large next items prefer roomier bins
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: only attractive when open bins are nearly full
    // or the fit here is terrible.
    if bin_residual == bin_capacity {
        let base = 300.0
            + mean_residual * 1.2
            + open_bins_count as f64 * 5.0;
        // Late in the stream, discourage spawning extra bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += base * (0.6 + 0.4 * progress);
    } else {
        // Slight preference for bins with residuals near the item size (tight fit).
        let tightness = 1.0 - ((bin_residual - item_size) as f64 / cap);
        score -= 20.0 * tightness;
    }

    // Mean residual coupling: prefer bins below mean residual (fill emptier bins
    // when they're roomy, keep tight bins for small items).
    let diff = mean_residual - bin_residual as f64;
    score += 0.3 * diff;

    // Modulo-style tie-breaking on post_residual classes to break ties deterministically.
    score += (pr % 7) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps.
    // A post_residual below the minimum item size (1) is impossible, but tiny
    // residuals (1..=10) are effectively dead space since most items are larger.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 12.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the fit in open bins is bad.
    // Empty-bin residual equals capacity -> discourage unless post_residual in open bins is large.
    if bin_residual == bin_capacity {
        // Base pressure against new bins, growing with number of open bins' slack.
        score += 30.0 + mean_residual * 0.5;
        // But if the stream is early and few bins exist, new bins are cheaper.
        if open_bins_count <= 2 {
            score -= 20.0;
        }
        // Perfect fit in a new bin is fine (item == capacity case).
        if post_residual == 0 {
            score -= 60.0;
        }
    } else {
        // Open-bin pressure: slightly favor filling bins that are already quite full
        // (small bin_residual relative to capacity), consolidating waste.
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill_ratio * 10.0;

        // Lookahead: if next item fits exactly in the post residual, reward this placement.
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover = post_residual - next_item_size;
            if leftover <= 10 {
                score -= 15.0;
            } else {
                score -= 5.0;
            }
        }
        // If next item would NOT fit here anyway, slight penalty for wasting the lookahead.
        if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
            score += 3.0;
        }

        // Many open bins -> pressure to close them out by filling tight fits.
        if open_bins_count > 6 {
            score -= 5.0;
        }
    }

    // Mild coupling with mean residual: prefer bins below mean residual (fuller bins).
    score -= (mean_residual - post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize post_residual quadratically less when small.
    let pr = post_residual as f64;
    score += 0.35 * pr * pr / bin_capacity as f64;

    // Exact fit: strong reward (subtract).
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: if the next item fits perfectly in the post-residual,
    // this placement sets up a two-item completion -> big reward.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if next_item_size as u32 <= post_residual {
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // post_residual cannot host next item: dead space penalty,
            // worse when the leftover is small (unusable sliver).
            score += 12.0 * (1.0 - pr / bin_capacity as f64);
        }
    }

    // Compare against mean residual across open bins: prefer bins whose
    // post-residual stays near/below the mean (keeps residuals balanced).
    score += 0.6 * (pr - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make the empty bin attractive only when the item is
    // large relative to capacity or no good fit exists; otherwise penalize it
    // to encourage filling existing bins.
    if bin_residual == bin_capacity {
        score += 45.0 - 0.25 * item_size as f64;
        // Late in the stream, discourage opening new bins even more.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    }

    // Prefer fuller bins (smaller bin_residual) slightly.
    score += 0.08 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is already favored by the base term.
    // Add a non-linear bonus for near-perfect fills.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that can never fit a future item:
    // if post_residual < smallest plausible item (1..100 unknown, use next_item_size as proxy)
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // dead space relative to lookahead: penalize proportionally
            score += 0.35 * (post_residual as f64);
        } else {
            // reward bins that can also host the next item (chain fit)
            score -= 3.0;
        }
        // Perfect pair: item + next item exactly fills the bin
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Fragmentation pressure: penalize leaving residuals near awkward mid-range values
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 6.0; // tiny unusable slivers
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into existing bins rather than opening new ones.
    let mean_pressure = mean_residual / (bin_capacity as f64);
    if bin_residual < bin_capacity {
        score -= 5.0 * mean_pressure;
    }

    // New-bin candidate handling: only attractive when no good existing option
    // exists, i.e., when open bins are crowded (low mean residual) or many bins open.
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 25.0;
        // cheaper to open a new bin early in the stream (horizon long enough to use it)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // if open bins are nearly full, new bin is more attractive
        score -= 10.0 * (1.0 - mean_pressure);
        // if many bins already open, discourage adding more
        score += 0.8 * (open_bins_count as f64);
        // if the next item is large and this bin would be left with a big residual,
        // a fresh bin is fine; small residuals elsewhere already penalized.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 4.0;
        }
    }

    // Time horizon: late in the stream, prefer closing bins out (favor larger fills)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * tightness;

    // Mild preference for bins with residual close to item size (best-fit sharpening)
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * fit_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // smooth polynomial coupling of post_residual with stream progress
    let shape = norm_pr * (1.0 - norm_pr);
    let coupling = shape * (1.0 + 2.0 * progress);
    score -= 12.0 * coupling * cap * 0.01;
    // penalize large residuals late in the stream (wasted space)
    score += norm_pr * norm_pr * cap * (0.2 + 0.8 * progress);
    // reward tight fits
    score -= (item_size as f64 / cap) * (1.0 - norm_pr) * 5.0;
    // lookahead: penalize if post_residual can't fit next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            score -= 3.0 * (1.0 - (pr - ns) / cap);
        } else {
            score += 4.0 * (ns - pr) / cap;
        }
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0;
    }
    // new-bin candidate: prefer opening new bins early, discourage late
    if bin_residual == bin_capacity {
        score += 8.0 * progress - 4.0 * (1.0 - progress);
    }
    // mean residual coupling
    score += 0.5 * (mean_residual - pr) / cap;
    // open bins pressure
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: classify leftover into capacity fractions
    let frac = post_residual as f64 / cap;
    let class = (frac * 10.0).floor() as i32; // 0..10 decile of leftover

    // Reward tight fits: leftover near zero is excellent
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 150.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Penalize dead space classes that are hard to fill (small leftovers)
    if class >= 1 && class <= 3 {
        score += 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 120.0 / (1.0 + slack as f64 / 10.0);
        } else {
            // next item won't fit here: penalize proportional to leftover
            score += 0.3 * (post_residual as f64 - (next_item_size as f64 - post_residual as f64)).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a bin unless existing residuals are bad
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - post_residual as f64;
        score += 250.0;
        if mean_residual > 0.0 {
            // open new bin only if open bins are nearly full
            score -= (mean_residual / cap) * 100.0;
        }
        let _ = mean_gap;
    }

    // Modulo-class coupling: leftover divisible into common item sizes is reusable
    let pr = post_residual;
    if pr % 10 == 0 && pr > 0 {
        score -= 25.0;
    }
    if pr % 20 == 0 && pr > 0 {
        score -= 15.0;
    }

    // Mild pressure to consolidate as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 10.0 * frac;

    // Slight preference for bins below mean residual (balance)
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for any plausible
    // future item (min size 1, but practically wasted if tiny) are heavily penalized.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Non-linear penalty growing sharply for small-but-nonzero gaps.
        score += 40.0 / (gap + 1.0);
        // If the gap cannot fit the lookahead item, it is likely dead space.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 15.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading out.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual != bin_capacity {
        score -= 8.0 * pressure;
    } else {
        // New-bin candidate: only attractive when no bin fits well
        // (few fitting bins) and current bins are already quite full.
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        let scarcity = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        score += 30.0 * pressure - 25.0 * scarcity * avg_fill;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Slight preference for filling bins earlier in the stream (keeps
    // flexibility for later items).
    score += 5.0 * (step_index as f64 / total_items.max(1) as f64);

    // Prefer bins whose residual is below the mean (fill the emptiest-relative
    // bins last, keep balanced large residuals available).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 50.0 + 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // penalize residual that is too small for the next item (dead space)
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
        // exact match of next item into post_residual
        if post_residual == next_item_size {
            score -= 200.0;
        }
    }

    // Compare against mean residual: bins already tighter than average are better targets
    score += 0.4 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably
    if bin_residual == bin_capacity {
        score += 120.0;
        // but new bin is attractive if it can host the next item too
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0;
        }
    }

    // Late in stream: prefer tighter packing, discourage waste
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize larger post-residual nonlinearly
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Exact fit is excellent
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: bonus if the next item fits the post-residual exactly or well
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item can't use leftover space; penalize large leftovers slightly
            score += 8.0 * tightness;
        }
    } else {
        // last item: prefer minimal residual
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Global state: when many bins are open, discourage opening new bins
    // (handled implicitly by new-bin candidate scoring below)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Base cost of a new bin, modulated by how poorly the item fits existing bins
        let mut new_bin_score = bin_capacity as f64 * 0.9;
        // If this bin is the only fitting option (fitting_bins_count counts only open bins
        // that fit; a new bin always fits), opening is more attractive when mean residual
        // is fragmented relative to item size
        if mean_residual < item_size as f64 {
            new_bin_score -= 40.0;
        }
        // Early in stream, opening bins is cheaper; late in stream, prefer consolidation
        new_bin_score += 30.0 * progress;
        // If many bins already open, prefer reusing
        new_bin_score += 2.0 * open_bins_count as f64;
        // If next item is large and no bin will fit it, a fresh bin is useful
        if next_item_size > 50 && mean_residual < next_item_size as f64 {
            new_bin_score -= 15.0;
        }
        score = new_bin_score;
    }

    // Mild preference for bins below mean residual (keeps residuals balanced)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Small exploration term coupling time and open bins
    score -= 0.01 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: squared coupling of fill ratio
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 2.5 * fill * fill * (bin_residual as f64);

    // Penalize post_residual that cannot fit the next item (dead space)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt {
            score += 1.8 * nxt * (1.0 + progress);
        } else {
            // reward leaving exactly enough room for the next item
            let gap = post_residual as f64 - nxt;
            score -= 1.2 * (1.0 - gap / bin_capacity as f64).max(0.0);
        }
    }

    // Smooth polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let norm = pr / bin_capacity as f64;
    score += progress * norm * norm * 4.0 - (1.0 - progress) * norm * 1.5;

    // Last-chance bonus: strongly favor this bin if it is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0 + 2.0 * progress;
    }

    // Deter opening new bins when many bins are already open and mean residual is large
    if bin_residual == bin_capacity {
        score += 6.0 + 0.15 * open_bins_count as f64 + mean_residual * 0.05;
    } else {
        // slight preference for bins below mean residual (balance residuals)
        score += 0.05 * (mean_residual - pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are "nice" fractions
    // of capacity are more reusable. Class = post_residual / 10 bucket.
    let class = post_residual / 10;
    match class {
        0 => score -= 18.0,               // near-perfect fit, tiny waste
        1 => score -= 12.0,
        2 => score -= 7.0,
        3 => score -= 3.0,
        4 => score -= 0.5,
        5 => score -= 2.0,                // half-full: decent class
        6 => score += 2.0,
        7 => score += 4.0,
        8 => score += 7.0,
        9 => score += 10.0,               // nearly empty bin left: bad
        _ => {}
    }

    // Modulo-10 harmonic bonus: residuals divisible by 10 align with the
    // 10-granular item grid, making exact future fits more likely.
    if post_residual % 10 == 0 {
        score -= 4.0;
    }
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 1.5;
    }
    if post_residual % 20 == 0 {
        score -= 2.0;
    }

    // Integer-division threshold: post_residual that can still host a
    // "large" item (>= 40) keeps the bin valuable.
    if post_residual >= 40 {
        score -= 5.0;
    } else if post_residual >= 25 {
        score -= 2.5;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let next_class = (post_residual - next_item_size) / 10;
            score -= match next_class {
                0 => 10.0,
                1 => 6.0,
                2 => 3.0,
                _ => 1.0,
            };
        } else {
            // Next item would not fit here: mild penalty scaled by overshoot.
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin for a reasonable placement.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // existing residuals are fragmented (high mean residual) or few bins
    // can fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = (bin_capacity as f64) * 0.55
            + fragmentation * 30.0
            - (open_bins_count as f64) * 0.4
            - progress * 5.0;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: must open
        }
        if fitting_bins_count == 1 && post_residual < 15 {
            score += 6.0; // last-chance bin exists; prefer it over a fresh bin
        }
    }

    // Mild penalty when this bin's residual deviates strongly from the mean
    // (keeps the population of residuals homogeneous and packable).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Tiny tie-break preferring tighter fits.
    score += (item_size as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A post_residual below the minimum item size (1) is impossible, but
    // very small residuals are nearly dead space for future items.
    if post_residual > 0 {
        // Non-linear penalty growing as post_residual shrinks toward 0.
        let tiny_gap = (12.0 - post_residual as f64).max(0.0);
        score += 2.5 * tiny_gap * tiny_gap / 12.0;
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward placements where post_residual can still fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Post residual too small for the next item: dead space penalty.
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage leaving many
    // partially filled bins around; prefer tighter fills.
    let open_pressure = open_bins_count as f64 / 10.0;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: if this bin is far below the mean residual,
    // filling it further reduces fragmentation variance.
    let dev = mean_residual - post_residual as f64;
    score -= 0.15 * dev;

    // New-bin candidate handling: opening a new bin is only attractive
    // when no open bin offers a decent fit. Penalize the empty bin
    // mildly so it wins only via its large post_residual when fits are bad.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Late in the stream, slightly prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Perfect-fit bonus when post_residual exactly matches next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: keep it attractive as a baseline, but let tight fits beat it.
    if bin_residual == bin_capacity {
        return 100.0 + 0.05 * open_bins_count as f64;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: this bin becomes exactly full next step
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how little slack remains after that
            let after_next = post_residual - next_item_size;
            score -= 30.0 * (1.0 - after_next as f64 / bin_capacity as f64);
        } else {
            // next item does NOT fit the residual: dead space risk
            let waste = (next_item_size - post_residual) as f64;
            score += 0.6 * waste.min(40.0);
        }
    }

    // Reward tight fits (small post_residual) super-linearly.
    score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Penalize residuals far above the mean residual (fragmentation outlier).
    score += 0.15 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Late in the stream, prefer closing bins tightly (fewer open bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Lookahead (k=2): reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0 + 0.3 * (post_residual - next_item_size) as f64;
        } else {
            // Dead space relative to the next item: penalize proportionally.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Penalize bins whose residual deviates upward from the mean (fragmented space).
    let dev = post_residual as f64 - mean_residual;
    score += 0.08 * dev.abs();

    // Early in the stream: encourage consolidation into few bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 20.0 * (1.0 - progress) * (open_bins_count as f64 / 10.0);

    // New-bin candidate: only attractive when open bins are nearly full on average
    // or this item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        let mean_fullness = 1.0 - mean_residual / bin_capacity as f64;
        let item_pressure = item_size as f64 / bin_capacity as f64;
        let urgency = mean_fullness * 1.2 + item_pressure * 0.5;
        score += 150.0 - 200.0 * urgency.min(1.0);
        // Late in stream, opening fresh bins is more acceptable.
        score -= 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    let fit = item_size as f64 / cap;
    let nxt = next_item_size as f64 / cap;

    // Base: penalize leftover space, more strongly late in the stream
    let mut score = pr * (1.0 + 1.5 * progress);

    // Smooth non-linear coupling: quadratic dead-space penalty
    score += 40.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits (small post_residual) with cubic interaction
    score -= 60.0 * (1.0 - pr_norm).powi(3) * fit;

    // Lookahead coupling: favor residuals that can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 * nxt * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 15.0 * nxt * (1.0 - pr_norm);
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 45.0 * (1.0 + progress);
    }

    // Mild pressure against accumulating many open bins
    score += 0.5 * open_bins_count as f64 * pr_norm;

    // Mean residual alignment: prefer bins near the mean residual (balanced packing)
    score += 10.0 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: make it slightly unattractive unless residual is truly huge
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) - 20.0 * progress * fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quality depends on residue class
    let class = post_residual / 10; // integer division threshold: 0..10 capacity fractions
    match class {
        0 => score -= 25.0,                 // near-perfect fit
        1 => score -= 10.0,                 // good
        2 => score += 0.0,
        3 => score += 4.0,                  // awkward 30-39 zone
        4 => score -= 3.0,                  // 40-49 fits mid items
        5 => score += 2.0,
        6 => score += 5.0,
        7 => score += 8.0,                  // 70-79 mostly dead
        _ => score += 12.0,                 // 80+: nearly empty bin
    }

    // Exact residue-class bonus: post_residual divisible by small harmonics
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0; // aligns with 10-multiple item sizes
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0; // chaining potential
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 {
                score -= 4.0; // leaves harmonic residue again
            }
        } else {
            let waste = next_item_size - post_residual;
            score += (waste as f64) * 0.15; // next item would not fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening new bins when open bins are underused,
    // but allow it late in stream or when many bins are open
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 20.0 - open_pressure * 2.0 + progress * 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity && next_item_size > item_size {
            score += 3.0; // big next item may prefer a fresh bin
        }
    }

    // Mild preference to fill emptier bins first (balance residuals)
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit is extremely desirable
    if post_residual == 0 {
        score -= 60.0;
    }
    // Post-residual that exactly fits the next lookahead item is a bonus
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }
    // Post-residual that can still fit the next item is mildly rewarded
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += 10.0; // next item cannot reuse this bin's remainder
    }

    // Fit tightness: reward filling a large fraction of the residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, avoid spreading into new ones
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins already exist
        score += 25.0 + 15.0 * pressure;
        // But allow new bin early in stream or when mean residual is low
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    } else {
        // Using an existing bin relieves pressure slightly
        score -= 3.0 * pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize large wasted residual, superlinearly.
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Lookahead: if next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item cannot use the leftover space: penalize dead space.
            score += 0.5 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many fitting bins: mild penalty to prefer tight fits among many options.
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Time horizon: early on, prefer compacting (low post_residual);
    // later, be more tolerant to avoid leaving many nearly-empty bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0;

    // Global residual state: if mean residual is large, prefer filling bins
    // with large residuals (reduce fragmentation).
    score -= 0.1 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive if nothing fits well; penalize
    // opening a new bin when open bins exist and item is small.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 12.0 + 0.2 * open_bins_count as f64;
        if item_size <= 30 {
            score += 10.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 15.0; // pair potential: item + next fill a fresh bin
        }
    }

    // Perfect closure reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual (tight fit preferred)
    let mut score = pr;

    // Non-linear polynomial coupling of post-residual with stream progress:
    // late in the stream, small residuals matter more (dead space is permanent)
    let progress_weight = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += progress_weight * 30.0 * norm_pr * norm_pr;

    // Penalize residuals that cannot fit the lookahead item (wasted capacity)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            let gap = (nxt - pr) / cap;
            score += 25.0 * gap * (1.0 + progress);
        } else {
            // reward leaving room exactly for the next item
            let fit_quality = 1.0 - ((pr - nxt) / cap).powi(2);
            score -= 12.0 * fit_quality * (1.0 - progress * 0.5);
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 * (1.0 - norm_pr);
    }

    // Slight penalty when many bins are open and this creates tiny residual
    let tiny = if pr < 10.0 { (10.0 - pr) / 10.0 } else { 0.0 };
    score += tiny * 15.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // New-bin candidate: make it attractive only when open bins fit poorly
    if bin_residual == bin_capacity {
        let avg_tightness = 1.0 - (mean_residual / cap);
        score = cap * (0.5 + 0.5 * avg_tightness) + 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 1000.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead-space severity classes
    let pr = post_residual;
    let cls = (pr * 5) / bin_capacity; // 0..=4 capacity-fraction classes
    let cls_penalty: [f64; 5] = [0.0, -2.0, 0.0, 3.0, 8.0];
    score += cls_penalty[(cls as usize).min(4)];

    // Modulo-10 harmonic class: residuals divisible by 10 pair well with
    // typical item granularities; odd prime residuals are less reusable.
    if pr % 10 == 0 && pr > 0 {
        score -= 1.5;
    }
    if pr > 0 && pr % 10 != 0 && pr < 10 {
        score += 4.0; // tiny unusable sliver
    }

    // Lookahead coupling: does post_residual fit the next item exactly or well?
    if next_item_size > 0 {
        if next_item_size <= pr {
            let nxt = next_item_size as f64;
            let gap = (pr as f64 - nxt) / cap;
            if next_item_size == pr {
                score -= 6.0; // perfect harmonic match
            } else if (pr - next_item_size) % 10 == 0 {
                score -= 3.0; // same granularity class
            } else {
                score += gap * 10.0; // mismatch penalty grows with leftover
            }
        } else {
            // next item won't fit here: residual becomes dead space unless small
            if pr < 20 {
                score += 2.0;
            } else {
                score += 1.0;
            }
        }
    }

    // Last-chance bonus: only fitting bin, avoid opening a new bin needlessly
    if fitting_bins_count == 1 {
        score -= 4.0;
    }

    // New-bin candidate handling: neutral baseline, slightly worse than a
    // decent fit but attractive when all open bins are tight.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + (post_residual as f64) * 0.1;
        if fitting_bins_count == 0 {
            score -= 10.0; // must open a new bin
        } else if open_bins_count > 0 && mean_residual < item_size as f64 * 1.2 {
            score -= 3.0;
        }
    }

    // Progress pressure: later in stream, prefer compacting into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever fit a future
    // item (min item size 1, but practically small gaps < ~10 are near-waste)
    // are heavily penalized with a non-linear blow-up.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if post_residual < 10 {
            score += 40.0 * (10.0 - pr); // unusable sliver: strong penalty
        } else if post_residual < 20 {
            score += 8.0; // hard-to-fill zone
        }
        // Perfect fit bonus
        if post_residual == 0 {
            score -= 60.0;
        }
    }

    // Reward bins whose residual is close to the item (tight packing)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 20.0 * tightness;

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins when mean
    // residual is already high; encourage consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it's a straggler bin — using it consolidates dead space.
    let dev = mean_residual - bin_residual as f64;
    score += 0.25 * dev;

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 25.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Next item cannot use this gap: penalize creating blocking dead space
        score += 6.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it
    // moderately attractive only when existing bins would create bad gaps.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin (grows with open bins, shrinks late)
        score = 55.0 + 1.2 * open_bins_count as f64 - 20.0 * progress;
        if item_size >= 60 {
            score -= 25.0; // big items deserve a fresh bin
        }
        if post_residual < 10 {
            score += 10.0; // fresh bin will be left with a sliver
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: lower post_residual is already favored by the base term.

    // 2-step lookahead: if next item fits exactly into the post-residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit in the leftover: penalize proportional to dead space.
        score += 6.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Perfect match bonus (post_residual == next_item_size).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 8.0;
    }

    // Penalize large leftovers that no typical item can use (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 5.0; // tiny unusable sliver
    }

    // Compare against mean residual: placing in a bin with residual far above mean
    // helps balance; placing in a below-mean bin wastes scarce space.
    let cap = bin_capacity as f64;
    let mean_gap = (bin_residual as f64 - mean_residual) / cap;
    score -= 4.0 * mean_gap;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate: mildly penalize so we only open when fits are bad.
    if bin_residual == bin_capacity {
        score += 3.0;
        // But if lookahead suggests next item also needs fresh space, ease penalty.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 4.0;
        }
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (1.0 - (post_residual as f64 / cap));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post-residual non-linearly.
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.4) * 0.05;
    } else {
        score -= 20.0; // perfect fit is excellent
    }

    // Lookahead: if next item fits in the post-residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.25 * (next_item_size as f64);
        }
        // Penalize leaving a residual that is a "dead zone": too small for
        // the next item but not tiny either.
        let gap = post_residual as f64;
        if gap > 0.0 && (next_item_size as f64) > gap {
            let dead = (gap / bin_capacity as f64).powf(0.5);
            score += 8.0 * dead;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
        if post_residual <= 5 {
            score -= 10.0; // near-perfect last chance
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // many bins are open with fragmented space, or the fit here is awful.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: keep it moderately high.
        score = bin_capacity as f64 * 0.9;
        // If current bin's fit is poor (large waste), new bin becomes better.
        let waste = (bin_residual - item_size) as f64;
        if waste > 30.0 {
            score -= (waste - 30.0) * 0.6;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
        // Many open bins with low mean residual: consolidation is preferable.
        if mean_residual < 30.0 && open_bins_count > 2 {
            score += 15.0;
        }
    }

    // Mild penalty when this bin is much emptier than average (save big
    // residuals for large future items).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.05;
    } else {
        score += (-dev) * 0.05;
    }

    // Small early-stream exploration term: encourage diverse placements early.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 2.0 * (open_bins_count.min(20) as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer small post-residual, with non-linear scaling
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth coupling: as stream progresses, tighten fit preference more aggressively
    score += 20.0 * progress * norm_pr * norm_pr * cap;

    // Reward near-perfect fills smoothly (post_residual near 0)
    score -= 15.0 * (1.0 - norm_pr).powi(6) * (1.0 + progress);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    }

    // Penalize when many bins could fit (less urgency) via smooth term
    score += 0.5 * (fitting_bins_count as f64).ln().max(0.0);

    // Lookahead: reward residual that matches next item size (smooth kernel)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let diff = (norm_pr - nx).abs();
        score -= 10.0 * (-8.0 * diff * diff);
        // Penalize leaving residual just barely below next item
        score += 8.0 * (norm_pr / (nx + 0.01)) * (norm_pr < nx) as i32 as f64 * norm_item;
    }

    // Mild penalty when bin residual deviates from mean residual (balance)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Slight bias toward filling existing bins vs opening new ones as stream grows
    score += 0.02 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact fill is ideal.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Penalize dead space: residuals too small for any item (1..=100) are wasted.
    // Harmonic classes: classify post_residual by modulo-10 bands.
    let cls = post_residual / 10; // integer division threshold class
    match cls {
        0 => {
            // post_residual in 0..10 -> dead space if >0
            if post_residual > 0 { score += 60.0; }
        }
        1 => { score += 25.0; }  // 10..20: only tiny items fit
        2 => { score += 10.0; }  // 20..30
        3 => { score += 4.0; }
        4 => { score -= 2.0; }
        _ => { score -= 5.0; }   // large residual: flexible bin
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // next item leaves a good class afterward
        let next_post = post_residual - next_item_size;
        if next_post >= 10 { score -= 5.0; }
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        // dead space blocks next item anyway
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins are plentiful
    // and mean residual is high; encourage when residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 20.0 * (1.0 - progress);
        if mean_residual > item_size as f64 * 1.5 {
            score += 40.0; // plenty of usable space exists elsewhere
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
    }

    // Mild pressure against bin proliferation.
    score += open_bins_count as f64 * 0.5;

    // Exact-fit modulo harmony: item divides capacity nicely.
    if bin_capacity % item_size == 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the minimum item (1) are fine,
    // but residuals in the awkward mid-range are likely to become unusable.
    if post_residual > 0 && post_residual < item_size {
        score += 12.0; // creates a gap smaller than the incoming item
    }
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // tiny gap is nearly perfect packing
    }

    // Reward tight fits (low post_residual relative to item size).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill_ratio;

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 3.0;
        } else {
            score += 5.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few open bins, opening a new bin is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * progress);

    // Prefer bins whose residual deviates from the mean residual in a useful way:
    // a bin with residual close to item_size is a great target.
    let gap_to_mean = (bin_residual as f64 - item_size as f64).abs();
    score += gap_to_mean * 0.05;

    // New-bin candidate: make it attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - fill_ratio.min(1.0));
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        if next_item_size > 0 && bin_capacity as f64 - mean_residual < next_item_size as f64 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: exact match of next item into post_residual is excellent
    if next_item_size > 0 && next_item_size <= post_residual {
        // reward proportional to how snugly the next item fits
        let slack_after_next = post_residual - next_item_size;
        score -= 12.0 - (slack_after_next as f64) * 0.15;
    } else if next_item_size > 0 {
        // next item cannot follow here: penalize dead space a bit more
        score += 3.0;
    }

    // Prefer bins whose residual is close to mean_residual (balanced packing),
    // penalize outliers that create fragmented space
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.08;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Penalize creating tiny unusable residuals (< 10 can't fit any item)
    if post_residual < 10 && post_residual > 0 {
        score += 6.0;
    }

    // Late in the stream, prefer tighter fills to close bins out
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * (0.15 * progress);

    // New-bin candidate: mildly discouraged so it's chosen only when
    // existing bins would create bad fits (its post_residual is large,
    // which naturally scores higher unless rewards flip it)
    if bin_residual == bin_capacity {
        score += 5.0 + mean_residual * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize relative waste quadratically.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            // Extra reward for a near-perfect two-item packing.
            let pair_waste = (bin_capacity as f64 - (item_size as f64 + next_item_size as f64)).max(0.0);
            if item_size + next_item_size <= bin_capacity && post_residual >= next_item_size {
                score -= 10.0 * (1.0 - pair_waste / bin_capacity as f64);
            }
        } else if next_item_size > post_residual && post_residual > 0 {
            // Dead space relative to lookahead item: penalize unusable gap.
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 5.0 * gap as f64 / 10.0;
            } else {
                score += 5.0 + 0.3 * (gap as f64 - 10.0);
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer it when the fit into any open bin is poor,
    // or when many open bins already have large residuals (fragmentation).
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: its post_residual is huge, so subtract
        // to keep it competitive; but add a mild cost of opening bins.
        score -= 20.0;
        score += 3.0 * (open_bins_count as f64).sqrt();
        // If current item is small, a fresh bin wastes capacity — penalize.
        if item_size < bin_capacity / 2 {
            score += 0.4 * (bin_capacity / 2 - item_size) as f64;
        }
    }

    // Global fragmentation pressure: if mean residual is high, prefer
    // consolidating into existing bins (penalize opening new space).
    let frag = mean_residual / bin_capacity as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * frag;
    }

    // Time horizon: early in the stream, be conservative (favor tight fits
    // less aggressively); late in the stream, squeeze every bin.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * fill_ratio;

    // Prefer bins that are already partially filled vs many near-empty ones.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, scaled by stream progress (late stream penalizes waste more)
    let mut score = pr * (0.9 + 0.4 * progress);

    // Smooth non-linear coupling: quadratic dead-space penalty on normalized residual
    score += 25.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits with smooth exponential-like term
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * tightness;

    // Interaction with mean residual: prefer bins below mean residual (compact usage)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev.abs();

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: penalize if post residual can't fit next item (smooth decay)
    if next_item_size > 0 {
        let gap = next_item_size as f64 - pr;
        if gap > 0.0 {
            score += 5.0 * (gap / cap) * (1.0 + progress);
        } else {
            score -= 3.0 * (-gap / cap);
        }
    }

    // Mild penalty for many open bins to encourage consolidation early
    score += 0.5 * (open_bins_count as f64).ln() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward low post_residual aggressively.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Harmonic classes: classify residual space by capacity fractions.
    let cap = bin_capacity as f64;
    let res_frac = post_residual as f64 / cap;
    // Dead-space classes: residuals in (0,10] are nearly unusable (min item 1, but typical items larger).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - res_frac * 10.0);
    }

    // Modulo-style classification of post_residual against common item sizes.
    let cls = post_residual % 25;
    if cls == 0 && post_residual > 0 {
        score -= 12.0; // divisible residual likely reusable by 25-class items
    } else if cls > 20 {
        score += 6.0;
    }

    // Next-item lookahead: bonus if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.8;
        } else {
            // next item won't fit here; slight penalty scaled by waste
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer it only when current bins would leave big waste
    // or when the item is huge relative to the residual.
    if bin_residual == bin_capacity {
        // baseline for fresh bin: its post_residual = cap - item_size
        // penalize opening new bins late in the stream slightly
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 + 10.0 * progress;
        if fitting_bins_count > 0 && (bin_residual - item_size) >= 40 {
            score += 20.0; // plenty of room existed elsewhere; discourage new bin
        }
    }

    // Mild pressure to consolidate: fewer open bins -> favor existing bins.
    score += open_bins_count as f64 * 0.05;

    // Deviation from mean residual: prefer bins already below mean (tighter bins).
    score += (post_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals below the minimum item size (1..10) are pure waste.
    let min_item = 10u32;
    if post_residual > 0 && post_residual < min_item {
        score += 60.0 * (min_item - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else {
        // Smooth tightness reward: tighter fits preferred among usable residuals.
        score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 30.0;
        } else if gap < min_item {
            score += 15.0; // next item would create dead space here
        } else {
            score -= 10.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this bin's leftover; mild penalty for stranding space.
        score += 8.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading; but for
    // the new-bin candidate this term is neutralized below.
    if bin_residual != bin_capacity {
        score += 0.6 * open_bins_count as f64;
        // Prefer bins below mean residual (consolidate into emptier bins? no:
        // prefer filling fuller bins => residual below mean is a fuller bin).
        let dev = mean_residual - bin_residual as f64;
        score -= 0.4 * dev;
    } else {
        // New-bin candidate: penalize opening a new bin, more so late in stream
        // and when many bins already exist; relax when open bins are all nearly full.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 55.0 + 30.0 * progress + 0.5 * open_bins_count as f64;
        if mean_residual < 12.0 {
            // All open bins nearly full: opening a new bin is reasonable.
            score -= 45.0;
        }
        // If item is large relative to mean residual, new bin may be best.
        if (bin_capacity as f64 - mean_residual) < item_size as f64 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 45.0 / (1.0 + lookahead_gap);
        // Perfect 2-step chain fit: strong bonus.
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // Penalize leaving dead space smaller than the smallest plausible item (1..100).
        if post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 25.0;
        }
    } else {
        // Last item: prefer tightest fit.
        score -= 20.0;
    }

    // Reward bins tighter than the mean residual (good fillers).
    score -= 0.35 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when existing bins fit decently.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 10.0 * progress;
        // Still allow new bin if item leaves a very awkward residual in any existing bin.
        if post_residual < 10 {
            score -= 30.0;
        }
    }

    // Small bonus for high occupancy relative to capacity.
    score -= 12.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness).powi(3);

    // Penalize dead space that can never be used by typical items.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // tiny slivers are wasted but harmless-ish; slight bonus
    } else if post_residual >= 10 && post_residual <= 40 {
        score += 6.0 * (1.0 - (post_residual as f64 - 10.0) / 30.0); // moderately usable
    } else if post_residual > 80 {
        score += 10.0; // large residual is fine, keep flexible
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 5.0; // next item won't fit here; slight penalty for blocking
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Time horizon: late in the stream, prefer consolidating (avoid new bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 20.0 + 30.0 * progress;
        // But if open bins are very fragmented (high mean residual), a new bin is okay.
        if mean_residual > 50.0 && open_bins_count > 3 {
            score -= 25.0;
        }
    } else {
        score -= 5.0 * progress;
    }

    // Mild preference for bins with residuals near the item size (perfect-ish fit family).
    let diff = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * diff;

    // Encourage balancing residual pool when many bins are open.
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (low post residual), with non-linear shaping
    let mut score = pr as f64;

    // Smooth polynomial coupling with stream progress:
    // late in the stream, dead space becomes more costly -> penalize large x more
    let tight_penalty = x * x * (1.0 - progress) + x * x * x * progress;
    score += 40.0 * tight_penalty;

    // Reward near-perfect fits via smooth bump: exp-like quadratic dip
    let bump = -60.0 * (1.0 - x) * (1.0 - x) * (1.0 - progress * 0.5);
    score += bump;

    // Lookahead coupling: if next item fits the post residual, reward this bin
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = (nx <= pr as f64) as i32 as f64;
        let slack = (pr - nx).max(0.0) / cap;
        score += fit_next * (-30.0 + 40.0 * slack * slack);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Mild diversity pressure: many open bins with high mean residual -> prefer filling emptier bins less
    score += 0.05 * (open_bins_count as f64).ln() * (x - mean_residual / cap);

    // New-bin candidate (empty bin): make it unattractive unless residual would be huge elsewhere
    if bin_residual == bin_capacity {
        score += 15.0 + 30.0 * progress - (x * 0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band does it land in?
    let pr = post_residual;
    let band = match pr {
        0 => 0u32,
        1..=10 => 1,
        11..=25 => 2,
        26..=50 => 3,
        51..=75 => 4,
        _ => 5,
    };

    // Reward tight fits strongly (post residual near zero is ideal).
    score -= (cap - (pr as f64 - cap / 2.0).abs()) * 0.05;

    // Dead-space penalty: tiny unusable leftovers (1..=10) are the worst outcome.
    if band == 1 {
        score += 40.0;
    } else if band == 2 {
        score += 12.0;
    }

    // Perfect fit bonus.
    if pr == 0 {
        score -= 60.0;
    }

    // Harmonic complementarity: does the next item fit exactly / well into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0; // exact complement chain
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / cap);
            // residue class coupling: next item leaves a "good" remainder again
            let nr = pr - next_item_size;
            if nr % 10 == 0 || nr % 25 == 0 {
                score -= 8.0;
            }
        } else {
            // next item cannot fit here; penalize leaving a large awkward gap
            score += 10.0 + (pr as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: prefer it only when nothing fits harmonically.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mean-residual drift: favor bins close to the mean residual (balanced packing),
    // unless it's a tight fit situation.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Modulo threshold on post_residual: multiples of 10 and 25 are classic
    // "harmonic" leftovers that combine well with typical item sizes.
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 6.0;
    }
    // Odd awkward residues get a small penalty.
    if pr % 2 == 1 && pr > 0 {
        score += 3.0;
    }

    // Late-stream consolidation: as the stream progresses, favor filling existing
    // bins harder to avoid many near-empty bins at the end.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    // A residual below the minimum item size (1..=100, min observed ~10) is dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Moderate dead space (10..20) is often unusable too; penalize proportionally.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (exact or near-exact fill).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * (1.0 - tightness * 4.0).max(-1.0) * (1.0 - tightness);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    // New-bin candidate has bin_residual == bin_capacity; push its score up
    // as open_bins_count grows.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 8.0 + (open_bins_count as f64) * 1.5;
        // But if current bin would leave a bad gap and next item could use a fresh bin, soften.
        if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size && next_item_size <= bin_capacity {
            score -= 10.0;
        }
    } else {
        // Slight bonus for keeping bins consolidated when few bins are open.
        score -= (bin_capacity as f64 - mean_residual).max(0.0) * 0.02;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // If next item fits in post_residual, mild reward; if not, mild penalty for stranding space.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size < post_residual {
            score -= 3.0;
        } else {
            score += 4.0;
        }
    }

    // Late in the stream, consolidation matters more (no future to amortize new bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Reward near matches: next item fits into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Tighter slack is better; decay with slack size.
        score -= 40.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
    } else if next_item_size > 0 {
        // Next item will NOT fit here: penalize wasted residual relative to next item.
        let waste = (next_item_size - post_residual) as f64;
        score += 10.0 + 0.5 * waste;
    }

    // Compare post residual against mean residual of open bins.
    // Leaving less than average residual is good (compact packing).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize creating very small dead space that likely nothing can use
    // (items are >= 1; dead space < 10 is nearly unusable under typical ranges).
    if post_residual < 10 && post_residual > 0 {
        score += 20.0;
    }

    // Perfect closure of the bin is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Mild penalty for opening a new bin when other bins fit, growing with stream progress.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + 20.0 * progress;
    }

    // Slight preference to fill emptier bins first when many bins are open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer near-perfect fits: strong reward for small post_residual.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 60.0 * (1.0 - fit_ratio).powf(6.0);

    // Penalize dead space that cannot host the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0 + 0.25 * (next_item_size - post_residual) as f64;
        } else {
            // Reward bins whose leftover can still hold the next item.
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild penalty for opening a new bin when many bins are open with slack.
    if bin_residual == bin_capacity {
        let mean_slack = mean_residual.max(0.0);
        score += 10.0 + 0.5 * mean_slack + 0.3 * open_bins_count as f64;
        // Late in the stream, opening new bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 12.0 * progress;
    }

    // Reward using bins whose residual is already small (consolidation).
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness * tightness;

    // Discard bins whose residual becomes an awkward prime-like leftover.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear shaping.
    let mut score = pr;

    // Quadratic/cubic coupling of post_residual with stream progress:
    // late in the stream, small residuals matter more (avoid dead space).
    let progress_weight = 0.5 + 2.0 * t * t;
    score += progress_weight * norm_pr * pr;

    // Smooth penalty for awkward residuals near half-capacity (hard to fill),
    // modeled as a smooth bump around 0.5.
    let bump = (std::f64::consts::PI * norm_pr).sin().abs();
    score += 12.0 * bump * norm_pr * (1.0 - norm_pr) * 4.0;

    // Reward bins whose residual stays compatible with the next item (k=2 lookahead).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            // Prefer exact-ish compatibility; smooth falloff with slack.
            score -= 10.0 * (-slack / cap).exp();
        } else {
            // Next item won't fit here: mild penalty, stronger late in stream.
            score += 5.0 + 10.0 * t;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin (smooth in fitting_bins_count).
    let last_chance = 1.0 / fitting_bins_count.max(1) as f64;
    score -= 15.0 * last_chance * (0.5 + t);

    // Prefer bins with residuals below the mean (fill the emptier-relative bins),
    // smooth interaction with progress.
    let dev = (mean_residual - bin_residual as f64) / cap;
    score += 8.0 * dev * (0.5 + t);

    // Mild preference for keeping few open bins early; relax later.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - t);

    // New-bin candidate: penalize opening a new bin unless it's genuinely better,
    // with smooth relaxation as stream progresses.
    if bin_residual == bin_capacity {
        score += 20.0 - 10.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "small
    // dead-space" classes are rewarded; large awkward leftovers are penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional fill of the bin after placement
    let fill = 1.0 - pr / cap;
    score -= 40.0 * fill * fill; // reward tight fills quadratically

    // Modulo-class logic on post_residual: leftovers in [1..10] are near-perfect;
    // leftovers divisible by 10 pair well with typical item granularities.
    let pr_u = post_residual;
    if pr_u == 0 {
        score -= 25.0; // perfect bin
    } else if pr_u < 10 {
        score -= 15.0; // tiny dead space, excellent
    } else {
        // harmonic classes via integer division: class = pr / 10
        let class = pr_u / 10;
        let in_class = pr_u % 10;
        // classes 1-3 (10..39) are usable; higher classes waste space
        let class_penalty = match class {
            1 => -6.0,
            2 => 0.0,
            3 => 4.0,
            4 => 9.0,
            5 => 14.0,
            _ => 20.0,
        };
        score += class_penalty;
        // within-class offset: multiples of 5 are more reusable
        if in_class == 0 {
            score -= 3.0;
        } else if in_class <= 5 {
            score -= 1.0;
        } else {
            score += 1.0;
        }
    }

    // Lookahead coupling: does the leftover accommodate the next item?
    if next_item_size > 0 {
        if next_item_size <= pr_u {
            let slack = pr_u - next_item_size;
            score -= 6.0 + (slack as f64).min(30.0) * 0.15;
            // exact fit for next item is ideal
            if slack == 0 {
                score -= 8.0;
            }
        } else {
            score += 5.0; // leftover unusable by next item
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // are all poor fits. Penalize fresh bins, more so as stream progresses.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 45.0 + 25.0 * progress + 2.0 * open_bins_count as f64;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already "used up"; finishing it off is good.
    let diff = mean_residual - pr;
    if diff > 0.0 {
        score -= (diff * 0.25).min(12.0);
    } else {
        score += (-diff * 0.1).min(8.0);
    }

    // Late-stream consolidation: near the end, prefer closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // If the leftover cannot plausibly fit even the smallest future item,
    // it is dead space -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - (post_residual as f64) / 20.0);
    }

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // strongly favor this bin; if next item nearly fits, mild bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 - slack * 0.3;
    } else if next_item_size > post_residual && next_item_size <= bin_residual {
        score += 5.0; // this bin would break the chain for the next item
    }

    // Perfect-fit chain: bin residual equal to next item closes bin cleanly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Open-bin pressure: discourage opening new bins when open bins are plentiful
    // and still have room; the new-bin candidate (residual == capacity) gets
    // penalized proportionally to open_bins_count.
    if bin_residual == bin_capacity {
        score += 10.0 + 3.0 * open_bins_count as f64;
        // But if this is the last-chance bin scenario, opening is fine.
        if fitting_bins_count <= 1 {
            score -= 15.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it
    // over wasting it / opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below mean
    // (tighter bins get filled first, keeping large gaps open).
    score += 0.3 * ((bin_residual as f64) - mean_residual).max(-50.0).min(50.0);

    // Progression: early in the stream keep flexibility (favor tight fits less aggressively),
    // late in the stream maximize consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - (post_residual as f64) / capacity_f);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: strongly reward near-zero post residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 200.0 / (post_residual as f64).sqrt();
    }

    // 2-step lookahead: reward when the next item exactly fills the new post residual.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 400.0; // chain: this bin then next item = perfect pair
        } else if next_item_size <= post_residual {
            score -= 100.0 / (1.0 + diff);
        } else {
            // next item cannot fit here; penalize large dead space relative to next item
            score += 0.5 * (next_item_size as f64 - post_residual as f64).min(50.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is terrible.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 250.0 - 100.0 * progress;
        // allow new bin if item is huge relative to mean residual (poor fits everywhere)
        if item_size as f64 > mean_residual + 20.0 {
            score -= 150.0;
        }
    }

    // Mild preference for bins tighter than average (best-fit flavor).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Penalize leaving dead space smaller than the smallest plausible next item.
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Reward exact or near-exact fits heavily.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: penalize if the next item cannot fit in the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0; // chain-friendly placement
        } else {
            let wasted = (next_item_size as f64 - post_residual as f64).min(100.0);
            score += wasted * 0.3;
        }
    }

    // New-bin candidate: prefer opening a new bin only when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; offset by how bad the best alternative likely is.
        score += 60.0;
        if mean_residual > item_size as f64 * 1.5 {
            score -= 40.0; // open bins are roomy anyway; new bin less costly
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 15.0; // fresh bin can host a pair
        }
    }

    // Global state: many open bins -> consolidate, penalize spreading.
    score += open_bins_count as f64 * 0.5;

    // Time horizon: early stream, be flexible; late stream, fill aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * (1.0 - tightness);

    // Deviation from mean residual: prefer bins whose residual is near mean (balanced use),
    // but slightly prefer emptier bins when mean is low.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // smooth non-linear coupling of post_residual with stream progress
    let coupling = norm_pr * (1.0 - norm_pr);
    score -= 40.0 * coupling * (0.5 + progress);

    // penalize large dead space late in stream (quadratic in norm_pr)
    score += 60.0 * norm_pr * norm_pr * progress;

    // reward tight fits more strongly as stream advances
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 12.0 * (nx / cap);
        } else {
            score += 8.0 * (nx / cap) * progress;
        }
    }

    // mean residual interaction
    score += 0.1 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Leftovers in low classes (small, unusable)
    // are penalized; leftovers that form clean fractions of capacity are rewarded.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Integer-division thresholds on post_residual (harmonic classes of 25).
    let class = post_residual / 25; // 0..=4
    match class {
        0 => score += 18.0,                       // dead space < 25: worst
        1 => score += 6.0,                        // 25..49: moderate waste
        2 => score -= 4.0,                        // 50..74: half bin, still useful
        3 => score -= 8.0,                        // 75..99: excellent leftover
        _ => score -= 12.0,                       // near-full bin kept tight
    }

    // Modulo coupling: residuals divisible by 10 pair well with the typical
    // item granularity, reward them.
    if post_residual % 10 == 0 {
        score -= 3.0;
    } else if post_residual % 5 == 0 {
        score -= 1.5;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
            // harmonic match: next item leaves a class-3/4 residual again
            let next_post = post_residual - next_item_size;
            if next_post / 25 >= 3 {
                score -= 3.0;
            }
        } else {
            // next item cannot use the leftover: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let tight_pressure = mean_residual < item_size as f64 * 1.2;
        if tight_pressure && fitting_bins_count == 0 {
            score -= 10.0;
        } else {
            score += 14.0; // default: prefer filling existing bins
        }
    }

    // Tight fits are always good: reward small post residual directly.
    score -= (bin_capacity - post_residual) as f64 * 0.02;

    // Slight stream-progress adaptation: later in the stream, be more
    // conservative about leaving mid-range residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if class == 1 {
        score += 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small gaps: residual too small for typical future items.
    let dead_zone = 20.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 3.0;
    }
    // Reward tight fits.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 12.0;

    // Reward using the last remaining bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: prefer new bins when too many open bins exist.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64 / total_items.max(1) as f64);
    score += pressure * 0.5;

    // Lookahead: bonus if post_residual can still fit the next item.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 {
        score += 4.0;
    }

    // Slight preference for bins with below-mean residual (fill emptier bins less, tighter bins more).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate: neutral-ish baseline with mild penalty so it's chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score += 8.0 + pressure * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next item size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for perfect match (post_residual == next_item_size)
        score -= 60.0 * (-gap / 8.0).exp();
        // Penalize post_residual slightly larger than next item (unusable sliver)
        if post_residual > next_item_size && post_residual < next_item_size + 4 {
            score += 25.0;
        }
        // Bonus if next item still fits with a reasonable remainder
        if post_residual >= next_item_size {
            score -= 8.0;
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Next item won't fit: penalize more for large dead space
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - post_residual as f64) * 0.4;

    // Penalize creating tiny unusable residual (< 10 min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Late in stream: prefer compacting into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress;

    // New-bin candidate (empty bin): penalize unless current bin residuals are all poor
    if bin_residual == bin_capacity {
        score += 20.0;
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that nothing can ever use: post_residual below minimum item size.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: bonus if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: penalize opening new bins unless residual is very small.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is attractive only when current bin residual is large waste.
        score += 8.0 + 6.0 * progress - 14.0 * waste;
        if mean_residual > item_size as f64 * 1.5 {
            score += 6.0; // plenty of room elsewhere; avoid new bins
        }
    }

    // Slight preference for bins below mean residual (consolidating space).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // Dynamic time horizon: late in the stream, prefer filling bins more completely.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Many open bins: encourage consolidation into existing bins.
    score += 0.15 * open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap;

    // Base: prefer tight fits (small post_residual), smooth polynomial
    let mut score = 4.0 * x * x * x + 2.0 * x * x + x;

    // Non-linear coupling with stream progress: later in stream, demand tighter fits
    score += 3.0 * x * (0.5 + progress) * (1.0 - x);

    // Penalize bins far from mean residual (non-linear deviation penalty)
    let dev = (post - mean_residual) / cap;
    score += 1.5 * dev * dev * cap * 0.01;

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 4.0 * (1.0 - x);
    }

    // Lookahead: reward leaving space compatible with next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let slack_fit = (post - nx) / cap;
            score -= 2.0 * (1.0 - slack_fit) * (1.0 - x);
        } else {
            score += 1.0 + 0.02 * (nx - post);
        }
    }

    // Many open bins: slight penalty to discourage bin proliferation
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: keep it competitive only when current fits are poor
    if bin_residual == bin_capacity {
        score += 6.0 - 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo classes over capacity
    let pr = post_residual as f64;
    let class = (post_residual % 10) as f64;
    // Residuals in "harmonic" classes (multiples of 5/10) are more reusable
    if class == 0.0 {
        score -= 6.0;
    } else if class == 5.0 {
        score -= 3.0;
    } else {
        score += class * 0.4; // odd/awkward residues penalized
    }

    // Tight fit reward: post_residual small relative to smallest possible item
    if post_residual <= 10 {
        score -= 12.0;
    } else if post_residual < 20 {
        score -= 4.0;
    }

    // Perfect fit: massive reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead space penalty: large post_residual that no plausible item can use
    if post_residual > 60 {
        score += (post_residual as f64 - 60.0) * 0.3;
    }

    // Lookahead coupling: can the next item fit into the post residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // prefer leaving exactly-compatible space (harmonic match)
            let gap = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - gap / cap);
            if (post_residual - next_item_size) % 5 == 0 {
                score -= 3.0;
            }
        } else {
            score += 5.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor
    if bin_residual == bin_capacity {
        // base reluctance to open a new bin
        score += 18.0;
        // but if mean residual across open bins is too small for the item's
        // harmonic class, opening a fresh bin is attractive
        if (mean_residual as u32) < item_size + 5 {
            score -= 30.0;
        }
        // late in the stream, prefer consolidating rather than opening bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // many open bins: discourage opening another
        score += open_bins_count as f64 * 1.5;
    }

    // Favor bins that are already fairly full (less fragmentation overall)
    let fill = 1.0 - bin_residual as f64 / cap;
    score -= fill * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize post_residual in the "unusable gap" zone
    // where nothing from the typical size range can ever fill it.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Worst gaps: small but nonzero (1..=15) -> almost certainly dead space.
        if post_residual <= 15 {
            score += 40.0 * (16.0 - gap);
        } else if post_residual <= 30 {
            score += 15.0 * (31.0 - gap);
        }
        // Perfect fit bonus.
        if post_residual == 0 {
            score -= 60.0;
        }
        // Residual that exactly matches next item is valuable.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize if next item cannot fit into the post-residual (creates sequencing risk),
        // but only mildly since lookahead is limited.
        if next_item_size > post_residual && post_residual > 0 {
            score += 8.0;
        }
        // Reward residuals large enough to host any plausible next item.
        if post_residual >= 80 {
            score -= 10.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when few fitting bins exist
    // (last-chance bin should be strongly preferred to avoid opening new bins).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }
    // Mild penalty proportional to number of open bins to encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    // Progress-aware: early in the stream, tolerate spreading; late, tighten packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is close to the mean (balanced packing) slightly.
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    // New-bin candidate: only attractive when it beats terrible fits; make it moderately costly.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if current item is large, a fresh bin is fine (large items fit anywhere anyway).
        if item_size >= 60 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // 2-step lookahead: strongly reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item fills the remainder
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * fill;
        } else {
            // next item cannot fit here; penalize leftover dead space
            let waste = (next_item_size - post_residual) as f64;
            score += 0.3 * waste.min(40.0);
        }
    } else {
        // last item: prefer filling bins as tightly as possible
        score += post_residual as f64 * 0.5;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new bin unless current bin would leave a bad fit
    if bin_residual == bin_capacity {
        // new bin candidate: only attractive if item is large or fits poorly elsewhere
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 15.0 - 20.0 * large_item;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // good pair potential in fresh bin
        }
    }

    // Slight preference to keep number of open bins low as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = post / cap;

    // Base: prefer small post-residual (tight fit), non-linearly.
    let mut score = 10.0 * (1.0 - (1.0 - fit).powi(2)) * fit.powi(2) * 4.0 + post;

    // Smooth polynomial coupling of fit with stream progress:
    // early on, waste matters less; late, demand very tight fits.
    let tightness_weight = 1.0 + 3.0 * progress * progress;
    score += tightness_weight * post * post / cap;

    // Reward using nearly-full bins (low post residual) more as stream advances.
    score -= 20.0 * progress * (1.0 - fit) * (1.0 - fit);

    // Last-chance bonus: only bin that fits => strong incentive to use it.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Many fitting bins => this bin is less critical; slight penalty for
    // leaving large dead space when alternatives exist.
    if fitting_bins_count > 1 {
        score += 5.0 * fit * (open_bins_count as f64).ln();
    }

    // Lookahead: if next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = post - nxt;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here: penalize wasting residual it can't use
            score += 3.0 * (nxt - post) / cap;
        }
    }

    // Mean residual context: bins far from the mean residual get a mild
    // smoothing penalty, encouraging balanced residual distribution.
    let dev = (post - mean_residual).abs() / cap;
    score += 2.0 * dev * dev;

    // New-bin candidate (empty bin): should only win when it genuinely helps,
    // i.e. early stream or item is huge relative to residuals.
    if bin_residual == bin_capacity {
        let new_bin_bias = 8.0 * (1.0 - progress) + 0.5 * (item_size as f64);
        score += new_bin_bias;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 define "usable" classes.
    // Small post-residuals (dead space) are penalized super-linearly.
    let pr = post_residual as i64;
    let residue = (pr % 10) as f64;

    // Dead-space penalty: residual below the smallest item (<=10) is pure waste.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward exact harmonic fits (residue 0 => residual divisible into 10-blocks).
    if residue == 0.0 {
        score -= 8.0;
    } else if residue >= 5.0 {
        score += residue * 0.6; // odd half-block residue slightly penalized
    } else {
        score -= residue * 0.4;
    }

    // Integer-division threshold: can post_residual host the next item?
    if next_item_size > 0 {
        let ni = next_item_size as i64;
        if pr >= ni {
            // Chain bonus scaled by how tightly the next item nests.
            let tightness = 1.0 - (pr - ni) as f64 / bin_capacity as f64;
            score -= 12.0 * tightness;
            // Harmonic pair: (post_residual + next) divisible by 10 => smooth packing.
            if (pr + ni) % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // Next item won't fit here; penalize proportionally to overflow gap.
            score += (ni - pr) as f64 * 0.5;
        }
    } else {
        // Last item: just minimize waste.
        score += 0.0;
    }

    // Item size classes (integer division by 20: small/medium/large/xxl).
    let item_class = item_size / 20;
    match item_class {
        0 => score -= 2.0,   // small items: prefer filling gaps
        1 => score += 0.0,
        2 => score += 1.5,   // large items: slight preference for emptier bins
        _ => score += 3.0,   // xxl items: prefer near-empty bins
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when current fit is poor
    // or the stream is early and open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = if post_residual < 10 { 18.0 } else { 0.0 };
        let crowding = (open_bins_count as f64 / 8.0).min(3.0);
        score = 40.0 - poor_fit - crowding + 10.0 * progress;
    }

    // Mild normalization by mean residual state.
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward residual that can still host a typical future item.
    if post_residual >= 25 {
        score -= 8.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual,
    // this placement is doubly valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open-bin pressure: discourage spreading across many bins; but relax
    // pressure late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.5 - 1.5 * progress);

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild alignment with mean residual: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when existing bins would create
    // dead space or are congested.
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward a perfect or near-perfect fit (minimal dead space).
    if post_residual <= 2 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // this is an ideal chaining placement — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 3 {
            score -= 40.0;
        } else if post_residual < next_item_size && post_residual >= 10 {
            // dead space that the next item cannot use; penalize proportionally
            score += 0.5 * (next_item_size as f64 - post_residual as f64).min(50.0);
        }

        // If the next item fits loosely (leaves small remainder after next step),
        // give a mild bonus for keeping chains alive.
        if post_residual >= next_item_size && (post_residual - next_item_size) <= 8 {
            score -= 15.0;
        }
    }

    // Penalize bins whose residual is far above the mean (hoarding space in
    // scattered bins) unless it's a new empty bin.
    if bin_residual < bin_capacity {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.15 * dev;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer opening a new bin only when current residuals
    // are already tight (little usable space left overall).
    if bin_residual == bin_capacity {
        let avg_tightness = 1.0 - (mean_residual / bin_capacity as f64);
        // When open bins are mostly full, a new bin is fine; when they have
        // plenty of room, discourage spreading items across many bins.
        score = 40.0 - 30.0 * avg_tightness;
        if fitting_bins_count > 0 && mean_residual > 20.0 {
            score += 10.0; // discourage new bin when space exists
        }
        // Early in stream, keep bin count low.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Mild pressure to consolidate into fewer bins as stream progresses.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 20.0 {
            score += (20.0 - dead) * 2.5;
        }
    } else {
        // Perfect closure is excellent.
        score -= 40.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 25.0;
        } else {
            score += 8.0 * (next_item_size as f64 - post_residual as f64).min(40.0) / 40.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 3 {
        // Many alternatives: be picky, penalize mediocre fits.
        score += 5.0 * (1.0 - fit_ratio);
    }

    // Global state: many open bins with high mean residual -> prefer consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 4 && mean_residual > 30.0 {
        score += 0.15 * mean_residual * (0.5 + progress);
    }

    // Time horizon: early on, allow new bins; late, consolidate aggressively.
    let new_bin_penalty = 20.0 + 60.0 * progress;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
        // Opening a new bin is fine if the item is large and nothing fits well.
        if item_size > 70 && fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // early on, prefer tight fits; later, tolerate slack more.
    let slack_penalty = pr * pr / cap;
    let progress_weight = 1.0 - progress * progress;
    score += 0.8 * slack_penalty * progress_weight;

    // Reward near-perfect fits (smooth kernel around zero post-residual).
    let fit_kernel = (-(pr / cap) * (-(pr / cap) * 6.0)).exp();
    score -= 6.0 * fit_kernel;

    // Lookahead coupling: bonus if next item fits exactly into post_residual.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let diff = pr - next_item_size as f64;
        score -= 4.0 * (-(diff / cap) * 8.0).exp();
    } else if next_item_size > 0 {
        score += 1.5 * (next_item_size as f64 - pr) / cap;
    }

    // Penalize last-chance avoidance: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // New-bin candidate: discourage opening a new bin unless residuals are tight.
    if bin_residual == bin_capacity {
        let mean_tightness = mean_residual / cap;
        score += 2.0 + 6.0 * (1.0 - mean_tightness) * (1.0 - progress);
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.02 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes of common
    // item sizes (10..80 stream => residuals cluster around multiples of 10/20).
    let class = (post_residual % 10) as f64;
    let class20 = (post_residual % 20) as f64;

    // Reward residuals that land exactly on harmonic boundaries (0, 10, 20 ...)
    // since future items of typical sizes can fill them perfectly.
    if class == 0.0 {
        score -= 6.0;
    } else {
        score += class * 0.9; // penalize off-class dead space
    }
    if class20 == 0.0 {
        score -= 3.0;
    }

    // Integer-division thresholds: small post_residual = tight, efficient fit.
    let tight = post_residual / 10; // number of full 10-slots left
    if tight == 0 {
        score -= 10.0; // nearly perfect closure
    } else if tight <= 2 {
        score -= 4.0;
    } else if tight >= 6 {
        score += 3.0; // large leftover: wasteful placement
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward; if next item cannot fit any residual we leave, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 14.0;
        } else if next_item_size <= post_residual {
            let nxt_class = (post_residual - next_item_size) % 10;
            if nxt_class == 0 { score -= 8.0; } else { score += nxt_class as f64 * 0.5; }
        } else {
            // next item won't fit here regardless; mild penalty if we leave big gap
            score += (post_residual as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when current fit is bad
    // (huge post_residual) or stream is early with few bins open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = post_residual as f64; // = capacity - item_size for new bin
        let mut new_bin_score = 55.0 - fit_quality * 0.35;
        if open_bins_count == 0 { new_bin_score -= 40.0; }
        if progress < 0.15 { new_bin_score -= 5.0; }
        if next_item_size > 0 && next_item_size <= post_residual { new_bin_score -= 6.0; }
        score = score.max(new_bin_score);
        score = new_bin_score + (score - new_bin_score) * 0.2; // damp existing-bin advantage when new bin is good
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score -= (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty for unusable dead space: gaps too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 1000.0;
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Penalize leaving a gap that cannot host the lookahead item in this bin,
    // slightly worse when the next item would otherwise need a new bin anyway.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: discourage spreading across many bins; favor filling existing ones.
    score += open_bins_count as f64 * 2.0;

    // Mild attraction toward bins tighter than the mean residual (denser bins first).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: neutral base so it wins only when all open bins score badly.
    if bin_residual == bin_capacity {
        score = 250.0 + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: minimize wasted space, but with a twist for perfect fits.
    if post_residual == 0 {
        // Perfect fill: extremely desirable.
        score -= 1000.0;
    } else {
        // 2-step lookahead: reward when the next item exactly fits the leftover space.
        if next_item_size > 0 {
            let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
            if diff == 0.0 {
                // Next item will perfectly consume the residual: superb chaining.
                score -= 800.0;
            } else if next_item_size as u32 <= post_residual {
                // Next item can still fit: mild reward proportional to tightness.
                score -= 100.0 - diff * 0.5;
            } else {
                // Next item cannot use the leftover: penalize dead space growth.
                score += (next_item_size as f64 - post_residual as f64) * 0.3;
            }
        }

        // Penalize residuals that are too small to ever be useful (min item size ~1, but small slivers are risky).
        if post_residual < 10 {
            score += 60.0;
        }

        // Compare against mean residual across open bins: prefer bins already tighter than average.
        let pr = post_residual as f64;
        if pr < mean_residual {
            score -= (mean_residual - pr) * 0.4;
        } else {
            score += (pr - mean_residual) * 0.4;
        }

        // Last-chance bin: if this is the only fitting bin, strongly prefer using it
        // over opening a new bin (unless the fit is terrible).
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 150.0;
            // Extra urgency late in the stream.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score -= 100.0 * progress;
        }

        // Late-stream consolidation: favor filling existing bins rather than opening new ones.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 50.0 * progress * (bin_residual != bin_capacity) as i32 as f64;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it moderately
    // attractive only when no open bin gives a decent fit (post_residual large elsewhere).
    if bin_residual == bin_capacity {
        // Neutral-ish baseline: slightly worse than a good fit, better than a bad one.
        score = 55.0;
        if next_item_size > 0 && next_item_size as f64 > item_size as f64 * 1.5 {
            // Next item much larger: opening a fresh bin is attractive.
            score -= 40.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 6.0 * tightness * tightness * (item_size as f64);

    // Penalize dead space: residuals too small to plausibly hold future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual fits the next item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 4.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 {
        // Penalize leaving a residual that cannot host the next item.
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Time horizon: early in the stream, be more liberal about opening new bins
    // (better long-term packing); late, prefer filling existing bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: cheap early, expensive late.
        score = score * 0.5 + (1.0 - t) * 5.0 + t * 40.0;
    }

    // Global state: many open bins with high mean residual -> prefer filling them.
    if open_bins_count > 0 {
        score += (open_bins_count as f64).sqrt() * 1.5;
        score -= (mean_residual / cap) * 4.0;
    }

    // Mild bonus for perfectly filling a bin.
    if post_residual == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: penalize wasted space, smoothly
    let mut score = x;

    // Non-linear coupling: wasted space matters more as stream progresses
    let waste_curve = x * x * (1.0 + 3.0 * progress) - x * x * x * (2.0 * progress);
    score += 4.0 * waste_curve;

    // Tight fits rewarded more strongly early (fill bins), but near-perfect fits always good
    let tightness = (1.0 - x).powi(3);
    score -= 2.5 * tightness * (1.0 - 0.5 * progress);

    // Last-chance bin: strongly prefer using it when few alternatives
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 - progress * 0.5);
    } else {
        // mild bonus when many bins compete (keep flexibility)
        score += 0.15 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: reward leaving room compatible with next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let compat = (x - ns / cap).abs();
        score += 1.2 * compat * compat;
        // exact compatibility bonus
        score -= 1.0 * (-8.0 * compat).exp() * (1.0 - progress * 0.3);
    }

    // Prefer bins below mean residual slightly (consolidate space)
    score += 0.4 * ((pr as f64 - mean_residual) / cap).clamp(-1.0, 1.0);

    // Opening a new bin: penalize mildly unless current fit is bad
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        let badness = x; // new bin => post_residual large => large waste if item small
        score += 1.5 + 2.0 * badness * badness - 2.0 * (1.0 - x).powi(4);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1)
    // are impossible, but tiny gaps (1..=10) are practically unusable.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0; // hard penalty for creating dead space
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Tightness reward: fraction of residual consumed by the item.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate logic: opening a fresh bin is only attractive when
    // the current bin would leave a bad gap AND the next item could use
    // the fresh space well.
    if bin_residual == bin_capacity {
        // Base mild penalty so we prefer decent existing fits.
        score += 8.0;
        // If placing here creates a dead gap, prefer a fresh bin.
        if post_residual > 0 && post_residual <= 10 {
            score -= 55.0;
        }
        // If the next item fits exactly into a fresh bin after this one,
        // opening a new bin is very attractive.
        if next_item_size > 0 && next_item_size <= bin_capacity.saturating_sub(item_size) {
            score -= 15.0;
        }
        // Pressure: with many open bins, avoid proliferation.
        score += open_bins_count as f64 * 0.5;
    }

    // Mild open-bin pressure: prefer denser bins when many bins are open.
    score += open_bins_count as f64 * 0.3;

    // Prefer bins whose residual is close to the mean (balanced packing),
    // slightly scaled by stream progression.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0 * (post_residual as f64 - mean_residual).abs() * 0.1;

    // Lookahead: if the next item fits exactly in post_residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 && post_residual <= 10 {
        score += 20.0; // next item can't use this dead gap
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect match with the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual > next_item_size {
            // Next item fits after this placement; reward small leftover slack.
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize proportionally to the mismatch.
            let miss = (next_item_size - post_residual) as f64;
            score += 4.0 * (miss / bin_capacity as f64);
        }
        // Coupling with mean residual: a bin whose post-residual deviates
        // strongly from the mean residual is less useful as a buffer.
        let dev = (post_residual as f64 - mean_residual).abs();
        score += 0.5 * dev;
    } else {
        // Last item: prefer tightest fit as usual.
        score += 0.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Penalize opening a new bin when existing bins could absorb the item,
    // especially early in the stream when consolidation matters most.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 + 10.0 * (1.0 - progress);
        // A new bin is acceptable if the item leaves a residual that likely
        // matches the next item (seed a useful bin).
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 14.0;
        }
    }

    // Slight penalty for leaving tiny unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual, but avoid tiny useless slivers.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < 10 {
        score += 25.0; // dead space below min item size
    } else {
        // prefer smaller post-residual quadratically
        score += (post_residual as f64 / bin_capacity as f64).powi(2) * 20.0;
    }

    // Lookahead: if next item fits the post-residual exactly or well, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 40.0;
            } else if gap < 10 {
                score -= 15.0;
            } else {
                score += gap as f64 * 0.3;
            }
        } else {
            // next item won't fit here; penalize if post-residual becomes dead space
            if post_residual < 10 {
                score += 15.0;
            }
        }
    } else {
        // last item: strongly prefer perfect fill
        score -= post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only open a new bin when open bins fit poorly.
    if bin_residual == bin_capacity {
        // base penalty so new bins aren't opened frivolously
        score += 45.0;
        // more open bins with slack -> stronger preference to reuse
        score += open_bins_count as f64 * 2.0;
        // if this is the only fitting bin (none open), new bin is fine
        if fitting_bins_count == 1 {
            score -= 45.0;
        }
        // late in stream, prefer closing out with new bins for big items
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item_size > 70 {
            score -= 20.0 * progress;
        }
    }

    // Global state: if mean residual is high, encourage using fullest bins (largest residual gap)
    score -= (bin_residual as f64 - mean_residual) * 0.4;

    // Prefer bins whose residual is close to item size (minimize waste ratio)
    let waste_ratio = post_residual as f64 / bin_residual.max(1) as f64;
    score += waste_ratio * 30.0;

    // Time horizon: early in stream, be conservative about tight fits that fragment space
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual < 10 && progress < 0.5 {
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: prefer tight fits (post_residual small); late stream: tolerate slack.
    let norm_pr = pr / cap; // in [0,1)
    let p = progress;
    // smooth progress-dependent weighting of residual cost
    let w = 1.0 + 0.8 * p * p - 0.4 * p;
    score += w * cap * norm_pr * norm_pr * 2.0;

    // Reward near-perfect fills strongly (smooth quadratic bonus).
    let tightness = 1.0 - norm_pr;
    score -= 6.0 * tightness * tightness * tightness;

    // Last-chance bin: strong smooth reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 4.0 * (1.0 - p);
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        if pr >= nxt {
            score -= 5.0 * (1.0 - gap / cap);
        } else {
            score += 2.0 * gap / cap;
        }
    }

    // Penalize bins far from mean residual (fragmentation, smooth term).
    let dev = (pr - mean_residual) / cap;
    score += 1.5 * dev * dev * cap;

    // Mild penalty for too many open bins, smoothed by progress.
    score += 0.05 * open_bins_count as f64 * (0.5 + p);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10 / 20 define
    // how "usable" the leftover space is for future items (sizes 1..100).
    let post = post_residual as i64;
    let nxt = next_item_size as i64;

    // Perfect fit reward: strong subtraction.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: leftover too small for typical items is wasted.
    if post > 0 && post < 10 {
        score += 60.0;
    }

    // Harmonic residue classes: leftover congruent to 0 mod 10 is highly
    // reusable (many item sizes sum to multiples of 10).
    let r10 = post % 10;
    if r10 == 0 && post > 0 {
        score -= 25.0;
    } else if r10 <= 3 {
        score += 8.0 * (3 - r10) as f64;
    }

    // Integer-division thresholds on post_residual: classify leftover into
    // usable bands (>=50 half bin, >=25 quarter bin).
    if post >= 50 {
        score -= 15.0;
    } else if post >= 25 {
        score -= 5.0;
    } else if post > 0 {
        score += 10.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // this is a chained perfect fit — reward heavily.
    if nxt > 0 {
        if nxt == post {
            score -= 400.0;
        } else if nxt < post {
            // reward if post residual remains in a good class after next item
            let post2 = post - nxt;
            if post2 % 10 == 0 {
                score -= 40.0;
            }
            if post2 >= 10 {
                score -= 10.0;
            }
        } else {
            // next item cannot use this bin's leftover; slight penalty if
            // leftover is small (dead space locked in).
            if post > 0 && post < 20 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let base = 40.0 + 30.0 * progress;
        score += base;
        // But if mean residual across open bins is tiny (all bins nearly
        // full), opening fresh space is fine.
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 80.0;
        }
        // If next item is large, a fresh bin gives flexibility.
        if nxt >= 70 {
            score -= 20.0;
        }
    }

    // Prefer tighter bins overall: closeness of fit (small post_residual
    // relative to item size) rewarded.
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= 20.0 * tightness;

    // Mild pressure to consolidate: more open bins -> prefer filling existing.
    score += 0.5 * open_bins_count as f64;

    // Deviation from mean residual: bins far below mean are "tighter",
    // favor them slightly.
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for any plausible
    // future item (items >= 1, but small slivers < 10 are near-unusable) are
    // heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Penalize gaps that cannot fit the lookahead item but could have.
    if next_item_size > 0 && post_residual < next_item_size && post_residual < next_item_size + 5 {
        score += 15.0;
    }

    // Reward exact or near-exact fits.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward bins whose residual was already tight (efficient packing).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current bin
    // would leave a large dead gap. Base penalty plus pressure from open bins.
    if bin_residual == bin_capacity {
        score += 45.0 + 3.0 * open_bins_count as f64;
        // But if item is large and leaves big residual, opening fresh is fine.
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 25.0;
        }
        // Few open bins and early stream: opening is cheap.
        if open_bins_count < 3 {
            score -= 15.0;
        }
    }

    // Open-bin pressure: many open bins -> consolidate, prefer tight fits more.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Late in the stream, dead space matters more (less chance to fill it).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for bins below mean residual (more room to offer).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }

    // Penalize residuals that are too small to be useful later (dead space).
    let min_useful = 10u32;
    if post_residual < min_useful {
        score += 30.0;
    }

    // If next item fits in the post residual, reward; otherwise penalize slightly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            score += 8.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) nonlinearly.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Penalize dead space: residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: bonus if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            score += 8.0;
        }
    } else {
        // Last item: strongly prefer filling existing bins.
        score -= 30.0 * tight;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 22.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // New-bin candidate logic: only attractive when current fit is poor
    // or open bins are quite full on average.
    if bin_residual == bin_capacity {
        let mean_tightness = 1.0 - mean_residual / (bin_capacity as f64);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (post_residual as f64) / (bin_capacity as f64) > 0.45;
        if poor_fit || mean_tightness > 0.75 {
            score -= 15.0 + 10.0 * mean_tightness + 8.0 * progress;
        } else {
            score += 20.0;
        }
    }

    // Mild penalty for proliferating bins late in the stream.
    score += 0.4 * open_bins_count as f64 * (0.5 + step_index as f64 / (total_items.max(1) as f64));

    // Prefer using bins with larger residual slightly (first-fit-like bias).
    score -= 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual
    let t = progress;
    // smooth polynomial interaction: residual utility grows/shrinks over stream
    let coupling = prn * prn * (1.0 - t) * 30.0 - prn * t * 10.0;
    score += coupling;

    // Penalize residuals that can't fit the next item (dead space), smoothly
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 8.0 + 0.05 * pr;
    } else if next_item_size > 0 {
        // reward exact-ish fit for next item
        let gap = (pr - next_item_size as f64).abs();
        score -= (1.0 - gap / cap) * 6.0;
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Slight preference for bins tighter than average residual
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * 3.0;

    // New-bin candidate: mildly penalize opening a new bin unless residuals are large
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes of 10
    let class = (post_residual / 10) as f64;
    score += class * 3.0; // larger coarse class => worse (already in base score, amplify)

    // Tight fit reward: post_residual small relative to item
    if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // Lookahead coupling: penalize residuals that next item cannot use
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits perfectly: reward closeness
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 30.0;
            } else {
                score -= 15.0 * (1.0 - gap as f64 / post_residual as f64);
            }
        } else {
            // dead space for next item
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // default mild penalty; waived if no open bin fits or item is small
        let mut penalty = 15.0 + mean_residual * 0.1;
        if fitting_bins_count == 0 {
            penalty = -50.0; // forced new bin
        }
        if item_size > bin_capacity / 2 && open_bins_count > 0 && mean_residual < item_size as f64 {
            penalty = -10.0; // big item, poor fits elsewhere
        }
        score += penalty;
    }

    // Modulo harmonic: residuals that are multiples of common item sizes are reusable
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 5.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Progress coupling: late in stream, consolidate more aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.2 * progress;

    // Slight preference to fill bins with larger mean residual (balance)
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps that are too small for typical items are wasted.
    // Treat gaps below a "useful threshold" as increasingly costly (quadratic).
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * (dead_threshold - post_residual as f64) * 2.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 8.0;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual <= 5 {
            score -= 10.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.6 * (1.0 - progress * 0.5);

    // Mean-residual coupling: if this bin is far below mean residual, it is a good
    // "garbage absorber"; if far above mean, its residual is precious.
    let dev = (bin_residual as f64) - mean_residual;
    score += dev * 0.15;

    // Lookahead: if the next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            score -= 4.0;
        } else {
            // next item cannot fit here; slight penalty for stranding space.
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // New-bin candidate: opening a fresh bin is only attractive when no open bin fits
    // well. Base it on the mean residual of open bins: if open bins are mostly full
    // (low mean residual), a new bin is reasonable; otherwise discourage it.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 0.55 + mean_residual * 0.4 - (fitting_bins_count as f64) * 3.0;
        // Late in the stream, slightly prefer reusing bins.
        score += progress * 10.0;
        // If next item is large and open bins are fragmented, new bin helps.
        if next_item_size >= 60 && mean_residual < 30.0 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match: next item fits snugly after this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / 40.0).max(0.0);
    }

    // Penalize if next item cannot fit here afterwards (dead-end risk)
    if next_item_size > 0 && next_item_size > post_residual {
        score += 15.0;
    }

    // Reward tight fits relative to current residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Prefer bins with residual below mean residual (consolidate small leftovers)
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin unless it enables a perfect future pairing
    if bin_residual == bin_capacity {
        let perfect = next_item_size > 0 && (bin_capacity - item_size) == next_item_size;
        if perfect {
            score -= 50.0;
        } else {
            score += 20.0;
        }
    }

    // Late in stream: be more conservative, close out bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: baseline equals a fresh bin's residual (post_residual == bin_capacity).
    // Make it attractive only when the item is a poor fit for existing bins.
    if bin_residual == bin_capacity {
        // Slight preference for reusing existing bins by default.
        score += 5.0;
        // If this is the only bin that can fit (or very few fitting bins), opening
        // a new bin is cheap insurance: reduce its score so it competes well.
        if fitting_bins_count <= 1 {
            score -= 12.0;
        }
        // Large items waste less when placed in a fresh bin if existing residuals are tight.
        let tight = mean_residual < item_size as f64 * 0.6;
        if tight && open_bins_count > 0 {
            score -= 4.0;
        }
        // Late in the stream, avoid proliferation of near-empty bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.9 {
            score += 15.0 * progress;
        }
        return score;
    }

    // Existing bin: reward tight fits (low post_residual).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.05;

    // Penalize dead space that the next item cannot use.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Dead space relative to lookahead: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.3;
        } else {
            // Space usable by the next item: reward.
            score -= 2.0;
        }
        // Perfect pairing: post_residual exactly fits next item.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else {
        // Last item: pure best-fit, minimize waste.
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Mild penalty for leaving residuals in the awkward 1..=5 range (unusable for
    // items >= 10 typically, but guard for small items).
    if post_residual >= 1 && post_residual <= 5 {
        score += 6.0;
    }

    // Coupling with global state: when many bins are open with large mean residual,
    // prefer consolidating into bins below-mean residual (fill the fullest bins).
    if open_bins_count > 1 {
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: quadratic penalty on leftover space (waste grows super-linearly).
    let mut score = 10.0 * norm_post * norm_post + 2.0 * norm_post;

    // Smooth non-linear coupling: waste matters more as the stream progresses
    // (early on, flexibility is valuable; late, consolidation dominates).
    let urgency = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 30.0 * urgency * norm_post * norm_post;

    // Perfect fit reward: subtract strongly as post_residual approaches 0.
    score -= 8.0 * (1.0 - norm_post).powi(6);

    // Lookahead coupling: reward if the next item fits the post residual,
    // penalize if it nearly fits but not quite (dead space trap).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 4.0 * (1.0 - (nxt / (post + 1.0))).powi(2);
        } else {
            let gap = (nxt - post) / cap;
            score += 6.0 * (1.0 - gap.min(1.0)) * (1.0 - gap.min(1.0));
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly, but less when open bins are crowded
    // (mean residual low) or many bins would fit poorly.
    if bin_residual == bin_capacity {
        let crowd = mean_residual / cap;
        score += 12.0 * (1.0 - urgency) + 5.0 * crowd;
        if fitting_bins_count == 0 {
            score -= 20.0; // no open bin fits: opening is fine
        }
    }

    // Slight preference for tighter existing bins among equals.
    score += 0.01 * (bin_residual as f64 - post) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by capacity fractions.
    let frac = post_residual as f64 / cap;
    let class = (frac * 8.0).floor() as i32; // 8 harmonic classes of residual capacity

    // Reward tight fits; extra reward when post_residual falls into a "usable" class
    // (small enough to likely be filled by small items, or exactly zero).
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else {
        match class {
            0 => score -= 60.0,          // residual <= 12.5% : nearly full
            1 => score -= 30.0,          // <= 25% : still good
            2 => score -= 10.0,          // <= 37.5% : moderate
            3 => score += 15.0,          // <= 50% : awkward zone
            4 => score += 25.0,          // <= 62.5% : dead-space risk
            5 => score += 20.0,          // <= 75%
            6 => score += 10.0,          // <= 87.5%
            _ => score += 5.0,           // nearly empty bin
        }
    }

    // Integer-division thresholds: reward when post_residual can hold the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        // chain bonus scaled by how snugly the next item would fit
        let snug = (post_residual - next_item_size) as f64;
        score -= 40.0 - (snug / cap) * 40.0;
    } else if next_item_size > 0 {
        // next item cannot use the leftover: penalize proportionally to waste
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        // opening fresh is fine early or when very few bins fit the item
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (fitting_bins_count as f64).recip();
        score = 150.0 + progress * 50.0 - pressure * 40.0;
        if item_size > 70 {
            score -= 30.0; // big items fit best in fresh bins
        }
    }

    // Mild penalty for spreading across too many open bins
    score += open_bins_count as f64 * 0.5;

    // Tie-break with mean residual: prefer bins whose residual is near the mean
    // (keeps the bin population homogeneous for future harmonic matching)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never be filled again
    // (below the minimum item size) are the worst outcome.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // perfect fill, but keep it as a reward instead
        score -= 1000.0; // net zero base, handled below
    }

    // Base score: strongly reward small (but usable) post residuals.
    // Perfect fit (post_residual == 0) is ideal.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let tightness = 1.0 - pr / cap; // 1.0 when tight, 0.0 when empty
    score = (cap - pr) * 0.5; // larger residual => larger score => less preferred

    // Non-linear penalty for "awkward" small gaps that most items won't fit:
    // gaps in (0, 10) are dead space; gaps in [10, 20) are risky.
    if pr > 0.0 && pr < 10.0 {
        score += 500.0; // unusable dead space
    } else if pr >= 10.0 && pr < 20.0 {
        score += 120.0; // risky small gap
    } else if pr >= 20.0 && pr < 35.0 {
        score += 30.0; // moderate risk
    }

    // Reward if the lookahead item can fit into the resulting residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            // Reward proportional to how well the next item fills the gap.
            let fill_ratio = nxt / pr;
            score -= 40.0 * fill_ratio;
        } else {
            // Next item won't fit: this residual may become dead space.
            score += 15.0;
        }
    }

    // Open-bin pressure: when many bins are open, discourage opening/spreading;
    // favor packing into existing bins.
    let obp = open_bins_count as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += obp * (0.5 + 0.5 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below mean
    // (i.e., fuller bins) to consolidate packing.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.8;
    } else {
        score += (res - mean_residual) * 0.4;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Base new-bin cost grows with the number of open bins.
        score = 80.0 + obp * 6.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // nothing fits, must open
        } else if fitting_bins_count == 1 {
            score += 40.0; // one last-chance bin exists; prefer it
        }
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 30.0; // future items are large; a fresh bin helps
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead: strongly reward exact / near-exact match with next item ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chain: next item exactly fills this bin
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item still fits; reward proportionally to how tight the chain is
            let chain_tightness = next_item_size as f64 / post_residual as f64;
            score -= 10.0 + 40.0 * chain_tightness;
        } else {
            // Next item cannot fit here: penalize, worse if dead space is large
            let dead = post_residual as f64;
            score += dead * 0.3;
        }

        // Combined two-item coupling: item + next filling the bin nearly perfectly
        let two_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
        if two_fill > 0.95 {
            score -= 25.0 * (two_fill - 0.95) / 0.05;
        }
    } else {
        // Last item: minimize residual as much as possible
        score -= 20.0;
    }

    // --- Relative to mean residual across open bins ---
    // Placing into a bin whose residual is below average is a tight fit -> reward
    let rel = if mean_residual > 0.0 { bin_residual as f64 / mean_residual } else { 1.0 };
    score -= (1.0 - rel) * 15.0; // tight bins (small residual) get bonus
    score += (rel - 1.0).max(0.0) * 10.0; // loose bins penalized

    // --- Last-chance bin: if this is the only fitting bin, avoid opening a new one ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when current item leaves a large,
        // unusable residual in existing bins or few bins fit the item.
        let waste_pressure = post_residual as f64 / bin_capacity as f64;
        score = 55.0 + waste_pressure * 30.0;
        if fitting_bins_count <= 1 {
            score -= 20.0; // no good alternative -> prefer new bin
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin can also chain the next item
        }
        // Late in the stream, slightly discourage accumulating open bins
        score += progress * 5.0;
    }

    // --- Waste-avoidance: penalize residuals that are too small for any item ---
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Penalize small-but-not-zero dead space (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 5.0;
        }
        // Perfect chaining: post_residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer bins with low residual relative to the mean (fill emptier bins first
    // keeps larger residuals available for big future items).
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        score += 6.0 * (rel - 1.0);
    }

    // Time horizon: early in the stream, be conservative (favor new bins for
    // large items to keep flexibility); late, pack aggressively.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * t * (item_size as f64 / bin_capacity as f64);

    // Discourage spreading across too many open bins when item is small.
    if item_size < 40 && open_bins_count > 3 {
        score -= 3.0;
    }

    // New-bin candidate: baseline cost; open only if no open bin scores lower.
    if bin_residual == bin_capacity {
        score += 14.0 + 10.0 * (1.0 - t);
        // If item is large relative to capacity, opening fresh is less bad.
        score -= 6.0 * (item_size as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let x = pr / cap; // normalized post residual
    let t = progress;
    // Smooth interaction: dead-space penalty grows quadratically as stream progresses.
    let dead = x * x * (1.0 + t) * (2.0 + t * t);
    score += dead * cap * 0.5;

    // Early stream: prefer tight fits mildly; late stream: strongly prefer tight fits.
    let tightness = 1.0 - x;
    score -= tightness * (1.0 + 3.0 * t) * cap * 0.3;

    // Penalize opening new bins when good fits exist (new-bin candidate has pr == bin_residual == cap).
    if (bin_residual as f64 - cap).abs() < 1e-9 {
        score += cap * (0.6 + 2.0 * t);
    }

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= cap * (0.4 + 0.8 * t);
    }

    // Lookahead: bonus if next item fits the resulting residual.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 0.35 * cap * (1.0 - t * 0.5);
    } else if next_item_size > 0 {
        score += 0.15 * cap * (0.5 + t);
    }

    // Mild penalty proportional to number of open bins to encourage consolidation.
    score += (open_bins_count as f64) * 0.4 * (0.5 + t);

    // Deviation from mean residual: prefer bins near the mean (balanced packing).
    score += ((pr - mean_residual) / cap).abs() * cap * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into
    // "small" classes (post_residual < 10) are nearly perfect fits.
    if post_residual == 0 {
        score -= 50.0; // perfect fill, ideal
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Integer-division thresholds: residual divisible by common item classes
    // (10, 20, 25, 50) is more likely to be reusable later.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 6.0;
        }
        if post_residual % 25 == 0 {
            score -= 4.0;
        }
        if post_residual % 50 == 0 {
            score -= 4.0;
        }
    }

    // Lookahead coupling: if next item exactly fits post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual && post_residual - next_item_size < 10 {
            score -= 15.0;
        } else if next_item_size > post_residual {
            // next item cannot use this residual; penalize large leftover
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is bad
    // (large dead space) or many bins are already open with slack.
    if bin_residual == bin_capacity {
        score += 45.0;
        // more open bins with high mean residual -> new bin less attractive
        score += open_bins_count as f64 * 2.0;
        score += (mean_residual / bin_capacity as f64) * 30.0;
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 20.0;
    }

    // Mild penalty for wasting capacity fraction: dead space above half capacity
    if post_residual > bin_capacity / 2 {
        score += (post_residual - bin_capacity / 2) as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it's smaller than the smallest possible item (1..100 unknown,
    // so treat gaps < ~15 as near-dead, and gaps < next_item_size as unusable for lookahead).
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 15.0 {
        score += (15.0 - gap) * 3.0; // steep penalty for tiny dead gaps
    }
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5; // can't host lookahead item
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Tightness reward: fraction of bin filled by this placement.
    score -= (item_size as f64 / bin_capacity as f64) * 30.0;

    // Open-bin pressure: with many open bins, discourage spreading; favor filling existing bins
    // (new-bin candidate has bin_residual == bin_capacity, so this penalizes it when many bins open).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual == bin_capacity {
        score += pressure * 4.0; // opening a new bin is costly under pressure
    } else {
        score -= pressure * 0.5; // mild reward for using an existing bin
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Deviation from mean residual: prefer bins whose residual is closest to the item
    // (minimal waste relative to fleet average).
    score += (bin_residual as f64 - item_size as f64 - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Post-residual can still host the next item: reward tight-but-viable fits.
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + slack * 0.08);
    } else if next_item_size > 0 {
        // Next item cannot fit here afterwards: penalize dead space growth.
        let dead = (next_item_size - post_residual) as f64;
        score += dead * 0.35;
    }

    // Reward placements that bring post_residual below the smallest item (1),
    // i.e., near-perfect fills, relative to mean residual of open bins.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.25;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.15;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 && post_residual > 0 {
            ((bin_capacity as f64 - item_size as f64) / bin_capacity as f64).abs()
        } else {
            0.0
        };
        // Penalize new bin mildly; allow it when item barely fits existing bins.
        let min_fit_slack = 100u32.saturating_sub(item_size) as f64;
        if min_fit_slack < 15.0 && fitting_bins_count > 1 {
            score += 15.0; // existing bins can take it easily: keep current bins tight
        } else {
            score -= 5.0 + poor_fit * 10.0;
        }
    }

    // Early stream: encourage keeping bins open and consolidating.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 4 && progress < 0.5 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual is the base; amplify small residuals quadratically.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 18.0 * fit_ratio * fit_ratio * (bin_capacity as f64);

    // Penalize leaving residual that is too small to be useful for typical items (dead space).
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += 25.0 * (dead_threshold - post_residual as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: reward placements that leave room for the next item (pairing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // next item fits exactly-ish: reward closeness of post_residual to next_item_size
            let gap = post_residual as f64 - nxt;
            score -= 14.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here: mild penalty for stranding capacity
            score += 6.0 * (nxt - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Prefer filling bins with more residual when many bins are open (consolidation),
    // but prefer low-residual bins when few are open.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.8 * pressure * (bin_residual as f64 - item_size as f64).max(0.0) / bin_capacity as f64;

    // Penalize opening a new bin, more strongly early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 45.0 * (1.0 - 0.5 * progress);
        // Allow new bin if item is huge and nothing tight exists is handled implicitly:
        // a new bin's post_residual = capacity - item is small for big items, lowering base score.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mild global balance: nudge toward bins whose residual is near the mean (avoid extremes).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time-dependent exploration: slightly vary tightness preference over the stream.
    let phase = (progress * std::f64::consts::PI).sin();
    score -= 5.0 * phase * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: penalize wasted residual, with non-linear (quadratic) growth
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Smooth coupling: early in the stream, tolerate residual (future items may fit);
    // late in the stream, tighten packing harder.
    let tightness = 1.0 + progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score *= tightness;

    // Reward tight fits (small post_residual) with a smooth saturating bonus
    let fit_quality = 1.0 - pr_norm;
    score -= fit_quality * fit_quality * 20.0;

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many fitting bins: mild penalty to prefer the best-fit among them (handled by base),
    // but few open bins relative to residual mean suggests spreading is cheap
    let open_f = open_bins_count as f64;
    score += (open_f / (open_f + 5.0)) * 5.0 * pr_norm;

    // Lookahead coupling: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 * (1.0 - pr / (next_item_size as f64 + pr + 1.0));
    } else if next_item_size > 0 {
        // next item won't fit here: penalize leaving a large awkward residual
        score += pr_norm * 8.0;
    }

    // Mean residual coupling: prefer bins whose post-residual stays near the mean (balance)
    let dev = (pr - mean_residual).abs();
    score += dev * 0.3 * (1.0 - progress);

    // New-bin candidate: only attractive when current bins fit poorly
    if bin_residual == bin_capacity {
        score = 60.0 - 10.0 * (1.0 - progress) - (fitting_bins_count as f64) * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by 10 pair well with
    // typical item sizes; small odd residuals are dead space.
    let r = post_residual;
    let class_bonus: f64 = match r {
        0 => -40.0,                       // perfect fill
        x if x % 10 == 0 => -12.0,        // "clean" residual
        x if x < 10 => 30.0,              // unusable sliver
        x if x % 5 == 0 => -4.0,          // half-clean
        _ => 6.0,                         // awkward remainder
    };
    score += class_bonus;

    // Integer-division thresholds: if the NEXT item fits exactly in the
    // post_residual (or a harmonic fraction of it), reward this bin.
    if next_item_size > 0 && next_item_size <= r {
        let fits = r / next_item_size; // how many next items fit
        if r % next_item_size == 0 {
            score -= 20.0 + 5.0 * fits as f64;
        } else if fits >= 1 {
            score -= 8.0 * fits as f64;
        }
    } else if next_item_size > r {
        // next item won't fit here regardless; slight penalty for wasting
        // capacity that could have hosted it
        score += 5.0;
    }

    // Capacity-fraction coupling: penalize leaving post_residual in the
    // "unfillable band" (10..20) since min item is 10.
    if r > 10 && r < 20 {
        score += 15.0;
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer denser bins (low residual relative to mean) early in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (bin_residual as f64 - mean_residual) * 0.15 * (1.0 - progress);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let penalty = if fitting_bins_count == 0 { -10.0 } else { 45.0 };
        score += penalty;
    }

    // Mild pressure to close out nearly-full bins.
    if r <= 5 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (non-linear gap penalty)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 3.0 * post_residual as f64;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits (exact fills)
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward fitting next item exactly into post_residual (lookahead)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size > post_residual {
            score += 12.0; // next item can't use this bin's leftover
        } else {
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score += 6.0; // would create dead space next step
            } else {
                score -= 10.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it over new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 15.0 + 4.0 * open_bins_count as f64;
        // But allow new bin if existing fits are all terrible
        if post_residual >= bin_capacity as f64 - item_size as f64 && item_size >= 60 {
            score -= 10.0;
        }
    }

    // Mild preference for fuller bins relative to mean residual
    score += 0.05 * (mean_residual - bin_residual as f64).max(-30.0).min(30.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual with next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward when the next item exactly fills the leftover space.
        score -= 60.0 / (1.0 + gap);
        // Extra bonus if post_residual is at least the next item size (chain continues).
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Dead space that the next item cannot use: penalize.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: minimize leftover as usual.
        score += 0.0;
    }

    // Compare against mean residual: penalize bins with above-average residual
    // (they waste capacity), reward below-average residual bins.
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        let dev = res - mean_residual;
        score += 0.3 * dev;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (i.e., many fitting bins means we should reuse an existing one).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            score += 30.0; // a single fitting bin exists; prefer it (last chance)
        } else {
            // Several fitting bins: prefer reuse, penalize opening new bin,
            // unless item is large relative to capacity (poor fit anywhere).
            let tightness = item_size as f64 / bin_capacity as f64;
            score += 20.0 - 25.0 * tightness;
        }
    }

    // Mild stream-progression pressure: later in the stream, consolidate more
    // aggressively (avoid leaving many slightly-used bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * progress * (res / bin_capacity as f64);

    // Small penalty scaling with number of open bins to encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = (item_size as f64) / (bin_capacity as f64);
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);

    // Reward tight fits (small post_residual relative to capacity)
    score -= 30.0 * tightness * tightness;

    // Reward high fill ratio of the bin overall
    score -= 20.0 * fill;

    // Lookahead: if the next item fits exactly into the post-residual, big bonus
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // penalize leaving a residual the next item can't use
            score += 8.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Global state coupling: many open bins with large mean residual -> prefer filling existing bins
    let residual_pressure = mean_residual / (bin_capacity as f64) * (open_bins_count as f64).sqrt();
    if bin_residual < bin_capacity {
        score -= 5.0 * residual_pressure;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized when other bins fit the item
        if fitting_bins_count > 0 {
            let poor_fit_elsewhere = fitting_bins_count == 1;
            // Only allow new bin if the sole fitting bin leaves bad post-residual
            let new_bin_score = (bin_capacity - item_size) as f64;
            if poor_fit_elsewhere && post_residual as f64 > new_bin_score * 0.6 {
                score -= 10.0; // allow escape hatch for very bad fits
            } else {
                score += 60.0 + 20.0 * residual_pressure;
            }
        } else {
            score -= 15.0; // must open a new bin
        }
        // Late in the stream, discourage proliferation of bins
        score += 15.0 * progress;
    }

    // Small stochastic-free tie-breaker: prefer bins with residual closest to item+next combo
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0 * (post_residual - next_item_size) as f64 / (bin_capacity as f64);
    }

    // Slight preference to consolidate into bins with below-mean residual (fill emptier-of-space bins? no: fill bins with less residual first)
    if bin_residual < bin_capacity {
        score += 4.0 * (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: mildly prefer tight fits; late stream: strongly punish large residuals.
    let progress_weight = 0.5 + 1.5 * progress;
    score += progress_weight * (pr * pr) / cap;

    // Smooth cubic term: dead space in the "awkward" mid-range is penalized more.
    let x = pr / cap;
    score += 8.0 * x * (1.0 - x) * x;

    // Reward near-perfect fits smoothly.
    score -= 6.0 * (1.0 - x) * (1.0 - x) * (1.0 - x);

    // Last-chance bin: strongly encourage using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Coupling with mean residual: prefer bins whose residual deviates favorably
    // from the fleet mean (using this bin reduces variance).
    let dev = pr - mean_residual;
    score += 0.3 * dev * dev / cap;

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let nx = next_item_size as f64;
        let gap = (post_residual as f64 - nx) / cap;
        score -= 5.0 * (1.0 - gap);
    }

    // New-bin candidate: keep it competitive only when open bins would leave bad fits.
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1
    // Penalize residuals that fall in "unusable" harmonic bands: (0, 10) useless,
    // (10, 20) marginal, etc. Use integer division thresholds.
    let class = post_residual / 10; // 0..10 harmonic class
    let class_penalty = match class {
        0 => -30.0,                    // near-perfect fit
        1 => -10.0,                    // good (fits next small item likely)
        2 => 5.0,                      // awkward band
        3 => 12.0,
        4 => 18.0,
        5 => 22.0,                     // half-full: worst dead-space zone
        6 => 20.0,
        7 => 16.0,
        8 => 12.0,
        9 => 8.0,
        _ => 0.0,                      // empty / near-empty (new bin)
    };
    score += class_penalty;

    // Non-linear tightness reward: quadratic bonus for small post_residual
    score -= 40.0 * (1.0 - frac) * (1.0 - frac) - 40.0;

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining
        } else if next_item_size <= post_residual {
            score -= 15.0 * (post_residual - next_item_size) as f64 / cap;
        } else {
            // next item cannot follow here: slight penalty proportional to waste
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no good existing fit exists
    if bin_residual == bin_capacity {
        // base cost of opening a bin, softened if many bins open / early stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut nb = 45.0;
        nb -= 10.0 * (open_bins_count as f64).ln().max(0.0);
        nb -= 10.0 * (1.0 - progress);
        // if mean residual of open bins is large, opening new bin is wasteful
        nb += (mean_residual / cap).min(1.0) * 20.0;
        // empty bin leaves max residual: apply its own class (0 penalty) but add fixed cost
        score = post_residual as f64 + nb;
    }

    // Mild normalization: prefer bins whose residual is close to item (relative fit)
    if bin_residual > 0 {
        let rel = item_size as f64 / bin_residual as f64;
        score -= 10.0 * rel; // fuller bins (relative) preferred
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    // A gap below the minimum item size (1..100 unknown, use conservative 10)
    // is pure dead space unless it is zero.
    let dead_threshold = 10.0_f64;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        score += 40.0 * (dead_threshold - pr) / dead_threshold;
    }

    // Non-linear penalty on residual: small residuals are fine (tight fit),
    // mid residuals are the worst (wasted capacity nothing may fill).
    let tightness = pr / bin_capacity as f64;
    if tightness > 0.0 && tightness < 0.25 {
        score += 15.0 * (0.25 - tightness);
    }

    // Reward very tight fits (small post_residual) strongly.
    if pr <= 5.0 {
        score -= 20.0;
    } else if pr <= 12.0 {
        score -= 8.0;
    }

    // Open-bin pressure: many open bins -> favor filling existing ones,
    // penalize spreading into new space.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 3.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0;
    } else if next_item_size > 0 && pr > 0.0 {
        // next item won't fit in the gap -> gap is likely dead space
        score += 4.0 * pr / bin_capacity as f64;
    }

    // Early in the stream, allow opening new bins a bit more freely;
    // late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // New-bin candidate: empty bin gets a baseline cost so it only wins
    // when open bins are genuinely poor fits.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.3;
    }

    // Mean residual coupling: when mean residual is high, prefer bins that
    // reduce dispersion (place into bins below mean residual).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = (post_residual - next_item_size) as f64;
        score -= 50.0 + 0.5 * (bin_capacity as f64 - tightness);
    } else if next_item_size > 0 && post_residual > 0 {
        // penalize dead space that blocks the next item
        score += 20.0;
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (tighter bins)
    score += 0.6 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin when decent fits exist, more so early in stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 60.0 + 40.0 * (1.0 - progress);
    }

    // Slight penalty for large waste relative to capacity
    score += 0.3 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon factor: early stream -> explore packing density; late stream -> tighten.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let horizon = 1.0 + 0.6 * progress;

    // Reward tight fits: quadratic bonus for small post residual.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);

    // Penalize dead space that no plausible item can use.
    if post_residual > 0 {
        if post_residual < 10 {
            score -= 8.0; // near-perfect fill
        } else if post_residual < 30 {
            score += (post_residual as f64) * 0.15 * horizon;
        } else {
            score += (post_residual as f64 - 30.0).powi(2) * 0.02 * horizon;
        }
    }

    // Lookahead coupling: if next item fits in post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 + 4.0 * (1.0 - progress);
    } else if next_item_size > 0 && next_item_size <= bin_residual && next_item_size > post_residual {
        // next item would have fit if we hadn't placed here: mild penalty
        score += 2.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    } else if fitting_bins_count > 2 {
        // many alternatives: prefer the best-fitting one, discourage sloppy choices
        score += (fitting_bins_count as f64 - 2.0) * 0.4;
    }

    // Global residual balance: prefer bins whose residual is below mean (denser bins).
    score += (mean_residual - bin_residual as f64) * 0.25;

    // Slight preference to keep number of open bins in check early on.
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    // New-bin candidate: only attractive when no open bin fits well
    // (large dead space would otherwise be created in an existing bin).
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = fitting_bins_count == 0
            || (post_residual as f64) > mean_residual * 0.9;
        if poor_fit_elsewhere {
            score -= 3.0;
        } else {
            score += 12.0 + 6.0 * (1.0 - progress); // reuse open bins when fit is decent
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer tight fits (low post_residual), smoothed polynomial coupling.
    let mut score = pr;

    // Non-linear reward for small post_residual (wasted space penalty grows super-linearly).
    let pr_norm = pr / cap;
    score += 12.0 * pr_norm * pr_norm * cap * (0.5 + 0.5 * progress);

    // Reward tight fit: fraction of bin used by this item.
    let fill = item / cap;
    score -= 30.0 * fill * fill * (1.0 + progress);

    // Perfect or near-perfect fit bonus.
    if pr == 0 {
        score -= 50.0;
    } else if pr <= 10 {
        score -= 20.0 * (1.0 - pr / 10.0) * (1.0 + progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) as f64 / cap;
            score -= 18.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            // Penalize post_residual that is just barely too small for the next item.
            let gap = (nxt - pr) / cap;
            if gap < 0.15 {
                score += 10.0 * (1.0 - gap / 0.15);
            }
        }
    }

    // Prefer bins with below-mean residual (keep large residual bins flexible).
    let diff = (pr - mean_residual) / cap;
    score += 6.0 * diff;

    // New empty bin candidate: penalize early in the stream, relax later;
    // also penalize more when open bins already exist and item is small.
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) * (1.0 - progress);
        score += 0.5 * open_bins_count as f64;
        score += 0.3 * item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is best possible.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space: residuals below the minimum item size are unusable forever.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Harmonic classes: residual mod 10 quantizes fit quality.
    let class = post_residual % 10;
    score += match class {
        0 => -30.0,                       // clean decade residual, highly reusable
        1..=4 => -10.0 + class as f64,    // small clean remainder, good
        5..=8 => 5.0 + class as f64,      // awkward mid-range remainder
        _ => 15.0,                        // 9: worst reusable class
    };

    // Integer-division thresholds on post_residual: fraction of capacity left.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.5 {
        score -= 20.0;   // bin still half-full after placement: very healthy
    } else if frac < 0.1 {
        score += 25.0;   // nearly exhausted: wasteful unless perfect fit
    }

    // Lookahead coupling: reward if next item exactly fits the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            score -= 20.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item can't use this residual; penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 120.0 };
        score += pressure - mean_residual * 0.5;
        // Late in the stream, avoid spawning bins for small leftovers.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    // Gaps below the minimum plausible item size (1..=100 unknown dist; use
    // a conservative threshold) are pure waste — add a strong nonlinear penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + 8.0 * (10 - post_residual) as f64;
    } else if post_residual < 20 {
        // small but potentially usable gaps: mild penalty
        score += 12.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits (post_residual near zero but not a tiny dead gap).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 15 && post_residual >= 10 {
        score -= 10.0;
    }

    // Open-bin pressure: prefer keeping the count of open bins low.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate: make it unattractive unless the current bin would
    // create a bad dead gap. Compare against residual-based waste.
    if bin_residual == bin_capacity {
        // Empty bin baseline: neutral score ~ capacity, adjusted by pressure.
        score = bin_capacity as f64 + 2.5 * open_bins_count as f64;
        // If placing here would waste less than using an open bin, allow it:
        // (handled implicitly since open bins with big dead gaps score high)
        if post_residual == 0 {
            score -= 10.0;
        }
    }

    // Lookahead: if next item fits the post-residual exactly, reward this placement.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 15.0;
        }
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 10.0;
    }

    // Stream progression: early on, be more conservative about dead space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: post residual exactly matches next item -> strong reward.
            let gap = (post_residual as f64 - next_item_size as f64).abs();
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
            // Bonus for exact match (zero gap).
            if gap == 0.0 {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here: penalize proportionally to wasted lookahead space.
            score += 0.35 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Relative-to-mean coupling: prefer bins with residual below the mean (tighter packs).
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize tiny dead space (< ~10) that is hard to reuse, unless next item fills it.
    if post_residual > 0 && post_residual < 10 && next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Mild late-stream conservatism: prefer filling existing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress;

    // New-bin candidate: make empty bins less attractive unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 6.0 + 0.2 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit gets a strong reward (subtract a lot)
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize small dead space that nothing can use: dead space below min item size
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 25.0 * (10.0 - dead) / 10.0;
        }
        // Nonlinear penalty for large leftover if lookahead can't use it
        if next_item_size > 0 {
            if (post_residual as u32) < next_item_size {
                // leftover unusable by next item
                score += 8.0 + 0.15 * dead;
            } else {
                // reward bins that leave room for the next item
                score -= 6.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Tight fit reward: how well the item fills the bin relative to capacity
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Coupling with global mean residual: prefer bins whose residual deviates from mean
    // (packs tightly into outlier bins, keeps average residual bins flexible)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Late in stream: be more conservative, prefer filling existing bins tightly
    score += 12.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Early in stream: allow opening new bins more freely
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost, reduced early, increased with open bins count
        score += 15.0 - 10.0 * progress + 0.5 * open_bins_count as f64;
    }

    // Large items: prefer bins with exactly enough residual (minimize waste)
    if item_size >= 50 {
        score += 0.1 * post_residual as f64;
    }

    // Small items: prefer bins with small residual (use scraps)
    if item_size <= 20 {
        score -= 0.1 * (bin_capacity - bin_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.35 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: tighten packing more aggressively as stream advances
    let progress_coupling = 1.0 + 0.6 * progress * (1.0 - progress) * 4.0;
    score *= progress_coupling;

    // Reward tight fits (small post_residual relative to item size)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 6.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual that is too small to be useful
    let dead_threshold = 10.0;
    if pr < dead_threshold {
        score += (dead_threshold - pr) * 2.5;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward heavily
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let next_fit = (pr - next_item_size as f64).abs();
        score -= 8.0 * (1.0 - next_fit / cap);
    } else if next_item_size > 0 {
        // Next item won't fit here; mild penalty proportional to leftover waste
        score += 1.5 * (next_item_size as f64 / cap) * norm_pr;
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably from mean
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev - 2.0 * dev;

    // Mild penalty for proliferating open bins early in the stream
    score += 0.4 * (open_bins_count as f64) * (1.0 - progress) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "reusable"
    // residue classes (multiples of 10, and >= 20) are favored.
    let post = post_residual as i64;
    let cap = bin_capacity as i64;

    // Integer division thresholds on post_residual.
    if post >= 20 {
        score -= 8.0;
    }
    if post >= 30 {
        score -= 6.0;
    }
    if post % 10 == 0 && post > 0 {
        score -= 5.0; // perfectly reusable harmonic class
    }

    // Penalize tiny dead space classes that waste the bin.
    if post > 0 && post < 10 {
        score += 14.0;
    }

    // Perfect fit is ideal.
    if post == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: harmonic class of next_item_size vs post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here: strong reward, scaled by how well it divides.
            score -= 12.0;
            if (post_residual % next_item_size.max(1)) == 0 {
                score -= 6.0;
            }
        } else {
            // Next item cannot follow into this bin: penalize dead-end placements.
            score += 7.0;
        }
        // If next item is huge, prefer keeping a big-residual bin for it.
        if next_item_size >= 60 && post_residual < next_item_size {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score = bin_capacity as f64 * 0.55 + crowd * 6.0 - progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        if item_size as f64 >= mean_residual {
            score -= 15.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (size 1..100 unknown, assume worst-case min ~10) are
    // effectively unusable dead space; penalize heavily.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64);
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    }

    // Coupling: penalize residual relative to item size (waste ratio).
    score += (post_residual as f64 / (item_size as f64).max(1.0)) * 25.0;

    // Open-bins pressure: many open bins -> prefer filling existing ones.
    score += (open_bins_count as f64) * 3.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: empty bin should only win when it's genuinely better.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64) * 2.0;
        // If no open bin fits well (large mean residual mismatch), soften.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 20.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use this residual -> residual likely dead space
        score += (post_residual as f64) * 0.4;
    }

    // Stream progression: later in stream, be more conservative about new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled non-linearly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score = pr * (1.0 + 0.5 * (pr / cap).powi(2));

    // Aggressive 2-step lookahead: if the next item exactly fills post_residual,
    // strongly reward this bin (perfect chain fit).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as u32) == next_item_size {
            score -= 60.0; // perfect next-item fill
        } else if post_residual > next_item_size {
            // reward leaving space the next item can use, more so when the
            // resulting gap is small relative to capacity
            let gap = pr - nxt;
            score -= 40.0 * (1.0 - (gap / cap).powi(2));
        } else {
            // next item cannot use the leftover space: penalize proportionally
            score += 25.0 * (nxt / cap);
        }

        // Coupling with mean residual: if this bin's post-fit residual is far
        // below the mean, we are compacting well; reward it.
        let dev = (mean_residual - pr) / cap;
        score -= 15.0 * dev.clamp(-1.0, 1.0);
    } else {
        // Last item: pure tightness, no lookahead concerns.
        score = pr;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // mild penalty to spread load when many bins fit
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Early in the stream, be slightly more willing to keep bins tight;
    // late in the stream, favor consolidating into fewer bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - pr / cap);

    // Discourage opening a new bin unless the fit is genuinely poor:
    // new empty bin (residual == capacity) gets a penalty that tight fits beat.
    if bin_residual == bin_capacity {
        score += 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 14.0;
    }
    // Reward leaving exactly room for the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 22.0;
    }

    // New-bin candidate: penalize slightly unless current bin fit is bad.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > 55.0 && next_item_size > post_residual as u32;
        if bad_fit {
            score -= 5.0;
        } else {
            score += 26.0;
        }
    }

    // Prefer filling bins whose residual is already small relative to mean.
    let rel = (bin_residual as f64) - mean_residual;
    score += 0.08 * rel;

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - tightness);

    // Many open bins: discourage spreading; few open bins: allow flexibility.
    if open_bins_count > 4 {
        score += 0.6 * (post_residual as f64).sqrt();
    }

    // Perfect fill reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - post / cap;

    // Core: penalize leftover space non-linearly (dead space grows superlinearly).
    let mut score = post * (1.0 + 0.8 * post / cap);

    // Smooth polynomial coupling of tightness with stream progress:
    // late in the stream, reward tight fits (small post_residual) more aggressively.
    let tightness = (1.0 - fill).powi(2); // high when fill is low... invert
    let tight_reward = (fill.powi(3)) * (1.0 + 2.0 * progress);
    score -= 6.0 * tight_reward;

    // Smooth interaction: post_residual vs next item size — reward leaving space
    // that matches the next item (quadratic mismatch penalty).
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let mismatch = (post - nxt) / cap;
        score += 4.0 * mismatch * mismatch * cap;
        // smooth bonus when post_residual is just above next item size
        let cover = (post / nxt).min(2.0);
        score -= 2.0 * (cover - 1.0).max(0.0) * nxt / cap;
    }

    // Last-chance bin: strong smooth reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    }

    // New empty bin candidate: penalize smoothly, more so early (consolidate first),
    // but relax late in the stream when consolidation gains are exhausted.
    let is_new = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new {
        score += 10.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    // Mild penalty for spreading across many open bins vs mean residual.
    score += 0.05 * (post - mean_residual).abs();

    // Smooth extra push: exact fit gets large reward.
    score -= 5.0 * (-post as f64 / 5.0).exp() * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space.
    // Residuals that are exact fractions of capacity (25/50/75/100) are prime
    // targets for future items; odd tiny remainders are dead space.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -30.0 // perfect fit
    } else if pr <= 10 {
        12.0 // nearly dead space
    } else {
        match pr {
            x if x % 25 == 0 => -14.0,
            x if x % 20 == 0 => -10.0,
            x if x % 10 == 0 => -6.0,
            x if x % 5 == 0 => -3.0,
            _ => 4.0,
        }
    };
    score += harmonic_bonus;

    // Fractional fill level of this bin: prefer fuller bins (tight packing).
    let fill = (bin_capacity - bin_residual) as f64 / cap;
    score -= 10.0 * fill;

    // Lookahead: reward leaving post_residual that exactly fits next item,
    // penalize leaving a residual that is awkwardly just below next_item_size.
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 16.0;
        } else if pr >= next_item_size && pr - next_item_size <= 5 {
            score -= 8.0; // next item leaves near-perfect residual
        } else if pr < next_item_size && pr > 0 {
            score += 6.0; // next item cannot use this bin
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate: penalize opening a bin unless current placement
    // would create large dead space or few bins fit the item.
    if bin_residual == bin_capacity {
        let dead = if pr > 0 && pr <= 10 { 10.0 } else { 0.0 };
        let pressure = open_bins_count as f64 / 8.0;
        score += 18.0 + dead - pressure
            - if fitting_bins_count == 0 { 25.0 } else { 0.0 };
    }

    // Progress: as stream advances, be more conservative with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * fill;

    // Mean residual coupling: if open bins are already loose, prefer filling
    // existing bins rather than adding slack.
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: small post_residual strongly favored.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual < item_size.min(20) {
        // Dead space: gap too small for even the smallest future item (min size 10..20).
        score += 30.0 + post_residual as f64;
    }

    // Reward bins whose residual closely matches the item (perfect filling).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Lookahead: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }
    // Penalize if post_residual is nonzero but too small for next item (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 12.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a good fit exists.
    score += 1.5 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: neutral baseline; only attractive when all open fits are bad.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 5.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        // Early stream: slightly prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress);
        // If mean residual across open bins is large, opening new bin is wasteful.
        score += 0.3 * mean_residual;
    }

    // Mean-residual coupling: prefer bins below mean residual (denser bins first).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> strong reward.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 60.0;
        } else {
            // Penalize distance from perfect lookahead match (non-linearly).
            score += (gap * gap) / (bin_capacity as f64) - 10.0 * (-gap / 15.0);
        }

        // If next item can also fit exactly into post_residual region, extra reward.
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Dead space: next item cannot use the leftover.
            score += 12.0;
        }
    }

    // Avoid leaving tiny unusable slivers (dead space penalty).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Prefer bins whose residual deviates from the mean (tighten packing).
    score -= (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Early in stream, be slightly more willing to open new bins for good structure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: mild penalty so it is chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // opening fresh bin is good if next item is large
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) with a superlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly in the post residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // reward partial compatibility, scaled by how much would remain after next
            let after_next = post_residual - next_item_size;
            score -= 8.0 * (1.0 - after_next as f64 / bin_capacity as f64);
        } else {
            // next item cannot follow here; penalize dead space creation
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so when
    // many bins are open or the item would fit reasonably elsewhere.
    if bin_residual == bin_capacity {
        let fit_pressure = if fitting_bins_count > 0 {
            fitting_bins_count as f64
        } else {
            0.0
        };
        score += 25.0 + 5.0 * fit_pressure;
        // early in stream, opening bins is cheaper; late, consolidate
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // if item is large and mean residual is small, new bin is justified
        if (item_size as f64) > mean_residual {
            score -= 18.0;
        }
    } else {
        // Prefer bins whose residual is close to item_size (minimizing waste relative to mean)
        let deviation = (bin_residual as f64 - item_size as f64).abs();
        score += 0.5 * deviation;
        // prefer bins below mean residual (fill emptier bins first to consolidate)
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        } else {
            score += 1.0;
        }
    }

    // Mild penalty for accumulating too many open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Base: prefer tight fits, with non-linear sharpening over stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Smooth penalty for mid-range dead space (post_residual near half capacity)
    let dead = (pr / cap - 0.5) * (pr / cap - 0.5);
    score += 12.0 * dead * (0.5 + progress);

    // Reward high fill fraction non-linearly
    score -= 6.0 * fill * fill;

    // Lookahead coupling: bonus if next item fits the post residual smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_ratio = (pr - nxt).max(0.0) / cap;
        score -= 4.0 * (1.0 - (fit_ratio / (pr / cap + 0.001)).abs()) * (nxt / cap);
        if pr < nxt {
            score += 3.0 * (1.0 - pr / nxt);
        }
    }

    // Last-chance bin bonus (avoid opening new bin unnecessarily)
    if fitting_bins_count == 1 {
        score -= 5.0 + 3.0 * progress;
    }

    // Mild penalty when bin residual deviates from mean residual (balance-aware)
    score += 0.05 * (pr as f64 - mean_residual).abs();

    // New-bin candidate: smooth discouragement unless residuals are all tight
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (mean_residual / cap).min(1.0);
        score += 8.0 * (1.0 - tightness * tightness) + 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity-fraction band does it land in?
    // Classes: [0,10) dead, [10,25) poor, [25,50) medium, [50,100) rich.
    let class = if post_residual == 0 { 0usize }
        else if post_residual < bin_capacity / 10 { 1 }
        else if post_residual < bin_capacity / 4 { 2 }
        else if post_residual < bin_capacity / 2 { 3 }
        else { 4 };

    // Penalize dead/very small residuals (wasted space) strongly.
    score += match class {
        0 => 0.0,
        1 => 35.0,
        2 => 15.0,
        3 => 4.0,
        _ => 0.0,
    };

    // Reward tight fits: item fills most of the bin.
    let fill = item_size as f64 / cap;
    score -= 25.0 * fill * fill;

    // Harmonic coupling: if next item fits exactly into post_residual (mod-friendly),
    // big reward; if it nearly fits, mild penalty for near-miss.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect pairing
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap); // good follow-up
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 8.0 * (miss / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when open bins have bad residuals
    // or this item is huge relative to typical residuals.
    if bin_residual == bin_capacity {
        let open_pressure = mean_residual / cap;
        let benefit = 30.0 * open_pressure * open_pressure
            + 20.0 * (1.0 - fill)
            - 10.0 * (open_bins_count as f64).sqrt() / 10.0;
        // Harmonic gate: prefer new bin when item is in a "coarse" class (large items).
        let coarse = (item_size / (bin_capacity / 4)).max(1);
        score = 45.0 - benefit - 5.0 * coarse as f64 + (post_residual as f64) * 0.5;
    }

    // Mild time pressure: later in stream, consolidate more aggressively.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * t * (1.0 - fill);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold typical
    // future items (<= 10) are pure waste — penalize heavily.
    if post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual <= 20 {
        // Semi-dead zone: usable only by small items; mild penalty.
        score += 6.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Tightness reward relative to current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Lookahead coupling: if the next item fits exactly into the
    // post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Next item won't fit here; slightly penalize hoarding space.
        score += 4.0;
    }

    // Last-chance bonus: if this is the only bin that fits the item,
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // prefer consolidating into existing bins over opening new ones.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when existing bins fit badly.
    if bin_residual == bin_capacity {
        let spread = mean_residual - post_residual as f64;
        score += 30.0 + 0.5 * open_bins_count as f64 - spread.clamp(0.0, 50.0);
    } else {
        // Slight bias toward bins below mean residual (tighter bins).
        score += 0.1 * (mean_residual - bin_residual as f64);
    }

    // Mild stream-progression term: early on, be a bit more willing
    // to open bins; later, pack tighter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and next_item_size (perfect packing of the next item into this bin).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect match => strong bonus.
        if diff < 0.5 {
            score -= 60.0;
        } else if post_residual as f64 >= nxt {
            // Next item still fits here; reward tighter fits (small diff).
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item cannot fit here; penalize proportionally to the miss.
            score += 10.0 + 0.3 * diff;
        }
    }

    // Penalize tiny dead space (< 10) that is unlikely to be usable,
    // scaled by how early we are in the stream.
    if post_residual > 0 && post_residual < 10 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is below mean residual (denser bins),
    // i.e. reward placing into already-tight bins.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new empty bin unless nothing sensible fits:
    // new-bin candidate has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if the item leaves a residual matching the next item exactly,
        // opening a fresh bin is fine.
        if next_item_size > 0 && (bin_capacity as u32 - item_size) == next_item_size {
            score -= 70.0;
        }
    }

    // Mild reward for tight overall fits (small post_residual) early on.
    score -= 0.1 * (bin_capacity as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 30.0 * tightness * tightness;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead-space penalty: residual too small for the smallest future item
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: bonus if next item fits the post-residual exactly-ish
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            // next item cannot use leftover space; penalize large leftovers
            score += 0.2 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current fits are poor or many bins are open
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 0.0 && fitting_bins_count > 0;
        let fit_quality = if fitting_bins_count > 0 {
            (item_size as f64) / (bin_residual as f64).max(1.0)
        } else {
            0.0
        };
        // penalize new bin when a decent fit exists; reward when fits are bad
        score += 40.0 * fit_quality;
        if mean_residual > 0.0 && (bin_residual as f64) < mean_residual {
            score += 5.0;
        }
        let _ = poor_fit;
        // late in stream, prefer consolidating
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Mild penalty for spreading across too many open bins
    score += 0.5 * open_bins_count as f64;

    // Prefer bins whose residual is close to item (best-fit core)
    score += 0.3 * ((bin_residual as f64) - (item_size as f64)).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = item_size as f64 / cap;
    let res_norm = bin_residual as f64 / cap;

    // Base: post residual, with non-linear penalty on unusable leftovers
    let mut score = pr * (1.0 + 0.8 * (pr / cap).powi(2));

    // Smooth coupling: prefer tight fits more strongly as stream progresses
    let tightness = 1.0 - res_norm;
    score -= 12.0 * tightness * (0.5 + progress);

    // Penalize large residual variance vs mean (imbalance across bins)
    score += 0.05 * (pr - mean_residual).abs() * (0.5 + progress);

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 3.0 * (next_item_size as f64 / cap) * (pr / cap);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: mildly penalize opening bins late, allow early
    if bin_residual == bin_capacity {
        score += 4.0 + 10.0 * progress - 0.3 * open_bins_count as f64;
    }

    // Smooth item-size interaction: big items prefer emptier bins
    score -= 5.0 * fit_norm * (1.0 - res_norm) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual modulo 10: small remainders are "good" fits.
    let rem = (post_residual % 10) as f64;
    score -= (10 - rem) * 0.8;

    // Integer-division harmonic band of post_residual: dead-space bands.
    let band = post_residual / 10;
    score += match band {
        0 => 0.0,          // near-perfect fit
        1 => 5.0,          // residue 10..19: hard to reuse
        2 => 2.0,          // 20..29 fits small items
        3 => 0.0,          // 30..39 good
        4 => 3.0,
        5 => 1.0,
        6 => 4.0,
        7 => 2.0,
        8 => 6.0,
        _ => 8.0,          // nearly empty bin being consumed shallowly
    };

    // Reward exact harmonic alignment: next item fits into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_rem = (post_residual - next_item_size) % 10;
        score -= 6.0 + (10 - next_rem as f64) * 0.5;
        if next_item_size <= post_residual && post_residual - next_item_size <= 10 {
            score -= 8.0; // two-item chain closes harmonically
        }
    } else if next_item_size > 0 {
        score += 4.0; // next item cannot follow here
    }

    // Penalize wasting a scarce fitting bin when alternatives exist.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: attractive only if current fits are poor.
    if bin_residual == bin_capacity {
        score = 45.0 + mean_residual * 0.3 - (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // big item followed by big item: fresh bin fine
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Progress coupling: tighten fits as stream advances.
    let t = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.25 * t;

    // Prefer using bins below mean residual (balance open bins).
    score += ((post_residual as f64) - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for any plausible item are heavily penalized.
    let dead_threshold = 12.0; // smallest item is ~1, but keep gap utility margin
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit strongly rewarded
    }

    // Reward tight fits (post_residual small relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 12.0;

    // Lookahead: if next item fits in post_residual, this placement is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // creates a gap the next item cannot use
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // filling existing bins is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * 0.6 * (1.0 - progress);

    // Prefer bins with residual close to item_size (best-fit coupling).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += fit_gap * 0.3;

    // Mean residual coupling: avoid wasting a large-residual bin on a small item
    // when other bins are tighter.
    if (bin_residual as f64) > mean_residual + 20.0 {
        score += 5.0;
    }

    // New-bin candidate: only attractive when nothing fits well or bins are tight.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        let avg_tightness = mean_residual / (bin_capacity as f64);
        score += desperation * (40.0 * avg_tightness + 10.0);
        if next_item_size > 0 && next_item_size > bin_residual {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 5 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // chain completion
        } else if next_item_size <= post_residual {
            // partial lookahead fit: reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item does not fit: penalize dead space relative to next item
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.3 * overflow;
        }
    } else {
        // last item: strongly prefer exact fill
        score -= 300.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    // Compare residual against mean residual across open bins
    let res = post_residual as f64;
    if res < mean_residual {
        // tighter than average: good compaction
        score -= 0.8 * (mean_residual - res);
    } else {
        // looser than average: penalize creating outlier dead space
        score += 0.4 * (res - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are bad fits
    if bin_residual == bin_capacity {
        score += 60.0;
        // opening new bin is more acceptable early in stream or with many open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 * (1.0 - progress);
        // if next item is large, a fresh bin is more attractive
        if next_item_size > item_size {
            score -= 30.0;
        }
        // if this bin would leave a very loose residual anyway, new bin less bad
        if next_item_size > 0 && post_residual > next_item_size + 20 {
            score -= 50.0;
        }
    }

    // Mild penalty when many bins are open (consolidation pressure)
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead-aware)
    if next_item_size > 0 && post_residual > 0 {
        if (post_residual as u32) < next_item_size {
            // dead space: unusable for the next item
            let dead = post_residual as f64;
            score += 0.6 * dead;
        } else {
            // post_residual can host next item: reward chaining
            let chain = (post_residual as f64) / (next_item_size as f64);
            score -= 8.0 / (1.0 + (chain - 1.0).abs());
        }
    }

    // Last-chance bin: heavily favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when many bins could fit the item
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus penalty scaled by number of alternatives
        score += 25.0 + 3.0 * (fitting_bins_count as f64);
        // More acceptable late in the stream when open bins are fragmented
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score -= 10.0 * progress * (fragmentation / (bin_capacity as f64));
        // Slight penalty for accumulating many open bins
        score += 0.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mild preference for bins with residuals close to the current mean (balance load)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Reward using bins whose residual is "just enough" (waste minimization)
    let slack = (bin_residual - item_size) as f64;
    score += 0.05 * slack * slack / (bin_capacity as f64);

    // Early-stream exploration: be slightly greedy about tight fits early
    let early = 1.0 - (step_index as f64 / (total_items.max(1) as f64));
    score -= 4.0 * early * (1.0 - slack / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let r = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_r = r / cap;

    // Base: residual waste, softly normalized
    let mut score = norm_r * 10.0;

    // Non-linear penalty on mid-range residuals (dead space that fits nothing well)
    let mid = norm_r * (1.0 - norm_r);
    score += 6.0 * mid * mid * 4.0;

    // Polynomial coupling of residual with stream progress:
    // early on, waste is cheap; late, waste is heavily penalized
    let coupling = r * r / (cap * cap) * (0.5 + progress * progress * 2.0);
    score += coupling * 8.0;

    // Reward tight fits: small post_residual gets bonus
    score -= (1.0 - norm_r) * (1.0 - norm_r) * 5.0;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if r >= nx {
            score -= 4.0 * (1.0 - (r - nx) / cap);
        } else {
            score += 3.0 * (nx - r) / cap;
        }
    }

    // Prefer denser bins when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * norm_r;

    // Alignment with mean residual: bins close to mean residual are flexible
    let dev = (r - mean_residual) / cap;
    score += 1.5 * dev * dev;

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 6.0 - 4.0 * (fitting_bins_count == 0) as i32 as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into coarse buckets.
    let pr = post_residual;
    let class = match pr {
        0 => 0,          // perfect fit
        1..=5 => 1,      // near-perfect
        6..=15 => 2,     // usable for small items
        16..=30 => 3,    // medium leftover
        31..=50 => 4,    // large leftover
        _ => 5,          // mostly empty bin
    };

    // Reward perfect and near-perfect fits strongly.
    match class {
        0 => score -= 60.0,
        1 => score -= 40.0,
        2 => score -= 10.0,
        3 => score += 5.0,
        _ => {}
    }

    // Modulo coupling: residual divisible by common item sizes is reusable.
    for d in [10u32, 20, 25, 50] {
        if pr > 0 && pr % d == 0 {
            score -= 8.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            if slack <= 10 {
                score -= 20.0;
            } else if slack <= 25 {
                score -= 5.0;
            } else {
                score += slack as f64 * 0.1;
            }
        } else {
            // next item cannot use leftover: penalize proportionally
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: penalize opening a new bin unless current fits are bad.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But early in stream or when few bins open, new bin is cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 50.0;
        }
        // If item is large relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.7 * cap {
            score -= 15.0;
        }
    }

    // Slight preference for filling fuller bins as stream progresses.
    let fill_ratio = 1.0 - (post_residual as f64 / cap);
    score -= fill_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible item (<= 10) are pure waste; penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Gaps that can only fit tiny items are semi-dead; scale penalty by gap smallness.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // penalize opening yet another bin.
    let new_bin_penalty = 10.0 + (open_bins_count as f64) * 1.5;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
    } else {
        score -= 2.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0;
    }
    // If next item almost fits, mild penalty for leaving a near-miss gap.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 3.0;
    }

    // Late in the stream, tighten up: discourage spreading across bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    // Deviation from mean residual: prefer bins whose residual is close to item need
    // (tight fits), i.e. lower bin_residual relative to mean is better.
    score += 0.15 * ((bin_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) super-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Exact-fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: reward bins whose leftover matches the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / (bin_capacity as f64)).max(0.0);
        } else {
            // next item won't fit here; penalize proportionally to wasted gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Penalize creating dead space relative to mean residual of open bins.
    if post_residual as f64 > mean_residual {
        score += 0.4 * ((post_residual as f64 - mean_residual).min(50.0));
    } else {
        score -= 0.2 * (mean_residual - post_residual as f64).min(20.0);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin mildly, more when many bins open
    // or when this bin would be a poor host for the next item.
    if bin_residual == bin_capacity {
        let mut penalty = 35.0;
        if next_item_size > 0 {
            // a fresh bin is attractive if the next item could pair with the current one
            if item_size + next_item_size <= bin_capacity {
                penalty -= 25.0;
            }
        }
        if open_bins_count > 0 && fitting_bins_count > 0 {
            penalty += 20.0; // discourage abandoning usable open bins
        }
        score += penalty;
    }

    // Slight early-stream preference to keep several bins open for flexibility.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared waste penalty emphasizes near-exact placements.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_frac * waste_frac;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: penalize leaving a residual that blocks the next item,
    // reward residuals that can still accommodate it.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 8.0;
        }
    } else if next_item_size > 0 && post_residual == 0 {
        // Perfect fit but next item can't use this bin anyway: fine.
        score += 0.0;
    }

    // Penalize opening a brand-new bin when good alternatives exist.
    if bin_residual == bin_capacity {
        let good_fits = (fitting_bins_count as f64).max(1.0);
        score += 15.0 / good_fits.sqrt();
        // Opening new bins is more acceptable early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
        // If mean residual across open bins is large, prefer reusing open bins.
        score += 0.15 * mean_residual;
        // A new bin is attractive if the item is large and nothing fits well.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Mild preference for bins with lower residuals among many open bins
    // (keeps large residuals available for large future items).
    if open_bins_count > 1 {
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_res = post_residual as f64 / bin_capacity as f64;

    // Non-linear waste penalty: quadratic in normalized post residual, amplified by progress
    score += 40.0 * norm_res * norm_res * (0.5 + progress);

    // Reward tight fits (small post residual relative to item)
    let tight = 1.0 - (post_residual as f64 / (item_size as f64 + 1.0)).min(1.0);
    score -= 30.0 * tight * tight;

    // Lookahead coupling: reward when next item fits the post residual
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let fit_next = 1.0 - (gap / bin_capacity as f64).min(1.0);
        score -= 25.0 * fit_next * fit_next * (1.0 - progress);
        // Penalize post residual that is too small to ever be useful
        if post_residual < next_item_size && post_residual > 0 {
            score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin when existing bins fit decently
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - progress) + open_bins_count as f64 * 0.5;
        // But allow new bin if all open residuals are tiny (poor fits)
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
    }

    // Mild preference for bins below mean residual (balance spreading)
    score += 0.1 * (post_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: strongly prefer tight fits (low post_residual)
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * frac * frac * bin_capacity as f64;

    // Harmonic class of post_residual: residues mod 10 and mod 25.
    // Residuals that are "useful" sizes (multiples of 10 or 25, or small)
    // are more likely to be filled by future items.
    let r = post_residual;
    let class_bonus: f64 = if r == 0 {
        -30.0 // perfect fit
    } else if r % 25 == 0 || r % 10 == 0 {
        -6.0  // harmonic residual, likely reusable
    } else if r < 10 {
        10.0  // dead space below minimum item size
    } else if r > 80 {
        -2.0  // large residual still flexible
    } else {
        // non-harmonic mid residual: penalize proportional to distance
        // from nearest harmonic class (multiple of 10)
        let d = (r % 10).min(10 - (r % 10));
        1.5 * d as f64
    };
    score += class_bonus;

    // Lookahead coupling: reward bins whose post_residual can host next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 5.0 * (1.0 - slack / bin_capacity as f64);
            // harmonic chain: post_residual % next_item_size small remainder
            if post_residual % next_item_size == 0 {
                score -= 4.0;
            }
        } else {
            score += 3.0; // this placement kills future fit in this bin
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing bins
    // are nearly full or none fit well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / bin_capacity as f64;
        score = bin_capacity as f64 * (0.9 + 0.3 * progress)
            - 10.0 * (1.0 - pressure)
            + 5.0 * open_bins_count as f64;
        // if item fits poorly anywhere else (large item, few fitting bins),
        // opening fresh is more acceptable
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        if item_size >= 50 && next_item_size >= item_size {
            score -= 8.0;
        }
    }

    // Mild entropy: prefer consolidating into fewer bins early
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for small unusable dead space (residuals that likely can't fit future items).
    let dead_zone: f64 = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 6.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64);
        score -= tightness * 10.0;
    }

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize creating residual that the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + (next_item_size - post_residual) as f64 * 0.3;
    }
    // Reward residual that exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Pressure against opening new bins when open bins exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 20.0 + open_bins_count as f64 * 2.0;
        // Still allow new bin if residual of this item leaves a big usable gap anyway.
        if post_residual >= 40 {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins with residuals close to item size among many fitting bins.
    if fitting_bins_count > 1 {
        let waste = (bin_residual - item_size) as f64;
        score += waste * 0.5;
    }

    // Mild late-stream tightening: keep bins closed as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Penalize bins far above mean residual (fragmentation hoarding).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            // next item still fits here: mild reward proportional to tightness
            score -= 10.0 * (nxt / (post_residual as f64 + 1.0));
        } else {
            // next item cannot fit: penalize dead space left behind
            score += 8.0 * (nxt / (bin_capacity as f64));
        }
    }

    // Tightness reward: small post_residual is good.
    score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Compare residual against mean residual across open bins: prefer bins
    // whose residual is below average (already fragmented, absorb waste here).
    if post_residual as f64 > mean_residual {
        score += 3.0 * (post_residual as f64 - mean_residual) / bin_capacity as f64;
    } else {
        score -= 3.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when few/no good fits exist.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (fitting_bins_count as f64) };
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Penalize opening new bins early or when many bins fit the item.
        score += 40.0 * (1.0 - pressure) + 10.0 * (1.0 - progress);
        // If lookahead item is large and this bin is the only fit, new bin is fine.
        if next_item_size > 0 && post_residual < next_item_size && fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Mild open-bin count pressure: encourage consolidation when many bins open.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual (good fit).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        // Small dead space is nearly perfect.
        score -= 8.0;
    } else if post_residual < 20 {
        score -= 3.0;
    }

    // Penalize leaving residual that is too small for typical future items
    // (dead space): residual below the minimum item size is pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead coupling: reward leaving room for the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            // This bin can also host the next item: chain bonus, stronger
            // when the next item fills it tightly.
            let next_fit = next / post_residual as f64;
            score -= 6.0 * next_fit;
        } else if post_residual > 0 {
            // Post residual can't fit next item: mild penalty scaled by waste.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 5.0 * waste;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item fits poorly everywhere (large post_residual relative to item)
    // or early in the stream when spreading load is cheap.
    if bin_residual == bin_capacity {
        // Base reluctance to open new bins grows with stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 + 30.0 * progress;

        // If open bins are mostly empty (high mean residual), reuse them.
        score += 0.15 * mean_residual;

        // Few open bins => prefer consolidation into them.
        score += 3.0 * open_bins_count as f64;

        // Exception: big item with no good fit anywhere — opening fresh is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 20.0;
        }
        // Lookahead: if next item is huge, a fresh bin preserves flexibility.
        if next_item_size > 60 {
            score -= 8.0;
        }
    }

    // Mild global pressure: when many bins are open, discourage waste to
    // avoid bin proliferation.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Time-horizon modulation: early in stream, be slightly greedy toward
    // tight fits to build dense bins; late, prioritize just closing gaps.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * (1.0 - progress) * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize wasted space, quadratically coupled with stream progress
    let mut score = pr * (1.0 + 1.5 * progress + 2.0 * progress * progress);

    // Smooth cubic penalty for very small residuals (dead space)
    let dead = 1.0 - pr / cap;
    score -= 4.0 * dead * dead * dead * item_size as f64;

    // Interaction: post_residual vs mean residual (prefer bins tighter than average)
    let dev = mean_residual - pr;
    score += 0.35 * dev;

    // Last-chance bonus (smooth via fitting count)
    let last_chance = 1.0 / fitting_bins_count as f64;
    score -= 12.0 * last_chance * (1.0 + progress);

    // Lookahead: reward if next item fits into post residual
    if next_item_size > 0 {
        let fits = (next_item_size as f64 <= pr) as i32 as f64;
        let slack = 1.0 - ((next_item_size as f64 - pr).abs() / cap).min(1.0);
        score -= 6.0 * fits * slack * (1.0 - progress);
    }

    // Mild penalty for bin proliferation early in the stream
    score += 0.5 * open_bins_count as f64 * (0.5 - progress).max(0.0);

    // New-bin candidate handling: neutral baseline with slight tilt
    if bin_residual == bin_capacity {
        score = cap * (1.0 + 0.8 * progress) - 0.5 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits; dead space below a "usefulness floor" is wasted.
    let waste_threshold = bin_capacity / 10; // residuals < 10 are near-unusable
    if post_residual > 0 && post_residual < waste_threshold {
        score += 25.0 * (waste_threshold - post_residual) as f64 / waste_threshold as f64;
    }

    // Harmonic class: modulo-10 class of post_residual. Residuals in classes
    // compatible with the small-item quantum (10) are more reusable.
    let class = post_residual % 10;
    score += match class {
        0 => -6.0,           // perfect quantum alignment, highly reusable
        1..=4 => -1.5,       // small slack, can absorb tiny items
        5..=7 => 3.0,        // awkward mid-class
        _ => 1.0,            // 8-9: nearly full, low value either way
    };

    // Lookahead coupling: reward residuals that can host the next item exactly,
    // penalize residuals that fit next_item_size but leave a dead sliver.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0; // perfect two-item chain
        } else if post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            if slack < waste_threshold {
                score += 8.0; // would create dead space for the next item
            } else {
                score -= (slack % 10 == 0) as i32 as f64 * 5.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the item fits nothing well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = open_bins_count as f64 / 20.0;
        // Base new-bin cost, reduced late in the stream or when many bins open
        let mut nb = 55.0 - 20.0 * progress - crowd.min(20.0);
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            nb += 5.0; // slight bonus: fresh bin can chain next item too
        }
        if post_residual % 10 == 0 {
            nb -= 4.0; // clean empty-bin residual class
        }
        score += nb.max(0.0);
    }

    // Global balance: nudge score toward bins whose residual deviates from the
    // mean in the "tight" direction (consolidate fullness).
    let dev = mean_residual - post_residual as f64;
    score += 0.15 * dev;

    // Item-size harmonic penalty: large items should prefer near-exact fits.
    if item_size > bin_capacity / 2 && post_residual > bin_capacity / 4 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any plausible item are "dead".
    // Items are 1..100, so a post_residual < ~10 is nearly unusable; penalize hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward when the next item fits exactly in the post_residual (chained fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 - gap * 0.3;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item cannot follow in this bin: penalize proportional to tightness.
        score += (next_item_size as f64 - post_residual as f64) * 0.2;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few open bins, opening a new bin is cheap, so discourage wasteful fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate calibration: empty bin should win only when the fit
    // in existing bins is poor (large post_residual) or dead space is created.
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
    }

    // Mild attraction toward bins whose residual is close to the mean (keeps balance).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is a jackpot.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward tight match with the next item.
        score -= 60.0 * (-gap / 12.0).exp();
        // Exact fit chain gets a strong bonus.
        if post_residual == next_item_size {
            score -= 45.0;
        }
        // Penalize leaving a residual that no plausible item (1..100) can use well:
        // very small dead space (< 10) is nearly unusable.
        if post_residual > 0 && post_residual < 10 {
            score += 35.0;
        }
        // If next item could exactly fill this bin's residual, slightly discourage
        // dumping the current item here unless the fit is also tight.
        if next_item_size == bin_residual && gap > 10.0 {
            score += 20.0;
        }
    }

    // Tightness relative to the mean residual of open bins:
    // prefer bins whose leftover lands near the mean (keeps a healthy spread of
    // usable gaps), but strongly prefer below-mean leftovers (denser packing).
    let pr = post_residual as f64;
    let dev = pr - mean_residual;
    if dev < 0.0 {
        score -= 0.35 * (-dev);
    } else {
        score += 0.25 * dev;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit would be terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.3 * (bin_residual as f64 - pr);
    }

    // New-bin candidate (empty bin): only attractive when the item is large or
    // all existing fits would leave big gaps.
    if bin_residual == bin_capacity {
        let waste_here = pr; // residual if placed in a fresh bin
        let waste_open = if fitting_bins_count > 0 { mean_residual - item_size as f64 } else { f64::MAX };
        if waste_open <= 0.0 || (waste_here as f64) < waste_open - 8.0 {
            score -= 30.0; // opening a new bin is genuinely better
        } else {
            score += 15.0 + 0.5 * (open_bins_count as f64).sqrt(); // prefer reusing open bins
        }
    }

    // Mild preference for filling nearly-full bins to completion.
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 10.0 * fill_ratio * fill_ratio;

    // Slight stream-aware nudge: early on, keep bins open and flexible.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 6.0 * (1.0 - progress) * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space that cannot be used by the lookahead item
        let pr = post_residual as f64;
        let nis = next_item_size as f64;
        if nis > 0.0 {
            if post_residual as u32 >= next_item_size {
                score -= 30.0; // lookahead item fits in leftover
            } else {
                score += pr * 0.8; // unusable sliver for lookahead
                if pr < 10.0 { score += 25.0; } // tiny sliver is dead space
            }
        } else {
            // last item: any residual is pure waste
            score += pr * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate: opening a new bin is wasteful unless nothing fits well.
    // Give it a mild penalty so it only wins when open bins score badly.
    if bin_residual == bin_capacity {
        score += 150.0 + open_bins_count as f64 * 2.0;
        // But if the current item is large relative to capacity, a fresh bin is fine
        if item_size as f64 > bin_capacity as f64 * 0.5 {
            score -= 100.0;
        }
    }

    // Prefer bins whose residual is close to the item (tight fit signal)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 40.0;

    // Prefer bins below mean residual (fill emptier bins less, keep balanced spread)
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Late in the stream, consolidate: fewer open bins preferred
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.7 && bin_residual != bin_capacity {
        score -= 20.0 * progress;
    }

    // Reward placements that leave room exactly matching common small-item sizes
    if post_residual >= 10 && post_residual <= 30 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);
    score += 40.0 * poly * (0.5 + progress);

    // Penalize large residuals more as stream progresses
    score += 10.0 * pr_norm * pr_norm * (progress * (1.0 - progress) * 4.0);

    // Reward tight fits (small post_residual) with smooth decay
    score -= 15.0 * (-pr / 12.0).exp() * (1.0 - progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = pr - nxt;
        if diff >= 0.0 {
            score -= 8.0 * (-diff / 20.0).exp();
        } else {
            score += 6.0 * (-diff / 10.0).exp();
        }
    }

    // New-bin candidate: mildly penalize so we prefer using open bins unless fit is bad
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * (1.0 - progress);
    }

    // Mean residual coupling: prefer bins deviating from mean (consolidate)
    let dev = (pr - mean_residual).abs();
    score += 2.0 * dev * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: quantize post_residual into capacity-fraction buckets.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let harmonic_penalty: f64 = match post_residual {
        0 => -12.0,                                  // perfect fill: heavily reward
        r if r < eighth => -6.0,                     // near-perfect class
        r if r < quarter => 0.0,                     // neutral small class
        r if r < 2 * quarter => 4.0,                 // half-ish leftover
        _ => 8.0,                                    // large leftover: wasteful
    };
    score += harmonic_penalty;

    // Integer-division threshold on post_residual: dead space that no typical item (<=80, >=1)
    // can pair with in the future is worse than moderate leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0; // sliver: unusable dead space
    }

    // Lookahead coupling: does the next item fit into the resulting residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item can use the leftover: reward proportionally to tightness
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 8.0 * tightness;
        } else {
            // next item won't fit: penalize leftover size scaled by how much it misses
            let miss = (next_item_size - post_residual) as f64;
            score += 0.05 * miss;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit into
    // existing bins is poor. Give the fresh bin a baseline penalty that shrinks
    // when the item is large relative to what open bins can absorb.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 0.5 * item_size as f64;
        // if no other bin fits, opening is necessary: make it attractive
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // late in the stream, consolidating matters more
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is close to the mean (balance across open bins)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    // Mild pressure to fill existing bins when many are open
    score += 0.02 * open_bins_count as f64;

    // Modulo-style bonus: exact quarter/eighth alignments are classic good fits
    if post_residual % quarter == 0 && post_residual > 0 {
        score -= 2.0;
    }
    if post_residual % eighth == 0 && post_residual > 0 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (1..=10) are nearly unusable
    // for items of size >= 10, so penalize them heavily; zero residual is perfect.
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 8.0;
    }

    // Reward tight fits (wasted fraction of bin small).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Last-chance bin: strongly prefer using the only bin that fits to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones;
    // when few are open, a new bin is cheap.
    if bin_residual == bin_capacity {
        score += 5.0 + 4.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward heavily; if post residual is smaller than next item but nonzero,
    // slight penalty (dead space for the lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 5.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (consolidate space, keep large gaps concentrated in few bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Mild late-stream tightening: as the stream progresses, be pickier about
    // residual quality.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins where the item fills nearly all space.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 500.0;
    }

    // 2-step lookahead: if the next item exactly fills the post residual,
    // this is an ideal two-item packing.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 800.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits after this placement: reward proportional to how snugly.
        let slack_after_next = post_residual - next_item_size;
        score -= 200.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Next item won't fit here after placement: penalize dead space created.
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Compare post_residual against mean residual: leaving this bin far below
    // the mean residual wastes capacity elsewhere; keeping residuals balanced
    // preserves flexibility.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.3 * (pr - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - pr);
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are
    // poor fits or we're early in the stream with few bins open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (bin_residual - item_size) > bin_capacity / 2;
        score += 150.0;
        if fitting_bins_count == 0 {
            score -= 400.0; // no alternative: must open new bin
        }
        if poor_fit && next_item_size > 0 && next_item_size > bin_residual - item_size {
            score -= 250.0; // current bins would leave bad dead space
        }
        if open_bins_count > 8 && progress > 0.5 {
            score += 50.0 * progress; // late stream: consolidate
        }
    }

    // Mild penalty for very large leftovers that likely become dead space.
    if post_residual > 0 && post_residual < 10 {
        score -= 100.0; // small residual still usable for tiny items
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 0.6 * tightness * (post_residual as f64).sqrt();

    // Penalize dead space that can't fit a typical next item
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0 + (next_item_size - post_residual) as f64 * 0.25;
        } else {
            // Reward leaving room exactly for the lookahead item
            let gap = (post_residual - next_item_size) as f64;
            score -= 3.0 / (1.0 + gap);
        }
    } else {
        // Last item: strongly prefer filling bins as full as possible
        score -= 10.0 * tightness;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let crowding = (mean_residual / bin_capacity as f64).min(1.0);
        score += 6.0 + 10.0 * (1.0 - crowding);
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative, must open
        }
    }

    // Prefer filling bins whose residual is close to mean residual (balance)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Late in the stream: prioritize closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * tightness;

    // Many open bins: favor consolidating into emptier bins
    if open_bins_count > 3 {
        score += 0.05 * (bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: quadratic in post-residual, modulated by stream progress.
    // Later in the stream, dead space becomes more costly (higher power).
    let mut score = pr * (1.0 + progress * norm_pr * 2.0);

    // Smooth cubic coupling between post_residual and mean residual:
    // prefer bins whose leftover aligns with the fleet's average slack.
    let mean_norm = mean_residual / cap;
    score += 8.0 * (norm_pr - mean_norm).powi(3).abs() * (1.0 + progress);

    // Reward tight fits (small post_residual) super-linearly.
    score -= 30.0 * (1.0 - norm_pr).powi(4);

    // Lookahead: if the next item fits into post_residual, reward strongly;
    // otherwise penalize creating a residual that strands the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 12.0 * (nx / cap) * (1.0 + progress);
        } else {
            score += 6.0 * (1.0 - (cap - nx) / pr.max(1.0)).abs();
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good
    // alternatives exist or many bins are already open.
    if is_new_bin {
        score += 40.0 + 5.0 * open_bins_count as f64;
        // But late in the stream with fragmented bins, new bin is less bad.
        score -= 30.0 * progress * (1.0 - 1.0 / (1.0 + open_bins_count as f64));
    }

    // Slight penalty for bins that are already very full after placement
    // when many bins fit (keep flexibility).
    if fitting_bins_count > 2 {
        score += 3.0 * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements leaving small residuals.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness) * (1.0 - tightness);

    // Harmonic class logic: partition post_residual into classes via integer division.
    // Class 0: post_residual in 0..=9 (excellent dead-space suppression)
    // Class 1: 10..=19 (still usable by smallest items)
    // Class 2+: progressively worse.
    let cls = post_residual / 10;
    let class_penalty: f64 = match cls {
        0 => -25.0,
        1 => -8.0,
        2 => 6.0,
        3 => 14.0,
        _ => 22.0,
    };
    score += class_penalty;

    // Modulo coupling: residuals that pair well with typical item granularity (multiples of 5/10) are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 10.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        score -= 20.0 * (1.0 - gap as f64 / bin_capacity as f64);
        if gap == 0 {
            score -= 30.0;
        }
    } else if next_item_size > post_residual && post_residual < 10 {
        // Dead space unusable by next item: penalize mildly.
        score += 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin, scaled by how many open bins
    // could fit and how much residual mass is already stranded.
    if bin_residual == bin_capacity {
        let stranded = mean_residual * open_bins_count as f64;
        let waste_ratio = stranded / (open_bins_count as f64 * bin_capacity as f64).max(1.0);
        score += 60.0 + 40.0 * (1.0 - waste_ratio);
        // But if item is huge relative to capacity, new bin is less bad.
        score -= 20.0 * (item_size as f64 / bin_capacity as f64);
        // Late in stream, prefer consolidating into existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 * progress;
    }

    // Mild consolidation pressure: prefer bins with below-mean residual (pack fuller bins tighter).
    score += 3.0 * ((post_residual as f64 - mean_residual) / bin_capacity as f64);

    // Avoid scattering across many open bins: slight reward when open_bins_count is small.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (< 10, or below min item size) are pure waste.
    let min_size = 1.0f64;
    if (post_residual as f64) < min_size * 10.0 && post_residual > 0 {
        score += 40.0 + (10.0 - post_residual as f64) * 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 25.0;

    // Penalize gaps that can't fit the known next item (lookahead k=2).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 18.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading into new/partial bins;
    // with few open bins, consolidation is less critical.
    let pressure = (open_bins_count as f64).ln() * 7.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening a new bin, scaled by how many bins already fit the item.
        score += 45.0 + pressure;
        if fitting_bins_count > 0 {
            score += 25.0 + (fitting_bins_count as f64) * 4.0;
        }
        // Opening a new bin is more acceptable late in the stream when residuals are large.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
    } else {
        // Mild penalty for bins whose residual deviates far from the mean (fragmentation).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15 * (pressure / 7.0);
    }

    // Prefer bins with residual close to item_size (minimal waste placement).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 50.0 + 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Dead space relative to the next item: penalize proportionally.
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative-to-mean coupling: prefer bins with residual below the mean
    // (tighter bins first keeps wider bins flexible).
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize the new-bin candidate, but allow it when item fits poorly
    // anywhere (large post_residual on an existing bin).
    if bin_residual == bin_capacity {
        score += 80.0;
        // Opening fresh is attractive if the item is huge relative to mean residual.
        if item_size as f64 > mean_residual + 20.0 {
            score -= 120.0;
        }
    }

    // Mild late-stream tightening: near the end, avoid leaving large residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), scaled by fill ratio.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * fill * fill;

    // Penalize large dead space that likely becomes unusable.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // near-perfect fit bonus
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 3.0; // awkward gap
    }

    // Lookahead: reward if next item fits in the post residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // penalize leaving space just smaller than next item (blocking)
            let gap = (next_item_size - post_residual) as f64;
            score += 2.0 * (gap / 100.0).min(1.0);
        }
    } else {
        // last item: maximize fill aggressively
        score -= 10.0 * fill;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Crowding pressure: many open bins -> prefer consolidation into existing bins.
    let pressure = (open_bins_count as f64 / (1.0 + mean_residual / 20.0)).min(10.0);
    score += 0.4 * pressure;

    // Time horizon: late in stream, be greedy about filling bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * fill;

    // New-bin candidate handling: opening a new bin should only win when the
    // item fits badly everywhere else or open bins are nearly full.
    if bin_residual == bin_capacity {
        // Default: new bin is slightly unattractive.
        score += 25.0;
        // But if no open bin fits well (this call only happens for new bin
        // alongside poorly fitting bins), make it attractive when the item
        // is large relative to typical residual.
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mean_gap = (mean_residual - item_size as f64).abs();
        if mean_gap > 15.0 || item_frac > 0.7 {
            score -= 30.0 * item_frac;
        }
        // Early stream: opening bins is cheap and flexible.
        if progress < 0.15 {
            score -= 8.0;
        }
    } else {
        // Existing bin whose residual is far above item size: mild penalty
        // unless it's the last-chance bin.
        let waste = (bin_residual - item_size) as f64;
        if fitting_bins_count > 1 {
            score += 0.15 * waste.sqrt();
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post residual (waste minimization)
    let mut score = 2.0 * norm_pr + 1.5 * norm_pr * norm_pr;

    // Smooth non-linear coupling with stream progress: waste matters more later
    let progress_coupling = 1.0 + 1.8 * progress * progress;
    score *= progress_coupling;

    // Reward tight fits: bonus if post_residual is small relative to item size
    let item_f = item_size as f64;
    let tightness = item_f / bin_residual.max(1) as f64;
    score -= 3.0 * tightness * tightness;

    // Penalize dead space that next item cannot use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            let unusable = (nxt - pr) / cap;
            score += 2.5 * unusable * (1.0 + progress);
        } else if pr >= nxt {
            // reward leaving space the next item can use
            let usable = (pr - nxt) / cap;
            score -= 1.2 * usable * (1.0 - 0.5 * progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 4.0;
    } else {
        score += 0.3 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Coupling with mean residual: prefer bins deviating from the mean when mean is high
    let dev = (pr - mean_residual) / cap;
    score += 0.8 * dev * dev * (0.5 + progress);

    // New-bin candidate: penalize mildly, but relax if open bins are fragmented
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fragmentation = (mean_residual / cap).max(0.0);
        score += 1.5 + 2.0 * (1.0 - fragmentation) - 1.5 * progress;
        // If item is large, opening a fresh bin is more attractive
        score -= 0.01 * item_f;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tightness * tightness;

    // Harmonic classes: quantize post_residual into capacity fractions.
    // Residuals that form "usable slots" (>= 10-ish) are less penalized than dead space.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let dead = if post_residual < eighth {
        3.0
    } else if post_residual < quarter {
        1.5
    } else if post_residual < bin_capacity / 2 {
        0.7
    } else {
        0.0
    };
    score += 20.0 * dead;

    // Modulo arithmetic on post_residual: residuals near multiples of small
    // item classes (10, 20, 25) are reusable by future items.
    let r = post_residual;
    let harmonicity = if r == 0 {
        2.0 // perfect fill, excellent
    } else if r % 10 == 0 {
        1.5
    } else if r % 25 == 0 {
        1.2
    } else if r % 5 == 0 {
        0.8
    } else {
        0.0
    };
    score -= 12.0 * harmonicity;

    // Lookahead coupling: does the next item fit exactly or well in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 / (1.0 + slack);
            if post_residual == next_item_size {
                score -= 15.0; // perfect lookahead pair
            }
        } else {
            // next item won't fit here: mild penalty scaled by how close it was
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 * gap / cap;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin wastes potential.
    // Only prefer it when this bin's post_residual would be unusable dead space
    // and many other bins remain open.
    if bin_residual == bin_capacity {
        // new bin starts with full residual; neutral base, but discourage
        // unless placing here would create tiny dead space elsewhere.
        score += 10.0;
        if post_residual >= quarter {
            score -= 12.0; // fresh bin keeps large usable space: acceptable
        }
        if open_bins_count == 0 {
            score -= 50.0; // must open a bin
        }
    } else if dead >= 1.5 && open_bins_count > 2 && fitting_bins_count > 1 {
        // poor fit into an existing bin with alternatives -> consider new bin
        score += 8.0;
    }

    // Stream progression: early on, keep bins flexible; late, pack greedily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / cap);

    // Mean residual context: if open bins are already loose, prefer filling
    // whichever bin reduces spread.
    score += 0.15 * ((post_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = if bin_capacity == 0 { 1.0 } else { bin_capacity as f64 };
    let item = item_size as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;

    let progress = if total_items == 0 {
        0.0
    } else {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    };

    let open_f = open_bins_count as f64;
    let fit_f = fitting_bins_count as f64;
    let mean_res = if mean_residual.is_finite() { mean_residual.max(0.0) } else { 0.0 };

    let is_new_bin = bin_residual == bin_capacity;

    // Post-residual that a brand-new bin would leave for this item.
    let new_post = (cap - item).max(0.0);
    let new_post_usable_for_next = next_item_size == 0 || new_post >= next;

    // Base cost: less remaining space is better, with stronger pressure late in the stream
    // and when many bins are already open.
    let mut score = post * (0.85 + 0.45 * progress);
    score += (post / cap) * (1.0 + 0.18 * open_f);

    // Perfect fill is highly rewarded.
    if post_residual == 0 {
        score -= 30.0 + 2.5 * open_f + 12.0 * progress;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead-space penalty: the gap cannot fit the lookahead item.
        // If even a new bin could not fit the lookahead after this item,
        // reduce the penalty so we do not needlessly open a worse new bin.
        let deficit = next - post;
        let dead_scale = if new_post_usable_for_next { 1.0 } else { 0.18 };
        score += dead_scale * (30.0 + 3.0 * deficit + 0.20 * item + 8.0 * progress);
    } else if next_item_size > 0 {
        // Reward leaving exactly enough room for the next item, and mildly reward
        // usable gaps that are close to the lookahead size.
        if post_residual == next_item_size {
            score -= 8.0 + 0.10 * next;
        } else {
            score -= 1.25 * (next / (post + 1.0));
        }
    }

    if is_new_bin {
        // Opening pressure: strongly avoid creating another open bin when usable
        // residual capacity already exists.
        let mean_frac = (mean_res / cap).clamp(0.0, 1.0);
        score += 18.0
            + 2.5 * open_f
            + 7.0 * fit_f
            + 12.0 * mean_frac * (1.0 + 0.05 * open_f);

        // Small reward if the new bin preserves enough room for the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: prefer using it instead of opening a new bin, unless doing so
        // creates a dead gap while a new bin would actually preserve the lookahead item.
        let safe_from_dead = next_item_size == 0
            || post_residual == 0
            || post_residual >= next_item_size;

        if safe_from_dead || !new_post_usable_for_next {
            score -= 10.0 + 1.2 * open_f + 6.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs();
        if post_residual >= next_item_size {
            // Next item fits here afterwards: reward tightness of that follow-up fit.
            score -= 2.0 * (bin_capacity as f64 - lookahead_gap as f64);
        } else {
            // Next item won't fit here after placement: mild penalty scaled by leftover size.
            score += 0.5 * post_residual as f64;
        }
        // Extra reward when post_residual exactly equals next item size (perfect chaining).
        if post_residual == next_item_size {
            score -= 200.0;
        }
    }

    // Penalize large dead space relative to mean residual across open bins.
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Slight preference for opening new bins early in the stream when many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress) * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 0.8 * tightness * (item_size as f64);

    // Penalize dead space: post_residual too small for any plausible future item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can fit the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * (next_item_size as f64);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        score += 20.0 - 0.2 * (item_size as f64);
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer filling existing bins
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.05 * crowding * (1.0 - progress);

    // Time horizon: late in the stream, be more aggressive about tight packing
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap;

    let mut score = post * (1.0 + 0.8 * progress);

    // Smooth non-linear penalty for awkward dead space
    score += 12.0 * x * (1.0 - x) * (1.0 - progress);

    // Reward tight fits
    score -= 10.0 * (1.0 - x) * (1.0 - x);

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead coupling: prefer bins whose leftover can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 8.0 * (1.0 - (post - nxt) / cap).abs();
        } else {
            score += 6.0;
        }
    }

    // Mild pressure against bin proliferation
    score += 0.5 * open_bins_count as f64 * progress;

    // Deviation from mean residual
    score += 0.3 * (post - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: divide capacity into 5 sub-capacity bands
    let band = post_residual / (bin_capacity / 5);
    match band {
        0 => score -= 30.0, // tiny dead space: excellent fill
        1 => score -= 12.0,
        2 => score += 0.0,
        3 => score += 10.0,
        _ => score += 20.0, // half-empty bin: wasteful placement
    }

    // Exact-fill reward (post_residual == 0 is perfect)
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic pairing: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0; // perfect harmonic pair
        } else if next_item_size <= post_residual {
            // fraction of post residual usable by next item
            let frac = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * frac;
        } else {
            score += 8.0; // next item cannot use this bin
        }
    } else {
        // last item: strongly prefer tightest fit
        score -= 40.0;
    }

    // Modulo arithmetic on post_residual: residues near multiples of common item sizes
    let r = post_residual % 10;
    if r == 0 {
        score -= 5.0; // residual aligns with decile: likely reusable
    } else if r < 5 {
        score += (5 - r) as f64; // small odd residue is dead space
    }

    // Last-chance bin: if this is the only fitting bin, penalize opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor
    if bin_residual == bin_capacity {
        // opening a fresh bin: baseline cost plus pressure from open bins
        score = 45.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 20.0; // big next item: fresh bin is attractive
        }
        if post_residual == 0 {
            score -= 100.0;
        }
    }

    // Late in the stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Prefer bins below mean residual (below-average fill) to balance? No: prefer filling fuller bins
    if (bin_residual as f64) > mean_residual {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // A nonzero leftover that is too small to ever hold a typical item is pure waste.
    // Penalize gaps in the "dead zone" (1..=12) aggressively; gap 0 (perfect fit) is untouched.
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 2.5;
    }
    // Perfect-fit bonus: reward exact closures strongly.
    if post_residual == 0 {
        score -= 25.0;
    }

    // --- Tightness reward: the fuller this bin gets relative to its available space, the better ---
    if bin_residual > 0 {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= tightness * 15.0;
    }

    // --- New-bin candidate handling ---
    // The empty bin gets a fixed handicap so it only wins when every open bin fits poorly.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If the item is huge, a fresh bin is actually a clean placement: soften the handicap.
        if item_size >= 70 {
            score -= 20.0;
        }
    }

    // --- Last-chance pressure: if this is the only bin that can host the item, grab it ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // --- Open-bins pressure: with many bins open, discourage leaving large slack ---
    // (prefer consolidating into the tightest bin rather than spreading residue around).
    let slack_frac = post_residual as f64 / bin_capacity as f64;
    score += open_bins_count as f64 * slack_frac * 4.0;

    // Prefer bins that are already fuller than the fleet average.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if post_residual > 0 && (next_item_size as f64) > post_residual as f64 {
            // Leftover cannot serve the next item: it risks becoming dead space.
            score += 5.0;
            // Extra penalty if that leftover sits in the dead zone.
            if post_residual <= 12 {
                score += 8.0;
            }
        } else if post_residual > 0 {
            // Leftover can accommodate the next item: reserve-friendly bonus.
            score -= 6.0;
        }
    }

    // Mild progression term: late in the stream, be slightly more tolerant of new bins
    // (fewer future opportunities to fix fragmentation).
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward a perfect chain fit
    // (next item exactly fills the post_residual).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Reward proportional leftover after the chained placement
            let chain_left = post_residual - next_item_size;
            score -= 25.0 * (chain_left as f64 / bin_capacity as f64);
            // Penalize chain placements that leave tiny dead space (< 10)
            if chain_left < 10 {
                score += 8.0;
            }
        } else {
            // Next item cannot follow in this bin; mild penalty scaled by overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 3.0 + 0.15 * over;
        }
    } else {
        // Last item: prefer tightest fit only
        score -= 5.0;
    }

    // Reward bins whose residual is already below the mean (well-utilized bins)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize opening a new bin when decent fitting bins exist,
    // unless the item is large and residual fragmentation is high.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 * item_size as f64 / bin_capacity as f64;
        score += 15.0 - 0.3 * pressure - 5.0 * progress;
        // If item is huge, opening fresh is less bad
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
        // If no open bin leaves a good residual for the next item, new bin is OK
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
    }

    // Small penalty for leaving awkward residuals in [1, 9] (dead space zone)
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize large dead space relative to mean residual across open bins.
    if (post_residual as f64) > mean_residual {
        score += 0.6 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Lookahead: if the next item would fit in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64 / bin_capacity as f64);
        } else if post_residual > 0 && post_residual < next_item_size {
            // Creating a gap too small for the next item: penalize proportionally.
            score += 0.4 * (post_residual as f64 / bin_capacity as f64) * (next_item_size as f64 / bin_capacity as f64) * 100.0;
        }
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (post_residual of an empty bin = capacity - item_size).
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin, scaled by how many bins already fit.
        let mut new_bin_penalty = 5.0 + 1.5 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            // If some open bin fits, discourage new bin unless that fit would be terrible.
            let best_other_gap = (bin_capacity - item_size) as f64; // worst-case proxy
            new_bin_penalty += 4.0;
            let _ = best_other_gap;
        }
        // Early in the stream, opening bins is cheaper (build diversity of residuals).
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_penalty *= (1.0 - 0.5 * (1.0 - progress));
        // Very large items leave little room anyway; new bin less wasteful.
        if item_size > bin_capacity * 3 / 4 {
            new_bin_penalty *= 0.6;
        }
        score += new_bin_penalty;
    }

    // Mild preference to fill bins with larger residual when many bins are open
    // (consolidation pressure).
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 / bin_capacity as f64);

    // Small time-varying tie-break to diversify residual profiles across the stream.
    let phase = ((step_index as f64 * 0.37).sin()) * 0.5;
    score += phase * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills (low post_residual) more aggressively;
    // later, tolerate slack slightly but punish dead space super-linearly.
    let progress_coupling = norm_pr * norm_pr * (1.0 + 2.0 * progress) - 0.5 * norm_pr * (1.0 - progress);
    score += 3.0 * progress_coupling;

    // Reward bins whose residual after placement matches the lookahead item well.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 2.0 * (1.0 - gap / cap) * (1.0 - progress);
    }

    // Last-chance bin: strongly reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0 + 6.0 * progress;
    }

    // Penalize opening a new bin unless the current item leaves a very tight residual.
    if bin_residual == bin_capacity {
        score += 2.0 * (1.0 - (1.0 - norm_pr) * (1.0 - norm_pr)) * (1.0 + progress);
    }

    // Mild pressure toward consolidating into fewer bins.
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // Nudge toward bins with residuals close to the mean (balanced packing).
    score += 0.5 * (mean_residual - bin_residual as f64).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity-fraction buckets. Residuals in "harmonically useful" classes
    // (divisible by common item sizes) are cheap; awkward ones are expensive.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity remaining after placement.
    let frac = pr / cap;

    // Class index via integer division on capacity fractions (harmonic classes):
    // class 0: pr == 0 (perfect fit) -> huge reward
    // class 1: pr in (0, 10]  -> dead space, heavy penalty
    // class 2: pr in (10, 25] -> awkward mid gap, moderate penalty
    // class 3: pr in (25, 50] -> useful half-ish class
    // class 4: pr in (50, 100] -> large space, fine
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score += 45.0 * (1.0 - frac);
    } else if post_residual <= 25 {
        score += 18.0;
    } else if post_residual <= 50 {
        score -= 8.0;
    } else {
        score -= 4.0;
    }

    // Modulo harmony: residual divisible by small common item sizes is reusable.
    if post_residual > 0 {
        let mut harmony = 0.0;
        for m in [10u32, 20, 25, 50].iter() {
            if post_residual % m == 0 {
                harmony += 6.0;
            }
        }
        score -= harmony;
    }

    // Lookahead coupling: reward if next item fits the post-residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Extra reward for exact harmonic match of next item with post-residual.
        if next_item_size == post_residual {
            score -= 25.0;
        } else if post_residual % next_item_size == 0 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; penalize leaving stranded medium gaps.
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral baseline; make it slightly less attractive
    // than a decent existing fit, but better than a bad fit.
    if bin_residual == bin_capacity {
        score += 10.0 - 10.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Mild pressure to consolidate into fewer bins as stream progresses.
    score += (open_bins_count as f64).ln().max(0.0) * (frac * 4.0);

    // Prefer bins whose residual is below the mean (filling emptier-of-space bins).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size of 1, but practically small gaps)
    // are heavily penalized.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward tight fits: perfect fill is best.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 10.0 * tightness * tightness;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this residual: penalize proportionally to wasted space
            score += 3.0 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.8 * (0.5 + 0.5 * progress);

    // New-bin candidate handling: opening a new bin is only attractive when the
    // current item fits poorly everywhere else. Base new-bin score near mean residual.
    if bin_residual == bin_capacity {
        score = mean_residual + 15.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 1 {
            // Never open a new bin when a unique fitting bin exists.
            score += 100.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.min(bin_capacity - 1) {
            score -= 5.0; // slight bonus if next item pairs well in a fresh bin
        }
    } else if post_residual >= mean_residual {
        // Keeping residuals balanced is mildly rewarded.
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score -= 0.5 * (bin_capacity as f64 - post_residual as f64);

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain fill
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize large dead space
            score += 0.3 * (post_residual as f64 - (bin_capacity as f64 * 0.5)).abs();
        }
    }

    // Relative to mean residual: prefer bins below mean residual (tighter than average)
    score += 0.4 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if next item is huge and this item is small, new bin may be good
        if next_item_size > 60 && item_size < 30 {
            score -= 20.0;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual more than linearly.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no future item can use: if post_residual < 10
    // it is nearly unusable; if it's small but nonzero, mildly bad.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 35.0; // perfect chain
        } else if gap < 10 {
            score -= 15.0;
        } else {
            score -= 8.0 * (1.0 - gap as f64 / cap);
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slight penalty for wasting chain potential.
        score += 5.0;
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins (avoid bin proliferation).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = open_bins_count as f64 / 20.0;
    let mean_res_norm = mean_residual / cap;
    if bin_residual < bin_capacity {
        score -= crowding * mean_res_norm * 20.0 * (0.5 + progress);
    }

    // New-bin candidate handling: empty bin should only win when open bins are
    // poor fits or very crowded. Add a base cost to the new bin that scales
    // with how many bins already fit the item.
    if bin_residual == bin_capacity {
        let fit_pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 55.0 * fit_pressure * (1.0 - 0.3 * progress)
            + crowding * 5.0
            - mean_res_norm * 10.0;
        if next_item_size > 0 && next_item_size >= item_size && next_item_size <= 100 - item_size {
            score -= 10.0; // new bin can host current + next item nicely
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new = bin_residual == bin_capacity;

    // Core: non-linear waste term (quadratic in post_residual, normalized).
    let mut score = (pr / cap).powf(1.7) * 60.0;

    // Smooth interaction: waste hurts more as the stream progresses (prefer closing bins late).
    score *= 1.0 + 0.8 * progress;

    // Lookahead coupling: smooth sigmoid-ish reward when the next item still fits here.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = (pr - nxt) / cap; // positive => next item fits
        let s = 1.0 / (1.0 + (-6.0 * fit_next).exp()); // smooth step
        score -= 12.0 * s;                 // reward chaining
        score += 8.0 * (1.0 - s) * (pr / cap); // penalize dead space unusable by next item
    }

    // Last-chance bin: strongly reward using it, smoothly scaled by how tight the fit is.
    if fitting_bins_count == 1 && !is_new {
        score -= 25.0 * (1.0 - pr / cap);
    }

    // New-bin candidate: mild smooth penalty that grows with open bins and mean residual,
    // encouraging reuse; scaled by how much space a fresh bin would leave.
    if is_new {
        score += 6.0 + 0.15 * open_bins_count as f64 + 0.05 * mean_residual;
        // Allow opening a new bin late in the stream when item is large (little waste anyway).
        score -= 10.0 * progress * (item_size as f64 / cap);
    }

    // Mild coupling with mean residual: prefer bins tighter than average (smooth).
    score += 0.08 * (pr - mean_residual).max(-cap).min(cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Harmonic class: post_residual bucketed by capacity fractions
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let frac = pr / cap; // 0..1
    if frac <= 0.1 {
        score -= 12.0; // excellent leftover, nearly perfect fill
    } else if frac <= 0.25 {
        score -= 4.0;
    } else if frac <= 0.5 {
        score += 2.0;
    } else {
        score += 8.0; // large dead space risk
    }

    // Modulo classes on post_residual (decimal harmonic classes)
    let pr_mod = post_residual % 10;
    if pr_mod == 0 {
        score -= 3.0; // round leftover aligns with typical item sizes
    } else if pr_mod >= 8 {
        score -= 1.0;
    } else {
        score += (10 - pr_mod) as f64 * 0.4; // awkward small slivers
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // leftover usable by next item: reward proportionally
            score -= 6.0 * (next_item_size as f64 / cap);
            // extra reward if leftover is close to next item (chained tight fit)
            let chain_gap = (post_residual - next_item_size) as f64;
            if chain_gap <= 5.0 {
                score -= 5.0;
            }
        } else {
            // leftover below next item: dead space unless tiny
            if post_residual <= 5 {
                score -= 2.0; // negligible waste, effectively closed
            } else {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening new bins when many bins already fit the item well
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline preference only if current item is large
        // relative to capacity (harmonic class: > 50% of capacity)
        if item_size as f64 <= cap * 0.5 && fitting_bins_count > 0 {
            score += 20.0; // prefer existing bins for small/medium items
        } else {
            score += 5.0;
        }
        // Fewer open bins => slightly prefer consolidation into existing bins
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += (open_bins_count as f64).min(10.0) * 0.5;
        }
    }

    // Stream progression: early in stream, be more conservative (favor tight fits
    // to build well-packed bins); late in stream, accept decent fits to close bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (cap - pr) * 0.05;

    // Mean residual coupling: if this bin's residual is far below mean, it's
    // already "specialized"; filling it further is good
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev.min(20.0) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later (but nonzero) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 20.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: reward if the next item fits exactly into the post residual,
    // penalize if it cannot fit (dead space confirmed).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size > post_residual {
            score += 15.0;
        } else {
            // next item fits: small residual left after that is fine
            let after_next = post_residual - next_item_size;
            if after_next < 10 && after_next > 0 {
                score += 10.0;
            } else {
                score -= 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 0.5;

    // Slight preference to fill bins below mean residual (tighter bins first).
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Early in the stream, tolerate opening new bins less (favor consolidation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure that grows with stream progress.
        score = 40.0 + 60.0 * progress + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 1 {
            // Never open a new bin when this is the only fitting bin.
            score += 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
