pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic bonus for small post-residual.
    score -= 1.6 * (bin_capacity as f64 - post_residual as f64) * (bin_capacity as f64 - post_residual as f64) / (bin_capacity as f64 * bin_capacity as f64) * 40.0;

    // Penalize dead space that no future item (min size 1) can plausibly fill.
    if post_residual > 0 {
        score += 0.35 * (post_residual as f64).ln() * 6.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // partial compatibility reward, scaled by how much room remains after pairing
            let pair_waste = post_residual as f64 - next_item_size as f64;
            score -= 22.0 * (1.0 - pair_waste / bin_capacity as f64);
        } else {
            // next item cannot use this residual: mild penalty proportional to gap
            score += 0.08 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item: prefer minimal residual strongly.
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Crowding pressure: many open bins -> prefer consolidating into existing bins.
    let crowding = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
    score += 0.9 * crowding * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in stream, opening new bins is cheaper; late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_penalty = 12.0 + 55.0 * progress;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus crowding cost, discounted early.
        score += new_bin_penalty + 0.15 * open_bins_count as f64;
        // If item is large relative to capacity, new bin is more acceptable.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Prefer bins whose residual is close to item (perfect fit) via sigmoid coupling.
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += 8.0 * (diff / 25.0).tanh();

    // Mean-residual coupling: if this bin's residual is far below mean, it is an outlier; use it.
    score -= 1.2 * (mean_residual - bin_residual as f64).max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post residual, with non-linear (quadratic) coupling.
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Tightness reward: non-linear reward for near-perfect fits.
    let tightness = 1.0 - pr / cap;
    score -= 12.0 * tightness * tightness * tightness;

    // Stream-progress coupling: as the stream advances, waste becomes costlier
    // (fewer chances to reuse dead space), so scale the penalty up smoothly.
    let progress_factor = 1.0 + progress * (1.0 + progress);
    score *= progress_factor;

    // Dead-space penalty relative to mean residual of open bins.
    score += 0.15 * (pr - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0 + 10.0 * progress;
    }

    // Lookahead: reward leaving residual that can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            score -= 6.0 * (1.0 - slack / cap);
        } else {
            // Penalize residuals that cannot fit the lookahead item proportionally.
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // New-bin candidate: neutral reference, slightly penalized so it is only
    // chosen when the fit into open bins is genuinely poor.
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * progress + 0.2 * pr;
    }

    // Mild penalty for bin proliferation late in the stream.
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, especially perfect fits.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    }

    // Harmonic class logic: classify post_residual by integer division thresholds.
    // Residual classes: dead (<10), awkward (10..30), useful (30..60), large (>=60).
    let class = post_residual / 25; // 0..4 harmonic class
    score += class as f64 * 8.0;

    // Modulo arithmetic: residuals that are multiples of common item sizes (10,20,25,50)
    // are more likely to be filled later.
    let r = post_residual;
    if r % 10 == 0 || r % 25 == 0 {
        score -= 12.0;
    }
    if r % 50 == 0 {
        score -= 8.0;
    }

    // Lookahead coupling: if the next item can fit into post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        // Extra reward if next item exactly fills the remaining space.
        if next_item_size == post_residual {
            score -= 30.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead space relative to the lookahead item: penalize.
        score += 6.0;
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity when the item
    // fits reasonably well elsewhere. Penalize the empty bin unless the item is
    // large and no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 30.0;
        // If few bins can fit the item, a new bin is more acceptable.
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else if fitting_bins_count <= 2 {
            score -= 15.0;
        }
        // Large items benefit from fresh bins.
        if item_size >= 60 {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
    }

    // Mild penalty when this bin's residual is far above the mean (unbalanced bins).
    let diff = bin_residual as f64 - mean_residual;
    if diff > 0.0 {
        score += diff * 0.1;
    }

    // Slight preference to fill bins with more existing load (fewer open bins overall).
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to host the next item
    // (or the smallest plausible item) are "unusable" gaps -> heavy penalty.
    let min_useful = if next_item_size > 0 { next_item_size } else { 1 };
    if post_residual < min_useful {
        let dead = min_useful - post_residual;
        score += 2.0 * dead as f64;
    }
    // Very small absolute gaps (< 10) are effectively dead space regardless.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / (item_size + post_residual).max(1) as f64;
    score -= 1.2 * tightness;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer packing into existing
    // bins rather than spreading; when few bins are open, opening new ones is cheap.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.4 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean-residual coupling: bins with residual far below mean are worse targets
    // (their space is nearly exhausted); bins above mean absorb items better.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.5 * next_item_size as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when no good existing option exists.
    // Base cost of opening a bin grows with open bins and stream progress.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64 + 20.0 * progress;
        // But if the item is large and would leave a big gap in any existing bin,
        // a fresh bin is fine: soften the penalty.
        if item_size >= 70 {
            score -= 20.0;
        }
        // If item is tiny, opening a bin is wasteful.
        if item_size <= 20 {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;

    // Base: prefer minimal post-residual (tight fit).
    let mut score = post;

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next > 0.0 {
        let gap = (post - next).abs();
        if gap < 1.0 {
            score -= 40.0; // perfect chain: next item seals this bin
        } else if post >= next {
            score -= 25.0 * (1.0 - gap / cap); // next item likely fits here
        } else {
            // next item won't fit; penalize dead space scaled by gap
            score += 10.0 * (gap / cap);
        }
    }

    // Penalize large residual relative to mean residual across open bins
    // (avoid leaving oversized holes while other bins are tighter).
    score += 0.5 * (post - mean_residual).max(0.0);
    score -= 0.25 * (mean_residual - post).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: default penalty so we only open when fits are bad.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Open a fresh bin if item is large and no good chaining exists
        if item_size as f64 > 0.7 * cap {
            score -= 45.0;
        }
        if next > 0.0 && next >= post - item_size as f64 {
            score += 10.0;
        }
    }

    // Slight preference for filling bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (1.0 - post / cap);

    // Small penalty proportional to open bins to encourage consolidation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic decay of wasted space.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += waste * waste * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: strongly favor bins where the next item also fits (chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0 + 0.35 * (next_item_size as f64);
        } else {
            // Penalize leaving a gap the next item almost fits into (dead space).
            let gap = post_residual as f64;
            if gap > 0.0 && (next_item_size as f64) - gap <= 15.0 {
                score += 18.0;
            }
        }
    } else {
        // Last item: just minimize residual.
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 22.0;
    }

    // Many open bins: prefer consolidating into existing bins over spreading.
    if open_bins_count > 2 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // Global residual pressure: if mean residual is low, keep roomy bins for future items.
    let pressure = mean_residual / bin_capacity as f64;
    score += pressure * 12.0;

    // Time horizon: early in the stream, be more selective (favor tight fits);
    // late in the stream, just fill whatever fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * waste * 20.0;
    score -= progress * 8.0;

    // New-bin candidate: only attractive when no open bin fits well
    // (large item relative to mean residual, or many badly-fitting bins).
    if bin_residual == bin_capacity {
        let poor_fit = (mean_residual < item_size as f64) || (fitting_bins_count == 0);
        if poor_fit {
            score -= 35.0;
        } else {
            // Discourage opening new bins when existing bins can absorb the item.
            score += 45.0 + 0.5 * item_size as f64;
        }
    }

    // Small coupling: reward filling bins that are already partially used when
    // open-bin count is high (bin consolidation).
    let used = (bin_capacity - bin_residual) as f64;
    score -= 0.05 * used * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with smooth polynomial shaping.
    let mut score = norm_pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Non-linear coupling of post_residual with stream progress:
    // early on, tolerate larger residuals (bins stay flexible);
    // late, penalize residual more aggressively (tight packing matters).
    let progress_weight = 1.0 + 1.5 * t * t;
    score *= progress_weight;

    // Smooth interaction: penalize residuals that are "just barely" too small
    // for a plausible next item (dead-space coupling via lookahead).
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = ns - pr;
        if gap > 0.0 {
            let g = gap / cap;
            score += 0.6 * g * (1.0 - g) * (1.0 + t);
        } else {
            // next item fits too: reward with smooth discount
            let f = (-gap) / cap;
            score -= 0.4 * f * (1.0 - f) * (1.0 - 0.5 * t);
        }
    }

    // Last-chance bonus: only one fitting bin, avoid opening new bins late.
    if fitting_bins_count == 1 {
        score -= 0.5 * (1.0 - t) * (1.0 - t);
    }

    // Mild penalty proportional to residual deviation from mean residual
    // (smooth diversification across open bins).
    score += 0.15 * (pr - mean_residual) / cap;

    // New-bin candidate: keep it competitive only when open bins are tight.
    if bin_residual == bin_capacity {
        score = 0.45 + 0.5 * t - 0.1 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residue classes mod small integers
    // capture "how reusable" the leftover space is against typical item sizes.
    let pr = post_residual as u32;
    let cls5 = (pr % 5) as f64;      // fine-grained residue
    let cls10 = (pr % 10) as f64;    // decade residue
    let cls25 = (pr % 25) as f64;    // quarter-capacity residue
    // Reward post-residuals that align with common modulo classes (likely re-fittable)
    score -= 2.0 * ((4.0 - cls5) / 4.0) * (pr as f64 / cap);
    score -= 1.5 * ((9.0 - cls10) / 9.0) * (pr as f64 / cap);
    score -= 1.0 * ((24.0 - cls25) / 24.0) * (pr as f64 / cap);

    // Integer-division thresholds: post_residual bucketed by quotients of 10
    let bucket = pr / 10;
    score -= (bucket as f64) * 0.8; // larger usable leftover is good

    // Perfect/near-perfect fits are excellent
    if post_residual == 0 { score -= 100.0; }
    else if post_residual <= 3 { score -= 40.0; }
    else if post_residual <= 10 { score -= 15.0; }

    // Lookahead: does next_item_size fit exactly into the post-residual?
    if next_item_size > 0 {
        let nx = next_item_size as u32;
        if nx == pr {
            score -= 60.0; // exact chained fit
        } else if nx < pr {
            let waste = pr - nx;
            if waste <= 10 { score -= 20.0; }
            score -= (pr as f64 - waste as f64) * 0.3;
        } else {
            // next item cannot use this residual: dead space risk grows
            score += (nx - pr) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless current residual is tiny/awkward
    if bin_residual == bin_capacity {
        // new bin has full residual; make it attractive only if existing residual is fragmented
        score = cap - 5.0;
        if mean_residual < 12.0 { score -= 20.0; }
        if fitting_bins_count == 0 { score -= 50.0; }
        if next_item_size > 0 && next_item_size as u32 > mean_residual as u32 { score -= 10.0; }
    } else {
        // prefer bins whose residual is below mean (consolidate fullness)
        if (bin_residual as f64) < mean_residual { score -= 6.0; }
        // avoid spreading across too many bins late in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += open_bins_count as f64 * 0.05 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps much harder
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 25 {
        score += 12.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 60.0;
    }

    // Prefer bins whose residual was already small (tight packing pressure)
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (handled implicitly since a new empty bin has max post_residual),
    // but add explicit pressure against spreading when many bins are open.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item would be blocked by a tiny dead gap, penalize
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 15.0;
    }

    // Mild preference for keeping residuals near the mean (balance)
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    // Early stream: slightly favor consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Lookahead: reward if next item fits snugly into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as u32 >= next_item_size {
            // next item fits: reward tightness
            score -= 25.0 * (1.0 - diff / cap);
        } else {
            // next item won't fit here: penalize wasted potential
            score += 10.0 + 0.3 * diff;
        }
    }

    // Penalize post_residual far below mean residual (creates dead space)
    let mean_gap = post_residual as f64 - mean_residual;
    if mean_gap < 0.0 {
        score += 0.25 * (-mean_gap);
    } else {
        score -= 0.05 * mean_gap;
    }

    // Last chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no good existing fit
    if bin_residual == bin_capacity {
        let penalty = if fitting_bins_count <= 1 {
            0.0
        } else {
            let tightness = (bin_residual - item_size) as f64 / cap;
            15.0 + 30.0 * (1.0 - tightness)
        };
        score += penalty;
    }

    // Slight stream-progression bias toward consolidating late
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.02;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) - norm_pr * progress * (1.0 - norm_pr);
    score += 30.0 * coupling;

    // Reward tight fits, scaled by progress
    score -= (item_size as f64 / cap) * (1.0 + progress) * 10.0;

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (0.5 + progress);
        } else {
            score -= ((pr - nxt) / cap) * 15.0 * (1.0 - progress);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many bins when mean residual is high
    score += (open_bins_count as f64).ln() * (mean_residual / cap) * 5.0 * progress;

    // Penalize opening a new bin when existing bins fit well
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += mean_residual * 0.5 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls in a
    // "usable" residue class (multiples of 10) are more likely to host
    // future items, so reward them; odd/dead residues get penalized.
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10;
        if class == 0 {
            score -= 12.0; // perfectly aligned leftover
        } else if class <= 3 {
            score += 4.0; // near-aligned but likely dead
        } else {
            score += 8.0; // awkward residue
        }
        // Dead-space cliff: leftover too small for the smallest plausible item
        if pr < 10 && pr > 0 {
            score += 30.0;
        }
        // Harmonic usability: can leftover hold a "half-capacity" chunk?
        if pr >= 50 {
            score -= 10.0;
        } else if pr >= 25 {
            score -= 5.0;
        }
    }

    // Lookahead coupling: reward bins whose post_residual still fits the
    // next item (chaining), penalize bins that waste the next item's slot.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.1 * (post_residual - next_item_size) as f64;
        } else {
            score += 3.0;
        }
        // Modulo harmony: post_residual and next item share a residue class
        if post_residual % 10 == next_item_size % 10 && post_residual >= next_item_size {
            score -= 4.0;
        }
    }

    // Integer-division thresholds on tightness of fit
    let tight = bin_residual / item_size.max(1);
    if tight == 1 {
        score -= 15.0; // near-perfect fill
    } else if tight == 0 {
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let base = cap * 0.5;
        score += base;
        if fitting_bins_count == 0 {
            score -= cap; // must open a bin
        } else if mean_residual < item_size as f64 * 1.2 {
            score -= 10.0; // open bins are nearly full anyway
        } else {
            score += 15.0; // prefer packing into existing bins
        }
    }

    // Progress-aware mild consolidation pressure
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64).abs() * 0.05;
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (1..100 range, but typical items >= 10) are dead space.
    let dead_threshold = 9.0;
    if (post_residual as f64) < dead_threshold {
        score += 60.0; // hard penalty for unusable slivers
    } else if (post_residual as f64) < 20.0 {
        score += 15.0; // risky small gap
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 10.0; // this bin likely becomes dead after this placement
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new ones
    // and prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 35.0 + 10.0 * pressure;
    } else {
        score -= 5.0 * pressure.min(3.0);
    }

    // Prefer bins whose residual is near the mean (balanced packing),
    // penalize outliers that hoard space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.17;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * bin_capacity as f64 * 0.1;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize leaving dead space that no plausible item (10..80) can use,
    // unless it is exactly a usable gap.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable sliver
    }

    // Lookahead coupling: if next item fits in the post_residual, reward it;
    // if next item would be wasted, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 + 0.2 * next_item_size as f64;
        } else {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current bins are crowded or the item is huge and fits nothing well.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowding = if open_bins_count > 0 {
            1.0 - (mean_residual / bin_capacity as f64)
        } else {
            1.0
        };
        // Base cost of opening a new bin.
        score += 45.0;
        // Cheaper to open when existing bins are nearly full on average.
        score -= 30.0 * crowding;
        // Large items justify fresh bins more.
        score -= 0.25 * item_size as f64;
        // Slight preference to consolidate early, spread late.
        score += 10.0 * (1.0 - progress);
        // If no bin can fit at all, this call is the fallback: make it win.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mild penalty for scattering across many bins when mean residual is high.
    if open_bins_count > 3 && mean_residual > 30.0 && bin_residual < bin_capacity {
        score += 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: quadratic penalty on leftover space, modulated by stream progress.
    // Early on, tight fits matter (minimize waste); later, slightly relax to keep bins open.
    let mut score = pr * (1.0 + 0.9 * pr_norm) * (1.0 + 0.5 * progress);

    // Smooth coupling: reward filling bins deeply when many bins are open.
    let fill = 1.0 - pr_norm;
    score -= 12.0 * fill * fill * (open_bins_count as f64).ln1p();

    // Mean-residual coupling: penalize making this bin's residual deviate far from mean
    // (keeps residual profile balanced, reducing fragmentation).
    score += 0.35 * (pr - mean_residual).abs();

    // Lookahead coupling: reward residuals that can host the next item smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let compat = (pr - nx).abs() / cap;
        score -= 8.0 * (-3.0 * compat).exp();
        // exact fit for next item is very valuable
        if pr >= nx {
            score -= 4.0 * (1.0 - ((pr - nx) / cap).powi(2));
        }
    } else {
        // last item: strongly prefer minimal leftover
        score -= 6.0 * fill;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        score += 25.0 - 20.0 * progress;
        // opening is attractive if item is large relative to capacity (fresh space useful)
        score -= 0.15 * item_size as f64;
    }

    // Smooth cubic stream term: slight preference for consolidation early, spreading late.
    score += 6.0 * progress * progress * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but treat dead space non-linearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;                       // reward high fill fraction
    score += 0.15 * (post_residual as f64).powf(1.4); // superlinear penalty on leftover

    // Harmonic class of post_residual: residues mod small moduli.
    let pr = post_residual as i64;
    let r3 = pr % 3;
    let r5 = pr % 5;
    let r7 = pr % 7;
    score -= 2.0 * (r3 as f64) - 1.5 * (r5 as f64) + 1.0 * (r7 as f64);

    // Class of the residual by integer division thresholds (capacity fractions).
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.10 {
        score -= 8.0; // near-perfect closure, strongly favor
    } else if frac < 0.20 {
        score -= 4.0;
    } else if frac < 0.30 {
        score += 2.0;
    } else if frac > 0.60 {
        score += 5.0; // leaving a big hole is bad
    }

    // Dead space only matters if nothing else can use it: penalize residuals
    // smaller than the smallest plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // unusable sliver
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0 + 0.1 * next_item_size as f64; // chain placement possible
            // harmonic class of next item
            let nc = next_item_size % 10;
            if nc == 0 {
                score -= 3.0; // round next item pairs well with round residuals
            }
        } else {
            score += 3.0; // this bin will die after this item
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 10.0;
        if fit_ratio < 0.4 {
            score += 14.0; // poor fit in the only bin -> maybe new bin better
        }
    }

    // New-bin candidate handling: opening a bin is only attractive early or
    // when all open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fit = mean_residual / bin_capacity as f64;
        score = 30.0
            + 25.0 * (1.0 - progress)          // cheap to open early
            + 8.0 * (open_bins_count as f64).sqrt()
            - 20.0 * avg_fit.max(0.0);          // open if existing residuals are tight
        if next_item_size > item_size && next_item_size > 50 {
            score -= 5.0; // big next item: fresh bin useful
        }
    }

    // Mild stream-progress drift: tighten standards as stream advances.
    score -= 3.0 * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable gap
    } else if post_residual == 0 {
        score -= 10.0; // perfect fill reward
    }

    // Non-linear dead-space penalty: residual in the awkward 1..=30 band is
    // increasingly wasteful since most items (10..80) cannot use it.
    if post_residual >= 1 && post_residual <= 30 {
        let r = post_residual as f64;
        score += (30.0 - r) * (30.0 - r) * 0.08;
    }

    // Open-bin pressure: discourage spreading across many bins when
    // alternatives exist; mild penalty grows with open_bins_count.
    score += open_bins_count as f64 * 0.35;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it unattractive unless this bin would be a
    // poor host (large dead space). Baseline penalty for opening new bin.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If current bin would leave a large unusable gap, opening a fresh
        // bin becomes competitive: reduce the penalty.
        if post_residual >= 40 && bin_residual != bin_capacity {
            score -= 20.0;
        }
        // Lookahead: if next item is large, a fresh bin preserves capacity.
        if next_item_size > 50 {
            score -= 8.0;
        }
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 4.0; // gap cannot serve next item: mild penalty
        }
    }

    // Prefer bins with lower residual relative to the mean (tighter bins,
    // consolidating fill); slight correction term.
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Early-stream: be more tolerant of spreading to build good bin structure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness);

    // Aggressive 2-step lookahead: reward when the next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.35 * overflow; // next item won't fit here
        }
    } else {
        // Last item: prefer minimal final waste.
        score += 0.5 * post_residual as f64;
    }

    // Penalize bins already far below mean residual (fragmented bin).
    score += 0.4 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when other bins fit; relax slightly when many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut open_penalty = 45.0 + 20.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            open_penalty -= 5.0; // fresh bin guarantees next-item fit
        }
        if fitting_bins_count == 0 {
            open_penalty -= 30.0; // no alternative
        }
        if fitting_bins_count == 1 {
            open_penalty += 15.0; // last-chance open bin is better
        }
        if open_bins_count > 6 {
            open_penalty -= 8.0;
        }
        score += open_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    score -= (bin_capacity as f64 - post_residual as f64).sqrt() * 2.0;

    // Penalize leaving dead space that no small item can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // near-perfect fit
    }
    if post_residual > 0 && post_residual < item_size.min(20) {
        score -= 3.0;
    }

    // Lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
        // Extra reward when next item fills the bin almost exactly.
        let gap = post_residual as f64 - next_item_size as f64;
        if gap < 10.0 {
            score -= 4.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // Penalize leaving space the next item cannot use.
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else {
        // Slight penalty when many bins fit, encouraging consolidation.
        score += (fitting_bins_count as f64).ln() * 1.5;
    }

    // New-bin candidate: only attractive when open bins have poor fit.
    if bin_residual == bin_capacity {
        let best_alt = mean_residual - (mean_residual - post_residual as f64).abs();
        // Prefer new bin if item is large relative to typical residuals.
        let tightness = item_size as f64 / bin_capacity as f64;
        let pressure = if mean_residual > 0.0 { item_size as f64 / mean_residual } else { 0.0 };
        // Base cost of opening a bin, discounted by pressure and stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_cost = 60.0 - 25.0 * pressure.min(2.0) - 10.0 * progress;
        score = open_cost + post_residual as f64 * 0.1;
        // If no lookahead synergy and item is small, opening is worse.
        if next_item_size > 0 && next_item_size > post_residual {
            score += 10.0;
        }
        let _ = best_alt;
    }

    // Mild preference to fill bins with larger residuals early (balance load).
    score -= (bin_residual as f64) * 0.05;

    // Small noise-free tie-break by bin index proxy via open_bins_count.
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear polynomial shaping of post_residual.
    let mut score = pr - 0.8 * pr * norm_pr + 0.3 * pr * norm_pr * norm_pr;

    // Smooth coupling with stream progress: waste matters more early,
    // and residual consolidation matters more late.
    score += (1.0 - progress) * 0.15 * pr * (norm_pr - 0.5) * (norm_pr - 0.5);
    score -= progress * 0.5 * (1.0 - norm_pr) * (1.0 - norm_pr) * cap * 0.1;

    // Reward tightness relative to mean residual across open bins.
    score -= 0.4 * (mean_residual - pr) / cap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 10.0 * (1.0 - progress);
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 3.0 * (1.0 - (pr - nxt) / cap);
        } else {
            // Penalize leaving residuals that no small follow-up can use.
            score += 0.2 * (pr - nxt).abs();
        }
    }

    // Mild penalty for opening a brand-new bin when many bins are already open.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual classes mod 10 and integer-division bands.
    let pr = post_residual as u32;
    let cls = pr % 10;
    let band = pr / 10; // 0..=9 harmonic band

    // Reward small, "usable" residuals: residuals in [10..30] are prime targets for mid-size items.
    if pr > 0 {
        match band {
            0 => score -= 18.0,                 // 0..9: near-perfect fill
            1 => score -= 12.0,                 // 10..19: excellent
            2 => score -= 8.0,                  // 20..29: good
            3 => score -= 3.0,                  // 30..39: moderate
            4 | 5 => score += 2.0,              // 40..59: wasteful
            6 | 7 => score += 5.0,              // 60..79: very wasteful
            _ => score += 8.0,                  // 80..100: nearly untouched bin
        }
        // Modulo coupling: residuals divisible by 10 are "harmonic" with typical item sizes.
        if cls == 0 { score -= 4.0; }
        if cls == 5 { score -= 1.5; }
        // Odd residuals pair poorly with even items (common case).
        if cls % 2 == 1 { score += 1.0; }
    } else {
        score -= 25.0; // perfect closure
    }

    // Lookahead: does post_residual admit next_item_size exactly / closely?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= next_item_size {
            let slack = (pr - next_item_size) as f64;
            // Next item fits in the leftover: strong reward, best when slack is small.
            score -= 10.0 + 8.0 * (1.0 - slack / bin_capacity as f64);
            if slack == 0.0 { score -= 6.0; }       // chain of perfect fits
            if slack < 10.0 { score -= 3.0; }       // near-perfect chain
        } else {
            // Leftover too small for next item: penalize proportionally to wasted class.
            let gap = (next_item_size - pr) as f64;
            score += 2.0 + 6.0 * (gap / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a fresh bin: high residual (100) is naturally bad, add extra.
        score += 12.0;
        // But if many bins are open and mean residual is large (fragmentation), a fresh bin
        // is attractive: subtract to make it competitive.
        let frag = mean_residual / bin_capacity as f64;
        if frag > 0.5 {
            score -= 14.0 * frag;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Prefer spreading across bins when few are open; prefer dense packing when many are open.
    let open_f = open_bins_count as f64;
    score += (open_f / (open_f + 8.0)) * (post_residual as f64 / bin_capacity as f64) * 6.0;

    // Exact-fit reward relative to the item itself.
    if post_residual == 0 { score -= 5.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize residuals in the awkward band (just above the smallest item, hard to fill).
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward bins whose post-residual exactly matches the next item (lookahead chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    }
    // Penalize leaving a gap that the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Reward using the tightest bin: closeness of fit.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 5.0;

    // Last-chance bin: strongly prefer filling the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins fit poorly (large post_residual) or there are many open bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 55.0;
        // Cheaper to open bins early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // Pressure from number of open bins.
        score += open_bins_count as f64 * 3.0;
        // If existing bins would leave a big dead gap, new bin becomes competitive.
        score -= (post_residual as f64) * 0.1;
    }

    // Mild pressure to consolidate: prefer bins with below-average residual
    // (i.e., fuller bins) to concentrate waste in few bins.
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: reward when next item fits the post residual exactly/well
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_fit = next_item_size as f64 / post_residual as f64;
            // perfect chain: post_residual == next_item_size
            let chain_bonus = if post_residual == next_item_size {
                60.0
            } else {
                40.0 * next_fit * next_fit
            };
            score -= chain_bonus;
        } else {
            // next item cannot follow: penalize wasted post residual
            score += 15.0;
        }
    } else {
        // last item: just minimize post residual
        score -= 10.0;
    }

    // Relative to mean residual: prefer bins that are already below-average residual (well-used)
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: prefer it only when item is large and no good fit exists
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        let open_penalty = 40.0 + 10.0 * open_bins_count as f64;
        score += open_penalty * (1.0 - tightness);
        // opening a bin is good for huge items (little waste anyway)
        if tightness > 0.8 {
            score -= 30.0;
        }
    }

    // Mild progression scaling: early on, be more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving small unusable gaps (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 5.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to wasted potential.
            score += 3.0;
        }
    }

    // Prefer filling bins that are already relatively full compared to the mean residual.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Mild penalty on spreading across many open bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only when existing bins are fragmented or
        // the item is large relative to typical residuals.
        let fragmentation = (mean_residual - item_size as f64).abs();
        score += 30.0
            - 20.0 * progress
            - (open_bins_count as f64).ln().max(0.0) * 2.0
            + 0.1 * fragmentation;
    } else {
        // Slight preference for bins with less residual as stream matures.
        score += (1.0 - progress) * 2.0;
    }

    // Encourage perfect fills.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // non-linear coupling: squared post-residual weighted by stream progress
    score += 30.0 * norm_pr * norm_pr * (0.5 + progress);
    // smooth interaction: perfect-fit reward decaying with progress
    let fit = 1.0 - (pr as i64 - 0) as f64 / cap;
    score -= 20.0 * (-norm_pr * 8.0).exp() * (1.0 - progress * 0.5);
    // penalize dead space relative to mean residual
    score += 5.0 * (norm_pr - mean_residual / cap).abs() * (1.0 + progress);
    // lookahead: reward residual compatible with next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx) / cap;
        score += 15.0 * gap * gap;
        score -= 10.0 * (-(pr - nx).abs() / 10.0).exp();
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }
    // new-bin candidate: mild penalty to prefer reusing open bins early
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 6.0 * (open_bins_count as f64).ln().max(0.0);
    }
    let _ = fit;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as u32;
    let progress = step_index as f64 / (total_items as f64).max(1.0);

    // Perfect fit: strong reward
    if pr == 0 {
        score -= 60.0;
    }

    // Harmonic class logic on post_residual (integer division thresholds by tenths of capacity)
    if pr > 0 {
        let class = pr / 10; // 0..9 harmonic class of dead space
        match class {
            0 => score += 10.0,           // tiny unusable sliver (1..10): dead space
            1 => score -= 2.0,            // 10..19: potentially usable
            2 => score -= 4.0,            // 20..29
            3 => score -= 5.0,            // 30..39
            4 => score -= 4.0,            // 40..49
            5 => score -= 3.0,            // 50..59
            _ => {}                       // large residual: neutral (near-empty bin)
        }

        // Lookahead coupling: does the next item fit in the leftover?
        if next_item_size > 0 {
            if pr >= next_item_size {
                // leftover chains with next item: reward proportional to tightness
                score -= 8.0 + next_item_size as f64 * 0.25;
            } else {
                // leftover is dead for the lookahead: penalty grows with gap
                score += 12.0 + (next_item_size - pr) as f64 * 0.5;
            }
        }

        // Modulo arithmetic: residuals near multiples of common small sizes are reusable
        if pr % 10 == 0 && pr >= 20 {
            score -= 3.0;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // competition exists: prefer tighter fits mildly
        score += 2.0;
    }

    // Prefer bins whose residual is near the mean residual (balanced packing)
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    // Penalize opening too many bins early
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Baseline cost: opening a new bin wastes the whole residual
        score = bin_capacity as f64 - item_size as f64 + 25.0 + progress * 10.0;
        // If no (or exactly one marginal) open bin fits, opening a new bin becomes attractive
        if fitting_bins_count == 0 {
            score -= 40.0;
        } else if fitting_bins_count == 1 {
            score -= 18.0;
        }
        // If the next item is large, a fresh bin preserves flexibility
        if next_item_size > 50 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 && post_residual > 0 {
        score += 15.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward scaled by how well item matches residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage spreading across too many bins unless fit is good.
    let pressure = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()) * 2.0;
    score += pressure * (1.0 - fit_ratio);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let good_fit_exists = mean_residual >= item_size as f64 * 1.05 && fitting_bins_count > 0;
        if good_fit_exists {
            score += 50.0; // discourage opening new bin when decent fits exist
        } else {
            score -= 10.0;
        }
        // Late in stream, opening new bins is fine since leftovers are unlikely to be reused.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
    }

    // Lookahead: if next item fits the post-residual exactly, bonus for keeping this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Mild preference for bins below mean residual (consolidate into emptier bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is excellent.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // 2-step lookahead: if the next item exactly fills the post_residual,
    // this is a perfect pairing — reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize leftover slack after both placements
            let slack_after_next = post_residual - next_item_size;
            score -= 15.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // next item won't fit in residual: penalize proportionally to waste
            let overflow = next_item_size - post_residual;
            score += 0.15 * overflow as f64;
        }
    }

    // Compare against mean residual across open bins.
    // Bins with residual below mean are "scarce" — using them for a tight
    // fit is valuable; penalize leaving big residuals relative to mean.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        score += 8.0 * (rel - 1.0).abs().min(3.0);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin gets a moderate penalty so
    // it is only chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Early in the stream, opening bins is cheap-ish; later, avoid it.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    }

    // Mild penalty for leaving residuals that are "dead zones" (small,
    // unlikely to fit typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: prefer bins where the item fills a large fraction of residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness * tightness;

    // Penalize large dead space that cannot fit typical future items.
    if post_residual > 0 {
        if post_residual < next_item_size && next_item_size > 0 {
            score += 6.0; // dead space too small for the lookahead item
        }
        if post_residual < 10 {
            score -= 4.0; // near-perfect fill
        }
    }

    // Lookahead coupling: bonus if post_residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    // Mild penalty if next item would fit comfortably elsewhere anyway.
    if next_item_size > 0 && post_residual > next_item_size * 2 {
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // bins are very full on average (mean residual low) or few bins fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0
            - 4.0 * (mean_residual / bin_capacity as f64)
            - 5.0 * (1.0 - progress);
        if fitting_bins_count > 2 {
            score += 10.0; // plenty of alternatives; discourage new bin
        }
    } else {
        // Prefer bins whose residual is below the mean (denser bins first).
        let diff = mean_residual - bin_residual as f64;
        score -= 0.05 * diff;
    }

    // Mild preference to spread load when many bins are open.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: penalize leftover space, but with non-linear decay (small leftovers are cheap).
    let mut score = x * x * (3.0 - 2.0 * x) * cap * 0.5 + pr;

    // Smooth coupling with stream progress: early on tolerate slack (more items to come),
    // later be strict about waste.
    score += 12.0 * (1.0 - progress) * x;
    score -= 8.0 * progress * (1.0 - x) * (1.0 - x);

    // Reward tight fits, more strongly as stream progresses.
    score -= (1.0 - x) * (item_size as f64 / cap) * (2.0 + 6.0 * progress);

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: if next item fits in the post residual, reward; if it barely misses, penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr as f64 {
            score -= 5.0 * (nx / cap);
        } else {
            score += 3.0 * (nx - pr as f64) / cap;
        }
    }

    // Mild penalty for spreading across many open bins with large mean residual.
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "useful" sizes
    // (small multiples of common item classes), penalize awkward dead space.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        let cls = pr % 10;
        match cls {
            0 => score -= 18.0,          // round residual: highly reusable
            5 => score -= 8.0,           // half-class residual
            1 | 9 => score += 10.0,      // awkward sliver risk
            2 | 8 => score += 5.0,
            3 | 7 => score -= 2.0,
            _ => {}
        }
        // Integer-division thresholds: residual usable by next item?
        if next_item_size > 0 {
            if pr >= next_item_size {
                // next item fits here afterwards: strong reward, scaled by fit tightness
                let slack = (pr - next_item_size) as f64;
                score -= 25.0 - (slack / cap) * 20.0;
            } else {
                // next item cannot use this residual: penalize proportional dead space
                score += (pr as f64) * 0.35;
            }
            // chain fit: residual >= item + next (both fit later in this bin's class)
            if pr >= item_size + next_item_size {
                score -= 12.0;
            }
        }
    }

    // Capacity-fraction coupling: prefer bins whose fill ratio lands on harmonic fractions
    let fill = (bin_capacity - bin_residual) as f64 / cap;
    let frac = fill * 4.0;
    if (frac - frac.round()).abs() < 0.05 {
        score -= 6.0; // fill at 1/4, 1/2, 3/4 boundaries
    }

    // Tightness reward: placing into a bin that just barely fits
    let tight = (bin_residual - item_size) as f64;
    score -= (cap - tight) * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tighter ones (already covered) but
        // add slight penalty for spreading across many open bins
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // New-bin candidate: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity && item_size < bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // base penalty so existing bins usually win
        score += 45.0;
        // but if item is huge relative to mean residual, a fresh bin is better
        if (item_size as f64) > mean_residual * 0.9 {
            score -= 55.0;
        }
        // late in stream, consolidate rather than open new bins
        score += progress * 10.0;
        // many open bins with small residuals: opening fresh bin spreads waste
        if mean_residual < 25.0 && open_bins_count > 3 {
            score -= 20.0;
        }
    }

    // Mild pressure to keep open-bin count low
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: harshly penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize mid-range dead space that is hard to fill (10..20).
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: penalize using bins when many are open,
    // encouraging consolidation into fewer bins.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if post_residual is nonzero but too small for next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by stream progression.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 70.0 + 30.0 * progress;
        // Make new bin more attractive if existing bins would leave bad gaps.
        if post_residual == bin_capacity - item_size && item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Slight tie-break toward bins below mean residual (more filled bins).
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect chain fit (post_residual == next_item_size)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // chain possible but imperfect: mild reward scaled by closeness
        let diff = (post_residual as f64 - next_item_size as f64).abs();
        score -= 30.0 / (1.0 + diff / 10.0);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // dead space relative to lookahead item
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Relative to mean residual: bins with residual below mean are "tighter" -> prefer filling them
    let res = post_residual as f64;
    score += (res - mean_residual) * 0.3;

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin unless current bins are all poor fits
    if bin_residual == bin_capacity {
        score += 25.0;
        if next_item_size > 0 && next_item_size >= item_size {
            // if next item is large, new bin keeps a big residual for it
            score -= 15.0;
        }
    } else {
        // small bonus for filling existing bins, stronger late in the stream
        let progress = step_index as f64 / total_items as f64;
        score -= 5.0 + 10.0 * progress;
    }

    // Penalize leaving large unusable gaps
    if res > 0.0 && res < 10.0 {
        score += 20.0; // tiny residual is nearly dead space
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square post-residual to punish wasteful placements.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 20.0;

    // Lookahead synergy: bonus if next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + (next_item_size as f64 / bin_capacity as f64) * 8.0;
        } else if next_item_size > post_residual {
            // Penalize leaving a residual too small for the next item (dead space risk)
            let waste = (post_residual as f64) * (post_residual as f64);
            score += waste * 0.15;
        }
    } else {
        // Last item: strongly prefer minimizing residual
        score -= 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fit is bad
    // or open bins are crowded.
    if bin_residual == bin_capacity {
        let avg_fit_quality = if bin_capacity as f64 > 0.0 {
            mean_residual / bin_capacity as f64
        } else {
            0.0
        };
        // Base cost of opening a new bin
        score += 25.0;
        // If open bins have plenty of room and item fits well somewhere, discourage new bin
        if fitting_bins_count > 0 {
            score += 10.0 * (1.0 - avg_fit_quality);
        }
        // Early in stream, opening bins is cheaper (build diversity of open bins)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
        // Few open bins: cheaper to open another
        score -= (5.0f64).min(open_bins_count as f64) * 2.0;
    }

    // Prefer bins whose residual is close to mean (balance load across bins)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 3.0 / (1.0 + dev * 0.1);

    // Slight preference for filling bins that are already partly used
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: penalize wasted residual, non-linearly (quadratic + cubic waste term)
    let mut score = pr + 18.0 * pr_norm * pr_norm + 40.0 * pr_norm.powi(3);

    // Tight fits are strongly rewarded (small post-residual preferred)
    let tightness = 1.0 - pr_norm;
    score -= 25.0 * tightness * tightness;

    // Stream-progress coupling: early on, prefer flexible bins (keep residual large);
    // later, tolerate tighter fits and penalize waste more aggressively.
    let flexibility = pr_norm * (1.0 - progress);
    score -= 15.0 * flexibility;
    score += 30.0 * progress * pr_norm * pr_norm;

    // Dead-space penalty if residual becomes too small to be useful
    let min_useful = 10.0;
    if pr < min_useful && pr > 0.0 {
        score += (min_useful - pr) * 2.0;
    }

    // Lookahead: reward leaving room for the next item; penalize blocking it
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 12.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: slight preference to consolidate into existing bins
    score += 0.5 * open_bins_count as f64 * pr_norm;

    // New-bin candidate: keep it neutral-to-slightly-high so it only wins when fits are bad
    if bin_residual == bin_capacity {
        score += 6.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that are "usable"
    // (multiples of common item sizes) are rewarded.
    let pr = post_residual;
    let usable = if pr == 0 { 60.0 }
        else if pr <= 10 { 40.0 }
        else if pr % 10 == 0 { 30.0 }
        else if pr % 5 == 0 { 20.0 }
        else if pr % 2 == 0 { 8.0 }
        else { 0.0 };
    score -= usable;

    // Dead-space penalty: tiny odd residuals are nearly unusable.
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 3.0;
    }

    // Coupling with next item: reward residuals that can host the lookahead.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 25.0 + (next_item_size as f64) * 0.2;
            // exact chain: post_residual equals next item size -> perfect pair
            if pr == next_item_size {
                score -= 30.0;
            }
        } else {
            // next item cannot follow here; slight penalty scaled by waste
            let gap = (next_item_size - pr) as f64;
            score += gap * 0.15;
            // but if next item fits a fresh bin exactly, prefer keeping this bin tight
            if bin_residual == item_size {
                score -= 20.0;
            }
        }
    }

    // Tightness bonus: filling a bin almost exactly is excellent.
    let fill = (item_size as f64) / cap;
    if fill > 0.9 { score -= 35.0; }
    else if fill > 0.7 { score -= 15.0; }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate (empty bin): usually bad unless no good open fit exists.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 }
            else {
                // penalty grows with how many bins fit and how good mean fit is
                let mean_fit = mean_residual / cap;
                40.0 + fitting_bins_count as f64 * 5.0 + mean_fit * 20.0
            };
        // late in stream, prefer consolidating into open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = cap - 20.0 + desperation + progress * 15.0;
        // a new bin is attractive only for very large items that would leave
        // awkward residuals elsewhere
        if item_size >= 80 { score -= 30.0; }
    } else {
        // mild preference for bins whose residual is close to item size
        let tightness = (bin_residual as f64 - item_size as f64).abs();
        score += tightness * 0.1;
        // spread awareness: if this bin is far below mean residual, it's a
        // leftover bin; using it balances the pool
        if (bin_residual as f64) < mean_residual - 10.0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for likely future items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual tightly matches the item (low slack).
    let slack = (bin_residual - item_size) as f64;
    score -= (1.0 - slack / bin_capacity as f64) * 10.0;

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - gap / bin_capacity as f64);
    }
    // If next item cannot fit post_residual, this bin creates dead space for the lookahead.
    if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 8.0;
    }

    // Open-bin pressure: prefer spreading into existing bins when many are open.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mean residual coupling: prefer bins with residual below mean (denser bins).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when no good fit exists (few fitting bins, large item).
    if bin_residual == bin_capacity {
        score = 60.0
            + (item_size as f64 / bin_capacity as f64) * 20.0
            - (fitting_bins_count as f64) * 5.0
            - open_bins_count as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post_residual (tight packing)
    let mut score = post_residual as f64;

    // Strong reward for exact / near-exact fits
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // 2-step lookahead: reward when next item fits into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - 0.25 * slack;
        // Extra reward if next item then leaves near-zero residual (chained perfect fit)
        if post_residual - next_item_size <= 5 {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // Dead space: next item cannot use the leftover; penalize proportionally
        let waste = post_residual as f64;
        score += 0.35 * waste;
        // Harsher if leftover is small-but-unusable (classic bad fragmentation)
        if post_residual < 10 {
            score += 10.0;
        }
    }

    // Prefer bins whose residual is below mean (fill emptier-tight bins first)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        let bad_fit_penalty = if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
            0.0 // opening new bin acceptable
        } else {
            45.0
        };
        score += 50.0 + bad_fit_penalty - 10.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize when post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize post_residual that is too small to hold any plausible future item
    // (dead space). Items can be as small as 1, so weight by how close post_residual
    // is to the smallest useful sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // nearly unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score += 8.0; // limited usability
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect pairing
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item won't fit here; mildly penalize leaving a large gap it could have used
            let gap = (post_residual as f64) / (next_item_size as f64);
            score += 5.0 * gap.min(2.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly discourage opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Fragmentation pressure: if mean residual across open bins is high, we have room
    // everywhere; prefer filling this bin anyway (keep score low for good fits), but
    // penalize opening yet another bin.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of opening a bin.
        let mut new_bin_score = bin_capacity as f64;
        new_bin_score -= 40.0 * tightness; // tightness is 0 here, so no reward
        // Time horizon: early in the stream, opening bins is cheaper (more future to use them);
        // late in the stream, prefer consolidating into existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score += 30.0 * progress;
        // If many open bins with high mean residual, opening a new bin is wasteful.
        new_bin_score += (open_bins_count as f64).sqrt() * 3.0 + mean_residual * 0.3;
        // If no existing bin fits (fitting_bins_count == 0 means only new-bin call), allow it.
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0;
        } else if fitting_bins_count == 1 {
            // Only one existing bin fits: only open new bin if that fit would be terrible.
            let existing_waste = (bin_residual - item_size) as f64;
            if existing_waste > 50.0 {
                new_bin_score -= 10.0;
            }
        }
        return new_bin_score;
    }

    // Mild bonus for keeping number of open bins from exploding: filling existing bins is good.
    score += (open_bins_count as f64) * 0.5;

    // Small time-dependent nudge: later in stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // base: prefer small post residual, non-linearly
    let mut score = 4.0 * x * x + 1.0 * x;

    // smooth progress coupling: late in stream, penalize residual waste more
    score += 3.0 * progress * x * x;

    // reward tight fits relative to mean residual state
    let tight = 1.0 - (pr as f64 / (bin_residual as f64 + 1.0));
    score -= 2.5 * tight * (1.0 - progress);

    // mean residual interaction: if open bins are loose, prefer filling this one
    score += 0.5 * (mean_residual / cap) * x;

    // last-chance bin bonus (only one fitting bin)
    if fitting_bins_count == 1 {
        score -= 2.0;
    }

    // lookahead: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 {
        let d = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 3.0 * (1.0 - d / cap).max(0.0);
    } else {
        // last item: strongly prefer minimal residual
        score += 2.0 * x;
    }

    // new-bin candidate: penalize unless open bins are mostly full
    if bin_residual == bin_capacity {
        let fullness = 1.0 - (mean_residual / cap);
        score += 1.5 + 4.0 * (1.0 - fullness);
        score -= 2.0 * progress;
    }

    // slight penalty for many open bins to encourage consolidation
    score += 0.02 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into
    // residue classes modulo the smallest item size (1..=100 interface).
    let dead = post_residual as i64;

    // Perfect fit class: nothing left or unusable sliver.
    if dead <= 1 {
        score -= 60.0; // excellent placement
    } else if dead <= 5 {
        score -= 25.0; // near-perfect, effectively dead space
    } else if dead <= 10 {
        score -= 8.0; // small but potentially usable
    }

    // Harmonic banding of post_residual by capacity fractions.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;
    if frac > 0.5 {
        score += 30.0; // wasted more than half: poor packing
    } else if frac > 0.25 {
        score += 10.0;
    } else if frac > 0.1 {
        score += 2.0;
    }

    // Lookahead coupling: does next item fit in the post residual?
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            // reward proportionally to how well next item fills leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * fill;
        } else {
            // leftover cannot host next item: penalize dead space growth
            score += 0.15 * dead as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is
    // huge relative to capacity (poor fit everywhere) or few bins open.
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64;
        score += 35.0; // default reluctance to open new bins
        if item_size as f64 > 0.8 * cap {
            score -= 50.0; // big items: better in a fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
        // Late in the stream, consolidation matters more.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.7 {
            score += 15.0;
        }
    }

    // Mild preference for bins below mean residual (balance residuals).
    let r = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 0.05 * (r - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: punish residual gaps that are too small
    // to be useful for typical future items (unusable dead space).
    let dead_threshold = 12.0; // gaps below this are nearly unusable
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 30.0;
    }

    // Reward tight fits (small positive residual) more aggressively than linear.
    if post_residual > 0 {
        score -= 20.0 * (1.0 - (post_residual as f64) / bin_capacity as f64);
    }

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bin pressure: discourage spreading across many open bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; penalize it
    // mildly so it only wins when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if the current item nearly fills a fresh bin, opening is fine.
        if item_size >= (bin_capacity as f64 * 0.8) as u32 {
            score -= 40.0;
        }
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        score -= 15.0;
    }
    // If next item would leave another dead gap, penalize.
    if next_item_size > 0 && post_residual >= next_item_size {
        let nr = post_residual - next_item_size;
        if nr > 0 && (nr as f64) < dead_threshold {
            score += (dead_threshold - nr as f64) * 12.0;
        }
    }

    // Deviation from mean residual: prefer bins whose residual is close to
    // the item need (balanced consolidation).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 10.0;

    // Early-stream: allow slightly more liberal bin opening to build good structure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 {
        score -= 5.0 * (1.0 - progress * 5.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item fill
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item can't follow here; penalize proportional overshoot
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
        // Bonus if next item fits together with current one leaving small residue
        if next_item_size <= post_residual {
            let combined = (item_size + next_item_size) as f64 / bin_capacity as f64;
            score -= 15.0 * combined;
        }
    } else {
        // Last item: strongly prefer fullest possible packing.
        score -= 40.0 * tightness;
    }

    // Penalize bins far from mean residual (avoid fragmenting many bins evenly).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless current bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 50.0);
        score += 25.0;
        // Open new bin if existing bins are very full (small mean residual).
        score -= 0.4 * (bin_capacity as f64 - mean_residual);
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        let _ = crowding;
    }

    // Slight late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual small relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize leaving dead space that nothing can use later (items >= 10, or 1..100 now).
    let min_item = 1.0;
    if (post_residual as f64) < min_item {
        score -= 10.0; // perfect fill
    } else {
        // Waste penalty: residual too small to be useful for typical items
        let usable = post_residual >= 10;
        if !usable {
            score += 8.0;
        }
    }

    // Lookahead: bonus if next item fits in post_residual (chaining placements).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0 + 0.05 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // penalize blocking the next item
        score += 1.5;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no open
    // bin fits well. Penalize new bins more as open bins accumulate and when
    // mean residual across open bins is still large.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowding = (open_bins_count as f64).ln1p();
        score += 4.0 + 2.0 * crowding + 3.0 * progress + 0.03 * mean_residual;
        // But if mean residual is tiny (open bins nearly full), new bin is fine
        score -= 0.05 * (bin_capacity as f64 - mean_residual).max(0.0);
    }

    // Prefer bins whose residual is below the mean (consolidate emptier space usage),
    // leaving larger residuals in fewer bins for big future items.
    score += 0.04 * (mean_residual - bin_residual as f64).max(0.0);

    // Mild time-horizon adaptation: early on, be conservative (keep space flexible);
    // later, accept tighter packing more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 2.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tight = item_size as f64 / cap;

    // Base: reward tight fits via non-linear decay of post_residual.
    let mut score = pr * (1.0 + 0.6 * (pr / cap).powi(2));

    // Smooth penalty for leaving residual just below typical item sizes:
    // dead space term as a smooth bump around mid residuals.
    let dead = (pr / cap - 0.5 * tight).abs();
    score += 12.0 * dead * dead * (1.0 - progress);

    // Lookahead coupling: reward if next item fits the post residual smoothly.
    if next_item_size > 0 {
        let gap = next_item_size as f64 - pr;
        if gap <= 0.0 {
            score -= 8.0 * (1.0 - (gap / cap).powi(2));
        } else {
            score += 6.0 * (gap / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening new bins smoothly, less so late in stream
    // or when the fit would be very loose.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        let waste = 1.0 - tight;
        score += 10.0 + 25.0 * waste * waste - 10.0 * progress;
    }

    // Mild preference for bins with below-average residual (consolidate emptier space).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Slight scaling with open bin count: discourage spreading across many bins.
    score *= 1.0 + 0.02 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus as post_residual approaches 0.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Harmonic class of post_residual: residues near multiples of common
    // item sizes (10..80) are more "usable" for future arrivals.
    let pr = post_residual;
    let mut usability = 0.0;
    for k in 10..=80 {
        if k <= pr {
            let r = pr % k;
            // residue 0 means a future item of size k fits exactly
            if r == 0 { usability += 1.5; }
            else if r >= 10 { usability += 0.5; }
        }
    }
    score -= usability.min(6.0);

    // Penalize dead space in the awkward 1..10 band (unusable by any item).
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: default it to a mild penalty so it only wins when
    // all open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If lookahead item is large and this bin would be left with tiny
        // residual, opening fresh may be better: reduce the penalty.
        if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
            score -= 45.0;
        }
    }

    // Lookahead coupling: reward leaving room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 4.0 * (1.0 - (slack as f64) / (bin_capacity as f64));
    } else if next_item_size > 0 {
        score += 5.0; // next item cannot follow here
    }

    // Late in the stream: consolidate aggressively into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 1 {
        score += progress * 3.0 * ((post_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // Prefer bins with below-average residual (they are "nearly full" —
    // filling them reduces bin count pressure).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Integer-division threshold: bins whose residual can host at least one
    // more mid-size item (>= 20) are valuable; penalize wasting them.
    if pr / 20 == 0 && pr >= 10 {
        score += 8.0; // residual in [10,19]: only tiny items fit later
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible future item
    // (sizes >= 1, but realistically >= 10) can use are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    } else if post_residual == 0 {
        // Perfect fill is the best outcome.
        score -= 40.0;
    }

    // Reward tight fits relative to the bin: small post_residual fraction.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * 30.0;

    // Pressure from number of open bins: discourage spreading across many bins
    // unless the fit is genuinely good. Linear + mild superlinear term.
    score += open_bins_count as f64 * 2.0;
    score += (open_bins_count as f64).powi(2) * 0.15;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // this placement is excellent; if next item fits but would leave a tiny
    // dead gap, slightly penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let pr2 = post_residual - next_item_size;
            if pr2 < 10 {
                score += 8.0;
            } else {
                score -= 10.0;
            }
        } else {
            // Next item cannot use this bin's leftover; mild penalty if leftover is small.
            if post_residual < next_item_size && post_residual < 20 {
                score += 6.0;
            }
        }
    }

    // Mean-residual coupling: placing into a bin whose residual is far below
    // the mean (i.e., already tight) is good; avoid dumping items into bins
    // with lots of slack when a better packing exists.
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        if bin_res_f < mean_residual {
            score -= 6.0;
        } else {
            score += 4.0;
        }
    }

    // New-bin candidate logic: an empty bin has no dead-space history; only
    // prefer it when all open bins would produce terrible fits (large dead gaps)
    // or when open-bin pressure is extreme.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 22.0;
        // But if every existing fit would leave a large unusable gap, opening
        // a fresh bin is better.
        let worst_gap = (bin_capacity.saturating_sub(item_size)) as f64;
        if fitting_bins_count == 0 {
            score -= 50.0;
        } else if worst_gap > 0.0 {
            // Compare: opening new bin leaves (C - item) fresh; using an open
            // bin leaves post_residual. If open bins would be badly fragmented,
            // new bin wins.
            let open_pressure = open_bins_count as f64 * 1.5;
            if open_pressure > 30.0 {
                score -= 15.0;
            }
        }
        // Early in the stream, opening bins is cheaper (long horizon to fill them).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
    }

    // Slight preference to fill bins that are closer to full overall.
    score += (bin_capacity.saturating_sub(bin_residual)) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_quality = (post_residual - next_item_size) as f64;
        score -= 120.0 - 2.0 * match_quality.min(60.0);
        // Exact chain fit (post_residual == next_item_size) is ideal
        if post_residual == next_item_size {
            score -= 150.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize dead space the next item cannot use
        score += 15.0;
    }

    // Prefer filling bins below mean residual (tighter bins)
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: make it moderately unattractive unless residuals are all bad
    if bin_residual == bin_capacity {
        score += 60.0 + 0.5 * open_bins_count as f64;
        // If next item is large, a fresh bin is more attractive
        if next_item_size > 50 {
            score -= 40.0;
        }
    }

    // Late in stream: consolidate, penalize spreading
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 10.0 * (open_bins_count as f64).ln().max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 30.0;

    // Exact or near-exact fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let lookahead_fit = (post_residual - next_item_size) as f64;
        score -= 20.0 - lookahead_fit * 0.3;
    } else if next_item_size > post_residual {
        // Next item won't fit here; penalize leaving a large unusable gap for it.
        score += (post_residual as f64).min(next_item_size as f64) * 0.15;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening new bins when many bins are already open and fragmented.
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty grows with open bin count.
        score += 40.0 + (open_bins_count as f64) * 2.5;

        // But if mean residual across open bins is small (all bins nearly full),
        // opening a new bin is reasonable — reduce the penalty.
        score -= (mean_residual * 0.4).min(30.0);

        // If the item is large relative to typical residuals, a fresh bin is fine.
        if item_size as f64 > mean_residual {
            score -= 10.0;
        }
    }

    // Time horizon: early in the stream, be more conservative about fragmentation;
    // late in the stream, packing into existing bins matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    // Slight preference for bins whose residual is close to mean residual
    // (keeps bin states homogeneous, easier to combine with future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) + norm_pr * progress * progress;
    score += 30.0 * poly;

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual of open bins
    let dead = (pr as f64 - mean_residual) / cap;
    score += 15.0 * dead * dead.abs();

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward residual that can fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 10.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for spreading across many open bins late in the stream
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    }

    // Harmonic class logic: residual buckets mod 10 and mod 20.
    // Small residues in "awkward" classes (11..19, 31..39) are dead space
    // since items are >= 1 but typical items are large; penalize.
    let pr = post_residual;
    let class10 = pr % 10;
    if pr > 0 && pr <= 19 {
        // dead space: nothing in [1, pr] may come, but small pr wastes capacity
        score += (20 - pr) as f64 * 8.0;
    }
    if class10 == 0 && pr > 0 {
        score -= 30.0; // clean decade residual, reusable by round sizes
    }
    if pr >= 20 && pr <= 29 {
        score -= 40.0; // fits a 20-class item later
    }

    // Coupling with lookahead item: reward if next item fits exactly or well.
    if next_item_size > 0 && next_item_size <= pr {
        let next_waste = pr - next_item_size;
        if next_waste == 0 {
            score -= 500.0;
        } else if next_waste <= 10 {
            score -= 120.0;
        } else {
            score -= 30.0;
        }
    } else if next_item_size > pr {
        // next item cannot go here; if this bin's residual becomes dead, penalize
        if pr > 0 && pr < 10 {
            score += 60.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        // Opening a new bin costs ~ one bin; make it unattractive unless
        // the item leaves a clean residual and few bins are open.
        score += 350.0;
        if pr % 10 == 0 {
            score -= 60.0;
        }
        if next_item_size > 0 && next_item_size <= pr {
            score -= 50.0;
        }
        // With many open bins, prefer packing into existing ones.
        score += openness * 5.0;
        // Late in the stream, opening new bins is less costly (fewer future items).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 100.0;
    }

    // Mild preference for bins below mean residual (keep a spread of sizes).
    score += 0.3 * (mean_residual - bin_residual as f64).abs().signum() * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (gaps that few future items can use).
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 60.0 * (10.0 - dead) / 10.0;
    } else if dead >= 10.0 && dead < 20.0 {
        score += 15.0 * (20.0 - dead) / 10.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    score -= (item_size as f64) * (1.0 - dead / bin_capacity as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate: penalize unless current fit is bad or bin is fresh.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 3.0;
        if dead == 0.0 { score -= 10.0; }
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= dead {
        score -= 12.0;
    } else if next_item_size > 0 && dead > 0.0 && (next_item_size as f64) > dead {
        score += 5.0 * (dead / (next_item_size as f64));
    }

    // Discourage placements far below mean residual utilization.
    score += (mean_residual - dead).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect wrap: leftover exactly matches the next item.
    if next_item_size > 0 {
        if post_residual as u64 == next_item_size as u64 {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Slack allows chaining, mildly rewarded proportional to closeness.
            let gap = (post_residual - next_item_size) as f64;
            score -= (30.0 * (1.0 - gap / bin_capacity as f64)).max(0.0);
        } else {
            // Dead space below the next item's size: penalize harder when
            // the next item nearly fits (wasted opportunity).
            let miss = (next_item_size - post_residual) as f64;
            score += (miss * 0.6).min(40.0);
        }
    }

    // Tight fits are good in general.
    if post_residual == 0 {
        score -= 45.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Compare against the fleet average residual: placing into a bin whose
    // post-residual is far below average concentrates waste efficiently.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item fits poorly everywhere else (large post_residual in an existing
    // bin already penalized). Give the fresh bin a mild penalty so it wins
    // only when existing placements are bad, plus a bonus when it enables a
    // perfect next-item fit later.
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins to build
    // a diverse residual portfolio.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: post_residual is the dominant term already.

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Reward partial compatibility, scaled by how much room remains after both.
            let after_next = post_residual - next_item_size;
            score -= 25.0 * (1.0 - after_next as f64 / bin_capacity as f64);
        } else {
            // Next item cannot follow here; penalize leaving medium dead space.
            if post_residual < next_item_size && post_residual > 0 {
                score += 10.0 * (post_residual as f64 / next_item_size.max(1) as f64);
            }
        }
    }

    // Last chance: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so that any
    // reasonably tight existing fit wins, but a poor fit in an old bin loses.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
    }

    // Prefer bins whose residual is below the mean (they are "tighter" than average).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Late in the stream, consolidate harder: penalize spreading across many bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 0.2 * open_bins_count as f64;

    // Slight preference for bins with larger pre-fit residual when residuals tie
    // (keeps small-residual bins available for small items).
    score += 0.05 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Late in the stream, compact fills matter more; dead space is penalized super-linearly.
    let dead_penalty = norm_pr * norm_pr * (1.0 + progress * 2.0);
    score += dead_penalty * cap * 0.5;

    // Reward tight fits more strongly as the stream progresses (smooth interaction).
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * progress * item_size as f64 * 0.3;

    // Last-chance bin: strongly favor using it (smooth exponential-ish via polynomial).
    if fitting_bins_count == 1 {
        score -= 40.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits the post-residual, reward this placement smoothly.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_quality = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 10.0 + 15.0 * fit_quality * (1.0 - progress);
    }

    // Penalize bins that deviate from mean residual (prefer balanced residual usage),
    // scaled non-linearly by number of open bins.
    let dev = (pr - mean_residual).abs() / cap;
    score += dev * dev * (open_bins_count as f64).min(10.0) * 5.0;

    // New-bin candidate: penalize opening a new bin unless residuals of open bins are low.
    if bin_residual == bin_capacity {
        let mean_norm = mean_residual / cap;
        score += 25.0 * (1.0 - mean_norm) * (1.0 - mean_norm) + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction classes.
    // Residuals that form "harmonic" complements of common item sizes are reusable.
    let cap = bin_capacity as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let sixteenth = bin_capacity / 16;

    // Reward residuals that are harmonic (multiples of small fractions of capacity):
    // these are likely to be exactly filled by future items.
    if post_residual > 0 && post_residual % sixteenth == 0 {
        score -= 6.0;
    }
    if post_residual % eighth == 0 {
        score -= 4.0;
    }
    if post_residual % quarter == 0 {
        score -= 4.0;
    }

    // Perfect fit: zero waste is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: small unusable residuals (< smallest plausible item / 4)
    // are nearly dead weight; penalize superlinearly.
    let small_threshold = bin_capacity / 20;
    if post_residual > 0 && post_residual < small_threshold {
        score += 25.0 + (small_threshold - post_residual) as f64;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how well it fills.
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 18.0 * fill_ratio;
            // Harmonic match: next item leaves a harmonic residual again.
            let nr = post_residual - next_item_size;
            if nr % sixteenth == 0 {
                score -= 5.0;
            }
        } else {
            // Next item cannot use this residual; mild penalty scaled by waste.
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): make it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = cap * 0.85;
        // Early in the stream, opening fresh bins is cheap (many items to come).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // If many open bins already, discourage proliferation.
        score += 2.0 * open_bins_count as f64;
        // If the item is large relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.6 * cap {
            score -= 20.0;
        }
        // If next item is large, a fresh bin preserves flexibility.
        if next_item_size as f64 > 0.6 * cap {
            score -= 12.0;
        }
    } else {
        // Prefer fuller bins: tighten toward best-fit by comparing residual to mean.
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0 * (bin_residual as f64 - mean_residual) / cap;
        }
        // Reward high occupancy fraction of the bin after placement.
        let occupancy = (bin_capacity - post_residual) as f64 / cap;
        score -= 10.0 * occupancy;
    }

    // Mild tie-breaker: prefer bins with tighter residual (smaller waste potential).
    score += post_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty for small unusable gaps (below typical min item size band)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Reward leaving a gap that can fit the next item exactly-ish
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / 40.0).max(0.0);
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot use this gap: penalize proportionally
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor new bin for poor fits
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 15.0 * pressure * (1.0 - fill_ratio);

    // New-bin candidate: mild bonus so it wins only when fits are bad
    if bin_residual == bin_capacity {
        score -= 10.0;
        // but penalize new bin when a good fit exists elsewhere
        if fill_ratio == 1.0 {
            score += 0.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good (already base of score).
    // Penalize dead space that is too small to ever be useful (<10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // Perfect chaining: next item exactly fills the remainder.
            let gap = (post_residual as f64) - nxt;
            score -= 30.0 * (1.0 - gap / capacity);
            if gap == 0.0 {
                score -= 20.0; // perfect 2-item fill
            }
        } else {
            // Next item cannot follow here: leftover is likely dead space.
            score += 0.5 * ((post_residual as f64) - nxt).abs();
        }
    }

    // Compare post_residual relative to mean residual of open bins:
    // leaving less than average waste is favorable.
    score -= 0.6 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Avoid scattering across many open bins when plenty are open already.
    score += 2.0 * open_bins_count as f64 / (1.0 + step_index as f64);

    // Mild preference for filling bins as stream progresses.
    score *= 1.0 - 0.1 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose post-residual is small.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that no plausible item could fill.
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // small unusable sliver is fine (already nearly full)
    } else if post_residual >= 10 && post_residual <= 40 {
        // mid-range residual is useful; mild reward scaled by mean residual gap
        score -= 8.0 * (1.0 - (post_residual as f64 - 10.0) / 30.0);
    } else if post_residual > 60 {
        score += 12.0 * ((post_residual as f64 - 60.0) / 40.0); // large waste penalty
    }

    // Lookahead: reward if next item fits the post-residual exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; penalize more if we're leaving big residual
        score += 6.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, use it to avoid new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer filling bins when many bins are open (consolidation pressure).
    score -= 2.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in stream, be more selective about creating tiny residuals;
    // late in stream, prioritize closing bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // Deviation from mean residual: prefer bins below mean residual (fuller bins).
    score += 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: only attractive when nothing decent fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted when many bins open or
        // current fit would be terrible, and when lookahead suggests a big item next.
        let poor_fit = if post_residual > 55 { 1.0 } else { 0.0 };
        let lookahead_big = if next_item_size > 60 { 1.0 } else { 0.0 };
        score = 70.0
            - 18.0 * poor_fit
            - 10.0 * lookahead_big
            - 4.0 * (open_bins_count as f64).ln().max(0.0)
            + 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Penalize large dead space quadratically, stronger late in stream
    score += 8.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) with a smooth saturating term
    score -= 12.0 * (-norm_pr * 6.0).exp();

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post-residual can still fit the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 6.0 * (1.0 - (pr - ni) / cap);
        } else {
            score += 4.0 * (ni - pr) / cap;
        }
    }

    // New-bin candidate: mildly penalize early, mildly reward late
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - 2.0 * progress) * (1.0 - 2.0 * progress) - 3.0 * progress;
    }

    // Mean residual coupling: prefer bins near the mean (balance residuals)
    score += 2.0 * (pr - mean_residual).abs() / cap;

    // Crowding penalty: many open bins -> prefer filling existing ones
    score += (open_bins_count as f64).ln() * 1.5 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity wasted if bin is abandoned here

    // Integer-division harmonic class: post_residual bucketed by capacity/8.
    let class = post_residual / (bin_capacity / 8).max(1); // 0..8
    // Penalize "dead" middle classes (residual too small for typical items but too large to ignore)
    let dead_penalty = match class {
        0 => -40.0,                    // perfect/tight fit: excellent
        1 => 6.0,                      // 12.5% leftover: slightly bad
        2 => 14.0,                     // 25% leftover: dead space risk
        3 => 10.0,
        4 => 4.0,                      // 50% leftover: still useful
        5 => 2.0,
        6 => -2.0,
        _ => -4.0,                     // large residual: bin still flexible
    };
    score += dead_penalty;

    // Modulo arithmetic on post_residual: reward residuals that are "friendly"
    // to common item sizes (multiples of 10 / divisors of 100).
    if post_residual % 10 == 0 {
        score -= 5.0;
    }
    if post_residual % 25 == 0 {
        score -= 3.0;
    }
    // Residual exactly matching next item => lookahead harmony.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Residual can host the next item too: strong chain reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.05 * (next_item_size as f64);
    }
    // Residual cannot host next item: penalize proportional to lookahead size.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 6.0 + 0.1 * (next_item_size - post_residual) as f64;
    }

    // Tightness coupling: how fully the item fills the bin.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill * fill; // quadratic reward for tight fits

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // With multiple options, prefer bins with smaller residual (best fit).
        score += 0.02 * (fitting_bins_count as f64);
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a decent fit (i.e., all residuals are poor).
    if bin_residual == bin_capacity {
        // Baseline score for fresh bin = its full residual, adjusted:
        // discourage opening new bins early / when open bins exist with room.
        score += 15.0 + 2.0 * (open_bins_count as f64).min(20.0);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin accommodates future large items well
        }
    } else {
        // Slight preference for existing bins over opening new ones.
        score -= 5.0;
    }

    // Mean-residual coupling: if this bin's residual is far below mean,
    // it is a laggard bin; placing here consolidates waste.
    let diff = mean_residual - pr;
    if diff > 0.0 {
        score -= 0.15 * diff; // favor below-mean-residual bins
    } else {
        score += 0.10 * (-diff); // penalize above-mean-residual bins slightly
    }

    // Stream progression: later in stream, waste matters more; be tighter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for typical future items
    // are effectively lost capacity. Penalize the "unusable zone" harshly.
    let dead_threshold = 10.0f64.min(mean_residual * 0.35);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 2.5;
    }

    // Tight fit reward: bonus proportional to fill ratio achieved.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 18.0;

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 2 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits into the post residual, this is valuable.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + (next_item_size as f64 / bin_capacity as f64) * 12.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Post residual can't host next item: mild penalty scaled by gap size.
        score += (next_item_size - post_residual) as f64 * 0.05;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is great.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.4 + 0.6 * progress) * 0.5;

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no open bin offers a decent fit. Make the empty bin moderately costly
    // so tight fits in existing bins win, but poor fits lose.
    if bin_residual == bin_capacity {
        // Baseline cost of a new bin; compare against post_residual of existing bins.
        score = (bin_capacity - item_size) as f64 * 0.9
            + open_bins_count as f64 * 0.3
            - fill * 5.0;
        // If the item is large, filling a new bin is fine; if small, discourage.
        if item_size < 40 {
            score += 8.0;
        }
        // Late in stream, prefer consolidating into open bins.
        score += progress * 6.0;
    }

    // Mean-residual coupling: if this bin's post residual is far below the mean,
    // we're compacting well; reward it slightly.
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less post residual is better (already primary term).
    // Penalize dead space that is too small for typical items (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // unusable sliver
    }

    // Aggressive 2-step lookahead: if the next item exactly fills post_residual,
    // strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item can still fit here: mild reward proportional to remaining slack.
            score -= 8.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // Next item cannot fit in residual: penalize proportionally to the gap.
            let gap = (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
            score += 20.0 * gap;
        }
    }

    // Relative to mean residual: placing in a bin with below-mean residual
    // (tighter bin) is preferable to fragmenting a roomy bin.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin
    // offers a good fit (post_residual large or item barely fits nowhere well).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: high unless other bonuses make it win.
        score += 15.0;
        // If the current item is large relative to capacity, a fresh bin is fine.
        if (item_size as f64) > 0.6 * bin_capacity as f64 {
            score -= 30.0;
        }
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // Many open bins with high mean residual: opening new bin is wasteful.
        if mean_residual > (item_size as f64) * 1.5 && open_bins_count > 2 {
            score += 25.0;
        }
    }

    // Slight preference to fill nearly-full bins to close them out.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared dead-space penalty amplified for large waste.
    let waste = post_residual as f64;
    score += 0.35 * (waste / bin_capacity as f64).powi(3) * bin_capacity as f64;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        score += 5.0; // next item cannot follow here; mild penalty
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 0.2 * bin_residual as f64;
    }

    // Penalize spreading across many open bins when mean residual is high.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (mean_residual - waste).abs() * 0.01;

    // Time horizon: early in the stream, be more conservative about filling bins
    // that leave awkward residuals; later, accept tighter packing greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.10 * waste;

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a decent fit (i.e., its raw residual advantage must overcome
    // the natural preference for existing bins).
    if bin_residual == bin_capacity {
        score += 25.0 + 0.5 * item_size as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin can host a chain of future items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with mild non-linear emphasis.
    let mut score = post + 0.35 * (post * post) / cap;

    // Smooth non-linear coupling of tightness with stream progress:
    // late in the stream, squeeze harder into existing bins.
    let tightness = 1.0 - post / cap; // 1.0 = perfect fit
    score -= tightness * tightness * (12.0 + 30.0 * progress * progress);

    // Lookahead: reward residuals that still fit the next item (usable space),
    // penalize dead space that cannot host the upcoming item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 6.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 + progress);
    }

    // Penalize new-bin candidate (empty bin) unless current fit is poor
    // or the item is large relative to the mean residual landscape.
    if bin_residual == bin_capacity {
        let waste = (post - mean_residual).abs();
        score += 18.0 - 10.0 * (1.0 - item_size as f64 / cap)
                 - 0.5 * open_bins_count as f64 * (1.0 - tightness)
                 + 4.0 * waste / cap;
    }

    // Mild dispersion pressure: keep residuals balanced across open bins.
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which "modular bucket" of leftover space
    // does this placement land in? Residuals in (0,10] are dead space; large
    // residuals are valuable. Penalize dead-space classes superlinearly.
    let pr = post_residual;
    if pr > 0 {
        let class = (pr / 10).min(9); // 0..9 harmonic buckets of width 10
        score += match class {
            0 => 60.0,                       // 1..10 : near-dead space
            1 => 25.0,                       // 11..20
            2 => 10.0,                       // 21..30
            3 => 3.0,
            4 => 0.0,
            5 => -4.0,
            6 => -7.0,
            7 => -9.0,
            8 => -10.0,
            _ => -12.0,                      // 91..99 : huge residual left
        };
    } else {
        score -= 40.0; // perfect fill
    }

    // Exact-fit coupling: post_residual divisible by common item sizes (10/20/25/50)
    // means the leftover is reusable by a future item -> reward.
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0) {
        score -= 12.0;
    }

    // Lookahead: does the next item fit exactly into the post-residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0; // guaranteed perfect pair
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            // harmonic class of the slack after the lookahead placement
            let slack_class = (slack / 10).min(9);
            score -= 20.0 - 2.0 * slack_class as f64;
            if slack % 10 == 0 { score -= 6.0; }
        } else {
            // next item cannot use this bin's leftover: leftover likely stranded
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin's post_residual == capacity - item.
    // Prefer reusing open bins when their residual is reasonable; open a new bin
    // only when every open bin would be left with dead space (small post_residual).
    if bin_residual == bin_capacity {
        // neutral-ish baseline for a fresh bin, slightly worse than a good reuse
        score += 8.0;
        if open_bins_count == 0 { score -= 20.0; }
        // late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild pressure toward bins with residuals near the mean (balanced packing)
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // Tie-break: prefer fuller bins (smaller residual) slightly
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize dead space: residual too small to ever be useful.
    // Assume minimum plausible item size ~1; treat residuals < 10 as near-waste.
    if post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Penalize residuals that cannot fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.6 * (next_item_size as f64 - post_residual as f64);
    }

    // Reward tight fits: exact or near-exact placements.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.85 {
        score -= 12.0 * (fit_ratio - 0.85) / 0.15;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins when
    // this bin is one of many fitting options; encourage using last-chance bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Slight penalty for opening a new bin when open bins exist and mean
    // residual across open bins is large enough to absorb the item.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        if mean_residual >= item_size as f64 {
            score += 8.0 + 0.1 * open_bins_count as f64;
        } else {
            score -= 3.0;
        }
    }

    // Late in the stream, be more conservative with dead space.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward residuals that exactly match the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // Leftover after next item would be post_residual - next_item_size.
            let tail = (post_residual - next_item_size) as f64;
            score += tail * 0.5;
        } else {
            // Next item can't use this residual; penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Compare against mean residual across open bins.
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: prefer it only when no good fit exists.
    if bin_residual == bin_capacity {
        let base = 60.0 + post_residual as f64;
        // As stream progresses, slightly discourage opening new bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = base + progress * 20.0;
    }

    // Small penalty for large open_bins_count to encourage consolidation.
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual (perfect fits).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 60.0;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Penalize residual space that is too small to be useful for future items
    // (items in [1,100]; a residual below ~10 is dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; slight penalty proportional to wasted gap
            score += (next_item_size - post_residual).min(30) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a bin is penalized, but becomes
    // attractive when the item fits poorly in every open bin.
    if bin_residual == bin_capacity {
        let mut open_penalty = 250.0;
        // As the stream progresses, be slightly more willing to open bins
        // (future load unknown; keep capacity flexibility).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        open_penalty *= 1.0 - 0.25 * progress;
        // More open bins => mild extra penalty to avoid bin explosion.
        open_penalty += open_bins_count as f64 * 4.0;
        // If current bin's fit is bad (large post_residual), opening new bin is
        // relatively better: reduce penalty by fit quality of this candidate.
        let fit_quality = 1.0 - (item_size as f64 / bin_capacity as f64);
        open_penalty -= fit_quality * 100.0;
        // If many bins fit the item, opening a new one is rarely worth it.
        if fitting_bins_count > 2 {
            open_penalty += 100.0;
        }
        score += open_penalty.max(0.0);
    }

    // Global state coupling: prefer bins whose residual is below the mean
    // (fill fuller bins first, keep emptier bins flexible).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.8;
    }

    // Small tie-breaker noise-free deterministic jitter based on state.
    score += (bin_residual as f64 * 0.001) - (open_bins_count as f64 * 0.0005);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste penalty: dead space grows quadratically in normalized residual.
    let norm_post = post / cap;
    score += 12.0 * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits: small post_residual relative to item size.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 20.0 * tightness * tightness;

    // Lookahead: if next item fits in post_residual, reward; else penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 10.0 * (1.0 - nxt / cap) * (1.0 - progress);
        } else {
            score += 6.0 * (nxt - post) / cap;
        }
    }

    // Last chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    // relative to mean residual of open bins (poor fits exist).
    if bin_residual == bin_capacity {
        let spread = mean_residual - item_size as f64;
        let penalty = 30.0 + 20.0 * progress + 10.0 * (spread / cap).max(0.0);
        score += penalty;
        if next_item_size > 0 && next_item_size as f64 > post {
            // opening a fresh bin is more attractive for big items
            score -= 15.0 * (item_size as f64 / cap);
        }
    } else {
        // Favor bins with residuals close to mean (balanced packing) via smooth coupling.
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 4.0 * dev * dev;
        // Slight preference for fewer open bins when many are open.
        score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals that are "usable"
    // by common item sizes (multiples of 10 and small remainders).
    let pr = post_residual;
    if pr > 0 {
        let mod10 = pr % 10;
        // Residuals congruent to 0 mod 10 are most reusable.
        score -= if mod10 == 0 { 12.0 } else { (10 - mod10) as f64 * 0.8 };
        // Dead-space penalty for tiny unusable slivers.
        if pr < 10 {
            score += 25.0;
        }
        // Integer-division threshold: residuals >= half capacity are valuable.
        if pr >= bin_capacity / 2 {
            score -= 8.0;
        }
    } else {
        // Perfect fit: strongly reward closing the bin exactly.
        score -= 40.0;
    }

    // Tightness reward: fraction of bin filled by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 15.0;

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward heavily; if it nearly fits, mild penalty for wasting the slot.
    if next_item_size > 0 {
        if next_item_size <= pr {
            if pr % next_item_size == 0 {
                score -= 20.0;
            } else {
                score -= 6.0;
            }
        } else {
            let gap = (next_item_size - pr) as f64;
            score += gap * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Penalize opening a new bin when open bins have plenty of room.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of a fresh bin.
        score += 30.0;
        // If existing bins are quite full, opening is more acceptable.
        let mean_fill = 1.0 - mean_residual / bin_capacity as f64;
        score -= mean_fill * 25.0;
        // Large items pair well with a fresh bin.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    } else {
        // Slight preference for fuller bins among open candidates.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += mean_residual * 0.05 * (1.0 - progress);
    }

    // Mild penalty for proliferating open bins.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (1..=10) are poison — nothing (min item size 10) may ever fill them.
    if post_residual >= 1 && post_residual < 10 {
        score += 60.0 + 4.0 * (10 - post_residual) as f64;
    }

    // Perfect / near-perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Tightness bonus: fraction of the bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Coupling: penalize post_residual scaled by how full the stream is —
    // later in the stream, wasted space is harder to recover.
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += post_residual as f64 * (0.4 + 0.6 * progress);

    // Open-bin pressure: discourage scattering across many open bins;
    // favor consolidating into fewer bins when pressure is high.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: if this is the ONLY bin that fits, heavily reward
    // using it rather than opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Dead-space interaction with mean residual: placing into a bin whose
    // residual is close to mean_residual keeps the fleet balanced.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Lookahead (k=2): if the next item fits exactly in the post_residual,
    // strongly reward this placement (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let nxt_left = post_residual - next_item_size;
            if nxt_left < 10 {
                score += 20.0; // chain would create dead space
            } else {
                score -= 10.0;
            }
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive if
    // no open bin offers a decent fit. Base cost keeps it competitive only
    // when existing fits are bad; ease slightly as pressure grows.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.5 * open_bins_count as f64 - 20.0 * progress;
        if post_residual < 20 { score -= 10.0; } // large item -> fresh bin useful
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post-residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact 2-step match is golden.
            if post_residual == next_item_size {
                score -= 500.0;
            } else {
                // Reward proportionally to how well next item fits leftover.
                let tightness = next_item_size as f64 / post_residual as f64;
                score -= 60.0 * tightness;
            }
        } else {
            // Post-residual too small for next item: penalize dead space,
            // worse when close to but below next item size.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Penalize large leftover space that is unlikely usable: compare post_residual
    // against mean residual of open bins.
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive when no open bin
    // offers a good fit. Penalize new bins mildly, more when many bins are open.
    if bin_residual == bin_capacity {
        score += 40.0 + 5.0 * open_bins_count as f64;
        // But if the item is huge, a fresh bin is natural.
        if item_size >= bin_capacity / 2 {
            score -= 30.0;
        }
    }

    // Slight preference for tighter fits overall.
    score += 0.1 * (bin_capacity - item_size - post_residual) as f64;

    // Late-stream consolidation: near the end, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: heavily discount small post-residuals (non-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item fits exactly into the post-residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here; mild penalty for stranding space
            score += 6.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize spreading across many open bins when mean residual is low.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let open_penalty = open_bins_count as f64 * (1.0 - progress) * 0.5;
    score += open_penalty;

    // Prefer bins whose residual deviates from the mean (consolidate similar fills).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate handling: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so open bins with decent fits win; relax late in stream
        // or when open bins are nearly full (mean residual small).
        let desperation = (mean_residual < item_size as f64 + next_item_size as f64) as i32 as f64;
        score += 20.0 + 15.0 * (1.0 - desperation) - 10.0 * progress;
        if post_residual == 0 { score -= 100.0; } // item exactly fills new bin
    }

    // Late-stream consolidation: favor filling bins completely as stream ends.
    if progress > 0.8 && post_residual < item_size.min(20) {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Reward tight fits: quadratic coupling of post_residual with item size ratio.
    let tightness = 1.0 - (it / cap);
    score -= (cap - pr) * (cap - pr) / cap * (0.5 + 0.5 * tightness);

    // Smooth polynomial decay of post_residual influence over stream progress.
    let decay = 1.0 - progress * progress;
    score += pr * pr / cap * decay * 0.6;

    // Lookahead: reward if next item can pair into the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= (1.0 - ((pr - nxt) / cap).abs()) * (1.0 + progress);
        } else {
            score += (nxt - pr) / cap * 8.0;
        }
    }

    // Last chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Penalize bins far from mean residual (outliers create fragmentation).
    let dev = (pr - mean_residual).abs();
    score += dev * dev / cap * (0.3 + 0.4 * progress);

    // Mild preference for consolidating into fewer bins early on.
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 2.0;

    // New-bin candidate should only win when residuals are hopelessly fragmented.
    if bin_residual == bin_capacity {
        score = pr as f64 + 12.0 * (1.0 - progress) + mean_residual * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space.
    // Residuals in [0..10] are near-perfect; larger chunks split into harmonic bands.
    let pr = post_residual;
    let harm_class: u32 = if pr == 0 {
        0
    } else if pr <= 10 {
        1
    } else if pr <= 20 {
        2
    } else if pr <= 30 {
        3
    } else if pr <= 50 {
        4
    } else {
        5
    };
    score += harm_class as f64 * 3.0;

    // Dead-space penalty: leftover that no typical small item (<=10) can use.
    if pr > 0 && pr < 10 {
        score -= 8.0; // tiny sliver: excellent packing
    }

    // Modulo coupling: reward when post_residual aligns with likely future item
    // granularity (items 1..100, common sizes cluster near multiples of 10).
    let mod10 = (pr % 10) as f64;
    score += mod10 * 0.6;

    // Integer-division threshold: can the next item fit into the post residual?
    if next_item_size > 0 && next_item_size <= pr {
        score -= 6.0;
        // Extra reward if next item leaves a further nice residual.
        let nr = pr - next_item_size;
        if nr <= 10 {
            score -= 4.0;
        }
    } else if next_item_size > 0 {
        score += 2.5; // lookahead item won't chain here
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate logic: opening a new bin wastes the residual of this one.
    if bin_residual == bin_capacity {
        // Prefer new bin only if existing fits are all poor (large post_residual
        // among alternatives is unknown; use mean_residual as proxy for fit quality).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = bin_residual as f64 - item_size as f64;
        score = waste + 20.0 * (1.0 - progress);
        // If open bins are crowded (mean residual low), new bin is attractive.
        score -= (mean_residual / bin_capacity as f64) * 5.0;
        // Late in stream, avoid opening bins unless necessary.
        score += progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open
        }
    } else {
        // Existing bin: reward tight fits relative to capacity fraction.
        let fill = (item_size as f64) / (bin_capacity as f64);
        score -= fill * 5.0;
        // Discard near-empty bins? No: using them reduces open-bin sprawl.
        if open_bins_count > 8 {
            score -= 3.0; // consolidate when many bins open
        }
    }

    // Prefer bins whose residual is close to the item (best-fit flavor).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

