    score += waste_frac * 30.0;

    // Open-bin pressure: penalize spreading across many bins.
    score += open_bins_count as f64 * 1.2;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: default neutral-ish, but discourage opening a new bin
    // when existing bins fit well; encourage it when all fits are poor.
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 0.5;
        if next_item_size > 0 && post_residual >= next_item_size {
