        }
    }

    // Lookahead coupling: if the next item fits the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 4.0; // next item can't use this gap
    }

    // Stream progression: late in the stream, be more conservative about
    // spreading (favor consolidating into existing bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * mean_residual * 0.05;

