    // New-bin candidate handling: only open a new bin if the fit is poor
    // and no better option exists (empty bin has large post_residual).
    if bin_residual == bin_capacity {
        // neutral baseline; opening a new bin should be slightly discouraged
        // so tight fits in existing bins win, but bad fits lose to it.
        score += 15.0;
        if item_size >= bin_capacity / 2 {
            score -= 10.0; // big items fine in fresh bins
        }
    }

    // Early in stream: prefer consolidating into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

