        score += 20.0;
        // But if existing bins are nearly full on average, opening is fine.
        let mean_frac = mean_residual / cap;
        if mean_frac < 0.15 { score -= 15.0; }
        if open_bins_count == 0 { score -= 25.0; }
        // Lookahead: if next item is large, a fresh bin is valuable.
        if next_item_size >= 60 { score -= 8.0; }
    } else {
        // Prefer bins whose residual is close to the item (minimize fragmentation).
        let tightness = (bin_residual - item_size) as f64 / cap;
        score += tightness * 4.0;
    }

    // Mild late-stream consolidation: fewer open bins preferred as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.3 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward exact fit for a plausible next item (lookahead coupling).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize leaving a gap that is just barely too small for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Tightness reward: fraction of the bin consumed by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // Prefer bins whose residual deviates favorably from the mean residual.
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 100.0 + 50.0 * progress + 3.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 200.0; // forced open
        }
        if post_residual == 0 { score -= 40.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: small post_residual is the primary goal.
    if post_residual == 0 {
        score -= 1000.0; // perfect closure
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // 2-step lookahead: if next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - 0.35 * slack; // prefer tight chain fits
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the lookahead item: penalize proportionally.
        score += 0.6 * (next_item_size - post_residual) as f64;
    }

    // Relative-to-mean-residual coupling: bins with residual far from the mean
    // that leave large post residuals create fragmentation.
    let mean_gap = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * mean_gap;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin for a small item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Penalize wasting a mostly-full bin's unique tightness on a loose fit.
    if post_residual > 0 && post_residual < 10 && next_item_size > post_residual {
        score += 15.0;
    }

    // Early in the stream, be slightly more willing to open fresh bins for big items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive if the item is large and would leave a
        // usable post residual, otherwise discourage.
        let pr = post_residual as f64;
        score = 30.0 + pr * 0.8 - (1.0 - progress) * 20.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0; // fresh bin can also chain the next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 20.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 5 {
        score -= 10.0;
    }

    // Lookahead: penalize residuals too small for the next item (dead space),
    // reward residuals that can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Among many options, mildly prefer bins with less residual before placement.
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    // New-bin candidate: make it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 25.0 + progress * 10.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_score -= 5.0;
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 40.0; // no alternative: must open
        }
        score = score.max(new_bin_score) + 5.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, compact placements (small post_residual) matter more.
    let progress_coupling = progress * norm_pr * norm_pr * 40.0;
    score += progress_coupling;

    // Reward near-perfect fits with a smooth saturating term.
    let fit_quality = 1.0 - norm_pr;
    score -= 12.0 * fit_quality * fit_quality * fit_quality;

    // Penalize dead space that is too small to be useful (smoothly).
    let dead = norm_pr * (1.0 - norm_pr);
    score += 6.0 * (1.0 - dead * 4.0).abs() * norm_pr;

    // Last-chance bin: strongly favor using it (smooth reward).
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty scaled by leftover size.
        score += 4.0 * norm_pr;
    }

    // Slight preference for keeping bins balanced with mean residual.
    score += 0.05 * (pr - mean_residual).abs();

    // Penalize opening new bins when open bins exist (smooth in open count).
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
