pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    } else {
        // Larger leftovers are reusable; reward tight-but-usable fits.
        score -= 4.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Prefer bins whose residual closely matches the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or late in stream.
        score += 20.0 + 2.5 * open_bins_count as f64 + 30.0 * progress;
        // If no other bin fits well, allow opening a new bin.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    } else if fitting_bins_count == 1 {
        // Last chance bin: strongly favor using it to avoid a new bin.
        score -= 15.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the upcoming item.
        score += 10.0;
    }

    // Mild preference for bins below mean residual (consolidating emptier bins).
    score -= (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits — squarify waste relative to mean residual.
    let waste_ratio = (post_residual as f64) / (mean_residual.max(1.0) + 1.0);
    score += 12.0 * waste_ratio;

    // Strong reward if the lookahead item exactly or nearly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-step chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward decays as slack grows; a small slack is excellent.
            score -= 40.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item cannot fit here after placement: penalize proportionally
            // to how much we "blocked" — big post_residual wasted.
            let overflow = (next_item_size - post_residual) as f64;
            score += 8.0 * (overflow / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is only attractive when the item is large and no
        // good chain exists; otherwise keep compacting existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        if large_item {
            score -= 10.0 + 10.0 * progress;
        } else {
            score += 18.0 + 5.0 * (open_bins_count as f64).ln();
        }
        // If next item is small, a fresh bin wastes its potential.
        if next_item_size > 0 && next_item_size < 20 {
            score += 10.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose post-residual stays in the "usable" band (>= 10),
    // since items are at least size 1 and small residuals are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post_residual (perfect fits).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Penalize bins whose residual is much larger than the item (wasteful use of big space).
    let waste_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 20.0 * waste_ratio * waste_ratio;

    // Lookahead: reward bins whose post_residual can host the next item (chained packing),
    // penalize leaving a residual just below the next item (frustrated fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // dead space relative to lookahead
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
        if post_residual > 40 {
            score += 12.0; // bad fit even in last-chance bin
        }
    }

    // New-bin candidate handling: opening a bin is only attractive when it gives
    // a near-perfect fit for the item itself, or when global state is congested
    // (many bins, high mean residual => fragmentation).
    if bin_residual == bin_capacity {
        score += 35.0; // base cost of opening a new bin
        if item_size >= 90 {
            score -= 35.0; // huge items fit perfectly in a fresh bin
        } else if item_size >= 60 {
            score -= 15.0;
        }
        // congestion: many open bins with large mean residual -> prefer fresh bin
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual > 30.0 && open_bins_count > 3 {
            score -= 10.0 + 10.0 * progress;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 12.0; // fresh bin can chain next item too
        }
    }

    // Mild preference to fill already-open bins as the stream progresses,
    // keeping the open-bin count low.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (mean_residual / bin_capacity as f64);

    // Small bonus for matching the mean residual (balanced packing).
    score -= 2.0 * (1.0 - ((post_residual as f64 - mean_residual).abs() / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;

    // Base: prefer minimal post-fit waste, mildly scaled by waste fraction.
    let mut score = post * (1.0 + 0.5 * (post / cap).powi(2));

    // Smooth reward for tight fits (small post_residual), non-linear in item size.
    score -= 8.0 * (1.0 - item / cap).powi(3) * (1.0 - post / cap).powi(2);

    // Lookahead coupling: reward if next item can use the post residual smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score += 0.6 * gap;
        if nxt <= post {
            score -= 5.0 * (1.0 - gap / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 12.0 * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: penalize opening bins unless current bin waste is severe.
    if is_new_bin {
        let waste_severity = (mean_residual / cap).powi(2);
        score += 10.0 + 15.0 * (1.0 - progress) - 20.0 * waste_severity;
        if fitting_bins_count <= 1 {
            score -= 18.0;
        }
    }

    // Late-stream pressure: consolidate into existing bins as stream progresses.
    score += 3.0 * progress * (post / cap);
    score += 0.05 * open_bins_count as f64 * (post / cap);

    // Mean-residual coupling: bins far from the mean residual get a small penalty
    // (prefer placing into bins whose residual matches the fleet average).
    score += 0.3 * ((bin_residual as f64 - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 defines "dead space quality"
    let r_mod = post_residual % 10;
    // Perfect fits / small dead space in multiples of 10 are highly reusable
    let harmonic_bonus: f64 = match r_mod {
        0 => 12.0,
        1 | 9 => 2.0,
        2 | 8 => 0.0,
        3 | 7 => -2.0,
        4 | 6 => -4.0,
        _ => -6.0, // r_mod == 5: half-filled class, awkward
    };
    score -= harmonic_bonus;

    // Integer-division threshold: post_residual in [0,10] is nearly dead
    if post_residual <= 10 && post_residual > 0 {
        score += 8.0;
    }
    if post_residual == 0 {
        score -= 20.0; // perfect packing
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item chains perfectly: reward, scaled by how tight the chain is
            let tightness = (post_residual - next_item_size) as f64;
            score -= 10.0 - tightness * 0.15;
            // harmonic class match of chain
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // next item won't fit here: penalize wasting a good residual
            score += 4.0;
            if next_item_size > bin_residual {
                score += 3.0; // next item needs a new bin anyway
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }
    // Many fitting bins: prefer the tightest, penalize less
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // fresh bin: attractive early or when no open bin fits well
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_alternatives = mean_residual < item_size as f64 * 0.5;
        if poor_alternatives {
            score -= 18.0;
        } else {
            score += 10.0 + progress * 10.0;
        }
        // don't open a new bin for a small item that many bins fit
        if fitting_bins_count > 2 && item_size <= 30 {
            score += 25.0;
        }
    }

    // Prefer bins whose residual is far below mean (tight bins stay tight)
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.05;

    // Normalize against capacity fraction
    score *= 1.0 + (bin_residual as f64 / bin_capacity as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Open-bin pressure: discourage proliferation of bins, but only mildly
    // so tight fits still win over new bins.
    score += open_bins_count as f64 * 0.5;

    // Prefer filling bins with larger mean residual slightly less
    // (keep small-residual bins for tight future fits).
    score += (mean_residual - post_residual as f64).max(0.0) * 0.1;

    // New empty bin: penalize so it's chosen only when no good fit exists.
    if bin_residual == bin_capacity {
        score += 35.0;
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fits (dead space elimination)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    } else if post_residual <= 20 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can host next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
