            score += 40.0 * (gap / 100.0);
        }
    }

    // Relative-to-mean coupling: prefer tighter-than-average bins
    score -= 0.8 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is large
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 180.0 - 100.0 * (item_size as f64 / 100.0) + 50.0 * progress;
    }

    // Prefer filling bins that are already fairly full
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 30.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(4) * 30.0;

    // Penalize dead space that no typical item could fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Last-chance bonus: only bin that fits -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Penalize leaving a residual just below the next item (wasted gap).
            let gap = post_residual as f64 - (next_item_size as f64 - 10.0).max(0.0);
            if gap < 0.0 {
                score += (-gap).min(20.0);
            }
        }
    }

    // New-bin candidate logic: opening a new bin is attractive when open bins
    // have large mean residual but item fits poorly everywhere, or late in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0 + 1.0);
        // Prefer new bin when existing bins are fragmented (high mean residual spread)
        // and item is large.
        score += 10.0
            + fit_ratio * 20.0
            - (mean_residual / bin_capacity as f64) * 15.0
            - (item_size as f64 / 80.0) * 10.0
            - progress * 15.0
            + crowding * 2.0;
        // Perfect item for a fresh bin (item near capacity multiples).
        if item_size >= bin_capacity / 2 {
            score -= 12.0;
        }
    }

    // Mild penalty for using bins with small residual when many bins fit the item
    // (preserve flexibility for future items).
    if fitting_bins_count > 2 {
        score += (bin_residual as f64).ln().max(0.0) * 3.0;
    }

    // Encourage balancing residuals toward mean across open bins.
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let norm_post = post_residual as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 + 3.0 * progress) + norm_post * (0.5 + 2.0 * progress * progress);
    score += 8.0 * poly;

    // Dead-space penalty: tiny post-residuals are smooth quadratic waste
    let dead = (1.0 - norm_post).powi(3) * (norm_post * 4.0).powi(2);
    score -= 6.0 * dead;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    } else {
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead coupling: reward residuals that can host the next item
    if next_item_size > 0 && (post_residual as u64) >= next_item_size as u64 {
        let fit_quality = 1.0 - (post_residual as f64 - next_item_size as f64) / cap;
        score -= 10.0 * fit_quality * (1.0 + progress);
    } else if next_item_size > 0 {
        score += 5.0 * (1.0 + progress);
    }

    // Perfect-fit reward: smooth exponential of normalized tightness
    let tightness = 1.0 - norm_post;
    score -= 12.0 * tightness * tightness * tightness;

    // Mean residual deviation penalty (smooth quadratic)
    let dev = (post_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Late-stream consolidation: penalize spreading across many open bins
    score += (open_bins_count as f64).ln() * (1.0 + 2.0 * progress);

    // New-bin candidate handling: only attractive early or for huge items
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let big_item = item_size as f64 / cap;
        score += 18.0 * (1.0 - progress) - 15.0 * big_item * big_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = post_residual % (bin_capacity / 4); // classes of size 25

    // Reward very tight fits (small dead space) strongly
    if post_residual == 0 {
        score -= 200.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if class == 0 {
        // post_residual is a multiple of 25: highly reusable "harmonic" residue
        score -= 40.0;
    } else if post_residual < 10 {
        // dead space: too small for typical items (>=1 but risky)
        score += 60.0;
    } else if class == 10 {
        score -= 15.0;
    }

    // Fraction-of-capacity coupling: prefer residuals that are clean fractions
    let frac = pr / cap;
    if (frac - (frac * 4.0).round() / 4.0).abs() < 1e-9 {
        score -= 20.0; // residual is 0, 1/4, 1/2, 3/4 of capacity
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            let next_waste = post_residual - next_item_size;
            score -= 30.0 * (1.0 - next_waste as f64 / cap);
        } else {
            // next item won't fit here; slight penalty for hoarding space
            score += 10.0;
        }
    }

    // New-bin candidate handling: only attractive if no good open option
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 100.0;
        // early in stream, opening bins is cheaper (build diversity)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * (1.0 - progress);
        // if many bins already open and mean residual is high, discourage new bins
        score += 0.5 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 30.0;
        }
        // new bin can host next item pair nicely
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 60.0;
        }
    }

    // Mild preference for fuller bins overall
    score -= 0.1 * (bin_residual - post_residual) as f64;

    // Penalize leaving residual in awkward band (11..24) — hard to fill later
    if post_residual >= 11 && post_residual <= 24 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible future item are "dead space" -> heavy penalty.
    let min_item = 1.0f64;
    if post_residual > 0 && (post_residual as f64) < 10.0 {
        // unusable sliver: penalize proportionally to how wasted it is
        score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= 25.0 * (item_size as f64) / (bin_residual.max(1) as f64);
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    }
    // If next item cannot fit into post_residual, mild penalty (dead space likely).
    if next_item_size > post_residual && next_item_size > 0 {
        score += 8.0 * (next_item_size as f64 - post_residual as f64) / 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bins pressure: when many bins are open, discourage spreading;
    // prefer consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean-residual coupling: if this bin's residual is far below the mean
    // (already cramped), slightly favor it to close out small bins.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 0.15 * dev;
    } else {
        score += 0.10 * (-dev);
    }

    // New-bin candidate (empty bin): make it attractive only when it is a
    // genuinely good time to open (few bins open early, or item is large).
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 20.0;
        // large items justify fresh bins; small items should use leftovers
        score -= 0.35 * item_size as f64;
        // early in the stream, opening bins is cheaper
        score -= 25.0 * (1.0 - progress);
        // if no open bin fits well, opening is fine
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fit (low dead space).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 150.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 250.0;
        } else if post_residual >= next_item_size {
            // Next item fits: mild reward scaled by how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit: penalize leaving space it almost fits into.
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 20.0 {
                score += gap * 2.0;
            }
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    let diff = mean_residual - bin_residual as f64;
    score += 0.5 * diff;

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Penalize opening a new bin when good fitting bins exist.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when current item is large
        // or many bins are already open with high mean residual.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 90.0 - 0.6 * item_size as f64 + 0.3 * mean_residual + 20.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size && next_item_size <= bin_capacity {
            score -= 30.0; // new bin can serve both items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit, but reward near-perfect packing more strongly.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that nothing (including next item) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 18.0; // next item likely fills this bin perfectly
    }

    // Lookahead: if next item cannot fit here but fits elsewhere, mild penalty for consuming space.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 6.0;
    }

    // Last-chance bonus: only bin that fits -> strong preference to avoid new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Global pressure: many open bins with high mean residual -> favor filling existing bins.
    let pressure = mean_residual / bin_capacity as f64;
    score -= 8.0 * pressure * (open_bins_count as f64).ln().max(1.0);

    // Time horizon: early in stream, opening new bins is cheap; late, conserve.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: cost grows with progress and number of open bins.
        score += 15.0 * progress + 2.0 * (open_bins_count as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin can host next item too
        }
    } else if progress > 0.7 {
        score -= 10.0 * progress; // late stream: pack tightly
    }

    // Slight aversion to leaving very large residuals relative to capacity.
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap;
    let prog2 = progress * progress;
    score += 6.0 * prn * prn * (0.5 + progress) * cap * 0.1;
    score -= 4.0 * prn * (1.0 - progress) * (1.0 - progress);

    // Reward tight fits, stronger late in the stream
    let tight = 1.0 - prn;
    score -= 8.0 * tight * tight * (0.3 + 0.7 * progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 5.0 * (nx - pr) / cap * (1.0 + progress);
        } else {
            score -= 2.0 * (pr - nx) / cap;
        }
    }

    // Last-chance bonus: avoid opening a new bin when only this one fits
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    } else {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Mild pressure toward consolidating into existing bins
    score += 0.05 * (open_bins_count as f64) * prn;
    score += 0.5 * (mean_residual - pr) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 classes
    let class = post_residual % 10;
    // Small residuals are dead space; penalize tiny nonzero remainders
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Favor residuals that are "harmonic" (divisible by 5 or 10) -> easier future fits
    if class == 0 {
        score -= 8.0;
    } else if class == 5 {
        score -= 4.0;
    } else {
        score += class as f64 * 0.5;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            let rem2 = post_residual - next_item_size;
            // reward if the chain continues harmonically
            if rem2 % 10 == 0 { score -= 12.0; }
            score -= rem2 as f64 * 0.3;
        } else {
            // next item won't fit here; penalize large stranded residuals
            score += (post_residual as f64) * 0.25;
            // if residual is in awkward band 20..40 and next item is large, penalize
            if post_residual >= 20 && post_residual <= 40 && next_item_size > post_residual {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: neutral-ish, but discourage when a good fit exists
    if bin_residual == bin_capacity {
        score += 30.0;
        // opening a new bin is fine if item is huge relative to capacity fraction
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.6 { score -= 25.0; }
        // or if mean residual across open bins is too small to matter
        if mean_residual < item_size as f64 { score -= 15.0; }
    }

    // Progress-based pressure: late in stream, consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer filling bins with low mean residual (tight bins)
    score += (mean_residual - post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small gaps: residual below the minimum item size (1) is impossible,
    // but tiny residuals (< 12) are statistically hard to fill.
    if post_residual > 0 && post_residual < 12 {
        score += (12.0 - post_residual as f64) * 3.0;
    }

    // Reward tight fits (post_residual near zero) with a superlinear bonus.
    score -= 40.0 / (1.0 + post_residual as f64);

    // Pressure from number of open bins: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post-residual exactly, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 15.0 / (1.0 + slack);
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use leftover space: penalize wasted potential.
        score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.5;
    }

    // Mild bias toward bins with below-average residual (consolidate fullness).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Early in stream: be slightly more willing to open bins (keep flexibility);
    // later: consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when current bins are crowded or fit is bad.
        let crowding = mean_residual / bin_capacity as f64;
        score = 60.0 + crowding * 40.0 - progress * 30.0
            + if fitting_bins_count <= 1 { 0.0 } else { 20.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly favor bins where the item leaves minimal dead space.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this placement chains perfectly; reward it heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Next item fits: penalize by how much slack would remain after it
            // (encourages leaving tight, usable residuals).
            let chain_residual = post_residual - next_item_size;
            score -= 80.0 - (chain_residual as f64) * 0.5;
        } else {
            // Next item does NOT fit in the residual: penalize creating dead space
            // relative to the next item's size.
            let gap = next_item_size - post_residual;
            score += (gap as f64) * 0.8;
        }
    }

    // Relative-to-mean coupling: bins with residual far below the mean are already
    // "tight" — placing here compresses waste into few bins. Favor tight bins.
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.6;

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: make opening a fresh bin moderately expensive unless the
    // fit elsewhere is terrible. Base penalty on the mean residual (if open bins
    // are very full on average, a new bin is more acceptable).
    if bin_residual == bin_capacity {
        score += 60.0 + mean_residual * 0.5;
        // Late in the stream, avoid opening bins for small leftovers.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
    }

    // Mild preference for bins with larger current residual (best-fit is already
    // captured by post_residual; this breaks ties toward fuller bins).
    score += (bin_residual as f64) * 0.1;

    // Slight pressure to consolidate into fewer bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead reward: if the next item can also fit in the leftover space,
    // this bin is doubly useful -> subtract a bonus proportional to the fit.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_quality = next_item_size as f64 / bin_capacity as f64;
        score -= 8.0 + 12.0 * chain_quality;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Penalize new bins when a reasonable fit exists in an open bin.
    if is_new_bin {
        // The worse the best available fit (large mean residual left behind),
        // the more attractive a fresh bin becomes.
        let fit_pressure = (item_size as f64 / bin_capacity as f64).clamp(0.0, 1.0);
        let openness = (open_bins_count as f64).ln_1p();
        // Early in the stream, opening bins is cheaper; later, consolidate.
        let time_discount = 1.0 - 0.5 * progress;
        score -= 10.0 * time_discount * (1.0 - fit_pressure) - 3.0 * openness;
        // If the item is large, a fresh bin is naturally a good home.
        if item_size >= bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // Penalize creating awkward dead space: leftover slivers that almost no
    // future item (min size 1, but realistically >10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 4.0;
    }

    // Mild global balance: prefer bins whose residual is close to the mean
    // (keeps the open-bin pool homogeneous and packable).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for filling fuller bins as the stream matures.
    score -= progress * (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: prefer small post residual, with non-linear polynomial coupling
    let mut score = norm_pr * (1.0 + 2.0 * norm_pr * (1.0 - norm_pr));

    // Stream-progress coupling: later in the stream, penalize large residuals more strongly
    score += 0.8 * progress * norm_pr * norm_pr;

    // Lookahead coupling: reward bins whose post residual fits the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 0.6 * (1.0 - ((pr - nxt) / cap).abs()) * (1.0 - progress);
        } else {
            score += 0.4 * ((nxt - pr) / cap) * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // New-bin candidate: mild penalty so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 0.5 + 0.5 * (1.0 - progress);
    }

    // Dead-space penalty: residuals too small for typical items
    if pr > 0 && pr < 10 {
        score += 1.5 * (1.0 - pr / 10.0);
    }

    // Mean residual divergence: favor bins near the mean (balanced packing)
    score += 0.2 * ((mean_residual - pr) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: bucket post_residual into deciles of capacity.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (pr / (cap / 10.0)).floor() as i32; // 0..10

    // Dead-space penalty: small post_residual classes are good (tight fit),
    // mid-range classes (3..7) leave awkward gaps -> penalize.
    match class {
        0 => score -= 40.0,
        1 => score -= 25.0,
        2 => score -= 12.0,
        3 | 4 | 5 | 6 => score += 15.0,
        7 => score += 5.0,
        _ => {}
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 45.0;
    }

    // Lookahead coupling: can next item exactly fill the post_residual?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (nx - pr).abs() <= 2.0 {
            score -= 35.0; // this bin chains perfectly
        } else if nx <= pr {
            // next item fits here later: keep some usable room
            let usable = pr / nx;
            if usable >= 1.0 && usable < 2.0 {
                score -= 10.0;
            }
        } else {
            // next item cannot use this leftover -> dead space risk
            score += (nx - pr).min(30.0) * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: opening a new bin wastes existing residual mass.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; allow it only when current bins are crowded
        // or the item is large relative to mean residual.
        let pressure = (mean_residual / cap).max(0.0);
        score += 55.0 - 40.0 * pressure;
        if item_size as f64 > mean_residual {
            score -= 25.0; // large item, existing bins too tight
        }
        if next_item_size > 0 && (next_item_size as u32) + item_size <= bin_capacity {
            score -= 10.0; // new bin can host a pair
        }
    }

    // Slight preference for fuller bins overall (compactness pressure).
    score -= (bin_residual as f64 / cap) * 3.0;

    // Late-stream tightening: as stream ends, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item (1..100 range)
    // are worthless; residuals that fit the lookahead item are valuable.
    if post_residual > 0 {
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0; // gap remains usable for the next item
        } else if post_residual < 10 {
            score += 25.0; // tiny unusable dead space
        }
    } else {
        score -= 40.0; // perfect closure of the bin
    }

    // Tight-fit reward: fraction of the bin consumed by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity, so it gets no
    // tight-fit or last-chance rewards and a large residual score).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (2.0 + 3.0 * progress);

    // Prefer bins with below-average residual (denser bins absorb the item better).
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;

    // Lookahead coupling: if the next item would fit exactly in the post gap, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but avoid tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // dead space penalty: sliver too small for any item (min size 1..100 but keep buffer)
    }

    // 2-step lookahead: strongly reward exact match of post_residual with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect chain: next item exactly fills this bin
        } else if post_residual >= next_item_size {
            score -= 8.0; // next item can also fit here
            // extra reward for near-exact second fit
            let slack2 = (post_residual - next_item_size) as f64;
            if slack2 < 5.0 {
                score -= 5.0;
            }
        } else {
            // next item won't fit: penalize proportional to wasted lookahead potential
            let miss = (next_item_size - post_residual) as f64;
            score += 0.15 * miss;
        }
    } else {
        // last item: just close out tightly
        score -= 3.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are "odd" bins;
    // prefer placing into them when they fit well to consolidate.
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += 0.05 * dev; // slightly favor below-mean-residual bins (they get emptied)
    } else {
        score += 0.03 * dev; // mildly penalize above-mean bins
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Neutral-ish base; add pressure that grows with number of open bins
        // and with how well the item would fit in existing bins (fitting_bins_count > 0).
        score = bin_capacity as f64 * 0.9 + 2.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 10.0; // discourage opening new bin when open bins can fit
        }
        // Early in stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // If next item is large and would pair with current item in a fresh bin, allow it
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity && fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mild preference for consolidating into fewer bins overall.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (waste minimization core).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize leaving dead space that likely cannot be reused.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
            // Bonus when next item exactly fills the bin.
            if next_item_size == post_residual {
                score -= 30.0;
            }
        } else {
            // Next item won't fit here; slight penalty proportional to gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 22.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty for spreading across many fitting bins.
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Time horizon: as stream progresses, prefer consolidating into open bins
    // and penalize opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base score plus escalating penalty with progress
        // and number of open bins, so late in the stream we reuse bins.
        score += 12.0 + 25.0 * progress + 1.2 * open_bins_count as f64;
        // But early on, opening a new bin for very large items is fine.
        if item_size >= 50 && progress < 0.3 {
            score -= 15.0;
        }
        // Never open a new bin when a near-perfect fit exists elsewhere.
        if tightness < 0.05 && bin_residual != bin_capacity {
            score -= 100.0;
        }
    } else {
        // Reward using bins that deviate from the mean residual toward fullness.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 3.0 * (1.0 / (1.0 + dev / 50.0));
    }

    // Prefer packing into bins whose residual is close to item_size (exact-ish fits).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.2 * fit_gap;

    // Mild preference for bins with above-average residual (keeps small bins for small items).
    if bin_residual as f64 > mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Smooth non-linear coupling of post_residual with stream progress
    let poly = (1.0 - progress) * (norm_pr * norm_pr) + progress * (1.0 - norm_pr * norm_pr);
    score += 12.0 * poly;

    // Penalize dead space more sharply as stream advances (quadratic in progress)
    score += 8.0 * progress * norm_pr * norm_pr;

    // Reward tight fits (small post_residual) with a smooth saturating term
    let tight = (-norm_pr * 4.0).exp();
    score -= 15.0 * tight * (1.0 - progress * 0.5);

    // Lookahead: favor bins whose post_residual matches the next item
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score += 0.6 * diff * (1.0 - progress * 0.3);
        // Exact match bonus, smoothed
        let match_bonus = (-diff * diff / 50.0).exp();
        score -= 10.0 * match_bonus;
    }

    // Last-chance bin: strong reward to avoid opening new bins unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 * (1.0 + progress);
    }

    // Discard near-empty residuals that waste capacity
    if norm_pr < 0.05 {
        score += 5.0 * (0.05 - norm_pr) / 0.05;
    }

    // Mild penalty for spreading across too many open bins
    score += 0.3 * open_bins_count as f64 * norm_pr;

    // Mean-residual alignment: prefer bins close to the mean residual state
    let mean_diff = (pr - mean_residual).abs();
    score += 0.15 * mean_diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions.
    // Residuals in "dead" classes (small but unusable slivers) are penalized harder.
    let r = post_residual;
    let dead_class = if r == 0 { 0 } else if r < 10 { 1 } else if r < 25 { 2 } else { 3 };
    score += match dead_class {
        0 => -60.0,                      // perfect fill
        1 => 55.0,                       // tiny unusable sliver -> heavy penalty
        2 => 12.0,                       // moderate dead space
        _ => -8.0,                       // large residual still useful
    };

    // Harmonic compatibility: does the NEXT item divide into the post residual?
    if next_item_size > 0 {
        if next_item_size <= r {
            // next item fits exactly or with small slack -> reward
            let slack = (r - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this bin's residual -> mild penalty scaled by waste
            score += 6.0 * ((next_item_size - r) as f64 / bin_capacity as f64);
        }
        // harmonic pairing: next_item_size divides r evenly (r % next == 0)
        if next_item_size > 0 && r % next_item_size == 0 && r > 0 {
            score -= 18.0;
        }
    } else {
        // last item: strongly prefer tightest fill
        score -= 30.0;
    }

    // Last-chance bin: only one fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Prefer bins whose residual deviates from the mean toward small residuals
    // (concentrate waste into fewer bins).
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Late in the stream, tighten packing: penalize loose residuals more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.5;

    // New empty bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 35.0 + 5.0 * (open_bins_count as f64).sqrt();
        if fitting_bins_count > 1 {
            score += 20.0; // other bins fit; discourage opening new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps heavily.
    // A gap is "dead" if it is smaller than the smallest plausible item (1..100 range),
    // but especially if it falls below a mid-size threshold.
    if post_residual > 0 {
        if post_residual < 10 {
            // Nearly full bin: excellent, reward strongly (tiny unusable gap is fine
            // because the bin is essentially closed).
            score -= 30.0;
        } else if post_residual < 25 {
            // Small gap: likely dead space unless next item fits it.
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 15.0; // next item can use this gap
            } else {
                score += 25.0; // dead space penalty
            }
        } else if post_residual < 50 {
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 10.0;
            } else {
                score += 8.0;
            }
        } else {
            // Large residual: flexible, mild reward.
            score -= 5.0;
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 5.0;
            }
        }
    } else {
        // Perfect fit: bin fully closed.
        score -= 40.0;
    }

    // Open-bins pressure: penalize placements that keep many bins open,
    // encouraging consolidation into fewer bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 2 {
        // Many options: prefer the tightest fit implicitly via post_residual,
        // slight penalty to allow discrimination.
        score += 2.0;
    }

    // Prefer bins whose residual is close to the item (tight fit bonus).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 10.0;

    // Mean residual coupling: if this bin's residual is far below mean,
    // it is an outlier worth closing out.
    let residual_diff = mean_residual - bin_residual as f64;
    if residual_diff > 0.0 {
        score += residual_diff * 0.3;
    } else {
        score += residual_diff * 0.1;
    }

    // New-bin candidate handling: empty bin starts with max residual.
    // Only prefer opening a new bin if no open bin gives a good fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: grows with open bins and progress.
        score += 35.0 + open_bins_count as f64 * 3.0;
        // But if current item is large relative to typical residuals, opening
        // a fresh bin preserves flexibility for future items.
        if item_size >= 50 {
            score -= 20.0;
        }
    }

    // Lookahead: if next item is large, avoid leaving medium gaps that
    // neither fit it nor small items.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 30 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item exactly fills the post-residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Next item fits inside leftover: mildly good, but leaves more dead space later.
            score -= 30.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use the leftover: penalize proportionally to wasted space.
            score += 40.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Penalize creating unusable dead space (small slivers that few items can fill).
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Compare post_residual against mean residual across open bins:
    // prefer leaving residuals close to the mean (balanced bins), punish outliers.
    let diff = post_residual as f64 - mean_residual;
    score += 0.05 * diff * diff;

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 && post_residual >= next_item_size { 1.0 } else { 0.0 };
        score += 200.0 - 100.0 * pressure;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0 * progress;
        // Fewer open bins -> opening a new one is cheaper.
        score -= 10.0 * open_bins_count as f64;
    }

    // Slight preference for filling bins that are already mostly full.
    score -= 0.3 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Penalize large dead space relative to capacity
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * dead_frac * dead_frac;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 80.0;
        } else if next_item_size <= bin_residual && post_residual < next_item_size {
            // placement destroys ability to host next item in this bin
            score += 30.0;
        }
        // reward leaving space compatible with typical next sizes
        score += 0.3 * ((post_residual as f64 - next_item_size as f64).abs() / 20.0);
    }

    // Time horizon: early on, be conservative (prefer tight fits later);
    // late in stream, prefer filling existing bins aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 40.0 * progress * (1.0 - dead_frac);

    // Many open bins: discourage spreading; favor bins below mean residual
    if open_bins_count > 1 {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.15 * diff;
    }

    // Prefer bins that are already fairly full (small residual before placement)
    score += 0.2 * (bin_residual as f64 / bin_capacity as f64) * -1.0 + 20.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // New bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let penalty = if fitting_bins_count == 0 { -50.0 } else { 120.0 + 40.0 * (1.0 - progress) };
        score += penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res_norm = pr / cap;
    let mut score = pr;

    // Non-linear coupling: post_residual weighted by stream progress polynomial
    let prog_poly = 0.5 + 1.5 * progress * progress;
    score *= prog_poly;

    // Penalize large residuals early, reward tight fits late (smooth interaction)
    score += 10.0 * res_norm * res_norm * (1.0 - progress) * cap * 0.1;

    // Reward residual that matches next item size (smooth coupling)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx) / cap;
        score -= 8.0 * (-diff * diff * 40.0).exp() * nx / cap;
    }

    // Last-chance bin bonus (smooth penalty on alternatives via reward)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: mildly discouraged unless residual tightness elsewhere is bad
    if bin_residual == bin_capacity {
        score += 6.0 + 20.0 * progress;
    }

    // Mean residual alignment term (smooth)
    score += 0.05 * (mean_residual - pr).abs();

    // Slight open-bin consolidation pressure
    score += (open_bins_count as f64).ln().max(0.0) * res_norm * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space that is "usable" for common
    // small items (multiples of 10) is less costly than odd dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fill_frac = 1.0 - pr / cap;

    // Reward tight fits strongly (harmonic-like: reward ~ 1/(1+post_residual/10))
    score -= 40.0 / (1.0 + pr / 10.0);

    // Perfect or near-perfect fit gets a big bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Modulo-10 harmonic class: residuals that are multiples of 10 pair well
    // with items drawn on a 10-grid; penalize odd residuals (waste-prone).
    let rem10 = post_residual % 10;
    if rem10 == 0 {
        score -= 8.0;
    } else {
        score += 4.0 + rem10 as f64;
    }

    // Lookahead coupling: if the next item fits into post_residual, reward;
    // if not, the residual becomes dead space for the horizon -> penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // exact pairing bonus
            if next_item_size == post_residual {
                score -= 30.0;
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using
    // it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + fill_frac * 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        // Base penalty so we prefer existing bins with decent fits.
        score += 45.0;
        // But if the item is huge, a fresh bin is actually good (full pairing).
        if item_size >= bin_capacity * 3 / 4 {
            score -= 35.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // Many open bins with slack: discourage another one.
        if open_bins_count > 3 && mean_residual > item_size as f64 {
            score += 15.0;
        }
    }

    // Prefer bins with residuals close to the item (best-fit flavor) via
    // integer division threshold on residual class.
    let resid_class = bin_residual / 20; // coarse class 0..=5
    score -= resid_class as f64 * 1.5;

    // Mild penalty for spreading across too many bins.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }
    // Zero residual is a perfect fit: big reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tightness reward: fraction of bin consumed by this item.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // Many fitting bins: slight penalty to prefer consolidation.
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0);
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += open_bins_count as f64 * 0.5;

    // Lookahead: reward leaving space that the next item can use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Mean-residual coupling: penalize bins far below mean residual (fragmented).
    score += (mean_residual - bin_residual as f64).abs() * 0.1;

    // New-bin candidate baseline: keep it competitive but slightly conservative.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score -= (bin_capacity as f64 - gap) * 1.5; // strong reward for perfect next-fit
        // extra reward for exact match (post_residual == next_item_size)
        if gap < 1.0 {
            score -= bin_capacity as f64 * 2.0;
        }
    } else if next_item_size > 0 {
        // next item cannot fit here: penalize proportionally to wasted potential
        let waste = next_item_size as f64 - post_residual as f64;
        score += waste * 0.8;
    }

    // Penalize large leftover residual relative to mean residual (dead space)
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.6;

    // Reward tight fits overall (small post_residual)
    score -= (bin_capacity as f64 - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= bin_capacity as f64 * 3.0;
    }

    // Mild penalty for opening new bins when many bins are already open and could fit
    if bin_residual == bin_capacity {
        score += bin_capacity as f64 * (1.0 + open_bins_count as f64 * 0.05);
    }

    // Late-stream consolidation: prefer filling existing bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * post_residual as f64 * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward small residuals that few items can use.
    if post_residual > 0 {
        let awkward = (post_residual as f64) / bin_capacity as f64;
        if awkward < 0.15 {
            score += 30.0 * (0.15 - awkward) / 0.15;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let nl = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * nl;
        } else {
            // next item cannot use this residual; slight penalty for large wasted space
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Crowding: many open bins -> prefer filling existing ones over opening new.
    let crowding = open_bins_count as f64 / (total_items.max(1) as f64).sqrt().max(1.0);
    score += crowding * 3.0;

    // Deviation from mean residual: prefer bins whose residual is close to the item
    // (avoid wasting large-residual bins on small items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate handling: empty bin should only win when no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base cost of opening a bin; grows with number of open bins and stream progress.
        let mut nb = 70.0 + 10.0 * open_bins_count as f64 + 30.0 * progress;
        // If the item is huge relative to capacity, a fresh bin is more attractive.
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            nb -= 40.0;
        }
        // If no other bin fits, opening is fine.
        if fitting_bins_count == 0 {
            nb -= 80.0;
        }
        score = nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let coupling = pr_norm * pr_norm * (1.0 - progress) + pr_norm * progress * 0.5;
    score += coupling * 20.0;

    // Reward tight fits (small post_residual) increasingly as stream advances
    let tightness = (bin_capacity as f64 - pr) / bin_capacity as f64;
    score -= tightness * tightness * (1.0 + progress) * 10.0;

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + 10.0 * progress;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening new bins when many open bins have residual
    if bin_residual == bin_capacity {
        score += 5.0 + mean_residual * 0.3 + open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which small-item classes can still use it
    let post = post_residual as u32;
    if post > 0 {
        // classify post_residual into harmonic buckets via integer division
        let class = post / 10; // 0..10
        match class {
            0 => score -= 8.0,                 // nearly perfect fit
            1 => score -= 3.0,                 // very good
            2 => score -= 1.0,
            3 | 4 => score += 1.5,             // awkward mid space
            5 | 6 => score += 0.5,             // half-bin useful
            _ => {}                            // large residual, fine
        }
        // modulo coupling: post_residual divisible by common small sizes is reusable
        if post % 10 == 0 { score -= 2.0; }
        if post % 20 == 0 { score -= 1.5; }
        if post % 25 == 0 { score -= 1.0; }
        if post % next_item_size.max(1) == 0 && next_item_size > 0 && next_item_size <= post {
            score -= 3.0; // next item exactly fills leftover class
        }
    }

    // lookahead: next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 6.0;
        } else if next_item_size < post {
            score -= 1.0;
        } else {
            score += 2.0; // dead space for the known next item
        }
    }

    // last-chance bin: strongly reward using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // penalize creating residual below the smallest plausible item
    if post > 0 && post < 5 {
        score += 12.0;
    }

    // new-bin candidate: only attractive when current fit is poor
    if bin_residual == bin_capacity {
        let fit_quality = post as f64 / cap;
        if post == 0 {
            score = cap + 50.0; // perfect fit beats opening a new bin
        } else if fit_quality < 0.15 && open_bins_count > 0 {
            score = cap * 0.3; // poor fit -> prefer new bin
        } else {
            score = cap + 20.0;
        }
    }

    // mild pressure to consolidate as stream progresses
    score += (step_index as f64 / (total_items.max(1) as f64)) * mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible item (<= 10) are pure waste. Penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual == 0 {
        // Perfect fill is the best outcome.
        score -= 100.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio;

    // Penalize leaving a gap that neither fits the next item nor any small item well.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            // Gap can't hold the lookahead item: mild penalty scaled by gap smallness.
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        } else if next_item_size <= post_residual {
            // Gap can hold lookahead: reward exact lookahead fill.
            if post_residual == next_item_size {
                score -= 25.0;
            } else {
                score -= 5.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing
    // bins; opening a new bin is cheaper when few bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 3.0;

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: moderate, so poor fits in existing bins
        // (already penalized above) lose against it, but good fits win.
        score += 45.0;
        // Late in the stream, prefer closing out existing bins rather than
        // spawning new ones.
        score += 20.0 * progress;
        // If only one bin is open, opening a second is fine (parallelism).
        if open_bins_count <= 1 {
            score -= 15.0;
        }
    }

    // Slight preference for bins whose residual is close to mean (balanced packing).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 500.0;
    }

    // 2-step lookahead: strongly reward residual that matches the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual > next_item_size {
            // Next item fits too: penalize wasted leftover beyond next item.
            let after_next = post_residual - next_item_size;
            score -= 200.0 - (after_next as f64).min(100.0);
        } else {
            // Next item does not fit: penalize proportionally to the shortfall.
            let shortfall = next_item_size - post_residual;
            score += (shortfall as f64) * 3.0;
        }
    }

    // Compare post_residual relative to mean residual across open bins.
    let mean_post = mean_residual - item_size as f64;
    if post_residual as f64 > mean_post {
        score += (post_residual as f64 - mean_post) * 0.5;
    } else {
        score -= (mean_post - post_residual as f64) * 0.5;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when decent open bins exist, unless it's early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let open_bonus = if open_bins_count == 0 {
            -1000.0
        } else {
            (open_bins_count as f64) * 20.0 * (0.5 + progress)
        };
        score += open_bonus;
        // New bin is attractive if post_residual here (== capacity - item) pairs well with next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 150.0;
        }
    }

    // Mild preference for tighter bins as the stream progresses.
    score += (bin_residual as f64) * (0.1 + 0.1 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 60.0;
    }

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0;
        }
        // Exact pairing bonus: item + next item fills the bin.
        if item_size + next_item_size == bin_residual {
            score -= 120.0;
        }
        // Penalize wasting space when next item could fit better elsewhere.
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Crowding: many open bins -> prefer tightening existing bins over spreading.
    let crowding = open_bins_count as f64 / (1.0 + step_index as f64).max(1.0);
    score += crowding * 2.0;

    // Prefer bins with below-average residual (already tight bins).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Time horizon: early in the stream, keep bins balanced; later, pack greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 20.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Penalize opening new bins mildly; escalates with stream progress and crowding.
        score += 40.0 + 120.0 * progress + 5.0 * open_bins_count as f64;
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 150.0; // opening a fresh bin for a big pair is good
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: post-residual, damped by smooth progress coupling
    let mut score = r * (1.0 + 0.35 * progress * rn);

    // Non-linear penalty for awkward residuals (dead space that few items can use)
    score += 18.0 * rn * (1.0 - rn) * (1.0 - rn) * 4.0;

    // Reward tight fits more strongly as stream progresses
    score -= 25.0 * progress * (1.0 - rn) * (1.0 - rn);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item can use the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if r >= nxt {
            score -= 15.0 * (1.0 - ((r - nxt) / cap).abs());
        } else {
            score += 8.0 * (nxt - r) / cap;
        }
    }

    // Slight preference to fill bins when many bins are open
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - rn);

    // Mean-residual coupling: prefer bins deviating from mean (consolidation)
    score += 0.15 * (r - mean_residual).abs();

    // New-bin candidate: penalize mildly unless current residuals are all bad
    if bin_residual == bin_capacity {
        score += 30.0 - 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, penalize near-full residual waste asymmetrically.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * frac * frac;

    // Harmonic classes: bucket post_residual into modulo-10 classes.
    // Residuals divisible by 10 are "clean" (likely reusable by future items);
    // odd/prime-ish residuals are dead space.
    let cls = post_residual % 10;
    let class_bonus: f64 = match cls {
        0 => 25.0,
        1 | 9 => 2.0,
        5 => 8.0,
        2 | 4 | 6 | 8 => 5.0,
        _ => 0.0,
    };
    score -= class_bonus;

    // Integer-division threshold on post_residual: residuals in [1,10] are gold
    // (nearly full bin); residuals in (10,30] are the worst dead zone.
    if post_residual <= 10 && post_residual > 0 {
        score -= 40.0;
    } else if post_residual > 10 && post_residual <= 30 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward; if next item is close (within modulo-10 class), reward mildly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 20.0 * (1.0 - gap as f64 / 30.0).max(0.0);
            if gap % 10 == 0 {
                score -= 10.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate handling: opening a new bin is penalized when the stream
    // is early (many items left to fill it) but acceptable late.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 - 60.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Harmonic alignment with mean residual: prefer bins whose post_residual
    // stays near the open-bin mean (keeps bins interchangeable).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Coupling: large items prefer bins with small residual before placement.
    if item_size >= 50 && bin_residual - item_size <= 20 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A residual that cannot fit even the smallest plausible item (>=1)
    // is pure waste; residuals below a "useful threshold" are heavily taxed.
    let useful_threshold: f64 = 20.0;
    if (post_residual as f64) < useful_threshold {
        score += (useful_threshold - post_residual as f64) * 6.0;
    }
    // Exact fit is a perfect placement.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits the post residual,
    // reward this bin strongly (chaining placements).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual blocks the next item: dead space for the lookahead.
        score += 8.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading; makes opening new bins less attractive.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 3.0 * progress);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let mean_gap = mean_residual - item_size as f64;
        // Penalize new bin unless existing residuals are poor fits.
        if mean_gap > 0.0 {
            score += 30.0 + open_bins_count as f64 * 2.0;
        } else {
            score -= 5.0;
        }
    }

    // Mild alignment with mean residual: bins deviating far from the mean
    // residual (very full bins) are slightly preferred (tight packing).
    score -= (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item exactly fills the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if diff == 0.0 {
            score -= 800.0;
        } else if post >= nxt {
            score -= 300.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item cannot use the leftover space: penalize proportional to waste
            score += 0.5 * post * (1.0 - nxt / bin_capacity as f64);
        }
    }

    // Compare post_residual against mean residual: leaving less than average is good
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.3 * (post_f - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // New-bin candidate: penalize unless current bins fit poorly
    if bin_residual == bin_capacity {
        let mut base = 200.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            base -= 100.0;
        }
        if fitting_bins_count > 0 {
            base += 100.0;
        }
        score += base;
    }

    // Late in the stream: consolidate, avoid spreading across bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_f * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportionally to how well item fills the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize large post-residuals that are hard to reuse (dead space),
    // especially when they fall in the awkward mid-range (1..=15 too small for most).
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 20.0 {
        score += 25.0 * (1.0 - pr / 20.0);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 20.0 * (nxt / pr.max(1.0));
            if (pr - nxt).abs() < 3.0 {
                score -= 15.0;
            }
        } else {
            // next item won't fit here; slight penalty for blocking
            score += 5.0 * (1.0 - pr / bin_capacity as f64);
        }
    }

    // Global pressure: when many bins are open relative to progress, prefer
    // consolidating into existing bins (penalize new-bin candidate).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as pressure and progress grow.
        score += 10.0 + 20.0 * progress + 2.0 * bin_pressure;
    } else {
        score -= 5.0 * progress;
    }

    // Prefer bins whose residual is close to the mean residual (keeps spread even).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Slight reward for using fuller bins first (best-fit style).
    score -= 10.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear dead-space penalty: small residuals are wasted capacity.
    score += 40.0 * (1.0 - norm_pr).powi(6) * (1.0 + progress);

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, prefer bins that leave residuals matching future needs.
    let quad = norm_pr * (1.0 - norm_pr); // peaks at norm_pr = 0.5
    score -= 30.0 * quad * (0.5 + progress);

    // Reward tight fits (item fills most of the bin).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill * fill;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Many open bins: discourage spreading; prefer filling existing ones.
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 5.0;

    // Lookahead: bonus if post_residual aligns with next item size.
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 15.0 * (-diff / 20.0).exp();
    }

    // New-bin candidate: keep it neutral-to-slightly-high so it's only chosen
    // when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls on nice
    // capacity fractions (cap/2, cap/3, cap/4) are more reusable.
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;

    if post_residual == 0 {
        score -= 60.0; // perfect fit, ideal
    } else if post_residual == half {
        score -= 40.0;
    } else if post_residual == third {
        score -= 30.0;
    } else if post_residual == quarter {
        score -= 20.0;
    }

    // Penalize tiny dead space (< smallest plausible item) more than large gaps.
    if post_residual < 10 {
        score += 25.0;
    }

    // Modulo-class reward: residuals divisible by common item increments (10s grid)
    if post_residual % 10 == 0 {
        score -= 8.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin (chained fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // next item won't fit here; residual likely becomes dead space
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < half {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): discourage unless current fit is bad
    // or many bins are open with low mean residual (fragmentation).
    if bin_residual == bin_capacity {
        score = cap_f * 0.9;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
        if open_bins_count > 0 && mean_residual < (item_size as f64) {
            score -= 20.0; // fragmentation: fresh bin attractive
        }
    }

    // Late-stream consolidation: prefer tightening existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the worst outcome.
    let dead_limit = 9.0f64.min(next_item_size as f64);
    if (post_residual as f64) < dead_limit && post_residual > 0 {
        score += 60.0 * (dead_limit - post_residual as f64);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits relative to capacity.
    let tightness = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, allow new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (10.0 + 20.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: accept only if current fit is bad and pressure is low.
        score += 25.0 + 15.0 * pressure;
        if (post_residual as f64) < dead_limit || post_residual == 0 {
            score -= 35.0;
        }
    } else {
        score += 8.0 * pressure;
    }

    // Lookahead: favor leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Mean residual coupling: prefer bins near mean residual (balanced packing).
    score += 0.5 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect match of post_residual with next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.5 * diff;                       // penalize mismatch with next item
        if post_residual == next_item_size {
            score -= 60.0;                          // exact 2-step match: strong reward
        } else if post_residual >= next_item_size {
            score -= 5.0;                           // next item still fits here
        } else {
            score += 8.0;                           // dead space relative to next item
        }
        // scale lookahead by stream progress
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress * (1.0 - diff / bin_capacity as f64);
    } else {
        // last item: minimize residual as usual
        score += 0.0;
    }

    // Penalize deviation from mean residual (avoid wasting well-packed bins)
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: mild penalty so it only wins on genuinely poor fits
    if bin_residual == bin_capacity {
        score += 15.0;
        // open a new bin if current best fit would leave large unusable residue
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score -= 20.0;
        }
    }

    // slight preference for tighter fits overall
    score += 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize small post-residuals that are too small for typical future items
    // (dead space below the minimum item size is pure waste).
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        // Post-residual cannot fit the known next item: dead space penalty,
        // but softened if next item is small anyway.
        score += 8.0 * (1.0 - (next_item_size as f64 / 100.0));
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can also host the lookahead item.
        score -= 6.0 * (next_item_size as f64 / post_residual as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let global_tight = (mean_residual / bin_capacity as f64).max(0.0).min(1.0);
        // Open new bin when open bins are crowded or few fit; penalize otherwise.
        score += 45.0 * (1.0 - pressure) * (1.0 - global_tight) - 20.0 * pressure;
        // Late in the stream, prefer consolidating into open bins.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * t;
    }

    // Prefer filling bins with larger residuals when many bins are open (bin reduction).
    if open_bins_count > 3 {
        score += 0.3 * (bin_residual as f64 - mean_residual);
    }

    // Slight time-dependent preference for exact fills as stream progresses.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual == 0 {
        score -= 20.0 * (0.5 + 0.5 * t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 + 0.8 * progress) + 0.35 * pr_norm * (1.0 - progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    let mut score = pr + 30.0 * poly;

    // Penalize waste relative to mean residual across open bins
    score += 0.25 * (pr - mean_residual).abs();

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward leaving space compatible with next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (1.0 - ((pr - nx) / cap).powf(2.0));
        } else {
            score += 6.0;
        }
    }

    // Mild penalty for proliferating open bins early
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class boundaries: dead-space classes of size 10 (item granularity).
    let class = post_residual / 10; // 0..=10
    // Reward placements leaving residuals that are "harmonic" with common sizes.
    // Residuals divisible by 10 are more reusable.
    if post_residual % 10 == 0 {
        score -= 4.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 12.0;
    }
    // Penalize tiny unusable residuals (< 10): dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    // Non-linear penalty on mid-range dead classes (hard to fill later).
    score += 0.4 * (class as f64).sin().abs() * 2.0;

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 10.0;
        } else if next_item_size < post_residual {
            score -= 3.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // Next item won't fit here; penalize proportionally to wasted harmony.
            score += 2.0 * ((next_item_size - post_residual) as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Prefer fuller bins relative to the mean residual of open bins.
    if (bin_residual as f64) > mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    // New-bin candidate: make it unattractive unless all open bins are poor fits
    // (i.e., few fitting bins) or the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 6.0 + 0.1 * open_bins_count as f64 };
        score += pressure;
        // Slight progress-based discount: late in stream, reusing bins matters more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 3.0 * (1.0 - progress);
    }

    // Mild tie-breaker favoring bins with residual close to item (tight fit).
    score += 0.05 * ((bin_residual - item_size) as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - pr) * 12.0; // dead space zone penalty
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Reward tight fits relative to residual (high fill ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 8.0;

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item can't use the leftover: mild penalty
        score += 3.0;
    }

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Pressure against proliferation of open bins: new bins cost more when many are open.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0;
        // but opening a fresh bin is fine if current leftovers are all dead space
        if mean_residual < 10.0 {
            score -= 20.0;
        }
        // early stream: allow more bins to build capacity diversity
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 10.0;
        }
    }

    // Prefer bins with residual below mean (consolidate small leftovers).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight but usable fits: reward small residuals, but only mildly,
    // so that a perfect fit elsewhere still wins.
    score -= 20.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Aggressive 2-step lookahead: if the NEXT item fits exactly into
    // the post-residual, this is a chain perfect-fit -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }
    // Next item fits with small slack -> moderate reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / (bin_capacity as f64));
    }
    // Post-residual too small for the next item: penalize dead space,
    // scaled by how close the next item came to fitting.
    if next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        score += 15.0 * (1.0 - miss / 80.0).max(0.0);
    }

    // Relative-to-mean coupling: bins with residual already below the
    // mean are "dense" bins; filling them further is efficient.
    let dense = (mean_residual - post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * dense.max(-1.0).min(1.0);

    // Last-chance bin: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // New-bin candidate (empty bin): only attractive when the fit is
    // poor (large post_residual waste) or no real alternative exists.
    if bin_residual == bin_capacity {
        score += 60.0; // default penalty: prefer existing bins
        if fitting_bins_count == 1 {
            score += 150.0; // opening a new bin beats squeezing nothing? no:
            // actually the single fitting bin IS this empty bin case only
            // when no other bin fits; keep penalty moderate so a fresh
            // bin is chosen rather than an oversized gap elsewhere.
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // An empty bin can host the next item too; slight relief.
            score -= 10.0;
        }
    }

    // Stream progression: late in the stream, be more conservative with
    // opening bins (favor compacting into existing ones).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 80.0 * progress;
    } else {
        score -= 20.0 * progress;
    }

    // Too many open bins: discourage spreading items thin.
    if open_bins_count > 8 {
        score += 2.0 * (open_bins_count as f64 - 8.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual quadratically.
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / cap;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize stranding near-miss residuals.
        score += 0.25 * (next_item_size as f64 - post_residual as f64).min(20.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins with residuals below the mean (compact bins first).
    score += 0.5 * ((bin_residual as f64) - mean_residual);

    // Prefer fuller bins (small residual) generally.
    score += 0.2 * (bin_residual as f64);

    // Penalize opening new bins as stream progresses / many bins open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 + 20.0 * progress + 1.5 * open_bins_count as f64;
        // But allow a new bin if no open bin fits well.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap;

    // Base: waste potential of post residual, weighted by stream progress
    let mut score = post;

    // Non-linear polynomial coupling: late in stream, dead space hurts more
    let waste_penalty = pr * pr * (1.0 - pr) * (1.0 + progress * 40.0);
    score += waste_penalty * cap;

    // Reward tight fits via smooth cubic of fill fraction
    let fill = 1.0 - pr;
    score -= fill * fill * fill * 12.0;

    // Last-chance bonus: smooth escalation when few fitting bins
    let scarcity = 1.0 / (fitting_bins_count as f64);
    score -= scarcity * 8.0 * (0.5 + progress);

    // Lookahead coupling: if next item fits exactly in post residual, reward strongly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post - nxt) / cap;
        let match_bonus = (-diff * diff * 30.0).exp();
        score -= match_bonus * 10.0;
        // Penalize post residual too small for next item (dead-end)
        if post < nxt {
            score += (nxt - post) * 0.15;
        }
    }

    // Mild penalty for opening new bins when many open bins have slack
    if bin_residual == bin_capacity {
        score += 3.0 + mean_residual * 0.1 + open_bins_count as f64 * 0.5;
    } else {
        score -= 2.0;
    }

    // Mean residual deviation coupling: prefer bins close to mean (balanced packing)
    let dev = (post - mean_residual).abs() / cap;
    score += dev * dev * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near 0 (tight fit) are good,
    // residues near 50 (half-capacity leftovers) are worst (dead space).
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    let pr = post_residual as i64;
    let cap = bin_capacity as i64;

    // Distance to nearest "harmonic" class boundary: 0, quarter, half
    let d0 = (pr).abs();
    let dq = (pr - quarter as i64).abs();
    let dh = (pr - half as i64).abs();
    let dmin = d0.min(dq).min(dh) as f64;
    score += dmin * 0.35; // penalize residuals far from harmonic classes

    // Reward exact/near-zero residuals strongly (bin closed).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Penalize the "half-dead" class: residuals in [40, 60] are hard to fill
    // for items 1..100 (mid-range leftovers).
    if post_residual >= 40 && post_residual <= 60 {
        score += 15.0;
    }

    // Lookahead: does next item fit exactly into the post-residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score += 3.0; // mild penalty: keep slack for next item, but don't hoard
        }
        // If next item cannot fit here, slight bonus for tight packing now.
        if next_item_size > post_residual && post_residual < 10 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly unless current residuals are all tight.
    if bin_residual == bin_capacity {
        let avg_tightness = mean_residual / bin_capacity as f64;
        // open new bin if mean residual across open bins is small (bins nearly full)
        score = 45.0 + avg_tightness * 30.0;
        if post_residual == bin_capacity as u32 {
            // empty new bin: score relative to how full the stream is
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += progress * 5.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open
        }
    }

    // Integer-division threshold coupling: post_residual / 10 class
    let class = post_residual / 10;
    score += (class as f64) * 0.8;

    // Small preference for using more open bins when many are already open
    // (avoid fragmentation): penalize new bins proportionally.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is too small for the smallest plausible item (1..100, so gap==0 is perfect).
    if post_residual > 0 {
        // Non-linear dead-space penalty: quadratic blow-up for tiny nonzero gaps.
        let dead = (post_residual as f64).powi(2) / 100.0;
        score += dead;

        // If the gap cannot even hold the lookahead item, it is likely wasted.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 15.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Reward tight fits strongly.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: prefer spreading across fewer bins when many are open,
    // but allow opening new bins when existing ones would create dead space.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * open_pressure;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mean residual coupling: bins far below mean residual are underfilled; penalize
    // placing into them unless it is a tight fit (encourages balanced residual usage).
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    // Mild time progression: as stream advances, favor consolidation into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (1.0 - fill_ratio);

    // New-bin candidate (bin_residual == bin_capacity): penalize slightly so that
    // opening a new bin only wins when all open bins would create real dead space.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.3 * open_bins_count as f64;
        // But if no open bin fits well (would leave a tiny gap), the dead-space
        // penalties above already raised their scores; relax the new-bin penalty
        // when the item is large relative to capacity.
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

