    // New-bin candidate handling: opening a bin is penalized unless existing bins are poor fits
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = if fitting_bins_count == 0 { 0.0 } else {
            60.0 * (1.0 - tightness) * (1.0 + mean_residual / bin_capacity as f64)
        };
        score += 55.0 + 40.0 * progress + pressure;
        // fewer fitting bins -> new bin more acceptable
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
    }

    // Prefer consolidating into fewer bins when many are open
    score += (open_bins_count as f64) * 0.5 * (bin_residual as f64 / bin_capacity as f64);

    // Mild preference for bins with residual above mean (balance)
    score += 0.1 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
