    }

    // New-bin candidate handling: an empty bin is a fresh resource. Only make
    // it attractive when no open bin fits well (large residual gap vs item).
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 {
            0.0
        } else {
            let best_gap = (bin_residual - item_size) as f64;
            (best_gap / bin_capacity as f64) * 30.0
        };
        score += 10.0 + open_bins_count as f64 * 2.0 + desperation;
    }

    // Lookahead: if the next item exactly matches this placement's residual,
    // reward creating that chain fit.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 18.0;
    }
    // Penalize if next item cannot use the created residual (dead end ahead).
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
    }

    // Late in the stream, waste hurts more: scale dead-space penalty up.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * 0.15 * progress;

    // Mild preference for bins below mean residual (balance the load so
    // no bin becomes a straggler with stranded space).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/tight matches with next item
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_gap = post_residual - next_item_size;
        // Reward tight chain: next item leaves small leftover
        score -= 12.0 * (1.0 - fit_gap as f64 / bin_capacity as f64);
        // Extra reward for near-perfect two-item packing
        if fit_gap <= 5 {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot follow here: penalize proportionally to wasted potential
        let unusable = (next_item_size.min(post_residual)) as f64;
        score += 4.0 * (1.0 - unusable / bin_capacity as f64);
    }

    // Penalize post_residual that is small but unusable (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Reward closing bins tightly (post_residual near zero)
    if post_residual == 0 {
        score -= 15.0;
    }

    // Relative-to-mean coupling: prefer bins with residuals below mean (denser bins)
    score += 0.5 * ((bin_residual as f64) - mean_residual);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: mild penalty so we only open when fits are poor
    if bin_residual == bin_capacity {
        score += 8.0 + 0.3 * item_size as f64;
        // But if no tight lookahead fit exists anywhere, new bin becomes attractive
        if next_item_size == 0 || next_item_size > post_residual {
            score -= 5.0;
        }
    }

    // Late-stream consolidation: prefer fewer open bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: squared penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 60.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward using bins whose residual is close to the item (good fit ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= (fit_ratio - 1.0).abs() * 20.0;

    // Lookahead: penalize leaving residual that fits next item poorly (dead space),
    // reward residual that pairs with next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 12.0; // next item can still go here
        } else {
            score += 8.0; // next item can't use this residual
        }
    }

    // Last-chance bin: strongly favor placing into the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 55.0 + 0.35 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        }
        // Early stream: allow more bins to build diversity.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
    }

    // Global state: prefer bins below mean residual (more roomy bins get filled first,
    // preserving tight bins... inverse: prefer bins near mean to keep balance).
    score += (bin_residual as f64 - mean_residual).abs() * 0.25;

    // Prefer filling fuller bins (smaller residual) to consolidate.
    score += bin_residual as f64 * 0.15;

    // Late stream: consolidate harder, avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 40.0;
    } else {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: prefer small post-residual, with non-linear (quartic) sharpening
    let mut score = pr * (1.0 + 2.5 * fit_norm * fit_norm * fit_norm);

    // Smooth stream-progress coupling: later in the stream, tighten residual preference
    let tighten = 0.5 + 1.5 * progress * progress;
    score *= tighten;

    // Penalize residuals that cannot plausibly host a future item (smooth barrier)
    let dead_zone = (1.0 - fit_norm).powi(3);
    score += 12.0 * dead_zone * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Lookahead coupling: reward leaving room for the next item (smooth kernel)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (pr - ns).abs();
        score += 0.35 * gap * gap / cap;
        // exact lookahead fit is very attractive
        if pr >= ns {
            score -= 3.0 * (1.0 - (pr - ns) / cap);
        }
    }

    // Mild penalty for spreading across many open bins when mean residual is high
    score += 0.02 * open_bins_count as f64 * (mean_residual / cap);

    // New-bin candidate handling: make an empty bin mildly unattractive unless
    // no good fit exists (post_residual of a new bin == capacity)
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        score += 10.0 * (1.0 - scarcity) + 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes of post_residual: exact fits and near-perfect fills are gold.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Dead-space classes: residuals that few item sizes can ever reuse (items 1..100,
    // but practically 10..80) are penalized quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += 150.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 40.0;
    }

    // Integer-division threshold classes on post_residual (capacity fractions).
    let q = post_residual / (bin_capacity / 4);
    score += q as f64 * 15.0;

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // bonus scaled by how snugly the next item fits
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 60.0 + 40.0 * snug;
        } else {
            score += 30.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // (mean residual small) or this is the brand-new empty bin with no real competition.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = mean_residual / bin_capacity as f64;
        // Penalize opening a new bin; the penalty shrinks if existing residuals are tiny.
        score += 400.0 - 300.0 * (1.0 - crowding) - 50.0 * progress;
        // If nothing else fits (fitting_bins_count==0 counts only this new bin), make it cheap.
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    } else {
        // Mild preference to keep bins balanced: avoid dumping into the emptiest bin
        // when many bins are open and mean residual is low.
        if (bin_residual as f64) > mean_residual * 1.5 && open_bins_count > 2 {
            score += 20.0;
        }
    }

    // Modulo harmonic bonus: post_residual in "nice" classes (multiples of 10)
    // are more reusable by typical item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (post_residual < 10 is likely dead).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward exact / tight fits.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward bins whose residual is close to item size (good fill ratio).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio;

    // Lookahead: bonus if post_residual can host the next item exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_tightness = next_item_size as f64 / post_residual as f64;
        score -= 15.0 * next_tightness;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to next item.
        score += 8.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when many bins are open
    // or other bins fit; relax penalty when this is a last-chance situation.
    if bin_residual == bin_capacity {
        let base_penalty = 25.0;
        let pressure = (open_bins_count as f64) * 1.5;
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { (fitting_bins_count as f64) * 6.0 };
        score += base_penalty + pressure + scarcity;
        // Toward stream end, prefer reusing open bins even more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mild preference for bins below mean residual (consolidate space).
    score -= 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: post_residual exactly matches the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Next item fits comfortably in the leftover space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (post_residual - next_item_size) as f64 * 0.25;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that cannot host the next item: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Prefer bins whose residual is already below average (consolidating waste).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 * 2.0 + progress * 10.0;
        score += 15.0 + pressure;
        // But allow a new bin if this item is huge and would leave near-zero slack anyway.
        if item_size >= bin_capacity * 9 / 10 {
            score -= 10.0;
        }
    }

    // Mild bonus for very tight placements overall.
    if post_residual <= 5 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared waste penalty grows fast for large dead space.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Exact fit is excellent.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last chance: strongly favor using this bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: discourage spreading, prefer filling existing bins.
    let crowding = open_bins_count as f64;
    score += crowding * 0.35;

    // Mean residual coupling: if mean residual is small, protect remaining space.
    if mean_residual < item_size as f64 {
        score += 8.0;
    } else {
        score -= 3.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement;
    // if next item is large and would not fit, penalize slightly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size > post_residual {
            score += (next_item_size as f64 - post_residual as f64) * 0.15;
        }
    }

    // Time horizon: early in the stream, be more liberal about opening bins
    // (structure now pays off later); late in the stream, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening new bins, more so late in the stream.
        score += 30.0 + progress * 60.0;
        // But if the item is huge and fits nothing well, allow it.
        if item_size >= 70 {
            score -= 20.0;
        }
    } else {
        // Early stream: slightly favor using existing bins less to build structure.
        score -= (1.0 - progress) * 4.0;
    }

    // Small post-residual is good dead space (<10 unusable anyway).
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: prefer tight fits, with a non-linear (quadratic + cubic) shaping of post-residual
    let mut score = pr + 40.0 * pr_norm * pr_norm + 25.0 * pr_norm * pr_norm * pr_norm;

    // Stream-progress coupling: as the stream advances, penalize larger residuals more strongly
    // (late in the stream, dead space is less likely to be filled).
    let late = progress * progress;
    score += 60.0 * late * pr_norm;

    // Lookahead coupling: reward residual that can still accommodate the next item,
    // penalize residual just barely too small (unusable dead space).
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let diff = pr - nxt;
        if diff >= 0.0 {
            // residual can fit next item: reward smoothly, more so early in the stream
            score -= 12.0 * (1.0 - progress) * (1.0 - (diff / cap).min(1.0));
        } else {
            // just-miss penalty: cubic falloff on how close the miss is
            let miss = (-diff / cap).min(1.0);
            score += 18.0 * (1.0 - miss) * (1.0 - miss) * (1.0 - miss);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mean-residual coupling: if this bin's residual deviates from the mean,
    // slightly prefer bins that keep the residual distribution balanced.
    let bin_res = bin_residual as f64;
    let dev = (bin_res - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Many open bins: mild pressure to consolidate into existing bins
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions
    let post = post_residual as f64;
    let q = post_residual / 10; // decade class

    // Reward residuals that are "harmonically clean" (divisible classes)
    if post_residual % 10 == 0 {
        score -= 3.0;
    }
    if post_residual % 20 == 0 {
        score -= 2.0;
    }
    if post_residual % 25 == 0 {
        score -= 1.5;
    }
    if post_residual % 50 == 0 {
        score -= 2.0;
    }

    // Penalize dead space: residuals too small for the smallest plausible item (1..100, min 1 here)
    // but especially below common item sizes; treat small nonzero residuals as waste
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    } else if post_residual < 20 {
        score += 2.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: reward residuals that harmonically pair with next item size
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 2.0;
            if slack % 10 == 0 {
                score -= 2.0;
            }
            if slack == 0 {
                score -= 8.0;
            }
        } else {
            // next item cannot fit here; residual likely becomes dead space
            score += post / cap * 8.0;
        }
    } else {
        // last item: prefer tightest fit overall (post_residual already does this)
        score -= 1.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin should only win when fits are bad
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin: capacity worth of unused space potential
        score = cap * 0.75;
        if fitting_bins_count == 0 {
            score -= 20.0; // must open a bin
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // many open bins with high mean residual -> use them instead
        score += open_bins_count as f64 * 0.5 + mean_residual * 0.1;
    }

    // Mild pressure to fill bins deeply when few bins fit the item
    score += (fitting_bins_count as f64).min(10.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Small-but-usable gaps are also risky; scale penalty by gap size.
    else if post_residual < 20 {
        score += 12.0 + (20 - post_residual) as f64;
    }

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits proportional to fill ratio.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill * fill;

    // Open-bin pressure: discourage spreading across many bins when the
    // fit is mediocre; encourage using existing bins as open_bins_count grows.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 15.0;

    // Lookahead: favor bins whose leftover could host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
        // Extra bonus if leftover is close to the next item (good chaining).
        let gap = (post_residual - next_item_size) as f64;
        if gap < 10.0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Leftover can't host next item: mild penalty proportional to waste.
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: prefer opening a fresh bin only when no open bin
    // offers a good fit (post_residual small) — otherwise penalize it.
    if bin_residual == bin_capacity {
        if post_residual as f64 > mean_residual * 0.6 {
            score += 30.0 + pressure * 10.0;
        } else {
            score -= 5.0;
        }
    }

    // Slight drift: later in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

