    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if next_item_size as u32 == post_residual {
            score -= 60.0; // perfect chaining: next item fills this bin completely
        } else if next_item_size as u32 <= post_residual {
            score -= 25.0 * (1.0 - gap / bin_capacity as f64); // next item also fits here
        } else {
            // next item won't fit in this bin's remainder; penalize stranded space
            score += 10.0 * tightness;
        }
    }

    // Compare against mean residual: prefer bins whose leftover stays near/below mean
    // (avoid leaving one huge hole while others stay usable).
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: if this is the only bin that fits, using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when a reasonable fit exists in an open bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 / (1.0 + progress);
        score += 15.0 + 2.0 * pressure;
        // New bin is attractive only if no open bin fits well (large item, few fitting bins)
        if fitting_bins_count == 0 && item_size as f64 > 0.5 * bin_capacity as f64 {
            score -= 35.0;
        }
    }

    // Slight preference for filling bins that are already mostly full (consolidation).
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post residual, relative to capacity)
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Perfect fit gets a big bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize dead space that no future item can use (items >= 1, so any residual is usable,
    // but very small residuals are practically dead)
    if post_residual > 0 && post_residual < 5 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post residual can fit the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Penalize leaving a residual that wastes the next item's placement options
            score += 4.0;
        }
        // If this bin's current residual fits next item but post wouldn't, mild penalty
        if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 3.0;
        }
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly
    if bin_residual == bin_capacity {
        let base = 35.0;
        let pressure = if fitting_bins_count == 0 { 0.0 } else {
            (open_bins_count as f64).ln_1p() * 2.0
        };
        // Opening a bin early in the stream is fine; late in the stream prefer consolidation
        let time_factor = (step_index as f64) / (total_items.max(1) as f64);
        score = base + pressure + 20.0 * time_factor;

        // If the best alternative is bad (no bin fits), new bin is necessary
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure)
    score -= (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Slight preference to spread when mean residual is high and few bins open
    if open_bins_count <= 2 {
        score += 2.0;
    }

    // Penalize bins far from mean residual (fragmentation signal)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: post-residual with smooth non-linear shaping (waste penalty grows superlinearly)
    let mut score = pr + 40.0 * pr_norm * pr_norm;

    // Stream-progress coupling: early on, prefer tight packing (low residual);
    // later, tolerate residuals less (amplify waste penalty smoothly).
    let coupling = 1.0 + 2.0 * progress * progress;
    score *= coupling;

    // Smooth interaction between residual and mean residual: bins with residual
    // far above mean are less attractive unless residual is small.
    let dev = (pr - mean_residual) / cap;
    score += 25.0 * dev * dev.abs() * (1.0 - pr_norm);

    // Lookahead: reward bins whose post-residual can still fit the next item,
    // penalize bins that would strand dead space relative to next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - pr_norm);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to use the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln_1p();
    }

    // New-bin candidate: mildly discourage opening new bins early, allow later.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 1.5 * open_bins_count as f64;
    }

    // Small smooth crowding term
    score += 0.3 * (open_bins_count as f64).ln_1p();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Class index: 16 harmonic classes of residual space.
    let class = (frac * 16.0).floor().min(15.0) as f64;

    // Perfect fits are golden: zero out score entirely.
    if post_residual == 0 {
        return -1000.0;
    }

    // Penalize residuals that no plausible future item can use.
    // Items are 1..100; residual < smallest plausible item (~10) is dead space.
    if post_residual < 10 {
        score += 50.0;
    }

    // Coupling with lookahead: does next_item_size fit exactly or near-exactly?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0; // perfect lookahead fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // harmonic class match: next item leaves residual in same class
            let next_class = ((post_residual - next_item_size) as f64 / cap * 16.0).floor().min(15.0);
            score -= 80.0 - slack * 0.5 - (class - next_class).abs() * 2.0;
        } else {
            // next item won't fit here: mild penalty scaled by how much it overshoots
            score += ((next_item_size - post_residual) as f64) * 0.3;
        }
    }

    // Integer-division thresholds on post_residual (harmonic bands).
    let band = post_residual / 10; // 0..10 bands
    score += (band as f64) * 3.0;

    // Reward tight fits: small post residual relative to item size.
    score -= (item_size as f64 / cap) * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer bins where this item is a better fraction of residual
        score += (bin_residual as f64 - item_size as f64) * 0.1;
    }

    // New-bin candidate: neutral-ish baseline, penalized slightly so we only
    // open a new bin when existing fits are truly bad.
    if bin_residual == bin_capacity {
        score = cap * 0.5 + mean_residual * 0.2 - 40.0;
        // If nothing fits well (large residuals elsewhere), opening fresh is fine.
        if mean_residual < 25.0 {
            score -= 30.0;
        }
    }

    // Stream progression: early on, be pickier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * (1.0 - progress);

    // Small tie-breaker using open bin count: fewer bins, more pressure to fill.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 5.0;
    }

    // Reward tight fits: low post_residual relative to item size.
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score -= tightness.recip() * 4.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Dead space relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize leaving a gap that the next item nearly fits but misses.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open bins pressure: discourage spreading across many open bins when alternatives exist.
    if bin_residual != bin_capacity {
        score += open_bins_count as f64 * 0.5;
    } else {
        // New-bin candidate: slightly penalize unless current bins are crowded.
        score += 5.0;
        if open_bins_count as f64 > mean_residual / 10.0 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Late in the stream: prefer compacting into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Aggressive 2-step lookahead: reward exact match of post_residual to next item ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect 2-step fit: strongly reward
        if post_residual as u32 == next_item_size {
            score -= 60.0 + 20.0 * (1.0 - progress);
        } else if diff <= 5.0 {
            score -= 30.0 - 3.0 * diff;
        } else {
            // Penalize post_residual that is too small for next item (dead space)
            score += 0.35 * diff;
        }
        // If next item fits in post_residual, mild reward for keeping bin usable
        if post_residual >= next_item_size && post_residual as u32 != next_item_size {
            score -= 8.0;
        }
    }

    // --- Dead-space penalty: small unusable residuals are bad ---
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // --- Perfect closure: item exactly fills the bin ---
    if post_residual == 0 {
        score -= 45.0;
    }

    // --- Relative to mean residual: prefer bins with below-average residual (tighter bins) ---
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // --- Last-chance bin: if this is the only fitting bin, strongly favor using it ---
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Among multiple candidates, prefer tighter fit
        score += 0.15 * (fitting_bins_count as f64 - 1.0);
    }

    // --- New-bin candidate handling: empty bin should only win when fits are poor ---
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; cheaper early, more expensive later
        let open_cost = 35.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
        score += open_cost;
        // But a new bin is attractive if the item is large and would leave awkward gaps elsewhere
        let gap = (bin_capacity - item_size) as f64;
        if gap < 15.0 {
            score -= 25.0; // large item nearly fills a fresh bin
        }
        if next_item_size > 0 && gap > 0.0 && (gap - next_item_size as f64).abs() < 5.0 {
            score -= 15.0; // fresh bin anticipates next item too
        }
    }

    // --- Late stream: consolidate, avoid opening bins ---
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer placements that leave little waste.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tight * tight;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward if next item can fit into the post-residual (chaining),
    // penalize if post-residual is a dead space the next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0 + 3.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Dead space: small unusable leftovers are worst.
            let dead = post_residual as f64 / bin_capacity as f64;
            score += 5.0 * dead;
            // If next item fits current residual but not post, keeping this bin is fine anyway.
        }
        // If next item is large, prefer conserving roomy bins.
        if next_item_size > 50 && post_residual < next_item_size && bin_residual >= next_item_size {
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: be picky, penalize loose fits.
        score += 1.5 * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: penalize opening a new bin unless it's genuinely needed
    // (no good fits exist, or item is large and would leave a useful residual).
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 8.0 + 4.0 * (fitting_bins_count as f64).ln() };
        score += pressure;
        // Early in the stream, be more willing to open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 3.0 * (1.0 - progress);
        // Opening a bin for a large item is reasonable.
        score -= 0.06 * item_size as f64;
    }

    // Global residual balance: if mean residual is high, prefer filling fuller bins
    // (large placements into low-residual bins) to consolidate.
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / bin_capacity as f64;
        if rel < mean_residual / bin_capacity as f64 {
            score -= 2.0; // this bin is fuller than average -> good target
        } else {
            score += 1.0;
        }
    }

    // Mild penalty for spreading across many open bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 4 && progress > 0.5 {
        score += 0.3 * (open_bins_count as f64).ln() * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear coupling of post_residual with stream progress:
    // early on, prefer tight fills less aggressively; later, penalize wasted residual strongly.
    let norm_post = post / cap;
    let poly = norm_post * norm_post * (1.0 + 2.0 * progress);
    score += poly * cap * 0.8;

    // Reward tight fits (small post_residual) with smooth exponential bonus.
    score -= (1.0 - norm_post).powi(3) * (1.0 + progress) * 12.0;

    // Penalize leaving residual that is too small for typical future items (dead space).
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 1.5;
    }

    // Lookahead: reward bins whose post_residual fits the next item well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        let match_bonus = (1.0 - diff / cap).max(0.0);
        score -= match_bonus * 8.0 * (1.0 - progress * 0.5);
        // Penalize post_residual slightly larger than next item (unusable sliver).
        if post >= nxt && post - nxt < 5.0 {
            score += 6.0;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Many open bins: prefer consolidating into bins with low residual.
    let mean_gap = (mean_residual - post) / cap;
    score -= mean_gap * 5.0;

    // New-bin candidate: make empty bin mildly unattractive unless residuals are fragmented.
    if bin_residual == bin_capacity {
        score += 10.0 - 6.0 * (open_bins_count as f64 / (1.0 + open_bins_count as f64));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by common item
    // sizes are more reusable, so reward them.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let mut reuse_bonus = 0.0;
    for d in [10u32, 20, 25, 50] {
        if pr % d == 0 && pr > 0 {
            reuse_bonus += 12.0;
        }
    }
    score -= reuse_bonus;

    // Penalize dead space that is too small to hold even the smallest item.
    if pr > 0 && pr < 10 {
        score += 60.0;
    }

    // Penalize medium-dead space that next_item_size cannot use.
    if next_item_size > 0 && pr > 0 && pr < next_item_size {
        score += 0.35 * (next_item_size - pr) as f64;
    }
    // Reward when the next item exactly fills the post residual.
    if next_item_size == pr && pr > 0 {
        score -= 45.0;
    }
    // Reward when next item fits into post residual (chain packing).
    if next_item_size > 0 && next_item_size <= pr {
        score -= 18.0;
    }

    // Harmonic fraction: how much of the bin this placement consumes.
    let fill_frac = item_size as f64 / cap;
    score -= 25.0 * fill_frac;

    // Tight fits (post residual is a small harmonic fraction of capacity).
    if pr > 0 && pr <= bin_capacity / 10 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer bins whose residual is below the mean residual (denser bins first).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // New-bin candidate: only attractive when nothing fits well or stream is early.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        let poor_fit = fitting_bins_count == 0
            || (post_residual as f64 > 0.5 * cap && fitting_bins_count <= 1);
        if poor_fit || open_bins_count == 0 {
            score -= 55.0;
        } else {
            // Keep new bins unattractive when decent fits exist; slight decay late.
            score += 45.0 - 20.0 * progress + 0.5 * open_pressure;
        }
    }

    // Mild tie-break: prefer opening/using fewer bins overall.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 6.0 * post_residual as f64;
    }

    // Reward near-perfect fits (small post_residual that is still usable).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual >= 10 {
        // Mild reward proportional to how much of the residual was consumed.
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= 25.0 * fill_ratio;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
        if post_residual - next_item_size < 10 {
            score -= 15.0;
        }
    }
    // If next item cannot fit in post residual, penalize slightly (dead end for chain).
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin when other bins fit,
    // scaled by open-bin pressure (more open bins => stronger push to reuse).
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 40.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score -= (mean_residual - post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), scaled.
    score *= 1.0 + (item_size as f64 / bin_capacity as f64) * 0.5;

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // heavily reward this placement (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Reward proportional to how snugly the next item fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use the post residual; penalize large leftovers
            // that likely become dead space.
            score += (post_residual as f64 - bin_capacity as f64 * 0.5).max(0.0) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Compare residual against mean residual: bins with residual below mean
    // (already tight) are good targets; spreading waste is penalized.
    score += (mean_residual - bin_residual as f64) * 0.25;

    // Many open bins: encourage closing them out (fill existing bins tighter).
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate (empty bin): only attractive when no good fit exists,
    // i.e. item leaves a very awkward residual in every bin. Penalize default.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if item nearly fills a fresh bin, opening new is cheap.
        if item_size as f64 >= bin_capacity as f64 * 0.9 {
            score -= 45.0;
        }
        // Late in stream, fewer bins is better; discourage new bins slightly less.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    }

    // Discard tiny residuals as wasted: strong penalty for near-full leftovers.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly.
    let tight = post_residual as f64 / cap;
    score += 40.0 * tight * tight;

    // Strong reward for near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > 0 {
        // penalize leftovers that block the next item only slightly
        score += 4.0 * (1.0 - tight);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new empty bin, scaled by how many bins are open
    // and how much slack already exists globally.
    if bin_residual == bin_capacity {
        score += 35.0 + 2.0 * open_bins_count as f64 + mean_residual * 0.5;
        // Early in the stream, new bins are cheaper; late, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        // Favor bins with residual close to mean (balanced packing),
        // penalize outliers that hoard space.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.3 * dev;
    }

    // Mild bonus for using fuller bins overall.
    score -= 0.4 * (bin_residual as f64 / cap) * (bin_residual as f64 / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with quadratic dead-space penalty.
    let mut score = post + (post * post) / (2.0 * cap);

    // Non-linear coupling: dead space is more costly as the stream progresses.
    score += (post / cap) * (1.0 - progress) * 10.0;
    score -= (post / cap) * progress * 8.0;

    // Last-chance bonus: strongly reward using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - post / cap);
    }

    // New-bin candidate handling: only attractive when item barely fits elsewhere.
    if bin_residual == bin_capacity {
        // Mild penalty so existing bins are preferred unless fit is terrible.
        score += 15.0;
        score -= 10.0 * (item_size as f64 / cap);
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        if post >= nxt {
            score -= 20.0 * (1.0 - diff / cap) * (1.0 - progress * 0.5);
        } else {
            // Dead space that next item cannot use: penalize non-linearly.
            score += 8.0 * (diff / cap) * (0.5 + progress);
        }
    }

    // Mean-residual coupling: bins deviating below mean residual are better utilized.
    score += 0.15 * (mean_residual - bin_residual as f64).abs();

    // Slight preference to consolidate into fewer bins.
    score += 0.05 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;

    // Exact fit: strong reward (waste-free placement).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic classes: post_residual modulo 10 — small residue classes mean
    // near-tight fits; reward them proportionally.
    let m = (post_residual % 10) as f64;
    score -= (10.0 - m) * 0.6;

    // Dead-space penalty: residual too small for the lookahead item is
    // unusable; penalize the unusable gap non-linearly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64;
        score += dead * 1.5 + (dead * dead) / cap_f;
    }

    // Fractional capacity waste term: linear in wasted fraction of the bin.
    score += (post_f / cap_f) * 5.0;

    // New-bin candidate: brand-new empty bin has bin_residual == bin_capacity.
    // Bias slightly toward reusing open bins, but if this is the ONLY fitting
    // bin, opening a fresh bin preserves it for larger future items.
    if bin_residual == bin_capacity {
        score += 8.0;
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 15.0; // next item needs a fresh bin anyway
        }
    }

    // Mean-residual coupling: prefer bins whose post-residual stays near the
    // fleet mean (balanced packing); deviate mildly.
    score += (mean_residual - post_f) * 0.1;

    // Stream progression: as the stream advances, favor tighter consolidation.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= t * 3.0;

    // Many open bins: discourage leaving tiny unusable slivers behind.
    if open_bins_count > 4 && post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: punish small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 6.0 * post_residual as f64; // tiny gap => large penalty
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item if it fits exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual - next_item_size < 10 {
            score -= 25.0; // chain fit: post gap hosts next item almost fully
        } else {
            score -= 5.0;
        }
    }
    // Penalize placements that leave a gap the next item cannot use at all.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: attractive only when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.5);
        score = 15.0 + pressure * 3.0;
        if post_residual > 0 && post_residual < 10 {
            score += 20.0; // a fresh bin never creates a tiny dead gap for this item
        }
        if fitting_bins_count == 1 {
            score += 45.0; // override: still prefer the existing last-chance bin
        }
    }

    // Mild open-bin pressure: fewer bins favored early, consolidation later.
    score += open_bins_count as f64 * 0.5 * (step_index as f64 / total_items.max(1) as f64 + 0.5);

    // Slight preference for bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits (small post_residual is already low, amplify).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Aggressive 2-step lookahead: strongly reward bins whose residual after placement
    // matches the next item exactly or closely.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 45.0;
        } else if diff <= 5.0 {
            score -= 20.0;
        } else if diff <= 10.0 {
            score -= 8.0;
        } else {
            // Penalize leaving a residual that is too small for the next item
            // (dead space that cannot be reused immediately).
            if post_residual < next_item_size {
                score += 0.3 * (next_item_size - post_residual) as f64;
            }
        }
        // If next item fits this bin's residual anyway, mild bonus to keep chains tight.
        if next_item_size <= post_residual {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize bins far below mean residual (they are already "wasted"); prefer
    // consolidating into fuller bins.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Prefer bins with tight current residual (best-fit flavor) scaled by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.05 * (bin_residual as f64) * (0.5 + progress);

    // New-bin candidate: make it attractive only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Base penalty so open bins win when their post-fit is decent...
        score += 30.0;
        // ...but relax it late in the stream or when many bins are open and fragmented.
        score -= 5.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer placements that leave little waste.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio).powi(4);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: penalize leaving a residual that is awkwardly close to but
    // smaller than the next item (dead space), reward residuals that can host it.
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap >= 0.0 {
            // Next item fits: mild reward, scaled by how snugly it fits.
            score -= 8.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Dead space for the next item: penalize proportionally to the gap.
            score += 0.15 * (-gap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Among multiple candidates, mildly prefer bins with less residual left overall.
        score += 0.05 * (fitting_bins_count as f64);
    }

    // New-bin candidate logic: only open a new bin when the current item fits
    // poorly everywhere (large waste) or the stream is early with few bins.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize opening new bins by default...
        score += 20.0;
        // ...but relax the penalty when waste in this new bin would be small
        // relative to average residual state, or few bins fit the item.
        score -= 25.0 * (1.0 - waste / bin_capacity as f64);
        score -= 10.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Global state coupling: if mean residual across open bins is high,
    // encourage consolidating into existing bins (penalize spreading).
    score += 0.03 * mean_residual * (open_bins_count as f64).sqrt();

    // Prefer fuller bins over emptier ones when residuals tie.
    score += 0.05 * (bin_residual as f64 - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items as f64).max(1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted residual (dead space grows super-linearly).
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth stream-progress coupling: late in the stream, prefer tighter packs.
    let tightness = 1.0 + 2.0 * progress * progress;
    score *= tightness;

    // Reward filling bins well (low post_residual relative to item).
    let fill_ratio = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 25.0 * fill_ratio * fill_ratio;

    // Coupling with mean residual: prefer bins below mean residual (tighter than average).
    score += 0.15 * (mean_residual - pr).max(0.0);

    // Last-chance bonus: strongly favor the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward residual that can still host the next item.
    if next_item_size > 0 {
        if pr >= next_item_size as f64 {
            score -= 12.0 * (1.0 - progress);
        } else {
            score += 6.0 * (1.0 - (pr / (next_item_size as f64).max(1.0)));
        }
    }

    // Penalize opening a new bin when open bins could fit, unless it's early and bins are crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 45.0 + 30.0 * progress;
        if fitting_bins_count > 0 {
            score += 25.0;
        }
        // Early stream: opening bins is cheaper (more future items to fill them).
        score -= 40.0 * (1.0 - progress) * (1.0 - progress);
    }

    // Mild penalty for bin proliferation.
    score += 0.8 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Harmonic class of post_residual: penalize residuals that are "dead zones"
    // (too small for typical future items). Classes via integer division.
    let pr = post_residual;
    if pr > 0 {
        let class = pr / 10; // 0..=9 harmonic class
        // Residuals in low classes (1..=9) are mostly dead space unless near
        // the minimum item size; penalize moderately.
        if pr < 10 {
            score += 25.0; // unusable dead space
        } else if class <= 3 {
            score += 8.0; // only fits very small items
        } else if class <= 6 {
            score += 0.0;
        } else {
            score -= 5.0; // large residual, still flexible
        }
    } else {
        score -= 40.0; // perfect fit
    }

    // Lookahead: if next item fits into post_residual, reward this bin strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 20.0 + 15.0 * chain_fit;
    } else if next_item_size > 0 {
        // Next item won't chain here; penalize if post_residual is close but
        // insufficient (near-miss wastes potential).
        let gap = next_item_size.saturating_sub(post_residual);
        if gap <= 10 {
            score += 10.0;
        }
    }

    // Last chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: neutral baseline; open a new bin only when no open bin
    // offers a decent fit. Penalize opening new bins mildly, more so when many
    // bins are already open (encourage consolidation).
    if bin_residual == bin_capacity {
        score += 45.0;
        score += 2.0 * open_bins_count as f64;
        // If the item is small, prefer stuffing it somewhere rather than a fresh bin.
        if item_size <= 30 {
            score += 20.0;
        }
    }

    // Slight preference to use bins with residuals below the mean (drain
    // nearly-full bins first).
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 6.0 * (1.0 - res_f / mean_residual.max(1.0));
    } else {
        score += 3.0 * ((res_f - mean_residual) / bin_capacity as f64);
    }

    // Early in the stream, be a bit more liberal about opening bins to build
    // a portfolio; later, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress; // later: favor existing bins even more
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space: residuals too small for the smallest conceivable item (1) are fine,
    // but small-but-nonzero gaps that likely can't fit future items are dead space.
    // Since items are 1..100, treat post_residual in (0, 10) as unusable-ish dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward bins whose residual exactly matches item_size (tight fit).
    if bin_residual == item_size {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0; // next item cannot go here; gap likely wasted
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        // New-bin candidate base score.
        score += 15.0 + 2.0 * open_bins_count as f64;
        // If the item fits tightly in an existing bin elsewhere, new bin is bad;
        // but if item is large and mean residual is small, new bin may be needed.
        if item_size as f64 > mean_residual {
            score -= 20.0;
        }
        // Late in stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild preference for bins with residual close to mean (balanced packing).
    score -= 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to bin capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 * (next_item_size as f64) / (bin_capacity as f64);
        } else {
            // penalize post_residual that is dead space for the next item
            score += 8.0 * (post_residual as f64) / (bin_capacity as f64);
        }
    }

    // Penalize bins with residual far from the current mean residual (fragmentation)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bonus: this is the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are fragmented
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        score += 40.0 - 0.5 * open_f;
        // encourage opening a new bin late in the stream when mean residual is high
        if mean_residual > 45.0 {
            score -= 15.0;
        }
        // encourage new bin if next item is large and current bin would leave bad leftover
        if next_item_size > post_residual && post_residual < 40 && next_item_size > 0 {
            score -= 20.0;
        }
    }

    // Slight preference to fill earlier-opened bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 4.0 * tightness * tightness * (item_size as f64);

    // Penalize leaving awkward residuals that few future items (10..80 range) can use.
    if post_residual > 0 {
        let r = post_residual as f64;
        if r < 10.0 {
            score += 12.0; // tiny unusable sliver
        } else if r < 20.0 {
            score += 6.0 * (1.0 - r / 20.0);
        }
    }

    // New-bin candidate handling: opening a bin is expensive; only attractive
    // when the item fits poorly in all existing bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin.
        score += 25.0 + 2.0 * (open_bins_count as f64).sqrt();

        // If this is the only fitting option, opening a new bin is necessary.
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
        // Lookahead: if next item is large and would waste this fresh bin, dampen.
        if next_item_size > 0 && next_item_size >= post_residual {
            score += 8.0;
        }
    } else {
        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // Reward preserving large residuals elsewhere: prefer bins whose residual
        // is close to the item (leave big residuals untouched for big items).
        let waste_ratio = (bin_residual - item_size) as f64 / bin_residual as f64;
        score += 10.0 * waste_ratio * waste_ratio;

        // Lookahead synergy: if the post residual exactly accommodates the next item,
        // reward heavily (chaining perfect fits).
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 15.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 5.0; // post residual likely dead space
        }
    }

    // Global state: many open bins with high mean residual -> prefer consolidation
    // into existing bins rather than spreading.
    if mean_residual > 30.0 && open_bins_count > 3 && !is_new_bin {
        score -= 3.0 * (mean_residual / 100.0);
    }

    // Time horizon: late in the stream, avoid opening bins (less recovery time).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score += 20.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    // Mild deterministic tie-break favoring bins with residual close to item size.
    score += ((bin_residual as i64 - item_size as i64).abs() as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 12.0 * poly;

    // Penalize large wasted residual early, less late
    score -= 8.0 * (1.0 - progress) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Tight fits rewarded, superlinearly
    score -= 15.0 * fit_ratio * fit_ratio;

    // Lookahead: bonus if next item fits into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 10.0 * (1.0 - ((pr - nxt) / cap)) * (1.0 - progress);
        } else {
            score += 4.0 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Prefer bins with residual below mean residual (denser bins)
    score += 2.0 * ((pr as f64) - mean_residual) / cap;

    // New empty bin candidate: mild penalty so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 25.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into useful bands.
    // Residuals in [0,10] are near-perfect fits; [11,30] are "half-class";
    // [31,60] can host medium items; >60 is wasteful leftover.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit
    } else if pr <= 10 {
        score -= 20.0;
    } else if pr <= 30 {
        score -= 5.0;
    } else if pr <= 60 {
        score += 5.0;
    } else {
        score += 15.0;
    }

    // Modulo arithmetic: residuals that are multiples of common item sizes
    // (10, 20, 25, 50) are more likely to be exactly filled later.
    if pr % 10 == 0 { score -= 6.0; }
    if pr % 25 == 0 { score -= 3.0; }
    if pr % 50 == 0 && pr > 0 { score -= 4.0; }

    // Lookahead coupling: reward if next item fits the post residual exactly
    // or within a tight band; penalize if next item cannot use this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / 40.0).max(0.0);
        } else {
            // next item too big for this bin after placement: mild penalty
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid
    // opening a new bin for a poor fit.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Many fitting bins: prefer the tightest fit (already via post_residual),
    // but add mild pressure proportional to open bins to close bins early.
    score += open_bins_count as f64 * 0.3;

    // Prefer bins whose residual deviates favorably from the mean residual.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Stream progression: early on, be more willing to spread items
    // (open bins for future flexibility); late, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 3.0 - progress * 3.0;

    // New-bin candidate handling: an empty bin has large post_residual;
    // make it attractive only when the item is large or no tight option exists.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        // Large items start fresh bins cheaply; small items should reuse bins.
        score = 70.0 - 45.0 * fill_frac;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // big lookahead item benefits from fresh capacity
        }
        if fitting_bins_count == 1 {
            score += 25.0; // don't abandon the lone fitting bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (below min item size) are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 200.0 * (10 - post_residual) as f64; // unusable sliver => heavy penalty
    }
    // Mid-size dead space: gaps that can't fit the lookahead item are less useful.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 30.0;
    }
    // Reward perfect / near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Tightness bonus: fraction of bin consumed by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 50.0 * tightness;

    // Open-bin pressure: prefer existing bins when many are open, to consolidate.
    score += (open_bins_count as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: make it attractive only when current bin would be badly wasted.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; compare against wasted space of alternatives.
        score = 100.0 - 50.0 * tightness;
        if post_residual < 20 {
            score -= 20.0; // a fresh bin will soon be near-full too
        }
        if fitting_bins_count == 1 {
            score += 80.0; // don't abandon the last-chance bin
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin can serve the next item as well
        }
    }

    // Slight stream-progression term: later in stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
