pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect-fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize large dead space, especially when it can't hold the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64) < nx {
            // dead space that blocks lookahead item
            score += (nx - post_residual as f64) * 2.0;
        } else {
            // residual can host next item: reward
            score -= 5.0;
        }
        // if this bin could also fit the next item alongside, strong reward
        if post_residual >= next_item_size && bin_residual >= item_size + next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when existing fits are poor
    if bin_residual == bin_capacity {
        let tightness = if fitting_bins_count >= 1 {
            // how close is the best existing fit? approximate via mean residual
            (mean_residual - item_size as f64).abs()
        } else {
            100.0
        };
        // opening a bin is cheap early, expensive when many bins are open
        score = cap - item_size as f64 + 30.0
            + open_bins_count as f64 * 3.0
            - tightness * 0.5;
        // late in stream, prefer filling existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 25.0;
        // small next item can fill new bin later
        if next_item_size > 0 && next_item_size <= post_residual.max(0) as u32 {
            score -= 10.0;
        }
    } else {
        // reward tight fits relative to capacity
        score -= (item_size as f64 / cap) * 10.0;
        // penalize bins far below mean residual (fragmented state)
        if (bin_residual as f64 - mean_residual).abs() > cap * 0.5 {
            score += 5.0;
        }
    }

    // slight preference for bins whose residual after placement matches common sizes
    let pr = post_residual;
    if pr == 10 || pr == 20 || pr == 25 || pr == 50 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Base: quadratic waste coupling — dead space in mid-range is worst.
    let post_n = post / cap;
    score += 18.0 * post_n * (1.0 - post_n) * (1.0 - post_n);

    // Reward tight fits (small post_residual) super-linearly.
    score -= 25.0 * (1.0 - post_n).powi(4);

    // Stream progress: early on, keep bins flexible (penalize low residuals);
    // late in stream, tolerate tight packing.
    let flex = (1.0 - progress) * (1.0 - progress);
    score += 14.0 * flex * post_n;
    score -= 8.0 * progress * post_n * post_n;

    // Lookahead: if next item fits in post_residual, reward; else penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            score -= 10.0 * (nx / cap);
        } else {
            score += 6.0 * (1.0 - (post / nx).min(1.0));
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    // or many bins are open with high mean residual (fragmentation).
    if bin_residual == bin_capacity {
        let poor_fit = (item / cap).powi(3); // large items justify new bins
        let frag = (mean_residual / cap).powi(2) * (open_bins_count as f64).ln1p();
        score += 22.0 - 20.0 * poor_fit + 15.0 * frag;
        if fitting_bins_count <= 1 {
            score -= 12.0;
        }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.6 * (open_bins_count as f64).sqrt() * post_n;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space classes modulo 10.
    // Small residuals (<10) are perfect fits; medium residuals (10..30) are reusable;
    // large residuals are already reflected in the base score.
    let class = post_residual % 10;
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < 10 {
        score -= 40.0 + class as f64;
    } else if post_residual <= 30 {
        // reward residuals that are harmonic multiples of common item sizes
        if post_residual % 10 == 0 { score -= 12.0; }
        if post_residual % 20 == 0 { score -= 6.0; }
        if post_residual % 25 == 0 { score -= 5.0; }
    } else {
        // large leftover: mild penalty for granularity mismatch
        score += (class as f64) * 0.3;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score -= 20.0 - (gap as f64).min(20.0);
            // harmonic alignment of gap
            if gap % 10 == 0 { score -= 4.0; }
        } else {
            // next item cannot use this bin's leftover anyway
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = (mean_residual / bin_capacity as f64) < 0.35;
        if crowded || fitting_bins_count == 0 {
            score -= 30.0;
        } else {
            score += 15.0 + 5.0 * (open_bins_count as f64).ln().max(0.0);
        }
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill;

    // Progress modulation: early in stream, prefer consolidation; late, prefer any fit.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - fill);

    // Divergence from mean residual: penalize creating atypical dead space.
    score += ((post_residual as f64) - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 3.0 * post_residual as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Penalize leaving a gap that exactly matches the next item size (that's good actually):
    // reward if post_residual can host next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize post_residual that is just barely too small for the next item (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 1.5 * open_bins_count as f64;

    // Mean residual coupling: prefer bins deviating below mean residual (tighter bins).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate: penalize opening a new bin unless current bins are nearly full.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        score += 35.0 * (1.0 - avg_fill);
    }

    // Late-stream consolidation: as stream progresses, favor filling existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(4) * 30.0;

    // 2-step lookahead: if next item exactly fills post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // next fits: reward proportionally to how well it will fit after
            let rem2 = post_residual - next_item_size;
            score -= 25.0 * (1.0 - rem2 as f64 / bin_capacity as f64);
        } else {
            // next item cannot use the leftover: penalize dead space
            score += 15.0 + 0.2 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: strongly prefer fullest bin
        score -= 40.0;
    }

    // Compare against mean residual across open bins.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: avoid opening a new bin if this is the only fit.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Mild penalty for opening new bins when many are already open.
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * open_bins_count as f64;
    }

    // Early stream: be more conservative about fragmenting bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(3) * 30.0;

    // Penalize unusable dead space: residual below the minimum item size (1) is fine,
    // but residual in awkward low bands wastes capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny slivers are nearly dead space
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // placing here avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward for exact chain fit.
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else {
            score += 6.0;
        }
        // If current bin could host next item but post-placement won't, mild penalty.
        if bin_residual >= next_item_size && post_residual < next_item_size && post_residual > 0 {
            score += 8.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current fit is bad and there's room for the future.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin scales with stream progress
        // (early on, new bins are cheap to open; late, prefer consolidation).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 * 0.9 + progress * 40.0 + open_bins_count as f64 * 2.0;

        // A fresh bin is attractive if the item fits poorly everywhere else.
        if fitting_bins_count <= 1 {
            score -= 55.0;
        }
        // Fresh bin keeps full lookahead flexibility.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
        // If mean residual across open bins is large, prefer using them.
        score += mean_residual * 0.5;
    }

    // Slight preference for filling fuller bins first (best-fit flavor).
    score -= (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Mild penalty for spreading across many bins when residuals are high.
    if mean_residual > 50.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: waste after placement, non-linearly scaled
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Stream progress coupling: late in stream, penalize residual waste more strongly
    score += 25.0 * progress * norm_pr * norm_pr;

    // Lookahead coupling: reward residual that can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 10.0 * (1.0 - slack) * (1.0 + progress);
    } else if next_item_size > 0 {
        // residual too small for next item: penalize dead space
        score += 6.0 * norm_pr * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Mean residual deviation: prefer bins whose residual deviates from mean to consolidate
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Many open bins: discourage spreading; favor tight fits
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * norm_pr;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity fractions
    let cap_f = bin_capacity as f64;
    let pr = post_residual;
    let fill = 1.0 - (pr as f64) / cap_f;

    // Reward tight fits: post_residual in "harmonic" residue classes that pair well
    // with small items (1..=10 -> residual usable by next item).
    let pairable = if next_item_size > 0 { (pr >= next_item_size) as i32 } else { 1 };
    let dead = if next_item_size > 0 && pr > 0 && pr < next_item_size { (next_item_size - pr) as f64 } else { 0.0 };
    score += dead * 2.0; // penalize dead space blocking the lookahead item

    // Integer-division thresholds on post_residual: classify leftover
    let cls = pr / 10; // decade class
    match cls {
        0 => score -= 25.0,                       // near-perfect fit
        1 => score -= 15.0,
        2 => score -= 8.0,
        3 => score -= 3.0,
        4 => score -= 0.0,
        5 => score += 2.0,                        // half-full: mediocre
        6 | 7 => score += 4.0,
        _ => score += 6.0,                        // mostly empty
    }

    // Modulo coupling: post_residual % 25 harmonics (quarter-capacity classes)
    let q = pr % 25;
    score -= (25 - q.min(25 - q)) as f64 * 0.15; // reward residuals near quarter harmonics

    // Lookahead pairing bonus: exact fit for next item
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 40.0;
        } else if pr >= next_item_size && pr - next_item_size <= 10 {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, prefer tighter ones
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // New-bin candidate: penalize opening a bin unless current bins are quite full
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / cap_f;
        // open new bin only when open bins are heavily loaded or none fit well
        let pressure = avg_fill * 60.0 + (open_bins_count as f64) * 2.0;
        score += pressure;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 5.0; // new bin can host both items
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        }
    }

    // Slight preference for balancing mean residual early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64).abs() * 0.05 * (1.0 - progress);

    // Fill-fraction nonlinear reward
    score -= fill * fill * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold even the
    // minimum item (1..=min_gap) are pure waste -> heavy penalty.
    let min_gap = 1u32;
    if post_residual > 0 && post_residual < min_gap {
        score += 500.0;
    }
    // Small unusable gaps relative to typical item sizes (10..80): gaps < 10
    // can never be filled by any item in the classic regime; treat as dead.
    if post_residual > 0 && post_residual < 10 && bin_capacity >= 100 {
        score += 40.0 * (10.0 - post_residual as f64);
    }

    // Reward tight fits (near-zero post residual without being dead space).
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item exactly fills the post_residual,
    // strongly reward this placement (chain fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // next item still fits here -> mild reward for keeping usable space
        score -= 10.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use this gap: penalize proportionally
        score += 8.0 * ((next_item_size - post_residual) as f64).min(30.0);
    }

    // Last-chance bin: if this is the only bin that can fit the item, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        // Candidate new bin: base cost grows with number of open bins.
        score += 30.0 + 6.0 * open_bins_count as f64;
        // If next item is large and no open bin will likely fit it later,
        // opening early is less bad; slight relief.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    } else {
        // Reward using existing bins, more so when many are open.
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer spreading residual mass: if this bin's residual is far above the
    // mean residual, using it balances the workload across bins.
    let bin_res_f = bin_residual as f64;
    if bin_res_f > mean_residual {
        score -= 0.15 * (bin_res_f - mean_residual);
    } else {
        score += 0.15 * (mean_residual - bin_res_f);
    }

    // Stream progression: late in the stream, consolidate aggressively
    // (fewer residual fragments); early, be more flexible.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect (or near-perfect) fit.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward when next item exactly fits the residual left behind.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if nr == pr {
            score -= 500.0; // perfect chain
        } else if nr < pr && pr - nr <= 10.0 {
            score -= 150.0; // near chain
        } else if nr > pr {
            // next item cannot use the residual: dead-space penalty grows with gap
            score += (nr - pr) * 0.8;
        }
        // coupling with mean residual: prefer leaving residuals near the stream's average
        score += (pr - mean_residual).abs() * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, avoid wasting it on a bad fit.
    if fitting_bins_count == 1 && post_residual > 20 {
        score += 60.0;
    }

    // Prefer filling bins with small residuals relative to mean (avoid fragmentation).
    if (bin_residual as f64) < mean_residual {
        score -= 20.0;
    }

    // Late in the stream, consolidate: penalize opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 + 70.0 * progress;
        if fitting_bins_count == 0 {
            score -= 500.0; // no open bin fits: new bin is required
        }
    }

    // Mild bonus for many competing bins to encourage tight packing among candidates.
    score -= (fitting_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squaring post_residual amplifies penalty for large leftovers.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 30.0 * tightness * tightness;

    // Perfect-fit bonus: exact fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 5 {
        score -= 20.0;
    }

    // Lookahead: penalize leaving residual smaller than the next item unless it is near-zero;
    // reward leaving a residual that can host the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            score -= 8.0;
        } else if post_residual > 0 {
            // dead space relative to lookahead
            let waste = 1.0 - ((post_residual as f64) / next).min(1.0);
            score += 15.0 * waste;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin proportionally to how many
    // open bins could fit the item and how much mean residual is idle.
    if bin_residual == bin_capacity {
        let fit_pressure = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 0.0 };
        let idle = mean_residual / (bin_capacity as f64);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 + 10.0 * fit_pressure + 30.0 * idle - 10.0 * progress;
    } else {
        // Mildly favor bins with below-mean residual (concentrate filling).
        let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
        score += 5.0 * dev;
    }

    // Late-stream consolidation: as the stream progresses, prefer filling existing bins harder.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * t * ((bin_capacity - bin_residual) as f64) / (bin_capacity as f64);

    // Penalize leaving residuals in the awkward 50..70 band (hard to fill later).
    if post_residual >= 50 && post_residual <= 70 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, tolerate leftover space; later, strongly penalize waste.
    let waste_weight = 0.5 + 2.0 * progress * progress;
    score += waste_weight * (pr / cap) * (pr / cap) * cap * 0.1;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = 1.0 - pr / cap;
    score -= (item_size as f64 / cap) * tightness * 20.0;

    // Penalize bins whose residual deviates badly from the mean residual
    // (keeps a portfolio of usable gaps).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 15.0;

    // Last-chance bin: strong bonus to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // Lookahead: favor bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that cannot serve the next item is penalized more late in stream.
        score += 5.0 + 10.0 * progress;
    }

    // Mild penalty for spreading across many open bins.
    score += (open_bins_count as f64).ln() * 2.0;

    // Smooth preference for exact fills.
    if pr == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" the leftover space is.
    // Class boundaries via integer division on capacity fractions.
    let q = post_residual / (bin_capacity / 4); // 0..4 quarter classes
    match q {
        0 => score += 12.0,          // tiny dead space (<25) — very bad
        1 => score += 2.0,           // 25..49 — moderately usable
        2 => score -= 2.0,           // 50..74 — good leftover
        _ => score -= 5.0,           // 75..99 — excellent leftover
    }

    // Exact-fit harmonic bonus: post_residual divisible by common small classes.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward proportional to how snugly next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 - slack * 0.15;
        } else {
            // next item won't fit: penalize wasted potential, worse for tiny leftovers
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are nearly full
    // or there are no open bins at all.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 60.0; // must open first bin
        } else {
            let avg_fill = (bin_capacity as f64 - mean_residual).max(0.0);
            // open new bin only if existing bins are heavily loaded
            score += 30.0 - avg_fill * 0.4;
            if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
                score += 10.0; // big next item: keep capacity fresh? mild penalty anyway
            }
        }
    }

    // Late-stream tightening: as the stream progresses, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight preference for bins below mean residual (balance loads toward filling).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Harmonic class of item size: large items should go into tight bins.
    if item_size > bin_capacity * 3 / 4 {
        score -= 6.0;
    } else if item_size < bin_capacity / 4 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible item (size 1) are fine, but residuals below the
    // current item size or in a "useless gap" band are heavily penalized.
    // A post_residual that cannot fit the next item is a wasted gap.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 + (next_item_size - post_residual) as f64;
    }

    // Penalize tiny dead gaps that nothing (min size 1) can use — near-zero
    // residuals are actually good (tight fit), but mid-range dead space is bad.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // near-tight fit is desirable
    } else if post_residual >= 10 && post_residual < 30 {
        score += 15.0; // awkward dead zone
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is expensive when many bins
    // are open; encourage reusing open bins unless this is a last-chance fit.
    if bin_residual == bin_capacity {
        // Brand-new empty bin: baseline cost grows with open bin pressure.
        score = 60.0 + open_bins_count as f64 * 3.0;
        // Late in the stream, closing out bins matters more; slightly cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        // If the next item is huge, a fresh bin may be attractive.
        if next_item_size >= 60 {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, prefer placements that
    // consolidate (low post_residual) even more aggressively.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score -= pressure * (bin_capacity - post_residual) as f64 * 0.05;

    // Deviation from mean residual: bins far from the pack's average residual
    // that still leave dead space get a small penalty.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.02 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect or near-perfect fits (low dead space).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.85 {
        score -= 40.0 * fit_ratio;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits exactly-ish => big reward
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * next_fit;
        } else {
            // post_residual too small for next item => penalize dead space
            score += 8.0 + 0.15 * (post_residual as f64);
        }
    }

    // Compare post_residual against mean residual: avoid leaving atypically
    // small fragments relative to the fleet average.
    score += 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity (better to start fresh for big items).
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / bin_capacity as f64;
        score += 30.0 * (1.0 - size_frac);
    }

    // Mild pressure to keep the number of open bins bounded.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic discount for small post_residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize dead space that no plausible item can use.
    if post_residual > 0 {
        let dead = if next_item_size > 0 {
            if post_residual < next_item_size as f64 { post_residual as f64 } else { 0.0 }
        } else {
            post_residual as f64
        };
        score += 1.5 * dead;
    }

    // Lookahead: reward bins whose post-residual still fits the next item.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0;
    }

    // Last-chance bonus: this is the only fitting bin; strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: discourage spreading; prefer consolidation.
    if open_bins_count > 4 {
        score += 0.4 * (open_bins_count as f64 - 4.0);
    }

    // Prefer bins below mean residual (less-full bins get used first,
    // keeping tight bins for tight items).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when no bin fits well.
    if bin_residual == bin_capacity {
        let escape = if fitting_bins_count == 0 { 0.0 } else {
            let prog = step_index as f64 / total_items.max(1) as f64;
            30.0 + 20.0 * prog
        };
        score += escape;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    score += 8.0 * norm_pr * norm_pr * (1.0 + 2.0 * t) * cap * 0.1;
    score -= 6.0 * norm_pr * t * (1.0 - t) * 10.0;

    // Reward tight fits, more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (0.5 + t);

    // Penalize dead space relative to plausible next item
    if next_item_size > 0 {
        let waste = (pr - next_item_size as f64).max(0.0) / cap;
        score += 15.0 * waste * waste;
        if pr >= next_item_size as f64 {
            score -= 4.0 * (next_item_size as f64 / cap) * (1.0 - t);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * t;
    }

    // Mild penalty for proliferating bins early
    score += 0.3 * (open_bins_count as f64) * (1.0 - t);

    // Discourage near-empty placements in already-open bins
    if norm_pr > 0.7 {
        score += 5.0 * (norm_pr - 0.7) * (norm_pr - 0.7) * 10.0;
    }

    // Mean residual coupling: prefer bins deviating from the mean when tight
    score += 0.5 * (pr - mean_residual).abs() * (0.5 + tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but heavily penalize "dead" residuals that no
    // future item (1..100) can use efficiently.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Harmonic class of post_residual modulo capacity quarters.
    let q = post_residual % (bin_capacity / 4);
    // Residuals in the smallest quarter are near-dead; penalize them.
    if post_residual > 0 && post_residual < bin_capacity / 10 {
        score += 18.0;
    } else if q <= 5 && post_residual > 0 {
        score += 6.0;
    } else if post_residual == 0 {
        score -= 25.0; // perfect fill
    } else {
        score -= 4.0; // usable residual
    }

    // Lookahead coupling: reward residuals that exactly or nearly fit next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 10.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            // next item cannot use this residual at all -> mild penalty
            score += 3.0;
        }
        // Harmonic pairing: item + next item filling bin exactly is golden
        if item_size + next_item_size == bin_residual {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive when the item
    // is large relative to capacity or all fits are terrible.
    if bin_residual == bin_capacity {
        let tightness = (bin_residual - item_size) as f64; // == capacity - item
        // Base cost of a new bin grows with number of open bins (consolidation pressure)
        let open_cost = 40.0 + 3.0 * open_bins_count as f64;
        score = tightness + open_cost;
        // Small items shouldn't open new bins late in the stream
        if item_size < 40 && progress > 0.3 {
            score += 15.0;
        }
        // Large items near capacity: fresh bin is fine
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual is below the mean (denser bins first),
    // scaled by stream progress.
    score += 0.15 * (bin_residual as f64 - mean_residual) * (0.5 + progress);

    // Integer-division threshold: residuals divisible into halves of capacity
    // are more likely reusable by medium items.
    if post_residual > 0 && post_residual % 2 == 0 && post_residual >= 20 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to current residual.
    score -= 15.0 * (item_size as f64 / bin_residual.max(1) as f64);

    // Open-bin pressure: penalize spreading across many bins slightly,
    // but reward using bins when few bins fit the item.
    score += 0.8 * open_bins_count as f64;
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    // (i.e., this empty bin would otherwise be a wasteful placement).
    if bin_residual == bin_capacity {
        // Base new-bin cost; offset by how poorly current bins fit.
        score = 55.0 + 0.5 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 70.0; // no alternative: opening is right
        }
        if post_residual == 0 {
            score -= 60.0; // exact-fit item into fresh bin
        }
    }

    // Lookahead coupling: if next item would fit the post-residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    }
    // Penalize if post-residual is just barely too small for next item (dead space).
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual && post_residual < next_item_size {
        score += 6.0;
    }

    // Mean-residual coupling: prefer bins whose residual deviates from mean
    // in the direction of a tighter fill.
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (low post_residual), scaled by mean residual context.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 12.0 * tightness;

    // 2-step lookahead: strong reward if the next item fits exactly into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_waste = post_residual - next_item_size;
        score -= 30.0 * (1.0 - lookahead_waste as f64 / bin_capacity as f64);
        if post_residual == next_item_size {
            score -= 25.0; // perfect chain
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space the next item cannot use.
        score += 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Relative-to-mean-residual coupling: penalize bins far below mean residual (fragmented),
    // mildly favor bins near mean residual.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev * dev / (mean_residual + 1.0);

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let good_fit_exists = next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 15;
        if fitting_bins_count > 0 && (post_residual <= 20 || good_fit_exists) {
            score += 60.0; // discourage opening new bin when decent fit exists
        } else {
            score -= 5.0;
        }
    }

    // Slight preference to fill older/more open bins when many are open.
    score += 0.3 * (open_bins_count as f64).ln();

    // Early stream: be a bit more liberal with new bins (better long-run packing).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, but dampen when post_residual is a "dead zone"
    // (small unusable sliver) — a tiny leftover is fine if the next item can't use it anyway.
    let dead_zone = 10.0;
    if (post_residual as f64) < dead_zone {
        // sliver waste: penalize slightly relative to a perfect fill
        score += (dead_zone - post_residual as f64) * 0.5;
    }

    // Reward tight fits (item fills a large fraction of the residual)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 20.0;

    // Lookahead: if the next item fits exactly into the post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how well it fills the leftover
            let next_fit = next_item_size as f64 / post_residual.max(1) as f64;
            score -= next_fit * 15.0;
        } else {
            // next item will NOT fit here: leftover may become dead space;
            // penalize proportional to unusable leftover size
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes (capacity - item_size) on
    // average; make the empty-bin candidate attractive only when existing fits are poor.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin: its post_residual is large, already in score.
        // Adjust by global pressure: many open bins with large mean residual ->
        // prefer consolidating into existing bins, penalize new bin.
        score += mean_residual * 0.3;
        // early in the stream, opening bins is cheap; later, consolidation matters
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 15.0;
        // if only few bins fit the item, opening new is more acceptable
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    } else {
        // Existing bin: slight bonus for reusing bins to keep bin count low,
        // stronger when many bins are already open.
        score -= 5.0 + (open_bins_count as f64).min(20.0) * 0.5;
    }

    // Global balance: prefer bins whose residual is far from the mean residual
    // (keeps the pool of residuals diverse, improving future fit options),
    // but only mildly.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Late-stream tightening: as the stream ends, minimize per-bin waste harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + progress * (1.0 - norm_pr)) * (1.0 - progress * 0.5);

    let mut score = pr + 8.0 * poly * cap * 0.1;

    // Penalize dead space that no plausible item can fill
    if next_item_size > 0 {
        let gap = (next_item_size as i64 - post_residual as i64).max(0) as f64;
        score += 0.4 * gap;
        // Reward exact-ish fit for next item
        let tight = 1.0 - ((post_residual as f64 - next_item_size as f64).abs() / cap);
        score -= 6.0 * tight * tight;
    }

    // Last-chance bin bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64;

    // Penalize bins far from mean residual (fragmentation)
    score += 0.3 * (pr - mean_residual).abs();

    // New-bin candidate: neutral baseline, slightly penalized unless current fits are bad
    if bin_residual == bin_capacity {
        score = cap * 0.6 + progress * cap * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls on fine modulo
    // classes are more likely to accept future small items.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Penalize dead space that is too small to fit the smallest plausible item.
    if pr > 0 && pr < 10 {
        score += 30.0;
    }

    // Reward exact/near-exact fills.
    if pr == 0 {
        score -= 25.0;
    } else if pr <= 5 {
        score -= 8.0;
    }

    // Harmonic classes of post_residual (mod 10 bands): leftovers that match
    // common item-size granularity are reusable.
    let class = pr % 10;
    if class == 0 {
        score -= 6.0;
    } else if class == 5 {
        score -= 3.0;
    } else if class >= 7 {
        score += 2.5;
    }

    // Lookahead: if the next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size < pr {
            let waste = (pr - next_item_size) % 10;
            score -= 4.0 - (waste as f64) * 0.3;
        } else {
            // next item won't fit here; mild penalty proportional to overflow gap
            score += ((next_item_size - pr) as f64) * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Fraction of capacity filled by this placement: reward tight fits.
    let fill_ratio = item_size as f64 / cap;
    score -= fill_ratio * 8.0;

    // Prefer filling bins that are already relatively full (low residual fraction).
    let residual_frac = bin_residual as f64 / cap;
    score += residual_frac * 3.0;

    // Late in the stream, be more aggressive about closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - post_residual as f64).abs() * 0.1;

    // Prefer bins with below-mean residual (they are the "tight" ones).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted when many bins are open
        // and mean residual is fragmented.
        let fragmentation = mean_residual / cap;
        score = 55.0 + open_bins_count as f64 * 0.5 - fragmentation * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // new bin guarantees fit for next item too
            score -= 5.0;
        }
        if fitting_bins_count == 1 {
            // don't open a new bin when an existing one can take the item
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for the smallest plausible item
    let min_next = if next_item_size > 0 { next_item_size.min(100) } else { 10 };
    if post_residual < min_next {
        score += 40.0 + 0.5 * (min_next - post_residual) as f64;
    }

    // Reward tight fits: small post_residual relative to item size
    if item_size > 0 {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= 12.0 * fill_ratio * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Perfect-fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_penalty = 18.0 + 10.0 * (open_bins_count as f64).ln().max(0.0) + 15.0 * progress;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
        // Opening a new bin is acceptable if the item is huge and fits badly elsewhere
        if item_size > 60 && bin_residual - item_size < 20 {
            score -= 30.0;
        }
    } else {
        // Mild reward for consolidating into existing bins
        score -= 3.0;
        // Penalize bins whose residual deviates badly from mean (imbalance)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Encourage keeping residuals near multiples that stay usable
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (low post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // 2-step lookahead: strongly reward exact match of post_residual with next item
    if next_item_size > 0 {
        let look = next_item_size as f64;
        if (post_residual as u32) == next_item_size {
            score -= 120.0; // perfect 2-chain
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / (bin_capacity as f64)).max(0.0);
        } else {
            // next item cannot fit here: penalize leaving a gap close to next_item_size (dead space)
            let gap = look - post_residual as f64;
            score += 15.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);
        }
    }

    // Compare post_residual against mean residual: avoid creating far-below-mean residuals
    let mean_post = mean_residual - item_size as f64;
    if post_residual as f64 > mean_post + 0.5 * mean_residual.abs().max(1.0) {
        score += 10.0; // wasteful bin
    } else if (post_residual as f64) < mean_post {
        score -= 8.0; // better than average packing
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when fits are poor
    if bin_residual == bin_capacity {
        if next_item_size > 0 && (post_residual as u32) >= next_item_size && post_residual <= bin_capacity / 2 {
            score -= 30.0; // fresh bin can serve next item too
        } else {
            score += 25.0 + 0.05 * open_bins_count as f64; // discourage needless new bins
        }
    }

    // Late-stream bias: consolidate more aggressively as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: exact or near-exact fills get strong discounts.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        let tightness = 1.0 - (post / cap);
        score -= 12.0 * tightness * tightness;
    }

    // Penalize small dead space that likely becomes unusable (post_residual in 1..=10).
    if post_residual >= 1 && post_residual <= 10 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Next item can't use this dead space; penalize proportionally.
        score += 4.0 * (post / cap);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Prefer bins whose residual is below the mean residual (more filled bins first).
    let bin_res = bin_residual as f64;
    score += 0.15 * (bin_res - mean_residual);

    // Mild preference for placing into bins when many bins are open (consolidation).
    score += 0.05 * open_bins_count as f64;

    // Time horizon: early in the stream, be slightly more willing to open new bins
    // (keep flexibility); late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 5.0 + 10.0 * progress;
    } else {
        score -= 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: prefer low post_residual (tight packing).
    // Late stream: mild bonus for filling bins tightly, extra pressure to use open bins.
    let progress_coupling = pr * (0.5 + 1.5 * t) - pr * pr / cap * (1.0 + 2.0 * t * t);
    score += 0.8 * progress_coupling;

    // Reward tight fits (small post_residual) with smooth saturating bonus.
    let tight = 1.0 - pr / cap;
    score -= 6.0 * tight * tight * tight;

    // Penalize waste relative to mean residual: creating dead space worse if bin already loose.
    score += 0.5 * (pr - mean_residual).max(0.0);

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if next item fits in post_residual, reward; else penalize large leftovers.
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 4.0;
        } else {
            score += 0.3 * (pr - (next_item_size as f64 - pr).max(0.0));
        }
    }

    // New-bin candidate: penalize opening new bins, more so as stream progresses,
    // unless it would be extremely tight (small item into empty bin).
    if bin_residual == bin_capacity {
        let new_bin_penalty = 20.0 + 10.0 * t;
        let tight_new = (item_size as f64 / cap).powi(3);
        score += new_bin_penalty - 25.0 * tight_new;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: residuals near multiples of common item sizes are reusable.
    let post = post_residual;
    if post > 0 {
        // Class by quarters of capacity
        let quarter = (bin_capacity / 4) as f64;
        let class = (post as f64 / quarter).floor();
        score += class * 4.0; // coarser bins (larger classes) penalized mildly

        // Reward residuals that are "harmonic" with next item size (exact or near divisor)
        if next_item_size > 0 && next_item_size <= post {
            let diff = post - next_item_size;
            if diff == 0 {
                score -= 25.0; // perfect pairing with lookahead
            } else if diff <= 10 {
                score -= 12.0;
            } else if diff <= 25 {
                score -= 5.0;
            }
        } else if next_item_size > post {
            score += 6.0; // lookahead cannot use this leftover
        }

        // Modulo arithmetic: leftover divisible by small common sizes is more usable
        for m in [10u32, 20, 25, 50] {
            if post % m == 0 && post > 0 {
                score -= 3.0;
                break;
            }
        }

        // Integer-division thresholds: tiny dead space is fine (bin nearly full),
        // medium dead space is the worst.
        let dead = post as f64 / cap;
        if dead < 0.05 {
            score -= 15.0;
        } else if dead < 0.15 {
            score += 8.0; // awkward small-medium gap
        } else if dead < 0.35 {
            score += 3.0;
        }
    } else {
        score -= 40.0; // perfect fill
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a bin is expensive unless current bin is a bad fit
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_penalty = 55.0;
        // If mean residual is large and item is small, prefer existing bins
        if mean_residual > item_size as f64 * 1.2 {
            new_bin_penalty += 20.0;
        }
        // Late in stream, consolidate
        new_bin_penalty += progress * 15.0;
        score += new_bin_penalty;
    }

    // Mild bonus for tight fit relative to bin residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 10.0;

    // Spread across many open bins is costly; prefer filling bins with low residual
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    // Small tie-break noise-free deterministic perturbation on post_residual classes
    let r = ((post.wrapping_mul(2654435761) >> 13) & 0x7) as f64;
    score += r * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Mid-range gaps (10..=20) are moderately wasteful.
    if post_residual >= 10 && post_residual < 20 {
        score += 0.8 * post_residual as f64;
    }

    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Reward bins whose residual closely matches the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.5 * tightness;

    // Lookahead: if next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual >= next_item_size {
            score -= 0.3 * next_item_size as f64;
        } else {
            // Next item cannot use the gap: penalize proportional dead space.
            score += 0.4 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
    score += 0.05 * pressure * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 + 0.1 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a new bin
        }
        if post_residual as f64 > mean_residual + 30.0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward residuals that exactly match the next item,
    // penalize residuals slightly larger than next item (dead space).
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let nx = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 500.0; // chain fit: next item fills this bin perfectly
        } else if post_residual > next_item_size {
            let slack = pr - nx;
            // gentle penalty growing with slack beyond the next item
            score += 0.5 * slack;
            // bonus if next item could still fit comfortably
            score -= 10.0;
        } else {
            // next item won't fit here; penalize proportionally to how much
            // space is wasted relative to capacity
            score += 0.3 * pr;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Compare against mean residual: placing in a bin with residual far above
    // mean is a poor fit; bins tighter than mean are preferred.
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Prefer filling bins when many bins are open (consolidation pressure).
    if open_bins_count > 3 {
        score -= 5.0 + 0.2 * open_bins_count as f64;
    }

    // New-bin candidate: make it moderately attractive only when no open bin
    // fits well (post_residual large relative to capacity means poor fit).
    if bin_residual == bin_capacity {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        // opening new bin is good if best existing placements leave big waste
        if waste_ratio > 0.5 {
            score -= 150.0;
        } else {
            score += 100.0; // discourage opening new bins on good fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Strongly penalize leaving large, awkward dead space.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // near-perfect fill bonus
    }
    if post_residual > 50 {
        score += 4.0; // wasteful large gap
    }

    // Perfect fit is extremely attractive.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = open_bins_count as f64 / (mean_residual + 1.0);
        // Early in stream: opening fresh bins is cheap; later: consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 25.0 * progress - 5.0 * pressure;
        // If next item is large, a fresh bin is valuable.
        if next_item_size > 0 && next_item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 8.0;
        }
    } else {
        // Lookahead: if next item fits exactly in post_residual, big bonus.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 20.0;
            } else if next_item_size <= post_residual {
                score -= 5.0 * (post_residual as f64 - next_item_size as f64).min(10.0) / 10.0;
            } else {
                score += 3.0; // next item won't fit here anyway
            }
        }
        // Prefer bins with below-average residual (concentrate space).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Mild preference to fill older bins when many are open.
    score += 0.3 * open_bins_count as f64 * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Non-linear waste penalty: dead space hurts quadratically, more so late in stream.
    score += 0.35 * (pr / cap) * (pr / cap) * (1.0 + 2.0 * progress);

    // Reward tight fits (small post_residual relative to item).
    let tightness = it / cap;
    score -= 6.0 * tightness * (1.0 - pr / cap).powi(2);

    // Lookahead coupling: bonus if next item fits the post-residual exactly-ish.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let gap = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 4.0 * (1.0 - gap).max(0.0);
    } else if next_item_size > 0 {
        // Penalize leaving residual that no plausible item uses.
        score += 2.0 * (pr / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 + progress);
    }

    // Prefer bins below mean residual (keeps larger residuals available).
    score += 0.08 * (pr - mean_residual);

    // New-bin candidate: only attractive when it serves future items well.
    if bin_residual == bin_capacity {
        let base = 25.0 - 8.0 * progress;
        let lookahead_fit = if next_item_size > 0 && next_item_size <= item_size { 6.0 } else { 0.0 };
        score = score + base - lookahead_fit;
    }

    // Mild preference to consolidate into fewer bins.
    score += 0.02 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into residue classes
    let pr = post_residual as u32;
    let class = pr % 10; // harmonic class modulo 10
    // Penalize dead space that cannot host typical small items (1..=10)
    if pr > 0 && pr < 10 {
        score += 25.0; // pure dead space penalty
    }
    // Reward residuals in "useful" harmonic classes (multiples of 5/10 host many sizes)
    if class == 0 {
        score -= 6.0;
    } else if class == 5 {
        score -= 3.0;
    } else if class >= 7 {
        score += 2.0;
    }

    // Perfect fit: zero post residual is ideal
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit: post_residual smaller than smallest possible next item
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 1.5; // slight penalty: leftover unusable for lookahead item
        } else if post_residual == next_item_size {
            score -= 30.0; // perfect two-item chain
        } else {
            // fraction of residual reusable by next item
            let reuse = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * reuse;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a bin unless item is large relative to capacity
    if bin_residual == bin_capacity {
        let load_frac = item_size as f64 / cap;
        score = 0.6 * cap - 40.0 * load_frac;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // big item stream: fresh bin is fine
        }
        if fitting_bins_count <= 1 {
            score -= 15.0; // no real alternative
        }
    }

    // Encourage packing into bins below mean residual (balancing)
    let prf = post_residual as f64;
    if prf > mean_residual {
        score += 0.3 * (prf - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - prf);
    }

    // Late in stream: prefer filling existing bins aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - prf / cap);

    // Too many open bins: discourage spreading
    if open_bins_count > 8 {
        score += 0.5 * ((open_bins_count - 8) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps nonlinearly.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Dead space penalty grows sharply as gap shrinks below typical item sizes.
        if gap < 10.0 {
            score += 40.0 * (10.0 - gap) / 10.0;
        } else if gap < 20.0 {
            score += 12.0 * (20.0 - gap) / 10.0;
        }
        // Perfect fit bonus.
        if post_residual == 0 {
            score -= 30.0;
        }
    }

    // Reward filling bins tightly relative to capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Open bins pressure: with many open bins, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual != bin_capacity {
        // Existing bin: reward more when many bins are open.
        score -= 5.0 * pressure * (0.5 + 0.5 * progress);
    } else {
        // New-bin candidate: penalize when open bins can still absorb items,
        // but allow it if this is a last-chance-free situation with large item.
        score += 8.0 + 6.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        if item_size >= 60 {
            score -= 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0;
    }
    // If next item would NOT fit in post_residual but would fit a larger residual, mild penalty.
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score -= 3.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- 2-step lookahead: reward exact match between post_residual and next item ----
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect 2-chain: post_residual == next_item_size -> strong reward.
        if diff == 0.0 {
            score -= 25.0 + 15.0 * (1.0 - progress);
        } else {
            // Penalize mismatch proportionally; small mismatches still mildly penalized.
            score += 0.15 * diff;
            // If next item cannot fit into the leftover, this creates dead space.
            if (post_residual as i64) < (next_item_size as i64) {
                score += 0.35 * (next_item_size as f64 - post_residual as f64);
            }
        }
        // Triple-fill potential: next item also leaves room for a third small item.
        let second_left = post_residual as i64 - next_item_size as i64;
        if second_left >= 1 && second_left <= 10 {
            score -= 6.0;
        }
    } else {
        // Last item: just minimize waste.
        score -= 5.0;
    }

    // ---- Relative-to-mean-residual coupling ----
    // Prefer bins whose residual is close to the item (tight fit) relative to fleet average.
    let tightness = bin_residual as f64 - item_size as f64;
    if tightness < 0.25 * mean_residual && item_size <= bin_residual {
        score -= 4.0; // very tight fit relative to average open space
    }
    score += 0.10 * (bin_residual as f64 - mean_residual);

    // ---- Last-chance bin: avoid opening a new bin when this is the only fit ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is justified only when existing fits are poor:
        // penalize new bin normally, but less when many bins are open and fragmented.
        let waste_here = (bin_capacity - item_size) as f64;
        score = waste_here + 8.0 - 0.05 * open_bins_count as f64;
        // If next item is huge and would need a fresh bin anyway, favor opening now.
        if next_item_size > 50 && item_size >= 50 {
            score -= 10.0;
        }
    }

    // Small bonus for keeping a healthy number of bins from fragmenting early.
    if open_bins_count > 0 && post_residual >= 10 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    if post_residual == 0 {
        score -= 50.0;
    } else if fit_ratio < 0.10 {
        score -= 25.0 * (1.0 - fit_ratio / 0.10);
    }

    // Penalize residuals that are "dead zones": too small for the smallest
    // plausible item but large enough to waste capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty, worse if this is the only option.
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate logic: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let bad_existing = (post_residual as f64 - mean_residual).abs();
        score += 60.0 * pressure;
        score -= 20.0 * (1.0 - (item_size as f64 / bin_capacity as f64));
        if fitting_bins_count > 0 && bad_existing < 10.0 {
            score += 25.0; // existing bins fit well; discourage new bin
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Mild penalty for proliferating bins when many are already open.
    score += open_bins_count as f64 * 0.05;

    // Slight preference for bins already below-average residual (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: penalize post_residual quadratically relative to capacity.
    score += (post / cap) * (post / cap) * 30.0;

    // Reward filling bins well: bonus proportional to fill ratio, amplified with progress.
    let fill = 1.0 - (post / cap);
    score -= fill * fill * (20.0 + 25.0 * progress);

    // Penalize dead space that is too small for typical future items (unusable gap).
    if post > 0.0 && post < 10.0 {
        score += 15.0 * (1.0 - post / 10.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize mildly, more so as stream progresses (prefer consolidation).
    if bin_residual == bin_capacity {
        score += 35.0 + 30.0 * progress + open_bins_count as f64 * 2.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let tightness = 1.0 - (post - nxt) / cap;
            score -= 25.0 * tightness;
        } else {
            score += 8.0; // next item won't fit here; slight penalty
        }
    }

    // Prefer bins with below-mean residual (concentrate slack).
    let mean_gap = (post - mean_residual) / cap;
    score += mean_gap * 10.0;

    // Smooth non-linear stream coupling: late stream favors aggressive filling.
    score -= (progress * std::f64::consts::PI).sin() * 5.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: post_residual in harmonic low classes
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Harmonic class penalty: residual divisible by common item sizes is reusable
    if post_residual > 0 {
        let pr = post_residual;
        if pr % 10 == 0 {
            score -= 8.0;
        } else if pr % 5 == 0 {
            score -= 4.0;
        }
        // dead space: small odd residual unlikely to be filled
        if pr < 10 && pr % 2 == 1 {
            score += 6.0;
        }
    }

    // Lookahead: does next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
            // harmonic chain: post_residual % next_item_size small
            if post_residual % next_item_size.max(1) <= 3 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here: penalize wasting residual
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 8.0;
            } else {
                score += 4.0;
            }
        }
    }

    // Last chance: this is the only bin that fits -> strong reward
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize opening a new bin when open bins exist with decent residual
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 45.0;
            // scale penalty with mean residual available
            score += mean_residual * 0.3;
        } else {
            score -= 10.0;
        }
    }

    // Mild preference to fill earlier bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    // Tie-break: prefer bins with lower residual among equals
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 {
        // Estimate the minimum plausible future item size via stream progression.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let min_future = 10.0 * (1.0 - 0.4 * progress); // assume smaller items later
        if (post_residual as f64) < min_future {
            // Dead space: unusable for any expected item.
            score += 60.0 + 2.0 * (min_future - post_residual as f64);
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Tightness reward: favor bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Open bins pressure: penalize spreading across many bins slightly.
    score += 0.5 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (unless the fit would create dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual == 0 || (post_residual as f64) >= 10.0 {
            score -= 50.0;
        }
    }

    // Lookahead coupling: if the next item fits into the post residual, reward.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && (post_residual as f64) > 0.0 && (post_residual as f64) < next_item_size as f64 {
        // Next item won't fit here; penalize leaving a gap that wastes capacity.
        score += 10.0;
    }

    // New-bin candidate handling: opening a new bin should only win when this bin
    // would create severe dead space. Make the empty-bin baseline moderately high.
    if bin_residual == bin_capacity {
        score += 35.0 + 0.3 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins whose residual is near the mean
    // (balanced packing), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect-ish fits: low post residual strongly favored.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if the next item fits exactly in the
    // post residual, strongly reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_fit = next_item_size as f64 / post_residual as f64;
        score -= 25.0 * chain_fit;
        // Perfect chain: post_residual == next_item_size
        if next_item_size == post_residual {
            score -= 20.0;
        }
    } else if next_item_size > 0 {
        // Penalize leaving residual that the next item cannot use
        // (dead space relative to lookahead).
        let waste = (next_item_size as f64 - post_residual as f64).max(0.0);
        score += 0.15 * waste;
    }

    // Penalize post residuals too small to ever be useful for typical items.
    if post_residual < 10 {
        score += 12.0;
    }

    // Coupling with mean residual: prefer bins whose resulting residual
    // stays near the mean (balanced packing), penalize outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it unattractive unless current bin fits are bad.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Late in the stream, opening a new bin is less costly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
        // If next item is large and this item is small, new bin helps future fits.
        if next_item_size > item_size {
            score -= 8.0;
        }
    }

    // Mild pressure to fill already-open bins as they accumulate.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let fit_ratio = item / bin_residual as f64;
    let mut score = post;

    // Reward tight fits (high fill ratio) with a non-linear bonus
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize creating dead space that is too small to be useful for typical items
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (10.0 - post) / 10.0;
    }

    // Lookahead: reward if next item can fit into post_residual (chaining)
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 12.0 * (1.0 - post / cap);
    } else if next_item_size > 0 && (next_item_size as f64) > post {
        // penalize if post_residual is just barely too small for next item
        score += 8.0 * (1.0 - post / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Time horizon: later in the stream, be more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when existing bins fit poorly
        let spread = (mean_residual - post).abs();
        score = cap * (0.9 - 0.25 * progress);
        if fit_ratio > 0.9 || fitting_bins_count == 0 {
            score -= 50.0;
        }
        if spread > cap * 0.5 {
            score += 10.0;
        }
        // late in stream, prefer reusing open bins
        score += 15.0 * progress;
    }

    // Mild penalty for proliferating open bins early
    score += (open_bins_count as f64).sqrt() * (1.0 - progress) * 0.5;

    // Global residual pressure: if mean residual is small, conserve space in big-residual bins
    if bin_residual as f64 > mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap; // fraction of bin used after placement

    // Smooth polynomial core: reward high fill non-linearly
    let mut score = pr * (1.0 + 0.6 * progress) - 30.0 * fill * fill * (1.0 - fill);

    // Dead-space penalty: residuals too small for typical items are wasted
    let dead = if pr > 0.0 { ((pr / 10.0).floor().max(0.0)) } else { 0.0 };
    score += 2.0 * (10.0 - pr.min(10) as f64).max(0.0);

    // Lookahead coupling: smooth interaction between post_residual and next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (pr - n).abs();
        score += 0.35 * (gap * gap) / cap;           // penalize near-miss fits
        score -= 6.0 * (1.0 - (gap / cap).min(1.0)); // reward exact-ish lookahead fit
        if pr >= n {
            score -= 4.0 * (1.0 - pr / cap);         // bin remains useful
        } else {
            score += 5.0;                            // lookahead won't fit here
        }
    } else {
        score += 3.0; // last item: slightly prefer existing bins
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: smooth penalty growing with progress & open bins
    if bin_residual == bin_capacity {
        let open = open_bins_count as f64;
        score += 20.0 + 8.0 * progress + 1.5 * open
            - 10.0 * (mean_residual / cap).max(0.0).min(1.0);
        // allow new bin late in stream when few bins fit (fragmentation relief)
        score -= 15.0 * progress * (1.0 - (fitting_bins_count as f64).min(3.0) / 3.0);
    }

    // Mild diversity term: prefer bins whose residual deviates from mean residual
    let br = bin_residual as f64;
    score += 0.08 * (br - mean_residual) * (br - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact divisors of capacity are prime slots.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        // Residual classes: pr in [1..9] tiny dead space, mid residual risky
        if pr <= 9 {
            score -= 25.0;
        } else if pr <= 20 {
            score -= 8.0;
        } else if pr <= 33 {
            score += 6.0;
        } else {
            score += 14.0;
        }
        // Modulo-10 harmonic: residuals that are multiples of 10 align with
        // typical item granularities (items often multiples of 5/10).
        if pr % 10 == 0 {
            score -= 5.0;
        }
        if pr % 5 == 0 {
            score -= 2.0;
        }
    }

    // Integer-division threshold: can next item fit into post_residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chainable: reward proportional to leftover after chaining
            let chained_left = post_residual - next_item_size;
            score -= 10.0 + (chained_left as f64).min(20.0) * 0.3;
        } else {
            // dead space for the lookahead: penalize if the gap is "almost fitting"
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 12.0; // tantalizing but wasted
            } else {
                score += 3.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        // new bin starts with residual = capacity: big, so add penalty unless forced
        score += 55.0 * pressure - 0.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open
        }
    }

    // Crowd control: many open bins with high mean residual -> prefer consolidation
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 3 && mean_residual > 30.0 {
        score += (open_bins_count as f64 - 3.0) * 1.5 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny nonzero residuals are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward leaving residual that can still fit the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0; // dead space relative to lookahead
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // and discourage opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or stream is early.
        score = bin_capacity as f64 * 0.5 + open_bins_count as f64 * 3.0 + (1.0 - progress) * 10.0;
        // Allow new bin only if residuals elsewhere are small (poor fits everywhere).
        if mean_residual < 8.0 {
            score -= 20.0;
        }
    } else {
        // Prefer bins with larger residual consumed relative to mean residual.
        score -= (bin_residual as f64 - mean_residual) * 0.3;
        score += open_bins_count as f64 * 0.5;
    }

    // Mild tightness reward: proportional fit quality.
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Core dead-space penalty (quadratic in wasted space)
    score += 0.6 * (post_residual as f64).powi(2) / cap;

    // 2-step lookahead: reward when post_residual exactly matches next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff < 1.0 {
            score -= 25.0; // perfect two-step match
        } else {
            score += 0.5 * diff;
        }
        // If next item fits exactly into post_residual AND this fit was tight
        if post_residual >= next_item_size && post_residual - next_item_size < 5 {
            score -= 15.0;
        }
        // Penalize leaving residual too small for the next item (dead space)
        if post_residual < next_item_size {
            score += 0.8 * (nxt - post_residual as f64);
        }
    } else {
        // Last item: just minimize residual
        score -= 10.0;
    }

    // Relative to mean residual: prefer bins below mean residual (tighter bins)
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 30.0;
        // But allow new bin if the item fits perfectly in a fresh bin
        if item_size == bin_capacity {
            score -= 100.0;
        }
        // If lookahead item would pair perfectly with current item in fresh bin
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Late in stream: consolidate, avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / cap);

    // Prefer filling bins with many open bins (reduce bin count pressure)
    score -= 0.1 * open_bins_count as f64 * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fit (low post_residual) with a non-linear squash.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Utilization reward: how much of the bin the item consumes.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 15.0;

    // Lookahead: strongly favor bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if the next item would also fit snugly afterwards.
        let next_tight = (post_residual - next_item_size) as f64;
        score -= (1.0 - next_tight / bin_capacity as f64) * 6.0;
    } else if next_item_size > 0 {
        // Penalize leaving residual just below next item size (dead zone).
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Global state coupling: with many open bins, prefer consolidating into
    // bins below mean residual (denser bins).
    if open_bins_count > 0 {
        let diff = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += diff * 8.0;
    }

    // Time horizon: early in the stream, be more willing to leave slack
    // (future items unknown); late in the stream, pack tightly.
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 1.0 };
    score += (1.0 - progress) * fit_ratio * 10.0;
    score -= progress * fill * 5.0;

    // New-bin candidate: make it unattractive unless existing fits are terrible.
    if bin_residual == bin_capacity {
        score += 30.0 + fit_ratio * 20.0;
        // Late in stream with many open bins, opening new bins is fine.
        if progress > 0.7 && open_bins_count > 4 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / (total_items.max(1) as f64);
    let fit = item_size as f64 / cap;
    let mut score = pr;

    // Reward tight fits: quadratic suppression of score as post_residual shrinks.
    let tight = 1.0 - (pr / cap);
    score -= 22.0 * tight * tight;

    // Non-linear coupling: tightness gains value as the stream progresses.
    score -= 14.0 * tight * tight * t * (1.0 - t * 0.5);

    // Penalize large post-residuals superlinearly (dead space), scaled by stream progress.
    score += 0.9 * (pr / cap) * (pr / cap) * cap * (0.5 + 0.5 * t);

    // Last-chance bonus: strongly favor this bin if it is the only fitting one.
    if fitting_bins_count == 1 {
        score -= 18.0 + 10.0 * tight;
    }

    // Prefer bins whose residual deviates favorably from the mean residual (smooth coupling).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev * (dev.signum()) * -1.0 * -1.0; // penalize deviation
    score -= 4.0 * dev * (1.0 - t);

    // Lookahead: reward if next item fits the post-residual smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = ((pr - nx) / cap).max(-1.0);
        if pr as u32 >= next_item_size {
            score -= 8.0 * (1.0 - (nx / cap)) * (1.0 + fits_next.abs() * 0.0 + 0.5 * t);
        } else {
            score += 5.0 * (nx / cap) * (0.5 + t);
        }
    }

    // Mild pressure against hoarding many open bins late in the stream.
    score += 0.02 * open_bins_count as f64 * (0.3 + 0.7 * t);

    // Smooth new-bin preference: opening a fresh bin is attractive for big items or late big residuals.
    let is_new = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new {
        score -= 6.0 * fit * (1.0 - t) + 10.0 * fit * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into
    // "composable" classes (multiples of small divisors of capacity).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity consumed by this placement
    let fill = (bin_residual - post_residual) as f64 / cap;
    score -= 60.0 * fill * fill;

    // Harmonic classes of post_residual modulo {50, 25, 20, 10}:
    // residuals near these classes are more reusable by future items.
    let class_bonus = |r: u32| -> f64 {
        if r == 0 { 80.0 }
        else if r % 50 == 0 { 55.0 }
        else if r % 25 == 0 { 40.0 }
        else if r % 20 == 0 { 30.0 }
        else if r % 10 == 0 { 18.0 }
        else { 0.0 }
    };
    score -= class_bonus(post_residual);

    // Dead-space penalty: residuals too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // Lookahead coupling: does post_residual pair with next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // perfect pairing gets big reward; tighter fit is better
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here: mild penalty scaled by overshoot
            score += 0.15 * ((next_item_size - post_residual) as f64);
        }
        // harmonic alignment: next_item_size shares a divisor class with post_residual
        if post_residual % 10 == 0 && next_item_size % 10 == 0 {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is poor
    if bin_residual == bin_capacity {
        score += 30.0;
        if post_residual as f64 > mean_residual {
            score += 20.0;
        }
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * (1.0 - progress);
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64;

    // Prefer bins with residual close to item (tight fit) via harmonic banding
    let band = (bin_residual / 10).min(post_residual / 10 + 1);
    score -= band as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone: f64 = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 8.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight-fit reward: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 25.0;

    // Penalize leaving a gap that exactly wastes space relative to future item.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 12.0; // gap too small for lookahead item -> likely dead space
    }
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0; // lookahead item will fill bin perfectly
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when current fit is poor.
    if bin_residual == bin_capacity {
        let fit_quality = item_size as f64 / bin_capacity as f64;
        score += 20.0 - fit_quality * 40.0;
    }

    // Mean residual coupling: prefer bins deviating below mean residual (consolidation).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: next item fits with small slack left over.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - 0.6 * slack;
    }
    // Penalize if the next item will NOT fit in the residual (dead space risk).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Reward tight fits relative to bin capacity (small post_residual).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= (1.0 - tightness) * 10.0;

    // Compare against mean residual across open bins: prefer bins that
    // become more "average-consumed" than the fleet mean.
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when current bins fit badly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so open bins with decent fits win.
        score += 30.0;
        // If no open bin can fit the item, opening is natural (fitting_bins_count
        // counts only open bins; new bin always fits, so ==1 means only new bin).
        if fitting_bins_count == 1 {
            score -= 100.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Mild penalty for many open bins: encourage closing them out.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor near-perfect fits.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: heavy bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 12.0; // consuming space needed by the next item
        }
    }

    // Prefer bins with residual close to the mean residual (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Late in the stream, be greedier: reward tight fits even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * fit_ratio;

    // Mild penalty for proliferating open bins early on.
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let escape_cost = 30.0 + 45.0 * fit_ratio;
        score += escape_cost;
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: quadratic coupling of post_residual with stream progress.
    // Early on, tolerate slack; later, punish dead space quadratically.
    let mut score = post * (1.0 + 1.5 * progress) + 40.0 * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits with a smooth saturating term.
    let tightness = 1.0 - norm_post;
    score -= 12.0 * tightness * tightness;

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead compatibility: reward if next item fits the post residual,
    // penalize otherwise (smooth falloff with mismatch).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let compat = 1.0 / (1.0 + gap / 30.0);
        score -= 10.0 * compat;
        // Penalize residuals that fit neither current nor next item well.
        if next_item_size as u32 > post_residual {
            score += 6.0 + 8.0 * progress;
        }
    }

    // Mild preference to fill bins below mean residual (consolidation).
    score -= 0.05 * (mean_residual - post).max(0.0);

    // Slight penalty for proliferating bins late in the stream.
    score += 0.3 * (open_bins_count as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: strongly favor tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // Harmonic class of post_residual: residues mod 10 and mod 20.
    let r10 = (post_residual % 10) as f64;
    let r20 = (post_residual % 20) as f64;
    // Residues near 0 (divisible) are "clean" classes -> reward.
    score -= 6.0 * (1.0 - r10 / 9.0).min(1.0) * (post_residual > 0) as i32 as f64;
    score -= 3.0 * (1.0 - r20 / 19.0).min(1.0) * (post_residual > 0) as i32 as f64;

    // Integer division thresholds: post_residual buckets by capacity fractions.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual <= quarter {
        score -= 8.0; // excellent leftover class
    } else if post_residual <= half {
        score += 2.0; // mediocre
    } else {
        score += 6.0; // wasteful
    }

    // Lookahead coupling: if next item fits into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 + (post_residual - next_item_size) as f64 * 0.15;
    } else if next_item_size > post_residual {
        // dead space relative to the next item's harmonic class
        let gap = (next_item_size - post_residual) as f64;
        score += 0.05 * gap;
        // penalize if gap lands in an awkward class (mod 10 near small values)
        let gr = (next_item_size % 10) as f64;
        score += 0.3 * (gr / 9.0);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let spread = (mean_residual - post_residual as f64).abs();
        score += 15.0; // default penalty for opening new bin
        if post_residual == bin_capacity {
            // empty bin call: score relative to mean residual of open bins
            score -= 10.0 + mean_residual * 0.1;
            if fitting_bins_count == 0 {
                score -= 20.0;
            }
        }
        let _ = spread;
    }

    // Stream progression: early on, be conservative with bin count.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (open_bins_count as f64) * 0.3;
    score -= progress * 2.0;

    // Mild pull toward bins whose residual is near the mean (balance).
    score += 0.1 * ((bin_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; penalize gaps below a "usable" threshold nonlinearly.
    let dead_threshold = 10.0_f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= (item_size as f64) / (1.0 + post_residual as f64);
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // discourage opening new bins unless the fit is poor.
    score += (open_bins_count as f64) * 1.5;

    // New-bin candidate: only attractive when current fit leaves large waste
    // or the bin is a poor match for the lookahead item.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        // Base cost of opening a new bin grows with number of open bins.
        score += 55.0 + (open_bins_count as f64) * 2.0;
        // But if this bin would fit the item with small residual, it's a good
        // fresh start; and if next item fits the post-residual, reward it.
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 20.0;
        }
        // If placing in this fresh bin wastes less than the mean residual,
        // it may be better than cramming.
        if waste < mean_residual * 0.5 {
            score -= 15.0;
        }
    }

    // Lookahead coupling: penalize placements that leave a residual the next
    // item cannot use (dead space from the future's perspective).
    if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
        score += (next_item_size as f64 - post_residual as f64) * 0.8;
    }

    // Late in the stream, consolidate harder (fewer bins matters more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Post residual can still host the next item: mild reward proportional to closeness.
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit here afterward; penalize dead space, worse if large gap.
        let gap = (next_item_size - post_residual) as f64;
        score += 15.0 * (gap / bin_capacity as f64);
    }

    // Reward tight fits overall.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness;

    // Compare against mean residual: prefer bins whose post residual diverges
    // favorably (smaller than mean) to keep open-bin residuals heterogeneous.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well,
    // unless the item is large and existing residuals are small.
    if bin_residual == bin_capacity {
        let avg_fit = mean_residual / bin_capacity as f64;
        if avg_fit >= item_size as f64 {
            score += 20.0; // existing bins can comfortably host; avoid new bin
        } else {
            score -= 5.0; // poor fits elsewhere; new bin acceptable
        }
    }

    // Late in the stream, be more conservative: keep residuals compact.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / (total_items.max(1) as f64)).clamp(0.0, 1.0);
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(3) * 30.0;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward leaving space exactly for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate logic: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        let crowding = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 1.0 };
        let openness = 1.0 - progress;
        score = 55.0 - 25.0 * openness - 15.0 * (1.0 - crowding);
        if fitting_bins_count == 0 { score -= 40.0; }
        if next_item_size > item_size && next_item_size > 0 { score -= 5.0; }
    }

    // Mild time pressure: early on, be more willing to spread items.
    score -= progress * 5.0;

    // Slight penalty for bins far below mean residual (keep balance).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += dev * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;
    let progress2 = progress * progress;
    let progress3 = progress2 * progress;

    // Non-linear polynomial coupling of post_residual with progress
    let pr = post_residual as f64;
    let prn = pr / cap;
    score += prn * prn * (20.0 + 60.0 * progress2) - prn * (10.0 + 30.0 * progress3);

    // Reward tight fits, amplified as the stream progresses
    let tightness = 1.0 - prn;
    score -= tightness * tightness * (15.0 + 40.0 * progress);

    // Penalize dead space relative to mean residual (smooth quadratic coupling)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0 + 12.0 * progress;
    } else if next_item_size > 0 {
        score += 3.0 * (1.0 - progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Mild penalty for spreading across many open bins late in the stream
    score += open_bins_count as f64 * (2.0 * progress3);

    // New-bin candidate: make it slightly unattractive unless residual waste would be large
    if bin_residual == bin_capacity {
        score += 10.0 - 15.0 * progress2 * (prn);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "friendly" classes
    // (multiples of small divisors that future items likely fill exactly).
    let post = post_residual as u32;
    let friendly_bonus = if post == 0 {
        60.0 // perfect fit
    } else if post % 10 == 0 {
        30.0
    } else if post % 5 == 0 {
        15.0
    } else if post % 25 == 0 {
        20.0
    } else {
        0.0
    };
    score -= friendly_bonus;

    // Penalize small dead space that is hard to fill (< 10).
    if post > 0 && post < 10 {
        score += (10 - post) as f64 * 2.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 50.0;
        } else if next_item_size <= post {
            let r2 = post - next_item_size;
            score -= 20.0;
            if r2 % 10 == 0 { score -= 10.0; }
        } else {
            // next item cannot use this bin's remainder: slight penalty
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 40.0;
        if post > 20 { score -= 15.0; } // allow fresh bin for large items
        if open_bins_count == 0 { score -= 60.0; }
    }

    // Prefer fuller bins overall (tight packing as stream progresses).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity - bin_residual) as f64 * (0.3 + 0.4 * progress);

    // Slight preference for bins below mean residual (balance load).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins
    // unless the fit is excellent.
    let open_pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    score += 8.0 * open_pressure;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // dead space relative to the known next item
    }

    // New-bin candidate: attractive when the item is large and open bins are crowded,
    // unattractive early in the stream or when open bins have plenty of room.
    if bin_residual == bin_capacity {
        let crowded = if open_bins_count > 0 {
            mean_residual < item_size as f64 * 1.2
        } else {
            false
        };
        if crowded {
            score -= 15.0;
        } else {
            score += 25.0 + 5.0 * open_bins_count as f64;
        }
    }

    // Prefer bins whose residual is close to the item (best-fit flavor).
    score += 0.15 * ((bin_residual as f64 - item_size as f64).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // next item still fits, mild reward proportional to tightness
            score -= 60.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item will NOT fit: penalize wasted post residual that blocks nothing
            score += 25.0 + 0.15 * post_residual as f64;
