    }

    // New-bin candidate handling: make opening a new bin attractive only if all fits are loose
    if bin_residual == bin_capacity {
        // base penalty so new bins are not opened frivolously
        score += 150.0;
        // but if the best alternative would leave large dead space, allow new bin
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 100.0;
        }
        // fewer open bins => opening new bin slightly cheaper
        score -= 5.0 * open_bins_count as f64;
    }

    // Late in stream: consolidate, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 80.0 * progress;
    } else {
        score -= 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize large dead space, especially if it can't hold the next item.
    if post_residual > 0 {
        if (next_item_size > 0 && post_residual < next_item_size) {
            score += 12.0 + 0.15 * post_residual as f64;
        } else {
            score += 0.05 * post_residual as f64;
        }
    }

    // Perfect closure bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward leaving space exactly matching the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin before opening a new one.
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are bad
    // (item is small relative to residuals) or many bins are already congested.
    if bin_residual == bin_capacity {
        let bad_fit = fit_ratio < 0.4;
        let congestion = open_bins_count as f64 > 8.0 + 0.05 * (total_items as f64);
        if bad_fit || congestion {
            score -= 22.0;
        } else {
            score += 45.0;
        }
    }

    // Mild preference for balancing residuals toward the mean as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0 * (post_residual as f64 - mean_residual).abs() / bin_capacity as f64;

    // Slight bonus for reusing already-open bins to limit bin count growth.
    if bin_residual < bin_capacity {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let p2 = progress * progress;
    let coupling = norm_pr * norm_pr * (1.0 - progress) + norm_pr * p2;
    score += 40.0 * coupling;

    // Penalize waste when bin is the last chance
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * (1.0 - progress);
    }

    // Lookahead: reward residuals that can hold the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual as f64 >= n {
            score -= 15.0 * (n / cap) * (1.0 - progress);
        } else {
            score += 8.0 * (n / cap) * progress;
        }
    }

    // Prefer bins tighter than mean residual (best-fit flavor)
    score -= 0.3 * (mean_residual - pr);

    // Discourage opening new bins early when good fits exist
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) + 5.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual), stronger for exact fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic class of post_residual: dead space value depends on size class.
        let pr = post_residual;
        // Small residuals (<=10) are nearly useless; penalize mildly but they're still tight fits.
        if pr <= 10 {
            score -= 60.0; // tight fit is good
        } else if pr <= 20 {
            score -= 30.0;
        } else if pr <= 50 {
            // mid dead space: penalize extra
            score += 5.0 + (pr as f64) * 0.1;
        } else {
            score += 15.0; // large dead space
        }
    }

    // Lookahead: if next item fits into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 + 20.0 * (1.0 - slack / cap);
        // exact pairing bonus
        if post_residual == next_item_size {
            score -= 50.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot use the leftover: penalize proportional to wasted fraction
        score += 10.0 * (post_residual as f64) / cap;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin should generally lose unless
    // all fits are poor. Penalize the empty-bin call.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = cap * 0.9 + open_bins_count as f64;
        // but if item is large relative to capacity and mean residual is poor,
        // new bin becomes attractive
        let frac = item_size as f64 / cap;
        if frac > 0.6 && mean_residual < frac * cap * 0.5 {
            score -= 60.0;
        }
        // early in stream, slightly cheaper to open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    }

    // Mild preference for filling fuller bins (residual close to item).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fill_ratio;

    // Spread open bins: if many bins open, discourage leaving many half-empty.
    if open_bins_count > 0 {
        score += 0.05 * (open_bins_count as f64);
    }

    // Modulo-class coupling on post_residual (harmonic classes):
    // residuals divisible by 10 pair well with typical item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    // residual congruent to 1..3 mod 10 is nearly dead space
    if post_residual % 10 >= 1 && post_residual % 10 <= 3 && post_residual > 0 && post_residual < 15 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly useless.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny unusable sliver
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 30 {
            score += 8.0;
        } else {
            score -= 5.0; // large residual still reusable
        }
    } else {
        // Perfect fit is the best possible outcome.
        score -= 200.0;
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 30.0 * tightness;

    // Open-bin pressure: penalize accumulating many open bins mildly,
    // but reward spreading load when few bins are open.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 120.0; // chains a perfect fit
            } else if gap < 10 {
                score -= 20.0;
            } else {
                score -= 8.0;
            }
        } else {
            // Post residual too small for next item: penalize proportionally.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (fill fuller bins first).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: only attractive when nothing fits well
    // or open bins are very fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { mean_residual / open_bins_count as f64 } else { 0.0 };
        if fitting_bins_count == 0 || fragmentation < 15.0 {
            score -= 50.0; // open a fresh bin
        } else {
            score += 40.0; // prefer existing bins when they're reasonably empty
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead coupling: if the next item fits in the post-residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else {
            score += 0.15 * (next_item_size - post_residual.min(next_item_size)) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Crowding pressure: with many open bins, prefer filling existing ones.
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.4 * crowding * fit_ratio;

    // Time horizon: early on, be more willing to open new bins; late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 20.0 * (1.0 - progress) * fit_ratio;

    // Mean residual deviation: bins far below mean residual are less attractive.
    let dev = mean_residual - bin_residual as f64;
    score += 0.2 * dev;

    // New-bin candidate: only attractive when item is large and no good fit exists.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 35.0 - 30.0 * large_item - 40.0 * pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual fraction of capacity
    let post_frac = post / capacity;

    // Non-linear polynomial coupling: small residuals are valuable (tight fits),
    // large residuals waste space. Use a smooth convex penalty on post_residual.
    let mut score = post * (1.0 + 0.8 * post_frac * post_frac);

    // Reward tight fits more aggressively as the stream progresses
    let tightness = 1.0 - post_frac;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize bins whose residual deviates from the mean residual
    // (encourages homogeneity of open space for future packing)
    score += 0.15 * (post - mean_residual).abs();

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward this placement.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let gap = (post - next).abs();
        score -= 10.0 / (1.0 + gap);
        // If next item won't fit here at all, mildly favor bins leaving
        // residuals aligned with typical sizes (smooth decay with residual size)
        if post < next {
            score += 0.05 * post;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a neutral-to-slightly-high score,
    // but late in the stream (or when many bins are open) opening fresh bins is
    // penalized to force consolidation.
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * progress + 0.5 * open_bins_count as f64;
    } else {
        // Mild preference for reusing already-open bins
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits (small post_residual relative to capacity), non-linearly.
    let tightness = 1.0 - post / cap;
    score -= 10.0 * tightness.powi(4);

    // Harmonic class: dead-space detection on post_residual.
    // If the leftover can never fit the next item (or anything), it is waste.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0; // bin remains usable for the lookahead item
        } else if post_residual > 0 {
            score += 7.0; // leftover too small for lookahead -> dead space risk
        }
    } else {
        // last item in stream: any leftover is pure waste
        score += post * 0.5;
    }

    // Integer-division threshold: classify leftover into capacity/10 harmonic buckets.
    let bucket = post_residual / (bin_capacity / 10).max(1);
    score += bucket as f64 * 0.8;

    // Fine-grained modulo penalty: odd fragments are harder to pack.
    score += (post_residual % 10) as f64 * 0.15;

    // Last-chance bonus: this is the only bin that fits; avoid opening a new one
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
        // extra reward if the fit is also tight
        if post_residual <= 5 {
            score -= 4.0;
        }
    }

    // New-bin candidate handling: mildly penalize so a new bin is opened
    // only when every open bin offers a bad fit.
    if bin_residual == bin_capacity {
        score += 9.0;
        // A large item into a fresh bin is actually a good deal.
        if item_size >= bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // Progress coupling: late in the stream, prefer bins whose residual
    // matches the mean residual (consolidation of slack).
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += t * (mean_residual - post).abs() * 0.05;

    // Crowd factor: many open bins -> prefer placements that shrink residuals
    // toward zero to allow closing bins.
    if open_bins_count > 4 {
        score += post * 0.1 * ((open_bins_count as f64).ln());
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, the minimum item)
    // are worthless; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Gaps in [10,20) are only usable by very small items; moderate penalty.
        score += 15.0;
    }

    // Reward perfect / near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Tight fit bonus: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Dead-space ratio penalty: unusable fraction of the bin after placement.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * dead * dead;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins becomes more expensive.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * (1.0 - fill);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): make it attractive only when the item
    // would leave a large awkward gap everywhere else, or when few bins are open.
    if bin_residual == bin_capacity {
        let gap_penalty = if post_residual < 10 { 200.0 } else { 0.0 };
        score = 45.0 + pressure * 0.8 - 30.0 * fill + gap_penalty;
        // Lookahead: if next item is small enough to use this bin's residual,
        // opening a fresh bin is safer.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0;
        }
        // Early in the stream, new bins are cheap.
        score -= 20.0 * (1.0 - progress);
    }

    // Lookahead synergy: if the residual left here exactly accommodates the
    // next item, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        score += 10.0; // would create dead space after next item
    }

    // Slight preference for bins below mean residual (balance load).
    score += 0.1 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with the next item is gold.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0; // exact fill after next item
        } else if next_item_size <= post_residual {
            // next item fits here afterwards: reward small leftover slack
            score -= 300.0 - (post_residual - next_item_size) as f64 * 2.0;
        } else {
            // next item cannot follow in this bin: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // last item: just minimize waste
        score -= 50.0;
    }

    // Reward tight fits relative to capacity (low post_residual already does this,
    // but add a non-linear bonus for near-perfect packing).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Compare against mean residual across open bins: prefer bins whose remaining
    // space after placement deviates favorably (smaller) from the mean.
    score += (mean_residual - post_residual as f64) * -0.3;

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Discourage opening new bins when good open bins exist; make the empty-bin
    // candidate less attractive unless the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 120.0;
        score += 150.0 - large_item_bonus;
        // early in the stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 80.0 * (1.0 - progress);
    }

    // Mild penalty for leaving many open bins with fragmented space.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0 * (6 - post_residual) as f64;
    }

    // Penalize large dead space quadratically, scaled by bin capacity.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * dead * dead;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead coupling: reward bins whose leftover pairs well with the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let pair_waste = post_residual - next_item_size;
        if pair_waste == 0 {
            score -= 120.0;
        } else {
            score -= 20.0 * (1.0 - pair_waste as f64 / bin_capacity as f64);
        }
    } else if next_item_size > post_residual && post_residual < 10 && bin_residual != bin_capacity {
        // Dead space too small for the next item: penalize.
        score += 25.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_options = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        let avg_fit_gap = (mean_residual - item_size as f64).abs();
        score = 60.0 + 40.0 * progress + 30.0 * poor_options - avg_fit_gap.min(50.0);
        // Early stream: opening bins cheaply is fine.
        if progress < 0.2 {
            score -= 20.0;
        }
    }

    // Mild pressure to consolidate: prefer bins with below-average residual (fuller bins).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Slight preference for bins that would become tight.
    score += 0.02 * post_residual as f64 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual, with non-linear compression
    let mut score = pr.powf(1.5) / cap.sqrt();

    // Tight-fit reward: strongly subtract when post_residual is small relative to capacity
    let tightness = 1.0 - (pr / cap);
    score -= 12.0 * tightness * tightness * tightness;

    // Next-item lookahead: penalize residuals that cannot fit the next item (dead space),
    // reward residuals that can snugly host it.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = pr - ni;
            score -= 6.0 * (1.0 - slack / cap); // snug fit for next item
        } else {
            let gap = ni - pr;
            score += 4.0 * (gap / cap) * (gap / cap); // unusable for lookahead
        }
    }

    // Stream-progress coupling: late in stream, be greedier (favor tight fits, avoid spreading)
    score += 5.0 * progress * (pr / cap);

    // Non-linear coupling of post_residual with progress: mid-stream, tolerate mid residuals
    let phase = (progress * std::f64::consts::PI).sin();
    score -= 3.0 * phase * (1.0 - (pr / cap - 0.5).abs() * 2.0);

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: mildly discourage unless current fit is poor or few bins open
    if bin_residual == bin_capacity {
        let poor_fit = (item_size as f64 / cap) < 0.35;
        if poor_fit && progress > 0.5 {
            score -= 8.0; // opening fresh bin for small item late is fine
        } else {
            score += 10.0 + 5.0 * (open_bins_count as f64).ln().max(0.0);
        }
    }

    // Mean-residual coupling: if this bin's post-residual diverges from mean, penalize
    score += 0.08 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize residuals in "dead zones" that few item sizes can fill.
        // Class A: residual <= 10 -> nearly dead space.
        if post_residual < 10 {
            score += 60.0;
        }
        // Class B: residual in (10, 20) -> fillable only by small items.
        else if post_residual < 20 {
            score += 25.0;
        }
        // Class C: residual in [50, 90] -> moderately fillable.
        else if post_residual >= 50 && post_residual < 90 {
            score -= 8.0;
        }
        // Harmonic bonus: residual divisible by common item sizes (5,10,20,25).
        if post_residual % 10 == 0 {
            score -= 6.0;
        }
        if post_residual % 25 == 0 {
            score -= 4.0;
        }
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            // Next item still fits: mild bonus proportional to leftover after next.
            let after_next = post_residual - next_item_size;
            score -= 10.0 + (after_next as f64) * 0.2;
        } else {
            // Next item would not fit here: penalize leaving residual just below next size.
            if post_residual >= next_item_size.saturating_sub(10) {
                score += 20.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    // and we have many open bins already (consolidation pressure).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_fit = post_residual > 40.0f64.max(item_size as f64 * 0.5);
        if bad_fit && open_bins_count > 2 {
            score -= 30.0 + 20.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
    }

    // Prefer bins tighter than the mean residual (better packing direction).
    score += 0.3 * ((post_residual as f64) - mean_residual);

    // Mild preference for bins with less residual overall as stream matures.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 35 {
        score += 6.0;
    } else {
        // Larger residuals are more reusable; reward moderately.
        score -= 4.0;
    }

    // Perfect fit: zero residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits relative to bin residual (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening bins when open-bin pressure is low,
    // reward it when many bins are open (consolidation relief).
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
        score += 15.0 - 10.0 * pressure.min(3.0);
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 12.0;
    }
    // If next item cannot fit in post-residual but would fit a full bin,
    // slightly penalize leaving an awkward gap.
    if next_item_size > post_residual as u32 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Mild open-bin pressure: prefer filling existing bins over spreading.
    score += 0.3 * open_bins_count as f64;

    // Slight preference for using bins with below-average residual
    // (balances residual distribution across open bins).
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits perfectly after this placement.
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            score -= 60.0; // perfect 2-step chain
        } else if diff > 0 {
            score -= 25.0 * (1.0 - diff as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize wasted potential
            score += 10.0 + (-diff) as f64 * 0.15;
        }
    }

    // Penalize large dead space relative to mean residual of open bins.
    let dead = post_residual as f64;
    if dead > mean_residual {
        score += 0.35 * (dead - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - dead);
    }

    // Tight fit reward: small post_residual is good.
    score -= 40.0 * (1.0 - dead / bin_capacity as f64).powi(3);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 45.0;
        // If the item is large, opening a new bin is more acceptable.
        score -= (item_size as f64 / 100.0) * 20.0;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 10.0; // new bin can still serve the next item
        }
    }

    // Late-stream consolidation: prefer compacting into few bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * open_bins_count as f64 / (open_bins_count.max(1) as f64 + 5.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize large dead space after placement (nonlinear).
    if post_residual > 0 {
        score += 0.05 * (post_residual as f64).powf(1.4);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host next item well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * next_fit;
        } else {
            // post_residual too small to be useful for next item -> dead space penalty
            score += 0.10 * post_residual as f64;
        }
        // If next item fits exactly in post_residual, strong bonus.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let bad_fit = fit_ratio < 0.5;
        score += if bad_fit { 5.0 - 10.0 * progress } else { 60.0 };
        // Early stream: opening bins is cheaper; late stream: reuse is critical.
        score += 20.0 * (1.0 - progress);
    }

    // Prefer using bins with below-mean residual (consolidate emptier bins' space).
    if bin_residual != bin_capacity {
        score -= 0.15 * (mean_residual - bin_residual as f64);
    }

    // Many open bins: encourage consolidation into fewer bins.
    score += 1.5 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Mild time pressure: later in stream, penalize wasted residual more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: leftover space, normalized, with non-linear growth penalizing large dead space.
    let mut score = post / cap;

    // Smooth polynomial coupling of dead space with stream progress:
    // late in the stream, wasted space is increasingly costly.
    score += 0.35 * (post / cap).powi(2) * (0.5 + progress);

    // Reward tight fits (small post_residual) with a smooth quadratic bonus.
    score -= 0.5 * (1.0 - post / cap).powi(3);

    // Reward bins whose residual closely matches the item (perfect-ish fit).
    let fit_tightness = 1.0 - (bin_residual as f64 - item_size as f64) / cap;
    score -= 0.25 * fit_tightness * fit_tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 0.8 + 0.4 * progress;
    }

    // Many fitting bins: mild penalty to prefer the best-fit among them via residual ordering.
    if fitting_bins_count > 2 {
        score += 0.05 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: if the next item could reuse this bin's post-residual, reward leaving exactly that space.
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs() / cap;
        score -= 0.3 * (1.0 - gap).powi(2);
    } else {
        // Last item: minimize leftover aggressively.
        score += 0.2 * (post / cap);
    }

    // Align with global mean residual: bins near mean residual keep balance smooth.
    score += 0.1 * ((post - mean_residual) / cap).abs();

    // New-bin candidate: make it attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        score = 1.2 + post / cap - 0.3 * progress;
        if fitting_bins_count == 1 {
            score += 1.5; // discourage opening new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item (capacity fractions / integer division thresholds)
    let item_class = item_size / (bin_capacity / 4).max(1); // 0..=3 harmonic tier
    let next_class = next_item_size / (bin_capacity / 4).max(1);

    // Reward tight fits strongly
    let tight = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tight) * 30.0;

    // Penalize dead space: residuals that few future items can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }
    if post_residual >= 10 && post_residual < 30 {
        score += 8.0; // awkward gap
    }

    // Lookahead: does the next item fit in post_residual? Reward coupling.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0 + 6.0 * (next_class as f64);
        // harmonic pairing bonus when classes complement (mod arithmetic)
        if (item_size + next_item_size) % bin_capacity == 0 {
            score -= 40.0; // perfect pair fills bin exactly
        } else if (item_size + next_item_size) % 10 == 0 {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here; penalize leaving stranded residual
        score += 10.0 + 5.0 * (item_class as f64);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Many open bins: prefer consolidating into existing bins
    if open_bins_count > 4 {
        score -= 4.0 * (open_bins_count.min(20) as f64) * (1.0 - tight);
    }

    // Mean residual coupling: placing in a bin far below mean residual is wasteful
    score += 0.15 * (mean_residual - bin_residual as f64).abs();

    // New-bin candidate handling: only attractive when no good existing fit
    if bin_residual == bin_capacity {
        let base = 55.0 + 10.0 * (item_class as f64);
        // early in stream: opening bins is cheap; later: prefer filling
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = base + 40.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 12.0; // fresh bin can host the pair
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a bin
        }
    }

    // Modulo-class affinity: prefer bins whose residual shares residue class with item
    if bin_residual < bin_capacity && bin_residual % 10 == item_size % 10 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less leftover space is better.
    score -= (item_size as f64 / bin_capacity as f64) * 8.0;

    // Penalize unusable dead space: gaps too small for the minimum item size.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Small-but-usable gaps: mild penalty, only large items can use them.
        score += 6.0;
    }

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the item
    // fits poorly in every open bin (large dead space would be created).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many bins are already open
        // and mean residual is high (fragmented state).
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = (bin_capacity as f64) * 0.35 + fragmentation * 10.0
            + (open_bins_count as f64) * 0.15;
        // If the next item is small, a fresh bin retains flexibility.
        if next_item_size > 0 && next_item_size <= 25 {
            score -= 8.0;
        }
        // Late in the stream, avoid opening bins that will be mostly wasted.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 6.0;
    } else {
        // Prefer bins whose residual is close to the item (best-fit style),
        // with a mild pressure term from the number of open bins.
        score += (bin_residual as f64 - item_size as f64) * 0.05
            + (open_bins_count as f64).ln().max(0.0) * 0.3;
        // Bonus if this bin's post-residual can still fit the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly preferred: reward small post_residual.
    score -= 60.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Aggressive 2-step lookahead: if the next item fits the post_residual
    // exactly or very well, heavily reward this placement.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        if gap == 0.0 {
            score -= 45.0; // perfect pair: item + next item fill the bin
        } else if gap > 0.0 {
            // next item fits too; reward proportionally to how snug the pair is
            score -= 40.0 * (1.0 - gap / bin_capacity as f64).powi(2);
        } else {
            // next item does not fit; penalize wasted space that blocks it
            score += (-gap).min(bin_capacity as f64) * 0.35;
        }
    }

    // Compare against mean residual: bins with residual far below mean are
    // "waste candidates"; placing here concentrates small leftovers.
    let dev = post_residual as f64 - mean_residual;
    score += 0.12 * dev;

    // Last-chance bin: strongly reward using the only bin that fits,
    // avoiding opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize creating very small unusable slivers (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Mild pressure to close bins early when many bins are open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let best_possible = if next_item_size > 0 {
            (bin_capacity.saturating_sub(item_size + next_item_size)) as f64
        } else {
            (bin_capacity - item_size) as f64
        };
        // If an existing bin would leave a small residual, prefer it;
        // if all open bins would be badly fragmented, allow the new bin.
        let existing_bad = fitting_bins_count == 0 || mean_residual < item_size as f64 * 0.6;
        if existing_bad {
            score -= 20.0;
        } else {
            score += 15.0 + 0.5 * (mean_residual - best_possible).abs();
        }
    }

    // Slight progression term: later in stream, tighten packing further.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward low post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that the lookahead item cannot use.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let wasted = (next_item_size - post_residual) as f64;
        score += 0.9 * wasted;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that remain useful for the next item.
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Slight penalty when many bins are open (encourage consolidation).
    score += 0.35 * open_bins_count as f64;

    // Nudge toward bins whose residual is near the mean residual (keeps spread balanced).
    score += 0.12 * (bin_residual as f64 - mean_residual).abs();

    // Time horizon: as stream progresses, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // New-bin candidate: make it unattractive unless existing fits are terrible.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let quad = norm_pr * norm_pr * (1.0 + 40.0 * progress);
    let cubic = norm_pr * norm_pr * norm_pr * (30.0 * (1.0 - progress));
    score += quad - cubic;

    // Reward tight fits more strongly later in the stream
    let fit_bonus = (item_size as f64 / cap) * (1.0 + 25.0 * progress) * (norm_pr + 0.5);
    score -= fit_bonus;

    // Penalize dead space relative to mean residual (smooth coupling)
    score += 0.15 * (pr - mean_residual).abs() * (0.5 + progress);

    // Last-chance bin: smooth reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    }

    // Lookahead: reward residual that can host the next item (smooth bell)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let d = pr - nx;
        let bell = (-d * d / 900.0).exp();
        score -= 8.0 * bell * (1.0 + progress);
    }

    // Mild penalty for proliferation of open bins, smoothed by progress
    score += (open_bins_count as f64).ln() * (2.0 + 6.0 * progress);

    // New-bin candidate: prefer keeping it closed early, allow opening late
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity fraction buckets.
    // Residuals that are "harmonically useful" (small, or complements of common sizes) are good.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: which integer division bucket it falls into
    // Small residuals (< 10) are dead space -> penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Residuals that are complements of typical item sizes (10..80) are reusable:
    // reward if post_residual itself is in [10, 80] range (likely a future item fits exactly-ish)
    if post_residual >= 10 && post_residual <= 80 {
        score -= 12.0;
    }

    // Modulo-10 harmonic class: residuals divisible by 10 pair well with grid-like streams
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
            // extra reward for near-exact lookahead fit
            let gap = post_residual - next_item_size;
            if gap < 5 {
                score -= 15.0;
            }
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // New empty bin: post_residual = capacity - item_size. Neutral baseline,
        // but penalize slightly so a decent existing fit wins; relax late in stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Prefer bins tighter than the mean residual (better fit quality)
    score += 0.3 * (pr - mean_residual).max(-50.0).min(50.0);

    // Many open bins: encourage consolidation into existing bins
    score += 0.5 * open_bins_count as f64;

    // Late stream: be greedy, minimize residual aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny dead space is nearly worthless
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 40 {
            score -= 10.0; // medium gaps may still fit future items
        } else {
            score -= 20.0; // large residual keeps flexibility
        }
    } else {
        // Perfect fit: strongly reward closing the bin.
        score -= 100.0;
    }

    // Dead space relative to capacity: quadratic penalty on tight fills.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 15.0 * frac * frac;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; prefer
    // filling existing bins rather than opening new ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open.
        score += 30.0 + 12.0 * pressure;
    } else {
        score -= 5.0 * pressure;
    }

    // Lookahead: if the next item fits in this bin's post-residual,
    // reward the placement (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // If next item would leave this bin's residual dead anyway, slight penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 20.0;
    }

    // Late in the stream, tighten up: favor tight fits even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - frac);

    // Mild preference for bins below mean residual (balance spreading).
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.05 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: residual close to zero is good.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space exponentially; small residuals are valuable.
        score += (post_residual as f64).powi(2) * 0.01;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // perfect chaining: next item exactly fills this bin
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 - slack * 0.5; // next item still fits: bonus decays with slack
        } else {
            // next item won't fit here; penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    } else {
        // Last item: prefer zero residual even more strongly.
        score -= 100.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are scarcer; favor filling them.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.6;
    } else {
        score += (res - mean_residual) * 0.3;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a new bin should only win when it beats
    // a poor fit. Give the empty bin a mild handicap so real fits usually win,
    // but allow it when all open fits would waste a lot of space.
    if bin_residual == bin_capacity {
        score += 60.0;
        // If existing fits are terrible (large post_residual relative to next item),
        // the base score may already be high enough for the new bin to win.
        if next_item_size > 0 && post_residual as f64 > next_item_size as f64 * 1.5 {
            score -= 40.0;
        }
    }

    // Slight stream-progression pressure: late in the stream, consolidate more eagerly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (res / bin_capacity as f64);

    score
}
